#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for a log entry
typedef struct {
    uint64_t timestamp;
    int log_level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log
#define MAX_LOG_SIZE 1024

// Define a dynamic array to store the log entries
ModemLogEntry* log = NULL;
size_t log_size = 0;
size_t log_capacity = 0;

// Function to add a new entry to the log
void add_log_entry(uint64_t timestamp, int log_level, char* message) {
    // Check if the log is full and needs to be resized
    if (log_size == log_capacity) {
        // Double the size of the log
        log_capacity *= 2;
        ModemLogEntry* new_log = realloc(log, sizeof(ModemLogEntry) * log_capacity);
        if (!new_log) {
            printf("Error: Failed to allocate memory for log\n");
            return;
        }
        log = new_log;
    }

    // Add the new entry to the log
    ModemLogEntry* entry = &log[log_size++];
    entry->timestamp = timestamp;
    entry->log_level = log_level;
    entry->message = message;
}

// Function to retrieve an entry from the log by timestamp
ModemLogEntry* get_log_entry(uint64_t timestamp) {
    // Check if the log is empty
    if (log_size == 0) {
        return NULL;
    }

    // Search for the entry with the specified timestamp
    ModemLogEntry* entry = NULL;
    for (size_t i = 0; i < log_size; i++) {
        if (log[i].timestamp == timestamp) {
            entry = &log[i];
            break;
        }
    }

    // Return the found entry or NULL if not found
    return entry;
}

// Function to clear the entire log
void clear_log() {
    // Free the memory allocated for the log
    free(log);
    log = NULL;
    log_size = 0;
    log_capacity = 0;
}

// Function to limit the number of entries in the log to a specified maximum size
void limit_log_size(size_t max_size) {
    // Check if the log is already at the specified size
    if (log_size <= max_size) {
        return;
    }

    // Remove excess entries from the log
    while (log_size > max_size) {
        free(log[0].message);
        memmove(&log[0], &log[1], sizeof(ModemLogEntry) * (log_size - 1));
        log_size--;
    }
}
```
