    int value;
} record_t;

// Function to initialize the arrays and populate them with random values
void init_arrays(long* offset_arr, int* key_arr, record_t** record_arr, size_t num_records) {
    // Allocate memory for the offset array
    offset_arr = (long*)malloc(num_records * sizeof(long));
    if (!offset_arr) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % 1000 + 1;
    }

    // Allocate memory for the key array
    key_arr = (int*)malloc(num_records * sizeof(int));
    if (!key_arr) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offset_arr);
        return;
    }

    // Initialize the key array with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        key_arr[i] = rand() % 100 + 1;
    }

    // Allocate memory for the record array
    record_arr = (record_t**)malloc(num_records * sizeof(record_t*));
    if (!record_arr) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offset_arr);
        free(key_arr);
        return;
    }

    // Initialize the record array with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        record_arr[i] = malloc(sizeof(record_t));
        if (!record_arr[i]) {
            printf("Error: Failed to allocate memory for record %zu\n", i);
            free(offset_arr);
            free(key_arr);
            free(record_arr);
            return;
        }
        record_arr[i]->value = rand() % 100 + 1;
    }
}

// Function to handle memory deallocation and prevent leaks
void cleanup_arrays(long* offset_arr, int* key_arr, record_t** record_arr) {
    // Free the memory for the offset array
    free(offset_arr);

    // Free the memory for the key array
    free(key_arr);

    // Free the memory for each record in the record array
    for (size_t i = 0; i < num_records; i++) {
        free(record_arr[i]);
    }

    // Free the memory for the record array
    free(record_arr);
}
