#include <openssl/evp.h>
#include <json-c/json.h>

bool validate_access_token(const char* json) {
    struct json_object *obj = json_tokener_parse(json);
    if (!obj) return false;

    const char* access_token = json_object_get_string(json_object_object_get(obj, "access_token"));
    if (!access_token) {
        json_object_put(obj);
        return false;
    }

    int expires_in = json_object_get_int(json_object_object_get(obj, "expires_in"));
    if (expires_in <= 0) {
        json_object_put(obj);
        return false;
    }

    const char* token_type = json_object_get_string(json_object_object_get(obj, "token_type"));
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        json_object_put(obj);
        return false;
    }

    const char* refresh_token = json_object_get_string(json_object_object_get(obj, "refresh_token"));
    if (refresh_token && strcmp(refresh_token, "") != 0) {
        json_object_put(obj);
        return false;
    }

    json_object_put(obj);
    return true;
}

EVP_CIPHER* choose_cipher(const char* cipher_name) {
    if (strcmp(cipher_name, "DES") == 0) {
        return EVP_des_cbc();
    } else if (strcmp(cipher_name, "EDE") == 0) {
        return EVP_des_ede3_cbc();
    } else if (strcmp(cipher_name, "CFB") == 0) {
        return EVP_des_cfb();
    } else if (strcmp(cipher_name, "EDE3") == 0) {
        return EVP_des_ede3_cbc();
    } else {
        return NULL;
    }
}

bool validate_and_choose_cipher(const char* cipher_name, const char* json) {
    if (!validate_access_token(json)) return false;

    EVP_CIPHER* chosen_cipher = choose_cipher(cipher_name);
    if (chosen_cipher == NULL) return false;

    return true;
}
