import java.util.HashMap;
import java.util.Map;

public class PokemonReport {
    private static final Map<String, String> WEAKNESS_MAP = new HashMap<>();
    private static final Map<String, String> RESISTANCE_MAP = new HashMap<>();

    static {
        // Initialize the weakness and resistance maps with data from the library functions
        WEAKNESS_MAP.put("Grass", "Fire");
        WEAKNESS_MAP.put("Fire", "Water");
        WEAKNESS_MAP.put("Water", "Ground");
        RESISTANCE_MAP.put("Grass", "Psychic");
        RESISTANCE_MAP.put("Fire", "Fighting");
        RESISTANCE_MAP.put("Water", "Dragon");
    }

    public static String getReport(Pokemon pokemon) {
        // Use a switch statement to determine the weaknesses and resistances based on the Pokemon's type
        String type = pokemon.getType();
        switch (type) {
            case "Grass":
                return "Weak against Fire, Resistant to Psychic";
            case "Fire":
                return "Weak against Water, Resistant to Fighting";
            case "Water":
                return "Weak against Ground, Resistant to Dragon";
            default:
                // Handle cases where the Pokemon type is not recognized by the library
                return "Error: Unknown Pokemon type";
        }
    }

    public static String getReport(Pokemon pokemon, boolean includeWeather) {
        // Use an external weather API to adjust the Pokemon's weaknesses based on current weather conditions in the player's location
        if (includeWeather) {
            Weather weather = getCurrentWeather();
            switch (weather) {
                case RAINY:
                    return "Weak against Fire, Resistant to Psychic";
                case SUNNY:
                    return "Weak against Water, Resistant to Fighting";
                case CLOUDY:
                    return "Weak against Ground, Resistant to Dragon";
                default:
                    // Handle cases where the weather is not recognized by the library
                    return "Error: Unknown weather condition";
            }
        } else {
            return getReport(pokemon);
        }
    }

    public static String getReport(Pokemon pokemon, Language language) {
        // Use a library function to retrieve the Pokemon's name in the specified language
        String name = pokemon.getName(language);
        return "The " + name + " is weak against " + WEAKNESS_MAP.get(pokemon.getType()) + ", Resistant to " + RESISTANCE_MAP.get(pokemon.getType()) + ".";
    }
}
