bool is_algorithm_available(char* name) {
    // Check if the algorithm is available in hardware
    if (is_hardware_accelerated(name)) {
        return true;
    }

    // Check if the algorithm has a software fallback implementation
    if (has_software_fallback(name)) {
        return true;
    }

    return false;
}

// Function to retrieve the optimal algorithm based on a set of criteria
algo_t* get_optimal_algorithm(int memory_limit, int processing_speed) {
    // Iterate over the supported algorithms and find the one with the best balance between speed and security
    for (int i = 0; i < num_algos; i++) {
        if (algos[i].context_params[0] <= memory_limit && algos[i].context_params[1] >= processing_speed) {
            return &algos[i];
        }
    }

    // If no algorithm meets the criteria, return NULL
    return NULL;
}

// Function to handle unsupported algorithms or configuration errors without crashing the application
void handle_error(char* error_message) {
    printf("Error: %s\n", error_message);
}

