#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the logging levels
#define LOG_DEBUG 0
#define LOG_INFO  1
#define LOG_WARNING 2
#define LOG_ERROR 3

// Define the rate limiting mechanism
#define RATE_LIMIT 50

// Define the log buffer size
#define LOG_BUFFER_SIZE 4096

// Define the log file name
#define LOG_FILE "log.txt"

// Define the logging function
void log(int level, const char *format, ...) {
    // Check if the rate limit has been reached
    if (level >= RATE_LIMIT) {
        return;
    }

    // Get the current time and thread ID
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long tid = syscall(SYS_gettid);

    // Format the log message
    char buffer[LOG_BUFFER_SIZE];
    va_list args;
    va_start(args, format);
    vsnprintf(buffer, LOG_BUFFER_SIZE, format, args);
    va_end(args);

    // Log the message to both the file and console
    fprintf(stderr, "[%ld:%ld] %s\n", tid, ts.tv_sec, buffer);
    FILE *logFile = fopen(LOG_FILE, "a");
    if (logFile) {
        fprintf(logFile, "[%ld:%ld] %s\n", tid, ts.tv_sec, buffer);
        fclose(logFile);
    }
}

// Define the function to process a string with logging
void *processStringWithLogging(const char *string, int command) {
    // Check if the input string is null or empty
    if (!string || !*string) {
        log(LOG_ERROR, "Invalid input string");
        return NULL;
    }

    // Initialize the cipher object
    EVP_CIPHER_CTX *cipher = EVP_CIPHER_CTX_new();
    if (!cipher) {
        log(LOG_ERROR, "Failed to initialize cipher object");
        return NULL;
    }

    // Set the logging level and rate limiting mechanism
    int logLevel = LOG_INFO;
    int rateLimit = RATE_LIMIT;

    // Perform the specified operation based on the command-line option
    switch (command) {
        case 0:
            // Encrypt the string using AES-256-CBC
            if (!EVP_EncryptInit_ex(cipher, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
                log(LOG_ERROR, "Failed to initialize encryption");
                return NULL;
            }
            break;
        case 1:
            // Decrypt the string using AES-256-CBC
            if (!EVP_DecryptInit_ex(cipher, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
                log(LOG_ERROR, "Failed to initialize decryption");
                return NULL;
            }
            break;
        default:
            // Unknown command-line option
            log(LOG_WARNING, "Unknown command-line option %d", command);
            return NULL;
    }

    // Set the logging level and rate limiting mechanism
    EVP_CIPHER_CTX_set_key_length(cipher, 32);
    EVP_CIPHER_CTX_set_padding(cipher, 0);

    // Process the input string
    int len = strlen(string);
    unsigned char *input = (unsigned char *)string;
    unsigned char *output = (unsigned char *)malloc(len + EVP_CIPHER_CTX_block_size(cipher));
    if (!output) {
        log(LOG_ERROR, "Failed to allocate memory for output");
        return NULL;
    }
    int outLen = len + EVP_CIPHER_CTX_block_size(cipher);
    if (!EVP_EncryptUpdate(cipher, output, &outLen, input, len)) {
        log(LOG_ERROR, "Failed to encrypt the string");
        return NULL;
    }

    // Free the cipher object and return the output
    EVP_CIPHER_CTX_free(cipher);
    return output;
}
