#include <stdlib.h>
#include <pthread.h>

struct ResourcePool {
  int capacity;
  int size;
  void** resources;
  pthread_mutex_t mutex;
};

void initResourcePool(struct ResourcePool* pool, int initialCapacity) {
  pool->capacity = initialCapacity;
  pool->size = 0;
  pool->resources = malloc(initialCapacity * sizeof(void*));
  pthread_mutex_init(&pool->mutex, NULL);
}

void resizeResourcePool(struct ResourcePool* pool, int newCapacity) {
  void** newResources = realloc(pool->resources, newCapacity * sizeof(void*));
  if (newResources == NULL) {
    // handle error
  }
  pool->capacity = newCapacity;
  pool->resources = newResources;
}

void addResourceToPool(struct ResourcePool* pool, void* resource) {
  pthread_mutex_lock(&pool->mutex);
  if (pool->size == pool->capacity) {
    resizeResourcePool(pool, pool->capacity * 2);
  }
  pool->resources[pool->size++] = resource;
  pthread_mutex_unlock(&pool->mutex);
}

void* getResourceFromPool(struct ResourcePool* pool) {
  void* resource = NULL;
  pthread_mutex_lock(&pool->mutex);
  if (pool->size > 0) {
    resource = pool->resources[--pool->size];
  } else {
    // handle error
  }
  pthread_mutex_unlock(&pool->mutex);
  return resource;
}

void destroyResourcePool(struct ResourcePool* pool) {
  free(pool->resources);
  pthread_mutex_destroy(&pool->mutex);
}
