const updateProfile = async (userId, updatedProfile) => {
  // Validate input data
  if (!updatedProfile.email || !updatedProfile.profilePictureUrl) {
    throw new Error("Invalid profile data");
  }

  // Update the profile in the database
  const result = await db.collection("profiles").updateOne(
    { _id: userId },
    { $set: updatedProfile }
  );

  if (result.modifiedCount === 0) {
    throw new Error(`Failed to update profile for user ${userId}`);
  }

  return result;
};

const retrieveProfiles = async (page, limit) => {
  // Fetch the profiles from the database
  const profiles = await db.collection("profiles").find({}).toArray();

  // Handle pagination
  if (page && limit) {
    return profiles.slice((page - 1) * limit, page * limit);
  }

  return profiles;
};

const archiveProfile = async (userId) => {
  // Mark the profile as inactive and update its status attribute
  const result = await db.collection("profiles").updateOne(
    { _id: userId },
    { $set: { status: "archived" } }
  );

  if (result.modifiedCount === 0) {
    throw new Error(`Failed to archive profile for user ${userId}`);
  }

  return result;
};
