import java.security.MessageDigest;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

public static String getHash(String input, boolean hex) {
    // Validate the input string
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be empty");
    }
    for (char c : input.toCharArray()) {
        if (!Character.isLetterOrDigit(c) && !Character.isWhitespace(c)) {
            throw new IllegalArgumentException("Invalid character in input string");
        }
    }

    // Generate the hash using a standard library function
    MessageDigest md;
    try {
        md = MessageDigest.getInstance("MD5");
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
    byte[] bytes = md.digest(input.getBytes());

    // Return the hash in the requested format
    if (hex) {
        return Base64.getEncoder().encodeToString(bytes);
    } else {
        return new String(bytes, StandardCharsets.UTF_8);
    }
}
