<?php

function handleUserRequest($_REQUEST) {
    // Validate input data
    $validation = validateInputData($_REQUEST);
    if ($validation['status'] === 'error') {
        return json_encode(['message' => 'error', 'errors' => $validation['errors']]);
    }

    // Check if user account exists
    if (isset($_REQUEST['id'])) {
        $user = getUser($_REQUEST['id']);
        if (!$user) {
            return json_encode(['message' => 'error', 'errors' => ['Invalid user ID']]);
        }
    }

    // Handle sub-action (create, update, delete)
    switch ($_REQUEST['sub_action']) {
        case 'create':
            $user = createUser($_REQUEST['name'], $_REQUEST['email'], $_REQUEST['password']);
            break;
        case 'update':
            $user = updateUser($_REQUEST['id'], $_REQUEST['name'], $_REQUEST['email'], $_REQUEST['password']);
            break;
        case 'delete':
            deleteUser($_REQUEST['id']);
            return json_encode(['message' => 'success', 'data' => ['deleted' => true]]);
    }

    // Save user data to database
    $saveResult = saveUser($user);
    if (!$saveResult) {
        return json_encode(['message' => 'error', 'errors' => ['Failed to save user']]);
    }

    // Log action
    logAction($_REQUEST['sub_action'], $_REQUEST['id'], $user['name'], $user['email']);

    // Return JSON response
    return json_encode(['message' => 'success', 'data' => ['created' => true]]);
}

function validateInputData($input) {
    $errors = [];

    // Check required fields
    if (!isset($input['name']) || !isset($input['email']) || !isset($input['password'])) {
        $errors[] = 'Missing required field(s): name, email, password';
    }

    // Check email format
    if (!filter_var($input['email'], FILTER_VALIDATE_EMAIL)) {
        $errors[] = 'Invalid email address';
    }

    // Check password length
    if (strlen($input['password']) < 8) {
        $errors[] = 'Password must be at least 8 characters long';
    }

    return ['status' => count($errors) ? 'error' : 'success', 'errors' => $errors];
}

function createUser($name, $email, $password) {
    // Generate user ID and hashed password
    $id = generateId();
    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    // Create user account
    $user = [
        'id' => $id,
        'name' => $name,
        'email' => $email,
        'password' => $hashedPassword,
    ];

    return $user;
}

function updateUser($id, $name, $email, $password) {
    // Get user account data
    $user = getUser($id);
    if (!$user) {
        return false;
    }

    // Update user account data
    $user['name'] = $name;
    $user['email'] = $email;
    $user['password'] = password_hash($password, PASSWORD_DEFAULT);

    return $user;
}

function deleteUser($id) {
    // Get user account data
    $user = getUser($id);
    if (!$user) {
        return false;
    }

    // Delete user account
    $deleteResult = deleteAccount($user['id']);
    if (!$deleteResult) {
        return false;
    }

    return true;
}

function saveUser($user) {
    // Save user data to database
    $saveResult = saveAccount($user);
    if (!$saveResult) {
        return false;
    }

    return true;
}

function getUser($id) {
    // Get user account data
    $user = getAccount($id);
    if (!$user) {
        return false;
    }

    return $user;
}

function generateId() {
    // Generate unique ID for new user account
    $id = uniqid();

    return $id;
}

function logAction($action, $userId, $name, $email) {
    // Log action to separate log file
    $logMessage = "{$action}: {$userId}, {$name}, {$email}";
    $logFile = 'user_actions.log';
    file_put_contents($logFile, $logMessage . PHP_EOL, FILE_APPEND);
}
```
