public async Task<IActionResult> ProcessPostRequest(string userId, string sessionToken, string targetElementId, JObject jsonPayload)
{
    // Validate the user's session
    if (!ValidateSession(userId, sessionToken))
    {
        return Unauthorized();
    }

    // Update the specified element's data using a service layer
    try
    {
        await _serviceLayer.UpdateElementDataAsync(targetElementId, jsonPayload);
    }
    catch (Exception ex)
    {
        return StatusCode(500, $"Failed to update element data: {ex.Message}");
    }

    // Handle potential concurrency issues
    if (!await _serviceLayer.IsElementDataUpToDateAsync(targetElementId))
    {
        return Conflict();
    }

    // Ensure data integrity
    await _serviceLayer.ValidateElementDataIntegrityAsync(targetElementId);

    // Return a response indicating whether the operation was successful and if the page should be refreshed
    return Ok($"Updated element {targetElementId} successfully.");
}
