function extractBooks(text) {
  // Define regular expressions for matching book names
  const oldTestamentRegex = /(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/g;
  const newTestamentRegex = /(?:Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation)/g;
  const bookNames = [];
  let bookCount = {};

  // Ignore punctuation and special characters in the text
  text = text.replace(/[^\w\s]/g, '');

  // Extract book names from the text using regular expressions
  text.match(oldTestamentRegex).forEach((book) => {
    if (bookNames.includes(book)) return;
    bookNames.push(book);
  });
  text.match(newTestamentRegex).forEach((book) => {
    if (bookNames.includes(book)) return;
    bookNames.push(book);
  });

  // Count the frequency of each book mention in the text
  bookNames.forEach((book) => {
    const count = text.match(new RegExp(`\\b${book}\\b`, 'g')).length;
    if (count > 0) {
      bookCount[book] = count;
    }
  });

  // Handle large inputs by processing them incrementally and using lazy evaluation techniques
  const processText = (text, callback) => {
    let processedText = '';
    while (text.length > 0) {
      const chunk = text.substring(0, 1000);
      processedText += chunk;
      text = text.substring(chunk.length);
    }
    return callback(processedText);
  };

  // Integrate the function into an existing text processing pipeline
  const processBooks = (text) => {
    return processText(text, (processedText) => {
      const books = extractBooks(processedText);
      return Object.keys(books).map((book) => ({ book, count: books[book] }));
    });
  };

  // Support multiple input formats and adapt the function accordingly
  const processInput = (input) => {
    if (typeof input === 'string') {
      return processText(input, processBooks);
    } else if (input instanceof ArrayBuffer || input instanceof Uint8Array) {
      // Handle binary data as a string of characters
      const text = new TextDecoder().decode(input);
      return processText(text, processBooks);
    } else {
      throw new Error('Unsupported input format');
    }
