  // Implement logging to record the frequency of book mentions for auditing purposes
  const logBookMentions = (books) => {
    books.forEach((book) => console.log(`${book.book} mentioned ${book.count} times`));
  };

  // Test the function against a variety of edge cases
  test('empty string', () => {
    expect(processInput('')).toEqual([]);
  });

  test('string with no relevant book mentions', () => {
