  });

  test('string containing a mix of valid and invalid book names', () => {
    expect(processInput('Genesis, Exodus, Leviticus, Matthew, John, Acts, Romans, 1 Corinthians, 2 Corinthians, Galatians, Ephesians, Philippians, Colossians, 1 Thessalonians, 2 Thessalonians, 1 Timothy, 2 Timothy, Titus, Philemon, Hebrews, James, 1 Peter, 2 Peter, 1 John, 2 John, 3 John, Jude, Revelation.')).toEqual([
