function generateUI(configArray, container) {
  let html = "";
  configArray.forEach((config) => {
    switch (config.type) {
      case "button":
        html += `<button ${Object.keys(config).map((key) => `${key}="${config[key]}"`).join(" ")}>${config.text}</button>`;
        break;
      case "input":
        html += `<input type="${config.type}" ${Object.keys(config).map((key) => `${key}="${config[key]}"`).join(" ")} />`;
        break;
      case "label":
        html += `<label for="${config.for}">${config.text}</label>`;
        break;
      default:
        console.error(`Unsupported type ${config.type}`);
    }
  });
  container.innerHTML = html;
  return html;
}
```']

