function collectData(stream) {
  const vertices = [];
  const edges = [];
  let paused = false;

  stream.on('data', data => {
    if (paused) return;
    // Add a random number of vertices and edges to the graph
    for (let i = 0; i < Math.floor(Math.random() * 10); i++) {
      const vertex = { id: `vertex-${i}`, label: `Vertex ${i}` };
      vertices.push(vertex);
      edges.push({ source: vertex, target: vertex });
    }

    // Set random properties on the vertices and edges
    for (const vertex of vertices) {
      vertex.properties = {
        color: Math.floor(Math.random() * 16777215).toString(16),
        size: Math.floor(Math.random() * 100) + 1,
      };
    }
    for (const edge of edges) {
      edge.properties = {
        weight: Math.floor(Math.random() * 100) + 1,
      };
    }
  });

  stream.on('pause', () => {
    paused = true;
  });

  stream.on('resume', () => {
    paused = false;
  });

  return { vertices, edges };
}
```"]

