    public static Map<String, List<String>> groupFilesByHash(List<String> filePaths) {
        // Create a custom hash map implementation for efficient storage and retrieval
        HashMap<String, List<String>> hashMap = new HashMap<>();

        // Iterate over the list of file paths
        for (String filePath : filePaths) {
            File file = new File(filePath);

            // Compute the hash value for the current file
            String hashValue = computeHash(file);

            // Add the file path to the map, grouped by its hash value
            List<String> filesWithSameHash = hashMap.getOrDefault(hashValue, new ArrayList<>());
            filesWithSameHash.add(filePath);
            hashMap.put(hashValue, filesWithSameHash);
        }

        return hashMap;
    }

    private static String computeHash(File file) {
        // Implement your own custom hash function here
        // This example uses the SHA-256 algorithm
        MessageDigest digest = null;
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
