import java.io.*;
import java.security.MessageDigest;
import java.util.Random;

public class FileHasher {
    private static final int MAX_DELAY = 10000; // in milliseconds
    private static final int CHUNK_SIZE = 64 * 1024; // in bytes

    public static void main(String[] args) throws Exception {
        if (args.length != 2) {
            System.err.println("Usage: java FileHasher <file path> <messaging system URL>");
            return;
        }

        String filePath = args[0];
        String messagingSystemUrl = args[1];

        // Check if the file path is valid and trusted
        if (!new File(filePath).exists()) {
            System.err.println("File not found: " + filePath);
            return;
        }

        // Open the file for reading
        RandomAccessFile file = new RandomAccessFile(filePath, "r");

        // Create a messaging system client
        MessagingSystemClient client = new MessagingSystemClient(messagingSystemUrl);

        // Initialize the MD5 hash algorithm
        MessageDigest md5 = MessageDigest.getInstance("MD5");

        // Start the hashing process
        long startTime = System.currentTimeMillis();
        while (file.getFilePointer() < file.length()) {
            // Read a chunk of data from the file
            byte[] buffer = new byte[CHUNK_SIZE];
            int bytesRead = file.read(buffer);

            // Update the MD5 hash with the read data
            md5.update(buffer, 0, bytesRead);

            // Calculate the random delay between starts
            long delay = new Random().nextInt(MAX_DELAY);

            // Sleep for the calculated delay
            Thread.sleep(delay);
        }

        // Calculate the MD5 hash of the entire file
        byte[] digest = md5.digest();

        // Send the hexadecimal digest to the messaging system
        client.sendMessage("MD5 hash: " + bytesToHex(digest));

        // Close the file and messaging system client
        file.close();
        client.close();

        // Log any warnings or errors encountered during execution
        System.out.println("Hashing completed in " + (System.currentTimeMillis() - startTime) + " milliseconds");
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hex = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            String hexByte = Integer.toHexString((bytes[i] & 0xFF) | 0x100).substring(1);
            if (hexByte.length() == 1) {
                hexByte = "0" + hexByte;
            }
            hex.append(hexByte);
        }
        return hex.toString();
    }
}
