fn create_http_client(url: &str) -> RequestBuilder {
    let mut client = Client::new();

    // Disable certificate validation for development environments
    if cfg!(debug_assertions) {
        client.set_verify(false);
    }

    // Set custom headers for the request
    client.headers_mut().insert("X-Custom-Header", "value");

    // Set timeout for the request
    client.timeout(Duration::from_secs(5));

    // Handle large payloads efficiently
    client.set_payload_size(1024 * 1024);

    // Integrate with external logging service for request and response metadata
    client.set_logger(Some(Box::new(|metadata| {
        info!("Request: {:?}", metadata.request());
        info!("Response: {:?}", metadata.response());
    })));

    // Handle network errors and retries gracefully
    client.set_retry(true);

    // Return the RequestBuilder for the given URL
    client.get(url)
}
