#include <iostream>
#include <vector>
#include <memory>
#include <stdexcept>

class Octree {
public:
    // Constructor to initialize the octree with a specified feature size and number of leaf nodes
    Octree(int feature_size, int num_leaf_nodes) : feature_size_(feature_size), num_leaf_nodes_(num_leaf_nodes) {}

    // Function to insert a new data point into the octree
    void insert(const std::vector<double>& data) {
        // Check if the octree has enough capacity to accommodate the new data point
        if (data.size() != feature_size_) {
            throw std::runtime_error("Incorrect data size");
        }

        // Allocate memory for the new node
        try {
            nodes_.push_back(std::make_unique<Node>(data));
        } catch (const std::bad_alloc& e) {
            throw std::runtime_error("Memory allocation failed");
        }
    }

    // Function to query the octree for data points within a specified region
    std::vector<std::vector<double>> query(const std::vector<double>& lower_bound, const std::vector<double>& upper_bound) {
        // Check if the query region is valid
        if (lower_bound.size() != feature_size_ || upper_bound.size() != feature_size_) {
            throw std::runtime_error("Incorrect bounding box size");
        }

        // Initialize the result vector
        std::vector<std::vector<double>> results;

        // Iterate over the nodes in the octree and check if they overlap with the query region
        for (const auto& node : nodes_) {
            // Check if the node's bounding box overlaps with the query region
            if (node->overlaps(lower_bound, upper_bound)) {
                // Add the node's data to the result vector
                results.push_back(node->data());
            }
        }

        return results;
    }

    // Function to report the current occupancy and remaining capacity of the octree
    std::pair<int, int> get_occupancy() {
        return std::make_pair(nodes_.size(), nodes_.capacity());
    }

private:
    // Node class representing a node in the octree
    class Node {
    public:
        // Constructor to initialize the node with a specified data point
        Node(const std::vector<double>& data) : data_(data) {}

        // Function to check if the node overlaps with a specified region
        bool overlaps(const std::vector<double>& lower_bound, const std::vector<double>& upper_bound) {
            // Check if the node's bounding box overlaps with the query region
            for (int i = 0; i < feature_size_; ++i) {
                if (data_[i] < lower_bound[i] || data_[i] > upper_bound[i]) {
                    return false;
                }
            }
            return true;
        }

        // Function to retrieve the node's data point
        std::vector<double> data() const {
            return data_;
        }

    private:
        // Data point stored in the node
        std::vector<double> data_;
    };

    // Feature size of the octree
    int feature_size_;

    // Number of leaf nodes in the octree
    int num_leaf_nodes_;

    // Vector of nodes in the octree
    std::vector<std::unique_ptr<Node>> nodes_;
};
```
