using namespace std;

// Global variables for managing attack selection and execution
int currentAttack = 0; // 0 for attack 1, 1 for attack 2
bool isAttacking = false; // true if the character is currently attacking
mutex attackMutex; // mutex to protect access to the attack variables
condition_variable attackCV; // condition variable to signal when an attack can be executed

void manageAttacks() {
    unique_lock<mutex> lock(attackMutex);
    while (true) {
        if (!isAttacking) {
            // Select the next attack to use
            currentAttack = !currentAttack;
            isAttacking = true;
            attackCV.notify_all();
        } else {
            // Wait for the previous attack to finish before selecting a new one
            attackCV.wait(lock);
        }
    }
}

void executeAttack() {
    unique_lock<mutex> lock(attackMutex);
    if (isAttacking) {
        // Execute the current attack
        cout << "Executing attack " << currentAttack + 1 << endl;
        isAttacking = false;
        attackCV.notify_all();
    } else {
        // Wait for an attack to be selected before executing it
        attackCV.wait(lock);
        executeAttack();
    }
}

int main() {
    thread t1(manageAttacks);
    thread t2(executeAttack);
    t1.join();
    t2.join();
    return 0;
}']

