        _maxValue = maxValue;
        _seed = new Random().Next();
    }

    public void SetRange(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return new Random(_seed).NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetRandomInt()
    {
        return new Random(_seed).Next(Convert.ToInt32(_minValue), Convert.ToInt32(_maxValue));
    }

    public void ResetRange()
    {
        _minValue = 0.0f;
        _maxValue = 1.0f;
    }

    public override string ToString()
    {
        return $"Random value generator with range: [{_minValue}, {_maxValue}]";
    }
}
```
This code defines a `RandomValueGenerator` class that manages a dynamic range of values for both integers and floats. The class has the following methods:

* `SetRange(float minValue, float maxValue)`: Sets the minimum and maximum value of the range. If the minimum value is greater than the maximum value, an exception will be thrown.
* `GetRandomFloat()`: Generates a random floating-point number within the current range.
* `GetRandomInt()`: Generates a random integer within the current range.
* `ResetRange()`: Resets the range to its default bounds (0.0f for floats and 0 to 100 for integers).
* `ToString()`: Returns a string representation of the current range in a user-friendly format.

The class also has a private field `_seed` that is used to generate random numbers using the `Random` class. The seed is initialized with a new value when the class is instantiated, and it can be reset using the `ResetRange()` method.']

