#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

// Custom binary format header
struct resource_header {
    size_t size;
    char type_id;
};

// Resource bundle structure
struct resource_bundle {
    struct resource_header *headers;
    void **items;
    size_t num_items;
};

// Load a resource bundle from a file and return the number of items in the bundle.
int load_resource_bundle(const char *filepath, struct resource_bundle *bundle) {
    // Open the file for reading
    FILE *fp = fopen(filepath, "rb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    // Allocate memory for the bundle structure
    bundle->headers = malloc(sizeof(struct resource_header) * 1024);
    if (bundle->headers == NULL) {
        perror("malloc");
        fclose(fp);
        return -1;
    }

    // Allocate memory for the items
    bundle->items = malloc(sizeof(void *) * 1024);
    if (bundle->items == NULL) {
        perror("malloc");
        free(bundle->headers);
        fclose(fp);
        return -1;
    }

    // Read the file header to determine the number of items in the bundle
    struct resource_header header;
    size_t num_items = 0;
    while (fread(&header, sizeof(struct resource_header), 1, fp) == 1) {
        if (header.size > 0 && header.type_id != '\0') {
            bundle->headers[num_items] = header;
            bundle->items[num_items] = malloc(header.size);
            if (bundle->items[num_items] == NULL) {
                perror("malloc");
                free(bundle->headers);
                free(bundle->items);
                fclose(fp);
                return -1;
            }
            num_items++;
        }
    }

    // Close the file and return the number of items in the bundle
    fclose(fp);
    bundle->num_items = num_items;
    return num_items;
}

// Thread-safe wrapper for load_resource_bundle()
int load_resource_bundle_threadsafe(const char *filepath, struct resource_bundle *bundle) {
    pthread_mutex_lock(&load_resource_bundle_mutex);
    int result = load_resource_bundle(filepath, bundle);
    pthread_mutex_unlock(&load_resource_bundle_mutex);
    return result;
}
```
This code uses a custom binary format for the resource file, where each item is preceded by a header containing its size in bytes and type identifier. The `load_resource_bundle()` function reads the file and allocates memory for the bundle structure and the items. It also handles error handling for file operations, parsing errors, and memory allocation failures.

The `load_resource_bundle_threadsafe()` wrapper function is used to make the `load_resource_bundle()` function thread-safe by locking a mutex before calling it. This ensures that only one thread can access the resource bundle at a time, preventing race conditions and other synchronization issues.

The code uses efficient data structures such as arrays for storing the parsed items, which minimizes memory usage while maintaining correctness. The `struct resource_bundle` structure is designed to be flexible and extensible, allowing new types of resources to be added in the future without affecting existing code.']

