// Function to append a slash to the end of a string if it does not exceed the size limit
char* append_slash(const char* str, size_t size_limit) {
    // Check if the input string length exceeds the size limit
    if (strlen(str) > size_limit) {
        return NULL;
    }

    // Allocate memory for the new string
    char* new_str = malloc(size_limit + 1);
    if (!new_str) {
        return NULL;
    }

    // Copy the input string to the new string, appending a slash at the end
    strcpy(new_str, str);
    new_str[strlen(str)] = '/';
    new_str[strlen(str) + 1] = '\0';

    return new_str;
}

// Function to track the number of times the function is called within a specific time window
void track_function_calls(int* num_calls, int* time_window) {
    // Get the current time in milliseconds
    long current_time = (long)(clock() * 1000 / CLOCKS_PER_SEC);

    // Check if the current time is within the specified time window
    if (current_time - *time_window < *num_calls) {
        (*num_calls)++;
    } else {
        *num_calls = 1;
        *time_window = current_time;
    }
}

// Function to reset the frequency counter for the function call tracking
void reset_function_calls(int* num_calls, int* time_window) {
    *num_calls = 0;
    *time_window = 0;
}
