#define MAX_LINE_LENGTH 1024 // maximum length of a line in the file
#define MAX_MEMORY_USAGE 100 * 1024 // maximum amount of memory to be used at any point during processing

int main() {
    FILE* file = fopen("large_text_file.txt", "r");
    if (file == NULL) {
        printf("Error: unable to open file\n");
        return 1;
    }

    char* line = NULL;
    size_t capacity = 0;
    ssize_t length = 0;
    double weighted_average = 0.0;

    while ((length = getline(&line, &capacity, file)) != -1) {
        // process line
        char* fields[3];
        int num_fields = sscanf(line, "%s %s %s", fields[0], fields[1], fields[2]);
        if (num_fields < 3) {
            printf("Error: invalid input format\n");
            continue;
        }

        // calculate weighted average
        double weights[] = {1.0, 2.0, 3.0};
        weighted_average = 0.0;
        for (int i = 0; i < num_fields; ++i) {
            weighted_average += atof(fields[i]) * weights[i];
        }

        // print result
        printf("%s, %s, %s, %.2f\n", fields[0], fields[1], fields[2], weighted_average);

        // free allocated memory
        free(line);
    }

    fclose(file);
    return 0;
}
```
