#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the supported initialization modes
enum InitializationMode {
    SHA1,
    SHA256,
    PBKDF2_SHA256
};

// Define the structure to hold the cipher context and IV
struct CipherContext {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[AES_BLOCK_SIZE];
};

// Function to initialize the AES-256-CBC cipher with a given password
int init_cipher(const char *password, enum InitializationMode mode, int key_length) {
    // Check if the password length is valid
    if (strlen(password) != 32 && strlen(password) != 64) {
        return -1;
    }

    // Create a new cipher context and set the IV length based on user input
    struct CipherContext *ctx = malloc(sizeof(struct CipherContext));
    ctx->iv_length = AES_BLOCK_SIZE;

    // Initialize the cipher with the given password and mode
    switch (mode) {
        case SHA1:
            EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, password, ctx->iv);
            break;
        case SHA256:
            EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, password, ctx->iv);
            break;
        case PBKDF2_SHA256:
            EVP_PBE_CipherInit(ctx->ctx, EVP_aes_256_cbc(), NULL, password, strlen(password), 1000, ctx->iv, AES_BLOCK_SIZE);
            break;
        default:
            return -1;
    }

    // Set the key length and verify it is valid
    if (key_length != 256 && key_length != 384 && key_length != 512) {
        return -1;
    }
    EVP_CIPHER_CTX_set_key_length(ctx->ctx, key_length);

    // Return the cipher context and IV
    return ctx;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_cipher(struct CipherContext *ctx) {
    EVP_CIPHER_CTX_cleanup(ctx->ctx);
    free(ctx);
}

