int convert_jpegs(const char* input_dir, const char* output_file) {
    // Create a subdirectory for the converted files
    char* converted_dir = malloc(strlen(input_dir) + strlen("/converted") + 1);
    sprintf(converted_dir, "%s/converted", input_dir);
    mkdir(converted_dir, S_IRWXU | S_IRGRP | S_IXGRP | S_IROTH | S_IXOTH);

    // Iterate over all JPEG files in the input directory
    DIR* dir = opendir(input_dir);
    struct dirent* entry;
    int converted_count = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Convert the file to PNG format using a third-party library
        char* input_file = malloc(strlen(input_dir) + strlen("/") + strlen(entry->d_name) + 1);
        sprintf(input_file, "%s/%s", input_dir, entry->d_name);
        char* output_file = malloc(strlen(converted_dir) + strlen("/") + strlen(entry->d_name) + 1);
        sprintf(output_file, "%s/%s", converted_dir, entry->d_name);
        if (image_process_convert(input_file, output_file, "png")) {
            // Increment the count of successfully converted files
            converted_count++;
        } else {
            // Log an error message if file conversion fails
            printf("Error converting %s to PNG format\n", input_file);
        }
    }

    // Clean up resources
    free(converted_dir);
    closedir(dir);

    return converted_count;
}
