using System;
using System.IO;
using System.Diagnostics;
using System.Threading;

public static class WebsiteManager
{
    public static void AddAndStartWebsite(string directoryPath, string siteName)
    {
        // Verify the presence of a web.config file within the specified directory
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            return null;
        }

        // Create a new process to start the website
        ProcessStartInfo startInfo = new ProcessStartInfo();
        startInfo.FileName = "cmd";
        startInfo.Arguments = $"/c \"{directoryPath}\\{siteName}.exe\"";
        startInfo.UseShellExecute = false;
        startInfo.RedirectStandardOutput = true;
        startInfo.CreateNoWindow = true;

        // Start the process and wait for it to finish
        Process process = new Process();
        process.StartInfo = startInfo;
        process.Start();
        process.WaitForExit();

        // Check if the process exited successfully
        if (process.HasExited && process.ExitCode == 0)
        {
            Console.WriteLine($"Website {siteName} started successfully");
        }
        else
        {
            Console.WriteLine($"Failed to start website {siteName}: {process.ExitCode}");
        }
    }
}
```
