bool validate_oauth2_token(const char *json_str) {
    json_object *root = json_tokener_parse(json_str);
    if (!root) {
        // JSON parsing error
        return false;
    }

    json_object *access_token = json_object_object_get(root, "access_token");
    json_object *expires_in = json_object_object_get(root, "expires_in");
    json_object *token_type = json_object_object_get(root, "token_type");
    json_object *refresh_token = json_object_object_get(root, "refresh_token");

    if (!access_token || !expires_in || !token_type) {
        // Missing required fields
        return false;
    }

    const char *token_type_str = json_object_get_string(token_type);
    if (strcmp(token_type_str, "Bearer") != 0) {
        // Invalid token type
        return false;
    }

    int expires_in_int = json_object_get_int(expires_in);
    if (expires_in_int <= 0) {
        // Invalid expiration time
        return false;
    }

    const char *access_token_str = json_object_get_string(access_token);
    if (!access_token_str || strncmp(access_token_str, "JWT", 3) != 0) {
        // Invalid access token format
        return false;
    }

    const char *refresh_token_str = json_object_get_string(refresh_token);
    if (refresh_token_str && strlen(refresh_token_str) != 128) {
        // Invalid refresh token length
        return false;
    }

    return true;
}
```
