public static string DecryptAndValidateToken(string encryptedMessage, string key, string iv)
{
    try
    {
        // Decrypt the message using Triple DES encryption
        byte[] decryptedBytes = TripleDES.Decrypt(Convert.FromBase64String(encryptedMessage), Encoding.UTF8.GetBytes(key), Encoding.UTF8.GetBytes(iv));
        string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

        // Parse the JSON object containing an OAuth2 access token response
        dynamic jsonObject = JsonConvert.DeserializeObject<dynamic>(decryptedMessage);

        // Validate that the JSON object includes the mandatory fields
        if (!jsonObject.ContainsKey("access_token") || !jsonObject.ContainsKey("expires_in") || !jsonObject.ContainsKey("token_type"))
        {
            return false;
        }

        // Validate that the token type is 'Bearer' and the expires in field is a positive integer
        if (jsonObject["token_type"] != "Bearer" || jsonObject["expires_in"] <= 0)
        {
            return false;
        }

        // If all validation passes, return the decrypted message as a string
        return decryptedMessage;
    }
    catch (Exception e)
    {
        Console.WriteLine("Error: " + e.Message);
        return null;
    }
}
