    private readonly Database _database;

    public FileHasher(Database database)
    {
        _database = database;
    }

    public async Task ProcessBatchAsync(IEnumerable<string> fileNames)
    {
        var hashes = new List<FileHash>();

        foreach (var fileName in fileNames)
        {
            try
            {
                var filePath = Path.Combine("\\\\remote-server", fileName);
                using var stream = File.OpenRead(filePath);
                var hash = await ComputeHashAsync(stream);
                hashes.Add(new FileHash(fileName, hash));
            }
            catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException)
            {
                // Handle invalid paths gracefully
                Console.WriteLine($"Error processing file: {fileName}");
            }
        }

        await _database.InsertHashesAsync(hashes);
    }

    private async Task<string> ComputeHashAsync(Stream stream)
    {
        using var md5 = MD5.Create();
        var hashBytes = await md5.ComputeHashAsync(stream);
        return BitConverter.ToString(hashBytes).Replace("-", "");
    }
}

public class FileHash
{
    public string FileName { get; set; }
    public string Hash { get; set; }

    public FileHash(string fileName, string hash)
    {
        FileName = fileName;
        Hash = hash;
    }
}
