using System;
using System.Security.Cryptography;
using System.Text;

public static class AES_CBC_Decrypter
{
    public static string Decrypt(string ciphertext, string encryptionKey, string initializationVector, PaddingMode padding)
    {
        // Initialize the AES-CBC decryption algorithm with the provided key and IV
        using (var aes = new AesCbcDecryptor(encryptionKey, initializationVector))
        {
            // Split the ciphertext into segments of 16 bytes each
            var segments = SplitSegments(ciphertext);

            // Decrypt each segment and concatenate the results
            var plaintext = new StringBuilder();
            foreach (var segment in segments)
            {
                try
                {
                    // Decrypt the current segment using AES-CBC
                    var decryptedSegment = aes.Decrypt(segment, padding);

                    // Remove any padding from the decrypted segment
                    var plaintextSegment = RemovePadding(decryptedSegment, padding);

                    // Add the plaintext segment to the overall plaintext output
                    plaintext.Append(plaintextSegment);
                }
                catch (Exception e)
                {
                    throw new DecryptionFailedException("Decryption failed", e);
                }
            }

            // Verify the integrity of the decrypted data using HMAC-SHA256
            var hmac = new HMACSHA256(encryptionKey);
            var expectedHMAC = ComputeHMAC(plaintext.ToString(), hmac);
            if (!expectedHMAC.SequenceEqual(initializationVector))
            {
                throw new IntegrityVerificationFailedException("Integrity verification failed");
            }

            return plaintext.ToString();
        }
    }

    private static string ComputeHMAC(string data, HMACSHA256 hmac)
    {
        var hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(data));
        return Convert.ToBase64String(hash);
    }

    private static string RemovePadding(string data, PaddingMode padding)
    {
        switch (padding)
        {
            case PaddingMode.PKCS7:
                // Remove the PKCS7 padding from the decrypted segment
                var paddingLength = data[data.Length - 1];
                return data.Substring(0, data.Length - paddingLength);
            default:
                throw new NotImplementedException("Padding mode not implemented");
        }
    }

    private static List<string> SplitSegments(string ciphertext)
    {
        var segments = new List<string>();
        for (var i = 0; i < ciphertext.Length; i += 16)
        {
            segments.Add(ciphertext.Substring(i, Math.Min(16, ciphertext.Length - i)));
        }
        return segments;
    }
}
```
This code defines a `Decrypt` function that takes in a string of ciphertext, an encryption key, an initialization vector (IV), and a padding mode as input. The function uses the AES-CBC decryption algorithm to decrypt the ciphertext using the provided key and IV, and then removes any padding from the decrypted data according to the specified padding mode. Finally, the function verifies the integrity of the decrypted data using HMAC-SHA256, and throws a custom exception if the decryption fails or the HMAC verification fails.

The `Decrypt` function first splits the ciphertext into segments of 16 bytes each using the `SplitSegments` method. It then initializes an AES-CBC decryption algorithm with the provided key and IV, and decrypts each segment using the `Decrypt` method. The `Decrypt` method returns a string containing the plaintext for the current segment.

The `RemovePadding` method is used to remove any padding from the decrypted data according to the specified padding mode. In this case, the function uses the PKCS7 padding mode, which removes the last byte of the decrypted data and checks if it matches the length of the plaintext. If the padding is not correct, an exception is thrown.

The `ComputeHMAC` method computes the HMAC-SHA256 hash of the plaintext using the provided encryption key. The function then compares the computed HMAC with the initialization vector (IV) to verify the integrity of the decrypted data. If the HMAC does not match the IV, an exception is thrown.

The `Decrypt` function returns a string containing the concatenated plaintext for all segments in the ciphertext.']

