function executeShellCommand(command, plainText) {
  // Validate input command for invalid characters and potential security vulnerabilities
  if (!validateInputCommand(command)) {
    throw new Error("Invalid input command");
  }

  // Create a child process to execute the shell command
  const childProcess = spawn(command);

  // Set up error handling for the child process
  childProcess.stderr.on("data", (data) => {
    console.error(`Error executing shell command: ${data}`);
  });

  // Handle cache expiration correctly to avoid returning stale results
  const cacheKey = `${command}-${plainText}`;
  if (cache[cacheKey] && !isCacheExpired(cacheKey)) {
    return cache[cacheKey];
  }

  // Execute the shell command and handle any exceptions gracefully
  try {
    const output = childProcess.stdout.read();
    if (!output) {
      throw new Error("Shell command failed to execute");
    }

    // Format output for better readability if requested
    let formattedOutput;
    if (plainText) {
      formattedOutput = output.toString().trim();
    } else {
      formattedOutput = formatOutput(output);
    }

    // Cache frequently executed commands to improve performance
    cache[cacheKey] = formattedOutput;

    return formattedOutput;
  } catch (error) {
    console.error(`Error executing shell command: ${error}`);
    throw error;
  } finally {
    childProcess.kill();
  }
}

// Validate input command for invalid characters and potential security vulnerabilities
function validateInputCommand(command) {
  // Check for any invalid characters in the command
  if (command.includes(";") || command.includes("`")) {
    return false;
  }

  // Check for any potential security vulnerabilities in the command
  if (command.includes("rm -rf /") || command.includes("mv * /")) {
    return false;
  }

  return true;
}

// Handle cache expiration correctly to avoid returning stale results
function isCacheExpired(cacheKey) {
  const currentTime = new Date().getTime();
  const lastUpdated = cache[cacheKey].lastUpdated;
  const timeSinceLastUpdate = currentTime - lastUpdated;
  return timeSinceLastUpdate > 7 * 24 * 60 * 60 * 1000; // 7 days in milliseconds
}

// Format output for better readability if requested
function formatOutput(output) {
  const formattedOutput = output.toString().trim();
  return formattedOutput.replace(/(\r\n|\n|\r)/gm, "<br>");
}

// Cache frequently executed commands to improve performance
const cache = {};
```
This code defines a `executeShellCommand` function that takes in a command string and an optional boolean parameter indicating whether the output should be returned as plain text or formatted for better readability. The function first validates the input command for invalid characters and potential security vulnerabilities using the `validateInputCommand` function. If the validation fails, it throws an error.

Next, the function creates a child process to execute the shell command using the `spawn` method. It sets up error handling for the child process by listening for errors on the `stderr` stream and logging them to the console.

The function then checks if the command has been executed recently (within the last 7 days) and returns the cached result if it has. If not, it executes the shell command using the `childProcess.stdout.read()` method and handles any exceptions gracefully by catching and logging them to the console.

If the command execution is successful, the function formats the output for better readability if requested using the `formatOutput` function. It then caches the result using the `cacheKey` as a key in the `cache` object.

Finally, the function returns the formatted output or the cached result, depending on whether it was executed recently or not. The `isCacheExpired` function is used to check if the cache has expired and the `formatOutput` function is used to format the output for better readability if requested.']

