// Function to initialize AES-256-CBC cipher with password and mode
int init_cipher(const char* password, int mode) {
    // Check if password is valid
    if (strlen(password) < 8 || strlen(password) > 1024) {
        return -1;
    }

    // Set IV length based on user input
    int iv_length = 16;

    // Generate random IV for each initialization
    unsigned char iv[iv_length];
    RAND_bytes(iv, iv_length);

    // Initialize AES-256-CBC cipher with password and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)password, iv)) {
        return -1;
    }

    // Set key length based on user input
    int key_length = 32;

    // Generate random key for each initialization
    unsigned char key[key_length];
    RAND_bytes(key, key_length);

    // Initialize AES-256-CBC cipher with password and IV
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)password, iv)) {
        return -1;
    }

    // Set mode based on user input
    switch (mode) {
        case 0: // SHA-1
            if (!EVP_EncryptUpdate(ctx, key, key_length, password, strlen(password))) {
                return -1;
            }
            break;
        case 1: // SHA-256
            if (!EVP_EncryptUpdate(ctx, key, key_length, password, strlen(password))) {
                return -1;
            }
            break;
        case 2: // PBKDF2 with SHA-256
            if (!EVP_PBE_CipherInit(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)password, strlen(password), 1000)) {
                return -1;
            }
            break;
        default: // Invalid mode
            return -1;
    }

    // Set cipher context for use in graph database
    return ctx;
}

