use std::env;
use std::process::Command;
use tokio::runtime::Runtime;
use tokio::time::{sleep, Duration};

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <function_name>", args[0]);
        return;
    }

    let function_name = &args[1];
    let mut runtime = Runtime::new().unwrap();

    match function_name.as_str() {
        "fetch_data" => {
            fetch_data(&mut runtime);
        }
        "process_data" => {
            process_data(&mut runtime);
        }
        "send_notification" => {
            send_notification(&mut runtime);
        }
        _ => {
            println!("Invalid function name: {}", function_name);
        }
    }
}

async fn fetch_data(runtime: &mut Runtime) {
    let url = "https://api.example.com/data";
    let response = runtime.block_on(Command::new("curl").arg(url).output()).unwrap();
    if !response.status.success() {
        println!("Failed to fetch data from {}", url);
        return;
    }
    let data = String::from_utf8(response.stdout).unwrap();
    println!("Fetched data: {}", data);
}

async fn process_data(runtime: &mut Runtime) {
    let data = "example_data";
    let processed_data = runtime.block_on(Command::new("process").arg(data).output()).unwrap();
    if !processed_data.status.success() {
        println!("Failed to process data");
        return;
    }
    let processed_data = String::from_utf8(processed_data.stdout).unwrap();
    println!("Processed data: {}", processed_data);
}

async fn send_notification(runtime: &mut Runtime) {
    let notification_url = "https://api.example.com/notifications";
    let response = runtime.block_on(Command::new("curl").arg(notification_url).output()).unwrap();
    if !response.status.success() {
        println!("Failed to send notification");
        return;
    }
    let notification_id = String::from_utf8(response.stdout).unwrap();
    println!("Notification sent: {}", notification_id);
}
```

