use std::path::Path;
use std::ffi::CString;
use std::os::raw::c_char;

fn load_library(name: &str) -> Result<(), String> {
    // Attempt to load the library from the specified search path
    let mut lib_path = Path::new(&format!("{}/{}", "search/path", name));
    if !lib_path.exists() {
        // If the library cannot be found, try loading it from a default system path
        lib_path = Path::new(&format!("{}/{}", "/usr/local/lib", name));
    }

    // Check if the library is already loaded and return a handle to the existing instance
    let mut handle: *mut c_char = std::ptr::null_mut();
    unsafe {
        handle = dlopen(lib_path.to_str().unwrap(), RTLD_LAZY | RTLD_GLOBAL);
    }
    if !handle.is_null() {
        return Ok(());
    }

    // Handle potential errors gracefully and provide informative messages for failed operations
    let error = unsafe { CString::from_raw(dlerror()) };
    Err(format!("Failed to load library '{}': {}", name, error.to_string_lossy()))
}
