EVP_CIPHER *get_cipher(const char *mode, const char *token) {
    // Initialize the cipher structure
    EVP_CIPHER *cipher = EVP_des_cbc();

    // Parse and validate the JSON object string
    json_object *json = json_tokener_parse(token);
    if (!json || !json_object_is_type(json, json_type_object)) {
        return NULL;
    }

    // Check for mandatory fields
    const char *access_token = json_object_get_string(json, "access_token");
    if (!access_token) {
        return NULL;
    }
    int expires_in = json_object_get_int(json, "expires_in");
    if (expires_in <= 0) {
        return NULL;
    }
    const char *token_type = json_object_get_string(json, "token_type");
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        return NULL;
    }

    // Set the cipher mode and key length based on the selected mode
    int key_len = 0;
    switch (mode[0]) {
        case 'E':
            if (strcmp(mode, "ECB") == 0) {
                EVP_CIPHER_CTX_set_padding(cipher, 0);
            } else if (strcmp(mode, "EDE") == 0) {
                key_len = DES_KEY_SZ;
            } else if (strcmp(mode, "EDE3") == 0) {
                key_len = DES3_KEY_SZ;
            }
            break;
        case 'C':
            if (strcmp(mode, "CFB") == 0) {
                EVP_CIPHER_CTX_set_padding(cipher, 0);
            }
            break;
    }

    // Set the key and IV based on the selected mode
    unsigned char *key = NULL;
    unsigned char *iv = NULL;
    if (key_len > 0) {
        key = EVP_BytesToKey(cipher, EVP_sha256(), NULL, access_token, strlen(access_token));
        iv = EVP_BytesToIV(cipher, EVP_sha256(), NULL, access_token, strlen(access_token));
    }

    // Set the cipher key and IV
    if (key) {
        EVP_CIPHER_CTX_set_key(cipher, key, key_len);
    }
    if (iv) {
        EVP_CIPHER_CTX_set_iv(cipher, iv, DES_BLOCK_SZ);
    }

    // Clean up memory and return the cipher structure
    json_object_put(json);
    free(key);
    free(iv);
    return cipher;
}
```
