#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <json-c/json.h>

// Define the supported cipher modes and key sizes
#define ECB 1
#define EDE 2
#define EDE3 3
#define CFB 4

#define MIN_KEY_SIZE 8
#define MAX_KEY_SIZE 64

// Define the mandatory fields in the OAuth2 access token response JSON object
#define ACCESS_TOKEN "access_token"
#define EXPIRES_IN "expires_in"
#define TOKEN_TYPE "token_type"
#define REFRESH_TOKEN "refresh_token"

// Define the error codes for the function
#define ERROR_MALLOC -1
#define ERROR_JSON_PARSE -2
#define ERROR_INVALID_CIPHER -3
#define ERROR_INVALID_KEY_SIZE -4
#define ERROR_THREAD_SAFETY -5

// Define the function to initialize and return a pointer to an EVP_CIPHER structure for the selected cipher mode
EVP_CIPHER* init_cipher(int mode, int key_size) {
    // Check if the input parameters are valid
    if (mode < ECB || mode > CFB || key_size < MIN_KEY_SIZE || key_size > MAX_KEY_SIZE) {
        return NULL;
    }

    // Initialize the EVP_CIPHER structure with the selected cipher mode and key size
    EVP_CIPHER* cipher = EVP_get_cipherbyname(mode == ECB ? "des_ecb" : (mode == EDE ? "des_ede" : (mode == EDE3 ? "des_ede3" : "des_cfb")));
    if (!cipher) {
        return NULL;
    }
    int ret = EVP_CIPHER_CTX_init(cipher, key_size);
    if (ret != 1) {
        return NULL;
    }

    // Return the initialized cipher structure
    return cipher;
}

// Define the function to parse and validate a JSON object string representing an OAuth2 access token response
int parse_access_token(const char* json, EVP_CIPHER** cipher) {
    // Initialize the error code to 0
    int error = 0;

    // Parse the JSON object string using json-c library
    json_object* root = json_tokener_parse(json);
    if (!root) {
        error = ERROR_JSON_PARSE;
        goto cleanup;
    }

    // Validate the mandatory fields in the JSON object
    json_object* access_token = json_object_object_get(root, ACCESS_TOKEN);
    if (!access_token) {
        error = ERROR_INVALID_JSON;
        goto cleanup;
    }
    json_object* expires_in = json_object_object_get(root, EXPIRES_IN);
    if (!expires_in) {
        error = ERROR_INVALID_JSON;
        goto cleanup;
    }
    json_object* token_type = json_object_object_get(root, TOKEN_TYPE);
    if (!token_type) {
        error = ERROR_INVALID_JSON;
        goto cleanup;
    }

    // Validate the token type and expiration time
    const char* token_type_str = json_object_get_string(token_type);
    if (strcmp(token_type_str, "Bearer") != 0) {
        error = ERROR_INVALID_TOKEN_TYPE;
        goto cleanup;
    }
    int expires_in_int = json_object_get_int(expires_in);
    if (expires_in_int <= 0) {
        error = ERROR_INVALID_EXPIRES_IN;
        goto cleanup;
    }

    // Initialize the cipher structure with the selected mode and key size
    int mode = ECB;
    int key_size = MIN_KEY_SIZE;
    if (json_object_object_get(root, REFRESH_TOKEN)) {
        mode = EDE3;
        key_size = MAX_KEY_SIZE;
    }
    *cipher = init_cipher(mode, key_size);
    if (!*cipher) {
        error = ERROR_INVALID_CIPHER;
        goto cleanup;
    }

cleanup:
    // Clean up the JSON object and return the error code
    json_object_put(root);
    return error;
}
