    int iv_len;
    int key_len;
} aes_cbc_ctx;

// Function to initialize an AES-256-CBC cipher with a given password and hash function
int init_aes_cbc(const char *password, const EVP_MD *hash_func) {
    // Create a new cipher context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -1;
    }

    // Set the key length and IV length to fixed values
    int iv_len = 16;
    int key_len = 32;

    // Derive the key using the specified hash function
    unsigned char key[key_len];
    if (EVP_BytesToKey(hash_func, EVP_aes_256_cbc(), NULL, password, strlen(password), 1, key, NULL) <= 0) {
        return -1;
    }

    // Set the cipher type and mode
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) <= 0) {
        return -1;
    }

    // Generate a secure random initialization vector for each encryption operation
    unsigned char iv[iv_len];
    if (RAND_bytes(iv, iv_len) <= 0) {
        return -1;
    }

    // Enable the cipher and return a pointer to the cipher context
    if (EVP_EncryptEnable(ctx, 1) <= 0) {
        return -1;
    }

    // Clean up and disable the cipher when it is no longer needed
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_aes_cbc(aes_cbc_ctx *ctx) {
    // Disable the cipher and free any allocated resources
    EVP_CIPHER_CTX_free(ctx->ctx);
}
