#include <openssl/sha.h>
#include <string.h>

void init_cipher(const char* filename, const char* password) {
    // Get the file extension and determine the number of digits
    const char* ext = strrchr(filename, '.');
    int num_digits = 0;
    if (ext != NULL) {
        num_digits = strlen(ext) - 1;
    }

    // Determine the file type based on the number of digits
    const char* file_type = "txt";
    if (num_digits == 3) {
        file_type = "pdf";
    } else if (num_digits == 4) {
        file_type = "docx";
    }

    // Initialize the AES-256-CBC cipher using the OpenSSL library
    EVP_CIPHER_CTX* ctx;
    int iv_len, key_len;
    unsigned char iv[16], key[32];
    if (strlen(password) == 0) {
        // Use a random password for the cipher
        RAND_bytes(key, sizeof(key));
    } else {
        // Use the given password for the cipher
        strncpy((char*)key, password, sizeof(key));
    }
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    iv_len = EVP_CIPHER_CTX_iv_length(ctx);
    key_len = EVP_CIPHER_CTX_key_length(ctx);

    // Initialize the cipher in multiple modes based on user input
    if (strcmp(password, "sha1") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    } else if (strcmp(password, "sha256") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    } else if (strcmp(password, "pbkdf2-sha256") == 0) {
        EVP_PBE_CipherInit(ctx, EVP_aes_256_cbc(), NULL, key, iv, 1000);
    } else {
        // Invalid password length or unsupported mode
        return;
    }

    // Set the IV length dynamically based on user input
    if (iv_len > 0) {
        EVP_CIPHER_CTX_set_iv_length(ctx, iv_len);
    } else {
        // Invalid IV length
        return;
    }

    // Set the key length and verify its validity
    if (key_len > 0) {
        EVP_CIPHER_CTX_set_key_length(ctx, key_len);
    } else {
        // Invalid key length
        return;
    }

    // Initialize the cipher contexts simultaneously without memory leaks
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL) != 1) {
        // Memory leak detected
        return;
    }

    // Cleanup and disable the cipher when it is no longer needed
    EVP_CIPHER_CTX_free(ctx);
}
