// Define the record structure
typedef struct {
    int value;
} Record;

// Define the function to dynamically allocate memory for the data structures
void init_data_structures(int num_records, long* offset_values, int* keys, Record** records) {
    // Allocate memory for the offset values array
    *offset_values = (long*)malloc(num_records * sizeof(long));

    // Initialize the offset values to 0
    memset(*offset_values, 0, num_records * sizeof(long));

    // Allocate memory for the keys array
    *keys = (int*)malloc(num_records * sizeof(int));

    // Initialize the keys to 0
    memset(*keys, 0, num_records * sizeof(int));

    // Allocate memory for the records array
    *records = (Record**)malloc(num_records * sizeof(Record*));

    // Initialize each record with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*records)[i] = malloc(sizeof(Record));
        (*records)[i]->value = rand() % 100 + 1; // Generate a random value within the specified range
    }
}

// Define the function to generate unique random values within a specified range
int get_random_value(int min, int max) {
    srand(time(NULL));
    return rand() % (max - min + 1) + min; // Generate a random value within the specified range
}

// Define the function to update the data structures with new records
void update_data_structures(int num_records, long* offset_values, int* keys, Record** records) {
    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));

    // Generate a random value within the specified range for the new record
    new_record->value = get_random_value(1, 100);

    // Add the new record to the end of the records array
    (*records)[num_records - 1] = new_record;

    // Update the offset values and keys arrays
    for (int i = 0; i < num_records; i++) {
        (*offset_values)[i] += sizeof(Record);
        (*keys)[i]++;
    }
}

// Define the function to free the memory allocated by the data structures
void free_data_structures(int num_records, long* offset_values, int* keys, Record** records) {
    // Free the memory for the offset values array
    free(*offset_values);

    // Free the memory for the keys array
    free(*keys);

    // Free the memory for the records array
    for (int i = 0; i < num_records; i++) {
        free((*records)[i]);
    }
    free(*records);
}
