#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <cstdlib>
#include <cstdio>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/ripemd.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <unordered_map>
#include <algorithm>

using namespace std;

class ServiceManager {
public:
    ServiceManager() {}
    ~ServiceManager() {}

    void processStringWithLogging(const string& str, const string& command) {
        // Check if the command is valid
        if (command != "md5" && command != "sha1" && command != "ripemd160") {
            throw invalid_argument("Invalid command");
        }

        // Create a new log entry with the current timestamp and thread ID
        LogEntry logEntry;
        logEntry.timestamp = chrono::system_clock::now();
        logEntry.threadId = this_thread::get_id();

        // Perform the specified operation on the string
        if (command == "md5") {
            MD5(str, strlen(str), logEntry.hash);
        } else if (command == "sha1") {
            SHA1(str, strlen(str), logEntry.hash);
        } else if (command == "ripemd160") {
            RIPEMD160(str, strlen(str), logEntry.hash);
        }

        // Log the hash to both file and console outputs simultaneously
        logHash(logEntry);
    }

private:
    struct LogEntry {
        chrono::system_clock::time_point timestamp;
        thread::id threadId;
        unsigned char hash[EVP_MAX_MD_SIZE];
    };

    // Mutex to protect the log buffer and ensure thread safety
    mutex mtx;

    // Condition variable to signal when the log buffer is full
    condition_variable cv;

    // Vector to store the log entries in chronological order
    vector<LogEntry> logBuffer;

    // Map to keep track of the number of log messages per second
    unordered_map<chrono::system_clock::time_point, int> logCounts;

    // Function to log a hash to both file and console outputs simultaneously
    void logHash(const LogEntry& logEntry) {
        // Acquire the mutex to protect the log buffer and ensure thread safety
        unique_lock<mutex> lock(mtx);

        // Check if the log buffer is full and wait for a signal if necessary
        while (logBuffer.size() >= 50) {
            cv.wait(lock);
        }

        // Add the log entry to the vector and update the map of log counts
        logBuffer.push_back(logEntry);
        logCounts[chrono::system_clock::now()]++;

        // Release the mutex and signal other threads that the log buffer is not full anymore
        lock.unlock();
        cv.notify_all();
    }

    // Function to periodically flush the log buffer to prevent data loss in case of a system crash
    void flushLogBuffer() {
        unique_lock<mutex> lock(mtx);

        // Check if the log buffer is not empty and wait for a signal if necessary
        while (logBuffer.empty()) {
            cv.wait(lock);
        }

        // Flush the log buffer to file and console outputs simultaneously
        ofstream outFile("log.txt", ios::app);
        ostringstream outConsole;
        for (const auto& logEntry : logBuffer) {
            outFile << chrono::system_clock::to_time_t(logEntry.timestamp) << " " << logEntry.threadId << " ";
            for (int i = 0; i < EVP_MAX_MD_SIZE; ++i) {
                outFile << hex << setw(2) << setfill('0') << (int)logEntry.hash[i];
                outConsole << hex << setw(2) << setfill('0') << (int)logEntry.hash[i];
            }
            outFile << endl;
            outConsole << endl;
        }
        outFile.close();

        // Clear the log buffer and update the map of log counts
        logBuffer.clear();
        logCounts.clear();
    }
};
