        cipher = EVP_aes_128_cbc();
    } else if (strcmp(cipher, "AES-256-CBC") == 0) {
        cipher = EVP_aes_256_cbc();
    }
    RAND_bytes(key, key_len / 8);
    if (strcmp(iv_gen_method, "random") == 0) {
        RAND_bytes(iv, 16);
    } else if (strcmp(iv_gen_method, "sequential") == 0) {
        for (int i = 0; i < 16; i++) {
            iv[i] = i;
        }
    }

    // Initialize encryption context and set key and IV
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, cipher, key, iv);

    // Process each filename in the list
    for (int i = 0; i < num_files; i++) {
        char *filename = filenames[i];
        FILE *file = fopen(filename, "r");
        if (!file) {
            printf("Error opening file %s\n", filename);
            continue;
        }

        // Read file contents and encrypt it
        unsigned char buffer[1024];
        int read_bytes;
        while ((read_bytes = fread(buffer, 1, sizeof(buffer), file)) > 0) {
            EVP_EncryptUpdate(ctx, buffer, &read_bytes);
        }

        // Append timestamp and checksum to filename
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char ts[16];
        sprintf(ts, "%04d%02d%02d%02d%02d%02d", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);
        char checksum[33];
        SHA256(buffer, read_bytes, checksum);
        char new_filename[strlen(filename) + 16];
        sprintf(new_filename, "%s.%s.%s", filename, ts, checksum);

        // Write encrypted data to new file
        FILE *outfile = fopen(new_filename, "w");
        if (!outfile) {
            printf("Error opening output file %s\n", new_filename);
            continue;
        }
        fwrite(buffer, 1, read_bytes, outfile);
        fclose(outfile);

        // Clean up resources
        EVP_CIPHER_CTX_free(ctx);
    }
}
