#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the function to dynamically allocate memory for the data structures
void allocate_data_structures(int num_records, long* offset_values, int* keys, Record** records) {
    // Allocate memory for the offset values array
    *offset_values = (long*)malloc(num_records * sizeof(long));
    if (*offset_values == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offset values\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the keys array
    *keys = (int*)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for keys\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the records array
    *records = (Record**)malloc(num_records * sizeof(Record*));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the offset values array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*offset_values)[i] = rand() % RAND_MAX;
    }

    // Initialize the keys array with unique random values within the specified range
    for (int i = 0; i < num_records; i++) {
        int key = rand();
        while (key == (*keys)[i]) {
            key = rand();
        }
        (*keys)[i] = key;
    }

    // Initialize the records array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        int value = rand() % RAND_MAX;
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record\n");
            exit(EXIT_FAILURE);
        }
        record->value = value;
        (*records)[i] = record;
    }
}

// Define the function to read a file, sort its lines, and extract a sequence number from the last line
int read_file_and_extract_sequence_number(char* file_path, int* sequence_number) {
    // Open the file for reading
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open file %s\n", file_path);
        return -1;
    }

    // Read the lines of the file into an array
    char** lines = malloc(sizeof(char*) * 1000);
    int num_lines = 0;
    while (fgets(line, sizeof(line), file) != NULL) {
        lines[num_lines] = strdup(line);
        if (lines[num_lines] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for line\n");
            exit(EXIT_FAILURE);
        }
        num_lines++;
    }

    // Sort the lines of the file in ascending order
    qsort(lines, num_lines, sizeof(char*), compare_strings);

    // Extract the sequence number from the last line
    char* last_line = lines[num_lines - 1];
    int start_index = 0;
    while (last_line[start_index] != ' ') {
        start_index++;
    }
    *sequence_number = atoi(last_line + start_index);

    // Free the memory allocated for the lines array
    for (int i = 0; i < num_lines; i++) {
        free(lines[i]);
    }
    free(lines);

    // Close the file
    fclose(file);

    return 0;
}
