// Define the data structures used in the function
typedef struct event {
    double measurement_values[4];
    char labels[4];
    time_t timestamp;
} event_t;

typedef struct node {
    event_t *event;
    struct node *next;
} node_t;

// Define the configurable parameters for the function
#define RANDOM_TIMESTAMP_RANGE 1000000000 // 1 second in nanoseconds
#define INITIAL_MEMORY_ALLOCATION_SIZE 1024 * 1024 // 1 MB
#define THRESHOLD_VALUE 5.0
#define LOG_FILE_PATH "/path/to/log/file"

// Define the function that dynamically allocates memory for and initializes the data structures
void initialize_data_structures() {
    // Allocate memory for the array of 'double' measurement values, an array of 'char' labels, and an array of 'event' records
    double *measurement_values = malloc(sizeof(double) * 4);
    char *labels = malloc(sizeof(char) * 4);
    event_t *events = malloc(sizeof(event_t));

    // Initialize the arrays and linked list of 'node' pointers
    for (int i = 0; i < 4; i++) {
        measurement_values[i] = 0.0;
        labels[i] = '\0';
        events[i].timestamp = 0;
        events[i].measurement_values[i] = 0.0;
    }

    // Generate unique random timestamps within the specified range for each event
    srand(time(NULL));
    for (int i = 0; i < 4; i++) {
        events[i].timestamp = rand() % RANDOM_TIMESTAMP_RANGE + 1;
    }

    // Allocate memory for the linked list of 'node' pointers and initialize it with the first event record
    node_t *head = malloc(sizeof(node_t));
    head->event = events;
    head->next = NULL;

    // Read the log file, parse its lines into events, and filter out entries based on the threshold value for the measurement fields
    int fd = open(LOG_FILE_PATH, O_RDONLY);
    if (fd == -1) {
        perror("Error opening log file");
        return;
    }

    char buffer[BUFSIZ];
    while (read(fd, buffer, BUFSIZ) > 0) {
        // Parse the line into an event record and filter out entries based on the threshold value for the measurement fields
        event_t *event = parse_line(buffer);
        if (event->measurement_values[0] >= THRESHOLD_VALUE || event->measurement_values[1] >= THRESHOLD_VALUE || event->measurement_values[2] >= THRESHOLD_VALUE || event->measurement_values[3] >= THRESHOLD_VALUE) {
            // Add the filtered event record to the linked list of 'node' pointers
