        } else if (i == 4) {
            event->measurement_values[3] = atof(token);
        } else {
            // Free the memory allocated for the filtered event record and return NULL to indicate an error
            free(event);
            return NULL;
        }
        i++;
        token = strtok(NULL, " ");
    }

    // Return the parsed event record
    return event;
}
