// Define the function to generate unique random timestamps within a specified range
void generate_timestamps(int min, int max) {
    // Generate a random number between the minimum and maximum values
    srand(time(NULL));
    int timestamp = rand() % (max - min + 1) + min;

    // Check if the generated timestamp is already in use
    while (is_timestamp_in_use(timestamp)) {
        timestamp = rand() % (max - min + 1) + min;
    }

    return timestamp;
}

// Define the function to check if a given timestamp is already in use
int is_timestamp_in_use(int timestamp) {
    // Iterate through the linked list of node pointers
    node *current = head;
    while (current != NULL) {
        // Check if the current event's timestamp matches the given timestamp
        if (current->event->timestamp == timestamp) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Define the function to read a log file, parse its lines into events, and filter out entries based on a given threshold value for the measurement fields
void read_log_file(char *log_file_path, int threshold) {
    // Open the log file in read mode
    FILE *log_file = fopen(log_file_path, "r");
    if (log_file == NULL) {
        printf("Error: Failed to open log file %s\n", log_file_path);
        exit(1);
