        if (event->measurement_values[0] >= threshold || event->measurement_values[1] >= threshold) {
            // Add the event to the linked list of node pointers
            node *new_node = malloc(sizeof(node));
            new_node->event = event;
            new_node->next = head;
            head = new_node;
        } else {
            // Free the memory allocated for the event
            free(event);
        }
    }

    // Close the log file
    fclose(log_file);
}

// Define the function to serialize filtered data into a JSON format
void serialize_data(char *json_file_path) {
    // Open the JSON file in write mode
    FILE *json_file = fopen(json_file_path, "w");
    if (json_file == NULL) {
        printf("Error: Failed to open JSON file %s\n", json_file_path);
        exit(1);
    }

