        // Serialize the current event's measurement values and timestamp into a JSON object
        json_object *json_obj = json_object_new();
        json_object_object_add(json_obj, "measurement_values", json_object_new_double(current->event->measurement_values[0]));
        json_object_object_add(json_obj, "timestamp", json_object_new_int(current->event->timestamp));

        // Write the JSON object to the JSON file
        fprintf(json_file, "%s\n", json_object_to_json_string(json_obj));

        current = current->next;
    }

    // Close the JSON file
    fclose(json_file);
}
