import java.util.logging.Logger;

public class IdentifierGenerator {
    private static final Logger LOGGER = Logger.getLogger(IdentifierGenerator.class.getName());
    private static final ConcurrentHashMap<String, String> CACHE = new ConcurrentHashMap<>();
    private static final int CACHE_EXPIRATION_TIME = 30; // days

    public static String generateIdentifier(String input, boolean useSHA256, boolean outputBase64) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be empty");
        }

        // validate input string against a whitelist
        // ...

        String algorithm = useSHA256 ? "SHA-256" : "MD5";
        String outputFormat = outputBase64 ? "base64" : "hexadecimal";

        String identifier = CACHE.get(input);
        if (identifier == null) {
            // generate identifier using the selected algorithm and output format
            try {
                MessageDigest digest = MessageDigest.getInstance(algorithm);
                byte[] hash = digest.digest(input.getBytes());
                identifier = outputFormat.equals("base64") ? Base64.getEncoder().encodeToString(hash) :
                        String.format("%0" + (hash.length * 2) + "x", new BigInteger(1, hash));
            } catch (NoSuchAlgorithmException e) {
                LOGGER.severe("Failed to generate identifier: " + e.getMessage());
                return null;
            }

            // cache the generated identifier for future use
            CACHE.put(input, identifier);
        }

        return identifier;
    }
}
