    double *measurementValues = (double *)malloc(numEvents * sizeof(double));
    char *labels = (char *)malloc(numEvents * sizeof(char));
    struct event *events = (struct event *)malloc(numEvents * sizeof(struct event));
    node *nodes = NULL;

    // Generate unique random timestamps for each event
    srand(time(NULL));
    for (int i = 0; i < numEvents; i++) {
        events[i].timestamp = rand() % thresholdValue + 1;
    }

    // Initialize linked list of nodes
    node *currentNode = NULL;
    for (int i = 0; i < numEvents; i++) {
        currentNode = (node *)malloc(sizeof(node));
        currentNode->data = events[i];
        currentNode->next = nodes;
        nodes = currentNode;
    }

    // Free memory for arrays and linked list
    free(measurementValues);
    free(labels);
    free(events);
    while (nodes != NULL) {
        node *temp = nodes;
        nodes = nodes->next;
        free(temp);
    }
}

// C function to read a log file, parse its lines into events, and filter out entries based on a given threshold value for the measurement fields. Serialize the filtered data into a JSON format.
void processLogFile(char *logFilePath, int thresholdValue) {
    // Open log file and check for errors
    FILE *file = fopen(logFilePath, "r");
    if (file == NULL) {
        printf("Error: unable to open log file\n");
        return;
    }

    // Initialize arrays for measurement values, labels, and events
    double *measurementValues = (double *)malloc(sizeof(double));
    char *labels = (char *)malloc(sizeof(char));
    struct event *events = (struct event *)malloc(sizeof(struct event));

    // Read lines from log file and parse into events
    while (!feof(file)) {
        fgets(line, sizeof(line), file);
        sscanf(line, "%lf %c", &measurementValues[i], &labels[i]);
        if (measurementValues[i] > thresholdValue) {
            events[i].timestamp = measurementValues[i];
            events[i].label = labels[i];
            i++;
        }
    }

    // Close log file and free memory for arrays
    fclose(file);
    free(measurementValues);
    free(labels);

    // Serialize filtered data into JSON format
    json_object *json = json_object_new_array();
    for (int i = 0; i < numEvents; i++) {
        json_object *event = json_object_new_object();
        json_object_object_add(event, "timestamp", json_object_new_int64(events[i].timestamp));
        json_object_object_add(event, "label", json_object_new_string(events[i].label));
        json_object_array_add(json, event);
    }
    printf("%s\n", json_object_to_json_string_ext(json, JSON_C_TO_STRING_PRETTY));
}

