    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), password, NULL);
    ciphers[numCiphers++] = ctx;

    // Add new cipher context to array and initialize with given password and mode
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), password, NULL);
    ciphers[numCiphers++] = ctx;

    // Cleanup and disable cipher contexts when they are no longer needed
