    memset(&addr, 0, sizeof(struct sockaddr_in));
    addr.sin_family = AF_INET;

    // Get the IP address for the given hostname
    int status = inet_pton(AF_INET, hostname, &addr.sin_addr);
    if (status <= 0) {
        printf("Error: Failed to resolve hostname\n");
        return NULL;
    }

    // Return the IP address as a u_char array
    return (u_char*)&addr.sin_addr;
