void insertAfter(vector<string>& list, const string& first, const string& second) {
    // Initialize data structures for multi-threaded access
    vector<int> ints;
    vector<item> items;
    unordered_set<string> names;
    mutex mtx;
    condition_variable cv;

    // Generate random values for the struct item
    default_random_engine engine;
    uniform_int_distribution<int> dist(0, 100);
    for (int i = 0; i < list.size(); ++i) {
        ints.push_back(dist(engine));
        items.push_back({ i, list[i], ACTIVE });
        names.insert(list[i]);
    }

    // Search for the first string argument in the forward list
    auto it = find(list.begin(), list.end(), first);
    if (it != list.end()) {
        // Insert the second string argument immediately after the first one
        int index = it - list.begin();
        list.insert(++it, second);
    } else {
        // Append the second string argument to the end of the list
        list.push_back(second);
    }

    // Deallocate memory for the data structures
    ints.clear();
    items.clear();
    names.clear();

    // Notify any waiting threads that the list has been modified
    cv.notify_all();
}

