#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

// Define the structure to hold the resource pool information
typedef struct {
    int capacity; // The maximum number of resources in the pool
    int size; // The current number of resources in the pool
    int *resources; // An array to store the allocated resources
    pthread_mutex_t mutex; // A mutex to protect concurrent access to the pool
} resource_pool_t;

// Define the function to initialize the resource pool
void init_resource_pool(resource_pool_t *pool, int capacity) {
    pool->capacity = capacity;
    pool->size = 0;
    pool->resources = (int *)malloc(sizeof(int) * capacity);
    pthread_mutex_init(&pool->mutex, NULL);
}

// Define the function to allocate a resource from the pool
int alloc_resource(resource_pool_t *pool) {
    int ret;
    pthread_mutex_lock(&pool->mutex);
    if (pool->size < pool->capacity) {
        ret = pool->resources[pool->size++];
    } else {
        ret = -1; // Return an error code if the pool is full
    }
    pthread_mutex_unlock(&pool->mutex);
    return ret;
}

// Define the function to deallocate a resource from the pool
void dealloc_resource(resource_pool_t *pool, int resource) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->size; i++) {
        if (pool->resources[i] == resource) {
            pool->resources[i] = pool->resources[--pool->size];
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

// Define the function to resize the resource pool
void resize_resource_pool(resource_pool_t *pool, int new_capacity) {
    if (new_capacity > 0 && new_capacity != pool->capacity) {
        int *new_resources = (int *)malloc(sizeof(int) * new_capacity);
        pthread_mutex_lock(&pool->mutex);
        for (int i = 0; i < pool->size; i++) {
            new_resources[i] = pool->resources[i];
        }
        free(pool->resources);
        pool->capacity = new_capacity;
        pool->resources = new_resources;
        pthread_mutex_unlock(&pool->mutex);
    }
}

// Define the function to monitor resource usage and log access events
void monitor_resource_usage(resource_pool_t *pool) {
    // Implement monitoring and logging functionality here
}

int main() {
    // Initialize the resource pool with a capacity of 10 resources
    resource_pool_t pool;
    init_resource_pool(&pool, 10);

    // Allocate resources from the pool
    int resource1 = alloc_resource(&pool);
    int resource2 = alloc_resource(&pool);

    // Deallocate a resource from the pool
    dealloc_resource(&pool, resource1);

    // Resize the resource pool to have a capacity of 5 resources
    resize_resource_pool(&pool, 5);

    // Monitor resource usage and log access events
    monitor_resource_usage(&pool);

    return 0;
}
```
