using System;
using System.Collections.Generic;
using System.Threading;

namespace DynamicRangeGenerator
{
    public class Range
    {
        private float _minValue;
        private float _maxValue;
        private int _seed;

        public Range(float minValue, float maxValue)
        {
            _minValue = minValue;
            _maxValue = maxValue;
        }

        public void SetSeed(int seed)
        {
            _seed = seed;
        }

        public float GetRandomFloat()
        {
            return (float)(_minValue + (_maxValue - _minValue) * new Random(_seed).NextDouble());
        }

        public int GetRandomInt()
        {
            return _minValue + (int)(_maxValue - _minValue) * new Random(_seed).Next(1, 100);
        }

        public override string ToString()
        {
            return $"{_minValue} to {_maxValue}";
        }
    }

    public class DynamicRangeGenerator
    {
        private readonly Dictionary<string, Range> _ranges = new Dictionary<string, Range>();
        private readonly object _lock = new object();

        public void AddRange(string name, float minValue, float maxValue)
        {
            lock (_lock)
            {
                _ranges.Add(name, new Range(minValue, maxValue));
            }
        }

        public void RemoveRange(string name)
        {
            lock (_lock)
            {
                if (_ranges.ContainsKey(name))
                {
                    _ranges.Remove(name);
                }
            }
        }

        public float GetRandomFloat(string rangeName)
        {
            lock (_lock)
            {
                return _ranges[rangeName].GetRandomFloat();
            }
        }

        public int GetRandomInt(string rangeName)
        {
            lock (_lock)
            {
                return _ranges[rangeName].GetRandomInt();
            }
        }

        public void ResetRanges()
        {
            lock (_lock)
            {
                foreach (var range in _ranges.Values)
                {
                    range.SetSeed(0);
                }
            }
        }

        public override string ToString()
        {
            var sb = new StringBuilder();
            lock (_lock)
            {
                foreach (var range in _ranges)
                {
                    sb.AppendLine($"{range.Key}: {range.Value}");
                }
            }
            return sb.ToString();
        }
    }
}
```
