// function to load the configuration file
void load_config(const char* config_file) {
    std::ifstream config(config_file);
    if (!config.is_open()) {
        // throw an error if the configuration file cannot be opened
        throw std::runtime_error("Cannot open configuration file");
    }

    // read the configuration file and enable or disable algorithms as needed
    while (config >> algorithm) {
        if (algorithm == "AES") {
            EVP_add_cipher(EVP_aes_128_cbc(), aes_key_size);
            EVP_add_cipher(EVP_aes_256_cbc(), aes_key_size);
        } else if (algorithm == "Camellia") {
            EVP_add_cipher(EVP_camellia_128_cbc(), camellia_key_size);
            EVP_add_cipher(EVP_camellia_256_cbc(), camellia_key_size);
        } else if (algorithm == "MD5") {
            EVP_add_digest(EVP_md5());
        } else if (algorithm == "SHA") {
            EVP_add_digest(EVP_sha1());
