// Function to initialize and return a pointer to an EVP_CIPHER structure
EVP_CIPHER* init_evp_cipher(int mode, int key_size) {
    // Check if the requested cipher mode is supported
    if (mode != CIPHER_MODE_ECB && mode != CIPHER_MODE_EDE && mode != CIPHER_MODE_EDE3 && mode != CIPHER_MODE_CFB) {
        return NULL;
    }

    // Check if the requested key size is supported
    if (key_size != KEY_SIZE_64 && key_size != KEY_SIZE_128 && key_size != KEY_SIZE_192 && key_size != KEY_SIZE_256) {
        return NULL;
    }

    // Initialize the EVP_CIPHER structure
    EVP_CIPHER* cipher = EVP_get_cipherbyname("des");
    if (cipher == NULL) {
        return NULL;
    }

    // Set the cipher mode and key size
    int ret = EVP_CIPHER_CTX_set_key_length(cipher, key_size);
    if (ret != 1) {
        return NULL;
    }
    ret = EVP_CIPHER_CTX_set_flags(cipher, EVP_CIPH_FLAG_DEFAULT_ASN1);
    if (ret != 1) {
        return NULL;
    }

    // Return the initialized EVP_CIPHER structure
    return cipher;
}

// Function to parse and validate a JSON object string representing an API response
json_object* parse_api_response(const char* json_string) {
    // Initialize the JSON parser
    json_parser* parser = json_parser_new();
    if (parser == NULL) {
        return NULL;
    }

    // Parse the JSON string
    json_object* root = json_parser_load(parser, json_string);
    if (root == NULL) {
        json_parser_free(parser);
        return NULL;
    }

    // Check for the presence of required fields
    json_object* access_token = json_object_get_object(root, ACCESS_TOKEN);
    if (access_token == NULL) {
        json_object_put(root);
        return NULL;
    }
    json_object* expires_in = json_object_get_int(root, EXPIRES_IN);
    if (expires_in == NULL || expires_in->i < 0) {
        json_object_put(root);
        return NULL;
    }
    json_object* token_type = json_object_get_string(root, TOKEN_TYPE);
    if (token_type == NULL || strcmp(token_type->s, "Bearer") != 0) {
        json_object_put(root);
        return NULL;
    }

    // Check for the presence of optional fields
    json_object* refresh_token = json_object_get_object(root, REFRESH_TOKEN);
    if (refresh_token != NULL) {
        json_object_put(root);
        return NULL;
    }

    // Free the JSON parser and return the parsed JSON object
    json_parser_free(parser);
    return root;
}
