#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <limits.h>

// Configuration structure for image conversion settings
typedef struct {
    int quality; // Image quality (0-100)
    int compression_level; // Compression level (0-9)
} convert_config_t;

// Function to convert an input JPEG file to a PDF file using a third-party tool
int convert_image(const char *input_file, const char *output_file, convert_config_t config) {
    // Check if the input and output files are valid
    if (!input_file || !output_file) {
        return -1;
    }

    // Build the command to execute the conversion tool
    char *command = malloc(PATH_MAX);
    snprintf(command, PATH_MAX, "convert %s %s", input_file, output_file);

    // Execute the command and wait for it to finish
    pid_t pid = fork();
    if (pid == 0) {
        execl("/usr/bin/convert", "convert", input_file, output_file, NULL);
        exit(1);
    } else {
        int status;
        waitpid(pid, &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            return -2;
        }
    }

    // Check if the output file was created successfully
    struct stat st;
    if (stat(output_file, &st) == -1) {
        return -3;
    }

    // Clean up memory and return success
    free(command);
    return 0;
}
```
This code defines a function `convert_image` that accepts three parameters: an input JPEG file path, an output PDF file path, and a configuration structure containing settings for image quality and compression level. The function utilizes a third-party command-line tool to perform the conversion, handling any potential errors gracefully.

The function first checks if the input and output files are valid, returning -1 if either is not provided. It then builds the command to execute the conversion tool using `snprintf`, and executes it using `execl`. The `fork` and `waitpid` functions are used to create a new process and wait for it to finish executing the command.

If the output file was not created successfully, the function checks if it exists using `stat`, returning -3 if it does not. Otherwise, the function cleans up memory and returns 0 upon successful completion.

The performance implications of the tool's execution are considered by the use of `fork` and `waitpid`, which allow for efficient handling of large files. The function also supports graceful degradation in case of tool failures, returning -2 if the conversion tool fails to execute or exit with a non-zero status.

The configuration structure allows for future extension to add additional conversion options like orientation or page margins.']

