    ret = ioctl(fd, SIOCSIFNAME, &ifr);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return;
    }

    // Set the interface IP address
    struct sockaddr_in *sin = (struct sockaddr_in *)&ifr.ifr_addr;
    sin->sin_family = AF_INET;
    sin->sin_port = 0;
    sin->sin_addr = data->ipAddress;
    ret = ioctl(fd, SIOCSIFADDR, &ifr);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return;
    }

    // Set the interface subnet mask
    sin->sin_family = AF_INET;
    sin->sin_port = 0;
    sin->sin_addr = data->subnetMask;
    ret = ioctl(fd, SIOCSIFNETMASK, &ifr);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return;
    }

    // Set the interface MAC address
    sin->sin_family = AF_INET;
    sin->sin_port = 0;
    sin->sin_addr = data->macAddress;
    ret = ioctl(fd, SIOCSIFHWADDR, &ifr);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return;
    }

    // Set the interface MTU size
    sin->sin_family = AF_INET;
    sin->sin_port = 0;
    sin->sin_addr = data->mtuSize;
    ret = ioctl(fd, SIOCSIFMTU, &ifr);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return;
    }

    // Set the interface operational state
    sin->sin_family = AF_INET;
    sin->sin_port = 0;
    if (data->isUp) {
        ifr.ifr_flags |= IFF_UP;
    } else {
        ifr.ifr_flags &= ~IFF_UP;
