    ctx->rsa_key = RSA_new();
    if (ctx->rsa_key == NULL) {
        return MEMORY_ERROR;
    }

    BIGNUM *bn = BN_new();
    if (bn == NULL) {
        return MEMORY_ERROR;
    }

    BN_set_word(bn, RSA_F4);
    if (!RSA_generate_key_ex(ctx->rsa_key, params->rsa_key_length, bn, NULL)) {
        return FAILURE;
    }

    // Free the memory allocated for the BIGNUM object
    BN_free(bn);

    return SUCCESS;
}

// Define the function to clean up the encryption context
int cleanup_encryption_context(EncryptionContext *ctx) {
    if (ctx->aes_ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->aes_ctx);
    }

    if (ctx->md_ctx != NULL) {
        EVP_MD_CTX_destroy(ctx->md_ctx);
