        RSA_free(ctx->rsa_key);
    }

    return SUCCESS;
}

// Define the function to encrypt data using AES-CBC and SHA-256
int aes_cbc_sha256_encrypt(EncryptionContext *ctx, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    // Encrypt the plaintext using AES-CBC
    if (EVP_EncryptUpdate(ctx->aes_ctx, ciphertext, &plaintext_len, plaintext, plaintext_len) != 1) {
        return FAILURE;
    }

    // Generate a secure random initialization vector for AES-CBC
    unsigned char iv[MAX_KEY_SIZE / 8];
    RAND_bytes(iv, sizeof(iv));

    // Encrypt the plaintext using SHA-256
    if (EVP_DigestUpdate(ctx->md_ctx, ciphertext, plaintext_len) != 1) {
        return FAILURE;
    }

    unsigned char hash[MAX_HASH_SIZE];
    int hash_len = EVP_MD_CTX_size(ctx->md_ctx);
    if (EVP_DigestFinal_ex(ctx->md_ctx, hash, &hash_len) != 1) {
        return FAILURE;
    }

    // Encrypt the plaintext using RSA-OAEP with SHA-256
    int ciphertext_len = RSA_size(ctx->rsa_key);
    if (RSA_public_encrypt(ciphertext_len, ciphertext, ciphertext, ctx->rsa_key, RSA_PKCS1_OAEP_PADDING) != 1) {
        return FAILURE;
    }

    return SUCCESS;
}

// Define the function to decrypt data using AES-CBC and SHA-256
int aes_cbc_sha256_decrypt(EncryptionContext *ctx, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    // Decrypt the ciphertext using RSA-OAEP with SHA-256
    int plaintext_len = RSA_size(ctx->rsa_key);
    if (RSA_private_decrypt(ciphertext_len, ciphertext, plaintext, ctx->rsa_key, RSA_PKCS1_OAEP_PADDING) != 1) {
        return FAILURE;
    }

    // Decrypt the ciphertext using SHA-256
    unsigned char hash[MAX_HASH_SIZE];
    int hash_len = EVP_MD_CTX_size(ctx->md_ctx);
    if (EVP_DigestFinal_ex(ctx->md_ctx, hash, &hash_len) != 1) {
        return FAILURE;
    }

    // Decrypt the ciphertext using AES-CBC
    if (EVP_DecryptUpdate(ctx->aes_ctx, plaintext, &plaintext_len, plaintext, plaintext_len) != 1) {
        return FAILURE;
    }

    return SUCCESS;
}

// Define the function to generate a secure random initialization vector for AES-CBC
int generate_iv(unsigned char *iv, int iv_len) {
    if (RAND_bytes(iv, iv_len) != 1) {
