    unsigned char final_hash[EVP_MAX_MD_SIZE];
    unsigned int final_hash_len = EVP_MAX_MD_SIZE;
    if (EVP_DigestFinal_ex(ctx->md_ctx, final_hash, &final_hash_len) != 1) {
