#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/ripemd.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <cstdarg>

class ServiceManager {
public:
    ServiceManager() {}
    ~ServiceManager() {}

    void processStringWithLogging(const std::string& str, const std::string& command) {
        // Check if the command is valid
        if (command != "md5" && command != "sha1" && command != "ripemd160") {
            throw std::invalid_argument("Invalid command");
        }

        // Create a new log entry with the current timestamp and thread ID
        LogEntry logEntry;
        logEntry.timestamp = std::chrono::system_clock::now();
        logEntry.threadId = std::this_thread::get_id();

        // Perform the specified operation on the string
        if (command == "md5") {
            MD5(str, strlen(str), logEntry.hash);
        } else if (command == "sha1") {
            SHA1(str, strlen(str), logEntry.hash);
        } else if (command == "ripemd160") {
            RIPEMD160(str, strlen(str), logEntry.hash);
        }

        // Log the hash to both file and console outputs simultaneously
        std::lock_guard<std::mutex> lock(logMutex);
        logEntries.push_back(logEntry);
        if (logEntries.size() >= 50) {
            flushLogBuffer();
        }
    }

private:
    struct LogEntry {
        std::chrono::system_clock::time_point timestamp;
        std::thread::id threadId;
        unsigned char hash[EVP_MAX_MD_SIZE];
    };

    // Mutex to protect the log buffer and ensure thread safety
    std::mutex logMutex;

    // Vector of log entries to be flushed to file and console outputs
    std::vector<LogEntry> logEntries;

    // Flush the log buffer periodically to prevent data loss in case of a system crash
    void flushLogBuffer() {
        std::lock_guard<std::mutex> lock(logMutex);
        for (const auto& entry : logEntries) {
            std::cout << "[" << entry.timestamp << "] Thread " << entry.threadId << ": ";
            for (int i = 0; i < EVP_MAX_MD_SIZE; ++i) {
                std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)entry.hash[i];
            }
            std::cout << std::endl;
        }
        logEntries.clear();
    }
};
