import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class GenerateMD5Hash {
    private static final int DEFAULT_THRESHOLD = 100; // default threshold value for filtering measurement fields
    private static final String LOG_FILE_PATH = "path/to/log/file"; // default log file path
    private static final int INITIAL_MEMORY_ALLOCATION_SIZE = 1024 * 1024; // initial memory allocation size for the hash map
    private static final String JSON_FORMAT = "{\"measurements\": [%s]}"; // JSON format for serializing filtered data

    public static void main(String[] args) {
        try {
            // parse command-line arguments
            int threshold = DEFAULT_THRESHOLD;
            String logFilePath = LOG_FILE_PATH;
            if (args.length > 0) {
                threshold = Integer.parseInt(args[0]);
            }
            if (args.length > 1) {
                logFilePath = args[1];
            }

            // read log file and generate MD5 hash for each line
            List<String> lines = Files.readAllLines(new File(logFilePath).toPath());
            ConcurrentHashMap<String, Integer> hashMap = new ConcurrentHashMap<>(INITIAL_MEMORY_ALLOCATION_SIZE);
            for (String line : lines) {
                String md5Hash = generateMD5Hash(line);
                if (md5Hash != null) {
                    hashMap.putIfAbsent(md5Hash, 1);
                }
            }

            // filter measurement fields and serialize filtered data into JSON format
            List<String> measurements = new ArrayList<>();
            for (String md5Hash : hashMap.keySet()) {
                if (hashMap.get(md5Hash) > threshold) {
                    measurements.add(md5Hash);
                }
            }
            String jsonData = String.format(JSON_FORMAT, String.join(",", measurements));

            // print JSON data to console
            System.out.println(jsonData);
        } catch (IOException | NoSuchAlgorithmException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    private static String generateMD5Hash(String line) throws NoSuchAlgorithmException, IOException {
        // extract measurement fields from log entry
        Pattern pattern = Pattern.compile("\\d+\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)");
        Matcher matcher = pattern.matcher(line);
        if (matcher.find()) {
            String measurementFields = matcher.group();
            // generate MD5 hash for measurement fields
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(measurementFields.getBytes());
            return bytesToHexString(bytes);
        } else {
            return null;
        }
    }

    private static String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
