// Define the record structure
typedef struct {
    int value;
} record;

// Define the function to dynamically allocate and initialize interconnected data structures
void init_data_structures(int range, int initial_size, char* file_path) {
    // Initialize the offset array
    long* offsets = (long*)malloc(initial_size * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the key array
    int* keys = (int*)malloc(initial_size * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Initialize the record array
    record* records = (record*)malloc(initial_size * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Generate unique random values within the specified range for each record
    srand(time(NULL));
    for (int i = 0; i < initial_size; i++) {
        records[i].value = rand() % range + 1;
    }

    // Initialize the offset array with the starting position of each record in the file
    FILE* file = fopen(file_path, "r");
    if (!file) {
        printf("Error: Failed to open file\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Read the lines of the file and extract the sequence number from the last line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Extract the sequence number from the last line
        int seq_num = atoi(strrchr(line, ' ') + 1);
        offsets[seq_num] = ftell(file) - len;
    }

    // Sort the offset array in ascending order
    qsort(offsets, initial_size, sizeof(long), compare_longs);

    // Generate unique random keys for each record
    for (int i = 0; i < initial_size; i++) {
        keys[i] = rand() % range + 1;
    }

    // Initialize the lock for thread-safe access to the data structures
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Return the initialized data structures and lock
    return offsets, keys, records, &lock;
}

// Define a comparison function for sorting long integers in ascending order
int compare_longs(const void* a, const void* b) {
    long x = *(const long*)a;
    long y = *(const long*)b;
    return (x < y) ? -1 : (x > y);
}
