        (*rec_arr)[i].key = rand() % 1000;
        (*ts_arr)[i] = time(NULL);
    }
}

// Define the function to handle memory deallocation
void free_arrays(long* offset_arr, int* key_arr, Record* rec_arr, unsigned long* ts_arr) {
    // Free the memory allocated for the arrays
