// Define the lock for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the arrays and populate with random values
void init_arrays() {
    // Allocate memory for each array
    records[0] = (Record *)malloc(sizeof(Record) * 5);
    records[1] = (int *)malloc(sizeof(int) * 5);
    records[2] = (Record *)malloc(sizeof(Record) * 5);
    records[3] = (unsigned long *)malloc(sizeof(unsigned long) * 5);
    records[4] = (float *)malloc(sizeof(float) * 5);

    // Initialize each array with unique random values within specified ranges
    for (int i = 0; i < 5; i++) {
        srand((unsigned int)time(NULL));
        records[i][0].key = rand() % 1000 + 1;
        records[i][1].weight = (float)(rand() % 1000) / 10.0f;
        records[i][2].timestamp = time(NULL);
    }
}

// Function to handle memory deallocation and cleanup of unused data
void cleanup_arrays() {
    // Free the memory allocated for each array
    free(records[0]);
    free(records[1]);
    free(records[2]);
    free(records[3]);
    free(records[4]);
}

// Function to insert a new record into the data structures
void insert_record(int key, float weight) {
    // Acquire the lock for concurrent access
    pthread_mutex_lock(&lock);

    // Allocate memory for the new record
    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->key = key;
    new_record->weight = weight;
    new_record->timestamp = time(NULL);

    // Insert the new record into the appropriate array
    records[0][records[1]++] = *new_record;
    records[2][records[3]++] = *new_record;
    records[4][records[5]++] = weight;

    // Release the lock for concurrent access
    pthread_mutex_unlock(&lock);
}

// Function to handle memory deallocation and cleanup of unused data
void delete_record(int key) {
    // Acquire the lock for concurrent access
    pthread_mutex_lock(&lock);

    // Find the record with the specified key
    int index = -1;
    for (int i = 0; i < records[1]; i++) {
        if (records[0][i].key == key) {
            index = i;
            break;
        }
    }

    // If the record is found, delete it from the appropriate array
    if (index != -1) {
        records[0][index] = records[0][records[1] - 1];
        records[1]--;
        records[2][index] = records[2][records[3] - 1];
        records[3]--;
        records[4][index] = records[4][records[5] - 1];
        records[5]--;
    }

    // Release the lock for concurrent access
    pthread_mutex_unlock(&lock);
}

// Function to handle memory deallocation and cleanup of unused data
void periodic_cleanup() {
    // Acquire the lock for concurrent access
    pthread_mutex_lock(&lock);

    // Iterate through each array and delete any records that have not been accessed in a specified time period
    for (int i = 0; i < 5; i++) {
        int index = -1;
        for (int j = 0; j < records[i]; j++) {
            if (records[i][j].timestamp < time(NULL) - 3600) { // Delete any record that has not been accessed in the last hour
                index = j;
                break;
            }
        }
        if (index != -1) {
            records[i][index] = records[i][records[i] - 1];
            records[i]--;
        }
    }

    // Release the lock for concurrent access
    pthread_mutex_unlock(&lock);
}

