// Define the function to initialize the memory for the arrays
void* init_memory(int num_records, int range_min, int range_max) {
    // Calculate the size of the offset and key arrays
    size_t offset_size = sizeof(offset_t) * num_records;
    size_t key_size = sizeof(key_t) * num_records;

    // Allocate memory for the offset and key arrays
    void* offset_ptr = malloc(offset_size);
    void* key_ptr = malloc(key_size);

    // Check if allocation failed
    if (offset_ptr == NULL || key_ptr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offset and key arrays\n");
        return NULL;
    }

    // Initialize the offset and key arrays with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        ((offset_t*)offset_ptr)[i].value = rand() % (range_max - range_min + 1) + range_min;
        ((key_t*)key_ptr)[i].key = rand() % (range_max - range_min + 1) + range_min;
    }

    // Allocate memory for the record array
    size_t record_size = sizeof(record_t) * num_records;
    void* record_ptr = malloc(record_size);

    // Check if allocation failed
    if (record_ptr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        free(offset_ptr);
        free(key_ptr);
        return NULL;
    }

    // Initialize the record array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        ((record_t*)record_ptr)[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    // Return a pointer to the first element of the record array
    return record_ptr;
}
