    // Initialize a variable to store the largest value
    int largest = INT_MIN;

    // Iterate through the auxiliary array and compare each element with the current largest value
    for (int i = 0; i < size; i++) {
        if (auxiliary_array[i] > largest) {
            largest = auxiliary_array[i];
        }
    }

    // Print the largest value
    printf("Largest integer: %d\n", largest);
}

