    // Initialize a variable to store the sum
    int sum = 0;

    // Iterate through the auxiliary array and add each element to the sum
    for (int i = 0; i < size; i++) {
        sum += auxiliary_array[i];
    }

    // Print the sum
    printf("Sum of integers: %d\n", sum);
}

// Function to free memory allocated by the function
