// Define the index node structure
typedef struct index_node {
    char* key;
    int id;
    struct index_node* next;
} index_node;

// Define the record structure
typedef struct record {
    int value;
} record;

// Define the memory pool configuration
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
#define MEMORY_POOL_ALIGNMENT 64 // 64-byte alignment

// Function to initialize the database indexing system
void* init_database(int record_count, int key_length, int value_range) {
    // Allocate memory for the index nodes and records
    size_t node_size = sizeof(index_node);
    size_t record_size = sizeof(record);
    size_t total_memory = (node_size + record_size) * record_count;
    void* memory_pool = malloc(total_memory);
    if (!memory_pool) {
        fprintf(stderr, "Error: Failed to allocate memory pool\n");
        return NULL;
    }

    // Initialize the index nodes and records
    index_node* index_nodes = (index_node*)memory_pool;
    record* records = (record*)(memory_pool + node_size * record_count);
    for (int i = 0; i < record_count; i++) {
        // Generate a random value within the specified range
        int value = rand() % value_range + 1;
        records[i].value = value;

        // Allocate memory for the index key and set its value
        char* key = malloc(key_length);
        if (!key) {
            fprintf(stderr, "Error: Failed to allocate memory for index key\n");
            return NULL;
        }
        snprintf(key, key_length, "%d", i);
        index_nodes[i].key = key;

        // Set the node ID and next pointer
        index_nodes[i].id = i;
        index_nodes[i].next = (i == record_count - 1) ? NULL : &index_nodes[i + 1];
    }

    return records;
}
