#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <limits.h>
#include <errno.h>

// Define the maximum size of the input and output files
#define MAX_FILE_SIZE 1024 * 1024 * 10 // 10 MB

// Define the maximum number of records to be processed
#define MAX_RECORDS 100000

// Define the maximum size of a record in bytes
#define MAX_RECORD_SIZE 1024

// Define the maximum size of an offset in bytes
#define MAX_OFFSET_SIZE sizeof(long)

// Define the maximum size of a key in bytes
#define MAX_KEY_SIZE sizeof(int)

// Define the maximum size of a value in bytes
#define MAX_VALUE_SIZE 1024

// Define the maximum size of an authentication token in bytes
#define MAX_TOKEN_SIZE 64

// Define the maximum number of attempts to generate a unique token
#define MAX_ATTEMPTS 10

// Define the minimum and maximum values for the random value
#define MIN_RANDOM_VALUE 0
#define MAX_RANDOM_VALUE INT_MAX

typedef struct {
    int key;
    char value[20];
    float value_float;
} record;

int main(int argc, char *argv[]) {
    // Check the number of command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input file> <output file> <transformation rules>\n", argv[0]);
        return 1;
    }

    // Get the input and output file names from the command-line arguments
    char *input_file = argv[1];
    char *output_file = argv[2];
    char *transformation_rules = argv[3];

    // Open the input and output files in binary mode
    FILE *input = fopen(input_file, "rb");
    if (input == NULL) {
        perror("fopen");
        return 1;
    }
    FILE *output = fopen(output_file, "wb");
    if (output == NULL) {
        perror("fopen");
        fclose(input);
        return 1;
    }

    // Allocate memory for the input and output files
    size_t file_size = MAX_FILE_SIZE;
    char *input_buffer = malloc(file_size);
    if (input_buffer == NULL) {
        perror("malloc");
        fclose(input);
        fclose(output);
        return 1;
    }
    char *output_buffer = malloc(file_size);
    if (output_buffer == NULL) {
        perror("malloc");
        free(input_buffer);
        fclose(input);
        fclose(output);
        return 1;
    }

    // Read the input file into memory
    size_t bytes_read = fread(input_buffer, 1, file_size, input);
    if (bytes_read == 0) {
        perror("fread");
        free(input_buffer);
        free(output_buffer);
        fclose(input);
        fclose(output);
        return 1;
    }

    // Parse the transformation rules
    int num_rules = 0;
    char **rule_strings = NULL;
    if (parse_transformation_rules(transformation_rules, &num_rules, &rule_strings) != 0) {
        fprintf(stderr, "Error parsing transformation rules\n");
        free(input_buffer);
        free(output_buffer);
        fclose(input);
        fclose(output);
        return 1;
    }

    // Allocate memory for the records
    size_t num_records = bytes_read / MAX_RECORD_SIZE;
    record *records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        perror("malloc");
        free(input_buffer);
        free(output_buffer);
        fclose(input);
        fclose(output);
        return 1;
    }

    // Read the records from the input buffer and apply the transformation rules
    size_t num_applied = 0;
    for (size_t i = 0; i < num_records; i++) {
        record *record = &records[i];
        char *input_ptr = input_buffer + (i * MAX_RECORD_SIZE);
        if (parse_record(input_ptr, record) != 0) {
            fprintf(stderr, "Error parsing record %zu\n", i);
            free(records);
            free(rule_strings);
            free(input_buffer);
            free(output_buffer);
            fclose(input);
            fclose(output);
            return 1;
        }
        for (int j = 0; j < num_rules; j++) {
            char *rule = rule_strings[j];
            if (strcmp(rule, "random") == 0) {
                record->key = generate_random_value();
            } else if (strcmp(rule, "sort") == 0) {
                qsort(records, num_applied, sizeof(record), compare_records);
            }
        }
    }

    // Write the output file
    size_t bytes_written = fwrite(output_buffer, 1, file_size, output);
    if (bytes_written == 0) {
        perror("fwrite");
        free(records);
        free(rule_strings);
        free(input_buffer);
        free(output_buffer);
        fclose(input);
        fclose(output);
        return 1;
    }

    // Free memory and close files
    free(records);
    free(rule_strings);
    free(input_buffer);
    free(output_buffer);
    fclose(input);
    fclose(output);

    return 0;
}

int parse_transformation_rules(char *transformation_rules, int *num_rules, char ***rule_strings) {
    // Split the transformation rules into individual strings
    char **tokens = strtok(transformation_rules, ",");
    if (tokens == NULL) {
        return 1;
    }
    *num_rules = 0;
    while (tokens != NULL) {
        (*num_rules)++;
        tokens = strtok(NULL, ",");
    }
    *rule_strings = malloc((*num_rules) * sizeof(char *));
    if (*rule_strings == NULL) {
        return 1;
    }
    // Copy the individual strings into an array of pointers
    tokens = strtok(transformation_rules, ",");
    for (int i = 0; i < *num_rules; i++) {
        size_t len = strlen(tokens);
        (*rule_strings)[i] = malloc(len + 1);
        if ((*rule_strings)[i] == NULL) {
            return 1;
        }
        memcpy((*rule_strings)[i], tokens, len + 1);
        tokens = strtok(NULL, ",");
    }
    return 0;
}

int parse_record(char *input_ptr, record *record) {
    // Read the key and value from the input buffer
    int key = 0;
    char value[20];
    float value_float = 0.0f;
    if (sscanf(input_ptr, "%d %s %f", &key, value, &value_float) != 3) {
        return 1;
    }
    // Set the record fields
    record->key = key;
    strcpy(record->value, value);
    record->value_float = value_float;
    return 0;
}

int generate_random_value() {
    int random_value = MIN_RANDOM_VALUE + (rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE));
    return random_value;
}

int compare_records(const void *a, const void *b) {
    record *record_a = (record *) a;
    record *record_b = (record *) b;
    if (record_a->key < record_b->key) {
        return -1;
    } else if (record_a->key > record_b->key) {
        return 1;
    } else {
        return 0;
    }
}
