// Define structure for record
typedef struct {
    int key;
} Record;

// Define function to read input from standard input and store in array
void readInput(int** arr, int* size) {
    // Initialize variables
    int i = 0;
    int max_size = 100000;
    *arr = (int*)malloc(max_size * sizeof(int));

    // Read input from standard input and store in array
    while (i < max_size && scanf("%d", &(*arr)[i]) == 1) {
        i++;
    }

    // Set size of array to number of elements read
    *size = i;
}

// Define function to find largest integer in array
int findLargest(int* arr, int size) {
    // Initialize variables
    int largest = INT_MIN;

    // Loop through array and find largest integer
    for (int i = 0; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    return largest;
}

// Define function to calculate sum of integers in array
int calculateSum(int* arr, int size) {
    // Initialize variables
    int sum = 0;

    // Loop through array and calculate sum
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }

    return sum;
}

// Define function to log operation details to file
void logOperation(char* filename, int start_time, int end_time, int largest, int smallest, int sum) {
    // Open file for writing
    FILE* fp = fopen(filename, "a");

    // Write log entry to file
    fprintf(fp, "%d %d %d %d %d\n", start_time, end_time, largest, smallest, sum);

    // Close file
    fclose(fp);
}

// Define function to handle large input sizes efficiently
void processInput(int* arr, int size) {
    // Initialize variables
    int chunk_size = 1000;
    int num_chunks = (size + chunk_size - 1) / chunk_size;
    int i = 0;

    // Loop through chunks of input and process each chunk separately
    for (int j = 0; j < num_chunks; j++) {
        // Calculate start and end indices for current chunk
        int start = j * chunk_size;
        int end = (j + 1) * chunk_size - 1;

        // Process current chunk of input
        processChunk(arr, size, start, end);
    }
}

// Define function to process a single chunk of input
void processChunk(int* arr, int size, int start, int end) {
    // Initialize variables
    int largest = INT_MIN;
    int smallest = INT_MAX;
    int sum = 0;

    // Loop through elements in current chunk and calculate statistics
    for (int i = start; i <= end; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
        if (arr[i] < smallest) {
            smallest = arr[i];
        }
        sum += arr[i];
    }

    // Log operation details to file
    logOperation("operation_log.txt", start, end, largest, smallest, sum);
}

// Define function to allocate and initialize arrays for records and keys
void allocateArrays(Record** records, int* record_size, int** keys, int* key_size) {
    // Initialize variables
    int max_record_size = 10000;
    *records = (Record*)malloc(max_record_size * sizeof(Record));
    *key_size = max_record_size;

    // Loop through records and initialize keys
    for (int i = 0; i < max_record_size; i++) {
        (*records)[i].key = rand() % 100 + 1;
    }
}

// Define function to free allocated memory
void freeMemory(Record* records, int record_size, int* keys, int key_size) {
    // Free allocated memory for arrays
    free(records);
    free(keys);
}

int main() {
    // Initialize variables
    Record* records = NULL;
    int record_size = 0;
    int* keys = NULL;
    int key_size = 0;
    int largest = INT_MIN;
    int smallest = INT_MAX;
    int sum = 0;
    int i = 0;

    // Allocate and initialize arrays for records and keys
    allocateArrays(&records, &record_size, &keys, &key_size);

    // Read input from standard input and store in array
    readInput(&keys, &key_size);

    // Process input using dedicated helper function
    processInput(keys, key_size);

    // Find largest integer in array and calculate sum of all integers
    for (i = 0; i < key_size; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
        sum += keys[i];
    }

    // Log operation details to file
    logOperation("operation_log.txt", 0, 0, largest, smallest, sum);

    // Free allocated memory
    freeMemory(records, record_size, keys, key_size);

    return 0;
}
