// Define the index node structure
typedef struct {
    char* key;
    int id;
    struct index_node* next;
} index_node;

// Define the record structure
typedef struct {
    int value;
} record;

// Function to initialize the database indexing system
index_node* init_database(int num_records, int range_min, int range_max) {
    // Allocate memory for the index nodes and records
    index_node* index = (index_node*)malloc(sizeof(index_node) * num_records);
    record* records = (record*)malloc(sizeof(record) * num_records);

    // Initialize the index nodes and records
    for (int i = 0; i < num_records; i++) {
        index[i].key = malloc(16);
        sprintf(index[i].key, "%d", i);
        index[i].id = i;
        index[i].next = NULL;
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    // Return the pointer to the first element of the record array
    return records;
}

// Function to release memory allocated for the index nodes and records
void free_database(index_node* index, int num_records) {
    // Release memory for the index nodes and records
    for (int i = 0; i < num_records; i++) {
        free(index[i].key);
    }
    free(index);
    free(records);
}
