// Define the struct for storing items
typedef struct {
    int i;
    double d;
} item_t;

// Define the function to allocate memory and initialize arrays
void init_arrays(double **d, char ***s, item_t **i) {
    // Allocate memory for the double array
    *d = (double *)malloc(5000 * sizeof(double));
    if (*d == NULL) {
        printf("Error: Failed to allocate memory for double array\n");
        exit(1);
    }

    // Initialize the double array with random values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < 5000; i++) {
        (*d)[i] = rand() % 100 + 1.0;
    }

    // Allocate memory for the char array
    *s = (char **)malloc(5000 * sizeof(char *));
    if (*s == NULL) {
        printf("Error: Failed to allocate memory for char array\n");
        exit(1);
    }

    // Initialize the char array with predefined string literals
    const char *str[5] = {"apple", "banana", "cherry", "date", "elderberry"};
    for (int i = 0; i < 5000; i++) {
        (*s)[i] = str[rand() % 5];
    }

    // Allocate memory for the item array
    *i = (item_t *)malloc(5000 * sizeof(item_t));
    if (*i == NULL) {
        printf("Error: Failed to allocate memory for item array\n");
        exit(1);
    }

    // Initialize the item array with randomly generated int and double values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < 5000; i++) {
        (*i)[i].i = rand() % 100 + 1;
        (*i)[i].d = rand() % 100 + 1.0;
    }
}

// Define the function to read input from standard input and store in an auxiliary array
void read_input(item_t **aux) {
    // Allocate memory for the auxiliary array
    *aux = (item_t *)malloc(50000 * sizeof(item_t));
    if (*aux == NULL) {
        printf("Error: Failed to allocate memory for auxiliary array\n");
        exit(1);
    }

    // Read input from standard input and store in the auxiliary array
    int i = 0;
    while (i < 50000 && scanf("%d %lf", &(*aux)[i].i, &(*aux)[i].d) == 2) {
        i++;
    }
}

// Define the function to identify and print the maximum value for both integers and floating-point numbers from the input list
void find_max(item_t *aux, int n) {
    // Initialize variables to store the maximum values
    int max_int = INT_MIN;
    double max_float = -DBL_MAX;

    // Iterate through the auxiliary array and update the maximum values
    for (int i = 0; i < n; i++) {
        if (aux[i].i > max_int) {
            max_int = aux[i].i;
        }
        if (aux[i].d > max_float) {
            max_float = aux[i].d;
        }
    }

    // Print the maximum values
    printf("Maximum integer value: %d\n", max_int);
    printf("Maximum floating-point value: %lf\n", max_float);
}

// Define the function to calculate the average of all floating-point numbers read from standard input and print this average as well
void calc_avg(item_t *aux, int n) {
    // Initialize variables to store the sum and count of floating-point values
    double sum = 0.0;
    int count = 0;

    // Iterate through the auxiliary array and update the sum and count
    for (int i = 0; i < n; i++) {
        if (aux[i].d != -DBL_MAX) {
            sum += aux[i].d;
            count++;
        }
    }

    // Calculate the average and print it
    double avg = sum / count;
    printf("Average of floating-point values: %lf\n", avg);
}

// Define the function to free memory allocated for arrays
void free_arrays(double *d, char **s, item_t *i) {
    // Free memory for the double array
    free(d);

    // Free memory for the char array
    free(s);

    // Free memory for the item array
    free(i);
}

// Define the function to handle large input sizes efficiently by breaking down the processing into smaller chunks if necessary
void process_input(item_t *aux, int n) {
    // Calculate the chunk size based on system resources and current workload
    int chunk_size = 100;

    // Iterate through the auxiliary array in chunks
    for (int i = 0; i < n; i += chunk_size) {
        // Process each chunk concurrently using multiple threads
        pthread_t thread[chunk_size];
        for (int j = 0; j < chunk_size && i + j < n; j++) {
            pthread_create(&thread[j], NULL, process_chunk, &aux[i + j]);
        }

        // Wait for all threads to complete
        for (int j = 0; j < chunk_size; j++) {
            pthread_join(thread[j], NULL);
        }
    }
}

// Define the function to handle concurrent execution by multiple threads, ensuring thread safety when accessing shared resources
void process_chunk(item_t *aux) {
    // Initialize variables to store the maximum values for integers and floating-point numbers in this chunk
    int max_int = INT_MIN;
    double max_float = -DBL_MAX;

    // Iterate through the auxiliary array in this chunk and update the maximum values
    for (int i = 0; i < chunk_size; i++) {
        if (aux[i].i > max_int) {
            max_int = aux[i].i;
        }
        if (aux[i].d > max_float) {
            max_float = aux[i].d;
        }
    }

    // Print the maximum values for this chunk
    printf("Maximum integer value in chunk: %d\n", max_int);
    printf("Maximum floating-point value in chunk: %lf\n", max_float);
}

// Define the function to provide a feature to log detailed information about the operation, including memory usage and processing time, to a file named "operation_log.txt"
void log_operation(item_t *aux, int n) {
    // Open the log file in append mode
    FILE *f = fopen("operation_log.txt", "a");
    if (f == NULL) {
        printf("Error: Failed to open log file\n");
        exit(1);
    }

    // Log the start time of the operation
    time_t start_time = time(NULL);
    fprintf(f, "Start time: %s", ctime(&start_time));

    // Process the input in chunks and log the maximum values for integers and floating-point numbers in each chunk
    process_input(aux, n);

    // Log the end time of the operation
    time_t end_time = time(NULL);
    fprintf(f, "End time: %s", ctime(&end_time));

    // Close the log file
    fclose(f);
}

int main() {
    // Declare and initialize variables for the arrays and auxiliary array
    double *d;
    char **s;
    item_t *i;
    init_arrays(&d, &s, &i);

    // Read input from standard input and store in an auxiliary array
    item_t *aux;
    read_input(&aux);

    // Find the maximum value for both integers and floating-point numbers from the input list
    find_max(aux, 50000);

    // Calculate the average of all floating-point numbers read from standard input and print this average as well
    calc_avg(aux, 50000);

    // Free memory allocated for arrays
    free_arrays(d, s, i);

    // Log detailed information about the operation to a file named "operation_log.txt"
    log_operation(aux, 50000);

    return 0;
}
