// Define the function to manage memory allocation and initialization for the database indexing system
void init_index(int num_records, int min_value, int max_value) {
    // Allocate memory for the array of index nodes
    index_node* index = (index_node*)malloc(sizeof(index_node) * num_records);
    assert(index != NULL);

    // Initialize each index node with a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        index[i].key = malloc(sizeof(char) * 16);
        sprintf(index[i].key, "%d", rand() % (max_value - min_value + 1) + min_value);
        index[i].id = i;
        index[i].next = NULL;
    }

    // Allocate memory for the array of records
    record* records = (record*)malloc(sizeof(record) * num_records);
    assert(records != NULL);

    // Initialize each record with a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Return the initialized index and record structures
    return index, records;
}
