#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>

// Define struct for item
struct item {
    int i;
    double d;
    long t;
};

// Define function to generate random values within specified ranges
void generate_random_values(int *i, double *d, long *t) {
    // Initialize random seed
    srand(time(NULL));

    // Generate random integer value between 1 and 100
    *i = rand() % 100 + 1;

    // Generate random floating-point value between 0.0 and 1.0
    *d = (double)rand() / RAND_MAX;

    // Generate random timestamp value between current time and 1 year from now
    *t = time(NULL) + rand() % 365 * 24 * 60 * 60;
}

// Define function to read input data from standard input
void read_input(struct item **items, int *num_items) {
    // Initialize variables
    char line[1024];
    int i = 0;
    double d = 0.0;
    long t = 0;

    // Read input data from standard input
    while (fgets(line, sizeof(line), stdin) != NULL && i < 50000) {
        // Parse input data into integer, floating-point, and timestamp values
        sscanf(line, "%d %lf %ld", &i, &d, &t);

        // Store parsed values in struct array
        items[i] = malloc(sizeof(struct item));
        items[i]->i = i;
        items[i]->d = d;
        items[i]->t = t;

        // Increment counter for number of items read
        i++;
    }

    // Set number of items to be returned
    *num_items = i;
}

// Define function to calculate average of floating-point numbers
double calculate_average(struct item **items, int num_items) {
    // Initialize variables
    double sum = 0.0;
    int count = 0;

    // Iterate over struct array and calculate sum of floating-point values
    for (int i = 0; i < num_items; i++) {
        sum += items[i]->d;
        count++;
    }

    // Return average of floating-point values
    return sum / count;
}

// Define function to log detailed information about operation
void log_operation(struct item **items, int num_items) {
    // Initialize variables
    FILE *log_file = fopen("operation_log.txt", "a");
    time_t start_time = time(NULL);
    time_t end_time = 0;
    double max_int = -1;
    double min_int = INT_MAX;
    double max_float = -1;
    double min_float = DBL_MAX;
    long max_timestamp = -1;
    long min_timestamp = LONG_MAX;
    double sum_ints = 0.0;
    int count_ints = 0;
    double average_floats = 0.0;
    int count_floats = 0;

    // Log start time of operation
    fprintf(log_file, "Start time: %s\n", ctime(&start_time));

    // Iterate over struct array and calculate maximum and minimum values for integers, floating-point numbers, and timestamps
    for (int i = 0; i < num_items; i++) {
        if (items[i]->i > max_int) {
            max_int = items[i]->i;
        }
        if (items[i]->i < min_int) {
            min_int = items[i]->i;
        }
        if (items[i]->d > max_float) {
            max_float = items[i]->d;
        }
        if (items[i]->d < min_float) {
            min_float = items[i]->d;
        }
        if (items[i]->t > max_timestamp) {
            max_timestamp = items[i]->t;
        }
        if (items[i]->t < min_timestamp) {
            min_timestamp = items[i]->t;
        }
        sum_ints += items[i]->i;
        count_ints++;
        average_floats += items[i]->d;
        count_floats++;
    }

    // Log maximum and minimum values for integers, floating-point numbers, and timestamps
    fprintf(log_file, "Maximum integer value: %d\n", max_int);
    fprintf(log_file, "Minimum integer value: %d\n", min_int);
    fprintf(log_file, "Maximum floating-point value: %f\n", max_float);
    fprintf(log_file, "Minimum floating-point value: %f\n", min_float);
    fprintf(log_file, "Earliest timestamp: %ld\n", min_timestamp);
    fprintf(log_file, "Latest timestamp: %ld\n", max_timestamp);

    // Log total sum of integers and average of floating-point numbers
    fprintf(log_file, "Total sum of integers: %f\n", sum_ints);
    fprintf(log_file, "Average of floating-point numbers: %f\n", average_floats / count_floats);

    // Log end time of operation
    end_time = time(NULL);
    fprintf(log_file, "End time: %s\n", ctime(&end_time));

    // Close log file
    fclose(log_file);
}

// Define function to handle large input sizes efficiently
void process_input(struct item **items, int *num_items) {
    // Initialize variables
    int chunk_size = 1000;
    int num_chunks = (*num_items + chunk_size - 1) / chunk_size;
    struct item **chunk_items = malloc(sizeof(struct item *) * chunk_size);

    // Iterate over input data in chunks
    for (int i = 0; i < num_chunks; i++) {
        // Calculate start and end indices for current chunk
        int start_index = i * chunk_size;
        int end_index = min(start_index + chunk_size, *num_items);

        // Initialize variables for current chunk
        int j = 0;
        double sum = 0.0;
        int count = 0;

        // Iterate over struct array and calculate sum of floating-point values in current chunk
        for (j = start_index; j < end_index; j++) {
            sum += items[j]->d;
            count++;
        }

        // Print average of floating-point values in current chunk
        printf("Average of floating-point numbers in chunk %d: %f\n", i + 1, sum / count);
    }
}

