void log(log_sink_t *sink, int level, char *message) {
    if (level > sink->level || !sink->enabled) {
        return;
    }
    pthread_mutex_lock(&sink->mutex);
    semaphore_wait(&sink->semaphore);
    int fd = sink->fd;
    if (fd > 0) {
        char *log_message = malloc(strlen(message) + 1);
        strcpy(log_message, message);
        write(fd, log_message, strlen(log_message));
        free(log_message);
