}

// Function to determine the event with the highest probability value in an event array
void find_highest_probability(Event* events, int num_events) {
    // Initialize variables for tracking highest probability value and its index
    double highest_probability = -1.0;
    int highest_index = 0;

    // Iterate through the event array and find the highest probability value
    for (int i = 0; i < num_events; i++) {
        if (events[i].probability > highest_probability) {
            highest_probability = events[i].probability;
            highest_index = i;
        }
    }

    // Print the event with the highest probability value and its index
    printf("Event with highest probability: %f at index %d\n", highest_probability, highest_index);
}

// Function to free memory allocated for the event array and input value array
void cleanup(Event* events, float* input_values) {
    // Free memory allocated for the event array
    if (events) {
        free(events);
    }

    // Free memory allocated for the input value array
    if (input_values) {
        free(input_values);
    }
}

int main() {
    // Initialize variables for tracking event metadata and input values
    Event* events = NULL;
    float* input_values = NULL;

    // Allocate memory for the event array and populate with random values
    init_events(events, MAX_EVENTS);

    // Read input values from standard input and store in an auxiliary array
    read_input(input_values, MAX_INPUT_VALUES);

