// Define the chunk header structure
typedef struct {
    char* identifier;
    int size;
    struct chunk_header* next;
} chunk_header;

// Define the compressed data block structure
typedef struct {
    uint8_t* data;
    int decompression_algorithm;
} compressed_data;

// Function to initialize memory for the chunk headers and compressed data blocks
chunk_header* init_memory(int num_chunks, int max_chunk_size, int max_decompression_algorithm) {
    // Allocate memory for the chunk headers
    chunk_header* chunk_headers = (chunk_header*)malloc(num_chunks * sizeof(chunk_header));
    if (!chunk_headers) {
        printf("Error: Failed to allocate memory for chunk headers\n");
        return NULL;
    }

    // Allocate memory for the compressed data blocks
    compressed_data* compressed_data_blocks = (compressed_data*)malloc(num_chunks * sizeof(compressed_data));
    if (!compressed_data_blocks) {
        printf("Error: Failed to allocate memory for compressed data blocks\n");
        free(chunk_headers);
        return NULL;
    }

    // Initialize the chunk headers and compressed data blocks
    for (int i = 0; i < num_chunks; i++) {
        chunk_headers[i].identifier = malloc(max_chunk_size * sizeof(char));
        if (!chunk_headers[i].identifier) {
            printf("Error: Failed to allocate memory for chunk identifier\n");
            free(chunk_headers);
            free(compressed_data_blocks);
            return NULL;
        }
        chunk_headers[i].size = 0;
        chunk_headers[i].next = NULL;

        compressed_data_blocks[i].data = malloc(max_chunk_size * sizeof(uint8_t));
        if (!compressed_data_blocks[i].data) {
            printf("Error: Failed to allocate memory for compressed data block\n");
            free(chunk_headers);
            free(compressed_data_blocks);
            return NULL;
        }
        compressed_data_blocks[i].decompression_algorithm = max_decompression_algorithm;
    }

    // Return a pointer to the first element of the compressed data blocks array
    return compressed_data_blocks;
}
