#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Custom memory pool for efficient allocation and deallocation
struct MemoryPool {
    size_t capacity;
    size_t used;
    void* buffer;
};

// Structure to hold a single record with an int value and a random long value
typedef struct Record {
    int value;
    long randomValue;
} Record;

// Function to allocate memory for an array of records, offset structures, and key structures
void* allocateMemory(size_t numRecords, size_t numOffsets, size_t numKeys) {
    // Calculate the total size required for all arrays
    size_t totalSize = (numRecords * sizeof(Record)) + (numOffsets * sizeof(long)) + (numKeys * sizeof(int));

    // Allocate memory from a custom memory pool if available, otherwise use malloc()
    void* memory = NULL;
    if (memoryPool != NULL) {
        memory = allocateFromMemoryPool(totalSize);
    } else {
        memory = malloc(totalSize);
    }

    // Check for allocation failure and handle errors appropriately
    if (memory == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize the offset array with random long values
    long* offsets = (long*)memory;
    for (size_t i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % 1000000;
    }

    // Initialize the key array with random int values
    int* keys = (int*)((char*)offsets + (numOffsets * sizeof(long)));
    for (size_t i = 0; i < numKeys; i++) {
        keys[i] = rand() % 1000000;
    }

    // Initialize the record array with random int values and set the offset and key pointers
    Record* records = (Record*)((char*)keys + (numKeys * sizeof(int)));
    for (size_t i = 0; i < numRecords; i++) {
        records[i].value = rand() % 1000000;
        records[i].randomValue = offsets[rand() % numOffsets];
        records[i].key = keys[rand() % numKeys];
    }

    return records;
}

// Function to deallocate memory for an array of records, offset structures, and key structures
void deallocateMemory(void* memory) {
    // Check if the memory is from a custom memory pool
    if (memoryPool != NULL && memory >= memoryPool->buffer && memory < (char*)memoryPool->buffer + memoryPool->capacity) {
        freeFromMemoryPool(memory);
    } else {
        free(memory);
    }
}

// Function to allocate memory from a custom memory pool
void* allocateFromMemoryPool(size_t size) {
    // Check if the memory pool is full or there are no available slots
    if (memoryPool->used == memoryPool->capacity || memoryPool->buffer[memoryPool->used] != NULL) {
        return NULL;
    }

    // Allocate memory from the custom memory pool and update the used count
    void* memory = &memoryPool->buffer[memoryPool->used];
    memoryPool->used++;

    return memory;
}

// Function to free memory from a custom memory pool
void freeFromMemoryPool(void* memory) {
    // Check if the memory is from the custom memory pool and update the used count
    if (memoryPool != NULL && memory >= memoryPool->buffer && memory < (char*)memoryPool->buffer + memoryPool->capacity) {
        memoryPool->used--;
    }
}

// Function to initialize a custom memory pool with a specified capacity
void initMemoryPool(size_t capacity) {
    // Allocate memory for the custom memory pool and set the used count to 0
    memoryPool = malloc(sizeof(struct MemoryPool));
    memoryPool->capacity = capacity;
    memoryPool->used = 0;
    memoryPool->buffer = malloc(capacity);
}

// Function to release resources allocated by a custom memory pool
void releaseMemoryPool() {
    // Check if the memory pool is initialized and free its buffer
    if (memoryPool != NULL) {
        free(memoryPool->buffer);
        memoryPool = NULL;
    }
}

// Function to generate random numbers within a specified range
int randRange(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random long value within a specified range
long randLongRange(long min, long max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random int value within a specified range
