    int value;
    int random_number;
};

// Function to dynamically manage memory allocation and initialization
void dynamic_memory_allocation(size_t offset_count, size_t key_count, size_t record_count, long min_value, long max_value) {
    // Initialize custom memory pool for efficient allocation
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    pool->capacity = offset_count + key_count + record_count;
    pool->buffer = malloc(pool->capacity * sizeof(void*));

    // Allocate memory for offset array
    struct Offset* offsets = (struct Offset*)malloc(offset_count * sizeof(struct Offset));
    for (size_t i = 0; i < offset_count; i++) {
        offsets[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for key array
    struct Key* keys = (struct Key*)malloc(key_count * sizeof(struct Key));
    for (size_t i = 0; i < key_count; i++) {
        keys[i].key = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for record array and initialize random numbers
    struct Record* records = (struct Record*)malloc(record_count * sizeof(struct Record));
    srand(time(NULL));
    for (size_t i = 0; i < record_count; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].random_number = rand() % (max_value - min_value + 1) + min_value;
    }

    // Free memory pool when done
    free(pool->buffer);
    free(pool);
}
