// Custom memory pool for efficient repeated allocations
struct MemoryPool {
    void* buffer;
    size_t capacity;
    size_t used;
};

// Offset structure containing a single long value
struct Offset {
    long value;
};

// Key structure holding an int key
struct Key {
    int key;
};

// Record structure containing an int value initialized to a random number within a specified range
struct Record {
    int value;
};

// Function to manage memory allocation and initialization for dynamic set of records
void* allocate_records(size_t num_records, size_t record_size, size_t offset_size, size_t key_size) {
    // Calculate the total size required for the arrays
    size_t array_size = (num_records * record_size) + (num_records * offset_size) + (num_records * key_size);

    // Allocate memory for the arrays using a custom memory pool
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    pool->buffer = malloc(array_size);
    pool->capacity = array_size;
    pool->used = 0;

    // Initialize the offset and key arrays
    void* offset_array = pool->buffer;
    void* key_array = (char*)pool->buffer + num_records * record_size;

    // Initialize the record array with random values within a specified range
    struct Record* record_array = (struct Record*)key_array + num_records * key_size;
    for (int i = 0; i < num_records; i++) {
        record_array[i].value = rand() % 100;
    }

    // Return a pointer to the start of the record array
    return record_array;
}

// Function to deallocate memory for dynamic set of records
void deallocate_records(void* records) {
    struct MemoryPool* pool = (struct MemoryPool*)((char*)records - sizeof(struct MemoryPool));
    free(pool->buffer);
    free(pool);
}

// Function to handle multi-threaded access to the memory pool
void* allocate_record(size_t record_size, size_t offset_size, size_t key_size) {
    // Lock the memory pool to prevent concurrent access
    pthread_mutex_lock(&pool->mutex);

    // Allocate a new record from the memory pool
    struct Record* record = (struct Record*)malloc(record_size);

    // Initialize the offset and key arrays for the record
    void* offset_array = malloc(offset_size);
    void* key_array = malloc(key_size);

    // Unlock the memory pool to allow other threads to access it
    pthread_mutex_unlock(&pool->mutex);

    return record;
}

// Function to deallocate a single record from the memory pool
void deallocate_record(struct Record* record) {
    // Lock the memory pool to prevent concurrent access
    pthread_mutex_lock(&pool->mutex);

    // Free the offset and key arrays for the record
    free((char*)record - sizeof(struct Offset));
    free((char*)record - sizeof(struct Key));

    // Free the record from the memory pool
    free(record);

    // Unlock the memory pool to allow other threads to access it
    pthread_mutex_unlock(&pool->mutex);
}
