// Custom memory pool structure
struct MemoryPool {
    void* data;
    size_t size;
    struct MemoryPool* next;
};

// Function to allocate memory from the custom memory pool
void* alloc(size_t size) {
    // Check if there is enough space in the current pool
    if (pool->size - pool->data < size) {
        // If not, create a new pool and add it to the list
        struct MemoryPool* new_pool = malloc(sizeof(struct MemoryPool));
        new_pool->data = malloc(size);
        new_pool->size = size;
        new_pool->next = NULL;
        pool->next = new_pool;
    }

    // Allocate memory from the current pool
    void* data = pool->data;
    pool->data += size;
    pool->size -= size;

    return data;
}

