struct packet {
    unsigned int protocol;
    char source_ip[16];
    long long timestamp;
    size_t length;
};

// Function to initialize the arrays and allocate memory for packets
void init_packet_arrays(size_t max_num_packets) {
    // Allocate memory for the protocol array
    unsigned int *protocol_arr = malloc(max_num_packets * sizeof(unsigned int));
    if (protocol_arr == NULL) {
        printf("Error: Failed to allocate memory for protocol array\n");
        exit(1);
    }

    // Allocate memory for the source IP address array
    char **source_ip_arr = malloc(max_num_packets * sizeof(char*));
    if (source_ip_arr == NULL) {
        printf("Error: Failed to allocate memory for source IP address array\n");
        exit(1);
    }

    // Allocate memory for the packet event structure array
    struct packet *packet_events = malloc(max_num_packets * sizeof(struct packet));
    if (packet_events == NULL) {
        printf("Error: Failed to allocate memory for packet event structure array\n");
        exit(1);
    }

    // Initialize the arrays with random values
    srand(time(NULL));
    for (size_t i = 0; i < max_num_packets; i++) {
        protocol_arr[i] = rand() % 256;
        source_ip_arr[i] = malloc(16 * sizeof(char));
        if (source_ip_arr[i] == NULL) {
            printf("Error: Failed to allocate memory for source IP address\n");
            exit(1);
        }
        strcpy(source_ip_arr[i], "192.168.0.1");
        packet_events[i].protocol = protocol_arr[i];
        packet_events[i].source_ip = source_ip_arr[i];
        packet_events[i].timestamp = rand() % 1000000000;
        packet_events[i].length = rand() % 10000;
    }
}

// Function to read and process input data from standard input
void process_input(size_t max_num_packets) {
    // Read the list of packet lengths and timestamps from standard input
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, stdin)) != -1) {
        // Parse the line to extract the packet length and timestamp
        unsigned int protocol;
        char source_ip[16];
        long long timestamp;
        size_t length;
        sscanf(line, "%u %s %lld %zu", &protocol, source_ip, &timestamp, &length);

        // Check if the packet is within the maximum allowed range
        if (length > 10000) {
            printf("Error: Packet length exceeds maximum allowed value\n");
            continue;
        }

        // Update the corresponding entry in the packet event structure array
        for (size_t i = 0; i < max_num_packets; i++) {
            if (strcmp(source_ip, packet_events[i].source_ip) == 0 && timestamp == packet_events[i].timestamp) {
                packet_events[i].protocol = protocol;
                packet_events[i].length = length;
                break;
            }
        }
    }
}

// Function to identify and print the longest packet by length
void find_longest_packet(size_t max_num_packets) {
    size_t longest_length = 0;
    for (size_t i = 0; i < max_num_packets; i++) {
        if (packet_events[i].length > longest_length) {
            longest_length = packet_events[i].length;
        }
    }
    printf("Longest packet by length: %zu\n", longest_length);
}

// Function to calculate and print the average packet length
void calculate_average_packet_length(size_t max_num_packets) {
    long long total_length = 0;
    for (size_t i = 0; i < max_num_packets; i++) {
        total_length += packet_events[i].length;
    }
    printf("Average packet length: %lld\n", total_length / max_num_packets);
}

// Function to determine the packet with the most recent timestamp
void find_most_recent_packet(size_t max_num_packets) {
    long long most_recent_timestamp = 0;
    size_t most_recent_index = 0;
    for (size_t i = 0; i < max_num_packets; i++) {
        if (packet_events[i].timestamp > most_recent_timestamp) {
            most_recent_timestamp = packet_events[i].timestamp;
            most_recent_index = i;
        }
    }
    printf("Packet with the most recent timestamp: %zu\n", most_recent_index);
}

// Function to free allocated memory
void cleanup(size_t max_num_packets) {
    for (size_t i = 0; i < max_num_packets; i++) {
        free(source_ip_arr[i]);
    }
    free(protocol_arr);
    free(source_ip_arr);
    free(packet_events);
}

int main() {
    // Initialize the arrays and allocate memory for packets
    size_t max_num_packets = 10000;
    init_packet_arrays(max_num_packets);

    // Read input data from standard input
    process_input(max_num_packets);

    // Identify and print the longest packet by length
    find_longest_packet(max_num_packets);

    // Calculate and print the average packet length
    calculate_average_packet_length(max_num_packets);

    // Determine the packet with the most recent timestamp
    find_most_recent_packet(max_num_packets);

    // Free allocated memory
    cleanup(max_num_packets);

    return 0;
}
