    size_t used;
};

// Function to allocate memory from the custom memory pool
void* mempool_alloc(size_t size) {
    struct MemoryPool* pool = get_memory_pool();
    if (pool->used + size > pool->capacity) {
        // Reallocate the buffer if it's full
        pool->buffer = realloc(pool->buffer, pool->capacity * 2);
        pool->capacity *= 2;
    }
    void* ptr = (char*)pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

// Function to deallocate memory from the custom memory pool
void mempool_free(void* ptr) {
    struct MemoryPool* pool = get_memory_pool();
    if (ptr >= pool->buffer && ptr < (char*)pool->buffer + pool->used) {
        // Free the memory block if it's within the buffer range
        size_t size = (char*)ptr - (char*)pool->buffer;
        pool->used -= size;
    } else {
        // Reallocate the buffer to remove any leaked memory blocks
