            ivlen = 32;
            break;
    }

    // Set the key length and initialize the cipher
    int keylen = strlen(password) * 8;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, password, ivlen) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Set the IV length based on the user input
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, ivlen, NULL) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

