void handle_ciphers(EVP_CIPHER_CTX** ctx, int num_contexts) {
    // Allocate memory for the cipher contexts
    struct MemoryPool* pool = get_memory_pool();
    void* buffer = mempool_alloc(num_contexts * sizeof(EVP_CIPHER_CTX));
    EVP_CIPHER_CTX** ctx_ptr = (EVP_CIPHER_CTX**)buffer;

    // Initialize the cipher contexts and set the memory pool for each one
    for (int i = 0; i < num_contexts; i++) {
        ctx_ptr[i] = EVP_CIPHER_CTX_new();
        if (!ctx_ptr[i]) {
            cleanup_ciphers(ctx, i);
            return -1;
        }
        EVP_CIPHER_CTX_set_memory_pool(ctx_ptr[i], pool);
    }

    // Return the cipher contexts and the memory pool
    *ctx = ctx_ptr;
    return pool;
}

// Function to clean up and disable multiple AES-256-CBC ciphers
void cleanup_ciphers(EVP_CIPHER_CTX** ctx, int num_contexts) {
    // Free the memory pool if it's not used by any other context
    struct MemoryPool* pool = get_memory_pool();
    if (pool->used == 0) {
        free(pool);
    }

    // Clean up and disable each cipher context
    for (int i = 0; i < num_contexts; i++) {
        EVP_CIPHER_CTX_free(ctx[i]);
    }
}

// Function to handle common error scenarios in AES-256-CBC cipher initialization
void handle_errors(int ret, const char* msg) {
    if (ret != 1) {
