        records[i].value = rand() % 100;
    }

    return records;
}

// Function to manage memory allocation and initialization for a dynamic set of records
void* allocate_memory(size_t offset_count, size_t key_count, size_t record_count) {
    // Allocate memory for the arrays of offsets, keys, and records
    struct Offset* offsets = allocate_offsets(offset_count);
    struct Key* keys = allocate_keys(key_count);
    struct Record* records = allocate_records(record_count);

    // Allocate memory for the custom memory pool
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        return NULL;
    }

    // Initialize the custom memory pool
    pool->data = offsets;
    pool->size = offset_count * sizeof(struct Offset);

    // Return a pointer to the custom memory pool
    return pool;
}

// Function to deallocate memory for a dynamic set of records
void deallocate_memory(void* pool) {
    // Check if the input is a valid memory pool
    if (!pool) {
        fprintf(stderr, "Invalid memory pool\n");
        return;
    }

    // Cast the input to a struct MemoryPool pointer
    struct MemoryPool* p = (struct MemoryPool*)pool;

    // Deallocate the memory for the arrays of offsets, keys, and records
    free(p->data);
    free(p);
}

// Function to serialize a dynamic set of records to a binary format
void serialize_records(void* pool, FILE* file) {
    // Check if the input is a valid memory pool
    if (!pool) {
        fprintf(stderr, "Invalid memory pool\n");
        return;
    }

    // Cast the input to a struct MemoryPool pointer
    struct MemoryPool* p = (struct MemoryPool*)pool;

    // Write the size of the custom memory pool to the file
    fwrite(&p->size, sizeof(size_t), 1, file);

    // Write the data for each offset structure to the file
    for (size_t i = 0; i < p->size / sizeof(struct Offset); i++) {
        struct Offset* offset = (struct Offset*)p->data + i;
        fwrite(&offset->value, sizeof(long), 1, file);
    }

    // Write the data for each key structure to the file
    for (size_t i = 0; i < p->size / sizeof(struct Key); i++) {
        struct Key* key = (struct Key*)p->data + i;
        fwrite(&key->value, sizeof(int), 1, file);
    }

    // Write the data for each record structure to the file
    for (size_t i = 0; i < p->size / sizeof(struct Record); i++) {
        struct Record* record = (struct Record*)p->data + i;
        fwrite(&record->value, sizeof(int), 1, file);
    }
}

// Function to deserialize a dynamic set of records from a binary format
void deserialize_records(FILE* file, void** pool) {
    // Check if the input is a valid memory pool
    if (!pool) {
        fprintf(stderr, "Invalid memory pool\n");
        return;
    }

    // Cast the input to a struct MemoryPool pointer
    struct MemoryPool* p = (struct MemoryPool*)pool;

    // Read the size of the custom memory pool from the file
    fread(&p->size, sizeof(size_t), 1, file);

    // Allocate memory for the arrays of offsets, keys, and records
    p->data = malloc(p->size);
    if (!p->data) {
        fprintf(stderr, "Failed to allocate memory for deserialized records\n");
        return;
    }

    // Read the data for each offset structure from the file
    for (size_t i = 0; i < p->size / sizeof(struct Offset); i++) {
        struct Offset* offset = (struct Offset*)p->data + i;
        fread(&offset->value, sizeof(long), 1, file);
    }

    // Read the data for each key structure from the file
    for (size_t i = 0; i < p->size / sizeof(struct Key); i++) {
        struct Key* key = (struct Key*)p->data + i;
        fread(&key->value, sizeof(int), 1, file);
    }

    // Read the data for each record structure from the file
    for (size_t i = 0; i < p->size / sizeof(struct Record); i++) {
        struct Record* record = (struct Record*)p->data + i;
        fread(&record->value, sizeof(int), 1, file);
    }
}
