    for (size_t i = 0; i < recordSize; ++i) {
        if (offsets[i] == offset && keys[i] == key) {
            return records + i;
        }
    }

    // If the record is not found, allocate a new one and add it to the dynamic set of records
    int* newRecord = (int*)malloc(sizeof(int));
    *newRecord = rand() % maxValue;
    offsets[recordSize] = offset;
    keys[recordSize] = key;
    records[recordSize] = *newRecord;
    recordSize++;

    // Release the mutex to allow other threads to access the record
    pthread_mutex_unlock(&recordMutex);

    return newRecord;
}

// Function to handle multi-threaded access to the dynamic set of records
void releaseRecord(size_t offset, size_t key) {
    // Synchronize access to the record using a mutex if necessary
    pthread_mutex_lock(&recordMutex);

    // Find the corresponding record based on the offset and key
    long* offsets = (long*)buffer;
    int* keys = (int*)((char*)buffer + offsetSize * sizeof(long));
    int* records = (int*)((char*)buffer + offsetSize * sizeof(long) + keySize * sizeof(int));
    for (size_t i = 0; i < recordSize; ++i) {
        if (offsets[i] == offset && keys[i] == key) {
            // Free the memory block allocated to the record
            free(records + i);

            // Remove the record from the dynamic set of records
            for (size_t j = i; j < recordSize - 1; ++j) {
                offsets[j] = offsets[j + 1];
                keys[j] = keys[j + 1];
                records[j] = records[j + 1];
