// Define the structure for packet events
struct packet {
    unsigned int protocol;
    char source_ip[16];
    long long timestamp;
    size_t length;
};

// Define the parameters for the function
#define MAX_PACKETS 200000
#define MIN_LENGTH 0
#define MAX_LENGTH 10000
#define THRESHOLD 50
#define LOG_FILE "packet_log.txt"

// Define the mutex for thread-safe access to shared resources
pthread_mutex_t lock;

// Function to generate a random timestamp within a specified range
long long get_random_timestamp(long long min, long long max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to allocate and populate the packet array with randomly generated packets
void generate_packets(struct packet **packet_array, size_t *num_packets) {
    // Initialize the packet array
    *packet_array = (struct packet *)malloc(sizeof(struct packet) * MAX_PACKETS);
    if (*packet_array == NULL) {
        printf("Error: Failed to allocate memory for packet array\n");
        exit(1);
    }

    // Initialize the number of packets
    *num_packets = 0;

    // Generate randomly generated packets with unique timestamps and lengths
    while (*num_packets < MAX_PACKETS) {
        struct packet *pkt = &(*packet_array)[*num_packets];
        pkt->protocol = rand() % 256;
        sprintf(pkt->source_ip, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        pkt->timestamp = get_random_timestamp(MIN_LENGTH, MAX_LENGTH);
        pkt->length = rand() % (MAX_LENGTH - MIN_LENGTH) + MIN_LENGTH;
        (*num_packets)++;
    }
}

// Function to read a list of packet lengths and timestamps from standard input
void read_input(struct packet **packet_array, size_t *num_packets) {
    // Initialize the packet array
    *packet_array = (struct packet *)malloc(sizeof(struct packet) * MAX_PACKETS);
    if (*packet_array == NULL) {
        printf("Error: Failed to allocate memory for packet array\n");
        exit(1);
    }

    // Initialize the number of packets
    *num_packets = 0;

    // Read the list of packet lengths and timestamps from standard input
    while (*num_packets < MAX_PACKETS) {
        struct packet *pkt = &(*packet_array)[*num_packets];
        if (scanf("%u %s %lld", &pkt->protocol, pkt->source_ip, &pkt->timestamp) != 3) {
            break;
        }
        pkt->length = strlen(pkt->source_ip);
        (*num_packets)++;
    }
}

// Function to log the packet events to a file
void log_events(struct packet *packet_array, size_t num_packets) {
    // Open the log file for writing
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Error: Failed to open log file\n");
        exit(1);
    }

    // Write the packet events to the log file
    for (size_t i = 0; i < num_packets; i++) {
        struct packet *pkt = &packet_array[i];
        fprintf(log_file, "%u %s %lld %zu\n", pkt->protocol, pkt->source_ip, pkt->timestamp, pkt->length);
    }

    // Close the log file
    fclose(log_file);
}

// Function to filter out events with a measurement value below a given threshold
void filter_events(struct packet *packet_array, size_t num_packets) {
    // Initialize the filtered event array
    struct packet *filtered_array = (struct packet *)malloc(sizeof(struct packet) * MAX_PACKETS);
    if (filtered_array == NULL) {
        printf("Error: Failed to allocate memory for filtered event array\n");
        exit(1);
    }

    // Initialize the number of filtered events
    size_t num_filtered = 0;

    // Filter out events with a measurement value below the threshold
    for (size_t i = 0; i < num_packets; i++) {
        struct packet *pkt = &packet_array[i];
        if (pkt->length >= THRESHOLD) {
            filtered_array[num_filtered++] = *pkt;
        }
    }

    // Update the number of filtered events
    num_packets = num_filtered;
}

// Function to serialize the filtered events into JSON format
void serialize_events(struct packet *filtered_array, size_t num_packets) {
    // Initialize the JSON object
    json_object *json = json_object_new();
    if (json == NULL) {
        printf("Error: Failed to create JSON object\n");
        exit(1);
    }

    // Add the filtered events to the JSON object
    for (size_t i = 0; i < num_packets; i++) {
        struct packet *pkt = &filtered_array[i];
        json_object_object_add(json, "protocol", json_object_new_int(pkt->protocol));
        json_object_object_add(json, "source_ip", json_object_new_string(pkt->source_ip));
        json_object_object_add(json, "timestamp", json_object_new_int64(pkt->timestamp));
        json_object_object_add(json, "length", json_object_new_int(pkt->length));
    }

    // Serialize the JSON object to a string
    char *json_string = json_object_to_json_string(json);
    if (json_string == NULL) {
        printf("Error: Failed to serialize JSON object\n");
        exit(1);
    }

    // Print the serialized JSON string
    printf("%s\n", json_string);
}

// Function to determine the longest packet by length
void find_longest_packet(struct packet *packet_array, size_t num_packets) {
    // Initialize the longest packet
    struct packet longest = {0};

    // Find the longest packet by length
    for (size_t i = 0; i < num_packets; i++) {
        struct packet *pkt = &packet_array[i];
        if (pkt->length > longest.length) {
            longest = *pkt;
        }
    }

    // Print the longest packet
    printf("Longest packet: %u %s %lld %zu\n", longest.protocol, longest.source_ip, longest.timestamp, longest.length);
}

// Function to calculate and print the average packet length
void calculate_average(struct packet *packet_array, size_t num_packets) {
    // Initialize the sum of packet lengths
    long long sum = 0;

    // Calculate the sum of packet lengths
    for (size_t i = 0; i < num_packets; i++) {
        struct packet *pkt = &packet_array[i];
        sum += pkt->length;
    }

    // Print the average packet length
    printf("Average packet length: %lf\n", (double)sum / num_packets);
}

// Function to determine the packet with the most recent timestamp
void find_most_recent(struct packet *packet_array, size_t num_packets) {
    // Initialize the most recent packet
    struct packet most_recent = {0};

    // Find the packet with the most recent timestamp
    for (size_t i = 0; i < num_packets; i++) {
        struct packet *pkt = &packet_array[i];
        if (most_recent.timestamp == 0 || pkt->timestamp > most_recent.timestamp) {
            most_recent = *pkt;
        }
    }

    // Print the packet with the most recent timestamp
    printf("Most recent packet: %u %s %lld %zu\n", most_recent.protocol, most_recent.source_ip, most_recent.timestamp, most_recent.length);
}

// Main function to manage the allocation, manipulation, and monitoring of interconnected data structures for a high-performance network packet processing and monitoring system
int main() {
    // Initialize the mutex for thread-safe access to shared resources
    pthread_mutex_init(&lock, NULL);

    // Declare variables for the packet array and number of packets
    struct packet *packet_array;
    size_t num_packets = 0;

    // Generate randomly generated packets with unique timestamps and lengths
    generate_packets(&packet_array, &num_packets);

    // Read a list of packet lengths and timestamps from standard input
    read_input(&packet_array, &num_packets);

    // Log the packet events to a file
    log_events(packet_array, num_packets);

    // Filter out events with a measurement value below a given threshold
    filter_events(packet_array, num_packets);

    // Serialize the filtered events into JSON format
    serialize_events(filtered_array, num_packets);

    // Determine the longest packet by length
    find_longest_packet(packet_array, num_packets);

    // Calculate and print the average packet length
    calculate_average(packet_array, num_packets);

    // Determine the packet with the most recent timestamp
    find_most_recent(packet_array, num_packets);

    // Clean up memory
    free(packet_array);
    pthread_mutex_destroy(&lock);

    return 0;
}
