// Function to generate a random timestamp within a specified range
long long get_random_timestamp(long long min, long long max) {
    // Generate a random number between the minimum and maximum values
    int random_number = rand() % (max - min + 1) + min;
    return random_number;
}

// Function to initialize the packet array with randomly generated packets
void init_packet_array(struct packet **packets, int *num_packets) {
    // Allocate memory for the packet array
    *packets = (struct packet *)malloc(INITIAL_MEMORY_ALLOCATION * sizeof(struct packet));
    if (*packets == NULL) {
        printf("Error: Failed to allocate memory for packet array\n");
        exit(1);
    }

    // Initialize the number of packets to 0
    *num_packets = 0;

    // Generate randomly generated packets and add them to the array
    while (*num_packets < INITIAL_MEMORY_ALLOCATION) {
        struct packet new_packet;
        new_packet.protocol = rand() % 256;
        sprintf(new_packet.source_ip, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        new_packet.timestamp = get_random_timestamp(0, 1000000000);
        new_packet.length = rand() % 1000;
        (*packets)[*num_packets] = new_packet;
        *num_packets += 1;
    }
}

// Function to read a list of packet lengths and timestamps from standard input
void read_input(struct packet **packets, int *num_packets) {
    // Read the number of packets from standard input
    printf("Enter the number of packets: ");
    scanf("%d", num_packets);

    // Check if the number of packets is within the maximum limit
    if (*num_packets > MAX_PACKETS) {
        printf("Error: The number of packets exceeds the maximum limit\n");
        exit(1);
    }

    // Allocate memory for the packet array
    *packets = (struct packet *)malloc(*num_packets * sizeof(struct packet));
    if (*packets == NULL) {
        printf("Error: Failed to allocate memory for packet array\n");
        exit(1);
    }

