        scanf("%s", new_packet.source_ip);
        scanf("%lld", &new_packet.timestamp);
        scanf("%d", &new_packet.length);
        (*packets)[i] = new_packet;
    }
}

// Function to read a log file and parse its lines into events
void read_log(struct packet **packets, int *num_packets) {
    // Open the log file for reading
    FILE *file = fopen(LOG_FILE_PATH, "r");
    if (file == NULL) {
        printf("Error: Failed to open log file\n");
        exit(1);
    }

    // Allocate memory for the packet array
    *packets = (struct packet *)malloc(*num_packets * sizeof(struct packet));
    if (*packets == NULL) {
        printf("Error: Failed to allocate memory for packet array\n");
        exit(1);
    }

    // Read the log file line by line and parse each line into an event
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        struct packet new_packet;
        sscanf(line, "%d %s %lld %d", &new_packet.protocol, new_packet.source_ip, &new_packet.timestamp, &new_packet.length);
        (*packets)[*num_packets] = new_packet;
        *num_packets += 1;
    }
}

// Function to filter out events with a measurement value below the threshold
void filter_events(struct packet **packets, int *num_packets) {
    // Allocate memory for the filtered event array
    struct packet *filtered_events = (struct packet *)malloc(*num_packets * sizeof(struct packet));
    if (filtered_events == NULL) {
        printf("Error: Failed to allocate memory for filtered event array\n");
        exit(1);
    }

    // Iterate through the events and filter out those with a measurement value below the threshold
    int filtered_count = 0;
    for (int i = 0; i < *num_packets; i++) {
        if ((*packets)[i].length >= THRESHOLD) {
            filtered_events[filtered_count] = (*packets)[i];
            filtered_count += 1;
        }
    }

    // Update the number of packets to the filtered count
    *num_packets = filtered_count;
}

// Function to serialize the filtered events into JSON format
void serialize_events(struct packet *filtered_events, int num_packets) {
    // Allocate memory for the JSON string
    char *json_string = (char *)malloc(num_packets * 100);
    if (json_string == NULL) {
        printf("Error: Failed to allocate memory for JSON string\n");
        exit(1);
    }

    // Iterate through the events and serialize them into a JSON array
    json_object *root = json_object_new_array();
    for (int i = 0; i < num_packets; i++) {
        json_object *event = json_object_new_object();
        json_object_object_add(event, "protocol", json_object_new_int((*filtered_events)[i].protocol));
        json_object_object_add(event, "sourceIP", json_object_new_string((*filtered_events)[i].source_ip));
        json_object_object_add(event, "timestamp", json_object_new_int64((*filtered_events)[i].timestamp));
        json_object_object_add(event, "length", json_object_new_int((*filtered_events)[i].length));
        json_object_array_add(root, event);
    }

    // Serialize the JSON array to a string
    json_string = json_to_string(root, 0);
    printf("%s\n", json_string);
}

// Function to determine the longest packet by length
void find_longest_packet(struct packet *packets, int num_packets) {
    // Initialize the longest packet with the first packet in the array
    struct packet longest_packet = packets[0];

    // Iterate through the remaining packets and compare their lengths to determine the longest one
    for (int i = 1; i < num_packets; i++) {
        if (packets[i].length > longest_packet.length) {
            longest_packet = packets[i];
        }
    }

    // Print the details of the longest packet
    printf("Longest packet: protocol %d, source IP %s, timestamp %lld, length %d\n", longest_packet.protocol, longest_packet.source_ip, longest_packet.timestamp, longest_packet.length);
}

// Function to calculate the average packet length
void calculate_average(struct packet *packets, int num_packets) {
    // Initialize the sum of packet lengths to 0
    long long sum = 0;

    // Iterate through the packets and add their lengths to the sum
    for (int i = 0; i < num_packets; i++) {
        sum += packets[i].length;
    }

    // Calculate the average packet length by dividing the sum by the number of packets
    double average = (double)sum / (double)num_packets;

    // Print the average packet length
    printf("Average packet length: %.2f\n", average);
}

// Function to determine the packet with the most recent timestamp
void find_most_recent(struct packet *packets, int num_packets) {
    // Initialize the most recent packet with the first packet in the array
    struct packet most_recent = packets[0];

    // Iterate through the remaining packets and compare their timestamps to determine the most recent one
    for (int i = 1; i < num_packets; i++) {
        if (packets[i].timestamp > most_recent.timestamp) {
            most_recent = packets[i];
        }
    }

    // Print the details of the most recent packet
    printf("Most recent packet: protocol %d, source IP %s, timestamp %lld, length %d\n", most_recent.protocol, most_recent.source_ip, most_recent.timestamp, most_recent.length);
}

// Function to dynamically resize the packet array to accommodate up to 500,000 packets efficiently
void resize_packet_array(struct packet **packets, int *num_packets) {
    // Check if the number of packets exceeds the maximum limit
    if (*num_packets > MAX_PACKETS) {
        printf("Error: The number of packets exceeds the maximum limit\n");
        exit(1);
    }

    // Allocate memory for the new packet array
    struct packet *new_packets = (struct packet *)malloc(500000 * sizeof(struct packet));
    if (new_packets == NULL) {
        printf("Error: Failed to allocate memory for new packet array\n");
        exit(1);
    }

    // Copy the contents of the old packet array to the new one
    memcpy(new_packets, *packets, (*num_packets) * sizeof(struct packet));

    // Free the memory for the old packet array
    free(*packets);

    // Update the pointer to the new packet array
    *packets = new_packets;
}

// Function to periodically compact the packet array to remove unused elements, reducing fragmentation
void compact_packet_array(struct packet **packets, int *num_packets) {
    // Allocate memory for a temporary array with half the size of the original array
    struct packet *temp = (struct packet *)malloc((*num_packets / 2) * sizeof(struct packet));
    if (temp == NULL) {
        printf("Error: Failed to allocate memory for temporary array\n");
        exit(1);
    }

    // Copy the contents of the original array to the temporary one, skipping any unused elements
    int temp_count = 0;
    for (int i = 0; i < *num_packets; i++) {
        if ((*packets)[i].length > 0) {
            temp[temp_count] = (*packets)[i];
            temp_count += 1;
        }
    }

    // Update the number of packets to the new count
    *num_packets = temp_count;

    // Free the memory for the original array
    free(*packets);

    // Update the pointer to the temporary array
    *packets = temp;
}

// Function to integrate with an external logging service to asynchronously log events
void log_events(struct packet *packets, int num_packets) {
    // Implement the integration with the external logging service here
}

int main() {
    // Initialize the packet array and number of packets
    struct packet *packets = NULL;
    int num_packets = 0;

    // Read the list of packet lengths and timestamps from standard input
    read_input(&packets, &num_packets);

    // Filter out events with a measurement value below the threshold
    filter_events(&packets, &num_packets);

    // Serialize the filtered events into JSON format
    serialize_events(packets, num_packets);

    // Determine the longest packet by length
    find_longest_packet(packets, num_packets);

    // Calculate the average packet length
    calculate_average(packets, num_packets);

    // Determine the packet with the most recent timestamp
    find_most_recent(packets, num_packets);

    // Dynamically resize the packet array to accommodate up to 500,000 packets efficiently
    resize_packet_array(&packets, &num_packets);

    // Periodically compact the packet array to remove unused elements, reducing fragmentation
    compact_packet_array(&packets, &num_packets);

    // Integrate with an external logging service to asynchronously log events
    log_events(packets, num_packets);

    return 0;
}']

