#include <time.h>

// Define structure for offset and key
typedef struct {
    long offset;
    int key;
} OffsetKey;

// Define structure for record
typedef struct {
    int value;
} Record;

// Define function to manage memory allocation and initialization
void* initializeMemory(int numRecords, int minValue, int maxValue) {
    // Calculate the size of the offset array
    int offsetSize = sizeof(OffsetKey) * numRecords;

    // Calculate the size of the key array
    int keySize = sizeof(int) * numRecords;

    // Calculate the size of the record array
    int recordSize = sizeof(Record) * numRecords;

    // Allocate memory for the offset and key arrays
    OffsetKey* offsets = (OffsetKey*)malloc(offsetSize);
    int* keys = (int*)malloc(keySize);

    // Initialize the offset and key arrays
    for (int i = 0; i < numRecords; i++) {
        offsets[i].offset = i * sizeof(Record);
        keys[i] = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Allocate memory for the record array
    Record* records = (Record*)malloc(recordSize);

    // Initialize the record array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Dynamically adjust the random number range based on the input data distribution
    int range = maxValue - minValue + 1;
    for (int i = 0; i < numRecords; i++) {
        if (records[i].value > range / 2) {
            range = records[i].value;
        }
    }

    // Log all memory allocation and deallocation events to a file named "memory_log.txt" in a structured format
    FILE* logFile = fopen("memory_log.txt", "a");
    if (logFile != NULL) {
        for (int i = 0; i < numRecords; i++) {
            fprintf(logFile, "%d %s %d %p\n", time(NULL), "allocation", offsetSize + keySize + recordSize, offsets);
            fprintf(logFile, "%d %s %d %p\n", time(NULL), "allocation", offsetSize + keySize, keys);
            fprintf(logFile, "%d %s %d %p\n", time(NULL), "allocation", recordSize, records);
        }
    }

    // Return a pointer to the first element of the record array upon successful initialization
    return records;
}
