    // Initialize the largest value with the first element in the auxiliary array
    int largest = *(*auxiliary + 0);

    // Iterate over the remaining elements in the auxiliary array and compare them to the current largest value
    for (int i = 1; i < size; i++) {
        if (*(*auxiliary + i) > largest) {
            largest = *(*auxiliary + i);
        }
    }

    // Print the largest value
