// Define a structure for records
typedef struct {
    int value;
} record;

void allocate_memory(int num_elements, long min_value, long max_value, int seed) {
    // Calculate the total memory required for arrays and records
    size_t array_size = sizeof(long) * num_elements;
    size_t record_size = sizeof(record) * num_elements;
    size_t total_memory = array_size + record_size;

    // Check if the total memory exceeds 1 MB
    if (total_memory > 1024 * 1024) {
        printf("Error: Total memory allocation exceeds 1 MB\n");
        return;
    }

    // Allocate memory for arrays and records
    long* offset_array = malloc(array_size);
    int* key_array = malloc(record_size);
    record* records = malloc(record_size);

    // Check if memory allocation failed
    if (offset_array == NULL || key_array == NULL || records == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize arrays and records based on input parameters
    srand(seed);
    for (int i = 0; i < num_elements; i++) {
        offset_array[i] = rand() % (max_value - min_value + 1) + min_value;
        key_array[i] = i;
        records[i].value = i;
    }

    // Print the allocated memory and its contents
    printf("Allocated memory: %lu bytes\n", total_memory);
    for (int i = 0; i < num_elements; i++) {
        printf("%d. offset: %ld, key: %d, value: %d\n", i + 1, offset_array[i], key_array[i], records[i].value);
    }

    // Free memory when no longer needed
    free(offset_array);
    free(key_array);
    free(records);
}
