// Define the record structure
typedef struct {
    int value;
    char buffer[64];
    time_t timestamp;
} Record;

// Function to dynamically allocate memory for arrays of long, int, and Record structures
void allocateMemory(int numElements, long minValueRange, long maxValueRange, unsigned int seed, size_t bufferLength) {
    // Calculate the total memory required for the arrays and records
    size_t totalMemory = (numElements * sizeof(long)) + (numElements * sizeof(int)) + (numElements * sizeof(Record));

    // Check if the total memory allocation exceeds 2 MB
    if (totalMemory > 2097152) {
        fprintf(stderr, "Error: Total memory allocation exceeds 2 MB\n");
        return;
    }

    // Allocate memory for the arrays and records
    long *offsetArray = malloc(numElements * sizeof(long));
    int *keyArray = malloc(numElements * sizeof(int));
    Record *recordArray = malloc(numElements * sizeof(Record));

    // Check if memory allocation failed
    if (offsetArray == NULL || keyArray == NULL || recordArray == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }

    // Initialize the arrays and records based on input parameters
    for (int i = 0; i < numElements; i++) {
        offsetArray[i] = rand_r(&seed) % (maxValueRange - minValueRange + 1) + minValueRange;
        keyArray[i] = rand_r(&seed) % INT_MAX;
        recordArray[i].value = rand_r(&seed) % INT_MAX;
        strcpy(recordArray[i].buffer, "");
        recordArray[i].timestamp = time(NULL);
    }

    // Print the arrays and records for debugging purposes
    printf("Offset array: ");
    for (int i = 0; i < numElements; i++) {
        printf("%ld ", offsetArray[i]);
    }
    printf("\n");
    printf("Key array: ");
    for (int i = 0; i < numElements; i++) {
        printf("%d ", keyArray[i]);
    }
    printf("\n");
    printf("Record array: ");
    for (int i = 0; i < numElements; i++) {
        printf("{value: %d, buffer: %s, timestamp: %ld} ", recordArray[i].value, recordArray[i].buffer, recordArray[i].timestamp);
    }
    printf("\n");

    // Free the memory allocated for the arrays and records
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}

// Main function to demonstrate the use of the allocateMemory function
int main() {
    // Set input parameters for the allocateMemory function
    int numElements = 10;
    long minValueRange = 10;
    long maxValueRange = 20;
    unsigned int seed = time(NULL);
    size_t bufferLength = 64;

    // Call the allocateMemory function to dynamically allocate memory for arrays of long, int, and Record structures
    allocateMemory(numElements, minValueRange, maxValueRange, seed, bufferLength);

    return 0;
}
