// Function to read and validate the configuration file
void read_config(const char* filename, size_t* offset_size, size_t* key_size) {
    // Open the configuration file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        exit(1);
    }

    // Read the values from the configuration file
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "offset_size", 11) == 0) {
            *offset_size = atoi(line + 12);
        } else if (strncmp(line, "key_size", 8) == 0) {
            *key_size = atoi(line + 9);
        }
    }

    // Close the configuration file
    fclose(fp);
}

// Function to allocate memory for and initialize the arrays
void init_arrays(size_t offset_size, size_t key_size) {
    // Allocate memory for the offset array
    long* offsets = malloc(offset_size * sizeof(long));
    if (offsets == NULL) {
        printf("Error: unable to allocate memory for offset array\n");
        exit(1);
    }

    // Initialize the offset array with random values
    srand(time(NULL));
    for (size_t i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 1000000;
    }

    // Allocate memory for the key array
    int* keys = malloc(key_size * sizeof(int));
    if (keys == NULL) {
        printf("Error: unable to allocate memory for key array\n");
        exit(1);
    }

    // Initialize the key array with random values
    srand(time(NULL));
    for (size_t i = 0; i < key_size; i++) {
        keys[i] = rand() % 1000000;
    }

    // Allocate memory for the record array
    Record* records = malloc(offset_size * sizeof(Record));
    if (records == NULL) {
        printf("Error: unable to allocate memory for record array\n");
        exit(1);
    }

    // Initialize the record array with random values
    srand(time(NULL));
    for (size_t i = 0; i < offset_size; i++) {
        records[i].key = rand() % 1000000;
    }
}

// Function to serialize the records into a binary format
void serialize_records(Record* records, size_t record_count) {
    // Open a file for writing in binary mode
    FILE* fp = fopen("records.bin", "wb");
    if (fp == NULL) {
        printf("Error: unable to open output file\n");
        exit(1);
    }

    // Write the record count to the file
    size_t written = fwrite(&record_count, sizeof(size_t), 1, fp);
    if (written != 1) {
        printf("Error: unable to write record count\n");
        exit(1);
    }

    // Write the records to the file
    for (size_t i = 0; i < record_count; i++) {
        written = fwrite(&records[i], sizeof(Record), 1, fp);
        if (written != 1) {
            printf("Error: unable to write record %zu\n", i);
            exit(1);
        }
    }

    // Close the file
    fclose(fp);
}

int main() {
    size_t offset_size = 0;
    size_t key_size = 0;

    // Read and validate the configuration file
    read_config("config.txt", &offset_size, &key_size);

    // Initialize the arrays
    init_arrays(offset_size, key_size);

    // Serialize the records into a binary format
    serialize_records(records, offset_size);

    return 0;
}
