#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define a structure to represent a record
typedef struct {
    int key;
    double weight;
    char *str;
} Record;

// Define a linked list node to manage records that exceed the size threshold
typedef struct Node {
    Record record;
    struct Node *next;
} Node;

// Function to initialize the arrays and allocate memory for records
void init_arrays(int num_offsets, int num_keys, double max_weight) {
    // Allocate memory for the offset array
    long *offsets = malloc(num_offsets * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        exit(1);
    }

    // Initialize the offset array with random values
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % max_weight;
    }

    // Allocate memory for the key array
    int *keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        exit(1);
    }

    // Initialize the key array with random values
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % max_weight;
    }

    // Allocate memory for the weight array
    double *weights = malloc(num_offsets * sizeof(double));
    if (weights == NULL) {
        printf("Error: Failed to allocate memory for weights\n");
        exit(1);
    }

    // Initialize the weight array with random values
    for (int i = 0; i < num_offsets; i++) {
        weights[i] = rand() % max_weight;
    }

    // Allocate memory for the record array
    Record *records = malloc(num_offsets * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the record array with random values
    for (int i = 0; i < num_offsets; i++) {
        records[i].key = keys[i];
        records[i].weight = weights[i];
        records[i].str = malloc(10 * sizeof(char));
        if (records[i].str == NULL) {
            printf("Error: Failed to allocate memory for string\n");
            exit(1);
        }
        sprintf(records[i].str, "Record %d", i);
    }

    // Allocate memory for the linked list node
    Node *head = malloc(sizeof(Node));
    if (head == NULL) {
        printf("Error: Failed to allocate memory for linked list\n");
        exit(1);
    }

    // Initialize the linked list node with the first record
    head->record = records[0];
    head->next = NULL;

    // Iterate over the remaining records and add them to the linked list
    for (int i = 1; i < num_offsets; i++) {
        Node *node = malloc(sizeof(Node));
        if (node == NULL) {
            printf("Error: Failed to allocate memory for linked list\n");
            exit(1);
        }
        node->record = records[i];
        node->next = head;
        head = node;
    }
}

// Function to read and validate a configuration file
void read_config(const char *filename) {
    // Open the configuration file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Failed to open configuration file\n");
        exit(1);
    }

    // Read the number of offsets, keys, and weights from the file
    int num_offsets = 0;
    int num_keys = 0;
    double max_weight = 0.0;
    if (fscanf(file, "%d %d %lf", &num_offsets, &num_keys, &max_weight) != 3) {
        printf("Error: Failed to read configuration file\n");
        exit(1);
    }

    // Close the configuration file
    fclose(file);

    // Initialize the arrays and allocate memory for records
    init_arrays(num_offsets, num_keys, max_weight);
}

// Function to serialize the records into a binary format
void serialize_records(const char *filename) {
    // Open the output file for writing
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Failed to open output file\n");
        exit(1);
    }

    // Write the number of records to the file
    int num_records = 0;
    fwrite(&num_records, sizeof(int), 1, file);

    // Iterate over the linked list and write each record to the file
    Node *node = head;
    while (node != NULL) {
        Record record = node->record;
        fwrite(&record.key, sizeof(int), 1, file);
        fwrite(&record.weight, sizeof(double), 1, file);
        fwrite(record.str, strlen(record.str), 1, file);
        num_records++;
        node = node->next;
    }

    // Close the output file
    fclose(file);
}

// Function to deserialize the records from a binary format
void deserialize_records(const char *filename) {
    // Open the input file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Failed to open input file\n");
        exit(1);
    }

    // Read the number of records from the file
    int num_records = 0;
    fread(&num_records, sizeof(int), 1, file);

    // Allocate memory for the record array
    Record *records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Iterate over the linked list and read each record from the file
    Node *node = head;
    while (node != NULL) {
        Record record = node->record;
        fread(&record.key, sizeof(int), 1, file);
        fread(&record.weight, sizeof(double), 1, file);
        fread(record.str, strlen(record.str), 1, file);
        records[num_records - 1] = record;
        node = node->next;
    }

    // Close the input file
    fclose(file);
}

// Main function to demonstrate the use of the functions
int main() {
    read_config("config.txt");
    serialize_records("output.bin");
    deserialize_records("output.bin");
    return 0;
}
