#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the hash table structure
typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
} HashTable;

// Function to allocate memory for and initialize an array of 'record' structures
Record* initRecords(size_t numRecords, int minKeyValue, int maxKeyValue) {
    // Allocate memory for the record array
    Record* records = malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        return NULL;
    }

    // Initialize the hash table
    HashTable* hashTable = malloc(sizeof(HashTable));
    if (hashTable == NULL) {
        printf("Error: Failed to allocate memory for hash table\n");
        free(records);
        return NULL;
    }
    hashTable->capacity = numRecords;
    hashTable->size = 0;
    hashTable->records = records;

    // Initialize the record values and keys
    for (int i = 0; i < numRecords; i++) {
        int keyValue = minKeyValue + rand() % (maxKeyValue - minKeyValue);
        while (hashTableLookup(hashTable, keyValue) != NULL) {
            keyValue = minKeyValue + rand() % (maxKeyValue - minKeyValue);
        }
        records[i].key = keyValue;
        records[i].offset = i * sizeof(Record);
    }

    // Return the initialized record array and hash table
    return records;
}

// Function to lookup a record in the hash table based on its key value
Record* hashTableLookup(HashTable* hashTable, int keyValue) {
    for (int i = 0; i < hashTable->size; i++) {
        if (hashTable->records[i].key == keyValue) {
            return &hashTable->records[i];
        }
    }
    return NULL;
}

// Function to add a record to the hash table
void hashTableAdd(HashTable* hashTable, Record* record) {
    if (hashTable->size == hashTable->capacity) {
        printf("Error: Hash table is full\n");
        return;
    }
    hashTable->records[hashTable->size++] = *record;
}

// Function to free the memory allocated for the record array and hash table
void destroyRecords(Record* records, size_t numRecords) {
    free(records);
}
```
This code defines a `Record` structure that contains an `int` key value and a `long` offset value. It also defines a `HashTable` structure that stores an array of `Record` structures and provides a lookup function for quick access to records based on their keys. The `initRecords` function allocates memory for the record array and initializes it with random values within a given range, while ensuring that no two records have the same key. It also initializes the hash table and returns the initialized record array and hash table.

The `hashTableLookup` function takes a `HashTable*` pointer and an `int` key value as input, and returns a pointer to the corresponding `Record` structure if it exists in the hash table, or `NULL` otherwise. The `hashTableAdd` function adds a new record to the hash table, while ensuring that the hash table is not full.

The `destroyRecords` function frees the memory allocated for the record array and hash table.

