#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    int value;
} record;

// Define the hash table structure
typedef struct {
    int size;
    int *keys;
    long *offsets;
    record **records;
} hash_table;

// Define the configuration parameters
#define MAX_RECORDS 10000
#define MIN_KEY 0
#define MAX_KEY 1000000
#define MIN_OFFSET 0
#define MAX_OFFSET 1000000000
#define RANDOM_SEED 42

// Define the mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the hash table
void init_hash_table(hash_table *ht) {
    // Allocate memory for the keys and offsets arrays
    ht->keys = (int *)malloc(sizeof(int) * MAX_RECORDS);
    ht->offsets = (long *)malloc(sizeof(long) * MAX_RECORDS);
    ht->records = (record **)malloc(sizeof(record *) * MAX_RECORDS);

    // Initialize the keys and offsets arrays with random values
    for (int i = 0; i < MAX_RECORDS; i++) {
        ht->keys[i] = MIN_KEY + rand() % (MAX_KEY - MIN_KEY);
        ht->offsets[i] = MIN_OFFSET + rand() % (MAX_OFFSET - MIN_OFFSET);
    }

    // Initialize the records array with random values
    for (int i = 0; i < MAX_RECORDS; i++) {
        ht->records[i] = (record *)malloc(sizeof(record));
        ht->records[i]->key = ht->keys[i];
        ht->records[i]->offset = ht->offsets[i];
        ht->records[i]->value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE);
    }
}

// Function to insert a new record into the hash table
void insert(hash_table *ht, int key, long offset) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the key already exists in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            // Release the mutex lock and return
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Insert the new record into the hash table
    ht->keys[ht->size] = key;
    ht->offsets[ht->size] = offset;
    ht->records[ht->size] = (record *)malloc(sizeof(record));
    ht->records[ht->size]->key = key;
    ht->records[ht->size]->offset = offset;
    ht->records[ht->size]->value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE);
    ht->size++;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to delete a record from the hash table
void delete(hash_table *ht, int key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Find the index of the record to be deleted
    int i = 0;
    while (i < ht->size && ht->keys[i] != key) {
        i++;
    }

    // Check if the record exists in the hash table
    if (i == ht->size) {
        // Release the mutex lock and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Delete the record from the hash table
    for (int j = i; j < ht->size - 1; j++) {
        ht->keys[j] = ht->keys[j + 1];
        ht->offsets[j] = ht->offsets[j + 1];
        ht->records[j] = ht->records[j + 1];
    }
    ht->size--;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a record from the hash table
record *get(hash_table *ht, int key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Find the index of the record in the hash table
    int i = 0;
    while (i < ht->size && ht->keys[i] != key) {
        i++;
    }

    // Check if the record exists in the hash table
    if (i == ht->size) {
        // Release the mutex lock and return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Return a copy of the record
    record *rec = (record *)malloc(sizeof(record));
    rec->key = ht->keys[i];
    rec->offset = ht->offsets[i];
    rec->value = ht->records[i]->value;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);

    return rec;
}

// Function to free the memory allocated for the hash table
void free_hash_table(hash_table *ht) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the keys and offsets arrays
    free(ht->keys);
    free(ht->offsets);

    // Free the memory allocated for the records array
    for (int i = 0; i < ht->size; i++) {
        free(ht->records[i]);
    }
    free(ht->records);

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}
```
This code implements a thread-safe hash table that manages memory for multiple sets of related data structures. The hash table is designed to minimize external dependencies and leverage an existing logging system for tracking memory allocations and errors. The function `init_hash_table` initializes the hash table with random values, while the functions `insert`, `delete`, and `get` manage the insertion, deletion, and retrieval of records from the hash table, respectively. The function `free_hash_table` frees the memory allocated for the hash table.

The hash table is implemented using an array of `int` keys and an array of `long` offsets, both with a maximum size defined by a configuration parameter. Each record in the hash table contains a unique `int` key, a `long` offset, and a random `int` value within a specified range. The hash table is designed to be efficient for insertion, deletion, and retrieval operations, while also ensuring thread safety and graceful handling of memory allocation failures.

The configuration parameters include:

* Maximum number of records (`max_records`)
* Key range (`min_key`, `max_key`)
* Offset range (`min_offset`, `max_offset`)
* Random seed for initializing values

The function `init_hash_table` allocates memory for the keys and offsets arrays, initializes them with random values, and sets the size of the hash table to 0. The function `insert` acquires a mutex lock, checks if the key already exists in the hash table, and inserts a new record into the hash table if it does not exist. The function `delete` finds the index of the record to be deleted, deletes it from the hash table, and frees its memory. The function `get` finds the index of the record in the hash table, returns a copy of the record, and releases the mutex lock. The function `free_hash_table` frees the memory allocated for the keys and offsets arrays, the records array, and sets the size of the hash table to 0.

The code uses pthreads library for thread safety, and implements error handling for memory allocation failures by returning NULL when a record is not found in the hash table. The function `free_hash_table` also ensures that all resources are properly deallocated upon function termination or failure.']

