#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
    char buffer[64];
    time_t timestamp;
} Record;

// Define the function to allocate memory for arrays and records
void* allocateMemory(int numElements, int minValueRange, int maxValueRange, unsigned long seed, size_t bufferLength) {
    // Calculate the total memory required for the arrays and records
    size_t totalSize = (numElements * sizeof(long)) + (numElements * sizeof(int)) + (numElements * sizeof(Record));

    // Check if the total memory allocation exceeds 2 MB
    if (totalSize > 2097152) {
        fprintf(stderr, "Error: Total memory allocation exceeds 2 MB\n");
        return NULL;
    }

    // Allocate memory for the arrays and records
    long* offsetArray = malloc(numElements * sizeof(long));
    int* keyArray = malloc(numElements * sizeof(int));
    Record* recordArray = malloc(numElements * sizeof(Record));

    // Check if memory allocation failed
    if (!offsetArray || !keyArray || !recordArray) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(offsetArray);
        free(keyArray);
        free(recordArray);
        return NULL;
    }

    // Initialize the arrays and records based on input parameters
    for (int i = 0; i < numElements; i++) {
        offsetArray[i] = rand_r(&seed) % (maxValueRange - minValueRange + 1) + minValueRange;
        keyArray[i] = rand_r(&seed) % maxValueRange;
        recordArray[i].value = rand_r(&seed) % maxValueRange;
        memset(recordArray[i].buffer, 0, bufferLength);
        recordArray[i].timestamp = time(NULL);
    }

    // Return the allocated memory
    return (void*)offsetArray;
}

// Define a function to deallocate memory for arrays and records
void deallocateMemory(void* memory) {
    // Check if the input parameter is NULL
    if (!memory) {
        fprintf(stderr, "Error: Input parameter is NULL\n");
        return;
    }

    // Cast the input parameter to the appropriate type
    long* offsetArray = (long*)memory;
    int* keyArray = (int*)offsetArray + numElements;
    Record* recordArray = (Record*)keyArray + numElements;

    // Deallocate memory for the arrays and records
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}

// Define a function to resize the arrays and records
void resizeMemory(void* memory, int newNumElements) {
    // Check if the input parameter is NULL
    if (!memory) {
        fprintf(stderr, "Error: Input parameter is NULL\n");
        return;
    }

    // Cast the input parameter to the appropriate type
    long* offsetArray = (long*)memory;
    int* keyArray = (int*)offsetArray + numElements;
    Record* recordArray = (Record*)keyArray + numElements;

    // Calculate the new total memory required for the arrays and records
    size_t newTotalSize = (newNumElements * sizeof(long)) + (newNumElements * sizeof(int)) + (newNumElements * sizeof(Record));

    // Check if the new total memory allocation exceeds 2 MB
    if (newTotalSize > 2097152) {
        fprintf(stderr, "Error: New total memory allocation exceeds 2 MB\n");
        return;
    }

    // Reallocate memory for the arrays and records
    long* newOffsetArray = realloc(offsetArray, newTotalSize);
    int* newKeyArray = (int*)newOffsetArray + numElements;
    Record* newRecordArray = (Record*)newKeyArray + numElements;

    // Check if memory reallocation failed
    if (!newOffsetArray || !newKeyArray || !newRecordArray) {
        fprintf(stderr, "Error: Memory reallocation failed\n");
        free(newOffsetArray);
        free(newKeyArray);
        free(newRecordArray);
        return;
    }

    // Initialize the new arrays and records based on input parameters
    for (int i = 0; i < newNumElements; i++) {
        newOffsetArray[i] = rand_r(&seed) % (maxValueRange - minValueRange + 1) + minValueRange;
        newKeyArray[i] = rand_r(&seed) % maxValueRange;
        newRecordArray[i].value = rand_r(&seed) % maxValueRange;
        memset(newRecordArray[i].buffer, 0, bufferLength);
        newRecordArray[i].timestamp = time(NULL);
    }

    // Update the number of elements and total memory size
    numElements = newNumElements;
    totalSize = newTotalSize;
}

// Define a function to manage memory leaks
void* leakCheck(void* memory) {
    // Check if the input parameter is NULL
    if (!memory) {
        fprintf(stderr, "Error: Input parameter is NULL\n");
        return NULL;
    }

    // Cast the input parameter to the appropriate type
