// Define the function to initialize the network
void* init_network(int num_nodes, int num_events) {
    // Allocate memory for the nodes and events
    node** nodes = (node**)malloc(num_nodes * sizeof(node));
    event** events = (event**)malloc(num_events * sizeof(event));

    // Initialize the nodes and events
    for (int i = 0; i < num_nodes; i++) {
