        events[i] = (event*)malloc(sizeof(event));
        events[i]->timestamp = 0;
        events[i]->packet_size = 0;
        events[i]->error_code = 0;
    }

    // Create a memory pool for allocating nodes and events
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    pool->nodes = nodes;
    pool->events = events;
    pool->num_nodes = num_nodes;
    pool->num_events = num_events;

    // Return a pointer to the first element of the configuration structure
    return (void*)&pool->nodes[0];
}

// Define the function to add a node to the network
void add_node(void* config, int latency, int bandwidth) {
    // Get the memory pool from the configuration
    memory_pool* pool = (memory_pool*)config;

    // Check if there is space for another node in the pool
    if (pool->num_nodes >= num_nodes) {
        return NULL;
    }

    // Allocate a new node and initialize it
    node* new_node = (node*)malloc(sizeof(node));
    new_node->discover = NULL;
    new_node->validate = NULL;
    new_node->route = NULL;
    new_node->monitor = NULL;
    new_node->latency = latency;
    new_node->bandwidth = bandwidth;
    new_node->health_status = 0;
    new_node->events = pool->events;

    // Add the new node to the pool
    pool->nodes[pool->num_nodes++] = new_node;
}

// Define the function to remove a node from the network
void remove_node(void* config, int index) {
    // Get the memory pool from the configuration
    memory_pool* pool = (memory_pool*)config;

    // Check if the index is valid
    if (index < 0 || index >= pool->num_nodes) {
        return NULL;
    }

    // Free the node and its events
    free(pool->nodes[index]);
    for (int i = 0; i < pool->num_events; i++) {
        if (pool->events[i]->node == index) {
            free(pool->events[i]);
        }
    }

    // Shift the remaining nodes and events in the pool
    for (int i = index + 1; i < pool->num_nodes; i++) {
        pool->nodes[i - 1] = pool->nodes[i];
        pool->events[i - 1] = pool->events[i];
    }

    // Decrement the number of nodes and events in the pool
    pool->num_nodes--;
}

