    // Check if the index is valid
    if (index < 0 || index >= pool->num_nodes) {
        return NULL;
    }

    // Allocate a new event and initialize it
    event* new_event = (event*)malloc(sizeof(event));
    new_event->timestamp = timestamp;
    new_event->packet_size = packet_size;
    new_event->error_code = error_code;

    // Add the new event to the node's events list
    pool->nodes[index]->events[pool->nodes[index]->num_events++] = new_event;
}

