    if (index < 0 || index >= pool->num_nodes) {
        return NULL;
    }

    // Check if the event index is valid
    if (event_index < 0 || event_index >= pool->nodes[index]->num_events) {
        return NULL;
    }

    // Free the event and shift the remaining events in the node's events list
    free(pool->nodes[index]->events[event_index]);
    for (int i = event_index + 1; i < pool->nodes[index]->num_events; i++) {
        pool->nodes[index]->events[i - 1] = pool->nodes[index]->events[i];
    }

    // Decrement the number of events in the node's events list
    pool->nodes[index]->num_events--;
