void* allocateMemory(int numElements, int minValueRange, int maxValueRange, uint64_t seed, size_t bufferLength) {
    // Calculate the total memory required for the two data structures
    size_t totalSize = (numElements * sizeof(long)) + (numElements * sizeof(customRecord));

    // Check if the total memory allocation exceeds 4 MB
    if (totalSize > 4 * 1024 * 1024) {
        fprintf(stderr, "Error: Total memory allocation exceeds 4 MB\n");
        return NULL;
    }

    // Allocate memory for the two data structures
