    if (mem == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for the two data structures\n");
        return NULL;
    }

    // Initialize the long offset values
    long* offsets = (long*) mem;
    for (int i = 0; i < numElements; i++) {
        offsets[i] = rand_r(&seed) % (maxValueRange - minValueRange + 1) + minValueRange;
