    // Allocate memory for the network service management system
    NetworkServiceManagementSystem* system = (NetworkServiceManagementSystem*)malloc(sizeof(NetworkServiceManagementSystem));
    if (!system) {
        printf("Failed to allocate memory for network service management system\n");
        return NULL;
    }

    // Initialize the number of nodes in the system
    system->num_nodes = num_nodes;

    // Allocate memory for the configurations array
