        printf("Failed to allocate memory for events linked list\n");
        free(system->configurations);
        free(system);
        return NULL;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_init(&system->mutex, NULL);

    // Return a pointer to the first element of the configurations array
    return system;
}

// Function to add a new service configuration to the network service management system
int add_service_configuration(NetworkServiceManagementSystem* system, void* state_object, ServiceDiscoveryMetadata* metadata) {
    // Check if the system is initialized
    if (!system) {
        printf("Network service management system not initialized\n");
        return -1;
    }

    // Acquire the mutex for thread safety
    pthread_mutex_lock(&system->mutex);

    // Check if the number of nodes in the system has been exceeded
    if (system->num_nodes >= num_nodes) {
        printf("Number of nodes in the system has been exceeded\n");
        pthread_mutex_unlock(&system->mutex);
        return -1;
    }

    // Allocate memory for the new configuration
    Configuration* configuration = (Configuration*)malloc(sizeof(Configuration));
    if (!configuration) {
        printf("Failed to allocate memory for new service configuration\n");
        pthread_mutex_unlock(&system->mutex);
        return -1;
    }

    // Initialize the state object and metadata for the new configuration
    configuration->state_object = state_object;
    configuration->metadata = metadata;

    // Add the new configuration to the configurations array
    system->configurations[system->num_nodes] = configuration;

    // Increment the number of nodes in the system
    system->num_nodes++;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&system->mutex);

    return 0;
}

// Function to remove a service configuration from the network service management system
int remove_service_configuration(NetworkServiceManagementSystem* system, int index) {
    // Check if the system is initialized
    if (!system) {
        printf("Network service management system not initialized\n");
        return -1;
    }

    // Acquire the mutex for thread safety
    pthread_mutex_lock(&system->mutex);

    // Check if the index is valid
    if (index < 0 || index >= system->num_nodes) {
        printf("Invalid index specified\n");
        pthread_mutex_unlock(&system->mutex);
        return -1;
    }

    // Free the memory for the configuration at the specified index
    free(system->configurations[index]);

    // Shift the configurations array to fill the gap left by the removed configuration
    for (int i = index; i < system->num_nodes - 1; i++) {
        system->configurations[i] = system->configurations[i + 1];
    }

    // Decrement the number of nodes in the system
    system->num_nodes--;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&system->mutex);

    return 0;
}

