int init_arrays(long *offset_arr, int *key_arr, size_t max_size) {
    // Check if the maximum size is valid
    if (max_size == 0) {
        return -1;
    }

    // Allocate memory for the offset array
    long *offset_ptr = malloc(sizeof(long) * max_size);
    if (!offset_ptr) {
        fprintf(stderr, "Error: Failed to allocate memory for offset array\n");
        return -1;
    }

    // Allocate memory for the key array
    int *key_ptr = malloc(sizeof(int) * max_size);
    if (!key_ptr) {
        fprintf(stderr, "Error: Failed to allocate memory for key array\n");
        free(offset_ptr);
        return -1;
    }

    // Allocate memory for the record array
    Record *record_arr = malloc(sizeof(Record) * max_size);
    if (!record_arr) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        free(offset_ptr);
        free(key_ptr);
        return -1;
    }

    // Initialize the offset and key arrays
    for (size_t i = 0; i < max_size; i++) {
        offset_arr[i] = i * sizeof(long);
        key_arr[i] = rand() % 100;
    }

    // Initialize the record array
    for (size_t i = 0; i < max_size; i++) {
        record_arr[i].key = key_arr[i];
    }

    // Check if the total memory usage exceeds the maximum size
    size_t total_mem_usage = sizeof(long) * max_size + sizeof(int) * max_size + sizeof(Record) * max_size;
    if (total_mem_usage > max_size) {
        fprintf(stderr, "Error: Total memory usage exceeds maximum size\n");
        free(offset_ptr);
        free(key_ptr);
        free(record_arr);
        return -1;
    }

    // Return the initialized arrays
    *offset_ptr = offset_arr;
    *key_ptr = key_arr;
    *record_arr = record_arr;

    return 0;
}
