// Define structure for user profile
typedef struct UserProfile {
    char *name;
    int age;
    LinkedList interests;
} UserProfile;

// Define linked list data structure for interests
typedef struct LinkedList {
    void *data;
    struct LinkedList *next;
} LinkedList;

// Custom allocator for interest lists
void *interest_alloc(size_t size) {
    // Allocate memory for the interest list
    void *ptr = malloc(size);

    // Initialize the interest list with a default capacity
    LinkedList *list = (LinkedList *)ptr;
    list->data = NULL;
    list->next = NULL;

    return ptr;
}

// Custom deallocator for interest lists
void interest_dealloc(void *ptr) {
    // Free the memory allocated for the interest list
    LinkedList *list = (LinkedList *)ptr;
    free(list);
}

// Function to read user profiles from a CSV file
UserProfile *read_profiles(const char *filename) {
    // Open the CSV file and check for errors
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return NULL;
    }

    // Initialize a dynamic array of user profiles
    UserProfile **profiles = malloc(sizeof(UserProfile *) * 10);
    int num_profiles = 0;

    // Read the CSV file and parse each line
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Parse the fields in the line
        char *name = strtok(line, ",");
        int age = atoi(strtok(NULL, ","));
        LinkedList *interests = interest_alloc(sizeof(LinkedList));
        while (strtok(NULL, ",") != NULL) {
            // Add each interest to the linked list
            char *interest = strdup(strtok(NULL, ","));
            interests->data = interest;
            interests->next = interest_alloc(sizeof(LinkedList));
        }

        // Create a new user profile and add it to the array
        UserProfile *profile = malloc(sizeof(UserProfile));
        profile->name = name;
        profile->age = age;
        profile->interests = interests;
        profiles[num_profiles++] = profile;
    }

    // Close the CSV file and return the array of user profiles
    fclose(file);
    return profiles;
}

// Function to search for users based on age or name
UserProfile *search_users(const char *name, int age) {
    // Initialize a binary search algorithm
    UserProfile **profiles = read_profiles("user_profiles.csv");
    if (profiles == NULL) {
        printf("Error: unable to read user profiles\n");
        return NULL;
    }

    // Define the comparison function for name searches
    int compare_names(const void *a, const void *b) {
        UserProfile *profile1 = (UserProfile *)a;
        UserProfile *profile2 = (UserProfile *)b;
        return strcasecmp(profile1->name, profile2->name);
    }

    // Define the comparison function for age searches
    int compare_ages(const void *a, const void *b) {
        UserProfile *profile1 = (UserProfile *)a;
        UserProfile *profile2 = (UserProfile *)b;
        return profile1->age - profile2->age;
    }

    // Perform the search based on the specified criteria
    if (name != NULL) {
        qsort(profiles, num_profiles, sizeof(UserProfile *), compare_names);
        UserProfile key = { name, 0, NULL };
        int index = bsearch(&key, profiles, num_profiles, sizeof(UserProfile *), compare_names);
        if (index >= 0) {
            return profiles[index];
        } else {
            printf("Error: unable to find user with name %s\n", name);
            return NULL;
        }
    } else if (age > 0) {
        qsort(profiles, num_profiles, sizeof(UserProfile *), compare_ages);
        UserProfile key = { "", age, NULL };
        int index = bsearch(&key, profiles, num_profiles, sizeof(UserProfile *), compare_ages);
        if (index >= 0) {
            return profiles[index];
        } else {
            printf("Error: unable to find user with age %d\n", age);
            return NULL;
        }
    } else {
        printf("Error: no search criteria specified\n");
        return NULL;
    }
}

// Function to compress the interest list for a user profile
void compress_interests(UserProfile *profile) {
    // Check if the interest list can be compressed
    LinkedList *list = profile->interests;
    while (list != NULL && list->next != NULL) {
        char *interest1 = (char *)list->data;
        char *interest2 = (char *)list->next->data;
        if (strcasecmp(interest1, interest2) == 0) {
            // Compress the interest list by replacing duplicates with references
            LinkedList *compressed_list = interest_alloc(sizeof(LinkedList));
            compressed_list->data = interest1;
            compressed_list->next = NULL;
            profile->interests = compressed_list;
            return;
        }
        list = list->next;
    }
}

// Main function to demonstrate the use of the search and compression functions
int main() {
    // Read user profiles from a CSV file
    UserProfile **profiles = read_profiles("user_profiles.csv");
    if (profiles == NULL) {
        printf("Error: unable to read user profiles\n");
        return 1;
    }

    // Search for users based on age or name
    UserProfile *profile = search_users("John", 30);
    if (profile != NULL) {
        printf("Found user with name John and age 30: %s\n", profile->name);
    } else {
        printf("Error: unable to find user with name John and age 30\n");
    }

    // Compress the interest list for a user profile
    compress_interests(profile);

    return 0;
}
