// Define the configuration parameters for the hash table
#define MAX_RECORDS 1000000
#define KEY_RANGE 1000000
#define CACHE_SIZE 10000
#define MIN_HASH_TABLE_SIZE 10000
#define MAX_HASH_TABLE_SIZE 1000000

// Define the data structures for the hash table and cache
typedef struct record {
    int key;
    long offset;
    int value;
} record;

typedef struct hash_table {
    int size;
    int num_records;
    record** records;
} hash_table;

typedef struct cache {
    int size;
    int num_records;
    record* records[CACHE_SIZE];
} cache;

// Define the custom hash function for the hash table
unsigned long hash(int key) {
    return (key % KEY_RANGE) * 1000000 + (key / KEY_RANGE);
}

// Define the functions for managing memory and thread safety
void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

void deallocate_memory(void* ptr) {
    free(ptr);
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the functions for managing the hash table and cache
hash_table* create_hash_table() {
    // Allocate memory for the hash table
    hash_table* table = allocate_memory(sizeof(hash_table));
    if (!table) {
        return NULL;
    }

    // Initialize the hash table
    table->size = MIN_HASH_TABLE_SIZE;
    table->num_records = 0;
    table->records = allocate_memory(sizeof(record*) * table->size);
    if (!table->records) {
        deallocate_memory(table);
        return NULL;
    }

    // Initialize the cache
    cache* cache = allocate_memory(sizeof(cache));
    if (!cache) {
        deallocate_memory(table->records);
        deallocate_memory(table);
        return NULL;
    }
    cache->size = CACHE_SIZE;
    cache->num_records = 0;

    // Return the initialized hash table and cache
    return table;
}

void destroy_hash_table(hash_table* table) {
    // Deallocate memory for the hash table and its records
    deallocate_memory(table->records);
    deallocate_memory(table);

    // Deallocate memory for the cache and its records
    deallocate_memory(cache);
}

void insert_record(hash_table* table, int key, long offset, int value) {
    // Acquire a lock on the hash table to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the record already exists in the cache
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache->records[i]->key == key) {
            // Update the record in the cache
            cache->records[i]->offset = offset;
            cache->records[i]->value = value;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Check if the hash table needs to be resized
    if (table->num_records >= table->size) {
        // Resize the hash table and cache
        int new_size = table->size * 2;
        record** new_records = allocate_memory(sizeof(record*) * new_size);
        if (!new_records) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        for (int i = 0; i < table->num_records; i++) {
            new_records[i] = table->records[i];
        }
        deallocate_memory(table->records);
        table->size = new_size;
        table->records = new_records;
    }

    // Insert the record into the hash table and cache
    int index = hash(key) % table->size;
    while (table->records[index] != NULL && table->records[index]->key != key) {
        index++;
        if (index == table->size) {
            index = 0;
        }
    }
    record* new_record = allocate_memory(sizeof(record));
    if (!new_record) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;
    table->records[index] = new_record;
    cache->records[cache->num_records++] = new_record;
    table->num_records++;

    // Release the lock on the hash table
    pthread_mutex_unlock(&mutex);
}

void delete_record(hash_table* table, int key) {
