// Custom memory pool implementation
struct MemoryPool {
    size_t capacity;
    size_t used;
    void* buffer;
};

void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
}

void freeMemoryPool(struct MemoryPool* pool) {
    free(pool->buffer);
}

void* allocateFromPool(struct MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        return NULL;
    }
    void* ptr = (char*)pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

// Custom memory allocation function
void* allocateMemory(size_t size, struct MemoryPool* pool) {
    if (pool != NULL) {
        return allocateFromPool(pool, size);
    } else {
        return malloc(size);
    }
}

// Custom memory deallocation function
void freeMemory(void* ptr, struct MemoryPool* pool) {
    if (ptr == NULL) {
        return;
    }
    if (pool != NULL) {
        freeFromPool(pool, ptr);
    } else {
        free(ptr);
    }
}

// Custom memory reallocation function
void* reallocateMemory(void* ptr, size_t newSize, struct MemoryPool* pool) {
    if (ptr == NULL) {
        return allocateMemory(newSize, pool);
    } else if (pool != NULL) {
        void* newPtr = allocateFromPool(pool, newSize);
        memcpy(newPtr, ptr, newSize);
        freeFromPool(pool, ptr);
        return newPtr;
    } else {
        return realloc(ptr, newSize);
    }
}

