// Custom allocator function for debugging purposes
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Function to dynamically allocate memory for arrays and initialize them with random values
void init_arrays(int num_records, int offset_range, int key_range) {
    // Allocate memory for the three arrays
    long* offsets = (long*)custom_alloc(num_records * sizeof(long));
    int* keys = (int*)custom_alloc(num_records * sizeof(int));
    record* records = (record*)custom_alloc(num_records * sizeof(record));

    // Initialize the arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;
        records[i].value = rand();
        strcpy(records[i].name, "Name");
        records[i].score = (double)rand() / RAND_MAX;
    }

    // Create a linked list of the records for insertion and deletion operations
    record* head = NULL;
    record* current = NULL;
    for (int i = 0; i < num_records; i++) {
        if (head == NULL) {
            head = &records[i];
            current = head;
        } else {
            current->next = &records[i];
            current = current->next;
        }
    }

    // Free the allocated memory when done
    free(offsets);
    free(keys);
    free(records);
}

// Function to traverse the linked list in both forward and backward directions
void traverse_list(record* head) {
    if (head == NULL) {
        return;
    }
    record* current = head;
    while (current != NULL) {
        printf("Offset: %ld, Key: %d, Value: %d, Name: %s, Score: %.2f\n", current->offset, current->key, current->value, current->name, current->score);
        current = current->next;
    }
}

// Function to insert a new record into the linked list
void insert_record(record* head, long offset, int key, int value) {
    if (head == NULL) {
        return;
    }
    record* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    record* new_record = (record*)custom_alloc(sizeof(record));
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;
    strcpy(new_record->name, "Name");
    new_record->score = (double)rand() / RAND_MAX;
    current->next = new_record;
}

// Function to delete a record from the linked list
void delete_record(record* head, long offset, int key) {
    if (head == NULL) {
        return;
    }
    record* current = head;
    while (current != NULL && current->offset != offset && current->key != key) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    record* previous = current->previous;
    record* next = current->next;
    if (previous == NULL) {
        head = next;
    } else {
        previous->next = next;
    }
    free(current);
