#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Custom memory pool for allocating index nodes and records
struct MemoryPool {
    void* data;
    size_t capacity;
    size_t used;
};

// Index node structure
struct index_node {
    char* key;
    int id;
    struct index_node* next;
};

// Record structure
struct record {
    int value;
};

// Function to manage memory allocation and initialization for the dynamic data storage structure and database indexing system
void init_data(int range, size_t capacity, size_t initial_capacity) {
    // Allocate memory for the index nodes array
    struct MemoryPool* index_nodes = malloc(sizeof(struct MemoryPool));
    if (!index_nodes) {
        printf("Error: Failed to allocate memory for index nodes\n");
        return;
    }
    index_nodes->data = calloc(capacity, sizeof(struct index_node));
    if (!index_nodes->data) {
        printf("Error: Failed to allocate memory for index node data\n");
        free(index_nodes);
        return;
    }
    index_nodes->capacity = capacity;
    index_nodes->used = 0;

    // Allocate memory for the records array
    struct MemoryPool* records = malloc(sizeof(struct MemoryPool));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(index_nodes);
        return;
    }
    records->data = calloc(capacity, sizeof(struct record));
    if (!records->data) {
        printf("Error: Failed to allocate memory for record data\n");
        free(records);
        free(index_nodes);
        return;
    }
    records->capacity = capacity;
    records->used = 0;

    // Allocate memory for the offsets array
    size_t* offsets = malloc(sizeof(size_t) * initial_capacity);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        free(records->data);
        free(records);
        free(index_nodes->data);
        free(index_nodes);
        return;
    }

    // Allocate memory for the keys array
    int* keys = malloc(sizeof(int) * initial_capacity);
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        free(records->data);
        free(records);
        free(index_nodes->data);
        free(index_nodes);
        return;
    }

    // Initialize the offsets and keys arrays with sequential values starting from 0
    for (size_t i = 0; i < initial_capacity; ++i) {
        offsets[i] = i * sizeof(struct record);
        keys[i] = i;
    }

    // Initialize the index nodes and records with random values within the specified range
    for (size_t i = 0; i < initial_capacity; ++i) {
        struct index_node* node = &index_nodes->data[i];
        node->key = malloc(strlen("random_key") + 1);
        if (!node->key) {
            printf("Error: Failed to allocate memory for index key\n");
            free(keys);
            free(offsets);
            free(records->data);
            free(records);
            free(index_nodes->data);
            free(index_nodes);
            return;
        }
        strcpy(node->key, "random_key");
        node->id = i;
        node->next = NULL;

        struct record* rec = &records->data[i];
        rec->value = rand() % range + 1;
    }

