#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <mutex>

// Custom allocator function for debugging purposes
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Custom deallocator function for debugging purposes
void custom_free(void* ptr) {
    free(ptr);
}

// Session data structure
struct session {
    char* id; // Unique session ID
    time_t last_activity; // Timestamp of the last activity
    struct device_list* devices; // List of logged-in devices
    int timeout; // Session timeout value
};

// Device list data structure
struct device_list {
    char* device_id; // Unique device ID
    time_t last_activity; // Timestamp of the last activity
    struct device_list* next; // Pointer to the next device in the list
};

// Mutex for synchronizing access to the session data structure
std::mutex session_mutex;

// Initialize the session data structure
void init_session(struct session* session) {
    session->id = NULL;
    session->last_activity = 0;
    session->devices = NULL;
    session->timeout = 0;
}

// Add a new device to the list of logged-in devices
void add_device(struct session* session, char* device_id) {
    struct device_list* new_device = (struct device_list*)custom_alloc(sizeof(struct device_list));
    new_device->device_id = device_id;
    new_device->last_activity = time(NULL);
    new_device->next = NULL;

    // Lock the mutex to synchronize access to the session data structure
    std::lock_guard<std::mutex> lock(session_mutex);

    if (session->devices == NULL) {
        session->devices = new_device;
    } else {
        struct device_list* current = session->devices;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_device;
    }
}

// Remove a device from the list of logged-in devices
void remove_device(struct session* session, char* device_id) {
    // Lock the mutex to synchronize access to the session data structure
    std::lock_guard<std::mutex> lock(session_mutex);

    struct device_list* current = session->devices;
    while (current != NULL && strcmp(current->device_id, device_id) != 0) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    struct device_list* previous = current;
    while (previous->next != NULL && strcmp(previous->next->device_id, device_id) == 0) {
        previous = previous->next;
    }
    if (previous->next == NULL) {
        return;
    }
    previous->next = current->next;
}

// Update the last activity timestamp for a session
void update_last_activity(struct session* session) {
    // Lock the mutex to synchronize access to the session data structure
    std::lock_guard<std::mutex> lock(session_mutex);

    session->last_activity = time(NULL);
}

// Check if a session has expired based on the timeout value
int check_expired(struct session* session) {
    // Lock the mutex to synchronize access to the session data structure
    std::lock_guard<std::mutex> lock(session_mutex);

    return (time(NULL) - session->last_activity) > session->timeout;
}

// Serialize the session data to a file for persistence
void serialize_session(struct session* session, FILE* fp) {
    // Lock the mutex to synchronize access to the session data structure
    std::lock_guard<std::mutex> lock(session_mutex);

    fprintf(fp, "%s\n", session->id);
    fprintf(fp, "%ld\n", session->last_activity);
    struct device_list* current = session->devices;
    while (current != NULL) {
        fprintf(fp, "%s\n", current->device_id);
        current = current->next;
    }
}

// Deserialize the session data from a file for retrieval
void deserialize_session(struct session* session, FILE* fp) {
    // Lock the mutex to synchronize access to the session data structure
    std::lock_guard<std::mutex> lock(session_mutex);

    char line[1024];
    while (fgets(line, 1024, fp) != NULL) {
        if (strcmp(line, "\n") == 0) {
            break;
        }
        if (session->id == NULL) {
            session->id = strdup(line);
        } else {
            add_device(session, line);
        }
    }
}

// Clean up all allocated resources and closed files when the function is done
void cleanup() {
    // Lock the mutex to synchronize access to the session data structure
    std::lock_guard<std::mutex> lock(session_mutex);

    struct device_list* current = session->devices;
    while (current != NULL) {
        struct device_list* next = current->next;
        custom_free(current);
        current = next;
    }
    custom_free(session->id);
}
