        } else if (strcmp(word, "Numbers") == 0) {
            numbers++;
        } else if (strcmp(word, "Deuteronomy") == 0) {
            deuteronomy++;
        }
    }

    // Log the number of times each book from the Old Testament appears in the text
    printf("Genesis: %d\n", genesis);
    printf("Exodus: %d\n", exodus);
    printf("Leviticus: %d\n", leviticus);
    printf("Numbers: %d\n", numbers);
    printf("Deuteronomy: %d\n", deuteronomy);
}

// Define a function to count the number of references to books from the Old Testament in a given text
int count_book_mentions(const char* text) {
    // Initialize a counter for each book in the Old Testament
    int genesis = 0, exodus = 0, leviticus = 0, numbers = 0, deuteronomy = 0;

    // Iterate over each word in the text
    for (const char* word = strtok(text, " "); word != NULL; word = strtok(NULL, " ")) {
        // Check if the current word is a recognized book from the Old Testament
        if (strcmp(word, "Genesis") == 0) {
            genesis++;
        } else if (strcmp(word, "Exodus") == 0) {
            exodus++;
        } else if (strcmp(word, "Leviticus") == 0) {
            leviticus++;
        } else if (strcmp(word, "Numbers") == 0) {
            numbers++;
        } else if (strcmp(word, "Deuteronomy") == 0) {
            deuteronomy++;
        }
    }

    // Return the total number of references to books from the Old Testament in the text
    return genesis + exodus + leviticus + numbers + deuteronomy;
}

