    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (int_arr[i] == int_arr[j]) {
                return false;
            }
        }
    }

    // Check if all elements in the record array are within the specified range
    for (int i = 0; i < m; i++) {
        if (record_arr[i].value < min_value || record_arr[i].value > max_value) {
