        }
    }

    // Check if all elements in the record array are unique
    for (int i = 0; i < m - 1; i++) {
        for (int j = i + 1; j < m; j++) {
            if (record_arr[i].value == record_arr[j].value) {
                return false;
            }
        }
    }

    // If all checks pass, return true
    return true;
}

