struct Record {
    int_value: i32,
}

fn main() {
    let args = std::env::args().collect::<Vec<String>>();
    if args.len() < 4 {
        println!("Usage: {} n m min_value max_value", args[0]);
        return;
    }

    let n = args[1].parse::<usize>().unwrap();
    let m = args[2].parse::<usize>().unwrap();
    let min_value = args[3].parse::<i32>().unwrap();
    let max_value = args[4].parse::<i32>().unwrap();

    if n < 0 || m < 0 {
        println!("Invalid input: n and m must be non-negative");
        return;
    }

    if min_value > max_value {
        println!("Invalid input: min_value cannot be greater than max_value");
        return;
    }

    let start = Instant::now();
    let mut keys = vec![0; n];
    let mut offsets = vec![0; n];
    let mut records = vec![Record { int_value: 0 }; m];

    for i in 0..n {
        keys[i] = (min_value + i as i32) % max_value;
    }

    for i in 0..m {
        records[i].int_value = rand::thread_rng().gen_range(min_value, max_value);
    }

    let mut book_counts: HashMap<String, usize> = HashMap::new();

    for i in 0..n {
        let offset = offsets[i];
        let key = keys[i];
        let record = records[key as usize];
        if record.int_value >= min_value && record.int_value <= max_value {
            book_counts.entry(record.int_value).or_insert(0);
            book_counts.get_mut(&record.int_value).unwrap() += 1;
        }
    }

    let end = Instant::now();
    println!("Time elapsed: {:?}", end - start);

    for (book, count) in &book_counts {
        println!("Book '{}' appears {} times.", book, count);
    }
}
