#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the structure for time-series data
typedef struct timeseries {
    long long timestamp; // Timestamp in nanoseconds
    int num_samples; // Number of samples
    bool valid; // Flag indicating whether the data is valid
    float *samples; // Pointer to an array of samples (if any)
} timeseries;

// Define the structure for metadata information
typedef struct metadata {
    char sensor_id[16]; // Sensor ID
    char location[32]; // Location
    char units[8]; // Units
} metadata;

// Function to initialize a dynamic collection of time-series data within a constrained environment
timeseries* init_timeseries(int num_timeseries, int max_samples, int resolution) {
    // Allocate memory for the timeseries array and metadata structures
    timeseries *ts = (timeseries*)malloc(num_timeseries * sizeof(timeseries));
    metadata *md = (metadata*)malloc(num_timeseries * sizeof(metadata));

    // Initialize each timeseries structure with default values
    for (int i = 0; i < num_timeseries; i++) {
        ts[i].timestamp = 0;
        ts[i].num_samples = 0;
        ts[i].valid = false;
        ts[i].samples = NULL;
        md[i].sensor_id[0] = '\0';
        md[i].location[0] = '\0';
        md[i].units[0] = '\0';
    }

    // Allocate memory for each timeseries structure's sample array (if necessary)
    for (int i = 0; i < num_timeseries; i++) {
        if (max_samples > 0) {
            ts[i].samples = (float*)malloc(max_samples * sizeof(float));
        }
    }

    // Initialize the timestamp resolution and return a pointer to the first element of the timeseries array
    for (int i = 0; i < num_timeseries; i++) {
        ts[i].timestamp = 1;
        while (ts[i].timestamp % resolution != 0) {
            ts[i].timestamp++;
        }
    }
    return ts;
}
```
