Record* allocate_records(int num_records, int min_value, int max_value) {
    // Check if the input parameters are valid
    if (num_records <= 0 || min_value < 0 || max_value < 0) {
        return NULL;
    }

    // Calculate the total size of memory needed to store the records
    int record_size = sizeof(Record);
    int total_size = num_records * record_size;

    // Allocate memory for the dataset using malloc()
    Record* dataset = (Record*)malloc(total_size);
    if (!dataset) {
        return NULL;
    }

    // Initialize each record in the dataset with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int key = rand() % (max_value - min_value + 1) + min_value;
        long value = rand() % (max_value - min_value + 1) + min_value;
        dataset[i].key = key;
        dataset[i].value = value;
    }

    return dataset;
}

// Define a function to free the memory allocated for the dynamic dataset of records
void free_records(Record* dataset) {
    if (dataset) {
        free(dataset);
    }
}
