String** generateStrings(size_t numStrings, size_t minLen, size_t maxLen) {
    // Check for invalid inputs
    if (numStrings == 0 || minLen > maxLen) {
        return NULL;
    }

    // Allocate memory for the array of strings
    String** strings = malloc(sizeof(String*) * numStrings);
    if (!strings) {
        return NULL;
    }

    // Initialize each string in the array with a random length within the specified range
    size_t i;
    for (i = 0; i < numStrings; i++) {
        strings[i] = malloc(sizeof(String));
        if (!strings[i]) {
            freeStrings(strings, i);
            return NULL;
        }
        strings[i]->len = minLen + rand() % (maxLen - minLen + 1);
        strings[i]->str = malloc(strings[i]->len * sizeof(char));
        if (!strings[i]->str) {
            freeStrings(strings, i);
            return NULL;
        }
        memset(strings[i]->str, 'a' + rand() % 26, strings[i]->len - 1);
        strings[i]->str[strings[i]->len - 1] = '\0';
    }

    // Return the array of strings
    return strings;
}

// Define a function to free memory allocated for the dynamic array of strings
void freeStrings(String** strings, size_t numStrings) {
    size_t i;
    for (i = 0; i < numStrings; i++) {
        if (strings[i]) {
            free(strings[i]->str);
            free(strings[i]);
        }
    }
    free(strings);
}
