void allocate_memory(int offset_size, int key_size, int record_size, int event_size) {
    // Validate the input sizes
    if (offset_size <= 0 || key_size <= 0 || record_size <= 0 || event_size <= 0) {
        fprintf(stderr, "Error: Invalid input size\n");
        exit(1);
