        exit(1);
    }

    // Allocate memory for the key array
    struct key *key_array = custom_malloc(sizeof(struct key) * key_size);
    if (!key_array) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(1);
    }

    // Allocate memory for the record array
    struct record *record_array = custom_malloc(sizeof(struct record) * record_size);
    if (!record_array) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(1);
    }

    // Allocate memory for the event array
    struct event *event_array = custom_malloc(sizeof(struct event) * event_size);
    if (!event_array) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(1);
    }

