    for (int i = 0; i < offset_size; i++) {
        offset_array[i].offset = rand() % 1000;
    }

    // Initialize the key array with random values
    for (int i = 0; i < key_size; i++) {
        key_array[i].key = rand() % 1000;
    }

    // Initialize the record array with random values within a specified range
    for (int i = 0; i < record_size; i++) {
        record_array[i].value = rand() % 1000;
    }

    // Initialize the event array with random descriptions and associated records
    for (int i = 0; i < event_size; i++) {
        char *description = custom_malloc(sizeof(char) * 256);
        if (!description) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            exit(1);
        }
        sprintf(description, "Event %d", i + 1);
        event_array[i].description = description;
        event_array[i].record = record_array[rand() % record_size];
    }
}

int main() {
    // Get the input sizes from the user
    int offset_size, key_size, record_size, event_size;
    printf("Enter the size of the offset array: ");
    scanf("%d", &offset_size);
    printf("Enter the size of the key array: ");
    scanf("%d", &key_size);
    printf("Enter the size of the record array: ");
    scanf("%d", &record_size);
