// Struct for event records
typedef struct event {
    double measurement_values[10];
    char label;
    time_t timestamp;
    char* description;
} event_t;

// Struct for linked list nodes
typedef struct node {
    event_t* event;
    struct node* next;
} node_t;

// Function to dynamically allocate memory for and initialize interconnected data structures
void init_data_structures(int num_measurement_values, int num_labels, int num_events, char* log_file_path) {
    // Allocate memory for the measurement values array
    double* measurement_values = (double*)custom_malloc(num_measurement_values * sizeof(double));
    if (!measurement_values) {
        fprintf(stderr, "Error: Failed to allocate memory for measurement values\n");
        return;
    }

    // Allocate memory for the labels array
    char* labels = (char*)custom_malloc(num_labels * sizeof(char));
    if (!labels) {
        fprintf(stderr, "Error: Failed to allocate memory for labels\n");
        return;
    }

    // Allocate memory for the events array
    event_t* events = (event_t*)custom_malloc(num_events * sizeof(event_t));
    if (!events) {
        fprintf(stderr, "Error: Failed to allocate memory for events\n");
        return;
    }

    // Allocate memory for the linked list nodes
    node_t* nodes = (node_t*)custom_malloc(num_events * sizeof(node_t));
    if (!nodes) {
        fprintf(stderr, "Error: Failed to allocate memory for linked list nodes\n");
        return;
    }

    // Initialize the measurement values array
    for (int i = 0; i < num_measurement_values; i++) {
        measurement_values[i] = 0.0;
    }

    // Initialize the labels array
    for (int i = 0; i < num_labels; i++) {
        labels[i] = 'A' + i % 26;
    }

    // Initialize the events array
    for (int i = 0; i < num_events; i++) {
        events[i].measurement_values[0] = measurement_values[i];
        events[i].label = labels[i % num_labels];
        events[i].timestamp = time(NULL);
        events[i].description = NULL;
    }

    // Initialize the linked list nodes
    for (int i = 0; i < num_events; i++) {
        nodes[i].event = &events[i];
        nodes[i].next = NULL;
    }

    // Read the log file and parse its lines into events
    FILE* log_file = fopen(log_file_path, "r");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), log_file)) {
        // Parse the line into an event record
        event_t* event = (event_t*)custom_malloc(sizeof(event_t));
        if (!event) {
            fprintf(stderr, "Error: Failed to allocate memory for event\n");
            return;
        }

        // Initialize the event record
        event->measurement_values[0] = 0.0;
        event->label = 'A';
        event->timestamp = time(NULL);
        event->description = NULL;

        // Parse the line into the event record
        char* token = strtok(line, " ");
        int i = 0;
        while (token != NULL) {
            if (i == 0) {
                event->measurement_values[0] = atof(token);
            } else if (i == 1) {
                event->label = token[0];
            } else if (i == 2) {
                event->timestamp = atol(token);
            } else {
                // Allocate memory for the description string
                char* description = (char*)custom_malloc((strlen(token) + 1) * sizeof(char));
                if (!description) {
                    fprintf(stderr, "Error: Failed to allocate memory for event description\n");
                    return;
                }

                // Copy the token into the description string
                strcpy(description, token);
                event->description = description;
            }

            i++;
            token = strtok(NULL, " ");
        }

        // Add the event record to the linked list
        node_t* new_node = (node_t*)custom_malloc(sizeof(node_t));
        if (!new_node) {
            fprintf(stderr, "Error: Failed to allocate memory for linked list node\n");
            return;
        }

        new_node->event = event;
        new_node->next = NULL;

        // Add the new node to the end of the linked list
        node_t* current_node = nodes;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }

        current_node->next = new_node;
    }

    // Filter out events with measurement values below the threshold value
    node_t* current_node = nodes;
    while (current_node != NULL) {
        if (current_node->event->measurement_values[0] < THRESHOLD_VALUE) {
            // Remove the event record from the linked list
            node_t* previous_node = current_node;
            current_node = current_node->next;
            free(previous_node);
        } else {
            current_node = current_node->next;
        }
    }

    // Serialize the filtered data to JSON format
    json_object* root = json_object_new_array();
    node_t* current_node = nodes;
    while (current_node != NULL) {
        json_object* event_json = json_object_new_object();
        json_object_object_add(event_json, "measurement_values", json_object_new_double(current_node->event->measurement_values[0]));
        json_object_object_add(event_json, "label", json_object_new_string(&current_node->event->label));
        json_object_object_add(event_json, "timestamp", json_object_new_int64(current_node->event->timestamp));
        json_object_object_add(event_json, "description", json_object_new_string(current_node->event->description));
        json_object_array_add(root, event_json);
        current_node = current_node->next;
    }

    // Output the filtered data to stdout
    printf("%s\n", json_object_to_json_string_ext(root, JSON_C_TO_STRING_PRETTY));

    // Clean up memory
    json_object_put(root);
}
