// Define a struct to represent a transaction
struct Transaction {
    char *id;
    int age;
    int num_transactions_3s;
    float weighted_sum;
};

// Define a function to generate a random string based on a prefix and length range
char* generate_random_string(const char *prefix, int min_len, int max_len) {
    // Generate a random integer between the minimum and maximum lengths
    int len = rand() % (max_len - min_len + 1) + min_len;

    // Allocate memory for the string
    char *str = malloc(len + 1);
    if (!str) {
        return NULL;
    }

    // Generate a random prefix and append it to the string
    strcpy(str, prefix);
    for (int i = 0; i < len - strlen(prefix); i++) {
        str[strlen(prefix) + i] = 'a' + rand() % 26;
    }

    // Add a null terminator to the end of the string
    str[len] = '\0';

    return str;
}

// Define a function to allocate memory for a dynamic array of strings
char** allocate_string_array(int num_strings) {
    // Allocate memory for the array of pointers
    char **arr = malloc(num_strings * sizeof(char*));
    if (!arr) {
        return NULL;
    }

    // Initialize each pointer in the array to NULL
    for (int i = 0; i < num_strings; i++) {
        arr[i] = NULL;
    }

    return arr;
}

// Define a function to free memory allocated for a dynamic array of strings
void free_string_array(char **arr, int num_strings) {
    // Free each string in the array
    for (int i = 0; i < num_strings; i++) {
        if (arr[i]) {
            free(arr[i]);
        }
    }

    // Free the array of pointers
    free(arr);
}

// Define a function to filter transactions based on criteria
struct Transaction* filter_transactions(struct Transaction *transactions, int num_transactions, int min_age, int max_num_3s, float min_weighted_sum) {
    // Allocate memory for the filtered transaction array
    struct Transaction *filtered_transactions = malloc(num_transactions * sizeof(struct Transaction));
    if (!filtered_transactions) {
        return NULL;
    }

    // Initialize the number of filtered transactions to 0
    int num_filtered_transactions = 0;

    // Iterate over each transaction and filter based on criteria
    for (int i = 0; i < num_transactions; i++) {
        struct Transaction *transaction = &transactions[i];

        // Check if the transaction meets the minimum age requirement
        if (transaction->age >= min_age) {
            // Check if the transaction meets the maximum number of transactions in the past 3 seconds requirement
            if (transaction->num_transactions_3s <= max_num_3s) {
                // Check if the transaction meets the minimum weighted sum requirement
                if (transaction->weighted_sum >= min_weighted_sum) {
                    // Add the transaction to the filtered array
                    filtered_transactions[num_filtered_transactions++] = *transaction;
                }
            }
        }
    }

    // Reallocate memory for the filtered transaction array to match the number of filtered transactions
    struct Transaction *reallocated_filtered_transactions = realloc(filtered_transactions, num_filtered_transactions * sizeof(struct Transaction));
    if (!reallocated_filtered_transactions) {
        free(filtered_transactions);
        return NULL;
    }

    // Return the filtered transaction array
    return reallocated_filtered_transactions;
}

// Define a function to update metrics and return the maximum weighted sum and corresponding transaction ID
struct Transaction* update_metrics(struct Transaction *transactions, int num_transactions) {
    // Initialize the maximum weighted sum to 0
    float max_weighted_sum = 0;

    // Initialize the corresponding transaction ID to NULL
    char *max_transaction_id = NULL;

    // Iterate over each transaction and update metrics
    for (int i = 0; i < num_transactions; i++) {
        struct Transaction *transaction = &transactions[i];

        // Update the maximum weighted sum if necessary
        if (transaction->weighted_sum > max_weighted_sum) {
            max_weighted_sum = transaction->weighted_sum;
            max_transaction_id = transaction->id;
        }
    }

    // Allocate memory for the updated metrics struct
    struct Transaction *updated_metrics = malloc(sizeof(struct Transaction));
    if (!updated_metrics) {
        return NULL;
    }

    // Set the maximum weighted sum and corresponding transaction ID in the updated metrics struct
    updated_metrics->weighted_sum = max_weighted_sum;
    updated_metrics->id = max_transaction_id;

    return updated_metrics;
}

// Define a function to manage a dynamic array of strings based on user-defined criteria
struct Transaction* manage_strings(const char *prefix, int min_len, int max_len, int num_transactions, int min_age, int max_num_3s, float min_weighted_sum) {
    // Allocate memory for the dynamic array of strings
    char **arr = allocate_string_array(num_transactions);
    if (!arr) {
        return NULL;
    }

    // Generate a random string based on the prefix and length range for each transaction
    for (int i = 0; i < num_transactions; i++) {
        arr[i] = generate_random_string(prefix, min_len, max_len);
        if (!arr[i]) {
            free_string_array(arr, num_transactions);
            return NULL;
        }
    }

    // Filter transactions based on the specified criteria
    struct Transaction *filtered_transactions = filter_transactions((struct Transaction *) arr, num_transactions, min_age, max_num_3s, min_weighted_sum);
    if (!filtered_transactions) {
        free_string_array(arr, num_transactions);
        return NULL;
    }

    // Update metrics and return the maximum weighted sum and corresponding transaction ID
    struct Transaction *updated_metrics = update_metrics(filtered_transactions, num_transactions);
    if (!updated_metrics) {
        free_string_array(arr, num_transactions);
        return NULL;
    }

    // Free the filtered transaction array and return the updated metrics struct
    free(filtered_transactions);
    return updated_metrics;
}
