// Define a function to allocate and initialize memory for the audio stream
audio_frame* allocate_stream(int num_frames, int num_channels) {
    // Calculate the total size of the memory block required
    size_t mem_size = sizeof(audio_frame) * num_frames + sizeof(short) * num_channels;

    // Allocate the memory block using malloc()
    void* mem_block = malloc(mem_size);

    // Check for allocation failure and handle it gracefully
    if (mem_block == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for audio stream\n");
        return NULL;
    }

    // Initialize the memory block with random sample values within a specified range
    srand(time(NULL));
    float* samples = (float*)mem_block;
    short* channels = (short*)(samples + num_frames);
    for (int i = 0; i < num_frames; i++) {
        samples[i] = rand() % 1000 / 10.0f; // Generate random sample values within a specified range
        channels[i] = rand() % 2; // Generate random channel indices
    }

    // Create a linked list of audio_frame structures from the memory block
    audio_frame* frame_list = (audio_frame*)mem_block;
    for (int i = 0; i < num_frames - 1; i++) {
        frame_list[i].next = &frame_list[i + 1];
    }
    frame_list[num_frames - 1].next = NULL;

    // Return the linked list of audio_frame structures
    return frame_list;
}
