void* allocateMemory(size_t num_elements, size_t element_size, struct MemoryAllocator* allocator) {
    // Check if the custom allocator is initialized
    if (allocator->memory_blocks == NULL) {
        // Initialize the custom allocator with a fixed number of memory blocks and a fixed block size
