        allocator->memory_block_size = 1024 * 1024;
        allocator->total_allocated_bytes = 0;
        allocator->memory_blocks = (void**)malloc(sizeof(void*) * allocator->num_memory_blocks);
    }

    // Check if the requested number of elements can fit in a single memory block
    size_t num_elements_per_block = allocator->memory_block_size / element_size;
    if (num_elements > num_elements_per_block) {
        // Allocate a new memory block and add it to the array of allocated blocks
        void* new_block = malloc(allocator->memory_block_size);
        allocator->memory_blocks[allocator->num_memory_blocks++] = new_block;
    }

    // Calculate the offset and size of the requested memory block
    size_t offset = 0;
    size_t size = num_elements * element_size;

    // Check if the requested memory block is already allocated
    for (size_t i = 0; i < allocator->num_memory_blocks; i++) {
        void* current_block = allocator->memory_blocks[i];
        size_t current_offset = offset;
        size_t current_size = size;
        if (current_block != NULL && current_offset + current_size <= allocator->memory_block_size) {
            // Allocate the requested memory block from the existing allocated blocks
            void* allocated_block = (char*)current_block + current_offset;
            offset += size;
            allocator->total_allocated_bytes += size;
            return allocated_block;
        }
    }

    // Allocate a new memory block and add it to the array of allocated blocks
    void* new_block = malloc(size);
    allocator->memory_blocks[allocator->num_memory_blocks++] = new_block;

    // Calculate the offset and size of the requested memory block
    offset = 0;
    size = num_elements * element_size;

    // Allocate the requested memory block from the existing allocated blocks
    void* allocated_block = (char*)new_block + offset;
    offset += size;
    allocator->total_allocated_bytes += size;

    return allocated_block;
}
