// Define a struct to represent a point with two integer coordinates
struct point {
    int x, y;
};

// Define a function to calculate the distance between two points
double distance(struct point p1, struct point p2) {
    return sqrt((p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y));
}

// Define a function to calculate the average distance of all points from the origin
double average_distance(struct point* points, int num_points) {
    double total_distance = 0;
    for (int i = 0; i < num_points; i++) {
        total_distance += distance(points[i], (struct point){0, 0});
    }
    return total_distance / num_points;
}

// Define a function to find the farthest point from the origin
struct point find_farthest_point(struct point* points, int num_points) {
    struct point farthest = (struct point){0, 0};
    for (int i = 0; i < num_points; i++) {
        if (distance(points[i], (struct point){0, 0}) > distance(farthest, (struct point){0, 0})) {
            farthest = points[i];
        }
    }
    return farthest;
}

// Define a function to read coordinate pairs from standard input and store them in an auxiliary array of point structures
void read_coordinates(struct point* points, int num_points) {
    for (int i = 0; i < num_points; i++) {
        scanf("%d %d", &points[i].x, &points[i].y);
    }
}

// Define a function to free all allocated memory
