    for (int i = 0; i < 20000; i++) {
        chars[i] = alphabet[rand() % strlen(alphabet)];
    }

    // Read a series of coordinate pairs from standard input, ensuring that the total number of points does not exceed 50,000
    read_coordinates(points, 50000);

