// Custom memory pool for efficient allocation and deallocation of memory
struct MemoryPool {
    void* buffer;
    size_t capacity;
    size_t used;
};

// Structure to hold a single record with an integer value and a random number
struct Record {
    int value;
    long random_number;
};

// Function to allocate memory for an array of records
void* allocate_records(size_t num_records, size_t record_size) {
    // Calculate the total size required for the array of records
    size_t total_size = num_records * record_size;

    // Allocate memory from the custom memory pool if available, otherwise use malloc()
    void* buffer = NULL;
    if (memory_pool != NULL) {
        buffer = memory_pool->buffer;
        memory_pool->used += total_size;
        assert(memory_pool->used <= memory_pool->capacity);
    } else {
        buffer = malloc(total_size);
    }

    // Initialize the records with random numbers within the specified range
    for (int i = 0; i < num_records; i++) {
        struct Record* record = (struct Record*)buffer + i * record_size;
        record->value = rand() % 100;
        record->random_number = rand() % 1000000;
    }

    return buffer;
}

// Function to deallocate memory for an array of records
void deallocate_records(void* buffer, size_t num_records, size_t record_size) {
    // Calculate the total size required for the array of records
    size_t total_size = num_records * record_size;

    // Deallocate memory from the custom memory pool if available, otherwise use free()
    if (memory_pool != NULL) {
        memory_pool->used -= total_size;
        assert(memory_pool->used >= 0);
    } else {
        free(buffer);
    }
}

// Function to manage memory allocation and initialization for a set of records
void* allocate_and_initialize_records(size_t num_records, size_t record_size, int min_value, int max_value) {
    // Allocate memory for the array of records
    void* buffer = allocate_records(num_records, record_size);
    if (buffer == NULL) {
        return NULL;
    }

    // Initialize the records with random numbers within the specified range
    for (int i = 0; i < num_records; i++) {
        struct Record* record = (struct Record*)buffer + i * record_size;
        record->value = rand() % max_value + min_value;
        record->random_number = rand() % 1000000;
    }

    return buffer;
}

// Function to deallocate memory for a set of records
void deallocate_records(void* buffer, size_t num_records, size_t record_size) {
    // Deallocate the memory for the array of records
    deallocate_records(buffer, num_records, record_size);
}
