    if (!char_array) {
        printf("Error: Failed to allocate memory for char array\n");
        exit(1);
    }

    // Allocate memory for point array
    Point *point_array = (Point *)malloc(num_points * sizeof(Point));
    if (!point_array) {
        printf("Error: Failed to allocate memory for point array\n");
        exit(1);
    }

    // Allocate memory for metadata array
    Metadata *metadata_array = (Metadata *)malloc(num_metadata * sizeof(Metadata));
    if (!metadata_array) {
