typedef struct {
    int key;
    char* user_id;
} record;

struct data {
    long* offsets;
    int* keys;
    record** records;
};

struct data* create_data(int num_records, int offset_range, int key_range) {
    struct data* data = malloc(sizeof(struct data));
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for data structure\n");
        return NULL;
    }

    // Allocate memory for offsets array
    data->offsets = malloc(num_records * sizeof(long));
    if (!data->offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets array\n");
        free(data);
        return NULL;
    }

    // Allocate memory for keys array
    data->keys = malloc(num_records * sizeof(int));
    if (!data->keys) {
        fprintf(stderr, "Failed to allocate memory for keys array\n");
        free(data->offsets);
        free(data);
        return NULL;
    }

    // Allocate memory for records array
    data->records = malloc(num_records * sizeof(record*));
    if (!data->records) {
        fprintf(stderr, "Failed to allocate memory for records array\n");
        free(data->keys);
        free(data->offsets);
        free(data);
        return NULL;
    }

    // Populate offsets and keys arrays with random values within specified range
    for (int i = 0; i < num_records; i++) {
        data->offsets[i] = rand() % offset_range + 1;
        data->keys[i] = rand() % key_range + 1;
    }

    // Allocate memory for each record's user ID string
    for (int i = 0; i < num_records; i++) {
        char* user_id = malloc(sizeof(char) * 20);
        if (!user_id) {
            fprintf(stderr, "Failed to allocate memory for user ID string\n");
            free(data->records[i]);
            data->records[i] = NULL;
        } else {
            sprintf(user_id, "%d", i);
            data->records[i] = malloc(sizeof(record));
            if (!data->records[i]) {
                fprintf(stderr, "Failed to allocate memory for record structure\n");
                free(user_id);
                continue;
            }
            data->records[i]->key = data->keys[i];
            data->records[i]->user_id = user_id;
        }
    }

    return data;
}

void destroy_data(struct data* data) {
    if (!data) {
        return;
    }

    // Free memory for offsets array
    free(data->offsets);

    // Free memory for keys array
    free(data->keys);

    // Free memory for records array
    for (int i = 0; i < data->num_records; i++) {
        if (data->records[i]) {
            free(data->records[i]->user_id);
            free(data->records[i]);
        }
    }
    free(data->records);

    // Free memory for data structure
    free(data);
}
