void init_data_structures(int num_records, int range_min, int range_max) {
    // Allocate memory for the offset array
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offset array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (range_max - range_min + 1) + range_min;
    }

    // Allocate memory for the key array
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the key array with unique random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (range_max - range_min + 1) + range_min;
        // Ensure that each key is unique by checking if it already exists in the array
        for (int j = 0; j < i; j++) {
            if (keys[i] == keys[j]) {
                keys[i]++;
            }
        }
    }

    // Allocate memory for the record structures
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record structures with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    // Ensure thread-safe access to the data structures by using a mutex
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Read the file and sort its lines
    char *file_path = "data.txt";
    FILE *file = fopen(file_path, "r");
    if (!file) {
        printf("Error: Failed to open file %s\n", file_path);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Extract the sequence number from the last line of the file
    int sequence_number = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Ensure that the line is not empty or a comment
        if (strlen(line) > 0 && line[0] != '#') {
            sequence_number++;
        }
    }
    free(line);
    fclose(file);

    // Handle exceptions gracefully and ensure robust file reading processes
    if (sequence_number == 0) {
        printf("Error: Failed to read any lines from the file %s\n", file_path);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Allocate memory for the sequence array
    int *sequence = (int *)malloc(sequence_number * sizeof(int));
    if (!sequence) {
        printf("Error: Failed to allocate memory for sequence\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Read the file again and extract the sequence array
    file = fopen(file_path, "r");
    if (!file) {
        printf("Error: Failed to open file %s\n", file_path);
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    sequence_number = 0;
    while ((read = getline(&line, &len, file)) != -1) {
        // Ensure that the line is not empty or a comment
        if (strlen(line) > 0 && line[0] != '#') {
            sequence[sequence_number++] = atoi(line);
        }
    }
    free(line);
    fclose(file);

    // Ensure that the sequence array is unique and contains all values from 1 to n
    for (int i = 0; i < sequence_number - 1; i++) {
        if (sequence[i] == sequence[i + 1]) {
            printf("Error: Sequence array contains duplicates\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
    }
    for (int i = 0; i < sequence_number; i++) {
        if (sequence[i] != i + 1) {
            printf("Error: Sequence array does not contain all values from 1 to n\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
    }

    // Free the memory allocated for the sequence array
    free(sequence);

    // Ensure that the record structures are thread-safe by using a mutex
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        records[i].value += offsets[i];
    }
    pthread_mutex_unlock(&mutex);

    // Free the memory allocated for the record structures
    free(records);

    // Free the memory allocated for the key array
    free(keys);

    // Free the memory allocated for the offset array
    free(offsets);
}
