// Define the log entry structure
typedef struct {
    char* timestamp;
    int identifier;
    char* content;
} log_entry;

// Define the metadata array structure
typedef struct {
    log_entry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} metadata_array;

// Define the content array structure
typedef struct {
    char** contents;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} content_array;

// Define the log component structure
typedef struct {
    metadata_array* metadata;
    content_array* content;
    size_t max_memory;
    pthread_mutex_t mutex;
} log_component;

// Initialize a new log entry
void init_log_entry(log_entry* entry, char* timestamp, int identifier, char* content) {
    entry->timestamp = timestamp;
    entry->identifier = identifier;
    entry->content = content;
}

// Add a new log entry to the component
void add_log_entry(log_component* component, log_entry* entry) {
    // Acquire lock on metadata and content arrays
    pthread_mutex_lock(&component->metadata->mutex);
    pthread_mutex_lock(&component->content->mutex);

    // Check if the metadata array is full
    if (component->metadata->count == component->metadata->capacity) {
        // Resize the metadata array
        component->metadata->entries = realloc(component->metadata->entries, 2 * component->metadata->capacity * sizeof(log_entry*));
        component->metadata->capacity *= 2;
    }

    // Check if the content array is full
    if (component->content->count == component->content->capacity) {
        // Resize the content array
        component->content->contents = realloc(component->content->contents, 2 * component->content->capacity * sizeof(char*));
        component->content->capacity *= 2;
    }

    // Add the new log entry to the metadata and content arrays
    component->metadata->entries[component->metadata->count] = entry;
    component->content->contents[component->content->count] = strdup(entry->content);
    component->metadata->count++;
    component->content->count++;

    // Release lock on metadata and content arrays
    pthread_mutex_unlock(&component->metadata->mutex);
    pthread_mutex_unlock(&component->content->mutex);
}

// Retrieve a log entry from the component
log_entry* get_log_entry(log_component* component, int index) {
    // Acquire lock on metadata array
    pthread_mutex_lock(&component->metadata->mutex);

    // Check if the index is valid
    if (index < 0 || index >= component->metadata->count) {
        return NULL;
    }

    // Retrieve the log entry from the metadata array
    log_entry* entry = component->metadata->entries[index];

    // Release lock on metadata array
    pthread_mutex_unlock(&component->metadata->mutex);

    return entry;
}

// Free a log entry
void free_log_entry(log_entry* entry) {
    free(entry->content);
    free(entry);
}

// Free the component and all its resources
void free_component(log_component* component) {
    // Acquire lock on metadata and content arrays
    pthread_mutex_lock(&component->metadata->mutex);
    pthread_mutex_lock(&component->content->mutex);

    // Free the log entries in the metadata array
    for (int i = 0; i < component->metadata->count; i++) {
        free_log_entry(component->metadata->entries[i]);
    }

    // Free the content array
    for (int i = 0; i < component->content->count; i++) {
        free(component->content->contents[i]);
    }

    // Release lock on metadata and content arrays
    pthread_mutex_unlock(&component->metadata->mutex);
    pthread_mutex_unlock(&component->content->mutex);

    // Free the component structure
    free(component->metadata);
    free(component->content);
}
