#include <pthread.h>

// Custom memory pool for efficient repeated allocations
struct MemoryPool {
    size_t capacity;
    size_t used;
    void* buffer;
};

// Data structure for a single record
struct Record {
    int value;
};

// Function to dynamically allocate and initialize interconnected data structures
void initDataStructures(int range, size_t initialSize, const char* filePath) {
    // Initialize memory pool with specified capacity
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    pool->capacity = initialSize;
    pool->used = 0;
    pool->buffer = malloc(pool->capacity * sizeof(void*));

    // Allocate memory for offset array
    size_t* offsets = (size_t*)malloc(initialSize * sizeof(size_t));

    // Allocate memory for key array
    int* keys = (int*)malloc(initialSize * sizeof(int));

    // Allocate memory for record structures
    struct Record* records = (struct Record*)malloc(initialSize * sizeof(struct Record));

    // Initialize random number generator
    srand(time(NULL));

    // Read file and extract sequence number from last line
    FILE* fp = fopen(filePath, "r");
    if (!fp) {
        printf("Error: unable to open file %s\n", filePath);
        return;
    }

    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Extract sequence number from last line
        int seqNum = atoi(strrchr(line, ' ') + 1);

        // Allocate memory for record structure
        struct Record* record = (struct Record*)malloc(sizeof(struct Record));
        record->value = rand() % range;

        // Add record to pool
        if (pool->used == pool->capacity) {
            pool->capacity *= 2;
            pool->buffer = realloc(pool->buffer, pool->capacity * sizeof(void*));
        }
        pool->buffer[pool->used++] = record;

        // Add offset to offset array
        offsets[pool->used - 1] = (size_t)record;

        // Add key to key array
        keys[pool->used - 1] = seqNum;
    }

    fclose(fp);

    // Sort offset and key arrays using merge sort
    mergeSort(offsets, pool->used);
    mergeSort(keys, pool->used);

    // Free line buffer
    free(line);

    // Initialize record structures with sorted keys
    for (size_t i = 0; i < pool->used; i++) {
        struct Record* record = (struct Record*)offsets[i];
        record->value = keys[i];
    }
}

// Merge sort implementation for offset and key arrays
void mergeSort(size_t* arr, size_t n) {
    if (n <= 1) return;
    size_t mid = n / 2;
    mergeSort(arr, mid);
    mergeSort(arr + mid, n - mid);
    merge(arr, mid, n - mid);
}

// Merge function for offset and key arrays
void merge(size_t* arr, size_t mid, size_t n) {
    size_t i = 0;
    size_t j = mid;
    size_t k = 0;
    size_t* temp = (size_t*)malloc(n * sizeof(size_t));
    while (i < mid && j < n) {
        if (arr[i] <= arr[j]) {
            temp[k++] = arr[i++];
        } else {
            temp[k++] = arr[j++];
        }
    }
    while (i < mid) {
        temp[k++] = arr[i++];
    }
    while (j < n) {
        temp[k++] = arr[j++];
    }
    memcpy(arr, temp, n * sizeof(size_t));
    free(temp);
}

// Thread-safe access mechanism for concurrent operations
void* getRecord(struct MemoryPool* pool, size_t index) {
    pthread_mutex_lock(&pool->mutex);
    void* record = pool->buffer[index];
    pthread_mutex_unlock(&pool->mutex);
    return record;
}

// Error handling for allocation failures
void handleAllocationFailure(struct MemoryPool* pool) {
    printf("Error: unable to allocate memory\n");
    free(pool->buffer);
    free(pool);
}

// Custom memory pool for efficient repeated allocations
struct MemoryPool* createMemoryPool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        handleAllocationFailure(pool);
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(pool->capacity * sizeof(void*));
    if (!pool->buffer) {
        handleAllocationFailure(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Custom memory pool for efficient repeated allocations
void destroyMemoryPool(struct MemoryPool* pool) {
    free(pool->buffer);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}
