        return -1;
    }

    // Allocate memory for the key array
    key_array = (int*)malloc(sizeof(int) * max_records);
    if (!key_array) {
        log_event("Failed to allocate memory for key array");
        return -1;
    }

    // Allocate memory for the record array
    record_array = (record*)malloc(sizeof(record) * max_records);
    if (!record_array) {
        log_event("Failed to allocate memory for record array");
        return -1;
    }

    // Allocate memory for the metadata array
    metadata_array = (char**)malloc(sizeof(char*) * max_records);
    if (!metadata_array) {
        log_event("Failed to allocate memory for metadata array");
        return -1;
    }

    // Allocate memory for the external data array
    external_data_array = (void**)malloc(sizeof(void*) * max_records);
    if (!external_data_array) {
        log_event("Failed to allocate memory for external data array");
        return -1;
    }

    // Initialize the offset array with invalid values
    for (int i = 0; i < max_records; i++) {
        offset_array[i] = -1;
    }

    // Initialize the key array with invalid values
    for (int i = 0; i < max_records; i++) {
        key_array[i] = -1;
    }

    // Initialize the record array with invalid records
    for (int i = 0; i < max_records; i++) {
        record_array[i].value = -1;
        record_array[i].external_data = NULL;
        record_array[i].metadata = NULL;
    }

    // Initialize the metadata array with invalid values
    for (int i = 0; i < max_records; i++) {
        metadata_array[i] = NULL;
    }

    // Initialize the external data array with invalid pointers
    for (int i = 0; i < max_records; i++) {
        external_data_array[i] = NULL;
    }

    return 0;
}

// Allocate memory for a new record and initialize it
record* allocate_record() {
    // Acquire the mutex to ensure thread-safe memory allocation
    pthread_mutex_lock(&mem_lock);

    // Check if there is enough space in the record pool
    if (current_records >= max_records) {
        log_event("Failed to allocate new record: no more space available");
        return NULL;
    }

    // Allocate memory for the new record
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        log_event("Failed to allocate memory for new record");
        pthread_mutex_unlock(&mem_lock);
        return NULL;
    }

    // Initialize the new record with invalid values
    new_record->value = -1;
    new_record->external_data = NULL;
    new_record->metadata = NULL;

    // Increment the total number of records and current number of active records
    total_records++;
    current_records++;

    // Release the mutex to allow other threads to access the record pool
    pthread_mutex_unlock(&mem_lock);

    return new_record;
}

// Deallocate memory for a record and update the record array
void deallocate_record(int key) {
    // Acquire the mutex to ensure thread-safe memory deallocation
    pthread_mutex_lock(&mem_lock);

