        record_array[i] = record_array[i + 1];
    }

    // Update the metadata array with invalid values
    for (int i = 0; i < max_records - 1; i++) {
        metadata_array[i] = metadata_array[i + 1];
    }

    // Update the external data array with invalid pointers
    for (int i = 0; i < max_records - 1; i++) {
        external_data_array[i] = external_data_array[i + 1];
    }

    // Decrement the current number of active records and increment the number of freed records
    current_records--;
    freed_records++;

    // Release the mutex to allow other threads to access the record pool
    pthread_mutex_unlock(&mem_lock);
}

// Update the metadata for a record and update the metadata array
void update_metadata(int key, char* new_metadata) {
    // Acquire the mutex to ensure thread-safe metadata updates
    pthread_mutex_lock(&mem_lock);

