#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <assert.h>

// Define the configuration setting structure
typedef struct ConfigSetting {
    char* key;
    char* value;
    enum SettingType type;
} ConfigSetting;

// Define the configuration settings array
ConfigSetting* configSettings = NULL;
size_t numConfigSettings = 0;
pthread_mutex_t configMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the configuration settings array
int initConfigSettings(size_t numSettings) {
    // Allocate memory for the configuration settings array
    configSettings = (ConfigSetting*)malloc(numSettings * sizeof(ConfigSetting));
    if (!configSettings) {
        return -1;
    }

    // Initialize each setting to an empty string
    for (size_t i = 0; i < numSettings; i++) {
        configSettings[i].key = "";
        configSettings[i].value = "";
        configSettings[i].type = SettingType::STRING;
    }

    // Set the number of configuration settings
    numConfigSettings = numSettings;

    return 0;
}

// Function to set a configuration setting
int setConfigSetting(const char* key, const char* value, enum SettingType type) {
    pthread_mutex_lock(&configMutex);

    // Find the index of the setting with the given key
    size_t index = 0;
    for (size_t i = 0; i < numConfigSettings; i++) {
        if (strcmp(key, configSettings[i].key) == 0) {
            index = i;
            break;
        }
    }

    // If the setting does not exist, create a new one
    if (index == numConfigSettings) {
        ConfigSetting* newSettings = (ConfigSetting*)realloc(configSettings, (numConfigSettings + 1) * sizeof(ConfigSetting));
        if (!newSettings) {
            pthread_mutex_unlock(&configMutex);
            return -1;
        }
        configSettings = newSettings;
        index = numConfigSettings++;
    }

    // Set the value and type of the setting
    configSettings[index].value = strdup(value);
    configSettings[index].type = type;

    pthread_mutex_unlock(&configMutex);

    return 0;
}

// Function to get a configuration setting
const char* getConfigSetting(const char* key) {
    pthread_mutex_lock(&configMutex);

    // Find the index of the setting with the given key
    size_t index = 0;
    for (size_t i = 0; i < numConfigSettings; i++) {
        if (strcmp(key, configSettings[i].key) == 0) {
            index = i;
            break;
        }
    }

    // If the setting does not exist, return NULL
    if (index == numConfigSettings) {
        pthread_mutex_unlock(&configMutex);
        return NULL;
    }

    const char* value = configSettings[index].value;

    pthread_mutex_unlock(&configMutex);

    return value;
}

// Function to free the configuration settings array
void freeConfigSettings() {
    pthread_mutex_lock(&configMutex);

    // Free each setting's value and key
    for (size_t i = 0; i < numConfigSettings; i++) {
        free(configSettings[i].value);
        free(configSettings[i].key);
    }

    // Free the configuration settings array
    free(configSettings);

    pthread_mutex_unlock(&configMutex);
}

// Function to validate a setting's value against its expected type
int validateSettingValue(const char* key, const char* value) {
    pthread_mutex_lock(&configMutex);

    // Find the index of the setting with the given key
    size_t index = 0;
    for (size_t i = 0; i < numConfigSettings; i++) {
        if (strcmp(key, configSettings[i].key) == 0) {
            index = i;
            break;
        }
    }

    // If the setting does not exist, return an error code
    if (index == numConfigSettings) {
        pthread_mutex_unlock(&configMutex);
        return -1;
    }

    // Validate the value against the expected type
    switch (configSettings[index].type) {
        case SettingType::STRING:
            break;
        case SettingType::INTEGER:
            if (!isInteger(value)) {
                pthread_mutex_unlock(&configMutex);
                return -1;
            }
            break;
        case SettingType::FLOAT:
            if (!isFloat(value)) {
                pthread_mutex_unlock(&configMutex);
                return -1;
            }
            break;
        default:
            pthread_mutex_unlock(&configMutex);
            return -1;
    }

    pthread_mutex_unlock(&configMutex);

    return 0;
}

// Function to serialize the configuration settings to JSON format
char* serializeConfigSettings() {
    // Allocate memory for the JSON string
    size_t jsonSize = numConfigSettings * (strlen(JSON_SETTING_KEY) + strlen(JSON_SETTING_VALUE) + 2);
    char* jsonString = (char*)malloc(jsonSize);
    if (!jsonString) {
        return NULL;
    }

    // Initialize the JSON string
    jsonString[0] = '{';
    size_t offset = 1;

    // Iterate over each setting and add it to the JSON string
    for (size_t i = 0; i < numConfigSettings; i++) {
        offset += sprintf(jsonString + offset, "%s%s:%s", JSON_SETTING_KEY, configSettings[i].key, JSON_SETTING_VALUE);
        switch (configSettings[i].type) {
            case SettingType::STRING:
                offset += sprintf(jsonString + offset, "\"%s\"", configSettings[i].value);
                break;
            case SettingType::INTEGER:
                offset += sprintf(jsonString + offset, "%d", atoi(configSettings[i].value));
                break;
            case SettingType::FLOAT:
                offset += sprintf(jsonString + offset, "%f", atof(configSettings[i].value));
                break;
        }
    }

    // Add the closing brace to the JSON string
    jsonString[offset++] = '}';
    jsonString[offset] = '\0';

    return jsonString;
}

// Function to deserialize the configuration settings from JSON format
int deserializeConfigSettings(const char* jsonString) {
    // Allocate memory for the configuration settings array
    configSettings = (ConfigSetting*)malloc(numConfigSettings * sizeof(ConfigSetting));
    if (!configSettings) {
        return -1;
    }

    // Initialize each setting to an empty string
    for (size_t i = 0; i < numConfigSettings; i++) {
        configSettings[i].key = "";
        configSettings[i].value = "";
        configSettings[i].type = SettingType::STRING;
    }

    // Deserialize the JSON string into the configuration settings array
    json_error_t error;
    json_t* root = json_loads(jsonString, 0, &error);
    if (!root) {
        return -1;
    }

    size_t index = 0;
    json_t* setting = NULL;
    json_t* value = NULL;
    const char* key = NULL;
    while ((setting = json_object_get(root, index)) != NULL) {
        // Get the key and value of the setting
        key = json_string_value(json_object_get(setting, JSON_SETTING_KEY));
        value = json_object_get(setting, JSON_SETTING_VALUE);

        // Set the value and type of the setting
        switch (json_typeof(value)) {
            case JSON_STRING:
                configSettings[index].type = SettingType::STRING;
                break;
            case JSON_INTEGER:
                configSettings[index].type = SettingType::INTEGER;
                break;
            case JSON_REAL:
                configSettings[index].type = SettingType::FLOAT;
                break;
        }
        configSettings[index].value = strdup(json_string_value(value));

        index++;
    }

    // Free the JSON string and root object
    json_decref(root);

    return 0;
}

// Function to validate that all allocated memory is correctly freed upon function exit, ensuring no memory leaks occur
void cleanup() {
    freeConfigSettings();
}
