#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <openssl/evp.h>
#include <openssl/des.h>
#include <openssl/err.h>

// Custom memory pool for efficient repeated allocations
struct MemoryPool {
    void* data;
    size_t size;
};

// Offset structure containing long values
struct Offset {
    long value;
};

// Key structure holding int keys
struct Key {
    int key;
};

// Record structure containing an int value initialized to a random number within a specified range
struct Record {
    int value;
};

// Memory monitor for tracking usage and resource limits
struct MemoryMonitor {
    size_t total_allocated;
    size_t total_freed;
    size_t peak_usage;
};

// Function to manage memory allocation and initialization for a dynamic set of records
void* allocate_records(size_t num_records, size_t offset_size, size_t key_size, size_t record_size, int min_value, int max_value) {
    // Calculate the total memory required for the arrays
    size_t total_memory = (num_records * sizeof(struct Offset)) + (num_records * sizeof(struct Key)) + (num_records * record_size);

    // Allocate memory from the custom memory pool or fall back to malloc if necessary
    void* data = NULL;
    if (total_memory > 0) {
        struct MemoryPool* pool = get_memory_pool();
        if (pool != NULL) {
            data = pool->data;
            total_memory = pool->size;
        } else {
            data = malloc(total_memory);
        }
    }

    // Initialize the memory monitor
    struct MemoryMonitor* monitor = get_memory_monitor();
    if (monitor != NULL) {
        monitor->total_allocated += total_memory;
    }

    // Initialize the offset array
    struct Offset* offsets = data;
    for (size_t i = 0; i < num_records; i++) {
        offsets[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize the key array
    struct Key* keys = data + (num_records * sizeof(struct Offset));
    for (size_t i = 0; i < num_records; i++) {
        keys[i].key = rand() % max_value;
    }

    // Initialize the record array
    struct Record* records = data + (num_records * sizeof(struct Offset)) + (num_records * sizeof(struct Key));
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand() % max_value;
    }

    // Return a pointer to the record array
    return records;
}

// Function to free memory allocated by allocate_records
void free_records(void* data) {
    // Release memory back to the custom memory pool or fall back to free if necessary
    struct MemoryPool* pool = get_memory_pool();
    if (pool != NULL) {
        pool->data = data;
        pool->size -= sizeof(struct Record);
    } else {
        free(data);
    }

    // Update the memory monitor
    struct MemoryMonitor* monitor = get_memory_monitor();
    if (monitor != NULL) {
        monitor->total_freed += sizeof(struct Record);
        monitor->peak_usage -= sizeof(struct Record);
    }
}

// Function to validate a JSON object string containing an OAuth2 access token response
bool validate_access_token(const char* json) {
    // Parse the JSON object
    cJSON* root = cJSON_Parse(json);
    if (root == NULL) {
        return false;
    }

    // Validate the presence of required fields
    cJSON* access_token = cJSON_GetObjectItemCaseSensitive(root, "access_token");
    cJSON* expires_in = cJSON_GetObjectItemCaseSensitive(root, "expires_in");
    cJSON* token_type = cJSON_GetObjectItemCaseSensitive(root, "token_type");
    if (access_token == NULL || expires_in == NULL || token_type == NULL) {
        return false;
    }

    // Validate the value of required fields
    if (!cJSON_IsString(access_token) || !cJSON_IsNumber(expires_in) || !cJSON_IsString(token_type)) {
        return false;
    }

    // Check for optional fields and validate their values if present
    cJSON* refresh_token = cJSON_GetObjectItemCaseSensitive(root, "refresh_token");
    if (refresh_token != NULL && !cJSON_IsString(refresh_token)) {
        return false;
    }

    // Check the value of token_type and ensure it is 'Bearer'
    const char* token_type_str = cJSON_GetStringValue(token_type);
    if (strcmp(token_type_str, "Bearer") != 0) {
        return false;
    }

    // Check the value of expires_in and ensure it is a positive integer
    int expires_in_int = cJSON_GetIntValue(expires_in);
    if (expires_in_int <= 0) {
        return false;
    }

    // Return true if all required fields are valid
    return true;
}

// Function to encrypt a string using the DES algorithm with ECB, EDE, EDE3, or CFB modes
void* encrypt_string(const char* plaintext, const char* key, int mode) {
    // Initialize the OpenSSL library
    OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_LOAD_CRYPTO_STRINGS, NULL);

    // Create a new DES cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the encryption mode and key length based on the input mode
    int key_len = 0;
    switch (mode) {
        case ECB:
            EVP_EncryptInit(ctx, EVP_des_ecb(), NULL, NULL);
            break;
        case EDE:
            EVP_EncryptInit(ctx, EVP_des_ede(), NULL, NULL);
            key_len = 24;
            break;
        case EDE3:
            EVP_EncryptInit(ctx, EVP_des_ede3(), NULL, NULL);
            key_len = 24;
            break;
        case CFB:
            EVP_EncryptInit(ctx, EVP_des_cfb(), NULL, NULL);
            key_len = 8;
            break;
    }

    // Set the encryption key and plaintext length
    int plaintext_len = strlen(plaintext);
    unsigned char* plaintext_bytes = (unsigned char*)plaintext;
    unsigned char* key_bytes = (unsigned char*)key;

    // Allocate memory for the ciphertext
    size_t ciphertext_len = plaintext_len + EVP_CIPHER_CTX_block_size(ctx);
    unsigned char* ciphertext = OPENSSL_malloc(ciphertext_len);

    // Encrypt the plaintext using the DES algorithm
    int len;
    EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext_bytes, plaintext_len);

    // Free the OpenSSL library and return the ciphertext
    EVP_CIPHER_CTX_free(ctx);
    OPENSSL_cleanup();
    return ciphertext;
}

// Function to decrypt a string using the DES algorithm with ECB, EDE, EDE3, or CFB modes
void* decrypt_string(const char* ciphertext, const char* key, int mode) {
    // Initialize the OpenSSL library
    OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_LOAD_CRYPTO_STRINGS, NULL);

    // Create a new DES cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the decryption mode and key length based on the input mode
    int key_len = 0;
    switch (mode) {
        case ECB:
            EVP_DecryptInit(ctx, EVP_des_ecb(), NULL, NULL);
            break;
        case EDE:
            EVP_DecryptInit(ctx, EVP_des_ede(), NULL, NULL);
            key_len = 24;
            break;
        case EDE3:
            EVP_DecryptInit(ctx, EVP_des_ede3(), NULL, NULL);
            key_len = 24;
            break;
        case CFB:
            EVP_DecryptInit(ctx, EVP_des_cfb(), NULL, NULL);
            key_len = 8;
            break;
    }

    // Set the decryption key and ciphertext length
    int ciphertext_len = strlen(ciphertext);
    unsigned char* ciphertext_bytes = (unsigned char*)ciphertext;
    unsigned char* key_bytes = (unsigned char*)key;

    // Allocate memory for the plaintext
    size_t plaintext_len = ciphertext_len + EVP_CIPHER_CTX_block_size(ctx);
    unsigned char* plaintext = OPENSSL_malloc(plaintext_len);

    // Decrypt the ciphertext using the DES algorithm
    int len;
    EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext_bytes, ciphertext_len);

    // Free the OpenSSL library and return the plaintext
    EVP_CIPHER_CTX_free(ctx);
    OPENSSL_cleanup();
    return plaintext;
}
