// Define the function to generate random numbers within a specified range
int generateRandomNumber(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Define the function to allocate and initialize memory for an array of long offset values
long* allocateLongArray(size_t size) {
    long* arr = malloc(sizeof(long) * size);
    if (!arr) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        arr[i] = generateRandomNumber(1, 1000000);
    }
    return arr;
}

// Define the function to allocate and initialize memory for an array of int keys
int* allocateIntArray(size_t size) {
    int* arr = malloc(sizeof(int) * size);
    if (!arr) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        arr[i] = generateRandomNumber(1, 1000000);
    }
    return arr;
}

// Define the function to allocate and initialize memory for an array of record structures
Record* allocateRecordArray(size_t size) {
    Record* arr = malloc(sizeof(Record) * size);
    if (!arr) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        arr[i].value = generateRandomNumber(1, 1000000);
    }
    return arr;
}

// Define the function to deallocate memory for an array of long offset values
void deallocateLongArray(long* arr) {
    free(arr);
}

// Define the function to deallocate memory for an array of int keys
void deallocateIntArray(int* arr) {
    free(arr);
}

// Define the function to deallocate memory for an array of record structures
void deallocateRecordArray(Record* arr) {
    free(arr);
}

// Define the function to generate a unique random value within a specified range
int generateUniqueRandomNumber(int min, int max) {
    int num = generateRandomNumber(min, max);
    while (numExists(num)) {
        num = generateRandomNumber(min, max);
    }
    return num;
}

// Define the function to check if a number exists in an array of long offset values
int numExists(long num) {
    for (int i = 0; i < size; i++) {
        if (arr[i] == num) {
            return 1;
        }
    }
    return 0;
}

// Define the function to check if a number exists in an array of int keys
int numExists(int num) {
    for (int i = 0; i < size; i++) {
        if (arr[i] == num) {
            return 1;
        }
    }
    return 0;
}

// Define the function to check if a number exists in an array of record structures
int numExists(Record* arr, int size, int num) {
    for (int i = 0; i < size; i++) {
        if (arr[i].value == num) {
            return 1;
        }
    }
    return 0;
}

// Define the function to read a file and extract a sequence number from the last line
int readFileAndExtractSequenceNumber(char* filename, int* sequence_number) {
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        return -1;
    }
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), fp)) {
        // Extract the sequence number from the last line of the file
        *sequence_number = atoi(strrchr(buffer, ' ') + 1);
    }
    fclose(fp);
    return 0;
}

// Define the function to generate a MD5 hash for a given string
char* generateMD5Hash(const char* str) {
    unsigned char md5[16];
    MD5((unsigned char*)str, strlen(str), md5);
    return md5;
}

// Define the function to allocate and initialize memory for a data pipeline
void generateDataPipeline(int min_value, int max_value, size_t initial_size) {
    // Allocate memory for the long offset values array
    long* long_offsets = allocateLongArray(initial_size);
    if (!long_offsets) {
        return;
    }

    // Allocate memory for the int keys array
    int* int_keys = allocateIntArray(initial_size);
    if (!int_keys) {
        deallocateLongArray(long_offsets);
        return;
    }

    // Allocate memory for the record structures array
    Record* records = allocateRecordArray(initial_size);
    if (!records) {
        deallocateIntArray(int_keys);
        deallocateLongArray(long_offsets);
        return;
    }

    // Initialize the long offset values array with random numbers within the specified range
    for (int i = 0; i < initial_size; i++) {
        long_offsets[i] = generateRandomNumber(min_value, max_value);
    }

    // Initialize the int keys array with random numbers within the specified range
    for (int i = 0; i < initial_size; i++) {
        int_keys[i] = generateRandomNumber(min_value, max_value);
    }

    // Initialize the record structures array with random values within the specified range
    for (int i = 0; i < initial_size; i++) {
        records[i].value = generateRandomNumber(min_value, max_value);
    }

    // Read the file and extract a sequence number from the last line
    int sequence_number = 0;
    readFileAndExtractSequenceNumber("file.txt", &sequence_number);

    // Generate a unique random value within the specified range for the next record
    int next_record_value = generateUniqueRandomNumber(min_value, max_value);

    // Deallocate memory for the long offset values array
    deallocateLongArray(long_offsets);

    // Deallocate memory for the int keys array
    deallocateIntArray(int_keys);

    // Deallocate memory for the record structures array
    deallocateRecordArray(records);
}
