#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <openssl/md5.h>

// Define the structure for the record
struct record {
    int value;
};

// Define the function to generate data pipeline
void generateDataPipeline(int range, int initial_size, char* file_path) {
    // Initialize the random seed
    srand(time(NULL));

    // Allocate memory for the offset array
    long* offsets = (long*)malloc(initial_size * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offset array with random values
    for (int i = 0; i < initial_size; i++) {
        offsets[i] = rand() % range + 1;
    }

    // Allocate memory for the key array
    int* keys = (int*)malloc(initial_size * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the key array with random values
    for (int i = 0; i < initial_size; i++) {
        keys[i] = rand() % range + 1;
    }

    // Allocate memory for the record array
    struct record* records = (struct record*)malloc(initial_size * sizeof(struct record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record array with random values
    for (int i = 0; i < initial_size; i++) {
        records[i].value = rand() % range + 1;
    }

    // Write the data to a file
    FILE* fp = fopen(file_path, "w");
    if (!fp) {
        printf("Error: Failed to open file\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Write the data to the file
    for (int i = 0; i < initial_size; i++) {
        fprintf(fp, "%ld %d %d\n", offsets[i], keys[i], records[i].value);
    }

    // Close the file
    fclose(fp);

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);
    free(records);
}

