#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Custom memory pool for efficient repeated allocations
struct MemoryPool {
    size_t capacity;
    size_t used;
    void* buffer;
};

// Initialize a custom memory pool with the given capacity
static struct MemoryPool* initMemoryPool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Allocate memory from the custom memory pool
static void* allocateMemory(struct MemoryPool* pool, size_t size) {
