class DynamicRandomRecordManager {
public:
    // Constructor
    DynamicRandomRecordManager(int numRecords, int minValue, int maxValue) :
        numRecords_(numRecords), minValue_(minValue), maxValue_(maxValue) {}

    // Destructor
    ~DynamicRandomRecordManager() {
        delete[] records_;
    }

    // Generate random values inclusively and exclusively within the current range
    void generateRandomValues(int numValues, int minValue, int maxValue) {
        std::uniform_int_distribution<int> distribution(minValue, maxValue);
        for (int i = 0; i < numRecords_; ++i) {
            records_[i].value = distribution(randomEngine_);
        }
    }

    // Reset the range to default bounds (0 to 100 for integers and 0.0 to 1.0 for floats)
    void resetRange() {
        minValue_ = 0;
        maxValue_ = 100;
    }

    // Set the range for the random values
    void setRange(int minValue, int maxValue) {
        if (minValue > maxValue) {
            std::swap(minValue, maxValue);
        }
        minValue_ = minValue;
        maxValue_ = maxValue;
    }

    // Get the range for the random values
    void getRange(int& minValue, int& maxValue) const {
        minValue = minValue_;
        maxValue = maxValue_;
    }

    // Generate multiple random values concurrently, ensuring thread safety and integrity of each range's seed
    std::vector<int> generateRandomValuesParallel(int numValues, int minValue, int maxValue) {
        std::vector<std::thread> threads;
        std::mutex mutex;
        std::condition_variable cv;
        std::vector<int> values;

        for (int i = 0; i < numRecords_; ++i) {
            threads.emplace_back([&]() {
                std::uniform_int_distribution<int> distribution(minValue, maxValue);
                int value = distribution(randomEngine_);
                mutex.lock();
                values.push_back(value);
                mutex.unlock();
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }

        return values;
    }

private:
    // Number of records to allocate memory for
    int numRecords_;

    // Minimum and maximum values for the random range
    int minValue_, maxValue_;

    // Random engine for generating random numbers
    std::random_device randomDevice;
    std::mt19937 randomEngine;

    // Records holding the generated random values
    record* records_;
};
