void init_file_handle(file_handle* handle, char* path) {
    handle->path = path;
    handle->fd = open(path, O_RDONLY);
    if (handle->fd == -1) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }
    struct stat sb;
    fstat(handle->fd, &sb);
    handle->file_size = sb.st_size;
    handle->is_open = true;
}

void close_file_handle(file_handle* handle) {
    if (handle->is_open) {
        close(handle->fd);
        handle->is_open = false;
    }
}

int read_last_line(file_handle* handle, char** line) {
    int ret = 0;
    off_t offset = lseek(handle->fd, -1, SEEK_END);
    if (offset == -1) {
        perror("Error seeking file");
        return -1;
    }
    char c = '\n';
    while (c != '\0') {
        ret = read(handle->fd, &c, 1);
        if (ret == -1) {
            perror("Error reading file");
            return -1;
        } else if (ret == 0) {
            break;
        }
    }
    *line = (char*)malloc(sizeof(char) * (offset + 2));
    lseek(handle->fd, offset, SEEK_SET);
    ret = read(handle->fd, *line, offset + 1);
    if (ret == -1) {
        perror("Error reading file");
        return -1;
    } else if (ret != offset + 1) {
        fprintf(stderr, "Error reading file: partial read\n");
        return -1;
    }
    (*line)[offset] = '\0';
    return ret;
}

