    if (index == theme_cache_size) {
        theme_cache[theme_cache_size] = (char*)malloc(sizeof(char) * (strlen(theme_name) + 1));
        strcpy(theme_cache[theme_cache_size], theme_name);
        theme_cache_size++;
    } else {
        char* cached_path = get_theme_path(theme_name);
        if (strcmp(cached_path, path) != 0) {
            free(cached_path);
            strcpy(theme_cache[index], theme_name);
        } else {
            free(cached_path);
        }
    }
    pthread_mutex_unlock(&theme_cache_lock);
}

void recycle_theme(char* theme_name) {
    pthread_mutex_lock(&theme_cache_lock);
    int index = 0;
    while (index < theme_cache_size && strcmp(theme_cache[index], theme_name) != 0) {
        index++;
    }
    if (index == theme_cache_size) {
        pthread_mutex_unlock(&theme_cache_lock);
        return;
    }
    char* cached_path = get_theme_path(theme_name);
    free(cached_path);
    memmove(theme_cache[index], theme_cache[index + 1], (theme_cache_size - index - 1) * sizeof(char*));
    theme_cache_size--;
    pthread_mutex_unlock(&theme_cache_lock);
}

