    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record with a unique user ID
    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return NULL;
        }

        // Generate a unique user ID using a random number generator
