        if (seq_num > 0) {
            break;
        }
    }

    // Close the file
    fclose(file);

    // Free the memory allocated for the line buffer
    free(line);

    // Print the sequence number to stdout
    printf("Sequence number: %d\n", seq_num);

    // Clean up the memory pool
    destroy_mempool(mempool);
}

// Define the function to create a custom memory pool for efficient repeated allocations
mempool_t* create_mempool() {
    mempool_t* mempool = (mempool_t*)malloc(sizeof(mempool_t));
    if (!mempool) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        return NULL;
    }

    // Initialize the memory pool with a fixed size
    mempool->size = 1024 * 1024;

    // Allocate memory for the memory pool
    mempool->memory = (char*)malloc(mempool->size);
    if (!mempool->memory) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        free(mempool);
        return NULL;
    }

    // Initialize the memory pool with a fixed size
    mempool->used = 0;

    // Return the memory pool
    return mempool;
}

// Define the function to destroy the custom memory pool
void destroy_mempool(mempool_t* mempool) {
    if (!mempool) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        return;
    }

    // Free the memory allocated for the memory pool
    free(mempool->memory);

    // Free the memory pool itself
    free(mempool);
}
