    // Allocate memory for the array of pointers to records
    Record** records = malloc(num_records * sizeof(Record*));
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for %zu records\n", num_records);
        return NULL;
    }

    // Initialize each record with a unique user ID
    for (size_t i = 0; i < num_records; i++) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record %zu\n", i);
            return NULL;
        }

        // Fetch a unique user ID from the external API
        char* user_id = fetch_user_id();
        if (user_id == NULL) {
            fprintf(stderr, "Error: Failed to fetch user ID for record %zu\n", i);
            return NULL;
        }

        // Initialize the record with the unique user ID
        record->offset = 0;
        record->key = i;
        record->user_id = user_id;

        // Add the record to the array of pointers to records
        records[i] = record;
    }

    return records;
}

// Define the function to deallocate memory for an array of records
