        // Handle API failure by retrying with exponential backoff and circuit breaking patterns
        retries++;
        sleep(pow(2, retries));
    }

    // Use a fallback mechanism to proceed with initialization if fetching the user ID fails repeatedly
    char* fallback_user_id = generate_fallback_user_id();
    return fallback_user_id;
