        char* user_id = generate_user_id();
        if (!user_id) {
            fprintf(stderr, "Error: Failed to generate unique user ID\n");
            free(records);
            return NULL;
        }
        record->user_id = user_id;
    }

    // Return the pointer to the first element of the array
