    while (retry_count < MAX_RETRY_COUNT) {
        // Generate a random number between 1 and 1000000
        int random_number = rand() % 1000000 + 1;

        // Convert the random number to a string using sprintf()
        char user_id[7];
        sprintf(user_id, "%d", random_number);

        // Check if the generated user ID is unique
        bool is_unique = true;
        for (int i = 0; i < num_records; i++) {
            Record* record = &records[i];
            if (!strcmp(record->user_id, user_id)) {
                is_unique = false;
                break;
            }
        }

        // If the generated user ID is unique, return it
        if (is_unique) {
            return strdup(user_id);
        }

        // Increment the retry count and sleep for a random amount of time between 0 and 1 second
        retry_count++;
        int sleep_time = rand() % 1000 + 1;
        usleep(sleep_time * 1000);
    }

    // If the retry count exceeds the maximum, return NULL to indicate failure
    return NULL;
}

