// Define the task structure
struct Task {
    int priority;
    time_t deadline;
    char *description;
};

// Define the task list data structure
struct TaskList {
    struct Task *tasks;
    size_t capacity;
    size_t size;
};

// Initialize a new task list with a given capacity
struct TaskList* initTaskList(size_t capacity) {
    struct TaskList *list = malloc(sizeof(struct TaskList));
    if (list == NULL) {
        return NULL;
    }
    list->tasks = malloc(capacity * sizeof(struct Task));
    if (list->tasks == NULL) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->size = 0;
    return list;
}

// Add a new task to the task list
bool addTask(struct TaskList *list, int priority, time_t deadline, char *description) {
    if (list == NULL || description == NULL) {
        return false;
    }
    // Check if the task list is full
    if (list->size >= list->capacity) {
        return false;
    }
    // Add the new task to the list
    struct Task *task = &(list->tasks[list->size]);
    task->priority = priority;
    task->deadline = deadline;
    task->description = strdup(description);
    list->size++;
    return true;
}

// Remove a task from the task list by its index
bool removeTask(struct TaskList *list, size_t index) {
    if (list == NULL || index >= list->size) {
        return false;
    }
    // Shift all tasks after the given index to fill the gap
    for (size_t i = index + 1; i < list->size; i++) {
        list->tasks[i - 1] = list->tasks[i];
    }
    list->size--;
    return true;
}

// Update a task in the task list by its index
bool updateTask(struct TaskList *list, size_t index, int priority, time_t deadline, char *description) {
    if (list == NULL || index >= list->size) {
        return false;
    }
    // Update the task at the given index
    struct Task *task = &(list->tasks[index]);
    task->priority = priority;
    task->deadline = deadline;
    free(task->description);
    task->description = strdup(description);
    return true;
}

// Sort the tasks in the task list by their priorities and deadlines
void sortTasks(struct TaskList *list) {
    if (list == NULL || list->size <= 1) {
        return;
    }
    // Use a stable sorting algorithm to ensure that the order of equal-priority tasks is preserved
    qsort(list->tasks, list->size, sizeof(struct Task), compareTasks);
}

// Compare two tasks by their priorities and deadlines
int compareTasks(const void *a, const void *b) {
    struct Task *task1 = (struct Task *)a;
    struct Task *task2 = (struct Task *)b;
    // Sort first by priority, then by deadline
    if (task1->priority != task2->priority) {
        return task1->priority - task2->priority;
    } else {
        return task1->deadline - task2->deadline;
    }
}

// Process the tasks in the task list according to their priorities and deadlines
void processTasks(struct TaskList *list) {
    if (list == NULL || list->size <= 0) {
        return;
    }
    // Sort the tasks by priority and deadline
    sortTasks(list);
    // Process each task in order of priority and deadline
    for (size_t i = 0; i < list->size; i++) {
        struct Task *task = &(list->tasks[i]);
        // Validate the task with an external scheduling service
        bool validated = validateTask(task);
        if (!validated) {
            continue;
        }
        // Process the task
        processTask(task);
    }
}

