#define MAX_RECORDS 10000
#define MAX_USERID_LEN 64

typedef struct {
    long offset;
    int key;
    char *userid;
} record;

record* init_records(int num_records) {
    // Check if the number of records is valid
    if (num_records <= 0 || num_records > MAX_RECORDS) {
        return NULL;
    }

    // Allocate memory for the array of records
    record *records = malloc(sizeof(record) * num_records);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record with a unique user ID
    int i;
    for (i = 0; i < num_records; i++) {
        char *userid = malloc(MAX_USERID_LEN);
        if (userid == NULL) {
            fprintf(stderr, "Failed to allocate memory for user ID\n");
            free(records);
            return NULL;
        }
        snprintf(userid, MAX_USERID_LEN, "%d", i);
        records[i].userid = userid;
    }

    // Initialize the offset and key for each record
    for (i = 0; i < num_records; i++) {
        records[i].offset = i * sizeof(record);
        records[i].key = i;
    }

    return records;
}

void free_records(record *records) {
    // Check if the records are valid
    if (records == NULL) {
        return;
    }

    // Free each record's user ID and the array of records
    int i;
    for (i = 0; i < MAX_RECORDS; i++) {
        free(records[i].userid);
    }
    free(records);
}
