#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the log entry structure
typedef struct {
    struct tm timeStamp;
    enum operationType operationType;
    int resultCode;
    char* outcomeDescription;
} logEntry;

// Define the function to dynamically allocate and initialize an array of log entries
logEntry** createLogEntries(int numEntries) {
    // Check for valid input parameter
    if (numEntries <= 0) {
        return NULL;
    }

    // Allocate memory for the array of log entries
    logEntry** logEntries = malloc(sizeof(logEntry*) * numEntries);
    if (!logEntries) {
        return NULL;
    }

    // Initialize each log entry with a time stamp, operation type, and result code
    for (int i = 0; i < numEntries; i++) {
        logEntry* entry = malloc(sizeof(logEntry));
        if (!entry) {
            freeLogEntries(logEntries, i);
            return NULL;
        }

        // Initialize the time stamp with the current time
        time_t now = time(NULL);
        struct tm* localTime = localtime(&now);
        entry->timeStamp = *localTime;

        // Set the operation type and result code based on the input parameter
        switch (i % 3) {
            case 0:
                entry->operationType = CREATE;
                entry->resultCode = 201;
                break;
            case 1:
                entry->operationType = UPDATE;
                entry->resultCode = 204;
                break;
            case 2:
                entry->operationType = DELETE;
                entry->resultCode = 200;
                break;
        }

        // Allocate memory for the outcome description and set it to a default value
        char* outcomeDescription = malloc(100);
        if (!outcomeDescription) {
            freeLogEntries(logEntries, i);
            return NULL;
        }
        sprintf(outcomeDescription, "Operation %d completed with result code %d", i + 1, entry->resultCode);
        entry->outcomeDescription = outcomeDescription;

        // Add the log entry to the array of log entries
        logEntries[i] = entry;
    }

    return logEntries;
}

// Define a function to free all memory allocated for an array of log entries
void freeLogEntries(logEntry** logEntries, int numEntries) {
    // Check for valid input parameters
    if (!logEntries || numEntries <= 0) {
        return;
    }

    // Free the memory allocated for each log entry
    for (int i = 0; i < numEntries; i++) {
        free(logEntries[i]->outcomeDescription);
        free(logEntries[i]);
    }

    // Free the memory allocated for the array of log entries
    free(logEntries);
}
