// Define the entry structure for the dynamic array of entries
typedef struct {
    char* string;
    double value;
} entry_t;

// Define the data structure for the dynamic arrays of different types
typedef struct {
    int size;
    int capacity;
    void** data;
} dynamic_array_t;

// Define the range structure for the random values
typedef struct {
    double min;
    double max;
} range_t;

// Define the function to generate a random value within a specified range
double generate_random_value(range_t* range) {
    return (range->min + ((double)rand() / RAND_MAX) * (range->max - range->min));
}

// Define the function to generate a random string within a specified length
char* generate_random_string(int length) {
    char* str = malloc(length);
    for (int i = 0; i < length; i++) {
        str[i] = 'a' + ((rand() % 26));
    }
    return str;
}

// Define the function to initialize an entry with a unique string and random value within a specified range
void init_entry(entry_t* entry, range_t* range) {
    entry->string = generate_random_string(10);
    entry->value = generate_random_value(range);
}

// Define the function to dynamically allocate memory for an array of entries
dynamic_array_t* create_entry_array(int size, int capacity) {
    dynamic_array_t* array = malloc(sizeof(dynamic_array_t));
    array->size = size;
    array->capacity = capacity;
    array->data = malloc(sizeof(void*) * capacity);
    return array;
}

// Define the function to dynamically allocate memory for an array of data structures
dynamic_array_t* create_data_structure_array(int size, int capacity) {
    dynamic_array_t* array = malloc(sizeof(dynamic_array_t));
    array->size = size;
    array->capacity = capacity;
    array->data = malloc(sizeof(void*) * capacity);
    return array;
}

