void add_entry(dynamic_array_t* array, entry_t* entry) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, sizeof(void*) * array->capacity);
    }
    array->data[array->size++] = entry;
}

