#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <thread>

class ConfigurationManager {
public:
    struct SettingObserver {
        virtual void onSettingChanged(const std::string& key, const std::string& value) = 0;
    };

    ConfigurationManager() : configs_(), observers_(), mutex_(), condition_variable_() {}

    ~ConfigurationManager() {
        for (auto& observer : observers_) {
            delete observer.second;
        }
    }

    void addObserver(const std::string& key, SettingObserver* observer) {
        std::lock_guard<std::mutex> lock(mutex_);
        observers_.emplace(key, observer);
    }

    void removeObserver(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        observers_.erase(key);
    }

    void setSetting(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        configs_[key] = value;
        condition_variable_.notify_all();
    }

    void getSetting(const std::string& key, std::string& value) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = configs_.find(key);
        if (it != configs_.end()) {
            value = it->second;
        } else {
            throw std::runtime_error("Key not found");
        }
    }

    void updateSettings() {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& observer : observers_) {
            auto it = configs_.find(observer.first);
            if (it != configs_.end()) {
                observer.second->onSettingChanged(observer.first, it->second);
            }
        }
    }

private:
    std::unordered_map<std::string, std::string> configs_;
    std::unordered_map<std::string, SettingObserver*> observers_;
    mutable std::mutex mutex_;
    std::condition_variable condition_variable_;
};
