    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the data pipeline and initialize it
    struct DataPipeline* pipeline = (struct DataPipeline*)malloc(sizeof(struct DataPipeline));
    if (!pipeline) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    pipeline->offsets = offsets;
    pipeline->keys = keys;
    pipeline->records = records;
    pipeline->mutex = mutex;

    // Return the initialized data pipeline
