        pthread_mutex_lock(&mutex);
        for (uint32_t i = 0; i < num_events; i++) {
            if (events[i].severity_level >= min_severity) {
                // Remove the event from the array
                events[i] = events[num_events - 1];
                num_events--;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to extract metadata from the last event
    void get_last_event(uint32_t* ip, time_t* timestamp) {
        pthread_mutex_lock(&mutex);
        if (num_events > 0) {
            *ip = events[num_events - 1].ip;
            *timestamp = events[num_events - 1].timestamp;
        } else {
            // Handle exceptions gracefully and ensure robust file processing
            printf("Error: No events found\n");
        }
        pthread_mutex_unlock(&mutex);
    }
}
