// Define the data structure for the dynamic range manager
typedef struct {
    int size;
    entry_t* entries;
} dynamic_range_manager_t;

// Define the function to generate a random floating-point number within a specified range
double rand_float(double min, double max) {
    assert(min < max);
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

// Define the function to initialize an entry in the dynamic range manager
void init_entry(entry_t* entry, char* string, double value) {
    entry->string = string;
    entry->value = value;
}

// Define the function to add a new entry to the dynamic range manager
void add_entry(dynamic_range_manager_t* manager, char* string, double value) {
    // Check if the manager is full
    if (manager->size == 0) {
        // Allocate memory for the entries
        manager->entries = malloc(sizeof(entry_t));
        assert(manager->entries != NULL);
        manager->size++;
    } else {
        // Reallocate memory for the entries
        manager->entries = realloc(manager->entries, sizeof(entry_t) * (manager->size + 1));
        assert(manager->entries != NULL);
        manager->size++;
    }
    // Initialize the new entry
    init_entry(&manager->entries[manager->size - 1], string, value);
}

// Define the function to remove an entry from the dynamic range manager
void remove_entry(dynamic_range_manager_t* manager, int index) {
    // Check if the index is valid
    assert(index >= 0 && index < manager->size);
    // Shift the entries to the left
    for (int i = index; i < manager->size - 1; i++) {
        manager->entries[i] = manager->entries[i + 1];
    }
    // Decrease the size of the manager
    manager->size--;
}

// Define the function to get a random entry from the dynamic range manager
entry_t* get_random_entry(dynamic_range_manager_t* manager) {
    // Check if the manager is empty
    assert(manager->size > 0);
    // Generate a random index
    int index = rand() % manager->size;
    return &manager->entries[index];
}

