    int transaction_id;
    char *product_name;
} transaction;

// Function to initialize an array of transactions
transaction* init_transactions(int num_transactions) {
    // Allocate memory for the array of transactions
    transaction *transactions = malloc(num_transactions * sizeof(transaction));
    if (transactions == NULL) {
        printf("Error: Failed to allocate memory for transactions\n");
        return NULL;
    }

    // Initialize each transaction structure
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].amount = 0.0;
        transactions[i].transaction_id = 0;
        transactions[i].product_name = NULL;
    }

    // Fetch product names from the pricing service
    json_object *pricing_response = fetch_pricing_service(num_transactions);
    if (pricing_response == NULL) {
        printf("Error: Failed to fetch product names from pricing service\n");
        free(transactions);
        return NULL;
    }

    // Parse the JSON response and populate the product names
    json_object *product_names = json_object_get_array(pricing_response);
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].product_name = strdup(json_object_get_string(json_object_array_get_idx(product_names, i)));
    }

    // Clean up the pricing response
    json_object_put(pricing_response);

    return transactions;
}

// Function to fetch product names from the pricing service
json_object* fetch_pricing_service(int num_transactions) {
    // Implement a retry mechanism for failed connections, allowing a configurable number of retries before giving up
    int num_retries = 3;
    json_object *response = NULL;
    while (num_retries-- > 0 && response == NULL) {
        response = fetch_pricing_service_impl(num_transactions);
        if (response == NULL) {
            printf("Warning: Failed to connect to pricing service, retrying in %d seconds...\n", num_retries * 2);
            sleep(num_retries * 2);
        }
    }
    return response;
}

// Function to fetch product names from the pricing service (implementation)
json_object* fetch_pricing_service_impl(int num_transactions) {
    // Implement a mechanism to handle connection failures or delays in receiving product names from this service
    json_object *response = NULL;
    while (response == NULL) {
        response = json_object_new();
        if (response == NULL) {
            printf("Error: Failed to allocate memory for pricing response\n");
            return NULL;
        }
        // Fetch product names from the pricing service
        response = fetch_pricing_service_impl(num_transactions);
        if (response == NULL) {
            json_object_put(response);
            printf("Warning: Failed to connect to pricing service, retrying in %d seconds...\n", num_retries * 2);
            sleep(num_retries * 2);
        }
    }
    return response;
}

// Function to handle memory allocation and deallocation for the transactions array
void free_transactions(transaction *transactions) {
    // Free each transaction structure
    for (int i = 0; i < num_transactions; i++) {
        free(transactions[i].product_name);
    }
    // Free the memory allocated for the array of transactions
    free(transactions);
}
