            size_t value_size = strlen(value);
            char* new_key = realloc(key, key_size + value_size + 1);
            if (new_key == NULL) {
                printf("Failed to allocate memory for key\n");
                free(key);
                return NULL;
            }
            key = new_key;
            strcpy(key + key_size, value);
            key_size += value_size;
            i = j;
        } else {
            // Literal character, add it to the key
            char* new_key = realloc(key, key_size + 1);
            if (new_key == NULL) {
                printf("Failed to allocate memory for key\n");
                free(key);
                return NULL;
            }
            key = new_key;
            key[key_size++] = c;
        }
    }
    key[key_size] = '\0';
    return key;
}

// Function to get the value of a field in a record based on its name
char* get_field_value(record* record, char* field_name) {
    // Check if the field exists in the record
    int field_exists = 0;
    for (int i = 0; i < sizeof(record->value); i++) {
        if (strcmp(&record->value[i], field_name) == 0) {
            field_exists = 1;
            break;
        }
    }
    if (!field_exists) {
        printf("Field %s does not exist in the record\n", field_name);
        return NULL;
    }

    // Generate a random value for the field
    int value = rand() % 100;
    char* value_str = malloc(sizeof(char) * 1024);
    if (value_str == NULL) {
        printf("Failed to allocate memory for field value\n");
        return NULL;
    }
    sprintf(value_str, "%d", value);
    return value_str;
}
