#include <pthread.h>
#include <errno.h>
#include <stdbool.h>

#define MAX_INPUT_FILENAME_LENGTH 256
#define MAX_OUTPUT_FILENAME_LENGTH 256
#define MAX_FILTERING_CRITERIA_LENGTH 1024
#define MAX_CONFIGURATION_FILEPATH_LENGTH 256
#define MAX_AUTHENTICATION_TOKEN_LENGTH 128
#define MAX_MEMORY_ALLOCATION_LIMIT 1073741824 // 1 GB

// Struct to store sensor reading data
struct SensorReading {
    double timestamp;
    float value;
    bool isAnomaly;
};

// Function to validate user inputs and parse command-line arguments
void validateInputs(int argc, char *argv[]) {
    // Check if the number of command-line arguments is valid
    if (argc != 7) {
        fprintf(stderr, "Invalid number of command-line arguments. Expected 6.\n");
        exit(1);
    }

    // Validate input file name and output file name lengths
    if (strlen(argv[1]) > MAX_INPUT_FILENAME_LENGTH || strlen(argv[2]) > MAX_OUTPUT_FILENAME_LENGTH) {
        fprintf(stderr, "Input or output file name is too long. Maximum length is %d characters.\n", MAX_INPUT_FILENAME_LENGTH);
        exit(1);
    }

    // Validate filtering criteria length
    if (strlen(argv[3]) > MAX_FILTERING_CRITERIA_LENGTH) {
        fprintf(stderr, "Filtering criteria is too long. Maximum length is %d characters.\n", MAX_FILTERING_CRITERIA_LENGTH);
        exit(1);
    }

    // Validate configuration file path length
    if (strlen(argv[4]) > MAX_CONFIGURATION_FILEPATH_LENGTH) {
        fprintf(stderr, "Configuration file path is too long. Maximum length is %d characters.\n", MAX_CONFIGURATION_FILEPATH_LENGTH);
        exit(1);
    }

    // Validate authentication token length
    if (strlen(argv[5]) > MAX_AUTHENTICATION_TOKEN_LENGTH) {
        fprintf(stderr, "Authentication token is too long. Maximum length is %d characters.\n", MAX_AUTHENTICATION_TOKEN_LENGTH);
        exit(1);
    }

    // Validate memory allocation limit
    if (atoi(argv[6]) > MAX_MEMORY_ALLOCATION_LIMIT) {
        fprintf(stderr, "Memory allocation limit is too large. Maximum value is %d bytes.\n", MAX_MEMORY_ALLOCATION_LIMIT);
        exit(1);
    }
}

// Function to read sensor data from file and filter based on filtering criteria
void processSensorData(char *inputFile, char *outputFile, char *filteringCriteria, char *configurationFilePath, char *authenticationToken) {
    // Open input file for reading
    FILE *input = fopen(inputFile, "r");
    if (input == NULL) {
        fprintf(stderr, "Error opening input file: %s\n", strerror(errno));
        exit(1);
    }

    // Open output file for writing
    FILE *output = fopen(outputFile, "w");
    if (output == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        exit(1);
    }

    // Read sensor data from input file and filter based on filtering criteria
    struct SensorReading *readings = malloc(sizeof(struct SensorReading) * 1000000); // Allocate memory for 1 million readings
    int numReadings = 0;
    while (fscanf(input, "%lf,%f,%d", &readings[numReadings].timestamp, &readings[numReadings].value, &readings[numReadings].isAnomaly) == 3) {
        numReadings++;
    }

    // Filter and process sensor data based on filtering criteria
    for (int i = 0; i < numReadings; i++) {
        if (strcmp(filteringCriteria, "all") == 0 || strcmp(filteringCriteria, "valid") == 0) {
            // Filter valid readings
            if (!readings[i].isAnomaly) {
                fprintf(output, "%lf,%f\n", readings[i].timestamp, readings[i].value);
            }
        } else if (strcmp(filteringCriteria, "anomalies") == 0) {
            // Filter anomaly readings
            if (readings[i].isAnomaly) {
                fprintf(output, "%lf,%f\n", readings[i].timestamp, readings[i].value);
            }
        } else {
            // Unknown filtering criteria
            fprintf(stderr, "Unknown filtering criteria: %s\n", filteringCriteria);
            exit(1);
        }
    }

    // Close input and output files
    fclose(input);
    fclose(output);
}

