    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with the correct values
    for (int i = 0; i < num_records + 1; i++) {
        offsets[i].value = i * sizeof(record_t);
    }

    // Calculate the size of the key array
    size_t key_size = sizeof(key_t) * num_records;

    // Allocate memory for the key array
    key_t* keys = malloc(key_size);
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Initialize the key array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i].key = rand() % (range_max - range_min + 1) + range_min;
    }

    // Calculate the size of the record array
    size_t record_size = sizeof(record_t) * num_records;

    // Allocate memory for the record array
    record_t* records = malloc(record_size);
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

