// Define structure for sensor readings
typedef struct {
    long timestamp; // Timestamp in microseconds
    int num_values; // Number of sensor values
    float *values; // Array of sensor values
    char quality; // Quality flag (0: good, 1: bad)
} sensor_reading;

// Define structure for device metadata
typedef struct {
    int id; // Device ID
    char location[32]; // Location string
    float calibration[4]; // Calibration coefficients
} device_metadata;

// Function to manage dynamic collection of sensor readings
void manage_sensor_readings(int num_sensors, int num_readings) {
    // Allocate memory for array of sensor readings
    sensor_reading *readings = (sensor_reading *)malloc(num_sensors * sizeof(sensor_reading));
    if (!readings) {
        printf("Error: Failed to allocate memory for sensor readings\n");
        return;
    }

    // Initialize each reading with a timestamp and quality flag
    for (int i = 0; i < num_sensors; i++) {
        readings[i].timestamp = time(NULL) * 1000000; // Current timestamp in microseconds
        readings[i].quality = 0; // Good quality by default
    }

    // Allocate memory for array of device metadata
    device_metadata *metadata = (device_metadata *)malloc(num_sensors * sizeof(device_metadata));
    if (!metadata) {
        printf("Error: Failed to allocate memory for device metadata\n");
        free(readings);
        return;
    }

    // Initialize each device with metadata information
    for (int i = 0; i < num_sensors; i++) {
        metadata[i].id = i + 1; // Device ID starts from 1
        strcpy(metadata[i].location, "Unknown"); // Default location string
        metadata[i].calibration[0] = 1.0f; // Default calibration coefficient
        metadata[i].calibration[1] = 2.0f;
        metadata[i].calibration[2] = 3.0f;
        metadata[i].calibration[3] = 4.0f;
    }

    // Process incoming sensor readings and update metadata as necessary
    for (int i = 0; i < num_readings; i++) {
        int sensor_id = i % num_sensors; // Cycle through sensors
        float reading = (float)i / 10.0f; // Generate random reading value
        readings[sensor_id].values[i] = reading; // Update reading array
        if (reading > metadata[sensor_id].calibration[3]) { // Check for high values
            metadata[sensor_id].quality = 1; // Set quality flag to bad
        } else {
            metadata[sensor_id].quality = 0; // Set quality flag to good
        }
    }

    // Print statistics on processing latency and throughput
    printf("Processing latency: %f ms\n", (time(NULL) * 1000.0f - readings[0].timestamp) / 1000.0f);
    printf("Throughput: %.2f readings/second\n", num_readings / ((time(NULL) * 1000.0f - readings[0].timestamp) / 1000.0f));

    // Free memory for sensor readings and device metadata
    free(readings);
    free(metadata);
}
```
