    size_t queue_size; // Size of the queue in bytes
    int (*ingest)(struct collector*); // Function pointer for ingesting logs
    int (*process)(struct collector*); // Function pointer for processing logs
    int (*forward)(struct collector*); // Function pointer for forwarding logs
} collector;

// Define the log entry structure
typedef struct {
    time_t timestamp; // Timestamp of the log entry
    char* source; // Source of the log entry
    int level; // Log level of the log entry
    size_t message_size; // Size of the log message in bytes
} log_entry;

// Define the log queue structure
typedef struct {
    collector* collectors; // Array of collectors
    size_t num_collectors; // Number of collectors
    size_t queue_size; // Size of the queue in bytes
    int (*ingest)(struct log_queue*); // Function pointer for ingesting logs
    int (*process)(struct log_queue*); // Function pointer for processing logs
    int (*forward)(struct log_queue*); // Function pointer for forwarding logs
} log_queue;

// Define the log repository structure
typedef struct {
    collector* collectors; // Array of collectors
    size_t num_collectors; // Number of collectors
    size_t queue_size; // Size of the queue in bytes
    int (*ingest)(struct log_repository*); // Function pointer for ingesting logs
    int (*process)(struct log_repository*); // Function pointer for processing logs
    int (*forward)(struct log_repository*); // Function pointer for forwarding logs
} log_repository;

// Define the log aggregation system structure
typedef struct {
    log_queue* queue; // Log queue
    log_repository* repository; // Log repository
} log_aggregation_system;

// Initialize the log aggregation system
log_aggregation_system* initialize_log_aggregation_system(size_t num_collectors, size_t queue_size) {
    // Allocate memory for the log aggregation system structure
    log_aggregation_system* sys = (log_aggregation_system*)malloc(sizeof(log_aggregation_system));
    if (!sys) {
        fprintf(stderr, "Failed to allocate memory for the log aggregation system\n");
        return NULL;
    }

    // Allocate memory for the collectors array
    sys->collectors = (collector*)malloc(num_collectors * sizeof(collector));
    if (!sys->collectors) {
        fprintf(stderr, "Failed to allocate memory for the collectors array\n");
        free(sys);
        return NULL;
