    // Initialize each collector in the array
    for (size_t i = 0; i < num_collectors; i++) {
        sys->collectors[i].state = NULL;
        sys->collectors[i].queue = NULL;
        sys->collectors[i].queue_size = queue_size;
        sys->collectors[i].ingest = ingest_log_entry;
        sys->collectors[i].process = process_log_entry;
        sys->collectors[i].forward = forward_log_entry;
    }

    // Allocate memory for the log queue
    sys->queue = (log_queue*)malloc(sizeof(log_queue));
    if (!sys->queue) {
        fprintf(stderr, "Failed to allocate memory for the log queue\n");
        free(sys->collectors);
        free(sys);
        return NULL;
    }

    // Initialize the log queue
    sys->queue->collectors = sys->collectors;
    sys->queue->num_collectors = num_collectors;
    sys->queue->queue_size = queue_size;
    sys->queue->ingest = ingest_log_entry;
    sys->queue->process = process_log_entry;
    sys->queue->forward = forward_log_entry;

    // Allocate memory for the log repository
    sys->repository = (log_repository*)malloc(sizeof(log_repository));
    if (!sys->repository) {
        fprintf(stderr, "Failed to allocate memory for the log repository\n");
        free(sys->queue);
        free(sys->collectors);
        free(sys);
        return NULL;
    }

    // Initialize the log repository
    sys->repository->collectors = sys->collectors;
    sys->repository->num_collectors = num_collectors;
    sys->repository->queue_size = queue_size;
    sys->repository->ingest = ingest_log_entry;
    sys->repository->process = process_log_entry;
    sys->repository->forward = forward_log_entry;

    return sys;
}

// Ingest a log entry into the log aggregation system
int ingest_log_entry(log_aggregation_system* sys, const char* source, int level, size_t message_size) {
    // Allocate memory for the log entry
    log_entry* entry = (log_entry*)malloc(sizeof(log_entry));
    if (!entry) {
        fprintf(stderr, "Failed to allocate memory for the log entry\n");
        return -1;
    }

    // Initialize the log entry
    entry->timestamp = time(NULL);
    entry->source = source;
    entry->level = level;
    entry->message_size = message_size;

    // Ingest the log entry into the queue
    int ret = sys->queue->ingest(sys->queue, entry);
    if (ret < 0) {
        fprintf(stderr, "Failed to ingest the log entry\n");
        free(entry);
        return -1;
    }

    // Process the log entry in the queue
    ret = sys->queue->process(sys->queue, entry);
    if (ret < 0) {
        fprintf(stderr, "Failed to process the log entry\n");
        free(entry);
        return -1;
    }

    // Forward the log entry to the repository
    ret = sys->repository->forward(sys->repository, entry);
    if (ret < 0) {
        fprintf(stderr, "Failed to forward the log entry\n");
        free(entry);
        return -1;
    }

    // Free the memory allocated for the log entry
    free(entry);

    return 0;
}

// Process a log entry in the log aggregation system
int process_log_entry(log_aggregation_system* sys, log_entry* entry) {
    // Prioritize the log entry based on severity level
    if (entry->level == LOG_LEVEL_CRITICAL) {
        // Process the critical log entry immediately
        return 0;
    } else {
        // Add the log entry to the queue for further processing
        return sys->queue->enqueue(sys->queue, entry);
    }
}

// Forward a log entry to the repository in the log aggregation system
int forward_log_entry(log_aggregation_system* sys, log_entry* entry) {
    // Add the log entry to the queue for further processing
    return sys->queue->enqueue(sys->queue, entry);
}

// Enqueue a log entry in the log aggregation system
int enqueue(log_aggregation_system* sys, log_entry* entry) {
    // Check if the queue is full
    if (sys->queue->num_entries == sys->queue->queue_size) {
        fprintf(stderr, "The log queue is full\n");
        return -1;
    }

    // Add the log entry to the end of the queue
    sys->queue->entries[sys->queue->tail] = entry;
    sys->queue->num_entries++;
    sys->queue->tail = (sys->queue->tail + 1) % sys->queue->queue_size;

    return 0;
}

// Dequeue a log entry from the log aggregation system
log_entry* dequeue(log_aggregation_system* sys) {
    // Check if the queue is empty
    if (sys->queue->num_entries == 0) {
        fprintf(stderr, "The log queue is empty\n");
        return NULL;
    }

    // Get the head of the queue
    log_entry* entry = sys->queue->entries[sys->queue->head];
    sys->queue->num_entries--;
    sys->queue->head = (sys->queue->head + 1) % sys->queue->queue_size;

    return entry;
}
