    // Calculate the sum of the squared input values
    double sum_squares = 0.0;
    for (size_t i = 0; i < num_doubles; i++) {
        sum_squares += doubles[i] * doubles[i];
    }

    // Calculate the average value
    double avg = sum_squares / num_doubles;

    // Initialize the maximum absolute deviation to 0
    double max_abs_dev = 0.0;

    // Iterate over the input values and calculate the absolute deviation from the average
    for (size_t i = 0; i < num_doubles; i++) {
        double abs_dev = fabs(doubles[i] - avg);
        if (abs_dev > max_abs_dev) {
            max_abs_dev = abs_dev;
        }
    }

    // Print the maximum absolute deviation
