void initialize_data(int size, int max_value) {
    // Validate input parameters
    if (size <= 0 || max_value <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the offset values
    long* offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        printf("Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offset values
    for (int i = 0; i < size; i++) {
        offsets[i] = i * max_value / size;
    }

    // Allocate memory for the keys
    int* keys = malloc(sizeof(int) * size);
    if (!keys) {
        printf("Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the keys
    for (int i = 0; i < size; i++) {
        keys[i] = i + 1;
    }

    // Allocate memory for the records
    record* records = malloc(sizeof(record) * size);
    if (!records) {
        printf("Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Populate the records with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        int value = rand() % max_value + 1;
