    struct Arrays {
        long* offsets;
        int* keys;
        Record* records;
        char** metadata;
    };
    struct Arrays* result = malloc(sizeof(struct Arrays));
    result->offsets = offsets;
    result->keys = keys;
    result->records = records;
    result->metadata = metadata;
    return result;
}

// Function to free the memory allocated by init_arrays
void free_arrays(struct Arrays* arrays) {
    if (arrays == NULL) {
        return;
    }
    for (int i = 0; i < arrays->num_records; i++) {
        free(arrays->offsets[i]);
        free(arrays->keys[i]);
        free(arrays->records[i].user_id);
        free(arrays->metadata[i]);
    }
    free(arrays->offsets);
    free(arrays->keys);
    free(arrays->records);
    free(arrays->metadata);
}
