    hash_table_t *ht = malloc(sizeof(hash_table_t));
    ht->size = size;
    ht->count = 0;
    ht->table = calloc(size, sizeof(kv_pair_t*));
    return ht;
}

// Function to allocate and initialize a lock manager
lock_manager_t *allocate_lock_manager(int num_locks) {
    lock_manager_t *lm = malloc(sizeof(lock_manager_t));
    lm->num_locks = num_locks;
