// Function to add a key-value pair to the hash table
void add_kv_pair(hash_table_t *ht, char *key, void *value) {
    int index = ht->count % ht->size;
    kv_pair_t *new_pair = malloc(sizeof(kv_pair_t));
    new_pair->key = key;
    new_pair->value = value;
    new_pair->expiration = 0; // Set the expiration time to 0 for now
    ht->table[index] = new_pair;
    ht->count++;
}

// Function to get a key-value pair from the hash table
kv_pair_t *get_kv_pair(hash_table_t *ht, char *key) {
    int index = hash(key);
    kv_pair_t *pair = ht->table[index];
    while (pair != NULL && strcmp(pair->key, key) != 0) {
        pair = pair->next;
    }
    return pair;
}

// Function to remove a key-value pair from the hash table
void remove_kv_pair(hash_table_t *ht, char *key) {
    int index = hash(key);
    kv_pair_t *pair = ht->table[index];
    while (pair != NULL && strcmp(pair->key, key) != 0) {
        pair = pair->next;
    }
    if (pair != NULL) {
        free(pair);
        ht->count--;
    }
}

// Function to update the expiration time of a key-value pair in the hash table
void update_expiration(hash_table_t *ht, char *key, time_t expiration) {
    int index = hash(key);
    kv_pair_t *pair = ht->table[index];
    while (pair != NULL && strcmp(pair->key, key) != 0) {
        pair = pair->next;
    }
    if (pair != NULL) {
        pair->expiration = expiration;
    }
}

// Function to check the expiration time of a key-value pair in the hash table
time_t check_expiration(hash_table_t *ht, char *key) {
    int index = hash(key);
    kv_pair_t *pair = ht->table[index];
    while (pair != NULL && strcmp(pair->key, key) != 0) {
        pair = pair->next;
    }
    if (pair != NULL) {
        return pair->expiration;
    } else {
        return -1; // Return -1 if the key is not found
    }
}

