['```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define a record structure to hold offset, key, and buffer
typedef struct {
    long int offset;
    int key;
    char *buffer;
} record;

// Define a memory pool structure to manage reusable character buffers
typedef struct {
    size_t capacity; // maximum number of characters in the pool
    size_t size; // current number of characters in the pool
    char *pool; // pointer to the start of the memory pool
} mempool;

// Define a least-recently-used (LRU) eviction strategy for the memory pool
void lru_evict(mempool *pool) {
    size_t i, j;
    char *ptr = pool->pool;
    // Find the first unused character in the pool
    for (i = 0; i < pool->size; i++) {
        if (*ptr == '\0') {
            break;
        }
        ptr++;
    }
    // If no unused characters are found, evict the least recently used buffer
    if (i == pool->size) {
        for (j = 0; j < pool->size; j++) {
            if (*ptr == '\0') {
                break;
            }
            ptr++;
        }
        // If no unused buffers are found, evict the oldest buffer
        if (j == pool->size) {
            for (i = 0; i < pool->size; i++) {
                if (*ptr != '\0') {
                    break;
                }
                ptr++;
            }
        }
    }
    // Evict the buffer at the found index
    *ptr = '\0';
}

// Initialize a memory pool with a specified maximum size
mempool* init_mempool(size_t capacity) {
    mempool *pool = malloc(sizeof(mempool));
    if (pool == NULL) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->size = 0;
    pool->pool = malloc(capacity);
    if (pool->pool == NULL) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Allocate and initialize an array of record structures with a specified maximum size
record* init_records(size_t capacity, int key, long int offset) {
    record *records = malloc(capacity * sizeof(record));
    if (records == NULL) {
        return NULL;
    }
    for (int i = 0; i < capacity; i++) {
        records[i].offset = offset;
        records[i].key = key;
        records[i].buffer = malloc(MAX_BUFFER_SIZE);
        if (records[i].buffer == NULL) {
            free(records);
            return NULL;
        }
    }
    return records;
}

// Allocate and initialize a record structure with a specified maximum size, using a memory pool for buffer allocation
record* init_record(size_t capacity, int key, long int offset) {
    record *records = malloc(capacity * sizeof(record));
    if (records == NULL) {
        return NULL;
    }
    mempool *pool = init_mempool(MAX_BUFFER_SIZE);
    if (pool == NULL) {
        free(records);
        return NULL;
    }
    for (int i = 0; i < capacity; i++) {
        records[i].offset = offset;
        records[i].key = key;
        records[i].buffer = lru_alloc(pool, MAX_BUFFER_SIZE);
        if (records[i].buffer == NULL) {
            free(records);
            return NULL;
        }
    }
    return records;
}

// Allocate a buffer from the memory pool using an LRU eviction strategy
char* lru_alloc(mempool *pool, size_t size) {
    char *ptr = pool->pool;
    // Find the first unused character in the pool
    for (int i = 0; i < pool->size; i++) {
        if (*ptr == '\0') {
            break;
        }
        ptr++;
    }
    // If no unused characters are found, evict the least recently used buffer
    if (i == pool->size) {
        for (int j = 0; j < pool->size; j++) {
            if (*ptr == '\0') {
                break;
            }
            ptr++;
        }
        // If no unused buffers are found, evict the oldest buffer
        if (j == pool->size) {
            for (int i = 0; i < pool->size; i++) {
                if (*ptr != '\0') {
                    break;
                }
                ptr++;
            }
        }
    }
    // Allocate the buffer at the found index
    *ptr = malloc(size);
    if (*ptr == NULL) {
        return NULL;
    }
    pool->size++;
    return *ptr;
}

// Release a buffer from the memory pool using an LRU eviction strategy
void lru_free(mempool *pool, char *buffer) {
    size_t i;
    char *ptr = pool->pool;
    // Find the index of the buffer to be freed
    for (i = 0; i < pool->size; i++) {
        if (ptr == buffer) {
            break;
        }
        ptr++;
    }
    // If the buffer is not found, do nothing
    if (i == pool->size) {
        return;
    }
    // Evict the buffer at the found index
    *ptr = '\0';
    pool->size--;
}

// Logging mechanism to monitor buffer usage and memory pool statistics
void log_stats(mempool *pool, size_t capacity) {
    printf("Buffer usage: %d/%d\n", pool->size, capacity);
    printf("Memory pool statistics:\n");
    printf("\tCapacity: %zu\n", pool->capacity);
    printf("\tSize: %zu\n", pool->size);
}

// Main function to demonstrate the use of the memory pool and LRU eviction strategy
int main() {
    // Initialize a memory pool with a maximum size of 1024 characters
    mempool *pool = init_mempool(1024);
    if (pool == NULL) {
        return 1;
    }
    // Allocate and initialize an array of record structures with a maximum size of 10 records
    record *records = init_records(10, 1, 100);
    if (records == NULL) {
        free(pool);
        return 1;
    }
    // Log the buffer usage and memory pool statistics
    log_stats(pool, 1024);
    // Allocate a new record structure with a maximum size of 5 records using an LRU eviction strategy
    record *new_record = init_record(5, 2, 200);
    if (new_record == NULL) {
        free(records);
        free(pool);
        return 1;
    }
    // Log the buffer usage and memory pool statistics again
    log_stats(pool, 1024);
    // Release the new record structure using an LRU eviction strategy
    lru_free(pool, new_record->buffer);
    // Log the buffer usage and memory pool statistics one last time
    log_stats(pool, 1024);
    // Free the memory pool and all allocated buffers when no longer needed
    free(records);
    free(pool);
    return 0;
}
```
