#include <openssl/rand.h>
#include <openssl/err.h>

typedef struct {
    long offset;
    int key;
    record *record;
    log *log;
} entry;

typedef struct {
    int size;
    entry *entries;
} DynamicResourceManager;

DynamicResourceManager* DynamicResourceManager_create(int size, int min_value, int max_value) {
    // Validate input parameters
    if (size <= 0 || min_value > max_value) {
        return NULL;
    }

    // Allocate memory for the structure and its entries
    DynamicResourceManager *manager = malloc(sizeof(DynamicResourceManager));
    manager->entries = malloc(sizeof(entry) * size);

    // Initialize each entry with a unique string and random floating-point value within the specified range
    for (int i = 0; i < size; i++) {
        entry *e = &manager->entries[i];
        e->offset = i;
        e->key = i;
        e->record = malloc(sizeof(record));
        e->log = NULL;
        float random_value = (float)RAND_bytes(1, min_value, max_value);
        sprintf(e->record->user_id, "User %d", i);
        e->record->value = random_value;
    }

    // Generate unique user IDs based on the record index using OpenSSL library
    for (int i = 0; i < size; i++) {
        entry *e = &manager->entries[i];
        char *user_id = malloc(sizeof(char) * 16);
        int ret = EVP_BytesToKey(EVP_md5(), EVP_ENCODE_LENGTH, NULL, e->record->user_id, strlen(e->record->user_id), user_id, 16);
        if (ret != 0) {
            free(user_id);
            continue;
        }
        sprintf(e->record->user_id, "%s", user_id);
        free(user_id);
    }

    // Initialize the structure with the given size and entries
    manager->size = size;

    return manager;
}

void DynamicResourceManager_destroy(DynamicResourceManager *manager) {
    if (manager == NULL) {
        return;
    }

    for (int i = 0; i < manager->size; i++) {
        entry *e = &manager->entries[i];
        free(e->record);
        free(e->log);
    }
    free(manager->entries);
    free(manager);
}
