#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define a struct to represent a node in the BST
struct Node {
    unsigned long timestamp;
    char identifier;
    double value;
    struct Node* left;
    struct Node* right;
};

// Define a struct to represent the BST
struct BST {
    struct Node* root;
};

// Function to initialize the arrays and BST
void init(unsigned long* timestamps, char* identifiers, double* values, int size) {
    // Allocate memory for the arrays
    timestamps = (unsigned long*)malloc(size * sizeof(unsigned long));
    identifiers = (char*)malloc(size * sizeof(char));
    values = (double*)malloc(size * sizeof(double));

    // Check for NULL pointers and handle errors gracefully
    if (timestamps == NULL || identifiers == NULL || values == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the arrays with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        timestamps[i] = rand() % 1000000;
        identifiers[i] = 'A' + (rand() % 26);
        values[i] = (double)rand() / RAND_MAX * 100 - 50;
    }

    // Initialize the BST with the first element of the array
    struct Node* root = malloc(sizeof(struct Node));
    root->timestamp = timestamps[0];
    root->identifier = identifiers[0];
    root->value = values[0];
    root->left = NULL;
    root->right = NULL;

    // Insert the remaining elements of the array into the BST
    for (int i = 1; i < size; i++) {
        insert(root, timestamps[i], identifiers[i], values[i]);
    }
}

// Function to insert an element into the BST
void insert(struct Node* root, unsigned long timestamp, char identifier, double value) {
    // If the current node is NULL, create a new node and return it
    if (root == NULL) {
        struct Node* new_node = malloc(sizeof(struct Node));
        new_node->timestamp = timestamp;
        new_node->identifier = identifier;
        new_node->value = value;
        new_node->left = NULL;
        new_node->right = NULL;
        return new_node;
    }

    // If the current node is not NULL, compare the timestamp and insert accordingly
    if (timestamp < root->timestamp) {
        root->left = insert(root->left, timestamp, identifier, value);
    } else if (timestamp > root->timestamp) {
        root->right = insert(root->right, timestamp, identifier, value);
    }

    return root;
}

// Function to perform statistical analysis on the data
void analyze(struct BST* bst) {
    // Calculate the mean, median, and standard deviation of the values in the BST
    double sum = 0.0;
    int count = 0;
    struct Node* current = bst->root;
    while (current != NULL) {
        sum += current->value;
        count++;
        current = current->right;
    }
    double mean = sum / count;
    double median = 0.0;
    if (count % 2 == 0) {
        median = (bst->root->left->value + bst->root->right->value) / 2.0;
    } else {
        median = bst->root->right->value;
    }
    double stddev = sqrt(sum - mean * mean);

    // Output the results in a formatted log
    printf("Mean: %f\n", mean);
    printf("Median: %f\n", median);
    printf("Standard Deviation: %f\n", stddev);
}

// Function to read and validate the configuration file
void read_config(char* filename) {
    // Open the configuration file for reading
    FILE* config = fopen(filename, "r");
    if (config == NULL) {
        printf("Error: Could not open configuration file\n");
        return;
    }

    // Read the size of the arrays from the configuration file
    int size;
    fscanf(config, "%d", &size);

    // Read the range for the random values assigned to the numerical values from the configuration file
    double min_value;
    double max_value;
    fscanf(config, "%lf %lf", &min_value, &max_value);

    // Read the maximum size of individual items before they are managed by a custom data structure designed to handle large datasets efficiently from the configuration file
    int max_item_size;
    fscanf(config, "%d", &max_item_size);

    // Close the configuration file
    fclose(config);
}

// Function to handle memory allocation errors gracefully
void handle_error() {
    printf("Error: Memory allocation failed\n");
}

int main() {
    // Read and validate the configuration file
    read_config("config.txt");

    // Initialize the arrays and BST
    unsigned long* timestamps;
    char* identifiers;
    double* values;
    init(timestamps, identifiers, values, size);

    // Perform statistical analysis on the data
    analyze(bst);

    return 0;
}
