// Define the structure for the offset array
typedef struct {
    long value;
} offset_t;

// Define the structure for the key array
typedef struct {
    int key;
} key_t;

// Define the structure for the record array
typedef struct {
    int value;
} record_t;

// Define the function to allocate and initialize memory for the data structures
void init_data(int num_records, int min_value, int max_value) {
    // Allocate memory for the offset array
    offset_t *offsets = (offset_t *)malloc(num_records * sizeof(offset_t));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Allocate memory for the key array
    key_t *keys = (key_t *)malloc(num_records * sizeof(key_t));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Allocate memory for the record array
    record_t *records = (record_t *)malloc(num_records * sizeof(record_t));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the offset array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize the key array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        keys[i].key = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize the record array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Print the initialized data structures
    printf("Offsets: ");
    for (int i = 0; i < num_records; i++) {
        printf("%ld ", offsets[i].value);
    }
    printf("\n");

    printf("Keys: ");
    for (int i = 0; i < num_records; i++) {
        printf("%d ", keys[i].key);
    }
    printf("\n");

    printf("Records: ");
    for (int i = 0; i < num_records; i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");

    // Free the memory allocated for the data structures
    free(offsets);
    free(keys);
    free(records);
}
