}

// Function to read a binary input file and parse its contents
void read_input(const char *filename, transaction **transactions, account **accounts, customer **customers) {
    // Open the input file in binary mode
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: Failed to open input file %s\n", filename);
        exit(1);
    }

    // Read the contents of the input file into memory
    size_t filesize = 0;
    fseek(fp, 0, SEEK_END);
    filesize = ftell(fp);
    rewind(fp);
    void *buffer = malloc(filesize);
    if (buffer == NULL) {
        printf("Error: Failed to allocate memory for input file\n");
        exit(1);
    }
    fread(buffer, 1, filesize, fp);

    // Parse the contents of the input file and initialize the transaction, account, and customer structures
    int num_transactions = 0;
    int num_accounts = 0;
    int num_customers = 0;
    for (int i = 0; i < filesize; i++) {
        // Check if the current byte is a transaction record
        if ((char)buffer[i] == 'T') {
            // Increment the number of transactions and allocate memory for the next transaction record
            num_transactions++;
            (*transactions)[num_transactions - 1].timestamp = (long)buffer[i + 1];
            (*transactions)[num_transactions - 1].transaction_id = (int)buffer[i + 2];
            (*transactions)[num_transactions - 1].amount = *(double *)&buffer[i + 3];
        }

        // Check if the current byte is an account record
        else if ((char)buffer[i] == 'A') {
            // Increment the number of accounts and allocate memory for the next account record
            num_accounts++;
            (*accounts)[num_accounts - 1].account_id = (int)buffer[i + 1];
            (*accounts)[num_accounts - 1].balance = *(double *)&buffer[i + 2];
        }

        // Check if the current byte is a customer record
        else if ((char)buffer[i] == 'C') {
            // Increment the number of customers and allocate memory for the next customer record
            num_customers++;
            (*customers)[num_customers - 1].customer_id = (int)buffer[i + 1];
            strncpy((*customers)[num_customers - 1].name, (char *)&buffer[i + 2], 256);
            strncpy((*customers)[num_customers - 1].email, (char *)&buffer[i + 258], 256);
            strncpy((*customers)[num_customers - 1].phone, (char *)&buffer[i + 514], 32);
        }
    }

    // Close the input file
    fclose(fp);
}

// Function to generate an output file based on transformation rules
void write_output(const char *filename, transaction **transactions, account **accounts, customer **customers) {
    // Open the output file in binary mode
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error: Failed to open output file %s\n", filename);
        exit(1);
    }

    // Write the contents of the transaction, account, and customer structures to the output file
    for (int i = 0; i < num_transactions; i++) {
        fwrite(&(*transactions)[i].timestamp, sizeof(long), 1, fp);
        fwrite(&(*transactions)[i].transaction_id, sizeof(int), 1, fp);
        fwrite(&(*transactions)[i].amount, sizeof(double), 1, fp);
    }
    for (int i = 0; i < num_accounts; i++) {
        fwrite(&(*accounts)[i].account_id, sizeof(int), 1, fp);
        fwrite(&(*accounts)[i].balance, sizeof(double), 1, fp);
    }
    for (int i = 0; i < num_customers; i++) {
        fwrite(&(*customers)[i].customer_id, sizeof(int), 1, fp);
        strncpy((*customers)[i].name, (*customers)[i].name, 256);
        strncpy((*customers)[i].email, (*customers)[i].email, 256);
        strncpy((*customers)[i].phone, (*customers)[i].phone, 32);
    }

    // Close the output file
    fclose(fp);
}

// Function to enforce strict rules to prevent duplicate account IDs and handle concurrent access from multiple threads without data corruption or race conditions
void manage_memory(transaction **transactions, account **accounts, customer **customers) {
    // Initialize the hash table-based index for fast customer lookup based on account ID
    init_index(&index, max_accounts);

    // Enforce strict rules to prevent duplicate account IDs and handle concurrent access from multiple threads without data corruption or race conditions
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    for (int i = 0; i < max_accounts; i++) {
        // Check if the current account ID is already in use
        if ((*index)[i].account_id != 0) {
            printf("Error: Duplicate account ID %d\n", (*index)[i].account_id);
            exit(1);
        }

        // Lock the mutex to prevent concurrent access from multiple threads without data corruption or race conditions
        pthread_mutex_lock(&mutex);

        // Check if the current account ID is already in use by another thread
        for (int j = 0; j < max_accounts; j++) {
            if ((*index)[j].account_id == (*transactions)[i].account_id) {
                printf("Error: Duplicate account ID %d\n", (*transactions)[i].account_id);
                exit(1);
            }
        }

        // Update the hash table-based index with the new account ID and customer information
        (*index)[i].account_id = (*transactions)[i].account_id;
        (*index)[i].customer = &(*customers)[i];

        // Unlock the mutex to allow other threads to access the hash table-based index without data corruption or race conditions
        pthread_mutex_unlock(&mutex);
    }
}

// Function to handle memory allocation failures and resource release
void error_handler(const char *filename, transaction **transactions, account **accounts, customer **customers) {
    // Release the memory allocated for the transactions, accounts, and customers structures
    free(*transactions);
    free(*accounts);
    free(*customers);

    // Close the input and output files
    fclose(fp);

    // Print an error message to the console
    printf("Error: Failed to allocate memory for %s\n", filename);
}

