// Define the structure for customer transactions
struct transaction {
    long timestamp;
    int transaction_id;
    double amount;
};

// Define the structure for customer accounts
struct account {
    int account_id;
    double balance;
    struct transaction *transactions;
};

// Define the structure for customer sessions
struct session {
    int session_id;
    time_t start_time;
    time_t end_time;
    struct transaction *transactions;
};

// Define the structure for customer information
struct customer {
    int customer_id;
    char name[256];
    char email[256];
    struct account *accounts;
    struct session *sessions;
};

// Define the hash table for fast customer lookup by account ID
struct hash_table {
    int size;
    struct customer **customers;
};

// Function to initialize the hash table
void init_hash_table(struct hash_table *ht, int size) {
    ht->size = size;
    ht->customers = (struct customer **)malloc(sizeof(struct customer *) * size);
    memset(ht->customers, 0, sizeof(struct customer *) * size);
}

// Function to insert a new customer into the hash table
void insert_customer(struct hash_table *ht, struct customer *c) {
    int index = c->accounts[0].account_id % ht->size;
    if (ht->customers[index] == NULL) {
        ht->customers[index] = c;
    } else {
        struct customer *curr = ht->customers[index];
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = c;
    }
}

// Function to retrieve a customer from the hash table by account ID
struct customer *get_customer(struct hash_table *ht, int account_id) {
    int index = account_id % ht->size;
    struct customer *c = ht->customers[index];
    while (c != NULL && c->accounts[0].account_id != account_id) {
        c = c->next;
    }
    return c;
}

// Function to allocate memory for a new transaction record
struct transaction *allocate_transaction(int transaction_id, double amount) {
    struct transaction *t = (struct transaction *)malloc(sizeof(struct transaction));
    t->transaction_id = transaction_id;
    t->amount = amount;
    return t;
}

// Function to allocate memory for a new account record
struct account *allocate_account(int account_id, double balance) {
