    s->session_id = session_id;
    s->start_time = start_time;
    return s;
}

// Function to allocate memory for a new customer record
struct customer *allocate_customer(int customer_id, char *name, char *email) {
    struct customer *c = (struct customer *)malloc(sizeof(struct customer));
    c->customer_id = customer_id;
    strcpy(c->name, name);
    strcpy(c->email, email);
    return c;
}

// Function to initialize a new transaction record
