        sessions[i].user = "user";
        sessions[i].metadata = "metadata";
        sessions[i].log = NULL;
    }

    // Allocate memory for the activity log linked list
    activity_log_t* log = (activity_log_t*)malloc(sizeof(activity_log_t) * max_sessions);
    if (!log) {
        fprintf(stderr, "Error: failed to allocate memory for activity log\n");
        exit(1);
    }

    // Initialize the activity log linked list with timestamps and actions
    for (int i = 0; i < max_sessions; i++) {
        log[i].timestamp = time(NULL);
        log[i].action = "action";
        log[i].data = "data";
    }
}

