        index[i].user = "user";
        index[i].metadata = "metadata";
        index[i].log = NULL;
    }
}

// Define the function to handle concurrent access from multiple threads without data corruption or race conditions
void manage_threads(int max_sessions) {
    // Create a semaphore for each thread
    sem_t* semaphores[max_sessions];
    for (int i = 0; i < max_sessions; i++) {
        semaphores[i] = sem_open(NULL, O_CREAT | O_EXCL, 0644, 1);
        if (!semaphores[i]) {
            fprintf(stderr, "Error: failed to create semaphore\n");
            exit(1);
        }
    }

    // Create a thread for each session
    pthread_t threads[max_sessions];
    for (int i = 0; i < max_sessions; i++) {
        if (pthread_create(&threads[i], NULL, process_session, &semaphores[i])) {
            fprintf(stderr, "Error: failed to create thread\n");
            exit(1);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < max_sessions; i++) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error: failed to join thread\n");
            exit(1);
        }
    }
}

// Define the function to handle memory allocation failures and resource release
void cleanup() {
    // Release all allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(sessions);
    free(log);

    // Close all open files
    close(fd);
    close(out_fd);
