void add_log_entry(time_t timestamp, int level, char* message) {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_mutex);

    // Check if the log is full and needs to be purged
    if (num_log_entries >= max_log_size) {
        purge_old_entries();
    }

