    log_entries[num_log_entries]->level = level;
    log_entries[num_log_entries]->message = message;
    num_log_entries++;

    // Signal that a new entry has been added to the log
    pthread_cond_signal(&log_added);

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_mutex);
}

// Function to retrieve all log entries with a specified timestamp
ModemLogEntry* get_log_entries(time_t timestamp) {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_mutex);

    // Initialize an empty array of log entries
    ModemLogEntry* filtered_entries = malloc(sizeof(ModemLogEntry));
    int num_filtered_entries = 0;

    // Iterate over the log entries and filter out those with a timestamp less than the specified timestamp
    for (int i = 0; i < num_log_entries; i++) {
        if (log_entries[i]->timestamp >= timestamp) {
            filtered_entries[num_filtered_entries] = log_entries[i];
            num_filtered_entries++;
        }
    }

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_mutex);

    return filtered_entries;
}

// Function to clear all log entries
void clear_log() {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_mutex);

    // Free the memory allocated for the log entries
    for (int i = 0; i < num_log_entries; i++) {
        free(log_entries[i]);
    }

    // Reset the number of log entries to zero
    num_log_entries = 0;

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_mutex);
}

// Function to purge old entries from the log
void purge_old_entries() {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_mutex);

    // Iterate over the log entries and remove those that are older than the specified duration
    time_t current_time = time(NULL);
    int num_purged_entries = 0;
    for (int i = 0; i < num_log_entries; i++) {
        if (current_time - log_entries[i]->timestamp >= purge_duration) {
            free(log_entries[i]);
            num_purged_entries++;
        } else {
            break;
        }
    }

    // Shift the remaining log entries to fill the gap left by the purged entries
    for (int i = 0; i < num_log_entries - num_purged_entries; i++) {
        log_entries[i] = log_entries[i + num_purged_entries];
    }

    // Update the number of log entries to reflect the purged entries
    num_log_entries -= num_purged_entries;

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_mutex);
}

// Function to compact the log structure
void compact_log() {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_mutex);

    // Iterate over the log entries and remove any gaps between them
    int num_compacted_entries = 0;
    for (int i = 0; i < num_log_entries - 1; i++) {
        if (log_entries[i + 1] - log_entries[i] > 1) {
            memmove(log_entries[i], log_entries[i + 1], sizeof(ModemLogEntry));
            num_compacted_entries++;
        }
    }

    // Update the number of log entries to reflect the compacted entries
    num_log_entries -= num_compacted_entries;

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_mutex);
}

// Function to export the log entries to a file in a standardized format
