    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the duration for purging old entries (in seconds)
#define PURGE_DURATION 3600

// Define the frequency for compacting the log (in seconds)
#define COMPACT_FREQUENCY 86400

// Define the log level filter for filtering logs
#define LOG_LEVEL_FILTER 2 // Critical messages only

// Define the logging rate limiter to prevent overwhelming the system with too many log requests
#define LOGGING_RATE_LIMITER 100

// Define the function for managing the dynamic array of log entries
void manageLog(ModemLogEntry* log, int maxSize) {
    // Initialize the log array if it is not initialized yet
    if (log == NULL) {
        log = malloc(sizeof(ModemLogEntry) * maxSize);
        memset(log, 0, sizeof(ModemLogEntry) * maxSize);
    }

    // Add a new entry to the log array
    void addEntry(ModemLogEntry* entry) {
        if (entry == NULL) {
            return;
        }

        // Check if the log is full and needs to be purged
        if (log->size >= maxSize) {
            purgeOldEntries();
        }

        // Add the new entry to the log array
        log[log->size++] = *entry;
    }

    // Retrieve an entry from the log array by timestamp
    ModemLogEntry* getEntryByTimestamp(time_t timestamp) {
        for (int i = 0; i < log->size; i++) {
            if (log[i].timestamp == timestamp) {
                return &log[i];
            }
        }
        return NULL;
    }

    // Clear the entire log array
    void clearLog() {
        memset(log, 0, sizeof(ModemLogEntry) * maxSize);
        log->size = 0;
    }

    // Purge old entries from the log array to free up resources
    void purgeOldEntries() {
        time_t currentTime = time(NULL);
        for (int i = 0; i < log->size; i++) {
            if (log[i].timestamp < currentTime - PURGE_DURATION) {
                memmove(&log[i], &log[i + 1], sizeof(ModemLogEntry) * (log->size - i));
                log->size--;
                i--;
            }
        }
    }

    // Compact the log structure to reduce memory fragmentation
    void compactLog() {
        for (int i = 0; i < log->size; i++) {
            if (log[i].message != NULL) {
                char* newMessage = realloc(log[i].message, strlen(log[i].message));
                if (newMessage == NULL) {
                    // Handle memory allocation failure
                } else {
                    log[i].message = newMessage;
                }
            }
        }
    }

    // Export the log entries to a file in a standardized format for external analysis tools
    void exportLog(FILE* file) {
        if (file == NULL) {
            return;
        }

        // Write the log entries to the file
        for (int i = 0; i < log->size; i++) {
            fprintf(file, "%lu %d %s\n", log[i].timestamp, log[i].level, log[i].message);
        }
    }
}
