// Function to initialize a dynamic array of Network Flow Statistics structures
NetworkFlowStatistics* init_flow_stats(int num_flows, long min_byte_threshold, long max_byte_threshold) {
    // Allocate memory for the array of Network Flow Statistics structures
    NetworkFlowStatistics *flow_stats = (NetworkFlowStatistics*)malloc(num_flows * sizeof(NetworkFlowStatistics));

    // Initialize each structure with a unique flow identifier, timestamp, byte count, and packet count
    for (int i = 0; i < num_flows; i++) {
        flow_stats[i].flow_id = i + 1;
        flow_stats[i].timestamp = time(NULL);
        flow_stats[i].byte_count = 0;
        flow_stats[i].packet_count = 0;
    }

    // Filter the array based on minimum and maximum byte thresholds if specified
    if (min_byte_threshold > 0 || max_byte_threshold > 0) {
        int filtered_flows = 0;
        for (int i = 0; i < num_flows; i++) {
            if ((min_byte_threshold > 0 && flow_stats[i].byte_count >= min_byte_threshold) ||
                (max_byte_threshold > 0 && flow_stats[i].byte_count <= max_byte_threshold)) {
                filtered_flows++;
            } else {
                // Swap the current structure with the last structure in the array and decrement the size of the array
                NetworkFlowStatistics temp = flow_stats[i];
                flow_stats[i] = flow_stats[num_flows - 1];
                flow_stats[num_flows - 1] = temp;
                num_flows--;
            }
        }
        printf("Filtered %d flows based on byte threshold\n", filtered_flows);
    }

    return flow_stats;
}
