vector<NetworkFlowStatistics> initializeNetworkFlowStatistics(const vector<NetworkFlowStatistics>& input, const int minByteThreshold = 0, const int maxByteThreshold = INT_MAX) {
    // Create a new vector to store the filtered network flow statistics
    vector<NetworkFlowStatistics> output;

    // Iterate over the input and filter based on byte threshold
