// Define the maximum list size and segment size
#define MAX_LIST_SIZE 1024
#define SEGMENT_SIZE 1500

// Define the MAC_PDU structure
typedef struct {
    MAC_HEADER header;
    uint8_t *segments[SEGMENT_SIZE];
} MAC_PDU;

// Define the function to manage the list of MAC_PDU structures
int manage_mac_pdu_list(MAC_PDU **list, int n) {
    // Check if the input parameter is valid
    if (n < 0 || n > MAX_LIST_SIZE) {
        return -1;
    }

    // Allocate memory for the list and its elements
    MAC_PDU *pdu = malloc(sizeof(MAC_PDU) * n);
    if (!pdu) {
        return -2;
    }

    // Initialize the list with the given number of elements
    for (int i = 0; i < n; i++) {
        pdu[i].header.sequence_number = rand() % 65536;
        for (int j = 0; j < SEGMENT_SIZE; j++) {
            pdu[i].segments[j] = malloc(sizeof(uint8_t) * 1500);
            if (!pdu[i].segments[j]) {
                return -3;
            }
        }
    }

    // Ensure that the sequence numbers are unique across all structures in the list
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (pdu[i].header.sequence_number == pdu[j].header.sequence_number) {
                pdu[i].header.sequence_number++;
            }
        }
    }

    // Validate that all structures are properly initialized before adding them to the list
    for (int i = 0; i < n; i++) {
        if (!pdu[i].header.valid || !pdu[i].segments) {
            return -4;
        }
    }

    // Logging for debugging purposes
    printf("Successfully created %d MAC_PDU structures\n", n);

    // Seed the random number generator for reproducible testing scenarios
    srand(time(NULL));

    // Synchronize access to shared resources if the function is to be used in a multi-threaded environment
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Add the list of MAC_PDU structures to the shared memory
    *list = pdu;

    // Release the lock on the shared resources
    pthread_mutex_unlock(&mutex);

    return 0;
}

