// Define the structure for each entry in the dynamic array
typedef struct {
    int id;
    char* name;
} Entry;

// Define the structure for the dynamic array itself
typedef struct {
    Entry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

// Function to add a new entry to the dynamic array
void addEntry(DynamicArray* array, int id, char* name) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&array->mutex);

    // Check if the array needs to be resized
    if (array->count == array->capacity) {
        // Double the capacity of the array
        array->capacity *= 2;

        // Reallocate memory for the entries
        Entry** newEntries = realloc(array->entries, array->capacity * sizeof(Entry*));
        if (newEntries == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }

        // Update the entries pointer and unlock the mutex
        array->entries = newEntries;
        pthread_mutex_unlock(&array->mutex);
    }

    // Create a new entry and add it to the end of the array
    Entry* newEntry = malloc(sizeof(Entry));
    if (newEntry == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    newEntry->id = id;
    newEntry->name = name;
    array->entries[array->count++] = newEntry;

    // Unlock the mutex and return
    pthread_mutex_unlock(&array->mutex);
}

// Function to retrieve an entry from the dynamic array by ID
Entry* getEntry(DynamicArray* array, int id) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&array->mutex);

    // Search for the entry with the specified ID
    for (size_t i = 0; i < array->count; i++) {
        if (array->entries[i]->id == id) {
            Entry* result = array->entries[i];
            pthread_mutex_unlock(&array->mutex);
            return result;
        }
    }

    // If the entry was not found, return NULL and unlock the mutex
    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

// Function to clear the entire dynamic array
void clearArray(DynamicArray* array) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&array->mutex);

    // Free all of the entries in the array
    for (size_t i = 0; i < array->count; i++) {
        free(array->entries[i]);
    }

    // Reset the count and capacity of the array
    array->count = 0;
    array->capacity = 1;

    // Unlock the mutex and return
    pthread_mutex_unlock(&array->mutex);
}
