#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Custom data structure to represent a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Dynamic array of log entries
static ModemLogEntry* log_entries = NULL;

// Maximum size of the log in number of entries
#define MAX_LOG_SIZE 1024

// Current size of the log in number of entries
static int current_log_size = 0;

// Lock for synchronizing access to the log
static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new entry to the log
void add_entry(time_t timestamp, int level, char* message) {
    // Acquire lock on the log
    pthread_mutex_lock(&log_lock);

    // Check if the log is full and needs to be pruned
    if (current_log_size == MAX_LOG_SIZE) {
        // Prune the least recently used entry
        ModemLogEntry* entry = &log_entries[0];
        for (int i = 1; i < current_log_size; i++) {
            if (entry->timestamp < log_entries[i].timestamp) {
                entry = &log_entries[i];
            }
        }
        free(entry->message);
        memmove(&log_entries[0], &log_entries[1], sizeof(ModemLogEntry) * (current_log_size - 1));
        current_log_size--;
    }

    // Add the new entry to the log
    ModemLogEntry* new_entry = &log_entries[current_log_size];
    new_entry->timestamp = timestamp;
    new_entry->level = level;
    new_entry->message = strdup(message);
    current_log_size++;

    // Release lock on the log
    pthread_mutex_unlock(&log_lock);
}

// Function to retrieve an entry from the log by timestamp
ModemLogEntry* get_entry_by_timestamp(time_t timestamp) {
    // Acquire lock on the log
    pthread_mutex_lock(&log_lock);

    // Search for the entry with the specified timestamp
    ModemLogEntry* entry = NULL;
    for (int i = 0; i < current_log_size; i++) {
        if (log_entries[i].timestamp == timestamp) {
            entry = &log_entries[i];
            break;
        }
    }

    // Release lock on the log
    pthread_mutex_unlock(&log_lock);

    return entry;
}

// Function to clear the entire log
void clear_log() {
    // Acquire lock on the log
    pthread_mutex_lock(&log_lock);

    // Free all entries in the log
    for (int i = 0; i < current_log_size; i++) {
        free(log_entries[i].message);
    }
    current_log_size = 0;

    // Release lock on the log
    pthread_mutex_unlock(&log_lock);
}

// Function to filter logs based on log levels and timestamps
void filter_logs(int min_level, time_t min_timestamp) {
    // Acquire lock on the log
    pthread_mutex_lock(&log_lock);

    // Filter the log entries based on the specified criteria
    for (int i = 0; i < current_log_size; i++) {
        if (log_entries[i].level < min_level || log_entries[i].timestamp < min_timestamp) {
            free(log_entries[i].message);
            memmove(&log_entries[i], &log_entries[i + 1], sizeof(ModemLogEntry) * (current_log_size - i));
            current_log_size--;
        }
    }

    // Release lock on the log
    pthread_mutex_unlock(&log_lock);
}

// Function to serialize and deserialize the log data for persistence and recovery purposes
void serialize_log(FILE* file) {
    // Acquire lock on the log
    pthread_mutex_lock(&log_lock);

    // Serialize the log entries to the specified file
    for (int i = 0; i < current_log_size; i++) {
        fprintf(file, "%lu %d %s\n", log_entries[i].timestamp, log_entries[i].level, log_entries[i].message);
    }

    // Release lock on the log
    pthread_mutex_unlock(&log_lock);
}

void deserialize_log(FILE* file) {
    // Acquire lock on the log
    pthread_mutex_lock(&log_lock);

    // Deserialize the log entries from the specified file
    while (!feof(file)) {
        char line[1024];
        fgets(line, 1024, file);
        sscanf(line, "%lu %d %s", &log_entries[current_log_size].timestamp, &log_entries[current_log_size].level, log_entries[current_log_size].message);
        current_log_size++;
    }

    // Release lock on the log
    pthread_mutex_unlock(&log_lock);
}
