        for (auto it = sessions_.begin(); it != sessions_.end(); ++it) {
            if (!it->isActive && now - it->startTime > sessionTimeout_) {
                it->isActive = false;
            }
        }
    }

    // Limit the number of active sessions to the specified maximum size, removing least recently used sessions first
    void limitSessions() {
        std::lock_guard<std::mutex> lock(sessionsMutex_);
