// Define the frequency for compacting the log structure (in seconds)
#define LOG_COMPACT_FREQ 300

// Define the logging levels
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_WARN 3
#define LOG_LEVEL_ERROR 4

// Define the log entry structure
typedef struct {
    time_t timestamp;
    int level;
    char *message;
} ModemLogEntry;

// Define the log array and its mutex
ModemLogEntry *log_array = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new log entry
void add_log_entry(time_t timestamp, int level, char *message) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // Check if the log array is full and needs to be resized
    if (log_array == NULL || log_size >= MAX_LOG_SIZE) {
        // Resize the log array by 50%
        int new_size = log_size + (log_size / 2);
        ModemLogEntry *new_array = realloc(log_array, new_size * sizeof(ModemLogEntry));
        if (new_array == NULL) {
            // Reallocation failed, free the old array and return
            free(log_array);
            log_array = NULL;
            pthread_mutex_unlock(&log_mutex);
            return;
        }
        log_array = new_array;
    }

    // Add the new log entry to the end of the array
    log_array[log_size].timestamp = timestamp;
    log_array[log_size].level = level;
    log_array[log_size].message = strdup(message);
    log_size++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to retrieve a log entry by timestamp
ModemLogEntry *get_log_entry(time_t timestamp) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // Search for the log entry with the specified timestamp
    int i;
    for (i = 0; i < log_size; i++) {
        if (log_array[i].timestamp == timestamp) {
            break;
        }
    }

    // Return NULL if no matching log entry was found
    if (i >= log_size) {
        pthread_mutex_unlock(&log_mutex);
        return NULL;
    }

    // Create a copy of the log entry and unlock the mutex
    ModemLogEntry *entry = malloc(sizeof(ModemLogEntry));
    memcpy(entry, &log_array[i], sizeof(ModemLogEntry));
    pthread_mutex_unlock(&log_mutex);

    // Return the copy of the log entry
    return entry;
}

// Function to clear the entire log
void clear_log() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // Free all log entries and reset the log size
    for (int i = 0; i < log_size; i++) {
        free(log_array[i].message);
    }
    log_size = 0;

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to purge old log entries
void purge_old_logs() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // Iterate over the log array and remove any entries older than LOG_PURGE_AGE
    time_t current_time = time(NULL);
    for (int i = 0; i < log_size; i++) {
        if (current_time - log_array[i].timestamp > LOG_PURGE_AGE) {
            free(log_array[i].message);
            log_size--;
            memmove(&log_array[i], &log_array[i + 1], (log_size - i) * sizeof(ModemLogEntry));
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to compact the log structure
void compact_log() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // Iterate over the log array and remove any empty entries
    for (int i = 0; i < log_size; i++) {
        if (log_array[i].message == NULL) {
            free(log_array[i].message);
            log_size--;
            memmove(&log_array[i], &log_array[i + 1], (log_size - i) * sizeof(ModemLogEntry));
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to filter logs based on a specified log level
void filter_logs(int level) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // Iterate over the log array and remove any entries with a lower log level than the specified level
    for (int i = 0; i < log_size; i++) {
        if (log_array[i].level < level) {
            free(log_array[i].message);
            log_size--;
            memmove(&log_array[i], &log_array[i + 1], (log_size - i) * sizeof(ModemLogEntry));
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

