// Initialize the log array and set the maximum size
void init_log(int max_size) {
    // Allocate memory for the log array
    log = (struct ModemLogEntry *)malloc(max_size * sizeof(struct ModemLogEntry));
    if (!log) {
        perror("Failed to allocate memory for log");
        exit(1);
    }

    // Set the maximum size of the log array
    max_log_size = max_size;
}

// Add a new entry to the log
void add_entry(struct ModemLogEntry *entry) {
    // Acquire the mutex for the log array
    pthread_mutex_lock(&log_mutex);

    // Check if the log is full and needs to be purged
    if (log_size >= max_log_size) {
        purge_old_entries();
    }

    // Add the new entry to the log array
    log[log_size++] = *entry;

    // Release the mutex for the log array
    pthread_mutex_unlock(&log_mutex);
}

// Retrieve an entry from the log by timestamp
struct ModemLogEntry *get_entry(time_t timestamp) {
    struct ModemLogEntry *entry = NULL;

    // Acquire the mutex for the log array
    pthread_mutex_lock(&log_mutex);

    // Iterate through the log entries and find the matching entry
    for (int i = 0; i < log_size; i++) {
        if (log[i].timestamp == timestamp) {
            entry = &log[i];
            break;
        }
    }

    // Release the mutex for the log array
    pthread_mutex_unlock(&log_mutex);

    return entry;
}

// Clear all entries from the log
void clear_log() {
    // Acquire the mutex for the log array
    pthread_mutex_lock(&log_mutex);

