    pthread_mutex_unlock(&log_mutex);
}

// Purge old entries from the log to free up resources
void purge_old_entries() {
    // Acquire the mutex for the log array
    pthread_mutex_lock(&log_purge_mutex);

    // Iterate through the log entries and find the oldest entry
    time_t oldest_timestamp = 0;
    for (int i = 0; i < log_size; i++) {
        if (!oldest_timestamp || log[i].timestamp < oldest_timestamp) {
            oldest_timestamp = log[i].timestamp;
        }
    }

    // Check if the oldest entry is older than the maximum age
    time_t current_time = time(NULL);
    if (current_time - oldest_timestamp > MAX_ENTRY_AGE) {
        // Remove the oldest entry from the log
        for (int i = 0; i < log_size; i++) {
            if (log[i].timestamp == oldest_timestamp) {
                memmove(&log[i], &log[i + 1], (log_size - i - 1) * sizeof(struct ModemLogEntry));
                log_size--;
                break;
            }
        }
    }

    // Release the mutex for the log array
    pthread_mutex_unlock(&log_purge_mutex);
}

// Compact the log structure to reduce memory fragmentation
void compact_log() {
    // Acquire the mutex for the log array
    pthread_mutex_lock(&log_compact_mutex);

