    struct ModemLogEntry *new_log = (struct ModemLogEntry *)malloc(log_size * sizeof(struct ModemLogEntry));
    if (!new_log) {
        perror("Failed to allocate memory for compacted log");
        exit(1);
    }

    // Copy the entries from the old log array to the new log array
    memcpy(new_log, log, log_size * sizeof(struct ModemLogEntry));

    // Free the memory allocated to the old log array
    free(log);

    // Set the new log array as the current log array
    log = new_log;

    // Release the mutex for the log array
    pthread_mutex_unlock(&log_compact_mutex);
}

