    pthread_mutex_lock(&log_mutex);

    // Iterate through the log entries and remove any that do not match the specified level
    for (int i = 0; i < log_size; i++) {
        if (log[i].level != level) {
            memmove(&log[i], &log[i + 1], (log_size - i - 1) * sizeof(struct ModemLogEntry));
            log_size--;
            i--;
        }
    }

    // Release the mutex for the log array
    pthread_mutex_unlock(&log_mutex);
}

// Start the log purge thread
void start_purge_thread() {
    // Create a new thread to purge old entries from the log
    pthread_create(&log_purge_thread, NULL, &purge_old_entries, NULL);
}

// Start the log compaction thread
void start_compact_thread() {
    // Create a new thread to compact the log structure
    pthread_create(&log_compact_thread, NULL, &compact_log, NULL);
}

// Start the log export thread
void start_export_thread(FILE *file) {
    // Create a new thread to export the log entries to a file
    pthread_create(&log_export_thread, NULL, &export_log, file);
}

// Stop the log purge thread
void stop_purge_thread() {
    // Join the log purge thread
    pthread_join(log_purge_thread, NULL);
}

// Stop the log compaction thread
void stop_compact_thread() {
    // Join the log compaction thread
    pthread_join(log_compact_thread, NULL);
}

// Stop the log export thread
void stop_export_thread() {
    // Join the log export thread
    pthread_join(log_export_thread, NULL);
}
