#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

// Define constants for command line arguments
#define ARG_TARGET_DIR "target-dir"
#define ARG_OUTPUT_FILE "output-file"
#define ARG_VERBOSITY "verbosity"

// Define constants for file I/O operations
#define BUFFER_SIZE 4096
#define MAX_LINE_LENGTH 1024

// Define data structures to store statistics
struct FileStats {
    int numLines;
    double avgWordLength;
    char mostFrequentWord[MAX_LINE_LENGTH];
};

// Function prototypes
void processDirectory(char *targetDir, FILE *outputFile, int verbosity);
void processFile(FILE *file, struct FileStats *stats);
void aggregateStats(struct FileStats *stats, int numFiles);
void printStats(struct FileStats *stats, FILE *outputFile);
void logProcessingTime(char *filename, double processingTime);
void handleError(char *message);

int main(int argc, char **argv) {
    // Check command line arguments
    if (argc < 3) {
        fprintf(stderr, "Usage: %s [%s] [%s] [%s]\n", argv[0], ARG_TARGET_DIR, ARG_OUTPUT_FILE, ARG_VERBOSITY);
        return 1;
    }

    // Initialize variables
    char *targetDir = argv[1];
    FILE *outputFile = NULL;
    int verbosity = atoi(argv[3]);

    // Open output file if specified
    if (strcmp(argv[2], "-") != 0) {
        outputFile = fopen(argv[2], "w");
        if (!outputFile) {
            handleError("Failed to open output file");
        }
    }

    // Process directory and generate statistics
    processDirectory(targetDir, outputFile, verbosity);

    // Clean up resources
    if (outputFile) {
        fclose(outputFile);
    }

    return 0;
}

void processDirectory(char *targetDir, FILE *outputFile, int verbosity) {
    DIR *dir = opendir(targetDir);
    if (!dir) {
        handleError("Failed to open directory");
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Open file and process it
        FILE *file = fopen(filename, "r");
        if (!file) {
            handleError("Failed to open file");
        }

        struct FileStats stats;
        memset(&stats, 0, sizeof(struct FileStats));
        processFile(file, &stats);
        aggregateStats(&stats, 1);

        // Log processing time and statistics
        logProcessingTime(filename, stats.numLines / (double)stats.avgWordLength);
        if (verbosity >= 2) {
            printStats(&stats, outputFile);
        }

        fclose(file);
    }

    closedir(dir);
}

void processFile(FILE *file, struct FileStats *stats) {
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        // Count number of lines and average word length
        stats->numLines++;
        int numWords = 0;
        for (int i = 0; i < strlen(buffer); i++) {
            if (buffer[i] == ' ') {
                numWords++;
            }
        }
        stats->avgWordLength += (double)numWords / (double)stats->numLines;

        // Identify most frequent word
        char *word = strtok(buffer, " ");
        while (word != NULL) {
            if (strlen(word) > strlen(stats->mostFrequentWord)) {
                strcpy(stats->mostFrequentWord, word);
            }
            word = strtok(NULL, " ");
        }
    }
}

void aggregateStats(struct FileStats *stats, int numFiles) {
    // Aggregate statistics across all files
    for (int i = 0; i < numFiles; i++) {
        stats->numLines += stats[i].numLines;
        stats->avgWordLength += stats[i].avgWordLength;
        if (strlen(stats->mostFrequentWord) < strlen(stats[i].mostFrequentWord)) {
            strcpy(stats->mostFrequentWord, stats[i].mostFrequentWord);
        }
    }
}

void printStats(struct FileStats *stats, FILE *outputFile) {
    // Print statistics to output file
    fprintf(outputFile, "Total lines: %d\n", stats->numLines);
    fprintf(outputFile, "Average word length: %.2f\n", stats->avgWordLength);
    fprintf(outputFile, "Most frequent word: %s\n", stats->mostFrequentWord);
}

void logProcessingTime(char *filename, double processingTime) {
    // Log processing time and statistics to output file
    FILE *logFile = fopen("processing_time.log", "a");
    if (!logFile) {
        handleError("Failed to open log file");
    }
    fprintf(logFile, "%s: %.2f\n", filename, processingTime);
    fclose(logFile);
}

void handleError(char *message) {
    // Handle errors gracefully
    perror(message);
    exit(1);
}
