#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the maximum age of a log entry in seconds
#define MAX_LOG_AGE 3600

// Define the log level for each message
typedef enum {
    CRITICAL,
    ERROR,
    WARNING,
    INFO,
    DEBUG
} LogLevel;

// Define the structure to hold a single log entry
typedef struct {
    time_t timestamp;
    LogLevel level;
    char* message;
} ModemLogEntry;

// Define the structure to hold the entire log array
typedef struct {
    int size;
    int capacity;
    ModemLogEntry* entries[MAX_LOG_SIZE];
} ModemLog;

// Function to add a new entry to the log
void addLogEntry(ModemLog* log, time_t timestamp, LogLevel level, char* message) {
    // Check if the log is full and needs to be purged
    if (log->size == log->capacity) {
        purgeOldEntries(log);
    }

    // Add the new entry to the log
    ModemLogEntry* entry = malloc(sizeof(ModemLogEntry));
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = strdup(message);
    log->entries[log->size++] = entry;
}

// Function to retrieve a log entry by timestamp
ModemLogEntry* getLogEntryByTimestamp(ModemLog* log, time_t timestamp) {
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i]->timestamp == timestamp) {
            return log->entries[i];
        }
    }
    return NULL;
}

// Function to clear the entire log
void clearLog(ModemLog* log) {
    for (int i = 0; i < log->size; i++) {
        free(log->entries[i]->message);
        free(log->entries[i]);
    }
    log->size = 0;
}

// Function to purge old entries from the log
void purgeOldEntries(ModemLog* log) {
    // Calculate the maximum age of an entry in seconds
    time_t maxAge = MAX_LOG_AGE * 1000000;

    // Iterate through the log and remove any entries older than the maximum age
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i]->timestamp < time(NULL) - maxAge) {
            free(log->entries[i]->message);
            free(log->entries[i]);
            log->size--;
            i--;
        }
    }
}

// Function to filter logs based on a specified log level
void filterLogsByLevel(ModemLog* log, LogLevel level) {
    // Iterate through the log and remove any entries that do not match the specified level
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i]->level != level) {
            free(log->entries[i]->message);
            free(log->entries[i]);
            log->size--;
            i--;
        }
    }
}

// Function to export the log entries to a file in a standardized format
void exportLogToFile(ModemLog* log, char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");

    // Iterate through the log and write each entry to the file
    for (int i = 0; i < log->size; i++) {
        fprintf(fp, "%s %d %s\n", ctime(&log->entries[i]->timestamp), log->entries[i]->level, log->entries[i]->message);
    }

    // Close the output file
    fclose(fp);
}

// Function to dynamically adjust the log capacity based on system resource availability and current load
void adjustLogCapacity(ModemLog* log) {
    // Calculate the current system load
    float load = getSystemLoad();

    // Adjust the log capacity based on the current load
    if (load < 0.5) {
        log->capacity += 16;
    } else if (load >= 0.5 && load < 0.8) {
        log->capacity += 32;
    } else {
        log->capacity += 64;
    }
}

// Function to monitor and report on log activity
void monitorLogActivity(ModemLog* log) {
    // Calculate the number of entries in the log
    int numEntries = log->size;

    // Calculate the average entry size
    int avgEntrySize = 0;
    for (int i = 0; i < log->size; i++) {
        avgEntrySize += strlen(log->entries[i]->message);
    }
    avgEntrySize /= log->size;

    // Calculate the total log size
    int totalLogSize = 0;
    for (int i = 0; i < log->size; i++) {
        totalLogSize += strlen(log->entries[i]->message);
    }

    // Print the log activity metrics to the console
    printf("Number of entries: %d\n", numEntries);
    printf("Average entry size: %d\n", avgEntrySize);
    printf("Total log size: %d\n", totalLogSize);
}
