// Define the lock for protecting the log array
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a new entry is added to the log
pthread_cond_t log_added = PTHREAD_COND_INITIALIZER;

// Define the log array
ModemLogEntry* log_array = NULL;

// Define the number of entries in the log
int num_entries = 0;

// Define the maximum size of the log array
int max_log_size = MAX_LOG_SIZE;

// Define the log level filter
int log_level_filter = LOG_LEVEL_FILTER;

// Define the duration for purging old entries (in seconds)
