// Function to add a new entry to the log
void add_log_entry(time_t timestamp, int level, char* message) {
    // Lock the log array
    pthread_mutex_lock(&log_lock);

    // Check if the log is full
    if (num_entries == max_log_size) {
        // Purge old entries if necessary
        purge_old_entries();
    }

    // Add the new entry to the log array
    log_array[num_entries].timestamp = timestamp;
    log_array[num_entries].level = level;
    log_array[num_entries].message = message;
    num_entries++;

    // Signal that a new entry has been added to the log
    pthread_cond_signal(&log_added);

    // Unlock the log array
    pthread_mutex_unlock(&log_lock);
}

// Function to retrieve all entries in the log with a specified timestamp
ModemLogEntry* get_log_entries(time_t timestamp) {
    // Lock the log array
    pthread_mutex_lock(&log_lock);

    // Find the first entry with the specified timestamp
    int i = 0;
    while (i < num_entries && log_array[i].timestamp != timestamp) {
        i++;
    }

    // If no entries were found, return NULL
    if (i == num_entries) {
        pthread_mutex_unlock(&log_lock);
        return NULL;
    }

    // Create a new array to hold the retrieved entries
    ModemLogEntry* retrieved_entries = malloc(sizeof(ModemLogEntry) * (num_entries - i));

    // Copy the retrieved entries into the new array
    for (int j = 0; j < num_entries - i; j++) {
        retrieved_entries[j] = log_array[i + j];
    }

    // Unlock the log array
    pthread_mutex_unlock(&log_lock);

    return retrieved_entries;
}

// Function to clear all entries in the log
void clear_log() {
    // Lock the log array
    pthread_mutex_lock(&log_lock);

    // Set the number of entries to 0
    num_entries = 0;

    // Unlock the log array
    pthread_mutex_unlock(&log_lock);
}

// Function to purge old entries from the log
void purge_old_entries() {
    // Lock the log array
    pthread_mutex_lock(&log_lock);

    // Find the first entry that is older than the purge duration
    int i = 0;
    while (i < num_entries && log_array[i].timestamp >= time(NULL) - purge_duration) {
        i++;
    }

    // If no entries were found, return
    if (i == num_entries) {
        pthread_mutex_unlock(&log_lock);
        return;
    }

    // Remove the old entries from the log array
    for (int j = i; j < num_entries; j++) {
        log_array[j] = log_array[j + 1];
    }

    // Decrement the number of entries in the log
    num_entries--;

    // Unlock the log array
    pthread_mutex_unlock(&log_lock);
}

// Function to compact the log structure
void compact_log() {
    // Lock the log array
    pthread_mutex_lock(&log_lock);

    // Find the first entry that is not in use
    int i = 0;
    while (i < num_entries && log_array[i].timestamp != 0) {
        i++;
    }

    // If no entries were found, return
    if (i == num_entries) {
        pthread_mutex_unlock(&log_lock);
        return;
    }

    // Remove the unused entries from the log array
    for (int j = i; j < num_entries; j++) {
        log_array[j] = log_array[j + 1];
    }

    // Decrement the number of entries in the log
    num_entries--;

    // Unlock the log array
    pthread_mutex_unlock(&log_lock);
}

// Function to export logs to a file
void export_logs(char* filename) {
    // Lock the log array
    pthread_mutex_lock(&log_lock);

    // Open the output file
    FILE* fp = fopen(filename, "w");

    // Write the log entries to the file
    for (int i = 0; i < num_entries; i++) {
        fprintf(fp, "%ld %d %s\n", log_array[i].timestamp, log_array[i].level, log_array[i].message);
    }

    // Close the output file
    fclose(fp);

    // Unlock the log array
    pthread_mutex_unlock(&log_lock);
}
