        // Process each file in a separate thread to improve concurrency
        pthread_t thread;
        int rc = pthread_create(&thread, NULL, process_file, (void *)file->d_name);
        if (rc != 0) {
            fprintf(stderr, "Error creating thread: %s\n", strerror(rc));
            exit(1);
        }
    }

