    pthread_exit(NULL);
}

// Function to process a single file in a separate thread
void *process_file(char *filename) {
    // Open the file and read it line by line
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        exit(1);
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    int line_count = 0;
    double average_word_length = 0;
    char most_frequent_word[100] = "";

    while ((read = getline(&line, &len, fp)) != -1) {
        // Increment line count and calculate average word length
        line_count++;
        average_word_length += strlen(line);

        // Identify the most frequently occurring word in the file
        char *token = strtok(line, " ");
        while (token != NULL) {
            if (strcmp(most_frequent_word, "") == 0 || strcasecmp(most_frequent_word, token) > 0) {
                strcpy(most_frequent_word, token);
            }
            token = strtok(NULL, " ");
        }
    }

    // Close the file and update statistics
    fclose(fp);
    file_stats_t stats;
    stats.line_count = line_count;
    stats.average_word_length = average_word_length / line_count;
    strcpy(stats.most_frequent_word, most_frequent_word);

    // Write log entry for the file and update statistics
    write_log(&stats);
}

// Function to write a log entry for a processed file
void write_log(log_entry_t *log_entry) {
    // Open the log file in append mode
    FILE *fp = fopen("log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        exit(1);
    }

    // Write log entry to the file
    fprintf(fp, "%s\t%ld\t%s\n", ctime(&log_entry->processing_time), log_entry->total_lines, log_entry->most_frequent_words[0]);

    // Close the log file and update statistics
    fclose(fp);
}
