void log(int level, const char* message) {
    // Get the current time
    time_t timestamp = time(NULL);

    // Create a new log entry
    ModemLogEntry entry = {timestamp, level, strdup(message)};

    // Add the entry to the log array
    pthread_mutex_lock(&log_mutex);
    if (log_size < MAX_LOG_SIZE) {
        log_array[log_size++] = entry;
    } else {
        // Purge old entries if necessary
        purge_old_entries(timestamp - retention_policy.retention_days * 24 * 60 * 60);

        // Add the new entry to the log array
        log_array[log_size++] = entry;
    }
    pthread_mutex_unlock(&log_mutex);
}

// Purge old entries from the log array
void purge_old_entries(time_t timestamp) {
    // Find the first entry that is older than the specified timestamp
    int i = 0;
    while (i < log_size && log_array[i].timestamp >= timestamp) {
        i++;
    }

    // Remove all entries before the specified timestamp
    for (int j = 0; j < i; j++) {
        free(log_array[j].message);
    }
    log_size -= i;
}

// Compact the log structure to reduce memory fragmentation
void compact_log() {
    // Create a new array with the same size as the old one
    ModemLogEntry* new_array = malloc(sizeof(ModemLogEntry) * log_size);

    // Copy the entries from the old array to the new one
    for (int i = 0; i < log_size; i++) {
        new_array[i] = log_array[i];
    }

    // Free the old array and set the new one as the current one
    free(log_array);
    log_array = new_array;
}

// Export the log entries to a file in a standardized format
