    // Open the file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Write the log entries to the file
    for (int i = 0; i < log_size; i++) {
        fprintf(fp, "%d %s\n", log_array[i].timestamp, log_array[i].message);
    }

    // Close the file
    fclose(fp);
}
