    log_array = (LogEntry*)malloc(sizeof(LogEntry) * MAX_LOG_SIZE);
    if (!log_array) {
        fprintf(stderr, "Failed to allocate memory for log array\n");
        exit(1);
    }

    // Initialize the log size and lock
    log_size = 0;
    pthread_mutex_init(&log_lock, NULL);
}

// Add a new entry to the log
void add_entry(time_t timestamp, int level, const char* message) {
    // Acquire the lock for thread-safe access to the log array
    pthread_mutex_lock(&log_lock);

    // Check if the log is full and needs to be purged
    if (log_size >= MAX_LOG_SIZE) {
        purge_old_entries();
    }

    // Add the new entry to the log array
    LogEntry* entry = &log_array[log_size++];
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = strdup(message);

    // Release the lock and return
    pthread_mutex_unlock(&log_lock);
}

// Retrieve all entries in the log with a specified timestamp
void retrieve_entries(time_t timestamp) {
    // Acquire the lock for thread-safe access to the log array
    pthread_mutex_lock(&log_lock);

    // Iterate over the log array and print each entry that matches the timestamp
    for (size_t i = 0; i < log_size; i++) {
        LogEntry* entry = &log_array[i];
        if (entry->timestamp == timestamp) {
            printf("Log entry at %ld: level=%d, message=%s\n", timestamp, entry->level, entry->message);
        }
    }

    // Release the lock and return
    pthread_mutex_unlock(&log_lock);
}

// Clear all entries in the log
void clear_log() {
    // Acquire the lock for thread-safe access to the log array
    pthread_mutex_lock(&log_lock);

    // Free the memory allocated for the log array and reset the size
    free(log_array);
    log_array = NULL;
    log_size = 0;

    // Release the lock and return
    pthread_mutex_unlock(&log_lock);
}

// Purge old entries from the log to free up resources
void purge_old_entries() {
    // Acquire the lock for thread-safe access to the log array
    pthread_mutex_lock(&log_lock);

    // Iterate over the log array and remove any entries that are older than MAX_ENTRY_AGE
    time_t current_time = time(NULL);
    size_t new_size = 0;
    for (size_t i = 0; i < log_size; i++) {
        LogEntry* entry = &log_array[i];
        if (current_time - entry->timestamp <= MAX_ENTRY_AGE) {
            log_array[new_size++] = *entry;
        } else {
            free(entry->message);
        }
    }

    // Resize the log array to the new size and release the lock
    log_size = new_size;
    pthread_mutex_unlock(&log_lock);
}

// Compact the log structure to reduce memory fragmentation
void compact_log() {
    // Acquire the lock for thread-safe access to the log array
    pthread_mutex_lock(&log_lock);

    // Iterate over the log array and remove any empty entries
    size_t new_size = 0;
    for (size_t i = 0; i < log_size; i++) {
        LogEntry* entry = &log_array[i];
        if (entry->message) {
            log_array[new_size++] = *entry;
        } else {
            free(entry->message);
        }
    }

    // Resize the log array to the new size and release the lock
    log_size = new_size;
    pthread_mutex_unlock(&log_lock);
}

// Export the log entries to a file in a standardized format
void export_log(const char* filename) {
    // Acquire the lock for thread-safe access to the log array
    pthread_mutex_lock(&log_lock);

    // Open the output file and write each entry to it
    FILE* fp = fopen(filename, "w");
    if (!fp) {
        perror("Failed to open output file");
        exit(1);
    }
    for (size_t i = 0; i < log_size; i++) {
        LogEntry* entry = &log_array[i];
        fprintf(fp, "%ld %d %s\n", entry->timestamp, entry->level, entry->message);
    }

    // Close the output file and release the lock
    fclose(fp);
    pthread_mutex_unlock(&log_lock);
}

// Filter log entries based on a specified log level
void filter_log(int level) {
    // Acquire the lock for thread-safe access to the log array
    pthread_mutex_lock(&log_lock);

    // Iterate over the log array and print each entry that matches the specified level
    for (size_t i = 0; i < log_size; i++) {
        LogEntry* entry = &log_array[i];
        if (entry->level == level) {
            printf("Log entry at %ld: level=%d, message=%s\n", timestamp, entry->level, entry->message);
        }
    }

    // Release the lock and return
    pthread_mutex_unlock(&log_lock);
}
