    // Find the first and last indices of the data range in the buffer
    int start_index = find_first_index(start_time);
    int end_index = find_last_index(end_time);

    // Check if there is any data within the specified time range
    if (start_index == -1 || end_index == -1) {
        return;
    }

    // Iterate over the data points in the specified range and print them
    for (int i = start_index; i <= end_index; i++) {
        SensorData* data = &buffer->buffer[i];
        printf("Sensor ID: %d, Timestamp: %ld, Temperature: %.2f, Humidity: %.2f, Description: %s\n",
            data->sensor_id, data->timestamp, data->temperature, data->humidity, data->description);
    }
}

// Define the function to clear the entire dataset
void clear_data() {
    buffer->size = 0;
}

// Define the function to limit the number of entries per sensor
void limit_entries(int max_entries) {
    // Check if the maximum number of entries is valid
    if (max_entries < 1 || max_entries > MAX_ENTRIES) {
        return;
    }

    // Iterate over the data points in the buffer and remove any duplicates
    for (int i = 0; i < buffer->size; i++) {
        SensorData* data = &buffer->buffer[i];
        if (data->sensor_id == sensor_id) {
            // Remove the duplicate entry from the buffer
            memmove(&buffer->buffer[i], &buffer->buffer[i + 1], sizeof(SensorData));
            buffer->size--;
            i--;
        }
    }
}

// Define the function to purge old data
void purge_old_data() {
    // Get the current time
    time_t now = time(NULL);

    // Iterate over the data points in the buffer and remove any that are older than the specified duration
    for (int i = 0; i < buffer->size; i++) {
        SensorData* data = &buffer->buffer[i];
        if (now - data->timestamp > OLD_DATA_DURATION) {
            // Remove the old entry from the buffer
            memmove(&buffer->buffer[i], &buffer->buffer[i + 1], sizeof(SensorData));
            buffer->size--;
            i--;
        }
    }
}

// Define the function to compact the data structures
void compact_data() {
    // Get the current time
    time_t now = time(NULL);

    // Iterate over the data points in the buffer and remove any that are older than the specified duration
    for (int i = 0; i < buffer->size; i++) {
        SensorData* data = &buffer->buffer[i];
        if (now - data->timestamp > OLD_DATA_DURATION) {
            // Remove the old entry from the buffer
            memmove(&buffer->buffer[i], &buffer->buffer[i + 1], sizeof(SensorData));
            buffer->size--;
            i--;
        }
    }
}

// Define the function to export data to a file
void export_data() {
    // Check if there is any data to export
    if (buffer->size == 0) {
        return;
    }

    // Open the output file for writing
    FILE* fp = fopen("output.txt", "w");
    if (fp == NULL) {
        printf("Error: Unable to open output file\n");
        return;
    }

    // Iterate over the data points in the buffer and write them to the file
    for (int i = 0; i < buffer->size; i++) {
        SensorData* data = &buffer->buffer[i];
        fprintf(fp, "Sensor ID: %d, Timestamp: %ld, Temperature: %.2f, Humidity: %.2f, Description: %s\n",
            data->sensor_id, data->timestamp, data->temperature, data->humidity, data->description);
    }

    // Close the output file
    fclose(fp);
}

// Define the function to resize the buffer
void resize_buffer() {
    // Check if the buffer is already at its maximum size
    if (buffer->capacity == MAX_BUFFER_SIZE) {
        return;
    }

    // Increase the capacity of the buffer by a factor of 2
    int new_capacity = buffer->capacity * 2;
    if (new_capacity > MAX_BUFFER_SIZE) {
        new_capacity = MAX_BUFFER_SIZE;
    }

    // Reallocate the memory for the buffer
    SensorData* new_buffer = realloc(buffer->buffer, new_capacity * sizeof(SensorData));
    if (new_buffer == NULL) {
        printf("Error: Unable to resize buffer\n");
        return;
    }

    // Update the buffer with the new memory location and size
    buffer->buffer = new_buffer;
    buffer->capacity = new_capacity;
}

// Define the function to find the first index of a data point in the buffer
int find_first_index(time_t timestamp) {
    // Iterate over the data points in the buffer and find the first one with a timestamp greater than or equal to the specified time
    for (int i = 0; i < buffer->size; i++) {
        SensorData* data = &buffer->buffer[i];
        if (data->timestamp >= timestamp) {
            return i;
        }
    }

    // If no data point was found, return -1
    return -1;
}

// Define the function to find the last index of a data point in the buffer
int find_last_index(time_t timestamp) {
    // Iterate over the data points in the buffer and find the last one with a timestamp less than or equal to the specified time
    for (int i = buffer->size - 1; i >= 0; i--) {
        SensorData* data = &buffer->buffer[i];
        if (data->timestamp <= timestamp) {
            return i;
        }
    }

    // If no data point was found, return -1
    return -1;
}
