public class ModemLog {
  private static final int MAX_LOG_SIZE = 1000; // maximum number of log entries
  private static final int PURGE_FREQUENCY = 60; // frequency for purging old entries (in seconds)
  private static final int COMPACT_FREQUENCY = 300; // frequency for compacting the log (in seconds)
  private static final int LOG_LEVEL_FILTER = LogLevel.CRITICAL; // minimum log level to filter by

  private List<ModemLogEntry> logEntries;
  private ExecutorService executor;

  public ModemLog() {
    this.logEntries = new ArrayList<>();
    this.executor = Executors.newSingleThreadExecutor();
  }

  public void addEntry(long timestamp, LogLevel level, String message) {
    // check if the log size has reached its maximum capacity
    if (logEntries.size() >= MAX_LOG_SIZE) {
      purgeOldEntries();
    }

    // add the new entry to the log
    ModemLogEntry entry = new ModemLogEntry(timestamp, level, message);
    logEntries.add(entry);
  }

  public List<ModemLogEntry> getEntriesByTimestamp(long timestamp) {
    return logEntries.stream()
      .filter(entry -> entry.getTimestamp() >= timestamp)
      .collect(Collectors.toList());
  }

  public void clearLog() {
    logEntries.clear();
  }

  private void purgeOldEntries() {
    // create a new list of entries that are not older than the maximum age
    List<ModemLogEntry> newEntries = logEntries.stream()
      .filter(entry -> entry.getTimestamp() >= System.currentTimeMillis() - MAX_LOG_SIZE)
      .collect(Collectors.toList());

    // update the log entries with the new list
    logEntries = newEntries;
  }

  private void compactLog() {
    // create a new list of entries that are not older than the maximum age
    List<ModemLogEntry> newEntries = logEntries.stream()
      .filter(entry -> entry.getTimestamp() >= System.currentTimeMillis() - MAX_LOG_SIZE)
      .collect(Collectors.toList());

    // update the log entries with the new list
    logEntries = newEntries;
  }

  private void filterLogByLevel(LogLevel level) {
    // create a new list of entries that are not older than the maximum age
    List<ModemLogEntry> newEntries = logEntries.stream()
      .filter(entry -> entry.getLevel().ordinal() >= level.ordinal())
      .collect(Collectors.toList());

    // update the log entries with the new list
    logEntries = newEntries;
  }

  public void shutdown() {
    executor.shutdown();
  }
}
