// Define the structure for a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the configuration settings for the log
typedef struct {
    // The maximum number of entries in the log
    int max_log_size;
    // The frequency of log entry retention checks (in seconds)
    int retention_check_frequency;
    // The duration after which old entries are purged (in seconds)
    int purge_duration;
    // The compression level for the log data (0-9, 0 being no compression and 9 being maximum compression)
    int compression_level;
} LogConfig;

// Define the log structure
typedef struct {
    // The array of log entries
    ModemLogEntry* entries;
    // The number of log entries in the array
    int num_entries;
    // The configuration settings for the log
    LogConfig config;
} Log;

// Define the function to add a new entry to the log
void add_log_entry(Log* log, time_t timestamp, int level, char* message) {
    // Check if the log is full and needs to be purged
    if (log->num_entries >= log->config.max_log_size) {
        purge_old_entries(log);
    }

    // Add the new entry to the log array
    ModemLogEntry* new_entry = malloc(sizeof(ModemLogEntry));
    new_entry->timestamp = timestamp;
    new_entry->level = level;
    new_entry->message = message;
    log->entries[log->num_entries++] = *new_entry;
}

// Define the function to retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(Log* log, time_t timestamp) {
    // Iterate through the log entries and find the one with the matching timestamp
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i].timestamp == timestamp) {
            return &log->entries[i];
        }
    }

    // If no entry is found, return NULL
    return NULL;
}

// Define the function to clear the entire log
void clear_log(Log* log) {
    // Free the memory allocated for the log entries
    free(log->entries);
    log->num_entries = 0;
}

// Define the function to purge old entries from the log
void purge_old_entries(Log* log) {
    // Iterate through the log entries and find the ones that are older than the purge duration
    time_t current_time = time(NULL);
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i].timestamp < current_time - log->config.purge_duration) {
            // Free the memory allocated for the entry and shift the remaining entries down
            free(log->entries[i].message);
            memmove(&log->entries[i], &log->entries[i + 1], (log->num_entries - i - 1) * sizeof(ModemLogEntry));
            log->num_entries--;
        }
    }
}

// Define the function to filter logs based on a specified log level
void filter_logs(Log* log, int level) {
    // Iterate through the log entries and remove any that do not match the specified log level
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i].level != level) {
            // Free the memory allocated for the entry and shift the remaining entries down
            free(log->entries[i].message);
            memmove(&log->entries[i], &log->entries[i + 1], (log->num_entries - i - 1) * sizeof(ModemLogEntry));
            log->num_entries--;
        }
    }
}

// Define the function to export the log entries to a file in a standardized format
void export_log(Log* log, char* filename, bool binary) {
    // Open the output file for writing
    FILE* outfile = fopen(filename, "w");
    if (outfile == NULL) {
        printf("Error: Could not open output file.\n");
        return;
    }

    // Write the log entries to the output file in a standardized format
    for (int i = 0; i < log->num_entries; i++) {
        fprintf(outfile, "%lu %d %s\n", log->entries[i].timestamp, log->entries[i].level, log->entries[i].message);
    }

    // Close the output file
    fclose(outfile);
}
