```
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ModemLogService {
  private static final Logger LOGGER = Logger.getLogger(ModemLogService.class.getName());
  private static final int MAX_LOG_SIZE = 10000; // maximum number of log entries to store
  private static final long PURGE_INTERVAL = 60 * 60 * 1000; // purge interval in milliseconds
  private static final int LOG_LEVEL_FILTER = Level.INFO; // filter out messages with lower level than INFO

  private ConcurrentHashMap<String, List<ModemLogEntry>> logs; // map of tenant IDs to log entries
  private ExecutorService executor; // background thread for purging old entries

  public ModemLogService() {
    this.logs = new ConcurrentHashMap<>();
    this.executor = Executors.newSingleThreadExecutor();
    this.executor.scheduleAtFixedRate(this::purgeOldEntries, PURGE_INTERVAL, PURGE_INTERVAL, TimeUnit.MILLISECONDS);
  }

  public void addLogEntry(String tenantId, ModemLogEntry entry) {
    List<ModemLogEntry> log = logs.getOrDefault(tenantId, new ArrayList<>());
    log.add(entry);
    logs.put(tenantId, log);
  }

  public List<ModemLogEntry> getLogEntries(String tenantId) {
    return logs.getOrDefault(tenantId, Collections.emptyList());
  }

  public void clearLog(String tenantId) {
    logs.remove(tenantId);
  }

  private void purgeOldEntries() {
    long now = System.currentTimeMillis();
    for (Map.Entry<String, List<ModemLogEntry>> entry : logs.entrySet()) {
      String tenantId = entry.getKey();
      List<ModemLogEntry> log = entry.getValue();
      Iterator<ModemLogEntry> iterator = log.iterator();
      while (iterator.hasNext()) {
        ModemLogEntry entry = iterator.next();
        if (now - entry.getTimestamp() > PURGE_INTERVAL) {
          iterator.remove();
        }
      }
    }
  }

  public void setLogLevelFilter(int logLevel) {
    this.LOG_LEVEL_FILTER = logLevel;
  }

  public int getLogLevelFilter() {
    return this.LOG_LEVEL_FILTER;
  }
}
```
