    size_t num_filtered_metrics = 0;
    for (size_t i = 0; i < num_metrics; i++) {
        if (metrics[i].bandwidth_usage >= bandwidth && metrics[i].latency <= latency && metrics[i].packet_loss <= packet_loss && metrics[i].error_rate <= error_rate) {
            filtered_metrics[num_filtered_metrics++] = metrics[i];
        }
