}

// Define the function to purge outdated metrics
void purge_outdated_metrics() {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < num_metrics; i++) {
        if (current_time - metrics[i].timestamp > RETENTION_PERIOD) {
