            memmove(&metrics[i], &metrics[i + 1], sizeof(NetworkMetric) * (num_metrics - i));
            num_metrics--;
        }
    }
}

// Define the function to compact the metrics array
void compact_metrics() {
    size_t new_size = num_metrics * sizeof(NetworkMetric);
    NetworkMetric *new_metrics = (NetworkMetric*)realloc(metrics, new_size);
    if (new_metrics == NULL) {
        // Handle the error
    } else {
        metrics = new_metrics;
    }
}

// Define the function to export metrics to a file in JSON format
void export_metrics(FILE *file) {
    fprintf(file, "[");
    for (size_t i = 0; i < num_metrics; i++) {
        if (i > 0) {
            fprintf(file, ",");
        }
        fprintf(file, "{\"timestamp\":%ld,\"bandwidth_usage\":%d,\"latency\":%d,\"packet_loss\":%.2f,\"error_rate\":%.2f}", metrics[i].timestamp, metrics[i].bandwidth_usage, metrics[i].latency, metrics[i].packet_loss, metrics[i].error_rate);
    }
