    // Iterate through the log array and find entries older than the maximum age
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i]->timestamp < max_age) {
            free(log->entries[i]);
            log->num_entries--;
        }
    }
}

// Function to filter logs based on a specified log level
void filter_logs(LogArray* log, int level) {
    // Iterate through the log array and remove entries with a lower log level than the specified level
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i]->level < level) {
            free(log->entries[i]);
            log->num_entries--;
        }
    }
}

// Function to export the log entries to a file in a standardized format
void export_logs(LogArray* log, char* filename) {
