        return entry;
      }
    }
    return ModemLogEntry(); // Return an empty entry if not found
  }

  // Retrieve an entry from the log by log level
  ModemLogEntry getEntryByLevel(int logLevel) {
    std::lock_guard<std::mutex> lock(mutex_);
    for (auto& entry : entries_) {
