// Define constants for configuration parameters
#define DEFAULT_MAX_LINE_COUNT 1000000
#define DEFAULT_LOG_ROTATION_INTERVAL 86400 // 24 hours in seconds
#define DEFAULT_COMPRESSION_FORMAT "gzip"
#define DEFAULT_VERBOSITY_LEVEL 1
