void process_file(char *file_name);
void aggregate_stats(file_stats_t *stats, int line_count, double average_word_length, char *most_frequent_word);

// Define functions for logging and resource management
void log_processing_time(log_entry_t *entry);
void log_aggregated_stats(aggregated_stats_t *stats);
void manage_resources();

int main(int argc, char **argv) {
    // Parse command-line arguments and set default values for configuration parameters
    parse_command_line_args(argc, argv);

    // Initialize data structures for storing statistics and logs
    file_stats_t *file_stats = malloc(sizeof(file_stats_t) * DEFAULT_MAX_FILE_SIZE);
    aggregated_stats_t *aggregated_stats = malloc(sizeof(aggregated_stats_t));
    log_entry_t *log_entries = malloc(sizeof(log_entry_t) * DEFAULT_MAX_LINE_COUNT);

    // Initialize variables for tracking processing time and resource usage
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    int file_count = 0;
    long total_line_count = 0;
    double average_word_length = 0.0;
    char most_frequent_word[DEFAULT_MAX_WORD_COUNT];
    strcpy(most_frequent_word, "");

    // Iterate over files in the target directory and process each file
    DIR *dir = opendir(target_directory);
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *file_name = entry->d_name;
        if (strcmp(file_name, ".") == 0 || strcmp(file_name, "..") == 0) continue;
        process_file(file_name);
    }
    closedir(dir);

    // Aggregate statistics across all files in the directory
    for (int i = 0; i < file_count; i++) {
        aggregate_stats(&aggregated_stats->most_frequent_words[i], file_stats[i].line_count, file_stats[i].average_word_length, file_stats[i].most_frequent_word);
    }

    // Log processing time and aggregated statistics
    clock_gettime(CLOCK_MONOTONIC, &end);
    log_processing_time(&log_entries[file_count]);
    log_aggregated_stats(aggregated_stats);

    // Clean up resources
    manage_resources();

    return 0;
}

void parse_command_line_args(int argc, char **argv) {
    int c;
    while ((c = getopt(argc, argv, "o:v:c:")) != -1) {
        switch (c) {
            case 'o':
                output_file = optarg;
                break;
            case 'v':
                verbosity_level = atoi(optarg);
                break;
            case 'c':
                compression_format = optarg;
                break;
        }
    }
}

void process_file(char *file_name) {
    // Open file and read line by line without loading entire file into memory
    FILE *file = fopen(file_name, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }
    char *line = malloc(sizeof(char) * DEFAULT_MAX_LINE_LENGTH);
    int line_count = 0;
    double average_word_length = 0.0;
    char most_frequent_word[DEFAULT_MAX_WORD_LENGTH];
    strcpy(most_frequent_word, "");
    while (fgets(line, DEFAULT_MAX_LINE_LENGTH, file) != NULL) {
        // Increment line count and calculate average word length
        line_count++;
        int word_length = 0;
        char *token = strtok(line, " ");
        while (token != NULL) {
            word_length += strlen(token);
            token = strtok(NULL, " ");
        }
        average_word_length += (double)word_length / line_count;

        // Identify most frequent word in file
        int word_count = 0;
        char *word = malloc(sizeof(char) * DEFAULT_MAX_LINE_LENGTH);
        while ((token = strtok(NULL, " ")) != NULL) {
            if (strcmp(token, most_frequent_word) > 0) {
                strcpy(most_frequent_word, token);
            }
            word_count++;
        }
    }

    // Aggregate statistics for file and log processing time
    aggregate_stats(&file_stats[file_count], line_count, average_word_length, most_frequent_word);
    log_processing_time(&log_entries[file_count]);

    // Close file and increment file count
    fclose(file);
    file_count++;
}

void aggregate_stats(file_stats_t *stats, int line_count, double average_word_length, char *most_frequent_word) {
    stats->line_count += line_count;
    stats->average_word_length += average_word_length;
    if (strcmp(most_frequent_word, "") == 0) {
        strcpy(stats->most_frequent_word, most_frequent_word);
    } else if (strcmp(stats->most_frequent_word, "") == 0 || strcmp(most_frequent_word, stats->most_frequent_word) > 0) {
        strcpy(stats->most_frequent_word, most_frequent_word);
    }
}

void log_processing_time(log_entry_t *entry) {
    // Log processing time and file name
    entry->file_name = target_directory;
    clock_gettime(CLOCK_MONOTONIC, &entry->processing_time);
}

void log_aggregated_stats(aggregated_stats_t *stats) {
    // Log aggregated statistics and most frequent words
    stats->total_line_count = file_stats[file_count].line_count;
    stats->most_frequent_word_count = 0;
    for (int i = 0; i < DEFAULT_MAX_WORD_COUNT; i++) {
        if (strcmp(file_stats[i].most_frequent_word, "") == 0) break;
        strcpy(stats->most_frequent_words[i], file_stats[i].most_frequent_word);
        stats->most_frequent_word_count++;
    }
}

void manage_resources() {
    // Release memory for data structures and close output file
    free(file_stats);
    free(aggregated_stats);
    free(log_entries);
    if (output_file != NULL) fclose(output_file);
}
