// Define the structure for a network session
typedef struct NetworkSession {
    int id;
    char* client_ip;
    time_t start_time;
    char* data;
} NetworkSession;

// Define the maximum number of active sessions
#define MAX_ACTIVE_SESSIONS 1000

// Define the duration for which a session is considered expired
#define SESSION_EXPIRATION_DURATION 3600 // in seconds

// Define the frequency for purging expired sessions
#define PURGE_FREQUENCY 120 // in seconds

// Define the structure for a session manager
typedef struct SessionManager {
    NetworkSession* sessions;
    int num_sessions;
    int max_sessions;
} SessionManager;

// Initialize a new session manager
void init_session_manager(SessionManager* sm) {
    // Allocate memory for the session array
    sm->sessions = (NetworkSession*)malloc(sizeof(NetworkSession) * MAX_ACTIVE_SESSIONS);
    if (!sm->sessions) {
        printf("Error: Failed to allocate memory for session manager\n");
        exit(1);
    }
    // Initialize the number of sessions and maximum number of sessions
    sm->num_sessions = 0;
    sm->max_sessions = MAX_ACTIVE_SESSIONS;
}

// Add a new session to the manager
void add_session(SessionManager* sm, int id, char* client_ip, time_t start_time, char* data) {
    // Check if there is space for a new session
    if (sm->num_sessions >= sm->max_sessions) {
        printf("Error: Maximum number of active sessions reached\n");
        return;
    }
    // Allocate memory for the new session
    NetworkSession* new_session = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (!new_session) {
        printf("Error: Failed to allocate memory for new session\n");
        return;
    }
    // Initialize the new session
    new_session->id = id;
    new_session->client_ip = client_ip;
    new_session->start_time = start_time;
    new_session->data = data;
    // Add the new session to the manager
    sm->sessions[sm->num_sessions++] = *new_session;
}

// Retrieve a session by client IP address
NetworkSession* get_session(SessionManager* sm, char* client_ip) {
    // Iterate over all sessions and find the one with the matching client IP
    for (int i = 0; i < sm->num_sessions; i++) {
        if (!strcmp(sm->sessions[i].client_ip, client_ip)) {
            return &sm->sessions[i];
        }
    }
    // Return NULL if no matching session is found
    return NULL;
}

// Clear all sessions in the manager
void clear_sessions(SessionManager* sm) {
    // Set the number of sessions to 0
    sm->num_sessions = 0;
}

// Purge expired sessions from the manager
void purge_expired_sessions(SessionManager* sm) {
    // Iterate over all sessions and find the ones that are expired
    for (int i = 0; i < sm->num_sessions; i++) {
        if ((time(NULL) - sm->sessions[i].start_time) > SESSION_EXPIRATION_DURATION) {
            // Remove the expired session from the manager
            memmove(&sm->sessions[i], &sm->sessions[i + 1], (sm->num_sessions - i - 1) * sizeof(NetworkSession));
            sm->num_sessions--;
            i--; // Decrement the loop counter to avoid skipping a session
        }
    }
}

// Compact the session structures in the manager
