    if (!connections) {
        perror("Failed to allocate memory for TCP connection records");
        exit(1);
    }
}

// Function to add a new TCP connection record to the dynamic array
void add_connection(int socket_descriptor, struct sockaddr_in remote_address) {
    // Check if there is enough space in the dynamic array for a new record
    if (num_connections >= max_connections) {
        // If not, resize the array by doubling its size
        max_connections *= 2;
        connections = (tcp_connection_record *)realloc(connections, max_connections * sizeof(tcp_connection_record));
        if (!connections) {
            perror("Failed to reallocate memory for TCP connection records");
            exit(1);
        }
    }

    // Add the new record to the dynamic array
    connections[num_connections].socket_descriptor = socket_descriptor;
    connections[num_connections].remote_address = remote_address;
    num_connections++;
