// Define a mutex to synchronize access to the connections array
pthread_mutex_t connections_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to update the TCP connection statistics
void update_tcp_connection_stats(int conn_id, unsigned long bytes_transferred, double packet_loss_rate, double latency) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&connections_mutex);

    // Update the connection statistics
    connections[conn_id].bytes_transferred = bytes_transferred;
    connections[conn_id].packet_loss_rate = packet_loss_rate;
    connections[conn_id].latency = latency;

    // Release the mutex
    pthread_mutex_unlock(&connections_mutex);
}

// Function to generate random values for the TCP connection statistics
void generate_random_tcp_connection_stats(int conn_id) {
    // Generate random values for bytes transferred, packet loss rate, and latency
    unsigned long bytes_transferred = rand() % 10000;
    double packet_loss_rate = (double)rand() / RAND_MAX;
    double latency = (double)rand() / RAND_MAX;

    // Update the connection statistics
    update_tcp_connection_stats(conn_id, bytes_transferred, packet_loss_rate, latency);
}

// Function to handle overflow of the connections array
void handle_overflow(int conn_id) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&connections_mutex);

    // Check if the connections array is full
    if (conn_id == MAX_CONNECTIONS - 1) {
        // Resize the connections array by doubling its size
        tcp_connection_stats *new_connections = realloc(connections, sizeof(tcp_connection_stats) * MAX_CONNECTIONS * 2);
        if (new_connections == NULL) {
            printf("Error: Failed to resize connections array\n");
            exit(1);
        }
        connections = new_connections;
    }

    // Release the mutex
    pthread_mutex_unlock(&connections_mutex);
}

// Function to handle periodic updates of the connection statistics based on simulated network conditions
void update_connection_stats(int conn_id) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&connections_mutex);

    // Generate random values for bytes transferred, packet loss rate, and latency
    generate_random_tcp_connection_stats(conn_id);

    // Release the mutex
    pthread_mutex_unlock(&connections_mutex);
}
```
