    char most_frequent_word[MAX_WORD_LENGTH];
} FileStats;

// Define data structure for aggregated statistics
typedef struct {
    int total_line_count;
    double average_word_length;
    char most_frequent_word[MAX_WORD_LENGTH];
} AggregateStats;

// Function to process a single file
void processFile(const char *filename, FileStats *stats) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Initialize variables for line counting and word length calculation
    int line_count = 0;
    double average_word_length = 0.0;
    char most_frequent_word[MAX_WORD_LENGTH] = "";

    // Read the file line by line
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file) != NULL) {
        // Increment line count and calculate average word length
        line_count++;
        for (int i = 0; i < strlen(buffer); i++) {
            if (isalpha(buffer[i])) {
                average_word_length += 1.0 / strlen(buffer);
            }
        }

        // Identify the most frequent word in the line
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            if (strcasecmp(most_frequent_word, token) < 0) {
                strcpy(most_frequent_word, token);
            }
            token = strtok(NULL, " ");
        }
    }

    // Close the file and update the statistics
    fclose(file);
    stats->line_count = line_count;
    stats->average_word_length = average_word_length;
    strcpy(stats->most_frequent_word, most_frequent_word);
}

// Function to aggregate statistics across multiple files
void aggregateStats(const char *target_dir, AggregateStats *aggregate) {
    // Initialize variables for aggregation
    int total_line_count = 0;
    double average_word_length = 0.0;
    char most_frequent_word[MAX_WORD_LENGTH] = "";

    // Iterate over files in the target directory
    DIR *dir = opendir(target_dir);
    if (dir == NULL) {
        perror("opendir");
        return;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip non-files and hidden files
        if (!S_ISREG(entry->d_type) || entry->d_name[0] == '.') {
            continue;
        }

        // Process the file
        char filename[MAX_FILENAME_LENGTH];
        strcpy(filename, target_dir);
        strcat(filename, "/");
        strcat(filename, entry->d_name);
        FileStats stats;
        processFile(filename, &stats);

        // Aggregate statistics
        total_line_count += stats.line_count;
        average_word_length += stats.average_word_length;
        if (strcasecmp(most_frequent_word, stats.most_frequent_word) < 0) {
            strcpy(most_frequent_word, stats.most_frequent_word);
        }
    }

    // Close the directory and update the aggregate statistics
    closedir(dir);
    aggregate->total_line_count = total_line_count;
    aggregate->average_word_length = average_word_length / total_line_count;
    strcpy(aggregate->most_frequent_word, most_frequent_word);
}

// Function to handle command line arguments
void handleArgs(int argc, char *argv[]) {
    // Check for the presence of required command line arguments
    if (argc < 2) {
        printf("Usage: %s [options]", argv[0]);
        return;
    }

    // Parse command line arguments
    const char *target_dir = NULL;
    const char *output_file = NULL;
    int verbosity = 1;
    bool compression = false;
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-d") || !strcmp(argv[i], "--target-dir")) {
            target_dir = argv[++i];
        } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output-file")) {
            output_file = argv[++i];
        } else if (!strcmp(argv[i], "-v") || !strcmp(argv[i], "--verbosity")) {
            verbosity = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-c") || !strcmp(argv[i], "--compression")) {
            compression = true;
        }
    }

    // Check for the presence of required command line arguments
    if (target_dir == NULL) {
        printf("Error: Target directory not specified\n");
        return;
    }

    // Process the target directory and generate aggregated statistics
    AggregateStats aggregate;
    aggregateStats(target_dir, &aggregate);

    // Print the aggregated statistics to the console
    printf("Total line count: %d\n", aggregate.total_line_count);
    printf("Average word length: %.2f\n", aggregate.average_word_length);
    printf("Most frequent word: %s\n", aggregate.most_frequent_word);

    // Write the aggregated statistics to a file if specified
    if (output_file != NULL) {
        FILE *file = fopen(output_file, "w");
        if (file == NULL) {
            perror("fopen");
            return;
        }
        fprintf(file, "Total line count: %d\n", aggregate.total_line_count);
        fprintf(file, "Average word length: %.2f\n", aggregate.average_word_length);
        fprintf(file, "Most frequent word: %s\n", aggregate.most_frequent_word);
        fclose(file);
    }
}

// Main function to handle command line arguments and process files
int main(int argc, char *argv[]) {
    // Handle command line arguments
    handleArgs(argc, argv);
    return 0;
}
