// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the structure for a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the function to manage the dynamic array of log entries
void manageLog(ModemLogEntry** log, size_t* capacity) {
    // Check if the log is full and needs to be resized
    if (*capacity == 0 || *log == NULL) {
        // Allocate a new log with twice the current capacity
        *capacity = (*capacity > 0) ? 2 * *capacity : MAX_LOG_SIZE;
        *log = realloc(*log, sizeof(ModemLogEntry) * *capacity);
    }
}

// Define the function to add a new log entry
void addLogEntry(ModemLogEntry** log, size_t* capacity, time_t timestamp, int level, char* message) {
    // Manage the log array and allocate more space if necessary
    manageLog(log, capacity);

    // Add the new log entry to the end of the array
    (*log)[*capacity - 1].timestamp = timestamp;
    (*log)[*capacity - 1].level = level;
    (*log)[*capacity - 1].message = message;
}

// Define the function to retrieve a log entry by timestamp
ModemLogEntry* getLogEntry(ModemLogEntry** log, size_t capacity, time_t timestamp) {
    // Iterate through the log array and find the matching entry
    for (size_t i = 0; i < capacity; i++) {
        if ((*log)[i].timestamp == timestamp) {
            return &(*log)[i];
        }
    }

    // If no match is found, return NULL
    return NULL;
}

// Define the function to clear the entire log
void clearLog(ModemLogEntry** log, size_t* capacity) {
    // Free the memory allocated for the log array
    free(*log);

    // Reset the capacity and log pointer to NULL
    *capacity = 0;
    *log = NULL;
}
