    new_entry->timestamp = timestamp;
    new_entry->log_level = log_level;
    new_entry->message = message;
    buffer->entries[buffer->count++] = new_entry;
}

// Function to retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(LogBuffer* buffer, time_t timestamp) {
    // Iterate through the entries and find the one with the matching timestamp
    for (size_t i = 0; i < buffer->count; i++) {
        if (buffer->entries[i]->timestamp == timestamp) {
            return buffer->entries[i];
        }
    }

    // If no entry is found, return NULL
    return NULL;
}

// Function to clear the entire log buffer
void clear_log_buffer(LogBuffer* buffer) {
    for (size_t i = 0; i < buffer->count; i++) {
        free(buffer->entries[i]);
    }
    buffer->count = 0;
}

// Function to limit the number of entries in the log buffer to a specified maximum size
void limit_log_buffer_size(LogBuffer* buffer, size_t max_size) {
    if (buffer->count > max_size) {
        // Remove excess entries from the end of the buffer
        for (size_t i = 0; i < buffer->count - max_size; i++) {
            free(buffer->entries[i]);
        }
        buffer->count -= max_size;
    }
}

// Function to filter logs based on a specified log level
void filter_log_level(LogBuffer* buffer, int log_level) {
    // Iterate through the entries and remove any that do not match the specified log level
    for (size_t i = 0; i < buffer->count; i++) {
        if (buffer->entries[i]->log_level != log_level) {
            free(buffer->entries[i]);
            buffer->count--;
            i--;
        }
    }
}

// Function to resize the log buffer when it is full
void resize_log_buffer(LogBuffer* buffer) {
    // Double the capacity of the buffer and reallocate memory for the entries
    size_t new_capacity = buffer->capacity * 2;
    ModemLogEntry** new_entries = malloc(new_capacity * sizeof(ModemLogEntry));
    memcpy(new_entries, buffer->entries, buffer->count * sizeof(ModemLogEntry));
    free(buffer->entries);
    buffer->entries = new_entries;
    buffer->capacity = new_capacity;
}

