    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the log array and its mutex
ModemLogEntry* log_array = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new entry to the log
void add_log_entry(time_t timestamp, int level, char* message) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // Check if the log array is full and needs to be resized
    if (log_array == NULL || log_size >= MAX_LOG_SIZE) {
        // Resize the log array by a factor of 2
        int new_size = log_size * 2;
        ModemLogEntry* new_array = realloc(log_array, new_size * sizeof(ModemLogEntry));
        if (new_array == NULL) {
            // Reallocation failed, free the old array and return
            free(log_array);
            log_array = NULL;
            pthread_mutex_unlock(&log_mutex);
            return;
        }
        log_array = new_array;
    }

    // Add the new entry to the log array
    log_array[log_size].timestamp = timestamp;
    log_array[log_size].level = level;
    log_array[log_size].message = strdup(message);
    log_size++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to retrieve a log entry by timestamp
