    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to limit the number of entries in the log to a specified maximum size
void limit_log_size(int max_size) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // If the log array is already at its maximum size, return
    if (log_size >= max_size) {
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    // Iterate over the log array and remove any entries that are older than the specified duration
    time_t current_time = time(NULL);
    int i;
    for (i = 0; i < log_size; i++) {
        if (current_time - log_array[i].timestamp > MAX_LOG_DURATION) {
            free(log_array[i].message);
            memmove(&log_array[i], &log_array[i + 1], (log_size - i - 1) * sizeof(ModemLogEntry));
            log_size--;
            i--;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to compact the log structure periodically
void compact_log() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // If the log array is already at its maximum size, return
    if (log_size >= MAX_LOG_SIZE) {
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    // Iterate over the log array and remove any entries that are older than the specified duration
    time_t current_time = time(NULL);
    int i;
    for (i = 0; i < log_size; i++) {
        if (current_time - log_array[i].timestamp > MAX_LOG_DURATION) {
            free(log_array[i].message);
            memmove(&log_array[i], &log_array[i + 1], (log_size - i - 1) * sizeof(ModemLogEntry));
            log_size--;
            i--;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to export the log entries to a file in a standardized format
void export_log(char* filename) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log_mutex);

    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening log export file");
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    // Iterate over the log array and write each entry to the output file
    int i;
    for (i = 0; i < log_size; i++) {
        fprintf(fp, "%lu %d %s\n", log_array[i].timestamp, log_array[i].level, log_array[i].message);
    }

    // Close the output file and unlock the mutex
    fclose(fp);
    pthread_mutex_unlock(&log_mutex);
}
