// Define a linked list node to store the log entries
typedef struct LogNode {
    ModemLogEntry entry;
    struct LogNode* next;
} LogNode;

// Define a global variable to keep track of the total memory usage
size_t total_memory = 0;

// Define a function to add a new log entry
void add_log_entry(ModemLogEntry entry) {
    // Acquire a lock on the log list
    pthread_mutex_lock(&log_list_lock);

    // Create a new node for the log entry
    LogNode* new_node = malloc(sizeof(LogNode));
    new_node->entry = entry;
    new_node->next = NULL;

    // Add the new node to the end of the list
    if (log_list == NULL) {
        log_list = new_node;
    } else {
        LogNode* current = log_list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Update the total memory usage
    total_memory += sizeof(ModemLogEntry);

    // Release the lock on the log list
    pthread_mutex_unlock(&log_list_lock);
}

