                current->next = new_node;
            }
        }
        current = current->next;
    }

    // Release the lock on the log list
    pthread_mutex_unlock(&log_list_lock);
}

// Define a function to support logging entries asynchronously
void async_logging() {
    // Acquire a lock on the log list
    pthread_mutex_lock(&log_list_lock);

    // Iterate through the log entries and print them
