#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>

#define BUFFER_SIZE 4096
#define MAX_LINE_COUNT 1000000
#define MAX_MEMORY_USAGE 500000000 // 500 MB

// Struct to hold information about a file being processed
struct file_info {
    char *filename;
    int fd;
    off_t offset;
};

// Struct to hold information about a line being processed
struct line_info {
    char *line;
    size_t length;
};

// Function to parse command line arguments and provide usage information if no input file is provided
void parse_args(int argc, char **argv) {
    // Check if any input files are specified
    if (argc < 2) {
        printf("Usage: %s [options] <input_file>\n", argv[0]);
        printf("Options:\n");
        printf("\t--manpage\tDisplay comprehensive usage documentation.\n");
        printf("\t-cs\tConvert all characters in the input file to uppercase.\n");
        printf("\t-o <output_file>\tWrite the processed content to a specified output file instead of printing to stdout.\n");
        printf("\t-l <line_count>\tPrint only the first `line_count` lines from the input file.\n");
        printf("\t-f <filter_string>\tOnly process lines containing `filter_string`.\n");
        exit(1);
    }
}

// Function to open a file and return its file descriptor
int open_file(char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        exit(1);
    }
    return fd;
}

// Function to close a file descriptor and handle any errors that may occur
void close_file(int fd) {
    if (close(fd) == -1) {
        perror("Error closing input file");
        exit(1);
    }
}

// Function to read a line from a file descriptor and return it as a string
char *read_line(int fd, size_t *length) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read = read(fd, buffer, BUFFER_SIZE);
    if (bytes_read == -1) {
        perror("Error reading from input file");
        exit(1);
    }
    *length = bytes_read;
    return strndup(buffer, *length);
}

// Function to convert a line of text to uppercase
char *to_uppercase(char *line) {
    char *uppercase_line = malloc(strlen(line));
    for (int i = 0; i < strlen(line); i++) {
        uppercase_line[i] = toupper(line[i]);
    }
    return uppercase_line;
}

// Function to write a line of text to an output file
void write_line(char *line, char *output_file) {
    int fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Error opening output file");
        exit(1);
    }
    ssize_t bytes_written = write(fd, line, strlen(line));
    if (bytes_written == -1) {
        perror("Error writing to output file");
        exit(1);
    }
    close(fd);
}

// Function to filter a line of text based on a given string
char *filter_line(char *line, char *filter_string) {
    if (strstr(line, filter_string)) {
        return strdup(line);
    } else {
        return NULL;
    }
}

// Function to process a line of text and perform the desired operations
void process_line(char *line, char *output_file, int line_count) {
    // Convert line to uppercase if requested
    if (strcmp(argv[1], "-cs") == 0) {
        line = to_uppercase(line);
    }
    // Filter line based on filter string if provided
    if (strlen(filter_string) > 0) {
        line = filter_line(line, filter_string);
    }
    // Write line to output file if requested
    if (output_file != NULL) {
        write_line(line, output_file);
    } else {
        printf("%s\n", line);
    }
}

// Function to process a file and perform the desired operations
void process_file(char *filename, char *output_file, int line_count) {
    // Open input file
    int fd = open_file(filename);
    // Read lines from input file
    size_t length;
    char *line = read_line(fd, &length);
    while (line != NULL && line_count > 0) {
        process_line(line, output_file, line_count);
        line_count--;
        free(line);
        line = read_line(fd, &length);
    }
    // Close input file
    close_file(fd);
}

// Function to handle errors that may occur during processing
void error_handler(char *message) {
    perror(message);
    exit(1);
}

// Main function to run the program
int main(int argc, char **argv) {
    // Parse command line arguments and provide usage information if no input file is provided
    parse_args(argc, argv);
    // Initialize variables for processing
    int line_count = 0;
    char *output_file = NULL;
    char *filter_string = "";
    // Check if any options are specified and handle them accordingly
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-l") == 0) {
            line_count = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0) {
            output_file = argv[++i];
        } else if (strcmp(argv[i], "-f") == 0) {
            filter_string = argv[++i];
        }
    }
    // Process input file and perform desired operations
    process_file(argv[argc - 1], output_file, line_count);
    return 0;
}
