// Define a hash function for the RX_UE_INFORMATION_TAG and RNTI
unsigned int hash(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
    // Implement a simple hash function using the RX_UE_INFORMATION_TAG and RNTI
    return (rx_ue_information.cell_id + rnti.rnti) % 10000;
