// Initialize the list with a capacity of 10,000 structures
void init_thread_safe_list(thread_safe_list_t *list) {
    list->size = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10000);
}

// Add a new structure to the list, ensuring thread-safety and memory management
void add_to_thread_safe_list(thread_safe_list_t *list, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
