// Define the function to add a new entry to the log
void add_log_entry(ModemLogEntry* entry) {
    // Acquire the lock for accessing the log
    pthread_mutex_lock(&log_lock);

    // Check if the log is full and needs to be archived
    if (log_size >= MAX_LOG_SIZE) {
        archive_old_entries();
    }

    // Add the new entry to the log
    log[log_size++] = *entry;

    // Release the lock for accessing the log
    pthread_mutex_unlock(&log_lock);
}

// Define the function to retrieve entries from the log by timestamp
ModemLogEntry* get_log_entries(time_t start_timestamp, time_t end_timestamp) {
    // Acquire the lock for accessing the log
    pthread_mutex_lock(&log_lock);

    // Find the first and last indices of the entries in the specified range
    int first_index = -1;
    int last_index = -1;
    for (int i = 0; i < log_size; i++) {
        if (log[i].timestamp >= start_timestamp && log[i].timestamp <= end_timestamp) {
            if (first_index == -1) {
                first_index = i;
            }
            last_index = i;
        }
    }

    // Create a new array to hold the retrieved entries
    ModemLogEntry* retrieved_entries = malloc(sizeof(ModemLogEntry) * (last_index - first_index + 1));

    // Copy the retrieved entries from the log into the new array
    for (int i = first_index; i <= last_index; i++) {
        retrieved_entries[i - first_index] = log[i];
    }

    // Release the lock for accessing the log
    pthread_mutex_unlock(&log_lock);

    return retrieved_entries;
}

// Define the function to clear the entire log
void clear_log() {
    // Acquire the lock for accessing the log
    pthread_mutex_lock(&log_lock);

    // Clear the log by setting its size to 0
    log_size = 0;

    // Release the lock for accessing the log
    pthread_mutex_unlock(&log_lock);
}

// Define the function to archive old entries in the log
void archive_old_entries() {
    // Acquire the lock for accessing the log
    pthread_mutex_lock(&log_lock);

    // Find the oldest entry in the log and its index
    int oldest_index = -1;
    time_t oldest_timestamp = 0;
    for (int i = 0; i < log_size; i++) {
        if (log[i].timestamp < oldest_timestamp || oldest_index == -1) {
            oldest_index = i;
            oldest_timestamp = log[i].timestamp;
        }
    }

    // If the oldest entry is older than the retention policy, archive it
    if (oldest_timestamp < time(NULL) - RETENTION_POLICY_AGE || oldest_index == -1) {
        log[oldest_index] = NULL;
        log_size--;
    }

