    // Iterate through the log entries and write them to the file
    for (size_t i = 0; i < log->count; i++) {
        fprintf(file, "%lu %d %s\n", log->entries[i].timestamp, log->entries[i].level, log->entries[i].message);
    }

    // Close the file
    fclose(file);
}

// Function to purge the oldest entries in the log
void purge_oldest_entries(LogArray *log) {
    // Check if the log is empty
    if (log->count == 0) {
        return;
    }

    // Find the oldest entry and remove it from the log
    size_t oldest_index = 0;
    time_t oldest_timestamp = log->entries[oldest_index].timestamp;
    for (size_t i = 1; i < log->count; i++) {
        if (log->entries[i].timestamp < oldest_timestamp) {
            oldest_index = i;
            oldest_timestamp = log->entries[i].timestamp;
        }
    }
    pthread_mutex_lock(&log->mutex);
    log->count--;
    memmove(log->entries + oldest_index, log->entries + oldest_index + 1, (log->count - oldest_index) * sizeof(ModemLogEntry));
    pthread_mutex_unlock(&log->mutex);
}

// Function to filter the log entries by level
void filter_by_level(LogArray *log, int level) {
    // Iterate through the log entries and remove any that do not match the specified level
    for (size_t i = 0; i < log->count; i++) {
        if (log->entries[i].level != level) {
            pthread_mutex_lock(&log->mutex);
            memmove(log->entries + i, log->entries + i + 1, (log->count - i) * sizeof(ModemLogEntry));
            log->count--;
            pthread_mutex_unlock(&log->mutex);
        }
    }
}
