        scanf("%d %d", &new_point.x, &new_point.y);
        if (new_point.x == -1 && new_point.y == -1) {
            break;
        }
        points[num_coords] = new_point;
        num_coords++;
    }

    // Identify and print the farthest point from the origin (0, 0)
    int max_dist = 0;
    Point *farthest_point = NULL;
    for (int i = 0; i < num_points; i++) {
        if (points[i].x * points[i].x + points[i].y * points[i].y > max_dist) {
            farthest_point = &points[i];
            max_dist = points[i].x * points[i].x + points[i].y * points[i].y;
        }
    }
    printf("Farthest point from the origin: (%d, %d)\n", farthest_point->x, farthest_point->y);

    // Calculate the average distance of all points from the origin and print it
    double avg_dist = 0;
    for (int i = 0; i < num_points; i++) {
        avg_dist += sqrt(points[i].x * points[i].x + points[i].y * points[i].y);
    }
    avg_dist /= num_points;
    printf("Average distance of all points from the origin: %f\n", avg_dist);

    // Free the allocated memory
    free(rssi);
    free(data);
    free(points);
}
