Here's an example implementation of a high-performance logging framework in C that supports multiple logging levels, including DEBUG, INFO, WARNING, ERROR, and FATAL, alongside a NO_LOG mode for testing purposes:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Logging levels
#define LOG_DEBUG 0
#define LOG_INFO 1
#define LOG_WARNING 2
#define LOG_ERROR 3
#define LOG_FATAL 4
#define LOG_NO_LOG 5

// Log message structure
typedef struct {
    int level;
    char *message;
} log_msg_t;

// Logging module structure
typedef struct {
    pthread_mutex_t mutex;
    FILE *file;
    int level;
} logging_module_t;

// Initialize the logging module
void init_logging(logging_module_t *module) {
    // Set the default logging level to INFO
    module->level = LOG_INFO;

    // Open the log file for writing
    module->file = fopen("log.txt", "w");
    if (module->file == NULL) {
        perror("fopen");
        exit(1);
    }
}

// Log a message with the specified level
void log_message(logging_module_t *module, int level, char *message) {
    // Check if the logging level is enabled
    if (level <= module->level) {
        // Lock the mutex to prevent concurrent access
        pthread_mutex_lock(&module->mutex);

        // Write the log message to the file
        fprintf(module->file, "%s: %s\n", get_log_level_string(level), message);

        // Unlock the mutex
        pthread_mutex_unlock(&module->mutex);
    }
}

// Get a string representation of the logging level
char *get_log_level_string(int level) {
    switch (level) {
        case LOG_DEBUG: return "DEBUG";
        case LOG_INFO: return "INFO";
        case LOG_WARNING: return "WARNING";
        case LOG_ERROR: return "ERROR";
        case LOG_FATAL: return "FATAL";
        default: return "NO_LOG";
    }
}

// Set the logging level for the module
void set_logging_level(logging_module_t *module, int level) {
    // Check if the logging level is valid
    if (level < LOG_DEBUG || level > LOG_FATAL) {
