    LOG_ERROR_NONE = 0, // no error occurred
    LOG_ERROR_INVALID_LEVEL = -1, // invalid log level specified
    LOG_ERROR_MEMORY_ALLOCATION = -2, // failed to allocate memory for the log message
};

void debug_log(int level, const char* message) {
    if (level < 0 || level > CRITICAL) {
        return LOG_ERROR_INVALID_LEVEL;
    }
    struct DebugLog* message = alloc_log_message();
    if (message == NULL) {
        return LOG_ERROR_MEMORY_ALLOCATION;
