// Define the function to purge old entries from the log
void purge_old_entries(Log* log) {
    // Iterate through the log entries and find the oldest entry
    int oldest_index = -1;
    time_t oldest_timestamp = 0;
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i]->timestamp < oldest_timestamp || oldest_index == -1) {
            oldest_index = i;
            oldest_timestamp = log->entries[i]->timestamp;
        }
    }

    // Purge the oldest entry from the log
    free(log->entries[oldest_index]);
    for (int i = oldest_index; i < log->size - 1; i++) {
        log->entries[i] = log->entries[i + 1];
    }
    log->size--;
}

// Define the function to filter logs based on a specified log level
void filter_logs(Log* log, int level) {
    // Iterate through the log entries and filter out entries with lower levels
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i]->level < level) {
            free(log->entries[i]);
            for (int j = i; j < log->size - 1; j++) {
                log->entries[j] = log->entries[j + 1];
            }
            log->size--;
        }
    }
