    } else if (strcmp(mode, "CFB") == 0 && strcmp(algorithm, "DES") == 0) {
        return EVP_des_cfb();
    } else {
        // Invalid mode or algorithm specified
        return NULL;
    }
}

int encrypt_decrypt(const unsigned char* input, size_t input_len, const unsigned char* key, size_t key_len, const unsigned char* iv, size_t iv_len, EVP_CIPHER* cipher, int enc) {
    // Initialize the OpenSSL library
    OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_ADD_ALL_DIGESTS, NULL);

    // Check if the input and key are valid
    if (input == NULL || key == NULL) {
        return -1;
    }

    // Create an EVP context for the encryption/decryption process
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -2;
    }

    // Set the cipher and key length
    int ret = EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -3;
    }

    // Allocate memory for the output buffer
    unsigned char* output = OPENSSL_malloc(input_len + EVP_CIPHER_CTX_block_size(ctx));
    if (output == NULL) {
        EVP_CIPHER_CTX_free(ctx);
        return -4;
    }

    // Encrypt/decrypt the input data
    int len = 0;
    ret = EVP_EncryptUpdate(ctx, output + len, &len, input, input_len);
    if (ret != 1) {
        OPENSSL_free(output);
        EVP_CIPHER_CTX_free(ctx);
        return -5;
    }

    // Set the IV for decryption
    if (!enc) {
        ret = EVP_CipherInit_ex(ctx, NULL, NULL, key, iv, enc ? 1 : 0);
        if (ret != 1) {
            OPENSSL_free(output);
            EVP_CIPHER_CTX_free(ctx);
            return -6;
        }
    }

    // Encrypt/decrypt the input data
    int outlen = 0;
    ret = EVP_EncryptFinal_ex(ctx, output + len, &outlen);
    if (ret != 1) {
        OPENSSL_free(output);
        EVP_CIPHER_CTX_free(ctx);
        return -7;
    }

    // Free the OpenSSL context and return the output buffer
    EVP_CIPHER_CTX_free(ctx);
    return outlen;
}
```
This function takes in a mode (ECB, EDE, EDE3, or CFB), an algorithm (DES), and a key as input. It returns a pointer to an `EVP_CIPHER` structure representing the chosen cipher. The function also takes in an input buffer, an input length, a key buffer, a key length, an IV buffer, and an IV length as input.

The function first initializes the OpenSSL library using `OPENSSL_init_crypto`. It then checks if the input and key are valid before proceeding with the encryption/decryption process.

For ECB mode, it uses `EVP_des_ecb` to create an EVP context for the encryption/decryption process. For other modes, it uses `EVP_des_ede`, `EVP_des_ede3`, and `EVP_des_cfb` respectively.

The function then allocates memory for the output buffer using `OPENSSL_malloc`. It sets the cipher and key length using `EVP_EncryptInit_ex` and `EVP_CipherInit_ex`. If the mode is CFB, it also sets the IV for decryption using `EVP_CipherInit_ex`.

The function then encrypts/decrypts the input data using `EVP_EncryptUpdate` and `EVP_EncryptFinal_ex`. It frees the output buffer and the OpenSSL context using `OPENSSL_free` and `EVP_CIPHER_CTX_free` respectively.

The function returns the length of the encrypted/decrypted data.']

