class SensorReadingManager {
private:
    // Define a struct to store sensor readings
    struct SensorReading {
        int timestamp;
        int sensorID;
        float temperature;
        float humidity;
    };

    // Define a vector to store the sensor readings
    std::vector<SensorReading> readings;

    // Define a mutex for thread safety
    std::mutex mtx;

public:
    // Add a new reading to the list
    void addReading(int timestamp, int sensorID, float temperature, float humidity) {
        SensorReading reading = {timestamp, sensorID, temperature, humidity};
        std::lock_guard<std::mutex> lock(mtx);
        readings.push_back(reading);
    }

    // Retrieve a reading by timestamp or sensor ID
    SensorReading getReading(int timestamp, int sensorID) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& reading : readings) {
            if (reading.timestamp == timestamp && reading.sensorID == sensorID) {
                return reading;
            }
        }
        // Return an empty reading if no match is found
        SensorReading emptyReading = {-1, -1, NAN, NAN};
        return emptyReading;
    }

    // Clear the entire data set
    void clear() {
        std::lock_guard<std::mutex> lock(mtx);
        readings.clear();
    }

    // Limit the number of readings in the dataset to a specified maximum size
    void limitReadingCount(int maxSize) {
        std::lock_guard<std::mutex> lock(mtx);
        if (readings.size() > maxSize) {
            readings.erase(readings.begin(), readings.end() - maxSize);
        }
    }

    // Filter readings based on a specified temperature range or humidity threshold
    std::vector<SensorReading> filterReadings(float minTemperature, float maxTemperature, float minHumidity, float maxHumidity) {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<SensorReading> filteredReadings;
        for (auto& reading : readings) {
            if (reading.temperature >= minTemperature && reading.temperature <= maxTemperature && reading.humidity >= minHumidity && reading.humidity <= maxHumidity) {
