    void purgeOldReadings(int duration) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = readings.begin();
        while (it != readings.end()) {
            if ((*it).timestamp < duration) {
                it = readings.erase(it);
            } else {
                ++it;
            }
        }
    }

