    void compactData() {
        std::lock_guard<std::mutex> lock(mtx);
        readings.shrink_to_fit();
    }

    // Export the readings to a file in a standardized format for external analysis tools
    void exportReadings(const char* filename) {
        std::lock_guard<std::mutex> lock(mtx);
        std::ofstream ofs(filename, std::ios::out | std::ios::binary);
        if (!ofs.is_open()) {
