        std::lock_guard<std::mutex> lock(mutex_);
        auto it = readings_.begin();
        while (it != readings_.end()) {
            if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - it->timestamp).count() > purgeInterval_) {
                it = readings_.erase(it);
            } else {
                ++it;
            }
        }
