            if (startTimestamp <= it->timestamp && endTimestamp >= it->timestamp) {
                totalTemperature += it->temperature;
                totalHumidity += it->humidity;
                count++;
            }
        }
        return std::make_pair(totalTemperature / count, totalHumidity / count);
    }

private:
