```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Log levels
#define DEBUG 0
#define INFO 1
#define WARNING 2
#define ERROR 3
#define CRITICAL 4

// Log message structure
typedef struct {
    int level; // Log level (DEBUG, INFO, WARNING, ERROR, or CRITICAL)
    char *message; // Log message string
} log_msg_t;

// Log file structure
typedef struct {
    FILE *file; // File handle for the log file
    pthread_mutex_t lock; // Mutex to protect concurrent access to the log file
} log_file_t;

// Logging function prototype
void log(int level, const char *message);

// Initialize logging framework
void init_logging() {
    // Create a new log file and initialize its mutex
    log_file_t *log_file = malloc(sizeof(log_file_t));
    log_file->file = fopen("log.txt", "w");
    pthread_mutex_init(&log_file->lock, NULL);
}

// Deinitialize logging framework
void deinit_logging() {
    // Close the log file and destroy its mutex
    log_file_t *log_file = malloc(sizeof(log_file_t));
    fclose(log_file->file);
    pthread_mutex_destroy(&log_file->lock);
}

// Log a message with the specified level
void log(int level, const char *message) {
    // Check if the log level is valid
    if (level < DEBUG || level > CRITICAL) {
        return;
    }

    // Acquire the mutex for the log file
    pthread_mutex_lock(&log_file->lock);

    // Write the log message to the log file
    fprintf(log_file->file, "%s\n", message);

    // Release the mutex for the log file
    pthread_mutex_unlock(&log_file->lock);
}
```
