class SensorReadingManager {
public:
    // Constructor
    SensorReadingManager(int maxSize = 1000) : maxSize_(maxSize) {}

    // Adds a new reading to the list
    void addReading(const SensorReading& reading) {
        if (readings_.size() >= maxSize_) {
            purgeOldestReading();
        }
        readings_.push_back(reading);
    }

    // Retrieves a reading by timestamp or sensor ID
    const SensorReading* getReading(const std::string& timestampOrSensorId) const {
        for (auto it = readings_.begin(); it != readings_.end(); ++it) {
            if ((*it).timestamp == timestampOrSensorId || (*it).sensorId == timestampOrSensorId) {
                return &(*it);
            }
        }
        return nullptr;
    }

    // Clears the entire data set
    void clear() {
        readings_.clear();
    }

private:
    // Purge the oldest reading in the list
    void purgeOldestReading() {
        if (!readings_.empty()) {
            readings_.pop_front();
        }
    }

    // The maximum size of the data set
    int maxSize_;

    // The list of sensor readings
    std::list<SensorReading> readings_;
};
