```c++
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <thread>
#include <mutex>
#include <condition_variable>

class SensorDataManager {
public:
    // Constructor
    SensorDataManager(int maxSize = 1000) : maxSize_(maxSize), records_(std::vector<SensorReading>(maxSize)) {}

    // Add a new reading to the dataset
    void addReading(const std::string& sensorId, double temperature, double humidity) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (records_.size() >= maxSize_) {
            purgeOldestRecord();
        }
        records_.push_back(SensorReading(sensorId, temperature, humidity));
    }

    // Retrieve a reading by timestamp or sensor ID
    SensorReading getReading(const std::string& timestampOrSensorId) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = records_.begin(); it != records_.end(); ++it) {
            if (it->timestamp == timestampOrSensorId || it->sensorId == timestampOrSensorId) {
                return *it;
            }
        }
        return SensorReading(); // Return an empty reading if not found
    }

    // Clear the entire dataset
    void clear() {
        std::lock_guard<std::mutex> lock(mutex_);
        records_.clear();
    }

private:
    // Purge the oldest record in the dataset
    void purgeOldestRecord() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (records_.size() > 0) {
            records_.erase(records_.begin());
        }
    }

    // Maximum size of the dataset
    int maxSize_;

    // Vector of sensor readings
    std::vector<SensorReading> records_;

    // Mutex for thread-safe access to the dataset
    std::mutex mutex_;
};
```
