// Define a synchronization mechanism for accessing the trace log
pthread_mutex_t trace_log_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new trace entry to the log
void add_trace(TraceLog* log, NetworkTrace* trace) {
    // Acquire the lock for accessing the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Check if the log is full and needs to be archived
    if (log->num_traces >= log->max_size) {
        // Archive the oldest traces first
        archive_traces(log, log->num_traces - log->max_size + 1);
    }

    // Add the new trace to the end of the log
    log->traces[log->num_traces++] = trace;

    // Release the lock for accessing the trace log
    pthread_mutex_unlock(&trace_log_lock);
}

// Function to retrieve traces from the log by timestamp or IP address
