    // Acquire the lock for accessing the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Iterate over the traces in the log and find the ones that match the given timestamp or IP address
    NetworkTrace* traces = NULL;
    size_t num_traces = 0;
    for (size_t i = 0; i < log->num_traces; i++) {
        if ((timestamp != -1 && log->traces[i]->timestamp == timestamp) ||
            (ip_address != NULL && strcmp(log->traces[i]->source_ip, ip_address) == 0)) {
            traces = realloc(traces, (num_traces + 1) * sizeof(NetworkTrace));
            traces[num_traces++] = log->traces[i];
        }
    }

    // Release the lock for accessing the trace log
    pthread_mutex_unlock(&trace_log_lock);

    return traces;
}

// Function to clear the entire trace log
void clear_traces(TraceLog* log) {
    // Acquire the lock for accessing the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Free all the traces in the log
    free(log->traces);
    log->num_traces = 0;

    // Release the lock for accessing the trace log
    pthread_mutex_unlock(&trace_log_lock);
}

// Function to archive old traces when the log reaches its maximum size
void archive_traces(TraceLog* log, size_t num_traces) {
    // Acquire the lock for accessing the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Iterate over the oldest traces in the log and move them to a separate archive
    for (size_t i = 0; i < num_traces; i++) {
        NetworkTrace* trace = log->traces[i];
        free(trace->payload);
        free(trace->source_ip);
        free(trace->destination_ip);
        free(trace);
    }

    // Shift the remaining traces in the log to fill the gap left by the archived traces
    for (size_t i = num_traces; i < log->num_traces - 1; i++) {
        log->traces[i] = log->traces[i + 1];
    }

    // Decrement the number of traces in the log by the number archived
    log->num_traces -= num_traces;

    // Release the lock for accessing the trace log
    pthread_mutex_unlock(&trace_log_lock);
