    }

    // Release the lock for accessing the trace log
    pthread_mutex_unlock(&trace_log_lock);
}

// Function to implement a mechanism for compressing archived traces to reduce storage requirements
void compress_traces(TraceLog* log) {
    // Acquire the lock for accessing the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Iterate over the archived traces and compress them using a lossless compression algorithm
    for (size_t i = 0; i < log->num_traces; i++) {
        NetworkTrace* trace = log->traces[i];
        // Compress the payload of the trace using a lossless compression algorithm
        size_t compressed_payload_size = compress(trace->payload, strlen(trace->payload));
        if (compressed_payload_size > 0) {
            // Update the compressed payload size in the trace
            trace->compressed_payload_size = compressed_payload_size;
        }
    }

    // Release the lock for accessing the trace log
    pthread_mutex_unlock(&trace_log_lock);
}
