#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>

// Define a struct to represent a single TCP connection record
typedef struct {
    int socket; // The socket descriptor for the connection
    char *ip_address; // The remote IP address of the connection
    int port; // The remote port number of the connection
} tcp_connection_t;

// Define a dynamic array to store the TCP connection records
tcp_connection_t *connections = NULL;
int num_connections = 0;

// Function to initialize the dynamic array and populate it with up to N records
void init_connections(int n) {
    // Allocate memory for the dynamic array
    connections = (tcp_connection_t *)malloc(n * sizeof(tcp_connection_t));
    if (!connections) {
        fprintf(stderr, "Error: failed to allocate memory for connections\n");
        exit(1);
    }

    // Initialize the dynamic array with NULL values
    for (int i = 0; i < n; i++) {
        connections[i].socket = -1;
        connections[i].ip_address = NULL;
        connections[i].port = -1;
    }
}

// Function to add a new TCP connection record to the dynamic array
void add_connection(int socket, char *ip_address, int port) {
    // Check if there is enough space in the dynamic array for another record
    if (num_connections >= n) {
        fprintf(stderr, "Error: no more space in connections array\n");
        exit(1);
    }

    // Find an empty slot in the dynamic array and add the new connection record
    int i;
    for (i = 0; i < n; i++) {
        if (connections[i].socket == -1) {
            break;
        }
    }
    connections[i].socket = socket;
    connections[i].ip_address = ip_address;
    connections[i].port = port;
    num_connections++;
}

// Function to remove a specific TCP connection record from the dynamic array
void remove_connection(int socket) {
    // Find the index of the connection record with the given socket descriptor
    int i;
    for (i = 0; i < n; i++) {
        if (connections[i].socket == socket) {
            break;
        }
    }
    if (i >= n) {
        fprintf(stderr, "Error: connection not found\n");
        exit(1);
    }

    // Remove the connection record from the dynamic array
    connections[i].socket = -1;
    connections[i].ip_address = NULL;
    connections[i].port = -1;
    num_connections--;
}

// Function to check for an existing connection before adding a new one
int exists_connection(char *ip_address, int port) {
    // Iterate over the dynamic array and check if there is already a connection with the given IP address and port number
    for (int i = 0; i < n; i++) {
        if (connections[i].socket != -1 && strcmp(connections[i].ip_address, ip_address) == 0 && connections[i].port == port) {
            return 1;
        }
    }
    return 0;
}

// Function to list all active connections in a human-readable format
void list_connections() {
    // Iterate over the dynamic array and print each connection record
    for (int i = 0; i < n; i++) {
        if (connections[i].socket != -1) {
            printf("Connection %d: socket=%d, ip_address=%s, port=%d\n", i + 1, connections[i].socket, connections[i].ip_address, connections[i].port);
        }
    }
}
```
