        // Lock the mutex to prevent concurrent access to the vector
        std::lock_guard<std::mutex> lock(mutex_);

        // Find the oldest reading and remove it from the vector
        auto oldestReading = readings_.begin();
        for (auto it = readings_.begin(); it != readings_.end(); ++it) {
