        switch (c) {
            case 'm':
                is_manpage = true;
                break;
            case 'c':
                is_cs = true;
                break;
            case 'o':
                is_o = true;
                output_file = optarg;
                break;
            default:
                print_usage();
        }
    }
    if (optind < argc) {
        input_file = argv[optind];
    } else {
        print_usage();
    }
}

void read_file(const char *filename) {
    int fd;
    struct stat sb;
    char buffer[MAX_LINE_LENGTH];
    ssize_t num_read;

    // Open input file
    if ((fd = open(filename, O_RDONLY)) == -1) {
        log_error("Failed to open input file");
        return;
    }

    // Get file size
    if (fstat(fd, &sb) == -1) {
        log_error("Failed to get file size");
        close(fd);
        return;
    }

    // Check file size
    if (sb.st_size > MAX_FILE_SIZE) {
        log_error("File is too large");
        close(fd);
        return;
    }

    // Read file line by line
    while ((num_read = read(fd, buffer, MAX_LINE_LENGTH)) > 0) {
        num_lines++;
    }

    // Close input file
    close(fd);
}

void print_usage() {
    printf("Usage: %s [-m] [-c] [-o output_file] input_file\n", argv[0]);
    exit(1);
}

void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    printf("[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, message);
}

void log_info(const char *message) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    printf("[%d-%02d-%02d %02d:%02d:%02d] INFO: %s\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, message);
}

void cleanup() {
    // Release resources
    if (input_file) {
        free(input_file);
    }
    if (output_file) {
        free(output_file);
    }
}

void handle_signal(int signal) {
    log_info("Received signal");
    cleanup();
    exit(0);
}

void* thread_func(void *arg) {
    // Read input file concurrently using threads
    int fd;
    struct stat sb;
    char buffer[MAX_LINE_LENGTH];
    ssize_t num_read;

    if ((fd = open((char *)arg, O_RDONLY)) == -1) {
        log_error("Failed to open input file");
        return NULL;
    }

    // Get file size
    if (fstat(fd, &sb) == -1) {
        log_error("Failed to get file size");
        close(fd);
        return NULL;
    }

    // Check file size
    if (sb.st_size > MAX_FILE_SIZE) {
        log_error("File is too large");
        close(fd);
        return NULL;
    }

    // Read file line by line
    while ((num_read = read(fd, buffer, MAX_LINE_LENGTH)) > 0) {
        num_lines++;
    }

    // Close input file
    close(fd);

    return NULL;
}
