#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define a structure to represent a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define a linked list node to store the log entries
typedef struct Node {
    ModemLogEntry entry;
    struct Node* next;
} Node;

// Define a global variable to keep track of the head and tail nodes of the linked list
Node* head = NULL;
Node* tail = NULL;

// Define a lock for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new log entry to the linked list
void addLogEntry(ModemLogEntry entry) {
    // Acquire the lock before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node for the log entry
    Node* newNode = malloc(sizeof(Node));
    newNode->entry = entry;
    newNode->next = NULL;

    // If the linked list is empty, set the head and tail to the new node
    if (head == NULL) {
        head = newNode;
        tail = newNode;
    } else {
        // Otherwise, add the new node to the end of the linked list
        tail->next = newNode;
        tail = newNode;
    }

    // Release the lock after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a log entry from the linked list by timestamp
ModemLogEntry* getLogEntry(time_t timestamp) {
    // Acquire the lock before accessing the linked list
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list until we find the node with the specified timestamp
    Node* current = head;
    while (current != NULL && current->entry.timestamp != timestamp) {
        current = current->next;
    }

    // If we found a matching node, return its log entry
    if (current != NULL) {
        ModemLogEntry* result = malloc(sizeof(ModemLogEntry));
        *result = current->entry;
        pthread_mutex_unlock(&mutex);
        return result;
    } else {
        // Otherwise, return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}

// Function to clear the entire log by deleting all nodes
void clearLog() {
    // Acquire the lock before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list and delete each node
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    // Reset the head and tail pointers to NULL
    head = NULL;
    tail = NULL;

    // Release the lock after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to limit the number of log entries in the linked list to a specified maximum size
void limitLogSize(int maxSize) {
    // Acquire the lock before modifying the linked list
    pthread_mutex_lock(&mutex);

    // If the current size of the linked list is greater than the maximum size, delete the oldest entries
    while (getLogSize() > maxSize) {
        Node* oldest = head;
        head = head->next;
        free(oldest);
    }

    // Release the lock after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to filter log entries based on a specified log level
void filterLogLevel(int level) {
    // Acquire the lock before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list and delete any nodes with a lower log level than the specified level
    Node* current = head;
    while (current != NULL) {
        if (current->entry.level < level) {
            Node* next = current->next;
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }

    // Release the lock after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve the size of the log in terms of the number of nodes
int getLogSize() {
    int size = 0;

    // Acquire the lock before accessing the linked list
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list and count the number of nodes
    Node* current = head;
    while (current != NULL) {
        size++;
        current = current->next;
    }

    // Release the lock after accessing the linked list
    pthread_mutex_unlock(&mutex);

    return size;
}

// Function to export the log entries to a file in a standardized format
void exportLog(FILE* file) {
    // Acquire the lock before accessing the linked list
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list and write each entry to the file
    Node* current = head;
    while (current != NULL) {
        fprintf(file, "%d %d %s\n", current->entry.timestamp, current->entry.level, current->entry.message);
        current = current->next;
    }

    // Release the lock after accessing the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to asynchronously notify external logging services or databases of new log entries
void notifyExternalLogging(ModemLogEntry entry) {
    // Acquire the lock before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node for the log entry and add it to the end of the linked list
    Node* newNode = malloc(sizeof(Node));
    newNode->entry = entry;
    newNode->next = NULL;
    if (tail == NULL) {
        head = newNode;
        tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }

    // Release the lock after modifying the linked list
    pthread_mutex_unlock(&mutex);
}
