            if (log_array.entries[i].timestamp < purge_duration) {
                // Remove the purged entry from the log array
                log_array.entries[i] = log_array.entries[--log_array.num_entries];
            } else {
                break;
            }
        }
    }
}

// Define the function to compact the log structure
void compact_log() {
    // Check if there are any unused slots in the log array
    for (int i = 0; i < log_array.num_entries; i++) {
        if (log_array.entries[i].message == NULL) {
            // Remove the unused slot from the log array
            log_array.entries[i] = log_array.entries[--log_array.num_entries];
        }
    }
}

// Define the function to export the log entries to a file in a standardized format
void export_log(FILE* file) {
    // Iterate through the log entries and write them to the file
    for (int i = 0; i < log_array.num_entries; i++) {
        fprintf(file, "%s\n", log_array.entries[i].message);
    }
}

// Define the function to handle edge cases such as invalid input sizes and maintain thread safety if used in a multi-threaded environment
void handle_edge_cases() {
    // Check if the input size is valid
    if (log_array.num_entries > MAX_LOG_SIZE) {
        // Handle the invalid input size
    }

    // Check if the log array is accessed from multiple threads simultaneously
