    time_t now = time(NULL);

    // Iterate over the log array and remove any entries that are older than the maximum age
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i].timestamp + MAX_LOG_AGE <= now) {
            log->entries[i] = log->entries[--log->size];
        }
    }
}

// Define a function to compact the log structure periodically
void compactLog(LogArray* log) {
    // If the current size of the log is less than half of its capacity, do nothing
    if (log->size < log->capacity / 2) {
        return;
    }

    // Create a new log array with twice the capacity of the original one
    LogArray* newLog = malloc(sizeof(LogArray));
    newLog->size = 0;
    newLog->capacity = log->capacity * 2;
    newLog->entries = malloc(newLog->capacity * sizeof(LogEntry));

    // Iterate over the original log array and copy all entries to the new log array
    for (int i = 0; i < log->size; i++) {
        LogEntry* entry = &log->entries[i];
        LogEntry* newEntry = &newLog->entries[newLog->size++];
        newEntry->timestamp = entry->timestamp;
        newEntry->level = entry->level;
        strncpy(newEntry->message, entry->message, MAX_LOG_MESSAGE_SIZE);
    }

    // Free the original log array and replace it with the new one
    free(log->entries);
    *log = *newLog;
}

// Define a function to export the log entries to a file in a standardized format
void exportLogEntriesToFile(LogArray* log, const char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        return;
    }

    // Iterate over the log array and write each entry to the output file
    for (int i = 0; i < log->size; i++) {
        LogEntry* entry = &log->entries[i];
        fprintf(fp, "%ld %d %s\n", entry->timestamp, entry->level, entry->message);
    }

    // Close the output file
    fclose(fp);
}

// Define a function to handle edge cases such as invalid input sizes and maintain thread safety if used in a multi-threaded environment
void handleEdgeCasesAndMaintainThreadSafety(LogArray* log) {
    // Check if the input size is valid
    if (log->size < 0 || log->size > log->capacity) {
        return;
    }

    // Maintain thread safety by using a mutex to protect the log array
    pthread_mutex_lock(&log->mutex);

    // Handle edge cases such as invalid input sizes and maintain thread safety if used in a multi-threaded environment
    if (log->size < 0 || log->size > log->capacity) {
        return;
    }

    // Unlock the mutex to allow other threads to access the log array
    pthread_mutex_unlock(&log->mutex);
}
