    for (int i = 0; i < num_streams; i++) {
        start_streaming(&streams[i]);
    }

    // Wait for signals or exit
    while (is_running) {
        sleep(1);
    }

    // Clean up and exit
    handle_exit();

    return 0;
}

void parse_command_line_arguments(int argc, char **argv) {
    int c;
    while ((c = getopt(argc, argv, "i:o:b:")) != -1) {
        switch (c) {
            case 'i':
                // Parse input stream URLs
                break;
            case 'o':
                // Parse output directories
                break;
            case 'b':
                // Parse maximum bandwidth usage in bits per second for each type of stream
                break;
            default:
                print_usage();
                exit(1);
        }
    }
}

void handle_signal(int signal) {
    if (signal == SIGINT) {
        is_running = false;
    }
}

void handle_error(char *message) {
    perror(message);
    exit(1);
}

void handle_exit() {
    // Clean up streams and buffers
    for (int i = 0; i < num_streams; i++) {
        cleanup_stream(&streams[i]);
        cleanup_buffer(&buffers[i]);
    }

    // Clean up worker threads
    for (int i = 0; i < MAX_STREAMS; i++) {
        cleanup_worker_thread(&worker_threads[i]);
    }
}

void start_streaming(struct stream *stream) {
    // Open the input file and set up the buffer
    int fd = open(stream->url, O_RDONLY);
    if (fd == -1) {
        handle_error("Failed to open input file");
    }
    struct buffer *buffer = &buffers[stream->id];
    buffer->size = 0;

    // Set up the worker thread
    pthread_t thread;
    struct worker_thread *worker_thread = &worker_threads[stream->id];
    worker_thread->thread = thread;
    worker_thread->stream = stream;
    worker_thread->buffer = buffer;

    // Start the worker thread
    if (pthread_create(&thread, NULL, process_stream, worker_thread) != 0) {
        handle_error("Failed to create worker thread");
    }
}

void stop_streaming(struct stream *stream) {
    // Stop the worker thread
    pthread_cancel(worker_threads[stream->id].thread);

    // Clean up the buffer and stream
    cleanup_buffer(&buffers[stream->id]);
    cleanup_stream(stream);
}

void process_stream(struct worker_thread *worker_thread) {
    struct stream *stream = worker_thread->stream;
    struct buffer *buffer = worker_thread->buffer;

    // Read data from the input file and write it to the output directory
    while (is_running && !feof(stream->fd)) {
        char data[BUFFER_SIZE];
        size_t bytes_read = fread(data, 1, BUFFER_SIZE, stream->fd);
        if (bytes_read > 0) {
            // Write the data to the output directory
            write_to_output_directory(stream->id, buffer->data, bytes_read);

            // Update the buffer size and position
            buffer->size += bytes_read;
        } else if (ferror(stream->fd)) {
            handle_error("Failed to read from input file");
        }
    }
}

void cleanup_stream(struct stream *stream) {
    // Close the input file and free the buffer
    close(stream->fd);
    free(stream->buffer);
}

void cleanup_buffer(struct buffer *buffer) {
    // Free the buffer data
    free(buffer->data);
}

void cleanup_worker_thread(struct worker_thread *worker_thread) {
    // Cancel the worker thread and join it
    pthread_cancel(worker_thread->thread);
    pthread_join(worker_thread->thread, NULL);
}

void log_message(char *message, int level) {
    // Log the message to a file
    FILE *log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        handle_error("Failed to open log file");
    }
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(log_file, "[%s] [%d] %s\n", timestamp, level, message);
    fclose(log_file);
}

void print_usage() {
    printf("Usage: streaming-platform -i <input stream URLs> -o <output directories> -b <maximum bandwidth usage in bits per second for each type of stream>\n");
}
