void add_pdu(MAC_PDU** pdu_array, size_t* num_pdus, const MAC_COMMAND command, const MAC_HEADER header, void* payload) {
    // Check if the input is valid
    assert(pdu_array != NULL && num_pdus != NULL);

    // Allocate memory for the new PDU entry
