    // Find the index of the PDU entry to remove
    size_t index = find_pdu_index(pdu_array, num_pdus, rlc_sn);
    if (index == SIZE_MAX) {
        printf("Error: Failed to find PDU entry with RLC SN %d\n", rlc_sn);
        return;
    }

    // Remove the PDU entry from the array
    *num_pdus -= 1;
    for (size_t i = index; i < *num_pdus; i++) {
        pdu_array[i] = pdu_array[i + 1];
    }
}

// Define a function to find the index of a PDU entry in the array by RLC SN (Radio Link Control Sequence Number)
size_t find_pdu_index(MAC_PDU** pdu_array, size_t num_pdus, const uint16_t rlc_sn) {
    // Check if the input is valid
    assert(pdu_array != NULL && num_pdus > 0);

    // Iterate over the PDU entries in the array
    for (size_t i = 0; i < num_pdus; i++) {
        // Check if the current PDU entry has the specified RLC SN
        if (pdu_array[i]->header.rlc_sn == rlc_sn) {
