void serialize_pdus(MAC_PDU** pdu_array, size_t num_pdus, void* buffer) {
    // Check if the input is valid
    assert(pdu_array != NULL && num_pdus > 0);

    // Calculate the total size of the serialized data
    size_t total_size = sizeof(MAC_PDU*) * num_pdus;
    for (size_t i = 0; i < num_pdus; i++) {
        total_size += sizeof(MAC_COMMAND) + sizeof(MAC_HEADER) + pdu_array[i]->header.payload_length;
