        fprintf(stderr, "Error: invalid memory management\n");
        exit(EXIT_FAILURE);
    }

    // Open the user interface file and read the options
    FILE* ui = fopen("ui.txt", "r");
    if (ui == NULL) {
        fprintf(stderr, "Error: failed to open user interface file\n");
        exit(EXIT_FAILURE);
    }

    // Read the options from the user interface file and handle them accordingly
    char option[10];
    while (fscanf(ui, "%s", option) != EOF) {
        if (strcmp(option, "view") == 0) {
            // View the logs
            handle_logging();
        } else if (strcmp(option, "change") == 0) {
