            // Restart the service
            exit(EXIT_SUCCESS);
        } else {
            fprintf(stderr, "Error: invalid option\n");
            exit(EXIT_FAILURE);
        }
    }

    // Close the user interface file and free the memory for the record array
    fclose(ui);
}

