// Define a structure to represent a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define a linked list data structure to store the log entries
typedef struct LogListNode {
    ModemLogEntry entry;
    struct LogListNode* next;
} LogListNode;

// Define a function to add a new log entry to the list
void add_log_entry(ModemLogEntry* entry) {
    // Create a new node for the entry
    LogListNode* new_node = malloc(sizeof(LogListNode));
    assert(new_node != NULL);

    // Copy the entry data into the new node
    new_node->entry.timestamp = entry->timestamp;
    new_node->entry.level = entry->level;
    new_node->entry.message = strdup(entry->message);

    // Add the new node to the end of the list
    LogListNode* current = log_list;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
}

// Define a function to retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(time_t timestamp) {
    // Iterate through the list until we find an entry with the specified timestamp
    LogListNode* current = log_list;
    while (current != NULL && current->entry.timestamp < timestamp) {
        current = current->next;
    }

    // Return the entry if it was found, or NULL otherwise
    return (current == NULL || current->entry.timestamp > timestamp) ? NULL : &(current->entry);
}

// Define a function to clear the entire log
void clear_log() {
    // Free all nodes in the list
    LogListNode* current = log_list;
    while (current != NULL) {
        free(current->entry.message);
        LogListNode* next = current->next;
        free(current);
        current = next;
    }

    // Reset the list head to NULL
    log_list = NULL;
}

// Define a function to limit the number of entries in the log to a specified maximum size
void limit_log_size(int max_size) {
    // If the current list size is less than or equal to the maximum size, do nothing
    if (get_log_list_size() <= max_size) {
        return;
    }

    // Otherwise, remove the oldest entries until the list size is equal to the maximum size
    LogListNode* current = log_list;
    while (current != NULL && get_log_list_size() > max_size) {
        free(current->entry.message);
        LogListNode* next = current->next;
        free(current);
        current = next;
    }
}

// Define a function to compress the log entries to reduce memory usage when the log reaches a certain size threshold
void compress_log() {
    // If the log is already compressed, do nothing
    if (compression_enabled) {
        return;
    }

    // Otherwise, compress the log by removing all but the most recent entry
    LogListNode* current = log_list;
    while (current != NULL && current->next != NULL) {
        free(current->entry.message);
        LogListNode* next = current->next;
        free(current);
        current = next;
    }
}

// Define a function to decompress the log entries for efficient retrieval
void decompress_log() {
    // If the log is not compressed, do nothing
    if (!compression_enabled) {
        return;
    }

    // Otherwise, decompress the log by adding all but the most recent entry back to the list
    LogListNode* current = log_list;
    while (current != NULL && current->next != NULL) {
        add_log_entry(&(current->entry));
        current = current->next;
    }
}

