#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a log entry
typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the structure for the log manager
typedef struct {
    ModemLogEntry* entries;
    int num_entries;
    bool is_full;
} LogManager;

// Function to add a new entry to the log
void add_entry(LogManager* manager, time_t timestamp, int log_level, char* message) {
    // Check if the log is full
    if (manager->is_full) {
        // If the log is full, remove the oldest entry
        remove_oldest_entry(manager);
    }

    // Add the new entry to the end of the log
    manager->entries[manager->num_entries].timestamp = timestamp;
    manager->entries[manager->num_entries].log_level = log_level;
    manager->entries[manager->num_entries].message = message;
    manager->num_entries++;

    // Check if the log is now full
    if (manager->num_entries == MAX_LOG_SIZE) {
        manager->is_full = true;
    }
}

// Function to retrieve an entry from the log by timestamp
ModemLogEntry* get_entry(LogManager* manager, time_t timestamp) {
    // Iterate through the log entries and find the one with the matching timestamp
    for (int i = 0; i < manager->num_entries; i++) {
        if (manager->entries[i].timestamp == timestamp) {
            return &manager->entries[i];
        }
    }

    // If no entry is found, return NULL
    return NULL;
}

// Function to clear the entire log
void clear_log(LogManager* manager) {
    // Set the number of entries to 0 and mark the log as not full
    manager->num_entries = 0;
    manager->is_full = false;
}

// Function to remove the oldest entry from the log
void remove_oldest_entry(LogManager* manager) {
    // If there are no entries in the log, do nothing
    if (manager->num_entries == 0) {
        return;
    }

    // Remove the oldest entry by shifting all subsequent entries one position to the left
    for (int i = 1; i < manager->num_entries; i++) {
        manager->entries[i - 1] = manager->entries[i];
    }

    // Decrement the number of entries and mark the log as not full
    manager->num_entries--;
    manager->is_full = false;
}

// Function to limit the number of entries in the log to a specified maximum size
void limit_log_size(LogManager* manager, int max_size) {
    // If the current number of entries is less than or equal to the maximum size, do nothing
    if (manager->num_entries <= max_size) {
        return;
    }

    // Remove the oldest entry until the log size is equal to the maximum size
    while (manager->num_entries > max_size) {
        remove_oldest_entry(manager);
    }
}

// Function to flush the log to an external storage system
void flush_log(LogManager* manager, FILE* file) {
    // Iterate through the log entries and write each one to the file
    for (int i = 0; i < manager->num_entries; i++) {
        fprintf(file, "%lu %d %s\n", manager->entries[i].timestamp, manager->entries[i].log_level, manager->entries[i].message);
    }
}

// Function to configure the frequency of automatic log flushes
void set_flush_frequency(LogManager* manager, int frequency) {
    // Set the flush frequency based on the specified value
    if (frequency == 0) {
        manager->flush_frequency = 1;
    } else {
        manager->flush_frequency = frequency;
    }
}

// Function to handle asynchronous log flushes to an external storage system
void async_flush(LogManager* manager, FILE* file) {
    // If the log is not full, do nothing
    if (!manager->is_full) {
        return;
    }

    // Flush the log to the external storage system
    flush_log(manager, file);

    // Clear the log and mark it as not full
    clear_log(manager);
}
