#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>

// Define the log entry structure
typedef struct {
    time_t timestamp;
    int level;
    char message[256];
} ModemLogEntry;

// Define the log array data structure
typedef struct {
    ModemLogEntry* entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LogArray;

// Initialize the log array with a given capacity
void init_log_array(LogArray* log, size_t capacity) {
    log->entries = (ModemLogEntry*)malloc(capacity * sizeof(ModemLogEntry));
    log->capacity = capacity;
    log->count = 0;
    pthread_mutex_init(&log->mutex, NULL);
}

// Add a new entry to the log array
void add_entry(LogArray* log, time_t timestamp, int level, const char* message) {
    // Lock the mutex before modifying the log array
    pthread_mutex_lock(&log->mutex);

    // Check if the log array is full and needs to be resized
    if (log->count == log->capacity) {
        log->entries = (ModemLogEntry*)realloc(log->entries, 2 * log->capacity * sizeof(ModemLogEntry));
        log->capacity *= 2;
    }

    // Add the new entry to the log array
    ModemLogEntry* entry = &log->entries[log->count++];
    entry->timestamp = timestamp;
    entry->level = level;
    strncpy(entry->message, message, 256);

    // Unlock the mutex after modifying the log array
    pthread_mutex_unlock(&log->mutex);
}

// Retrieve an entry from the log array by timestamp
ModemLogEntry* get_entry(LogArray* log, time_t timestamp) {
    // Lock the mutex before accessing the log array
    pthread_mutex_lock(&log->mutex);

    // Search for the entry with the given timestamp in the log array
    for (size_t i = 0; i < log->count; i++) {
        if (log->entries[i].timestamp == timestamp) {
            ModemLogEntry* entry = &log->entries[i];
            pthread_mutex_unlock(&log->mutex);
            return entry;
        }
    }

    // If the entry is not found, return NULL
    pthread_mutex_unlock(&log->mutex);
    return NULL;
}

// Clear the entire log array
void clear_log(LogArray* log) {
    // Lock the mutex before modifying the log array
    pthread_mutex_lock(&log->mutex);

    // Reset the count and capacity of the log array
    log->count = 0;
    log->capacity = 16;

    // Reallocate the memory for the log array to its initial size
    log->entries = (ModemLogEntry*)realloc(log->entries, log->capacity * sizeof(ModemLogEntry));

    // Unlock the mutex after modifying the log array
    pthread_mutex_unlock(&log->mutex);
}

// Export the log entries to a CSV file
void export_log(LogArray* log, const char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: unable to open output file\n");
        return;
    }

    // Lock the mutex before accessing the log array
    pthread_mutex_lock(&log->mutex);

    // Write the header row of the CSV file
    fprintf(fp, "timestamp,level,message\n");

    // Iterate over the log entries and write each one to the CSV file
    for (size_t i = 0; i < log->count; i++) {
        ModemLogEntry* entry = &log->entries[i];
        fprintf(fp, "%lu,%d,%s\n", entry->timestamp, entry->level, entry->message);
    }

    // Unlock the mutex after accessing the log array
    pthread_mutex_unlock(&log->mutex);

    // Close the output file
    fclose(fp);
}
```
