#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

// Custom binary format header for each item in the resource bundle
struct ResourceHeader {
    size_t size; // Size of the item in bytes
    char type; // Type identifier for the item
};

// Structure to hold the entire resource bundle
struct ResourceBundle {
    struct ResourceHeader *headers; // Array of headers for each item
    void **items; // Array of items, where each item is a pointer to its data
    size_t numItems; // Number of items in the bundle
};

// Function to load a resource bundle from a file
int loadResourceBundle(const char *path, struct ResourceBundle *bundle) {
    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        perror("fopen");
        return -1;
    }

    // Read the number of items in the bundle from the file header
    size_t numItems;
    if (fread(&numItems, sizeof(size_t), 1, file) != 1) {
        perror("fread");
        fclose(file);
        return -1;
    }

    // Allocate memory for the bundle structure and its headers array
    struct ResourceHeader *headers = malloc(numItems * sizeof(struct ResourceHeader));
    if (headers == NULL) {
        perror("malloc");
        fclose(file);
        return -1;
    }

    // Allocate memory for the items array and read each item from the file
    void **items = malloc(numItems * sizeof(void*));
    if (items == NULL) {
        perror("malloc");
        free(headers);
        fclose(file);
        return -1;
    }

    // Read each item header and allocate memory for its data
    size_t i;
    for (i = 0; i < numItems; i++) {
        struct ResourceHeader *header = &headers[i];
        if (fread(header, sizeof(struct ResourceHeader), 1, file) != 1) {
            perror("fread");
            free(items);
            free(headers);
            fclose(file);
            return -1;
        }

        items[i] = malloc(header->size);
        if (items[i] == NULL) {
            perror("malloc");
            free(items);
            free(headers);
            fclose(file);
            return -1;
        }

        if (fread(items[i], header->size, 1, file) != 1) {
            perror("fread");
            free(items[i]);
            items[i] = NULL;
            free(items);
            free(headers);
            fclose(file);
            return -1;
        }
    }

    // Close the file and set the output parameters
    fclose(file);
    bundle->headers = headers;
    bundle->items = items;
    bundle->numItems = numItems;

    return 0;
}
```
