            if (strcmp(INVALIDATION_POLICY, "age-based") == 0) {
                // Invalidate the least recently used entry in the cache
                int lru = 0;
                for (int i = 1; i < size; i++) {
                    if (log[i].timestamp < log[lru].timestamp) {
                        lru = i;
                    }
                }
                log[lru] = *entry;
            } else {
                // Invalidate the oldest entry in the cache
                log[0] = *entry;
            }
        }
    }

    // Retrieve an entry from the log array by timestamp
    ModemLogEntry* getEntry(time_t timestamp) {
        for (int i = 0; i < size; i++) {
            if (log[i].timestamp == timestamp) {
                return &log[i];
            }
        }
        return NULL;
    }

    // Clear the entire log array
    void clearLog() {
        for (int i = 0; i < size; i++) {
            free(log[i].message);
        }
        size = 0;
    }
}

// Define the function to handle network failures
void handleNetworkFailures(ModemLogEntry* entry) {
    // Implement a retry mechanism with exponential backoff
    int retries = 3;
    while (retries > 0) {
        if (sendLogEntry(entry)) {
            break;
        } else {
            sleep(pow(2, retries - 1));
            retries--;
        }
    }
}

// Define the function to send a log entry to the external logging service
int sendLogEntry(ModemLogEntry* entry) {
    // Implement a caching mechanism for frequently accessed log entries
    if (cache[entry->timestamp] != NULL) {
        return 1;
    } else {
        cache[entry->timestamp] = malloc(sizeof(ModemLogEntry));
        memcpy(cache[entry->timestamp], entry, sizeof(ModemLogEntry));
        return 0;
    }
}

