// Structure to represent a UE context
typedef struct NRUEContext {
    int UE_ID;
    int RNTI;
    void* NRCellConfig;
} NRUEContext;

// Function to initialize and manage the dynamic array of UE contexts
void initNRUEContexts(int num_contexts) {
    // Allocate memory for the dynamic array of UE contexts
    NRUEContext** ue_contexts = (NRUEContext**)malloc(num_contexts * sizeof(NRUEContext*));
    if (!ue_contexts) {
        printf("Error: Failed to allocate memory for UE contexts\n");
        return;
    }

    // Initialize the dynamic array of UE contexts
    for (int i = 0; i < num_contexts; i++) {
        ue_contexts[i] = NULL;
    }
}

// Function to add a new UE context to the dynamic array
void addNRUEContext(int UE_ID, int RNTI, void* NRCellConfig) {
    // Find the first empty slot in the dynamic array of UE contexts
    for (int i = 0; i < num_contexts; i++) {
        if (!ue_contexts[i]) {
            ue_contexts[i] = malloc(sizeof(NRUEContext));
            if (!ue_contexts[i]) {
                printf("Error: Failed to allocate memory for UE context\n");
                return;
            }
            break;
        }
    }

    // Initialize the new UE context
    ue_contexts[i]->UE_ID = UE_ID;
    ue_contexts[i]->RNTI = RNTI;
    ue_contexts[i]->NRCellConfig = NRCellConfig;
}

// Function to update an existing UE context in the dynamic array
void updateNRUEContext(int UE_ID, int RNTI, void* NRCellConfig) {
    // Find the UE context with the specified UE ID
    for (int i = 0; i < num_contexts; i++) {
        if (ue_contexts[i] && ue_contexts[i]->UE_ID == UE_ID) {
            break;
        }
    }

    // Update the UE context with the new RNTI and NRCellConfig
    ue_contexts[i]->RNTI = RNTI;
    ue_contexts[i]->NRCellConfig = NRCellConfig;
}

// Function to retrieve a specific UE context from the dynamic array by its UE ID
NRUEContext* getNRUEContext(int UE_ID) {
    // Find the UE context with the specified UE ID
    for (int i = 0; i < num_contexts; i++) {
        if (ue_contexts[i] && ue_contexts[i]->UE_ID == UE_ID) {
            return ue_contexts[i];
        }
    }

    // Return NULL if the UE context is not found
    return NULL;
}

// Function to free the memory allocated for the dynamic array of UE contexts
void freeNRUEContexts() {
    // Free the memory allocated for each UE context in the dynamic array
    for (int i = 0; i < num_contexts; i++) {
        if (ue_contexts[i]) {
            free(ue_contexts[i]);
        }
    }

    // Free the memory allocated for the dynamic array of UE contexts
    free(ue_contexts);
}
