// Define the structure for storing user sessions
typedef struct UserSession {
    int sessionID;
    char clientIP[INET_ADDRSTRLEN];
    int serverSocket;
} UserSession;

// Define the hash table for storing user sessions
static UserSession* userSessions = NULL;
static size_t numUserSessions = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize and manage the dynamic hash table
void initUserSessions(size_t initialSize) {
    userSessions = (UserSession*)calloc(initialSize, sizeof(UserSession));
}

void addUserSession(int sessionID, char* clientIP, int serverSocket) {
    pthread_mutex_lock(&mutex);
    UserSession* newSession = (UserSession*)malloc(sizeof(UserSession));
    newSession->sessionID = sessionID;
    strcpy(newSession->clientIP, clientIP);
    newSession->serverSocket = serverSocket;
    userSessions[sessionID] = *newSession;
    numUserSessions++;
    pthread_mutex_unlock(&mutex);
}

void updateUserSession(int sessionID, char* clientIP, int serverSocket) {
    pthread_mutex_lock(&mutex);
    UserSession* existingSession = &userSessions[sessionID];
    strcpy(existingSession->clientIP, clientIP);
    existingSession->serverSocket = serverSocket;
    pthread_mutex_unlock(&mutex);
}

void deleteUserSession(int sessionID) {
    pthread_mutex_lock(&mutex);
    UserSession* deletedSession = &userSessions[sessionID];
    memset(deletedSession, 0, sizeof(UserSession));
    numUserSessions--;
    pthread_mutex_unlock(&mutex);
}

UserSession* getUserSession(int sessionID) {
    pthread_mutex_lock(&mutex);
    UserSession* existingSession = &userSessions[sessionID];
    if (existingSession->sessionID == 0) {
        return NULL;
    } else {
        return existingSession;
    }
}

// Periodically clean up expired sessions based on a specified timeout value
void cleanupExpiredSessions(int timeout) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < numUserSessions; i++) {
        UserSession* session = &userSessions[i];
        if (session->sessionID != 0 && time(NULL) - session->serverSocket > timeout) {
            deleteUserSession(session->sessionID);
        }
    }
    pthread_mutex_unlock(&mutex);
}
```
