// Define the structure for a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the structure for the log array
typedef struct {
    ModemLogEntry* entries[MAX_LOG_SIZE];
    int num_entries;
} LogArray;

// Function to add a new entry to the log array
void add_log_entry(LogArray* log, time_t timestamp, int level, char* message) {
    // Check if the log is full
    if (log->num_entries == MAX_LOG_SIZE) {
        // Purge old entries if necessary
        purge_old_entries(log);
    }

    // Add the new entry to the end of the array
    ModemLogEntry* new_entry = malloc(sizeof(ModemLogEntry));
    new_entry->timestamp = timestamp;
    new_entry->level = level;
    new_entry->message = strdup(message);
    log->entries[log->num_entries++] = new_entry;
}

// Function to retrieve an entry from the log array by timestamp
ModemLogEntry* get_log_entry_by_timestamp(LogArray* log, time_t timestamp) {
    // Iterate through the entries in the log array
    for (int i = 0; i < log->num_entries; i++) {
        ModemLogEntry* entry = log->entries[i];
        if (entry->timestamp == timestamp) {
            return entry;
        }
    }

    // If no matching entry is found, return NULL
    return NULL;
}

// Function to clear the entire log array
void clear_log(LogArray* log) {
    for (int i = 0; i < log->num_entries; i++) {
        free(log->entries[i]);
    }
    log->num_entries = 0;
}

// Function to purge old entries from the log array
void purge_old_entries(LogArray* log) {
    // Determine the maximum age of an entry in the log array
    time_t max_age = get_max_age(log);

    // Iterate through the entries in the log array
    for (int i = 0; i < log->num_entries; i++) {
        ModemLogEntry* entry = log->entries[i];
        if (entry->timestamp <= max_age) {
            free(entry);
            log->num_entries--;
        } else {
            break;
        }
    }
}

// Function to get the maximum age of an entry in the log array
time_t get_max_age(LogArray* log) {
    // Determine the maximum age of an entry in the log array
    time_t max_age = 0;
    for (int i = 0; i < log->num_entries; i++) {
        ModemLogEntry* entry = log->entries[i];
        if (entry->timestamp > max_age) {
            max_age = entry->timestamp;
        }
    }
    return max_age;
}

// Function to filter logs based on a specified log level
void filter_logs(LogArray* log, int level) {
    // Iterate through the entries in the log array
    for (int i = 0; i < log->num_entries; i++) {
        ModemLogEntry* entry = log->entries[i];
        if (entry->level != level) {
            free(entry);
            log->num_entries--;
        } else {
            break;
        }
    }
}

// Function to export the log entries to a file in a standardized format
void export_log_to_file(LogArray* log, char* filename) {
    // Open the output file for writing
    FILE* out = fopen(filename, "w");
    if (out == NULL) {
        printf("Error: unable to open output file\n");
        return;
    }

    // Iterate through the entries in the log array
    for (int i = 0; i < log->num_entries; i++) {
        ModemLogEntry* entry = log->entries[i];
        fprintf(out, "%lu %d %s\n", entry->timestamp, entry->level, entry->message);
    }

    // Close the output file
    fclose(out);
}
