#define MAX_RULES_NUM 100
#define MAX_ENV_VAR_LEN 256
#define MAX_LOG_SIZE (1 << 20) // 1 MB
#define LOG_ROTATE_INTERVAL 30 // seconds
#define LOG_MAX_FILES 10

// Transformation rules
struct rule {
    char *pattern;
    char *replacement;
};

// Input file information
struct input_file {
    int fd;
    off_t size;
    char *filename;
};

// Output file information
struct output_file {
