int main(int argc, char **argv) {
    // Initialize global variables and configuration settings
    init_config(&config, argv);
    parse_command_line(argc, argv);
    validate_config();

    // Initialize input and output queues
    init_input_queue(&in_queue);
    init_output_queue(&out_queue);

    // Initialize logging
    init_log(config.log_filename);

    // Start processing files
    process_files();

    // Cleanup
    cleanup();

    return 0;
}

void init_input_queue(struct input_queue *q) {
    q->mutex = PTHREAD_MUTEX_INITIALIZER;
    q->cond = PTHREAD_COND_INITIALIZER;
    q->files = NULL;
    q->num_files = 0;
    q->head = 0;
    q->tail = 0;
}

void enqueue_input_file(struct input_file *f) {
    pthread_mutex_lock(&in_queue.mutex);
    if (in_queue.num_files == in_queue.head - in_queue.tail - 1) {
        // Queue is full, resize it
        struct input_file *new_files = realloc(in_queue.files, sizeof(struct input_file) * (in_queue.num_files + 1));
        if (!new_files) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        in_queue.files = new_files;
    }
    in_queue.files[in_queue.tail] = *f;
    in_queue.tail = (in_queue.tail + 1) % in_queue.num_files;
    pthread_cond_signal(&in_queue.cond);
    pthread_mutex_unlock(&in_queue.mutex);
}

struct input_file dequeue_input_file() {
    struct input_file f;
    pthread_mutex_lock(&in_queue.mutex);
    while (in_queue.num_files == 0) {
        pthread_cond_wait(&in_queue.cond, &in_queue.mutex);
    }
    f = in_queue.files[in_queue.head];
    in_queue.head = (in_queue.head + 1) % in_queue.num_files;
    pthread_mutex_unlock(&in_queue.mutex);
    return f;
}

void destroy_input_queue(struct input_queue *q) {
    free(q->files);
    q->files = NULL;
    q->num_files = 0;
    q->head = 0;
    q->tail = 0;
}

void init_output_queue(struct output_queue *q) {
    q->mutex = PTHREAD_MUTEX_INITIALIZER;
    q->cond = PTHREAD_COND_INITIALIZER;
    q->files = NULL;
    q->num_files = 0;
    q->head = 0;
    q->tail = 0;
}

void enqueue_output_file(struct output_file *f) {
    pthread_mutex_lock(&out_queue.mutex);
    if (out_queue.num_files == out_queue.head - out_queue.tail - 1) {
        // Queue is full, resize it
        struct output_file *new_files = realloc(out_queue.files, sizeof(struct output_file) * (out_queue.num_files + 1));
        if (!new_files) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        out_queue.files = new_files;
    }
    out_queue.files[out_queue.tail] = *f;
    out_queue.tail = (out_queue.tail + 1) % out_queue.num_files;
    pthread_cond_signal(&out_queue.cond);
    pthread_mutex_unlock(&out_queue.mutex);
}

struct output_file dequeue_output_file() {
    struct output_file f;
    pthread_mutex_lock(&out_queue.mutex);
    while (out_queue.num_files == 0) {
        pthread_cond_wait(&out_queue.cond, &out_queue.mutex);
    }
    f = out_queue.files[in_queue.head];
    in_queue.head = (in_queue.head + 1) % in_queue.num_files;
    pthread_mutex_unlock(&out_queue.mutex);
    return f;
}

void destroy_output_queue(struct output_queue *q) {
    free(q->files);
    q->files = NULL;
    q->num_files = 0;
    q->head = 0;
    q->tail = 0;
}

void init_log(char *filename) {
    log.filename = filename;
    log.fp = fopen(filename, "a");
    if (!log.fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    struct stat st;
    if (stat(filename, &st)) {
        perror("stat");
        exit(EXIT_FAILURE);
    }
    log.size = st.st_size;
