void add_entry(ModemLogEntry *entry) {
    pthread_mutex_lock(&log_mutex);
    if (log_array == NULL || log_array_size >= MAX_LOG_SIZE) {
        // If the log array is full, purge old entries to make room
        purge_old_entries();
    }
    // Add the new entry to the log array
    log_array[log_array_size++] = *entry;
    pthread_mutex_unlock(&log_mutex);
}

// Function to retrieve entries from the log by timestamp
ModemLogEntry *get_entries(time_t start, time_t end) {
    pthread_mutex_lock(&log_mutex);
    // Find the first entry with a timestamp greater than or equal to start
    size_t start_index = 0;
    while (start_index < log_array_size && log_array[start_index].timestamp < start) {
        start_index++;
    }
    // Find the last entry with a timestamp less than or equal to end
    size_t end_index = log_array_size - 1;
    while (end_index >= 0 && log_array[end_index].timestamp > end) {
        end_index--;
    }
    // Create a new array with the entries between start and end
    ModemLogEntry *entries = malloc(sizeof(ModemLogEntry) * (end_index - start_index + 1));
    for (size_t i = start_index; i <= end_index; i++) {
        entries[i - start_index] = log_array[i];
    }
    pthread_mutex_unlock(&log_mutex);
    return entries;
}

// Function to clear the entire log
void clear_log() {
    pthread_mutex_lock(&log_mutex);
    free(log_array);
    log_array = NULL;
    log_array_size = 0;
    pthread_mutex_unlock(&log_mutex);
}

// Function to purge old entries from the log
void purge_old_entries() {
    // Calculate the maximum age of an entry in the log
    time_t max_age = time(NULL) - 30 * 24 * 60 * 60; // 30 days
    pthread_mutex_lock(&log_mutex);
    size_t i = 0;
    while (i < log_array_size && log_array[i].timestamp < max_age) {
        i++;
    }
    if (i > 0) {
        // If there are old entries, move them to the beginning of the array
        memmove(log_array, log_array + i, sizeof(ModemLogEntry) * (log_array_size - i));
        log_array_size -= i;
    }
    pthread_mutex_unlock(&log_mutex);
}

// Function to filter logs based on a specified log level
void filter_logs(int level) {
    pthread_mutex_lock(&log_mutex);
    // Iterate over the log array and remove entries with a lower log level than the specified one
    for (size_t i = 0; i < log_array_size; i++) {
        if (log_array[i].level < level) {
            memmove(log_array + i, log_array + i + 1, sizeof(ModemLogEntry) * (log_array_size - i));
            log_array_size--;
            i--;
        }
    }
    pthread_mutex_unlock(&log_mutex);
}

