// Dynamic array of custom ModemLogEntry structures
struct ModemLogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
};

typedef struct {
    size_t capacity;
    size_t count;
    ModemLogEntry* entries;
} DynamicArray;

// Function to manage the dynamic array of ModemLogEntry structures
void manageModemLog(DynamicArray* log) {
    // Add new entry to the log
    void addEntry(time_t timestamp, int logLevel, char* message) {
        if (log->count == log->capacity) {
            // Resize the array if it's full
            log->entries = realloc(log->entries, 2 * log->capacity * sizeof(ModemLogEntry));
            log->capacity *= 2;
        }
        ModemLogEntry* newEntry = &log->entries[log->count++];
        newEntry->timestamp = timestamp;
        newEntry->logLevel = logLevel;
        newEntry->message = message;
    }

    // Retrieve entries by timestamp
    void getEntriesByTimestamp(time_t start, time_t end) {
        for (size_t i = 0; i < log->count; i++) {
            ModemLogEntry* entry = &log->entries[i];
            if (entry->timestamp >= start && entry->timestamp <= end) {
                // Print the entry
                printf("Timestamp: %ld, Log Level: %d, Message: %s\n", entry->timestamp, entry->logLevel, entry->message);
            }
        }
    }

    // Clear the entire log
    void clearLog() {
        free(log->entries);
        log->count = 0;
        log->capacity = 1;
        log->entries = malloc(sizeof(ModemLogEntry));
    }

    // Limit the number of entries in the log to a specified maximum size
    void limitEntries(size_t maxSize) {
        if (log->count > maxSize) {
            ModemLogEntry* newEntries = malloc(maxSize * sizeof(ModemLogEntry));
            memcpy(newEntries, log->entries, maxSize * sizeof(ModemLogEntry));
            free(log->entries);
            log->entries = newEntries;
            log->count = maxSize;
        }
    }

    // Filter logs based on a specified log level
    void filterLogs(int logLevel) {
        for (size_t i = 0; i < log->count; i++) {
            ModemLogEntry* entry = &log->entries[i];
            if (entry->logLevel >= logLevel) {
                // Print the entry
                printf("Timestamp: %ld, Log Level: %d, Message: %s\n", entry->timestamp, entry->logLevel, entry->message);
            }
        }
    }

    // Automatically purge old entries older than a configurable duration to free up resources
    void purgeOldEntries(time_t duration) {
        time_t currentTime = time(NULL);
        for (size_t i = 0; i < log->count; i++) {
            ModemLogEntry* entry = &log->entries[i];
            if (currentTime - entry->timestamp > duration) {
                // Remove the entry from the array
                memmove(&log->entries[i], &log->entries[i + 1], (log->count - i - 1) * sizeof(ModemLogEntry));
                log->count--;
            }
        }
    }

    // Compact the log structure periodically to reduce memory fragmentation
    void compactLog() {
        ModemLogEntry* newEntries = malloc(log->count * sizeof(ModemLogEntry));
        memcpy(newEntries, log->entries, log->count * sizeof(ModemLogEntry));
        free(log->entries);
        log->entries = newEntries;
    }

    // Export the log entries to a file in a standardized format for external analysis tools
    void exportLogsToFile(char* filename) {
        FILE* fp = fopen(filename, "w");
        if (fp == NULL) {
            printf("Error: Unable to open file %s\n", filename);
            return;
        }
        for (size_t i = 0; i < log->count; i++) {
            ModemLogEntry* entry = &log->entries[i];
            fprintf(fp, "%ld,%d,%s\n", entry->timestamp, entry->logLevel, entry->message);
        }
        fclose(fp);
    }
}

