#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the structure for a single log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Define the structure for the log array
typedef struct {
    LogEntry* entries[MAX_LOG_SIZE];
    size_t num_entries;
} LogArray;

// Define the function to add a new entry to the log
void add_log_entry(LogArray* log, time_t timestamp, int level, char* message) {
    // Check if the log array is full
    if (log->num_entries == MAX_LOG_SIZE) {
        // If it is, purge old entries to make room for the new one
        purge_old_entries(log);
    }

    // Add the new entry to the end of the log array
    LogEntry* new_entry = malloc(sizeof(LogEntry));
    new_entry->timestamp = timestamp;
    new_entry->level = level;
    new_entry->message = strdup(message);
    log->entries[log->num_entries++] = new_entry;
}

// Define the function to retrieve a log entry by timestamp
LogEntry* get_log_entry(LogArray* log, time_t timestamp) {
    // Iterate through the log array and find the entry with the specified timestamp
    for (size_t i = 0; i < log->num_entries; i++) {
        if (log->entries[i]->timestamp == timestamp) {
            return log->entries[i];
        }
    }

    // If no entry was found, return NULL
    return NULL;
}

// Define the function to clear the entire log
void clear_log(LogArray* log) {
    // Free all of the entries in the log array
    for (size_t i = 0; i < log->num_entries; i++) {
        free(log->entries[i]);
    }

    // Reset the number of entries to zero
    log->num_entries = 0;
}

// Define the function to limit the number of entries in the log
void limit_log_size(LogArray* log, size_t max_size) {
    // If the current number of entries is less than or equal to the maximum size, do nothing
    if (log->num_entries <= max_size) {
        return;
    }

    // Purge old entries to make room for new ones
    purge_old_entries(log);
}

// Define the function to filter logs based on a specified log level
void filter_logs(LogArray* log, int level) {
    // Iterate through the log array and remove any entries with a lower log level than the specified one
    for (size_t i = 0; i < log->num_entries; i++) {
        if (log->entries[i]->level < level) {
            free(log->entries[i]);
            log->entries[i] = NULL;
        }
    }
}

// Define the function to purge old entries from the log
void purge_old_entries(LogArray* log) {
    // Sort the log array by timestamp in descending order
    qsort(log->entries, log->num_entries, sizeof(LogEntry), compare_timestamps);

    // Iterate through the log array and remove any entries that are older than the specified duration
    time_t purge_timestamp = time(NULL) - PURGE_DURATION;
    for (size_t i = 0; i < log->num_entries; i++) {
        if (log->entries[i]->timestamp < purge_timestamp) {
            free(log->entries[i]);
            log->entries[i] = NULL;
        } else {
            break;
        }
    }
}

// Define the function to compact the log structure
void compact_log(LogArray* log) {
    // Iterate through the log array and remove any NULL entries
    for (size_t i = 0; i < log->num_entries; i++) {
        if (log->entries[i] == NULL) {
            free(log->entries[i]);
            log->entries[i] = NULL;
        }
    }
}

// Define the function to export the log entries to a file in a standardized format
void export_log_to_file(LogArray* log, FILE* file) {
    // Iterate through the log array and write each entry to the file
    for (size_t i = 0; i < log->num_entries; i++) {
        fprintf(file, "%lu %d %s\n", log->entries[i]->timestamp, log->entries[i]->level, log->entries[i]->message);
    }
}

// Define the function to handle edge cases such as invalid input sizes and maintain thread safety if used in a multi-threaded environment
void handle_edge_cases(LogArray* log) {
    // Check if the log array is full
    if (log->num_entries == MAX_LOG_SIZE) {
        // If it is, purge old entries to make room for new ones
        purge_old_entries(log);
    }

    // Check if the log array is empty
    if (log->num_entries == 0) {
        // If it is, return NULL
        return NULL;
    }
}
