class NetworkTrafficLog {
public:
    // Constructor
    NetworkTrafficLog(int maxSize = 1000, int purgeDuration = 3600) : maxSize_(maxSize), purgeDuration_(purgeDuration) {}

    // Add a new event to the log
    void addEvent(const NetworkTrafficEvent& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        events_.push_back(event);
        if (events_.size() > maxSize_) {
            purgeOldEvents();
        }
    }

    // Retrieve all events for a given source IP
    std::vector<NetworkTrafficEvent> getEventsBySourceIP(const std::string& sourceIP) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<NetworkTrafficEvent> result;
        for (auto& event : events_) {
            if (event.sourceIP == sourceIP) {
                result.push_back(event);
            }
        }
        return result;
    }

    // Retrieve all events for a given destination IP
    std::vector<NetworkTrafficEvent> getEventsByDestinationIP(const std::string& destinationIP) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<NetworkTrafficEvent> result;
        for (auto& event : events_) {
            if (event.destinationIP == destinationIP) {
                result.push_back(event);
            }
        }
        return result;
    }

    // Retrieve all events filtered by protocol type
    std::vector<NetworkTrafficEvent> getEventsByProtocolType(const std::string& protocolType) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<NetworkTrafficEvent> result;
        for (auto& event : events_) {
            if (event.protocolType == protocolType) {
                result.push_back(event);
            }
        }
        return result;
    }

    // Clear the entire traffic log
    void clear() {
        std::lock_guard<std::mutex> lock(mutex_);
        events_.clear();
    }

private:
    // Purge old events to free up resources
    void purgeOldEvents() {
        auto now = std::chrono::system_clock::now();
        for (auto it = events_.begin(); it != events_.end();) {
            if (now - it->timestamp > std::chrono::seconds(purgeDuration_)) {
                it = events_.erase(it);
            } else {
                ++it;
            }
        }
    }

    // Compact the event structure to reduce memory fragmentation
    void compactEvents() {
        std::lock_guard<std::mutex> lock(mutex_);
        events_.shrink_to_fit();
    }

    // Export traffic events to a file in a standardized format
    void exportEventsToFile(const std::string& filename) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::ofstream ofs(filename, std::ios::out | std::ios::binary);
        for (auto& event : events_) {
            ofs.write((char*)&event, sizeof(NetworkTrafficEvent));
        }
    }

    // Background thread to purge old events and compact the log
    void backgroundThread() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(purgeDuration_ / 2));
            purgeOldEvents();
            compactEvents();
        }
    }

    // Mutex to protect the log from concurrent access
    std::mutex mutex_;

    // Vector of events in the log
    std::vector<NetworkTrafficEvent> events_;

    // Maximum size of the log
    int maxSize_;

    // Duration for which old events are purged (in seconds)
    int purgeDuration_;
};
