    if (!entry) {
        pthread_mutex_unlock(&log->lock);
        return;
    }
    entry->timestamp = time(NULL);
    entry->level = 0;
    entry->message = strdup("Stream log message");
    log->entries[log->count++] = entry;

    // Unlock the log
    pthread_mutex_unlock(&log->lock);
}

// Implement a background cleanup service that periodically removes entries older than a specified retention period, using a separate thread pool to manage the cleanup tasks without impacting the main logging process
void modem_log_cleanup(ModemLog* log, time_t retention) {
    // Lock the log to prevent concurrent access
    pthread_mutex_lock(&log->lock);

    // Search for entries older than the specified retention period
    size_t i;
    for (i = 0; i < log->count; i++) {
        if (log->entries[i]->timestamp < time(NULL) - retention) {
            break;
        }
    }

    // Free all entries older than the specified retention period
    size_t j;
    for (j = 0; j < i; j++) {
        free(log->entries[j]->message);
        free(log->entries[j]);
    }
    log->count -= j;

    // Unlock the log
    pthread_mutex_unlock(&log->lock);
}

// Implement a feature that allows the log to grow indefinitely, but with a configurable maximum size per stream, after which it starts to drop entries on a FIFO basis
void modem_log_grow(ModemLog* log) {
    // Lock the log to prevent concurrent access
    pthread_mutex_lock(&log->lock);

    // Add a new entry to the log
    ModemLogEntry* entry = malloc(sizeof(ModemLogEntry));
    if (!entry) {
        pthread_mutex_unlock(&log->lock);
        return;
    }
    entry->timestamp = time(NULL);
    entry->level = 0;
    entry->message = strdup("Grow log message");
    log->entries[log->count++] = entry;

    // Unlock the log
    pthread_mutex_unlock(&log->lock);
}
