    // Array of offsets
    Offset* offsets;
    // Array of keys
    Key* keys;
    // Array of records
    Record* records;
    // Size of the pool
    size_t size;
    // Capacity of the pool
    size_t capacity;
    // Lock for concurrent access
    pthread_mutex_t lock;
};

// Define the function to create a new pool
Pool* create_pool(size_t initial_capacity, size_t range) {
    // Allocate memory for the pool structure
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for pool\n");
        return NULL;
    }

    // Initialize the pool structure
    pool->offsets = malloc(initial_capacity * sizeof(Offset));
    pool->keys = malloc(initial_capacity * sizeof(Key));
    pool->records = malloc(initial_capacity * sizeof(Record));
    pool->size = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);

    // Initialize the offsets, keys, and records
    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->offsets[i].offset = rand() % range;
        pool->keys[i].key = rand() % range;
        pool->records[i].value = rand() % range;
    }

    return pool;
}

// Define the function to resize the pool
void resize_pool(Pool* pool, size_t new_capacity) {
    // Check if the new capacity is greater than the current capacity
    if (new_capacity > pool->capacity) {
        // Allocate memory for the new offsets, keys, and records
        Offset* new_offsets = realloc(pool->offsets, new_capacity * sizeof(Offset));
        Key* new_keys = realloc(pool->keys, new_capacity * sizeof(Key));
        Record* new_records = realloc(pool->records, new_capacity * sizeof(Record));
        if (!new_offsets || !new_keys || !new_records) {
            fprintf(stderr, "Failed to resize pool\n");
            return;
        }

        // Initialize the new offsets, keys, and records
        for (size_t i = pool->capacity; i < new_capacity; ++i) {
            new_offsets[i].offset = rand() % range;
            new_keys[i].key = rand() % range;
            new_records[i].value = rand() % range;
        }

        // Update the pool structure
        pool->offsets = new_offsets;
        pool->keys = new_keys;
        pool->records = new_records;
        pool->capacity = new_capacity;
    }
}

// Define the function to add a record to the pool
void add_record(Pool* pool, int value) {
    // Lock the pool for concurrent access
    pthread_mutex_lock(&pool->lock);

    // Check if the pool is full
    if (pool->size == pool->capacity) {
        // Resize the pool if it is full
        resize_pool(pool, pool->capacity * 2);
    }

    // Add the record to the pool
    pool->records[pool->size].value = value;
    ++pool->size;

    // Unlock the pool for concurrent access
    pthread_mutex_unlock(&pool->lock);
}

// Define the function to get a record from the pool
Record* get_record(Pool* pool, int key) {
    // Lock the pool for concurrent access
    pthread_mutex_lock(&pool->lock);

    // Find the record with the given key
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->keys[i].key == key) {
            Record* record = &pool->records[i];
            pthread_mutex_unlock(&pool->lock);
            return record;
        }
    }

    // Unlock the pool for concurrent access
    pthread_mutex_unlock(&pool->lock);

    // Return NULL if the record is not found
    return NULL;
}

// Define the function to remove a record from the pool
void remove_record(Pool* pool, int key) {
    // Lock the pool for concurrent access
    pthread_mutex_lock(&pool->lock);

    // Find the record with the given key
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->keys[i].key == key) {
            // Remove the record from the pool
            --pool->size;
            for (size_t j = i; j < pool->size; ++j) {
                pool->offsets[j] = pool->offsets[j + 1];
                pool->keys[j] = pool->keys[j + 1];
                pool->records[j] = pool->records[j + 1];
            }
            break;
        }
    }

    // Unlock the pool for concurrent access
    pthread_mutex_unlock(&pool->lock);
}

// Define the function to destroy the pool
void destroy_pool(Pool* pool) {
    // Lock the pool for concurrent access
    pthread_mutex_lock(&pool->lock);

    // Free the memory allocated for the offsets, keys, and records
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);

    // Unlock the pool for concurrent access
    pthread_mutex_unlock(&pool->lock);

    // Free the memory allocated for the pool structure
    free(pool);
}
