            records = realloc(records, argc * sizeof(record_t));
        }

        // Check if any of the arrays need to be initialized
        if (offsets[0].offset == 0 || keys[0].key == 0 || records[0].value == 0) {
            // Initialize the arrays if necessary
            for (int i = 0; i < argc; i++) {
                offsets[i].offset = i * sizeof(offset_t);
                keys[i].key = i + 1;
                records[i].value = rand() % 100;
            }
        }

        // Release the lock to allow other threads to access the shared data structures
        pthread_mutex_unlock(&mutex);

        // Monitor resource usage and log access events
        num_accesses++;
        if (num_accesses % 100 == 0) {
            time_t current_time = time(NULL);
            double elapsed_time = difftime(current_time, start_time);
            printf("Resource usage: %.2f%%\n", (double) num_accesses / elapsed_time * 100);
        }

        // Sleep for a short period of time to simulate workload
        usleep(10000);
    }

    // Free the memory pool and return
    free(mempool);
    pthread_mutex_destroy(&mutex);
    return NULL;
}
