        Offset* new_offsets = (Offset*)realloc(pool->offsets, new_capacity * sizeof(Offset));
        Key* new_keys = (Key*)realloc(pool->keys, new_capacity * sizeof(Key));
        Record* new_records = (Record*)realloc(pool->records, new_capacity * sizeof(Record));

        // Check if the reallocation was successful
        if (!new_offsets || !new_keys || !new_records) {
            return;
        }

        // Update the fields of the resource pool structure
        pool->capacity = new_capacity;
        pool->offsets = new_offsets;
        pool->keys = new_keys;
        pool->records = new_records;
    }
}

// Define the function to add a record to the resource pool
void add_record(ResourcePool* pool, int value) {
    // Check if the pool is full
    if (pool->size == pool->capacity) {
        // Resize the pool if necessary
        resize_resource_pool(pool, pool->capacity * 2);
    }

    // Add a new record to the pool
    pool->records[pool->size].value = value;
    ++pool->size;
}

// Define the function to get a record from the resource pool
Record* get_record(ResourcePool* pool, int key) {
    // Check if the key is valid
    if (key < 0 || key >= pool->capacity) {
        return NULL;
    }

    // Return the record corresponding to the key
    return &pool->records[key];
}

// Define the function to delete a record from the resource pool
void delete_record(ResourcePool* pool, int key) {
    // Check if the key is valid
    if (key < 0 || key >= pool->capacity) {
        return;
    }

    // Shift all records after the specified key to fill the gap
    for (size_t i = key + 1; i < pool->size; ++i) {
        pool->records[i - 1] = pool->records[i];
    }

    --pool->size;
}

// Define the function to release resources used by the resource pool
void destroy_resource_pool(ResourcePool* pool) {
    // Free the memory allocated for the arrays of offsets, keys, and records
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);

    // Free the memory allocated for the resource pool structure
    free(pool);
}
