struct record {
    long offset;
    int key;
    char* user_id;
};

void process_file(const char* filepath) {
    // Open the file for reading
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error opening file %s\n", filepath);
        return;
    }

    // Initialize a hash object to compute the MD5 hash of the file contents
    hashlib_md5_t* md5 = hashlib_md5_new();

    // Allocate memory for the records in chunks to avoid excessive memory consumption
    const int chunk_size = 1024;
    struct record* records = (struct record*)malloc(chunk_size * sizeof(struct record));

    // Initialize a mutex to synchronize access to the cache and the hash object
    std::mutex mtx;

    // Initialize a cache for user IDs to minimize network requests and improve performance
    std::map<std::string, char*> user_id_cache;

    // Read the file in chunks and update the hash using the hashlib.md5() object
    while (!feof(fp)) {
        // Read a chunk of data from the file
        char buffer[chunk_size];
        size_t bytes_read = fread(buffer, 1, chunk_size, fp);

        // Update the hash using the hashlib.md5() object
        hashlib_md5_update(md5, buffer, bytes_read);

        // Process each record in the chunk
        for (int i = 0; i < bytes_read / sizeof(struct record); i++) {
            struct record* rec = &records[i];

            // Get the user ID from the cache if available, otherwise fetch it from the external API
            char* user_id = NULL;
            std::string user_id_str = std::to_string(rec->key);
            {
                std::lock_guard<std::mutex> lock(mtx);
                auto it = user_id_cache.find(user_id_str);
                if (it != user_id_cache.end()) {
                    user_id = it->second;
                } else {
                    // Fetch the user ID from the external API and add it to the cache
                    user_id = fetch_user_id(rec->key);
                    user_id_cache[user_id_str] = user_id;
                }
            }

            // Initialize the record with the offset, key, and user ID
            rec->offset = i * sizeof(struct record);
            rec->key = rec->key;
            rec->user_id = user_id;
        }
    }

    // Compute the hexdigest of the hash object
    char* hexdigest = hashlib_md5_hexdigest(md5);

    // Clean up resources
    fclose(fp);
    hashlib_md5_free(md5);
    free(records);

    return hexdigest;
}

