            char* user_id = fetch_user_id_from_api(key);
            return user_id;
        } catch (const std::exception& e) {
            // Handle transient failures gracefully by retrying with exponential backoff
            printf("Error fetching user ID for key %d: %s\n", key, e.what());
            if (backoff >= max_retries * initial_backoff) {
                throw;
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(backoff));
                backoff *= 2;
            }
        }
    }
