```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for a log entry
typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
    char* source_ip;
    int error_code;
    // Other metadata fields...
} ModemLogEntry;

// Define the structure for a record in the dynamic array
typedef struct {
    long offset;
    int key;
    ModemLogEntry entry;
} Record;

// Define the global variables for the log instances
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_instances = 0;
static int max_size = 1000; // Default maximum size of each instance
static int retention_policy = 2; // Default retention policy (maximum age)
static int total_memory = 0; // Total memory used by the log entries
static Record* records = NULL; // Array of records

// Function to add a new entry to the log
void add_entry(ModemLogEntry* entry, int instance_id) {
    pthread_mutex_lock(&mutex);
    if (instance_id < 0 || instance_id >= num_instances) {
        // Invalid instance ID
        pthread_mutex_unlock(&mutex);
        return;
    }
    int index = -1;
    for (int i = 0; i < max_size; i++) {
        if (records[i].key == -1) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        // Log is full, need to resize
        int new_max_size = max_size * 2;
        Record* new_records = realloc(records, sizeof(Record) * new_max_size);
        if (new_records == NULL) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        records = new_records;
        max_size = new_max_size;
        index = 0;
    }
    records[index].key = instance_id;
    records[index].entry = *entry;
    total_memory += sizeof(ModemLogEntry);
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve entries by timestamp
void get_entries_by_timestamp(time_t timestamp, int instance_id) {
    pthread_mutex_lock(&mutex);
    if (instance_id < 0 || instance_id >= num_instances) {
        // Invalid instance ID
        pthread_mutex_unlock(&mutex);
        return;
    }
    int index = -1;
    for (int i = 0; i < max_size; i++) {
        if (records[i].key == instance_id && records[i].entry.timestamp >= timestamp) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        // No entries found
        pthread_mutex_unlock(&mutex);
        return;
    }
    ModemLogEntry* entry = &records[index].entry;
    printf("Timestamp: %ld, Log Level: %d, Message: %s, Source IP: %s, Error Code: %d\n",
           entry->timestamp, entry->log_level, entry->message, entry->source_ip, entry->error_code);
    pthread_mutex_unlock(&mutex);
}

// Function to clear the entire log
void clear_log(int instance_id) {
    pthread_mutex_lock(&mutex);
    if (instance_id < 0 || instance_id >= num_instances) {
        // Invalid instance ID
        pthread_mutex_unlock(&mutex);
        return;
    }
    for (int i = 0; i < max_size; i++) {
        if (records[i].key == instance_id) {
            records[i].key = -1;
            total_memory -= sizeof(ModemLogEntry);
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to export the log entries to a file
void export_log(int instance_id, char* filename) {
    pthread_mutex_lock(&mutex);
    if (instance_id < 0 || instance_id >= num_instances) {
        // Invalid instance ID
        pthread_mutex_unlock(&mutex);
        return;
    }
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        // Failed to open the file
        pthread_mutex_unlock(&mutex);
        return;
    }
    for (int i = 0; i < max_size; i++) {
        if (records[i].key == instance_id) {
            ModemLogEntry* entry = &records[i].entry;
            fprintf(file, "%ld,%d,%s,%s,%d\n",
                    entry->timestamp, entry->log_level, entry->message, entry->source_ip, entry->error_code);
        }
    }
    fclose(file);
    pthread_mutex_unlock(&mutex);
}

// Function to automatically archive old entries when the log reaches its maximum size
void archive_old_entries(int instance_id) {
    pthread_mutex_lock(&mutex);
    if (instance_id < 0 || instance_id >= num_instances) {
        // Invalid instance ID
        pthread_mutex_unlock(&mutex);
        return;
    }
    int index = -1;
    for (int i = 0; i < max_size; i++) {
        if (records[i].key == instance_id) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        // No entries found
        pthread_mutex_unlock(&mutex);
        return;
    }
    int oldest_entry = index;
    for (int i = 0; i < max_size; i++) {
        if (records[i].key == instance_id && records[i].timestamp < records[oldest_entry].timestamp) {
            oldest_entry = i;
        }
    }
    // Move the oldest entry to the end of the array
    Record* temp = &records[oldest_entry];
    for (int i = oldest_entry + 1; i < max_size; i++) {
        records[i - 1] = records[i];
    }
    records[max_size - 1] = *temp;
    total_memory -= sizeof(ModemLogEntry);
    pthread_mutex_unlock(&mutex);
}

// Function to manage memory allocation and initialization for a set of records
void allocate_records(int num_records) {
    pthread_mutex_lock(&mutex);
    if (num_records <= 0) {
        // Invalid number of records
        pthread_mutex_unlock(&mutex);
        return;
    }
    int new_max_size = num_records * 2;
    Record* new_records = realloc(records, sizeof(Record) * new_max_size);
    if (new_records == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    records = new_records;
    max_size = new_max_size;
    for (int i = 0; i < num_records; i++) {
        records[i].key = -1;
        total_memory += sizeof(ModemLogEntry);
    }
    pthread_mutex_unlock(&mutex);
}

// Function to initialize a record with an `int` value initialized to a random number within a specified range
void init_record(Record* record, int min, int max) {
    if (min > max || min == 0 || max == 0) {
        // Invalid input range
        return;
    }
    record->key = -1;
    record->offset = rand() % (max - min + 1) + min;
}

// Function to dynamically adjust the random number range based on the input data distribution
void adjust_random_range(int* min, int* max) {
    if (*min > *max || *min == 0 || *max == 0) {
        // Invalid input range
        return;
    }
    int mid = (*min + *max) / 2;
    int left_count = 0, right_count = 0;
    for (int i = 0; i < max_size; i++) {
        if (records[i].offset >= mid) {
            right_count++;
        } else {
            left_count++;
        }
    }
    if (left_count > right_count) {
        *max = mid - 1;
    } else {
        *min = mid + 1;
    }
}
```
