        return;
    }

    // Handle the case where the input list is not sorted
    if (!is_sorted(list)) {
        printf("Error: Input list is not sorted\n");
        return;
    }
}

// Function to manage memory allocation and initialization for a set of records while ensuring memory efficiency, performance, and scalability
void allocate_memory_for_records() {
    // Allocate memory for the offset array
    int num_offsets = 0;
    for (int i = 0; i < list->size; i++) {
        if (list->data[i] != NULL) {
            num_offsets++;
        }
    }
    long* offsets = (long*) malloc(sizeof(long) * num_offsets);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with the starting indices of each record in the input list
    int current_offset = 0;
    for (int i = 0; i < list->size; i++) {
        if (list->data[i] != NULL) {
            offsets[current_offset++] = i;
        }
    }

    // Allocate memory for the key array
    int num_keys = list->size - num_offsets + 1;
    int* keys = (int*) malloc(sizeof(int) * num_keys);
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
