        if (list->data[i] != NULL) {
            keys[current_offset++] = list->data[i]->key;
        }
    }

    // Allocate memory for the record array
    int num_records = num_offsets * num_keys;
    Record* records = (Record*) malloc(sizeof(Record) * num_records);
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record array with random values within a specified range
    srand(time(NULL));
    int min_value = 0;
    int max_value = 100;
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Dynamically adjust the random number range based on the input data distribution to minimize unnecessary random number generation while maintaining statistical validity
    int num_unique_keys = current_offset;
    if (num_unique_keys > 0) {
        min_value = keys[0];
        max_value = keys[current_offset - 1];
    } else {
        min_value = 0;
        max_value = 0;
    }
}
