import os
import struct
import threading
import time
import zlib
from collections import deque
from typing import Deque, Dict, List, Optional, Tuple

class ResourceBundle:
    def __init__(self, items: List[Tuple[str, bytes]]):
        self.items = items

    def get_item(self, key: str) -> Optional[bytes]:
        for item in self.items:
            if item[0] == key:
                return item[1]
        return None

class ResourceBundleLoader:
    def __init__(self):
        self.cache = {}  # type: Dict[str, ResourceBundle]
        self.lock = threading.Lock()

    def load_resource_bundle(self, filepath: str) -> Optional[ResourceBundle]:
        with self.lock:
            if filepath in self.cache:
                return self.cache[filepath]

            try:
                with open(filepath, "rb") as f:
                    data = f.read()
            except FileNotFoundError:
                print(f"File {filepath} not found.")
                return None

            items = []  # type: List[Tuple[str, bytes]]
            offset = 0
            while offset < len(data):
                size, type_id = struct.unpack("II", data[offset:offset + 8])
                offset += 8
                item = (type_id, data[offset:offset + size])
                items.append(item)
                offset += size

            bundle = ResourceBundle(items)
            self.cache[filepath] = bundle
            return bundle

    def get_resource_bundle(self, filepath: str) -> Optional[ResourceBundle]:
        with self.lock:
            if filepath in self.cache:
                return self.cache[filepath]
            else:
                return None

class ResourceBundleCompressor:
    def __init__(self):
        pass

    def compress(self, data: bytes) -> bytes:
        return zlib.compress(data)

    def decompress(self, data: bytes) -> bytes:
        return zlib.decompress(data)

class ResourceBundleParser:
    def __init__(self):
        pass

    def parse_resource_bundle(self, data: bytes) -> Optional[ResourceBundle]:
        items = []  # type: List[Tuple[str, bytes]]
        offset = 0
        while offset < len(data):
            size, type_id = struct.unpack("II", data[offset:offset + 8])
            offset += 8
            item = (type_id, data[offset:offset + size])
            items.append(item)
            offset += size
        return ResourceBundle(items)

class ResourceBundleCache:
    def __init__(self):
        self.cache = {}  # type: Dict[str, ResourceBundle]
        self.lock = threading.Lock()

    def get_resource_bundle(self, filepath: str) -> Optional[ResourceBundle]:
        with self.lock:
            if filepath in self.cache:
                return self.cache[filepath]
            else:
                return None

    def set_resource_bundle(self, filepath: str, bundle: ResourceBundle):
        with self.lock:
            self.cache[filepath] = bundle

class ResourceBundleLoaderThread(threading.Thread):
    def __init__(self, loader: ResourceBundleLoader, filepaths: List[str], cache: ResourceBundleCache):
        super().__init__()
        self.loader = loader
        self.filepaths = filepaths
        self.cache = cache

    def run(self):
        for filepath in self.filepaths:
            bundle = self.loader.load_resource_bundle(filepath)
            if bundle is not None:
                self.cache.set_resource_bundle(filepath, bundle)

class ResourceBundleLoaderPool:
    def __init__(self):
        self.threads = []  # type: List[ResourceBundleLoaderThread]
        self.lock = threading.Lock()

    def add_thread(self, loader: ResourceBundleLoader, filepaths: List[str], cache: ResourceBundleCache):
        with self.lock:
            thread = ResourceBundleLoaderThread(loader, filepaths, cache)
            self.threads.append(thread)
            thread.start()

    def join_all(self):
        with self.lock:
            for thread in self.threads:
                thread.join()

class ResourceBundleManager:
    def __init__(self, loader: ResourceBundleLoader, compressor: ResourceBundleCompressor, parser: ResourceBundleParser, cache: ResourceBundleCache):
        self.loader = loader
        self.compressor = compressor
        self.parser = parser
        self.cache = cache

    def load_resource_bundle(self, filepath: str) -> Optional[ResourceBundle]:
        bundle = self.cache.get_resource_bundle(filepath)
        if bundle is not None:
            return bundle

        try:
            with open(filepath, "rb") as f:
                data = f.read()
        except FileNotFoundError:
            print(f"File {filepath} not found.")
            return None

        if self.compressor.decompress(data):
            bundle = self.parser.parse_resource_bundle(data)
            if bundle is not None:
                self.cache.set_resource_bundle(filepath, bundle)
                return bundle

    def get_resource_bundle(self, filepath: str) -> Optional[ResourceBundle]:
        bundle = self.cache.get_resource_bundle(filepath)
        if bundle is not None:
            return bundle

        bundle = self.load_resource_bundle(filepath)
        if bundle is not None:
            self.cache.set_resource_bundle(filepath, bundle)
        return bundle

class ResourceBundleLogger:
    def __init__(self):
        pass

    def log(self, message: str, level: int = 0):
        print(message)

class ResourceBundleErrorHandler:
    def __init__(self):
        self.errors = []  # type: List[str]

    def handle_error(self, error: str):
        self.errors.append(error)

def load_and_hash_resource_bundle(filepath: str, hash_function=None) -> Optional[ResourceBundle]:
    loader = ResourceBundleLoader()
    compressor = ResourceBundleCompressor()
    parser = ResourceBundleParser()
    cache = ResourceBundleCache()
    logger = ResourceBundleLogger()
    error_handler = ResourceBundleErrorHandler()
    manager = ResourceBundleManager(loader, compressor, parser, cache)

    bundle = manager.load_resource_bundle(filepath)
    if bundle is not None:
        return bundle

    try:
        with open(filepath, "rb") as f:
            data = f.read()
    except FileNotFoundError:
        logger.log(f"File {filepath} not found.")
        error_handler.handle_error(f"File {filepath} not found.")
        return None

    if compressor.decompress(data):
        bundle = parser.parse_resource_bundle(data)
        if bundle is not None:
            cache.set_resource_bundle(filepath, bundle)
            return bundle

    logger.log(f"Failed to load resource bundle from {filepath}.")
    error_handler.handle_error(f"Failed to load resource bundle from {filepath}.")
    return None
