#include <stdio.h>

// Define the structure for a NICP message
typedef struct {
    char header[10]; // 10 bytes for the connection request header
    int session_id; // 4 bytes for the session ID
    char body[PAYLOAD_SIZE]; // variable size payload
} nicp_message_t;

// Define a dynamic array to store NICP messages
nicp_message_t* initialize_nicp_messages(int num_messages, int payload_size) {
    // Allocate memory for the dynamic array
    nicp_message_t** messages = malloc(num_messages * sizeof(nicp_message_t*));
    if (!messages) {
        fprintf(stderr, "Failed to allocate memory for NICP messages\n");
        return NULL;
    }

    // Initialize each message with a valid connection request header and session ID
    for (int i = 0; i < num_messages; i++) {
        messages[i] = malloc(sizeof(nicp_message_t));
        if (!messages[i]) {
            fprintf(stderr, "Failed to allocate memory for NICP message %d\n", i);
            return NULL;
        }
        memcpy(messages[i]->header, "CONNECT", 7); // 7 bytes for the connection request header
        messages[i]->session_id = i + 1; // start with session ID 1
    }

    // Allocate memory for each message body and populate it with random data
    for (int i = 0; i < num_messages; i++) {
        messages[i]->body = malloc(payload_size);
        if (!messages[i]->body) {
            fprintf(stderr, "Failed to allocate memory for NICP message body %d\n", i);
            return NULL;
        }
        // populate the message body with random data
        for (int j = 0; j < payload_size; j++) {
            messages[i]->body[j] = rand() & 0xFF;
        }
    }

    return messages;
}
