} data_aggregation_struct;

data_aggregation_struct *allocate_memory(int num_records) {
    // Allocate memory for the arrays
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    record **records = (record **)malloc(num_records * sizeof(record *));
    char **metadata = (char **)malloc(num_records * sizeof(char *));
    event_timestamp **event_timestamps = (event_timestamp **)malloc(num_records * sizeof(event_timestamp *));

    // Initialize the arrays with random values within a specified range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000000;
        keys[i] = rand() % 1000000;
        records[i] = malloc(sizeof(record));
        metadata[i] = malloc(256);
        event_timestamps[i] = malloc(sizeof(event_timestamp));
    }

    // Initialize the record structures with unique user IDs and status codes
    for (int i = 0; i < num_records; i++) {
        sprintf(metadata[i], "User ID: %d", keys[i]);
        records[i]->status_code = rand() % 1000000;
        records[i]->user_id = malloc(256);
        strcpy(records[i]->user_id, metadata[i]);
    }

    // Allocate memory for the data aggregation structure
    data_aggregation_struct *data_aggregation = (data_aggregation_struct *)malloc(sizeof(data_aggregation_struct));
    data_aggregation->offsets = offsets;
    data_aggregation->keys = keys;
    data_aggregation->records = records;
    data_aggregation->metadata = metadata;
    data_aggregation->event_timestamps = event_timestamps;

    return data_aggregation;
}
