#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define a custom data structure to store network metrics
typedef struct NetworkMetrics {
    int latency;
    int throughput;
    float packetLossPercentage;
    char* interfaceId;
} NetworkMetrics;

// Define a dynamic array to store the network metrics
typedef struct DynamicArray {
    NetworkMetrics** data;
    size_t capacity;
    size_t size;
} DynamicArray;

// Initialize a new dynamic array with a given capacity
void initDynamicArray(DynamicArray* arr, size_t capacity) {
    assert(arr != NULL);
    arr->data = (NetworkMetrics**)malloc(capacity * sizeof(NetworkMetrics*));
    if (arr->data == NULL) {
        printf("Error: Failed to allocate memory for dynamic array\n");
        exit(1);
    }
    arr->capacity = capacity;
    arr->size = 0;
}

// Add a new network metric entry to the dynamic array
void addNetworkMetric(DynamicArray* arr, NetworkMetrics* metric) {
    assert(arr != NULL && metric != NULL);
    if (arr->size == arr->capacity) {
        // Reallocate memory for the dynamic array if it's full
        size_t newCapacity = arr->capacity * 2;
        NetworkMetrics** newData = (NetworkMetrics**)realloc(arr->data, newCapacity * sizeof(NetworkMetrics*));
        if (newData == NULL) {
            printf("Error: Failed to reallocate memory for dynamic array\n");
            exit(1);
        }
        arr->data = newData;
        arr->capacity = newCapacity;
    }
    arr->data[arr->size++] = metric;
}

// Retrieve network metric entries within a given time interval
void getNetworkMetrics(DynamicArray* arr, int startTime, int endTime) {
    assert(arr != NULL);
    for (int i = 0; i < arr->size; i++) {
        NetworkMetrics* metric = arr->data[i];
        if (metric->timestamp >= startTime && metric->timestamp <= endTime) {
            printf("Latency: %d, Throughput: %d, Packet Loss Percentage: %.2f\n",
                   metric->latency, metric->throughput, metric->packetLossPercentage);
        }
    }
}

// Clear the entire network metric history
void clearNetworkMetrics(DynamicArray* arr) {
    assert(arr != NULL);
    for (int i = 0; i < arr->size; i++) {
        NetworkMetrics* metric = arr->data[i];
        free(metric);
    }
    arr->size = 0;
}

// Release memory allocated by the dynamic array
void destroyDynamicArray(DynamicArray* arr) {
    assert(arr != NULL);
    for (int i = 0; i < arr->size; i++) {
        NetworkMetrics* metric = arr->data[i];
        free(metric);
    }
    free(arr->data);
}
```
