    ModemLogEntry* filteredEntries = malloc(log->count * sizeof(ModemLogEntry));
    size_t count = 0;
    for (size_t i = 0; i < log->count; i++) {
        if (log->entries[i].level == level) {
            filteredEntries[count++] = log->entries[i];
        }
    }
    return filteredEntries;
}

