    for (size_t i = 0; i < log->count; i++) {
        if (log->entries[i].timestamp < time(NULL) - duration) {
            memmove(&log->entries[i], &log->entries[i + 1], sizeof(ModemLogEntry));
            log->count--;
            i--;
        }
    }
}

