// Struct to hold information about a cryptographic function
typedef struct {
    const char* name;
    void* impl;
    void* params;
} crypt_func_t;

// Function to load and initialize the cryptographic libraries
int load_crypt_libs(const char* config_file) {
    // Load the configuration file
    FILE* fp = fopen(config_file, "r");
    if (!fp) {
        printf("Error: failed to open configuration file\n");
        return -1;
    }

    // Read the configuration file and load the libraries
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') continue;

        // Split the line into library name and function name
        char* lib_name = strtok(line, " ");
        char* func_name = strtok(NULL, " ");

        // Load the library using dlopen
        void* handle = dlopen(lib_name, RTLD_LAZY);
        if (!handle) {
            printf("Error: failed to load library %s\n", lib_name);
            continue;
        }

        // Get the function pointer using dlsym
        void* func = dlsym(handle, func_name);
        if (!func) {
            printf("Error: failed to get function pointer for %s\n", func_name);
            dlclose(handle);
            continue;
        }

        // Add the function to the list of available functions
        crypt_func_t* new_func = malloc(sizeof(crypt_func_t));
        new_func->name = func_name;
        new_func->impl = func;
        new_func->params = NULL; // TODO: add parameter handling here
        // Add the function to the list of available functions
        crypt_func_t** funcs = realloc(available_funcs, sizeof(crypt_func_t*) * (num_funcs + 1));
        if (!funcs) {
            printf("Error: failed to allocate memory for available functions\n");
            dlclose(handle);
            continue;
        }
        available_funcs = funcs;
        available_funcs[num_funcs++] = new_func;
    }

    // Close the configuration file
    fclose(fp);

    return 0;
}

// Function to retrieve a list of available cryptographic functions
crypt_func_t** get_available_funcs() {
    if (!available_funcs) {
        load_crypt_libs("config.txt");
    }
    return available_funcs;
}

// Function to retrieve a specific cryptographic function by name
crypt_func_t* get_func(const char* func_name) {
    if (!available_funcs) {
        load_crypt_libs("config.txt");
    }
    for (int i = 0; i < num_funcs; i++) {
        if (strcmp(available_funcs[i]->name, func_name) == 0) {
            return available_funcs[i];
        }
    }
    return NULL;
}

// Function to call a specific cryptographic function by name
void* call_func(const char* func_name, void* params) {
    crypt_func_t* func = get_func(func_name);
    if (!func) {
        printf("Error: unknown function %s\n", func_name);
        return NULL;
    }
    return func->impl(params);
}
