                    var size = BitConverter.ToInt32(buffer, offset);
                    var typeId = buffer[offset + sizeof(int)];

                    if (typeId == 1) // MAC_PDU
                    {
                        var macHeader = new MAC_HEADER();
                        var macPayload = new MAC_PAYLOAD();
                        var macTrailer = new MAC_TRAILER();

                        offset += sizeof(int);
                        macHeader.Parse(buffer, ref offset);
                        macPayload.Parse(buffer, ref offset);
                        macTrailer.Parse(buffer, ref offset);

                        var macPdu = new MAC_PDU(macHeader, macPayload, macTrailer);
                        _array.Add(macPdu);
                    }
                }
            }

            return itemCount;
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error loading resource bundle: " + ex.Message);
            return -1;
        }
    }

    public void Add(MAC_PDU macPdu)
    {
        lock (_lock)
        {
            if (_array.Count >= MAX_CAPACITY)
            {
                TriggerGracefulDegradation();
            }

            _array.Add(macPdu);
            _cache[macPdu.Id] = macPdu;
        }
    }

    public void Remove(int id)
    {
        lock (_lock)
        {
            if (_cache.ContainsKey(id))
            {
                var macPdu = _cache[id];
                _array.Remove(macPdu);
                _cache.Remove(id);
            }
        }
    }

    public MAC_PDU Get(int id)
    {
        lock (_lock)
        {
            if (_cache.ContainsKey(id))
            {
                return _cache[id];
            }
            else
            {
                var macPdu = new MAC_PDU();
                _array.Add(macPdu);
                _cache[id] = macPdu;
                return macPdu;
            }
        }
    }

    public void TriggerGracefulDegradation()
    {
        // Implement graceful degradation strategy here.
    }

    public void CompressPayload(MAC_PDU macPdu)
    {
        lock (_lock)
        {
            var compressedData = new byte[macPdu.Payload.Length];
            using (var compressor = new DeflateStream(new MemoryStream(compressedData), CompressionMode.Compress, COMPRESSION_LEVEL))
            {
                compressor.Write(macPdu.Payload, 0, macPdu.Payload.Length);
            }

            macPdu.Payload = compressedData;
        }
    }

    public void DecompressPayload(MAC_PDU macPdu)
    {
        lock (_lock)
        {
            var decompressedData = new byte[macPdu.Payload.Length];
            using (var decompressor = new DeflateStream(new MemoryStream(decompressedData), CompressionMode.Decompress))
            {
                decompressor.Write(macPdu.Payload, 0, macPdu.Payload.Length);
            }

            macPdu.Payload = decompressedData;
        }
    }
}
