// Define the structure for log entries
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the retention policy for each tenant
typedef struct {
    int max_log_size;
    int purge_frequency;
} RetentionPolicy;

// Define the logging function
void log(int level, char* message) {
    // Create a new log entry
    ModemLogEntry* entry = (ModemLogEntry*)malloc(sizeof(ModemLogEntry));
    entry->timestamp = time(NULL);
    entry->level = level;
    entry->message = strdup(message);

    // Add the log entry to the array
    pthread_mutex_lock(&log_mutex);
    if (log_array_size < MAX_LOG_SIZE) {
        log_array[log_array_size++] = entry;
    } else {
        // Purge old entries if necessary
        purgeOldEntries();
        log_array[log_array_size++] = entry;
    }
    pthread_mutex_unlock(&log_mutex);
}

// Define the function to purge old entries
void purgeOldEntries() {
    // Check if there are any old entries to purge
    if (log_array_size > 0) {
        // Find the oldest entry and remove it from the array
        int oldest_index = 0;
        for (int i = 1; i < log_array_size; i++) {
            if (log_array[i]->timestamp < log_array[oldest_index]->timestamp) {
                oldest_index = i;
            }
        }
        free(log_array[oldest_index]);
        log_array[oldest_index] = NULL;
        log_array_size--;
    }
}

// Define the function to compact the log structure
void compactLog() {
    // Check if there are any unused entries in the array
    int unused_entries = 0;
    for (int i = 0; i < log_array_size; i++) {
        if (log_array[i] == NULL) {
            unused_entries++;
        }
    }

    // If there are any unused entries, compact the array
    if (unused_entries > 0) {
        int new_size = log_array_size - unused_entries;
        ModemLogEntry* new_log_array = (ModemLogEntry*)malloc(new_size * sizeof(ModemLogEntry));
        for (int i = 0, j = 0; i < log_array_size; i++) {
            if (log_array[i] != NULL) {
                new_log_array[j++] = log_array[i];
            }
        }
        free(log_array);
        log_array = new_log_array;
        log_array_size = new_size;
    }
}

// Define the function to export logs to a file
void exportLogsToFile() {
    // Open the log file for writing
    FILE* log_file = fopen("logs.txt", "w");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }

    // Write each log entry to the file
    pthread_mutex_lock(&log_mutex);
    for (int i = 0; i < log_array_size; i++) {
        fprintf(log_file, "%d %s\n", log_array[i]->timestamp, log_array[i]->message);
    }
    pthread_mutex_unlock(&log_mutex);

    // Close the log file
    fclose(log_file);
}
