// Define the function to read an input audio file and parse its contents
int read_audio_file(char *input_file, struct audio_frame **audio_buffer, int *buffer_size) {
    // Initialize variables
    int fd = 0;
    char *buffer = NULL;
    int bytes_read = 0;
    int i;

    // Open the input file in read-only mode
    if ((fd = open(input_file, O_RDONLY)) == -1) {
        printf("Error: Failed to open input file.\n");
        return -1;
    }

    // Read the contents of the input file into a buffer
    buffer = (char *)malloc(sizeof(char) * 4096);
    while ((bytes_read = read(fd, buffer + bytes_read, sizeof(char) * 4096)) > 0) {
        // Process each audio frame
        for (i = 0; i < bytes_read / sizeof(float); i++) {
            // Parse the contents of the buffer into an audio frame structure
            struct audio_frame *audio_frame = (struct audio_frame *)malloc(sizeof(struct audio_frame));
            audio_frame->timestamp = generate_timestamp();
            audio_frame->sample_rate = 44100.0f;
            audio_frame->channel_count = 2;
            audio_frame->audio_samples = (char *)malloc(sizeof(char) * 4096);
            memcpy(audio_frame->audio_samples, buffer + i * sizeof(float), sizeof(float));
            // Add the audio frame to the audio buffer
            if (*audio_buffer == NULL) {
                *audio_buffer = (struct audio_frame *)malloc(sizeof(struct audio_frame));
                (*audio_buffer)->timestamp = audio_frame->timestamp;
                (*audio_buffer)->sample_rate = audio_frame->sample_rate;
                (*audio_buffer)->channel_count = audio_frame->channel_count;
                (*audio_buffer)->audio_samples = (char *)malloc(sizeof(char) * 4096);
                memcpy((*audio_buffer)->audio_samples, audio_frame->audio_samples, sizeof(float));
            } else {
                struct audio_frame **temp = (struct audio_frame **)realloc(*audio_buffer, (*buffer_size + 1) * sizeof(struct audio_frame));
                if (temp == NULL) {
                    printf("Error: Failed to allocate memory for audio buffer.\n");
                    free(audio_frame);
                    return -1;
                }
                *audio_buffer = temp;
                (*audio_buffer)[*buffer_size].timestamp = audio_frame->timestamp;
                (*audio_buffer)[*buffer_size].sample_rate = audio_frame->sample_rate;
                (*audio_buffer)[*buffer_size].channel_count = audio_frame->channel_count;
                (*audio_buffer)[*buffer_size].audio_samples = (char *)malloc(sizeof(char) * 4096);
                memcpy((*audio_buffer)[*buffer_size].audio_samples, audio_frame->audio_samples, sizeof(float));
            }
            (*buffer_size)++;
        }
    }

    // Close the input file and free memory for the buffer
    close(fd);
    free(buffer);

    return 0;
}

// Define the function to write an output audio file with the highest precision value, average, and event with the highest probability
int write_output_file(char *output_file, char *identifier, unsigned long timestamp, int channel_count, float sample_rate, char *audio_samples) {
    // Initialize variables
    int fd = 0;
    char *buffer = NULL;
    int bytes_written = 0;
    int i;

    // Open the output file in write-only mode
    if ((fd = open(output_file, O_WRONLY)) == -1) {
        printf("Error: Failed to open output file.\n");
        return -1;
    }

    // Write the contents of the audio frame structure into a buffer
    buffer = (char *)malloc(sizeof(char) * 4096);
    for (i = 0; i < channel_count; i++) {
        memcpy(buffer + bytes_written, audio_samples + i * sizeof(float), sizeof(float));
        bytes_written += sizeof(float);
    }

    // Write the contents of the buffer to the output file
    if (write(fd, buffer, bytes_written) == -1) {
        printf("Error: Failed to write output file.\n");
        free(buffer);
        return -1;
    }

    // Close the output file and free memory for the buffer
    close(fd);
    free(buffer);

    return 0;
}

