using System;
using System.IO;
using System.Threading;
using System.Collections.Generic;

public class DynamicArrayManager
{
    private const int MAX_CAPACITY = 10000;
    private const int BLOCK_SIZE = 1024;
    private const int COMPRESSION_LEVEL = 6;

    private List<MAC_PDU> _array;
    private Dictionary<int, MAC_PDU> _cache;
    private object _lock = new object();

    public DynamicArrayManager()
    {
        _array = new List<MAC_PDU>(MAX_CAPACITY);
        _cache = new Dictionary<int, MAC_PDU>();
    }

    public int LoadResourceBundle(string path)
    {
        try
        {
            using (var fileStream = new FileStream(path, FileMode.Open))
            {
                var bundleSize = fileStream.Length;
                var buffer = new byte[bundleSize];
                fileStream.Read(buffer, 0, buffer.Length);

                var headerSize = sizeof(int) + sizeof(byte);
                for (var i = 0; i < bundleSize - headerSize; i += BLOCK_SIZE)
                {
                    var itemSize = BitConverter.ToInt32(buffer, i);
                    var typeId = buffer[i + sizeof(int)];

                    if (typeId == MAC_PDU.TypeId)
                    {
                        var macPdu = new MAC_PDU();
                        macPdu.Header = BitConverter.ToInt32(buffer, i + headerSize);
                        macPdu.Payload = Compress(buffer, i + headerSize + sizeof(int), itemSize - headerSize);
                        macPdu.Trailer = BitConverter.ToInt32(buffer, i + itemSize - sizeof(int));

                        lock (_lock)
                        {
                            _array.Add(macPdu);
                            _cache[macPdu.Header] = macPdu;
                        }
                    }
                }
            }
        }
        catch (Exception e)
        {
            Console.WriteLine("Error loading resource bundle: " + e.Message);
            return -1;
        }

        return _array.Count;
    }

    public MAC_PDU Get(int header)
    {
        lock (_lock)
        {
            if (_cache.ContainsKey(header))
            {
                return _cache[header];
            }
            else
            {
                var macPdu = new MAC_PDU();
                macPdu.Header = header;
                macPdu.Payload = Compress(_array, header);
                macPdu.Trailer = 0;

                _cache[header] = macPdu;
