// Custom memory pool for efficient repeated allocations
struct MemoryPool {
    size_t capacity;
    size_t used;
    void* buffer;
};

// Event metadata structure
struct EventMetadata {
    char* message;
    time_t timestamp;
    size_t payloadSize;
};

// Log data structure
struct LogData {
    struct MemoryPool* pool;
    struct EventMetadata* events;
    size_t numEvents;
    size_t maxEvents;
};

// Initialize log data structure
void initLog(struct LogData* log, size_t maxEvents) {
    log->pool = malloc(sizeof(struct MemoryPool));
    log->events = malloc(maxEvents * sizeof(struct EventMetadata));
    log->numEvents = 0;
    log->maxEvents = maxEvents;
}

// Add new event to the log
void addEvent(struct LogData* log, char* message, size_t payloadSize) {
    // Check if there is enough space in the pool for a new event
    if (log->pool->used + sizeof(struct EventMetadata) > log->pool->capacity) {
        // Reallocate memory pool to accommodate new event
        log->pool = realloc(log->pool, log->pool->capacity * 2);
    }

    // Allocate memory for the new event metadata
    struct EventMetadata* event = (struct EventMetadata*)malloc(sizeof(struct EventMetadata));
    event->message = message;
    event->timestamp = time(NULL);
    event->payloadSize = payloadSize;

    // Add event to the log
    log->events[log->numEvents++] = *event;

    // Update memory pool usage
    log->pool->used += sizeof(struct EventMetadata) + payloadSize;
}

// Retrieve events by timestamp
void getEventsByTimestamp(struct LogData* log, time_t timestamp, size_t* numEvents, struct EventMetadata** events) {
    // Find the first event with a timestamp greater than or equal to the given timestamp
    int i = 0;
    while (i < log->numEvents && log->events[i].timestamp < timestamp) {
        i++;
    }

    // Return the number of events and their metadata
    *numEvents = log->numEvents - i;
    *events = &log->events[i];
}

// Clear the entire log
void clearLog(struct LogData* log) {
    free(log->pool);
    free(log->events);
    initLog(log, log->maxEvents);
}

// Destroy log data structure
void destroyLog(struct LogData* log) {
    free(log->pool);
    free(log->events);
}
