    .entries = NULL,
    .capacity = 0,
    .count = 0
};

// Function to add a new log entry
void add_log_entry(LogEntry* entry) {
    // Check if the cache is full
    if (cache.count == cache.capacity) {
        // If the cache is full, remove the least recently used entry
        LogEntry* lru = cache.entries[0];
        for (size_t i = 1; i < cache.count; i++) {
            if (cache.entries[i]->timestamp < lru->timestamp) {
                lru = cache.entries[i];
            }
        }
        // Remove the LRU entry from the cache
        free(lru);
        memmove(&cache.entries[0], &cache.entries[1], (cache.count - 1) * sizeof(LogEntry*));
        cache.count--;
    }
    // Add the new log entry to the cache
    LogEntry* new_entry = malloc(sizeof(LogEntry));
    memcpy(new_entry, entry, sizeof(LogEntry));
    cache.entries[cache.count++] = new_entry;
}

// Function to retrieve a log entry by timestamp
LogEntry* get_log_entry(time_t timestamp) {
    // Check if the cache is empty
    if (cache.count == 0) {
        return NULL;
    }
    // Search for the log entry in the cache
    LogEntry* entry = NULL;
    for (size_t i = 0; i < cache.count; i++) {
        if (cache.entries[i]->timestamp == timestamp) {
            entry = cache.entries[i];
            break;
        }
    }
    // Return the log entry if found, otherwise return NULL
    return entry;
}

// Function to clear the entire log
void clear_log() {
    // Free all entries in the cache
    for (size_t i = 0; i < cache.count; i++) {
        free(cache.entries[i]);
    }
    // Reset the cache
    cache.count = 0;
}

// Function to export the log as a CSV file
void export_log(char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        return;
    }
    // Write the header row to the file
    fprintf(fp, "Timestamp,Level,Message\n");
    // Iterate over all log entries and write them to the file
    for (size_t i = 0; i < cache.count; i++) {
        LogEntry* entry = cache.entries[i];
        fprintf(fp, "%lu,%d,%s\n", entry->timestamp, entry->level, entry->message);
    }
    // Close the output file
    fclose(fp);
}

// Function to import a CSV file as a log
void import_log(char* filename) {
