using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.XPath;
using System.Threading.Tasks;
using System.IO;
using System.Text;
using System.Diagnostics;

public class XmlParser
{
    private static readonly Dictionary<string, List<XElement>> _cache = new Dictionary<string, List<XElement>>();
    private static readonly object _lock = new object();
    private static readonly TimeSpan _cacheTimeout = TimeSpan.FromMinutes(5);

    public async Task<List<XElement>> ParseXmlAsync(string xml, string xPathQuery, DateTime? startDate = null, DateTime? endDate = null)
    {
        var key = $"{xml}|{xPathQuery}|{startDate?.ToString()}|{endDate?.ToString()}";

        List<XElement> elements;
        lock (_lock)
        {
            if (_cache.TryGetValue(key, out elements))
            {
                return elements;
            }
        }

        try
        {
            using (var reader = new StringReader(xml))
            {
                var document = XDocument.Load(reader);
                var nodes = document.XPathSelectElements(xPathQuery);

                if (startDate != null && endDate != null)
                {
                    nodes = nodes.Where(n => n.Attribute("creationDate") != null && DateTime.Parse(n.Attribute("creationDate").Value).CompareTo(startDate.Value) >= 0 && DateTime.Parse(n.Attribute("creationDate").Value).CompareTo(endDate.Value) <= 0);
                }

                elements = nodes.ToList();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            return new List<XElement>();
        }

        lock (_lock)
        {
            _cache[key] = elements;
        }

        return elements;
    }

    public async Task<List<XElement>> ParseXmlAsync(string xml, string xPathQuery, DateTime? startDate = null, DateTime? endDate = null, bool excludeDeprecated = false)
    {
        var key = $"{xml}|{xPathQuery}|{startDate?.ToString()}|{endDate?.ToString()}|{excludeDeprecated}";

        List<XElement> elements;
        lock (_lock)
        {
            if (_cache.TryGetValue(key, out elements))
            {
                return elements;
            }
        }

        try
        {
            using (var reader = new StringReader(xml))
            {
                var document = XDocument.Load(reader);
                var nodes = document.XPathSelectElements(xPathQuery);

                if (startDate != null && endDate != null)
                {
                    nodes = nodes.Where(n => n.Attribute("creationDate") != null && DateTime.Parse(n.Attribute("creationDate").Value).CompareTo(startDate.Value) >= 0 && DateTime.Parse(n.Attribute("creationDate").Value).CompareTo(endDate.Value) <= 0);
                }

                if (excludeDeprecated)
                {
                    nodes = nodes.Where(n => n.Attribute("deprecated") == null || !bool.Parse(n.Attribute("deprecated").Value));
                }

                elements = nodes.ToList();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            return new List<XElement>();
        }

        lock (_lock)
        {
            _cache[key] = elements;
        }

        return elements;
    }
}
