#include <time.h>

// Structure to hold TCP connection records
typedef struct {
    int id;
    time_t last_activity;
    bool active;
} TCP_CONNECTION_RECORD;

// Function to add a new connection record
void add_connection(TCP_CONNECTION_RECORD *record) {
    // Add the new record to the end of the array
    record->id = ++num_connections;
    record->last_activity = time(NULL);
    record->active = true;
}

// Function to remove a connection record
void remove_connection(int id) {
    // Find the index of the record with the given ID
    int i = 0;
    while (i < num_connections && connections[i].id != id) {
        i++;
    }
    if (i == num_connections) {
        return;
    }
    // Remove the record from the array by shifting all subsequent records back one index
    for (int j = i; j < num_connections - 1; j++) {
        connections[j] = connections[j + 1];
    }
    num_connections--;
}

// Function to lookup a connection record by ID
TCP_CONNECTION_RECORD *lookup_connection(int id) {
    // Find the index of the record with the given ID
    int i = 0;
    while (i < num_connections && connections[i].id != id) {
        i++;
    }
    if (i == num_connections) {
        return NULL;
    }
    // Return a pointer to the record at that index
    return &connections[i];
}

// Function to periodically clean up inactive connections
void cleanup_connections() {
    time_t current_time = time(NULL);
    for (int i = 0; i < num_connections; i++) {
        if (!connections[i].active && current_time - connections[i].last_activity > INACTIVE_TIMEOUT) {
            remove_connection(connections[i].id);
        }
    }
}
