    if (currentTime - lastFunctionCallTime < FUNCTION_CALL_TRACKING_WINDOW) {
        numFunctionCalls++;
    } else {
        numFunctionCalls = 1;
        lastFunctionCallTime = currentTime;
    }

    // Check if the number of function calls exceeds the maximum limit
    if (numFunctionCalls > FUNCTION_CALL_TRACKING_WINDOW) {
        return TOO_FREQUENT_ERROR;
    }

    // Handle potential delays in receiving valid RX_UE_INFORMATION_TAG and RNTI values from an external data source
    for (int i = 0; i < numUsers; i++) {
        if (pduArray[i].RX_UE_INFORMATION_TAG == 0 || pduArray[i].RNTI == 0) {
            // Use the fallback mechanism to receive valid RX_UE_INFORMATION_TAG and RNTI values
            sleep(FALLBACK_MECHANISM);
            pduArray[i].RX_UE_INFORMATION_TAG = rand() % 2;
            pduArray[i].RNTI = rand() % 2;
