#include <pthread.h>

// Define the structure for holding the CRC indication information
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformation;
    RNTI rnti;
    CRCFLAG crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the array to hold the CRC indication information
NFAPI_CRC_INDICATION_PDU_T *crcIndicationArray = NULL;

// Define the mutex for protecting concurrent access to the array
pthread_mutex_t crcIndicationMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to populate the CRC indication array with new information
void populateCrcIndicationArray(RX_UE_INFORMATION_TAG rxUeInformation, RNTI rnti) {
    // Lock the mutex to prevent concurrent access to the array
    pthread_mutex_lock(&crcIndicationMutex);

    // Check if the array needs to be resized
    if (crcIndicationArray == NULL || crcIndicationArray->size >= 10000) {
        // Resize the array if necessary
        NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(crcIndicationArray, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10000);
        if (newArray == NULL) {
            // Handle the error case where memory allocation fails
            pthread_mutex_unlock(&crcIndicationMutex);
            return;
        }
        crcIndicationArray = newArray;
    }

    // Add a new element to the array with the given information
    NFAPI_CRC_INDICATION_PDU_T *newElement = &crcIndicationArray[crcIndicationArray->size++];
    newElement->rxUeInformation = rxUeInformation;
    newElement->rnti = rnti;
    newElement->crcFlag = (CRCFLAG)rand() % 2; // Randomly set the CRCFLAG

    // Unlock the mutex and return
    pthread_mutex_unlock(&crcIndicationMutex);
}

// Function to update the CRC indication array with real-time network conditions
void updateCrcIndicationArray(RX_UE_INFORMATION_TAG rxUeInformation, RNTI rnti) {
    // Lock the mutex to prevent concurrent access to the array
    pthread_mutex_lock(&crcIndicationMutex);

    // Check if the array needs to be resized
    if (crcIndicationArray == NULL || crcIndicationArray->size >= 10000) {
        // Resize the array if necessary
        NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(crcIndicationArray, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10000);
        if (newArray == NULL) {
            // Handle the error case where memory allocation fails
            pthread_mutex_unlock(&crcIndicationMutex);
            return;
        }
        crcIndicationArray = newArray;
    }

    // Update the element in the array with the given information
    for (int i = 0; i < crcIndicationArray->size; i++) {
        if (crcIndicationArray[i].rxUeInformation == rxUeInformation && crcIndicationArray[i].rnti == rnti) {
            // Update the CRCFLAG with the new information
            crcIndicationArray[i].crcFlag = (CRCFLAG)rand() % 2;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&crcIndicationMutex);
