// Define a structure to represent a network session
typedef struct NetworkSession {
    int id;
    bool connected;
    char* user_profile;
} NetworkSession;

// Define a dynamic array to store the network sessions
static NetworkSession** sessions = NULL;
static size_t num_sessions = 0;
static size_t max_sessions = 1000; // maximum number of active sessions

// Function to add a new session to the array
void add_session(int id, bool connected, char* user_profile) {
    if (num_sessions >= max_sessions) {
        printf("Maximum number of active sessions reached. Closing oldest session.\n");
        close_session(0); // close the oldest session
    }
    NetworkSession* new_session = malloc(sizeof(NetworkSession));
    new_session->id = id;
    new_session->connected = connected;
    new_session->user_profile = user_profile;
    sessions[num_sessions++] = new_session;
}

// Function to retrieve a session by its ID
NetworkSession* get_session(int id) {
    for (size_t i = 0; i < num_sessions; i++) {
        if (sessions[i]->id == id) {
            return sessions[i];
        }
    }
    return NULL; // session not found
}

// Function to close a session by its ID
void close_session(int id) {
    NetworkSession* session = get_session(id);
    if (session != NULL) {
        free(session->user_profile);
        free(session);
        sessions[i] = NULL; // mark the session as closed
    }
}

// Function to limit the number of active sessions
void limit_sessions() {
    size_t num_closed = 0;
    for (size_t i = 0; i < num_sessions; i++) {
        if (!sessions[i]->connected) {
            close_session(sessions[i]->id);
            num_closed++;
        }
    }
    printf("Closed %zu sessions to limit the number of active sessions.\n", num_closed);
}

// Function to update a session's connection status and user profile
void update_session(int id, bool connected, char* user_profile) {
    NetworkSession* session = get_session(id);
    if (session != NULL) {
        session->connected = connected;
        free(session->user_profile);
        session->user_profile = user_profile;
    }
}
