void init_connection_pool(connection_pool_t* pool) {
    // Initialize the connection pool with a fixed number of connections
    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        connection_t* conn = malloc(sizeof(connection_t));
        if (!conn) {
            perror("Failed to allocate memory for connection pool");
            exit(1);
        }
        conn->socket = -1;
        conn->ssl = NULL;
        pool->connections[i] = conn;
    }
}

void destroy_connection_pool(connection_pool_t* pool) {
    // Destroy all connections in the pool and free their memory
    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        connection_t* conn = pool->connections[i];
        if (conn->socket != -1) {
            close(conn->socket);
        }
        SSL_free(conn->ssl);
        free(conn);
    }
}

void add_connection_to_pool(connection_pool_t* pool, int socket, SSL* ssl) {
    // Add a new connection to the pool and update its status
    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        if (pool->connections[i]->socket == -1) {
            pool->connections[i]->socket = socket;
            pool->connections[i]->ssl = ssl;
            break;
        }
    }
}

void remove_connection_from_pool(connection_pool_t* pool, int socket) {
    // Remove a connection from the pool and update its status
    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        if (pool->connections[i]->socket == socket) {
            pool->connections[i]->socket = -1;
            SSL_free(pool->connections[i]->ssl);
            break;
        }
    }
}

void handle_request(connection_t* conn, request_t* req) {
