    char *token = strtok(rule_str, ",");
    while (token != NULL) {
        rules = realloc(rules, (num_rules + 1) * sizeof(rule_t));
        rules[num_rules].rule = token;
        rules[num_rules].threshold = atoi(token);
        num_rules++;
        token = strtok(NULL, ",");
    }

    // Initialize the random number generator and its range
    srand(time(NULL));
    int rand_max = 100;

    // Initialize the auxiliary array for storing offsets
    long *offsets = malloc(num_records * sizeof(long));

    // Iterate over each record and apply the transformation rules
    for (int i = 0; i < num_records; i++) {
        // Check if the record is valid and skip it if not
        if (records[i].key <= 0 || records[i].offset <= 0) continue;

        // Generate a random number within the range of the input data distribution
        int rand_num = rand() % rand_max + 1;

        // Check if the random number is less than the threshold and skip the record if not
        if (rand_num < threshold) continue;

        // Apply the transformation rules to the current record
        for (int j = 0; j < num_rules; j++) {
            char *rule = rules[j].rule;
            int threshold = rules[j].threshold;
            if (strcmp(rule, "add") == 0) {
                records[i].offset += threshold;
            } else if (strcmp(rule, "subtract") == 0) {
                records[i].offset -= threshold;
            } else if (strcmp(rule, "multiply") == 0) {
                records[i].offset *= threshold;
            } else if (strcmp(rule, "divide") == 0) {
                records[i].offset /= threshold;
            }
        }
    }

    // Write the transformed records to the output file
    for (int i = 0; i < num_records; i++) {
        fprintf(output, "%d %ld\n", records[i].key, records[i].offset);
    }

    // Log any errors encountered during processing
    if (ferror(input) || ferror(output)) {
        printf("Error: unable to write to output file %s\n", output_filename);
    }

    // Free the memory allocated for the records and rules arrays
    free(records);
    free(rules);

    // Return a pointer to the first element of the record array
    return records;
}
```
