// Define the structure for a log entry
typedef struct {
    uint64_t timestamp;
    int log_level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the structure for the log array
typedef struct {
    ModemLogEntry* entries[MAX_LOG_SIZE];
    int num_entries;
} LogArray;

// Function to add a new entry to the log array
void add_log_entry(LogArray* log, uint64_t timestamp, int log_level, char* message) {
    // Check if the log array is full
    if (log->num_entries == MAX_LOG_SIZE) {
        // If it is, purge old entries to make room for the new one
        purge_old_entries(log);
    }

    // Add the new entry to the end of the log array
    ModemLogEntry* new_entry = malloc(sizeof(ModemLogEntry));
    new_entry->timestamp = timestamp;
    new_entry->log_level = log_level;
    new_entry->message = strdup(message);
    log->entries[log->num_entries++] = new_entry;
}

// Function to retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(LogArray* log, uint64_t timestamp) {
    // Iterate through the log array until we find an entry with the specified timestamp
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i]->timestamp == timestamp) {
            return log->entries[i];
        }
    }

    // If no entry was found, return NULL
    return NULL;
}

// Function to clear the entire log array
void clear_log(LogArray* log) {
    for (int i = 0; i < log->num_entries; i++) {
        free(log->entries[i]);
    }
    log->num_entries = 0;
}

// Function to purge old entries from the log array
void purge_old_entries(LogArray* log) {
    // Iterate through the log array and remove any entries that are older than the specified duration
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i]->timestamp < time(NULL) - MAX_LOG_DURATION) {
            free(log->entries[i]);
            log->num_entries--;
            i--;
        }
    }
}

// Function to filter logs based on a specified log level
void filter_logs(LogArray* log, int log_level) {
    // Iterate through the log array and remove any entries that do not match the specified log level
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i]->log_level != log_level) {
            free(log->entries[i]);
            log->num_entries--;
            i--;
        }
    }
}

// Function to export the log entries to a file in a standardized format
void export_logs(LogArray* log, char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: unable to open output file\n");
        return;
    }

    // Iterate through the log array and write each entry to the output file
    for (int i = 0; i < log->num_entries; i++) {
        fprintf(fp, "%lu %d %s\n", log->entries[i]->timestamp, log->entries[i]->log_level, log->entries[i]->message);
    }

    // Close the output file
    fclose(fp);
}
