void log_message(const char *tag, int level, const char *format, ...) {
    // Check if the logging level is enabled
    if (level > LOG_LEVEL) {
        return;
    }

    // Format the message using variable arguments
    va_list args;
    va_start(args, format);
    char *message = malloc(strlen(format) + 1);
    vsprintf(message, format, args);
    va_end(args);

    // Log the message to the error log
    fprintf(stderr, "%s: %s\n", tag, message);

    // Free the memory allocated for the formatted message
    free(message);
}
