void process_file(const char* filepath) {
    // Open the file for reading
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error opening file %s\n", filepath);
        return;
    }

    // Initialize a hash object to compute the MD5 hash of the file contents
    hashlib_md5_t* md5 = hashlib_md5_new();

    // Allocate memory for the records in chunks to reduce fragmentation and optimize allocation speed
    const int chunk_size = 1024;
    struct record* records = (struct record*)malloc(chunk_size * sizeof(struct record));

    // Initialize a cache for user IDs to minimize network requests and improve performance
    char** user_ids = (char**)malloc(sizeof(char*) * chunk_size);
    int num_user_ids = 0;

    // Mutex to synchronize access to the cache and records arrays
    std::mutex mtx;

    // Read the file in chunks and update the hash using the md5 object
    while (!feof(fp)) {
        char buffer[chunk_size];
        size_t bytes_read = fread(buffer, 1, chunk_size, fp);
        if (bytes_read > 0) {
            // Update the hash with the read data
            hashlib_md5_update(md5, buffer, bytes_read);

            // Allocate memory for the records in this chunk
            for (int i = 0; i < bytes_read; i++) {
                struct record* rec = &records[i];
                rec->offset = ftell(fp) - bytes_read + i;
                rec->key = buffer[i];

                // Check if the user ID is already in the cache, otherwise allocate memory for it
                char* user_id = NULL;
                {
                    std::lock_guard<std::mutex> lock(mtx);
                    for (int j = 0; j < num_user_ids; j++) {
                        if (strcmp(buffer[i], user_ids[j]) == 0) {
                            user_id = user_ids[j];
                            break;
                        }
                    }
                }
                if (user_id == NULL) {
                    // Allocate memory for the user ID and add it to the cache
                    user_id = (char*)malloc(strlen(buffer[i]) + 1);
                    strcpy(user_id, buffer[i]);
                    {
                        std::lock_guard<std::mutex> lock(mtx);
                        user_ids[num_user_ids++] = user_id;
                    }
                }
                rec->user_id = user_id;
            }
        }
    }

    // Compute the hexdigest of the hash and return it
    char* hexdigest = (char*)malloc(hashlib_md5_hexdigest_size(md5));
    hashlib_md5_hexdigest(md5, hexdigest);
    printf("Hexdigest: %s\n", hexdigest);

    // Clean up resources
    free(records);
    free(user_ids);
    hashlib_md5_free(md5);
    fclose(fp);
}
```
