        pthread_mutex_unlock(&wq->mutex);
        return NULL;
    }

    // Decrement the number of tasks
    wq->num_tasks--;

    // Copy the first task from the task array to the output parameter
    memcpy(t, &wq->tasks[0], sizeof(task));

    // Shift all remaining tasks in the task array down by one position
    for (int i = 1; i < wq->num_tasks; i++) {
        memcpy(&wq->tasks[i - 1], &wq->tasks[i], sizeof(task));
    }

    // Release the mutex for the work queue
    pthread_mutex_unlock(&wq->mutex);

