// Retry a failed task execution with exponential backoff
void retry_task(struct wq_manager* wq, task* t) {
    // Acquire the mutex for the work queue
    pthread_mutex_lock(&wq->mutex);

    // Check if there are any tasks in the work queue
    if (wq->num_tasks == 0) {
