// Define the fallback mechanism for logging to an external service
#define EXTERNAL_SERVICE_URL "https://example.com/log"

void log(int level, const char *format, ...) {
    // Check if the logging level is enabled
    if (level > LOG_DEBUG) {
        return;
    }

    // Allocate memory for the formatted message
    va_list args;
    va_start(args, format);
    char *message = malloc(MAX_LOG_LENGTH);
    vsnprintf(message, MAX_LOG_LENGTH, format, args);
    va_end(args);

    // Log the message to the error log
    FILE *logfile = fopen("error.log", "a");
    if (logfile == NULL) {
        // Fallback mechanism: log to an external service if the local file is unavailable
        char *url = malloc(strlen(EXTERNAL_SERVICE_URL) + strlen(message));
        sprintf(url, "%s%s", EXTERNAL_SERVICE_URL, message);
        free(message);
        message = url;
    }
    fputs(message, logfile);
    fclose(logfile);

    // Free the memory allocated for the formatted message
    free(message);
}
