// Define the logging levels
#define LOG_DEBUG 0
#define LOG_INFO 1
#define LOG_WARNING 2
#define LOG_ERROR 3
#define LOG_CRITICAL 4

// Define the maximum size of a log entry
#define MAX_LOG_ENTRY_SIZE 1024

// Define the logging buffer size
#define LOGGING_BUFFER_SIZE 1024

// Define the tag system for selective error logging
#define TAG_SYSTEM_SIZE 16

// Define the logging verbosity level
static int logging_verbosity = LOG_INFO;

// Define the logging buffer
static char logging_buffer[LOGGING_BUFFER_SIZE];

// Define the tag system for selective error logging
static char* tags[TAG_SYSTEM_SIZE] = {NULL};

// Define the mutex for thread-safe logging
static pthread_mutex_t logging_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_condition_error(int condition, const char* format, ...) {
    // Check if the condition is true and the current verbosity level allows for error logging
    if (condition && logging_verbosity >= LOG_ERROR) {
        // Acquire the mutex to prevent race conditions
        pthread_mutex_lock(&logging_mutex);

        // Get the current time in milliseconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long long ms = (long long)ts.tv_sec * 1000 + (long long)ts.tv_nsec / 1000000;

        // Format the log message using snprintf
        va_list args;
        va_start(args, format);
        int len = vsnprintf(logging_buffer, MAX_LOG_ENTRY_SIZE, format, args);
        va_end(args);

        // Add the timestamp and logging level to the log message
        char* log_entry = (char*)malloc(len + 32);
        sprintf(log_entry, "[%lld] [ERROR] %s", ms, logging_buffer);

        // Log the error using an external logging system
        // ...

        // Release the mutex to allow other threads to log messages
        pthread_mutex_unlock(&logging_mutex);
    }
}

void set_logging_verbosity(int verbosity) {
    // Set the new logging verbosity level
    logging_verbosity = verbosity;
}

void add_tag(const char* tag) {
    // Add a new tag to the tag system
    tags[TAG_SYSTEM_SIZE - 1] = (char*)malloc(strlen(tag) + 1);
    strcpy(tags[TAG_SYSTEM_SIZE - 1], tag);
}

void remove_tag(const char* tag) {
    // Remove a tag from the tag system
    for (int i = 0; i < TAG_SYSTEM_SIZE; i++) {
        if (tags[i] && strcmp(tags[i], tag) == 0) {
            free(tags[i]);
            tags[i] = NULL;
            break;
        }
    }
}
