// Function to add a new trace entry to the log
void add_trace(NetworkTrace* trace) {
    // Acquire the lock for the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Check if the trace log is full
    if (trace_log.size >= TRACE_LOG_MAX_SIZE) {
        // Archive old traces based on the retention policy
        archive_traces();
    }

    // Add the new trace entry to the log
    trace_log.push(trace);

    // Release the lock for the trace log
    pthread_mutex_unlock(&trace_log_lock);
}

// Function to retrieve traces by timestamp or IP address
void get_traces(uint64_t timestamp, char* ip_address) {
    // Acquire the lock for the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Iterate over the trace entries in the log
    for (int i = 0; i < trace_log.size; i++) {
