        }
    }

    // Release the lock for the trace log
    pthread_mutex_unlock(&trace_log_lock);
}

// Function to clear the entire trace log
void clear_traces() {
    // Acquire the lock for the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Clear the trace log
    trace_log.clear();

    // Release the lock for the trace log
    pthread_mutex_unlock(&trace_log_lock);
}

// Function to archive old traces based on the retention policy
void archive_traces() {
    // Acquire the lock for the trace log
    pthread_mutex_lock(&trace_log_lock);

    // Iterate over the trace entries in the log
    for (int i = 0; i < trace_log.size; i++) {
        NetworkTrace* trace = trace_log[i];

        // Check if the trace entry is older than the retention policy
        if (trace->timestamp <= get_retention_policy()) {
            // Archive the trace entry
