#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the log entry structure
typedef struct {
    time_t timestamp;
    int level;
    char message[];
} ModemLogEntry;

// Define the logging framework structure
typedef struct {
    pthread_mutex_t mutex; // Mutex for thread safety
    ModemLogEntry *entries; // Array of log entries
    size_t capacity; // Capacity of the log array
    size_t count; // Number of log entries in the array
} LogFramework;

// Define the logging rate limiter structure
typedef struct {
    pthread_mutex_t mutex; // Mutex for thread safety
    int limit; // Maximum number of logs per second
    time_t last_logged; // Timestamp of the last logged log
} LogRateLimiter;

// Define the logging configuration structure
typedef struct {
    size_t max_size; // Maximum size of the log array
    int max_duration; // Maximum duration of logs to keep (in seconds)
    int purge_frequency; // Frequency of purging old logs (in seconds)
} LogConfiguration;

// Define the logging function
void log(LogFramework *framework, const char *message, int level) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&framework->mutex);

    // Check if the log size is exceeded
    if (framework->count >= framework->capacity) {
        // Purge old logs if necessary
        purgeOldLogs(framework, framework->max_duration);
    }

    // Add the new log entry
    ModemLogEntry *entry = &framework->entries[framework->count++];
    entry->timestamp = time(NULL);
    entry->level = level;
    strcpy(entry->message, message);

    // Release the mutex
    pthread_mutex_unlock(&framework->mutex);
}

// Define the purgeOldLogs function
void purgeOldLogs(LogFramework *framework, int max_duration) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&framework->mutex);

    // Iterate over the log entries and remove those older than the maximum duration
    size_t i = 0;
    while (i < framework->count) {
        ModemLogEntry *entry = &framework->entries[i];
        if (difftime(time(NULL), entry->timestamp) > max_duration) {
            // Remove the log entry and shift the remaining entries
            memmove(&framework->entries[i], &framework->entries[i + 1], (framework->count - i - 1) * sizeof(ModemLogEntry));
            framework->count--;
        } else {
            i++;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&framework->mutex);
}

// Define the compactLogs function
void compactLogs(LogFramework *framework) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&framework->mutex);

    // Iterate over the log entries and remove any gaps in the array
    size_t i = 0;
    while (i < framework->count) {
        ModemLogEntry *entry = &framework->entries[i];
        if (entry == NULL) {
            // Remove the gap and shift the remaining entries
            memmove(&framework->entries[i], &framework->entries[i + 1], (framework->count - i - 1) * sizeof(ModemLogEntry));
            framework->count--;
        } else {
            i++;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&framework->mutex);
}

// Define the exportLogs function
void exportLogs(LogFramework *framework, const char *filename) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&framework->mutex);

    // Open the file for writing
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Iterate over the log entries and write them to the file
    size_t i = 0;
    while (i < framework->count) {
        ModemLogEntry *entry = &framework->entries[i];
        fprintf(file, "%lu %d %s\n", entry->timestamp, entry->level, entry->message);
        i++;
    }

    // Close the file
    fclose(file);

    // Release the mutex
    pthread_mutex_unlock(&framework->mutex);
}
