// Function to initialize a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *nfapi_crc_indication_list_init(size_t max_num_pdus) {
    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for CRC indication list\n");
        return NULL;
    }

    // Initialize the list with a maximum number of PDUs
    list->max_num_pdus = max_num_pdus;
    list->num_pdus = 0;
    list->pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_num_pdus);
    if (!list->pdu_list) {
        fprintf(stderr, "Failed to allocate memory for CRC indication PDU list\n");
        free(list);
        return NULL;
    }

    // Initialize each PDU with a random CRCFLAG value
    for (size_t i = 0; i < max_num_pdus; i++) {
        list->pdu_list[i].crcflag = rand() % 256;
    }

    return list;
}

// Function to add a new PDU to the list
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if the list is full
    if (list->num_pdus == list->max_num_pdus) {
        fprintf(stderr, "CRC indication list is full\n");
        return NULL;
    }

    // Allocate memory for the new PDU
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Failed to allocate memory for CRC indication PDU\n");
        return NULL;
    }

    // Initialize the new PDU with a random CRCFLAG value
    pdu->crcflag = rand() % 256;

    // Add the new PDU to the list
    list->pdu_list[list->num_pdus++] = *pdu;

    return pdu;
}

// Function to get the first element in the list
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_list_first(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list->num_pdus == 0) {
        return NULL;
    }

    return &list->pdu_list[0];
}

// Function to get the next element in the list
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_list_next(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (list->num_pdus == 0 || pdu >= &list->pdu_list[list->num_pdus - 1]) {
        return NULL;
    }

    return pdu + 1;
}
