    log.num_entries++;

    // Release the logging mutex
    pthread_mutex_unlock(&logging_mutex);
}

// Retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(time_t timestamp) {
    // Acquire the logging mutex
    pthread_mutex_lock(&logging_mutex);

    // Iterate through the log entries and find the matching timestamp
    for (int i = 0; i < log.num_entries; i++) {
        if (log.entries[i].timestamp == timestamp) {
            ModemLogEntry* entry = &log.entries[i];
            pthread_mutex_unlock(&logging_mutex);
            return entry;
        }
    }

    // Release the logging mutex
    pthread_mutex_unlock(&logging_mutex);

    // Return NULL if no matching timestamp is found
    return NULL;
}

// Clear the entire log
void clear_log() {
    // Acquire the logging mutex
    pthread_mutex_lock(&logging_mutex);

    // Reset the log entries and num_entries
    log.num_entries = 0;

    // Release the logging mutex
    pthread_mutex_unlock(&logging_mutex);
}

// Purge old entries from the log
void purge_old_entries() {
    // Acquire the logging mutex
    pthread_mutex_lock(&logging_mutex);

    // Iterate through the log entries and find the oldest entry
    time_t oldest_timestamp = 0;
    for (int i = 0; i < log.num_entries; i++) {
        if (log.entries[i].timestamp < oldest_timestamp || oldest_timestamp == 0) {
            oldest_timestamp = log.entries[i].timestamp;
        }
    }

    // Remove the oldest entry from the log
    for (int i = 0; i < log.num_entries; i++) {
        if (log.entries[i].timestamp == oldest_timestamp) {
            memmove(&log.entries[i], &log.entries[i + 1], sizeof(ModemLogEntry) * (log.num_entries - i - 1));
            log.num_entries--;
        }
    }

    // Release the logging mutex
    pthread_mutex_unlock(&logging_mutex);
}

// Compact the log structure
void compact_log() {
    // Acquire the logging mutex
    pthread_mutex_lock(&logging_mutex);

    // Iterate through the log entries and remove any empty slots
    for (int i = 0; i < log.num_entries; i++) {
        if (log.entries[i].message == NULL) {
            memmove(&log.entries[i], &log.entries[i + 1], sizeof(ModemLogEntry) * (log.num_entries - i - 1));
            log.num_entries--;
        }
    }

    // Release the logging mutex
    pthread_mutex_unlock(&logging_mutex);
}

// Export the log entries to a file in a standardized format
void export_log(char* filename) {
    // Acquire the logging mutex
    pthread_mutex_lock(&logging_mutex);

    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Iterate through the log entries and write them to the file
    for (int i = 0; i < log.num_entries; i++) {
        fprintf(fp, "%lu %d %s\n", log.entries[i].timestamp, log.entries[i].level, log.entries[i].message);
    }

    // Close the output file
    fclose(fp);

    // Release the logging mutex
    pthread_mutex_unlock(&logging_mutex);
}

// Filter the log entries based on a specified log level
void filter_log(int level) {
    // Acquire the logging mutex
    pthread_mutex_lock(&logging_mutex);

    // Iterate through the log entries and remove any that do not match the specified level
    for (int i = 0; i < log.num_entries; i++) {
        if (log.entries[i].level != level) {
            memmove(&log.entries[i], &log.entries[i + 1], sizeof(ModemLogEntry) * (log.num_entries - i - 1));
            log.num_entries--;
        }
    }

    // Release the logging mutex
    pthread_mutex_unlock(&logging_mutex);
}

// Initialize the logging system
void init_logging() {
    // Create a new thread for logging
    pthread_create(&logging_thread, NULL, &log_loop, NULL);
}

// Logging loop function
void* log_loop(void* arg) {
    while (1) {
        // Acquire the logging mutex
        pthread_mutex_lock(&logging_mutex);

        // Check if there are any new log entries to process
        if (log.num_entries > 0) {
            // Process the new log entries
            for (int i = 0; i < log.num_entries; i++) {
                // Write the log entry to the console
                printf("%lu %d %s\n", log.entries[i].timestamp, log.entries[i].level, log.entries[i].message);
            }

            // Clear the log entries
            clear_log();
        }

        // Release the logging mutex
        pthread_mutex_unlock(&logging_mutex);

        // Sleep for a short period of time to avoid overwhelming the system with too many log requests
        sleep(LOGGING_RATE_LIMIT);
    }
}

// Gracefully handle scenarios where external logging services or databases are unavailable
void handle_external_logging() {
    // Check if an external logging service is available
    if (external_logging_service_available()) {
        // Use the external logging service to log messages
        external_log(message);
    } else {
        // Log messages locally if the external logging service is not available
        add_log_entry(timestamp, level, message);
    }
}

// Optimize for both memory and CPU usage by using asynchronous I/O for exporting logs to files
void optimize_for_performance() {
    // Use asynchronous I/O for exporting logs to files
    async_export_log(filename);
}

// Implement a logging rate limiter to prevent overwhelming the system with too many log requests
void implement_logging_rate_limiter() {
    // Set the maximum number of log entries that can be added per second
    set_max_log_entries(LOGGING_RATE_LIMIT);
}

// Determine the optimal frequency for purging old entries and compacting the log, balancing between resource consumption and log integrity
void determine_purge_frequency() {
    // Set the purge frequency to 60 seconds
    set_purge_frequency(LOG_PURGE_FREQUENCY);
}

// Ensure that the function is robust enough to handle simultaneous log additions from multiple clients, possibly under heavy network load
void ensure_robustness() {
    // Use a lock-free data structure for the log entries
    use_lock_free_data_structure();
}

// Integrate support for multi-tenant environments, where each tenant has its own isolated log storage and filtering rules
void integrate_multi_tenancy() {
    // Create a new log structure for each tenant
    create_log_for_tenant(tenant);
}

// Implement a mechanism to allow administrators to configure custom retention policies per tenant
void implement_custom_retention_policies() {
    // Allow administrators to configure custom retention policies for each tenant
    set_retention_policy_for_tenant(tenant, policy);
}

// Design the function to handle potential network partitions, ensuring that logs are not lost and can be recovered if a server goes down
void design_network_partition_handling() {
    // Use a distributed log system with redundancy and failover mechanisms
    use_distributed_log_system();
}

// Implement a robust error recovery mechanism that can handle transient failures, such as temporary unavailability of the database or file system
void implement_error_recovery() {
    // Use a retry mechanism with exponential backoff to handle transient failures
    use_retry_mechanism();
}

// Design the function to be easily extensible, allowing for future enhancements without significant refactoring
void design_extensibility() {
    // Use a modular architecture with clear interfaces and separation of concerns
    use_modular_architecture();
}

// Provide clear documentation and unit tests to aid in maintenance
void provide_documentation_and_tests() {
    // Write detailed documentation for the function and its components
    write_documentation();

    // Write unit tests for the function and its components
    write_unit_tests();
}
