// Define the maximum size of the log entries
#define MAX_LOG_ENTRIES 1024

// Define the maximum size of a single log entry
#define MAX_LOG_ENTRY_SIZE 512

// Define the logging levels
typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARN,
    LOG_LEVEL_ERROR,
} LogLevel;

// Define the log entry structure
typedef struct {
    time_t timestamp;
    LogLevel level;
    char message[MAX_LOG_ENTRY_SIZE];
} ModemLogEntry;

// Define the primary and secondary logs
ModemLogEntry* primary_log = NULL;
ModemLogEntry* secondary_log = NULL;
size_t primary_log_size = 0;
size_t secondary_log_size = 0;

// Define the logging level filter
LogLevel log_level_filter = LOG_LEVEL_DEBUG;

// Function to add a new entry to the log
void add_entry(ModemLogEntry* entry) {
    // Check if the primary log is full
    if (primary_log_size >= MAX_LOG_ENTRIES) {
        // If the primary log is full, move the oldest entries to the secondary log
        for (int i = 0; i < primary_log_size; i++) {
            ModemLogEntry* entry = &primary_log[i];
            if (entry->timestamp <= time(NULL) - MAX_LOG_ENTRY_SIZE) {
                // Add the entry to the secondary log
                add_secondary_entry(entry);
                // Remove the entry from the primary log
                remove_primary_entry(entry);
            }
        }
    }

    // Check if the logging level filter is enabled
    if (log_level_filter != LOG_LEVEL_DEBUG) {
        // If the logging level filter is enabled, check if the entry's level is below the filter level
        if (entry->level < log_level_filter) {
            return;
        }
    }

    // Add the entry to the primary log
    add_primary_entry(entry);
}

// Function to retrieve an entry from the log by timestamp
ModemLogEntry* get_entry(time_t timestamp) {
    for (int i = 0; i < primary_log_size; i++) {
        ModemLogEntry* entry = &primary_log[i];
        if (entry->timestamp == timestamp) {
            return entry;
        }
    }
    return NULL;
}

// Function to clear the entire log
void clear_log() {
    // Free the memory allocated for the primary and secondary logs
    free(primary_log);
    free(secondary_log);

    // Reset the log sizes to 0
    primary_log_size = 0;
    secondary_log_size = 0;
}

// Function to set the logging level filter
void set_logging_level_filter(LogLevel level) {
    log_level_filter = level;
}

// Function to add an entry to the primary log
void add_primary_entry(ModemLogEntry* entry) {
    // Check if the primary log is full
    if (primary_log_size >= MAX_LOG_ENTRIES) {
        return;
    }

    // Add the entry to the primary log
    primary_log[primary_log_size++] = *entry;
}

// Function to add an entry to the secondary log
void add_secondary_entry(ModemLogEntry* entry) {
    // Check if the secondary log is full
    if (secondary_log_size >= MAX_LOG_ENTRIES) {
        return;
    }

    // Add the entry to the secondary log
    secondary_log[secondary_log_size++] = *entry;
}

// Function to remove an entry from the primary log
void remove_primary_entry(ModemLogEntry* entry) {
    for (int i = 0; i < primary_log_size; i++) {
        ModemLogEntry* current_entry = &primary_log[i];
        if (current_entry == entry) {
            // Remove the entry from the primary log
            memmove(&primary_log[i], &primary_log[i + 1], sizeof(ModemLogEntry) * (primary_log_size - i));
            primary_log_size--;
            return;
        }
    }
}
