// Define the primary cache size and secondary buffer size
#define PRIMARY_CACHE_SIZE 1000
#define SECONDARY_BUFFER_SIZE 10000

// Define the tertiary archive size
#define TERTIARY_ARCHIVE_SIZE 100000

// Define the structure for the data storage
typedef struct {
    SensorDataPoint* primary_cache;
    SensorDataPoint* secondary_buffer;
    SensorDataPoint* tertiary_archive;
} DataStorage;

// Define the function to add a new data point
void add_data_point(SensorDataPoint* data_point) {
    // Check if the primary cache is full, and flush it if necessary
    if (primary_cache->size == PRIMARY_CACHE_SIZE) {
        flush_primary_cache();
    }

    // Add the new data point to the primary cache
    primary_cache[primary_cache->size++] = *data_point;
}

// Define the function to retrieve data points by sensor ID and timestamp range
void retrieve_data_points(int sensor_id, uint64_t start_timestamp, uint64_t end_timestamp) {
    // Check if the primary cache contains the requested data points
    for (int i = 0; i < primary_cache->size; i++) {
        if (primary_cache[i].sensor_id == sensor_id && primary_cache[i].timestamp >= start_timestamp && primary_cache[i].timestamp <= end_timestamp) {
            printf("Data point found in the primary cache: %d, %lu, %f\n", primary_cache[i].sensor_id, primary_cache[i].timestamp, primary_cache[i].measurement_value);
        }
    }

    // Check if the secondary buffer contains the requested data points
    for (int i = 0; i < secondary_buffer->size; i++) {
        if (secondary_buffer[i].sensor_id == sensor_id && secondary_buffer[i].timestamp >= start_timestamp && secondary_buffer[i].timestamp <= end_timestamp) {
            printf("Data point found in the secondary buffer: %d, %lu, %f\n", secondary_buffer[i].sensor_id, secondary_buffer[i].timestamp, secondary_buffer[i].measurement_value);
        }
    }

    // Check if the tertiary archive contains the requested data points
    for (int i = 0; i < tertiary_archive->size; i++) {
        if (tertiary_archive[i].sensor_id == sensor_id && tertiary_archive[i].timestamp >= start_timestamp && tertiary_archive[i].timestamp <= end_timestamp) {
            printf("Data point found in the tertiary archive: %d, %lu, %f\n", tertiary_archive[i].sensor_id, tertiary_archive[i].timestamp, tertiary_archive[i].measurement_value);
        }
    }
}

// Define the function to clear the entire dataset
void clear_dataset() {
    // Clear the primary cache
    primary_cache->size = 0;

    // Clear the secondary buffer
    secondary_buffer->size = 0;

    // Clear the tertiary archive
    tertiary_archive->size = 0;
}

// Define the function to filter and sort data points based on measurement value, sensor type, and time intervals
void filter_and_sort(int sensor_type, uint64_t start_timestamp, uint64_t end_timestamp) {
    // Check if the primary cache contains the requested data points
    for (int i = 0; i < primary_cache->size; i++) {
        if (primary_cache[i].sensor_type == sensor_type && primary_cache[i].timestamp >= start_timestamp && primary_cache[i].timestamp <= end_timestamp) {
            printf("Data point found in the primary cache: %d, %lu, %f\n", primary_cache[i].sensor_id, primary_cache[i].timestamp, primary_cache[i].measurement_value);
        }
    }

    // Check if the secondary buffer contains the requested data points
    for (int i = 0; i < secondary_buffer->size; i++) {
        if (secondary_buffer[i].sensor_type == sensor_type && secondary_buffer[i].timestamp >= start_timestamp && secondary_buffer[i].timestamp <= end_timestamp) {
            printf("Data point found in the secondary buffer: %d, %lu, %f\n", secondary_buffer[i].sensor_id, secondary_buffer[i].timestamp, secondary_buffer[i].measurement_value);
        }
    }

    // Check if the tertiary archive contains the requested data points
    for (int i = 0; i < tertiary_archive->size; i++) {
        if (tertiary_archive[i].sensor_type == sensor_type && tertiary_archive[i].timestamp >= start_timestamp && tertiary_archive[i].timestamp <= end_timestamp) {
            printf("Data point found in the tertiary archive: %d, %lu, %f\n", tertiary_archive[i].sensor_id, tertiary_archive[i].timestamp, tertiary_archive[i].measurement_value);
        }
