}

// Define the function to flush the primary cache to the secondary buffer
void flush_primary_cache() {
    // Check if the secondary buffer is full, and flush it if necessary
    if (secondary_buffer->size == SECONDARY_BUFFER_SIZE) {
        flush_secondary_buffer();
    }

    // Copy the data points from the primary cache to the secondary buffer
    for (int i = 0; i < primary_cache->size; i++) {
        secondary_buffer[secondary_buffer->size++] = primary_cache[i];
    }

    // Clear the primary cache
    primary_cache->size = 0;
}

// Define the function to flush the secondary buffer to the tertiary archive
void flush_secondary_buffer() {
