    NetworkSession* session = NULL;
    for (int i = 0; i < MAX_SESSIONS_SIZE; i++) {
        if (sessions[i] != NULL && strcmp(sessions[i]->ip_address, ip_address) == 0) {
            session = sessions[i];
            break;
        }
    }

    // Release the mutex for protecting the shared data structure
    pthread_mutex_unlock(&session_mutex);

    return session;
}

// Define the function to clear all sessions
void clear_sessions() {
    // Acquire the mutex for protecting the shared data structure
    pthread_mutex_lock(&session_mutex);

    // Clear the dynamic array and set all sessions to NULL
    memset(sessions, 0, sizeof(NetworkSession*) * MAX_SESSIONS_SIZE);

    // Release the mutex for protecting the shared data structure
    pthread_mutex_unlock(&session_mutex);
}

// Define the function to purge inactive sessions
void purge_inactive_sessions() {
    // Acquire the mutex for protecting the shared data structure
    pthread_mutex_lock(&session_mutex);

    // Iterate through the dynamic array and find all inactive sessions
    int num_inactive_sessions = 0;
    for (int i = 0; i < MAX_SESSIONS_SIZE; i++) {
        if (sessions[i] != NULL && sessions[i]->end_time == 0) {
            num_inactive_sessions++;
        }
    }

    // If there are inactive sessions, purge them and set their pointers to NULL
    if (num_inactive_sessions > 0) {
        for (int i = 0; i < MAX_SESSIONS_SIZE; i++) {
            if (sessions[i] != NULL && sessions[i]->end_time == 0) {
                free(sessions[i]);
                sessions[i] = NULL;
            }
        }
    }

    // Release the mutex for protecting the shared data structure
    pthread_mutex_unlock(&session_mutex);
}

// Define the function to compact session structures
void compact_sessions() {
    // Acquire the mutex for protecting the shared data structure
    pthread_mutex_lock(&session_mutex);

    // Iterate through the dynamic array and find all NULL pointers
    int num_null_pointers = 0;
    for (int i = 0; i < MAX_SESSIONS_SIZE; i++) {
        if (sessions[i] == NULL) {
            num_null_pointers++;
        }
    }

    // If there are NULL pointers, compact the session structures by shifting them down
    if (num_null_pointers > 0) {
        for (int i = 0; i < MAX_SESSIONS_SIZE - num_null_pointers; i++) {
            if (sessions[i] == NULL) {
                sessions[i] = sessions[i + 1];
                sessions[i + 1] = NULL;
            }
        }
    }

    // Release the mutex for protecting the shared data structure
    pthread_mutex_unlock(&session_mutex);
}

// Define the function to export session information to a file in a standardized format
void export_sessions(char* filename) {
    // Acquire the mutex for protecting the shared data structure
    pthread_mutex_lock(&session_mutex);

    // Open the output file and write the header line
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("fopen");
        return;
    }
    fprintf(fp, "Session ID,Start Time,End Time,IP Address,User Agent\n");

    // Iterate through the dynamic array and write each session to the output file
    for (int i = 0; i < MAX_SESSIONS_SIZE; i++) {
        if (sessions[i] != NULL) {
            fprintf(fp, "%d,%ld,%ld,%s,%s\n", sessions[i]->id, sessions[i]->start_time, sessions[i]->end_time, sessions[i]->ip_address, sessions[i]->user_agent);
        }
    }

    // Close the output file and release the mutex for protecting the shared data structure
    fclose(fp);
    pthread_mutex_unlock(&session_mutex);
}
