    pthread_mutex_unlock(&log_array_mutex);
}

// Retrieve entries from the log array based on a specified timestamp
ModemLogEntry* retrieve_entries(time_t timestamp) {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_array_mutex);

    // Find the first entry with a timestamp greater than or equal to the specified timestamp
    ModemLogEntry* entry = NULL;
    for (size_t i = 0; i < log_array_size; i++) {
        if (log_array[i].timestamp >= timestamp) {
            entry = &log_array[i];
            break;
        }
    }

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_array_mutex);

    return entry;
}

// Clear the entire log array
void clear_log() {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_array_mutex);

    // Reset the log array size
    log_array_size = 0;

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_array_mutex);
}

// Purge old entries from the log array
void purge_old_entries() {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_array_mutex);

    // Find the first entry that is older than the specified duration
    time_t oldest_timestamp = 0;
    for (size_t i = 0; i < log_array_size; i++) {
        if (log_array[i].timestamp < oldest_timestamp) {
            oldest_timestamp = log_array[i].timestamp;
        }
    }

    // Remove all entries older than the specified duration
    for (size_t i = 0; i < log_array_size; i++) {
        if (log_array[i].timestamp < oldest_timestamp) {
            memmove(&log_array[i], &log_array[i + 1], sizeof(ModemLogEntry) * (log_array_size - i));
            log_array_size--;
            i--;
        }
    }

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_array_mutex);
}

// Compact the log structure by removing unused memory
void compact_log() {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_array_mutex);

    // Find the first entry that is not used
    size_t i = 0;
    while (i < log_array_size && log_array[i].message != NULL) {
        i++;
    }

    // Remove all unused entries
    for (size_t j = i; j < log_array_size; j++) {
        free(log_array[j].message);
        log_array[j] = log_array[j + 1];
    }

    // Reset the log array size
    log_array_size = i;

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_array_mutex);
}

// Export the log entries to a file in a standardized format
void export_log(FILE* file) {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_array_mutex);

    // Write each entry to the file
    for (size_t i = 0; i < log_array_size; i++) {
        fprintf(file, LOG_FILE_FORMAT, log_array[i].timestamp, log_array[i].level, log_array[i].message);
    }

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_array_mutex);
}

// Filter the log entries based on a specified log level
void filter_log(int level) {
    // Acquire the mutex for synchronizing access to the log array
    pthread_mutex_lock(&log_array_mutex);

    // Remove all entries with a lower log level than the specified level
    for (size_t i = 0; i < log_array_size; i++) {
        if (log_array[i].level < level) {
            memmove(&log_array[i], &log_array[i + 1], sizeof(ModemLogEntry) * (log_array_size - i));
            log_array_size--;
            i--;
        }
    }

    // Release the mutex for synchronizing access to the log array
    pthread_mutex_unlock(&log_array_mutex);
}

// Start the background thread for purging old entries
void start_purge_thread() {
    // Create a new thread for purging old entries
    pthread_create(&purge_thread, NULL, purge_old_entries, NULL);
}

// Stop the background thread for purging old entries
void stop_purge_thread() {
    // Join the purge thread to ensure it has completed
    pthread_join(purge_thread, NULL);
}
