// Define the maximum number of active sessions
#define MAX_ACTIVE_SESSIONS 1000

// Define the duration for which a session is considered inactive (in seconds)
#define INACTIVE_DURATION 3600

// Define the frequency for terminating inactive sessions (in seconds)
#define TERMINATE_FREQUENCY 300

// Define the frequency for compacting the session structure (in seconds)
#define COMPACT_FREQUENCY 600

// Define the maximum size of the dynamic array
#define MAX_ARRAY_SIZE 10000

// Define the structure to store a network session
typedef struct NetworkSession {
    int id;
    char* client_ip;
    time_t start_time;
    time_t end_time;
    char* data;
} NetworkSession;

// Define the dynamic array to store all active sessions
NetworkSession* active_sessions = NULL;

// Define the mutex for protecting the shared data structure
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a new session is added or removed
pthread_cond_t session_added = PTHREAD_COND_INITIALIZER;

// Define the function to add a new session
void add_session(int id, char* client_ip, time_t start_time, time_t end_time, char* data) {
    // Acquire the lock on the shared data structure
    pthread_mutex_lock(&session_lock);

    // Check if the maximum number of active sessions has been reached
    if (active_sessions == NULL || num_active_sessions >= MAX_ACTIVE_SESSIONS) {
        // If so, wait for a new session to be removed before adding the new one
        pthread_cond_wait(&session_added, &session_lock);
    }

    // Create a new network session structure and add it to the dynamic array
    NetworkSession* new_session = malloc(sizeof(NetworkSession));
    new_session->id = id;
    new_session->client_ip = client_ip;
    new_session->start_time = start_time;
    new_session->end_time = end_time;
    new_session->data = data;
    active_sessions = realloc(active_sessions, (num_active_sessions + 1) * sizeof(NetworkSession));
    active_sessions[num_active_sessions++] = new_session;

    // Release the lock on the shared data structure
    pthread_mutex_unlock(&session_lock);
}

// Define the function to retrieve a session by client IP address
NetworkSession* get_session_by_client_ip(char* client_ip) {
    // Acquire the lock on the shared data structure
    pthread_mutex_lock(&session_lock);

    // Iterate over all active sessions and find the one with the matching client IP address
    for (int i = 0; i < num_active_sessions; i++) {
        if (strcmp(active_sessions[i]->client_ip, client_ip) == 0) {
            // If found, return the session structure
            pthread_mutex_unlock(&session_lock);
            return active_sessions[i];
        }
    }

    // If not found, return NULL
    pthread_mutex_unlock(&session_lock);
    return NULL;
}

// Define the function to retrieve a session by ID
NetworkSession* get_session_by_id(int id) {
    // Acquire the lock on the shared data structure
    pthread_mutex_lock(&session_lock);

    // Iterate over all active sessions and find the one with the matching ID
    for (int i = 0; i < num_active_sessions; i++) {
        if (active_sessions[i]->id == id) {
            // If found, return the session structure
            pthread_mutex_unlock(&session_lock);
            return active_sessions[i];
        }
    }

    // If not found, return NULL
    pthread_mutex_unlock(&session_lock);
    return NULL;
}

// Define the function to clear all sessions
void clear_all_sessions() {
    // Acquire the lock on the shared data structure
    pthread_mutex_lock(&session_lock);

    // Free all active sessions and set the dynamic array to NULL
    for (int i = 0; i < num_active_sessions; i++) {
        free(active_sessions[i]);
    }
    free(active_sessions);
    active_sessions = NULL;
    num_active_sessions = 0;

    // Release the lock on the shared data structure
    pthread_mutex_unlock(&session_lock);
}

// Define the function to filter sessions based on a specified duration
void filter_sessions(int duration) {
    // Acquire the lock on the shared data structure
    pthread_mutex_lock(&session_lock);

    // Iterate over all active sessions and remove those that have ended more than the specified duration ago
    for (int i = 0; i < num_active_sessions; i++) {
        if (time(NULL) - active_sessions[i]->end_time > duration) {
            free(active_sessions[i]);
            memmove(&active_sessions[i], &active_sessions[i + 1], sizeof(NetworkSession) * (num_active_sessions - i));
            num_active_sessions--;
        }
    }

    // Release the lock on the shared data structure
    pthread_mutex_unlock(&session_lock);
}

// Define the function to terminate inactive sessions older than a configurable duration
void terminate_inactive_sessions() {
    // Acquire the lock on the shared data structure
    pthread_mutex_lock(&session_lock);

    // Iterate over all active sessions and remove those that have been inactive for longer than the specified duration
    for (int i = 0; i < num_active_sessions; i++) {
        if (time(NULL) - active_sessions[i]->end_time > INACTIVE_DURATION) {
            free(active_sessions[i]);
            memmove(&active_sessions[i], &active_sessions[i + 1], sizeof(NetworkSession) * (num_active_sessions - i));
            num_active_sessions--;
        }
    }

    // Release the lock on the shared data structure
    pthread_mutex_unlock(&session_lock);
}

// Define the function to compact the session structure
void compact_sessions() {
    // Acquire the lock on the shared data structure
    pthread_mutex_lock(&session_lock);

    // Reallocate the dynamic array with a smaller size if possible
    if (num_active_sessions > 0) {
        active_sessions = realloc(active_sessions, num_active_sessions * sizeof(NetworkSession));
    } else {
        free(active_sessions);
        active_sessions = NULL;
    }

    // Release the lock on the shared data structure
    pthread_mutex_unlock(&session_lock);
}

// Define the function to export session summaries to a file in a standardized format
void export_session_summaries(char* filename) {
    // Acquire the lock on the shared data structure
    pthread_mutex_lock(&session_lock);

    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening output file");
        return;
    }

    // Iterate over all active sessions and write a summary of each one to the output file
    for (int i = 0; i < num_active_sessions; i++) {
        fprintf(fp, "%d,%s,%ld,%ld\n", active_sessions[i]->id, active_sessions[i]->client_ip, active_sessions[i]->start_time, active_sessions[i]->end_time);
    }

    // Close the output file
    fclose(fp);

    // Release the lock on the shared data structure
    pthread_mutex_unlock(&session_lock);
}
