#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the maximum duration for which old entries can be kept in the log
#define MAX_ENTRY_AGE 3600 // seconds

// Define the minimum interval between log purges
#define MIN_PURGE_INTERVAL 300 // seconds

// Define the maximum number of threads that can access the log simultaneously
#define MAX_THREADS 16

// Define the log level for filtering logs
typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

// Define a structure to represent a log entry
typedef struct {
    time_t timestamp;
    LogLevel level;
    char* message;
} ModemLogEntry;

// Define a structure to represent the log array
typedef struct {
    int size;
    int capacity;
    ModemLogEntry* entries[MAX_LOG_SIZE];
} ModemLog;

// Define a function to add a new entry to the log
void addEntry(ModemLog* log, time_t timestamp, LogLevel level, char* message) {
    // Check if the log is full and needs to be purged
    if (log->size == log->capacity) {
        purgeOldEntries(log);
    }

    // Add the new entry to the log
    ModemLogEntry* entry = malloc(sizeof(ModemLogEntry));
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = strdup(message);
    log->entries[log->size++] = entry;
}

// Define a function to retrieve an entry from the log by timestamp
ModemLogEntry* getEntryByTimestamp(ModemLog* log, time_t timestamp) {
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i]->timestamp == timestamp) {
            return log->entries[i];
        }
    }
    return NULL;
}

// Define a function to clear the entire log
void clearLog(ModemLog* log) {
    for (int i = 0; i < log->size; i++) {
        free(log->entries[i]);
    }
    log->size = 0;
}

// Define a function to purge old entries from the log
void purgeOldEntries(ModemLog* log) {
    // Calculate the age of the oldest entry in the log
    time_t oldestEntryAge = getCurrentTime() - log->entries[0]->timestamp;

    // Purge any entries that are older than the maximum age
    for (int i = 0; i < log->size; i++) {
        if (oldestEntryAge > MAX_ENTRY_AGE) {
            free(log->entries[i]);
            log->size--;
        } else {
            break;
        }
    }
}

// Define a function to filter logs based on the specified log level
void filterLogs(ModemLog* log, LogLevel level) {
    // Create a new array to store the filtered entries
    ModemLogEntry* filteredEntries[log->size];
    int filteredSize = 0;

    // Iterate over the log entries and add them to the filtered array if they match the specified level
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i]->level == level) {
            filteredEntries[filteredSize++] = log->entries[i];
        }
    }

    // Update the log with the filtered entries
    log->size = filteredSize;
}

// Define a function to export the log entries to a file in a standardized format
void exportLogs(ModemLog* log, char* filename) {
