#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the frequency at which logs are flushed to disk (in seconds)
#define FLUSH_FREQUENCY 60

// Define the duration for which logs are kept before being archived (in days)
#define ARCHIVE_DURATION 30

// Define the size of the cache used to store recently accessed log entries
#define CACHE_SIZE 128

// Define the structure for the log array and its associated metadata
typedef struct {
    ModemLogEntry* entries;
    int num_entries;
    int max_size;
} LogArray;

// Define the cache structure
typedef struct {
    ModemLogEntry* entries;
    int num_entries;
} Cache;

// Function to add a new log entry to the array
void add_log_entry(LogArray* log, time_t timestamp, int level, char* message) {
    // Check if the log is full and needs to be resized
    if (log->num_entries == log->max_size) {
        log->max_size *= 2;
        log->entries = realloc(log->entries, log->max_size * sizeof(ModemLogEntry));
    }

    // Add the new entry to the end of the array
    log->entries[log->num_entries].timestamp = timestamp;
    log->entries[log->num_entries].level = level;
    log->entries[log->num_entries].message = strdup(message);
    log->num_entries++;
}

// Function to retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(LogArray* log, time_t timestamp) {
    // Iterate through the array and find the matching entry
    for (int i = 0; i < log->num_entries; i++) {
        if (log->entries[i].timestamp == timestamp) {
            return &log->entries[i];
        }
    }

    // If no match is found, return NULL
    return NULL;
}

// Function to clear the entire log array
void clear_log(LogArray* log) {
    // Free all memory allocated for the log entries
    for (int i = 0; i < log->num_entries; i++) {
        free(log->entries[i].message);
    }

    // Reset the number of entries to zero
    log->num_entries = 0;
}

// Function to flush the log array to disk
void flush_log(LogArray* log) {
    // Open a file for writing and write all log entries to it
    FILE* fp = fopen("log.txt", "w");
    for (int i = 0; i < log->num_entries; i++) {
        fprintf(fp, "%lu %d %s\n", log->entries[i].timestamp, log->entries[i].level, log->entries[i].message);
    }
    fclose(fp);
}

// Function to archive old logs and maintain a rolling log of a fixed size
void archive_logs(LogArray* log) {
    // Calculate the number of days since the oldest entry in the log
    time_t now = time(NULL);
    int days_since_oldest = (now - log->entries[0].timestamp) / 86400;

    // If the log is older than the specified duration, archive it and clear the log
    if (days_since_oldest > ARCHIVE_DURATION) {
        flush_log(log);
        clear_log(log);
    }
}

// Function to handle concurrent access patterns efficiently
void handle_concurrent_access(LogArray* log, int num_threads) {
    // Create a cache for recently accessed log entries
    Cache cache;
    cache.entries = malloc(CACHE_SIZE * sizeof(ModemLogEntry));
    cache.num_entries = 0;

    // Iterate through the array and check if any of the recent entries are in the cache
    for (int i = log->num_entries - 1; i >= 0; i--) {
        ModemLogEntry* entry = &log->entries[i];
        bool found = false;

        // Iterate through the cache and check if any of the recent entries are in it
        for (int j = 0; j < cache.num_entries; j++) {
            if (cache.entries[j].timestamp == entry->timestamp) {
                found = true;
                break;
            }
        }

        // If the entry is not in the cache, add it to the end of the cache
        if (!found) {
            cache.entries[cache.num_entries++] = *entry;
        }
    }
}
