    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroyDynamicArray(LTE_RRC_EUTRA_BEARER_CONFIG_T* array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int addBearerToArray(LTE_RRC_EUTRA_BEARER_CONFIG_T* array, int bearerID, int qosPriority, int ambr) {
    if (!array) {
        return -1;
    }
    pthread_mutex_lock(&array->lock);
    LTE_RRC_EUTRA_BEARER_CONFIG_T* newBearer = (LTE_RRC_EUTRA_BEARER_CONFIG_T*)malloc(sizeof(LTE_RRC_EUTRA_BEARER_CONFIG_T));
    if (!newBearer) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    newBearer->bearerID = bearerID;
    newBearer->qosPriority = qosPriority;
    newBearer->ambr = ambr;
    array[array->size++] = *newBearer;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int removeBearerFromArray(LTE_RRC_EUTRA_BEARER_CONFIG_T* array, int bearerID) {
    if (!array) {
        return -1;
    }
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->size; i++) {
        if (array[i].bearerID == bearerID) {
            memmove(&array[i], &array[i + 1], (array->size - i - 1) * sizeof(LTE_RRC_EUTRA_BEARER_CONFIG_T));
            array->size--;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1;
}
