// Define structure for LTE_RRC_EUTRA_BEARER_CONFIG
typedef struct {
    int bearer_id;
    int qos_priority;
    int ambr;
} LTE_RRC_EUTRA_BEARER_CONFIG_T;

// Define array for storing dynamic array of LTE_RRC_EUTRA_BEARER_CONFIG structures
LTE_RRC_EUTRA_BEARER_CONFIG_T* bearer_configs = NULL;

// Define maximum number of bearers that can be configured in a single structure
#define MAX_NUM_BEARERS 10

// Define mutex for protecting concurrent access to the array
pthread_mutex_t bearer_configs_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and manage dynamic array of LTE_RRC_EUTRA_BEARER_CONFIG structures
void init_bearer_configs(int num_bearers) {
    // Acquire mutex for protecting concurrent access to the array
    pthread_mutex_lock(&bearer_configs_mutex);

    // Check if the array has already been initialized
    if (bearer_configs == NULL) {
        // Allocate memory for the array of structures
        bearer_configs = malloc(num_bearers * sizeof(LTE_RRC_EUTRA_BEARER_CONFIG_T));
        if (bearer_configs == NULL) {
            perror("Failed to allocate memory for bearer configs");
            return;
        }
    } else {
        // Check if the number of bearers is greater than the maximum allowed
        if (num_bearers > MAX_NUM_BEARERS) {
            fprintf(stderr, "Number of bearers exceeds maximum allowed\n");
            return;
        }
    }

    // Initialize each structure in the array with default values
    for (int i = 0; i < num_bearers; i++) {
        bearer_configs[i].bearer_id = i + 1;
        bearer_configs[i].qos_priority = 5;
        bearer_configs[i].ambr = 10000000; // 10 Mbps
    }

    // Release mutex for protecting concurrent access to the array
    pthread_mutex_unlock(&bearer_configs_mutex);
}

// Function to add a new bearer configuration to the dynamic array
void add_bearer_config(int bearer_id, int qos_priority, int ambr) {
    // Acquire mutex for protecting concurrent access to the array
    pthread_mutex_lock(&bearer_configs_mutex);

    // Check if the array has already been initialized
    if (bearer_configs == NULL) {
        init_bearer_configs(1);
    }

    // Check if the number of bearers exceeds the maximum allowed
    if (num_bearers > MAX_NUM_BEARERS) {
        fprintf(stderr, "Number of bearers exceeds maximum allowed\n");
        return;
    }

    // Add new structure to the array with the specified configuration parameters
    LTE_RRC_EUTRA_BEARER_CONFIG_T* new_config = malloc(sizeof(LTE_RRC_EUTRA_BEARER_CONFIG_T));
    if (new_config == NULL) {
        perror("Failed to allocate memory for new bearer config");
        return;
    }
    new_config->bearer_id = bearer_id;
    new_config->qos_priority = qos_priority;
    new_config->ambr = ambr;
    bearer_configs[num_bearers++] = *new_config;

    // Release mutex for protecting concurrent access to the array
    pthread_mutex_unlock(&bearer_configs_mutex);
}

// Function to remove a bearer configuration from the dynamic array
void remove_bearer_config(int bearer_id) {
    // Acquire mutex for protecting concurrent access to the array
    pthread_mutex_lock(&bearer_configs_mutex);

    // Check if the array has already been initialized
    if (bearer_configs == NULL) {
        init_bearer_configs(1);
    }

    // Find the index of the bearer configuration to be removed
    int i;
    for (i = 0; i < num_bearers; i++) {
        if (bearer_configs[i].bearer_id == bearer_id) {
            break;
        }
    }

    // Check if the bearer configuration was found
    if (i == num_bearers) {
        fprintf(stderr, "Bearer configuration not found\n");
        return;
    }

    // Remove the structure from the array and free its memory
    LTE_RRC_EUTRA_BEARER_CONFIG_T* removed_config = &bearer_configs[i];
    memmove(&bearer_configs[i], &bearer_configs[i + 1], (num_bearers - i) * sizeof(LTE_RRC_EUTRA_BEARER_CONFIG_T));
    num_bearers--;
    free(removed_config);

    // Release mutex for protecting concurrent access to the array
    pthread_mutex_unlock(&bearer_configs_mutex);
}

// Function to validate the integrity of the configuration data before each operation
void validate_config() {
    // Acquire mutex for protecting concurrent access to the array
    pthread_mutex_lock(&bearer_configs_mutex);

    // Check if the array has already been initialized
    if (bearer_configs == NULL) {
        init_bearer_configs(1);
    }

    // Validate each structure in the array for consistency and correctness
    for (int i = 0; i < num_bearers; i++) {
        if (bearer_configs[i].bearer_id <= 0 || bearer_configs[i].qos_priority <= 0 || bearer_configs[i].ambr <= 0) {
            fprintf(stderr, "Invalid configuration data found\n");
            return;
        }
    }

    // Release mutex for protecting concurrent access to the array
    pthread_mutex_unlock(&bearer_configs_mutex);
}

// Function to log operations for debugging purposes
void log_operation(char* operation, int bearer_id) {
    // Acquire mutex for protecting concurrent access to the array
    pthread_mutex_lock(&bearer_configs_mutex);

    // Check if the array has already been initialized
    if (bearer_configs == NULL) {
        init_bearer_configs(1);
    }

    // Log the operation and bearer ID for debugging purposes
    printf("Operation: %s, Bearer ID: %d\n", operation, bearer_id);

    // Release mutex for protecting concurrent access to the array
    pthread_mutex_unlock(&bearer_configs_mutex);
}
