// Define a structure to represent an LTE UE context
typedef struct {
    int rnti; // RNTI (Radio Network Temporary Identity) of the UE
    void *mac_context; // MAC context for the UE
    void *ul_rlc_buffer; // UL RLC buffer for the UE
    void *dl_rlc_buffer; // DL RLC buffer for the UE
} lte_ue_context_t;

// Define a list data structure to store LTE UE contexts
typedef struct {
    int num_ues; // Number of UEs in the list
    int max_size; // Maximum size of the list (in number of UEs)
    lte_ue_context_t *ues; // Array of LTE UE context structures
} lte_ue_list_t;

// Initialize a list of LTE UE contexts with a given number of UEs
lte_ue_list_t *init_lte_ue_list(int num_ues) {
    // Check if the input parameter is valid
    assert(num_ues > 0);

    // Allocate memory for the list structure and its contents
    lte_ue_list_t *list = malloc(sizeof(lte_ue_list_t));
    list->num_ues = num_ues;
    list->max_size = num_ues;
    list->ues = calloc(num_ues, sizeof(lte_ue_context_t));

    // Initialize each UE context structure in the list
    for (int i = 0; i < num_ues; i++) {
        list->ues[i].rnti = -1;
        list->ues[i].mac_context = NULL;
        list->ues[i].ul_rlc_buffer = NULL;
        list->ues[i].dl_rlc_buffer = NULL;
    }

    return list;
}

// Add a new UE context to the list, returning its index in the list
int add_lte_ue_context(lte_ue_list_t *list, int rnti, void *mac_context, void *ul_rlc_buffer, void *dl_rlc_buffer) {
    // Check if the input parameters are valid
    assert(rnti > 0);
    assert(mac_context != NULL);
    assert(ul_rlc_buffer != NULL);
    assert(dl_rlc_buffer != NULL);

    // Ensure that there is enough memory to add a new UE context
    if (list->num_ues >= list->max_size) {
        return -1;
    }

    // Find the first available slot in the list and initialize it with the given parameters
    int index = 0;
    while (index < list->num_ues && list->ues[index].rnti != -1) {
        index++;
    }
    if (index == list->max_size) {
        return -2;
    }
    list->ues[index].rnti = rnti;
    list->ues[index].mac_context = mac_context;
    list->ues[index].ul_rlc_buffer = ul_rlc_buffer;
    list->ues[index].dl_rlc_buffer = dl_rlc_buffer;

    // Increment the number of UEs in the list and return the index of the new context
    list->num_ues++;
    return index;
}

// Update an existing UE context in the list, returning 0 on success or a negative value on failure
int update_lte_ue_context(lte_ue_list_t *list, int index, int rnti, void *mac_context, void *ul_rlc_buffer, void *dl_rlc_buffer) {
    // Check if the input parameters are valid
    assert(index >= 0 && index < list->num_ues);
    assert(rnti > 0);
    assert(mac_context != NULL);
    assert(ul_rlc_buffer != NULL);
    assert(dl_rlc_buffer != NULL);

    // Ensure that the given UE context exists in the list
    if (list->ues[index].rnti == -1) {
        return -1;
    }

    // Update the UE context with the given parameters
    list->ues[index].rnti = rnti;
    list->ues[index].mac_context = mac_context;
    list->ues[index].ul_rlc_buffer = ul_rlc_buffer;
    list->ues[index].dl_rlc_buffer = dl_rlc_buffer;

    return 0;
}

// Remove a UE context from the list, returning its index in the list or a negative value on failure
int remove_lte_ue_context(lte_ue_list_t *list, int rnti) {
    // Check if the input parameter is valid
    assert(rnti > 0);

    // Find the index of the given UE context in the list
    int index = -1;
    for (int i = 0; i < list->num_ues && index == -1; i++) {
        if (list->ues[i].rnti == rnti) {
            index = i;
        }
    }

    // Ensure that the given UE context exists in the list
    if (index == -1) {
        return -1;
    }

    // Remove the UE context from the list and update the number of UEs
    for (int i = index; i < list->num_ues - 1; i++) {
        list->ues[i] = list->ues[i + 1];
    }
    list->num_ues--;

    return index;
}

// Clean up the memory allocated for the LTE UE context list and its contents
void cleanup_lte_ue_list(lte_ue_list_t *list) {
    // Free the memory allocated for the list structure and its contents
    free(list->ues);
    free(list);
}
