    pthread_mutex_unlock(&log_lock);
}

// Function to purge old entries from the log
void purge_old_entries() {
    // Lock the log array
    pthread_mutex_lock(&log_lock);

    // Find the first entry that is older than the purge duration
    int i = 0;
    while (i < num_entries && log_array[i].timestamp >= time(NULL) - purge_duration) {
        i++;
    }

    // If no entries were found, return
    if (i == num_entries) {
        pthread_mutex_unlock(&log_lock);
        return;
    }

    // Remove the old entries from the log array
    for (int j = i; j < num_entries; j++) {
        free(log_array[j].message);
    }
    num_entries -= i;

    // Unlock the log array
    pthread_mutex_unlock(&log_lock);
}

// Function to compact the log structure
void compact_log() {
    // Lock the log array
    pthread_mutex_lock(&log_lock);

    // Find the first entry that is not at the end of the log array
    int i = 0;
    while (i < num_entries && log_array[i].timestamp == time(NULL)) {
        i++;
    }

    // If all entries are at the end of the log array, return
    if (i == num_entries) {
        pthread_mutex_unlock(&log_lock);
        return;
    }

    // Create a new array to hold the compacted log
    ModemLogEntry* compacted_log = malloc(sizeof(ModemLogEntry) * (num_entries - i));

    // Copy the compacted log into the new array
    for (int j = 0; j < num_entries - i; j++) {
        compacted_log[j] = log_array[i + j];
    }

    // Free the old log array
    free(log_array);

    // Set the new log array and number of entries
    log_array = compacted_log;
    num_entries -= i;

    // Unlock the log array
    pthread_mutex_unlock(&log_lock);
