typedef struct NetworkStats {
    time_t timestamp;
    double bandwidth;
    double latency;
    double packetLossPercentage;
} NetworkStats;

// Dynamic array of NetworkStats structures
NetworkStats* statsArray = NULL;
size_t statsArraySize = 0;
size_t statsArrayCapacity = 0;

// Function to add a new entry to the stats array
void addNetworkStat(time_t timestamp, double bandwidth, double latency, double packetLossPercentage) {
    // Check if the array needs to be resized
    if (statsArraySize == statsArrayCapacity) {
        statsArrayCapacity *= 2;
        NetworkStats* newArray = realloc(statsArray, sizeof(NetworkStats) * statsArrayCapacity);
        if (!newArray) {
            // Handle error
            return;
        }
        statsArray = newArray;
    }

    // Add the new entry to the array
    NetworkStats* newStat = &statsArray[statsArraySize++];
    newStat->timestamp = timestamp;
    newStat->bandwidth = bandwidth;
    newStat->latency = latency;
    newStat->packetLossPercentage = packetLossPercentage;
}

// Function to retrieve entries from the stats array within a given time interval
void getNetworkStats(time_t startTime, time_t endTime) {
    // Check if the input times are valid
    if (startTime > endTime || startTime < 0 || endTime < 0) {
        return;
    }

    // Find the first and last indices of the entries within the given interval
    size_t firstIndex = statsArraySize - 1;
    while (firstIndex > 0 && statsArray[firstIndex].timestamp >= startTime) {
        firstIndex--;
    }
    size_t lastIndex = firstIndex + 1;
    while (lastIndex < statsArraySize && statsArray[lastIndex].timestamp <= endTime) {
        lastIndex++;
    }

    // Print the entries within the interval
    for (size_t i = firstIndex; i < lastIndex; i++) {
        NetworkStats* stat = &statsArray[i];
        printf("Timestamp: %ld\n", stat->timestamp);
        printf("Bandwidth: %.2f Mbps\n", stat->bandwidth);
        printf("Latency: %.2f ms\n", stat->latency);
        printf("Packet Loss: %.2f%%\n", stat->packetLossPercentage);
    }
}

// Function to clear the entire stats history
void clearNetworkStats() {
    free(statsArray);
    statsArray = NULL;
    statsArraySize = 0;
    statsArrayCapacity = 0;
}

