    if (!filteredArray) {
        return;
    }
    size_t filteredArraySize = 1;
    size_t filteredArrayCapacity = 1;
    filteredArray[0] = statsArray[0];

    // Iterate over the remaining entries and filter out those that do not meet the thresholds
    for (size_t i = 1; i < statsArraySize; i++) {
        NetworkStats* stat = &statsArray[i];
        if (stat->bandwidth >= bandwidthThreshold && stat->latency <= latencyThreshold) {
            // Add the entry to the filtered array
            if (filteredArraySize == filteredArrayCapacity) {
                filteredArrayCapacity *= 2;
                NetworkStats* newFilteredArray = realloc(filteredArray, sizeof(NetworkStats) * filteredArrayCapacity);
                if (!newFilteredArray) {
                    // Handle error
                    return;
                }
                filteredArray = newFilteredArray;
            }
            NetworkStats* newStat = &filteredArray[filteredArraySize++];
            newStat->timestamp = stat->timestamp;
            newStat->bandwidth = stat->bandwidth;
            newStat->latency = stat->latency;
            newStat->packetLossPercentage = stat->packetLossPercentage;
        }
