```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Custom structure to hold network statistics
typedef struct NetworkStats {
    int bandwidth;
    int latency;
    float packet_loss;
} NetworkStats;

// Dynamic array of NetworkStats structures
static NetworkStats* stats = NULL;
static size_t num_stats = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Add a new entry to the dynamic array
void add_network_stat(NetworkStats stat) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Reallocate memory for the dynamic array if necessary
    if (num_stats == 0 || stats == NULL) {
        stats = realloc(stats, sizeof(NetworkStats) * num_stats + 1);
    }

    // Copy the new stat into the dynamic array
    memcpy(&stats[num_stats], &stat, sizeof(NetworkStats));
    num_stats++;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Retrieve entries from the dynamic array within a given time interval
void retrieve_network_stats(int start_time, int end_time) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate over the dynamic array and print each entry that falls within the specified time interval
    for (size_t i = 0; i < num_stats; i++) {
        if (stats[i].timestamp >= start_time && stats[i].timestamp <= end_time) {
            printf("Bandwidth: %d\n", stats[i].bandwidth);
            printf("Latency: %d\n", stats[i].latency);
            printf("Packet loss: %.2f%%\n", stats[i].packet_loss * 100.0);
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Clear the entire stats history
void clear_network_stats() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the dynamic array
    free(stats);
    stats = NULL;
    num_stats = 0;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Filter and aggregate statistics based on predefined thresholds for bandwidth and latency
void filter_and_aggregate_network_stats(int bandwidth_threshold, int latency_threshold) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate over the dynamic array and filter out entries that do not meet the predefined thresholds
    for (size_t i = 0; i < num_stats; i++) {
        if (stats[i].bandwidth < bandwidth_threshold || stats[i].latency > latency_threshold) {
            // Remove the entry from the dynamic array
            memmove(&stats[i], &stats[i + 1], sizeof(NetworkStats) * (num_stats - i));
            num_stats--;
        }
    }

    // Aggregate the remaining entries by summing their bandwidth and latency values
    int total_bandwidth = 0;
    int total_latency = 0;
    for (size_t i = 0; i < num_stats; i++) {
        total_bandwidth += stats[i].bandwidth;
        total_latency += stats[i].latency;
    }

    // Print the aggregated statistics
    printf("Aggregate bandwidth: %d\n", total_bandwidth);
    printf("Aggregate latency: %d\n", total_latency);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}
