// Define the function to manage the dynamic array of interconnected data structures
void manage_log_entries(ModemLogEntry* entry) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the log entry is a duplicate
    for (size_t i = 0; i < log_entry_count; i++) {
        if (log_entries[i].ip_address == entry->ip_address &&
            log_entries[i].timestamp == entry->timestamp) {
            // Release the mutex lock and return
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Check if the IP address is already in the array
    for (size_t i = 0; i < ip_address_count; i++) {
        if (ip_addresses[i] == entry->ip_address) {
            break;
        } else if (i == ip_address_count - 1) {
            // Add the IP address to the array
            ip_addresses = realloc(ip_addresses, ++ip_address_capacity * sizeof(uint32_t));
            ip_addresses[ip_address_count++] = entry->ip_address;
        }
    }

    // Check if the timestamp is already in the array
    for (size_t i = 0; i < timestamp_count; i++) {
        if (timestamps[i] == entry->timestamp) {
            break;
        } else if (i == timestamp_count - 1) {
            // Add the timestamp to the array
            timestamps = realloc(timestamps, ++timestamp_capacity * sizeof(time_t));
            timestamps[timestamp_count++] = entry->timestamp;
        }
    }

    // Check if the event is already in the array
    for (size_t i = 0; i < event_count; i++) {
        if (events[i].description == entry->event.description &&
            events[i].severity == entry->event.severity) {
            break;
        } else if (i == event_count - 1) {
            // Add the event to the array
            events = realloc(events, ++event_capacity * sizeof(Event));
            events[event_count++] = entry->event;
        }
    }

    // Check if the log rate limiter is exceeded
    if (log_rate_limiter > 0) {
        // Release the mutex lock and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Add the log entry to the array
    log_entries = realloc(log_entries, ++log_entry_capacity * sizeof(ModemLogEntry));
    log_entries[log_entry_count++] = *entry;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

