// Define the structure for the offset array
typedef struct {
    long offset;
} Offset;

// Define the structure for the key array
typedef struct {
    int key;
} Key;

// Define the structure for the record array
typedef struct {
    int value;
} Record;

// Define the function to manage memory allocation and initialization
void allocate_and_initialize(int num_records, int min_value, int max_value) {
    // Calculate the size of the offset and key arrays based on the number of records
    int offset_size = sizeof(Offset) * num_records;
    int key_size = sizeof(Key) * num_records;

    // Allocate memory for the offset and key arrays
    Offset* offsets = (Offset*)malloc(offset_size);
    Key* keys = (Key*)malloc(key_size);

    // Initialize the offset and key arrays with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i].offset = rand() % (max_value - min_value + 1) + min_value;
        keys[i].key = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for the record array
    Record* records = (Record*)malloc(sizeof(Record) * num_records);

    // Initialize the record array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Log the memory allocation and deallocation events to a file named "memory_log.txt" in a structured format
    FILE* log_file = fopen("memory_log.txt", "a");
    if (log_file == NULL) {
        printf("Error: unable to open log file\n");
        return;
    }

    // Log the allocation of the offset and key arrays
    fprintf(log_file, "%lu %s %d %p\n", time(NULL), "allocation", offset_size, offsets);
    fprintf(log_file, "%lu %s %d %p\n", time(NULL), "allocation", key_size, keys);

    // Log the allocation of the record array
    fprintf(log_file, "%lu %s %d %p\n", time(NULL), "allocation", sizeof(Record) * num_records, records);

    // Close the log file
    fclose(log_file);
}

