// Define the structure for a ModemLogEntry
typedef struct {
    uint64_t timestamp;
    int log_level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the dynamic array
#define MAX_LOG_SIZE 1024

// Define the function to manage the dynamic array of ModemLogEntries
void manage_log(ModemLogEntry** log, uint64_t timestamp, int log_level, char* message) {
    // Check if the log is full and needs to be resized
    if (log == NULL || *log == NULL || (*log)->size >= MAX_LOG_SIZE) {
        // Resize the log if it's full or doesn't exist yet
        ModemLogEntry** new_log = realloc(*log, sizeof(ModemLogEntry*) * (MAX_LOG_SIZE + 1));
        if (new_log == NULL) {
            // If reallocation fails, return an error
            printf("Error: Failed to resize log\n");
            return;
        }
        *log = new_log;
    }

    // Add the new entry to the log
    (*log)->size++;
    (*log)[(*log)->size - 1] = malloc(sizeof(ModemLogEntry));
    (*log)[(*log)->size - 1]->timestamp = timestamp;
    (*log)[(*log)->size - 1]->log_level = log_level;
    (*log)[(*log)->size - 1]->message = strdup(message);
}

// Define the function to retrieve an entry from the log by timestamp
ModemLogEntry* get_entry_by_timestamp(ModemLogEntry** log, uint64_t timestamp) {
    // Check if the log is empty or doesn't exist yet
    if (log == NULL || *log == NULL || (*log)->size == 0) {
        return NULL;
    }

    // Iterate through the log entries and find the one with the matching timestamp
    for (int i = 0; i < (*log)->size; i++) {
        if ((*log)[i]->timestamp == timestamp) {
            return &(*log)[i];
        }
    }

    // If no entry is found, return NULL
    return NULL;
}

// Define the function to clear the entire log
void clear_log(ModemLogEntry** log) {
    // Check if the log is empty or doesn't exist yet
    if (log == NULL || *log == NULL || (*log)->size == 0) {
        return;
    }

    // Free all the entries in the log
    for (int i = 0; i < (*log)->size; i++) {
        free((*log)[i]->message);
        free((*log)[i]);
    }

    // Reset the size of the log to 0
    (*log)->size = 0;
}
