// Define the function for calculating the MD5 hash of a file
void calculateMD5(const string& path) {
    ifstream file(path, ios::binary);
    if (!file.is_open()) {
        cerr << "Error: unable to open file '" << path << "' for reading" << endl;
        return;
    }

    // Create a buffer for reading the file in chunks
    const int BUFFER_SIZE = 1024 * 1024; // 1 MB
    char buffer[BUFFER_SIZE];

    // Initialize the MD5 hash context
    MD5_CTX ctx;
    MD5Init(&ctx);

    // Read the file in chunks and update the MD5 hash
    while (!file.eof()) {
        file.read(buffer, BUFFER_SIZE);
        if (file.gcount() > 0) {
            MD5Update(&ctx, buffer, file.gcount());
        }
    }

    // Calculate the final MD5 hash and print it to stdout
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5Final(md5Hash, &ctx);
    cout << "MD5 hash of file '" << path << "': ";
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        cout << hex << setw(2) << setfill('0') << (int)md5Hash[i];
    }
    cout << endl;
}

// Define the function for processing a client connection
void processClientConnection(const ClientInfo& clientInfo) {
    // Create a new thread to handle the client connection
    thread t([clientInfo]() {
        // Open a socket for the client connection
        int socket = socket(AF_INET, SOCK_STREAM, 0);
        if (socket < 0) {
            cerr << "Error: unable to create socket" << endl;
            return;
        }

        // Connect to the client
        sockaddr_in serverAddress = { AF_INET, htons(clientInfo.port), inet_addr(clientInfo.ipAddress) };
        if (connect(socket, (sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
            cerr << "Error: unable to connect to client" << endl;
            close(socket);
            return;
        }

        // Read the file path from the client
        char buffer[1024];
        if (recv(socket, buffer, 1024, 0) < 0) {
            cerr << "Error: unable to read file path" << endl;
            close(socket);
            return;
        }

        // Calculate the MD5 hash of the file
        calculateMD5(buffer);

        // Close the socket and exit the thread
        close(socket);
    });

    t.detach();
}

// Define the function for handling client connections in a separate thread
void handleClientConnections() {
    while (true) {
        // Accept a new client connection
        ClientInfo clientInfo;
        sockaddr_in clientAddress = { AF_INET, htons(0), inet_addr("127.0.0.1") };
        int socket = accept(serverSocket, (sockaddr*)&clientAddress, &clientAddressSize);
        if (socket < 0) {
