        processClientConnection(clientInfo);
    }
}

// Define the function for handling file processing in a separate thread
void handleFileProcessing() {
    while (true) {
        // Wait for a new file to be added to the queue
        unique_lock<mutex> lock(fileQueueMutex);
        fileQueueCondition.wait(lock, [&] { return !fileQueue.empty(); });

        // Process the next file in the queue
        FileInfo fileInfo = fileQueue.front();
        fileQueue.pop_front();
        lock.unlock();

        // Calculate the MD5 hash of the file
        calculateMD5(fileInfo.path);
    }
}

// Define the function for handling signals in a separate thread
void handleSignals() {
    while (true) {
        // Wait for a signal to be received
        unique_lock<mutex> lock(signalMutex);
        signalCondition.wait(lock, [&] { return !signalQueue.empty(); });

        // Handle the next signal in the queue
        SignalInfo signalInfo = signalQueue.front();
        signalQueue.pop_front();
        lock.unlock();

        // Handle the signal appropriately
        if (signalInfo.signal == SIGINT) {
            // Gracefully shut down the server
            cout << "Gracefully shutting down the server..." << endl;
            break;
        } else if (signalInfo.signal == SIGTERM) {
            // Forcefully shut down the server
            cout << "Forcefully shutting down the server..." << endl;
            exit(0);
        }
    }
}

int main(int argc, char** argv) {
    // Parse the command-line arguments
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " [options]" << endl;
        return 1;
    }

    // Initialize the server socket
    int serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (serverSocket < 0) {
        cerr << "Error: unable to create server socket" << endl;
        return 1;
    }

    // Bind the server socket to a specific port number
    sockaddr_in serverAddress = { AF_INET, htons(8080), inet_addr("127.0.0.1") };
    if (bind(serverSocket, (sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
        cerr << "Error: unable to bind server socket" << endl;
        close(serverSocket);
        return 1;
    }

    // Listen for incoming connections on the server socket
    if (listen(serverSocket, 3) < 0) {
        cerr << "Error: unable to listen on server socket" << endl;
        close(serverSocket);
        return 1;
    }

    // Initialize the file queue and signal queues
    deque<FileInfo> fileQueue;
    mutex fileQueueMutex;
    condition_variable fileQueueCondition;
    deque<SignalInfo> signalQueue;
    mutex signalMutex;
    condition_variable signalCondition;

    // Start the client connection handling thread
    thread t1(handleClientConnections);

    // Start the file processing thread
    thread t2(handleFileProcessing);

    // Start the signal handling thread
    thread t3(handleSignals);

    // Wait for the threads to finish
    t1.join();
    t2.join();
    t3.join();

    // Close the server socket and exit
    close(serverSocket);
    return 0;
}
