    // Allocate memory for the log entries, index nodes, and records arrays
    module->log_entries = (ModemLogEntry**)malloc(sizeof(ModemLogEntry*) * module->max_capacity);
    module->index_nodes = (index_node**)malloc(sizeof(index_node*) * module->max_index_capacity);
    module->records = (record*)malloc(sizeof(record) * module->max_record_capacity);
    // Initialize the mutex, condition variables, and other fields
