    pthread_cond_init(&module->remove_index_node_cond, NULL);
    pthread_cond_init(&module->add_record_cond, NULL);
    pthread_cond_init(&module->remove_record_cond, NULL);
}

// Add a new log entry to the logging module
void add_log_entry(struct logging_module* module, time_t timestamp, int level, char* message) {
    // Acquire the mutex for protecting the log entries array
    pthread_mutex_lock(&module->mutex);
    // Check if the maximum capacity of the log entries array has been reached
    if (module->num_log_entries == module->max_capacity) {
        // If so, purge old log entries to free up resources and reduce memory fragmentation
        purge_old_log_entries(module);
    }
    // Add the new log entry to the end of the array
    module->log_entries[module->num_log_entries++] = (ModemLogEntry*)malloc(sizeof(ModemLogEntry));
    module->log_entries[module->num_log_entries - 1]->timestamp = timestamp;
    module->log_entries[module->num_log_entries - 1]->level = level;
    module->log_entries[module->num_log_entries - 1]->message = message;
    // Release the mutex and signal the condition variable for new log entries
    pthread_mutex_unlock(&module->mutex);
    pthread_cond_signal(&module->cond);
