    // Acquire the mutex for protecting the log entries array
    pthread_mutex_lock(&module->mutex);
    // Iterate through the log entries and find the one with the matching timestamp
    for (size_t i = 0; i < module->num_log_entries; i++) {
        if (module->log_entries[i]->timestamp == timestamp) {
            // Return a copy of the log entry
            ModemLogEntry* result = (ModemLogEntry*)malloc(sizeof(ModemLogEntry));
            memcpy(result, module->log_entries[i], sizeof(ModemLogEntry));
            pthread_mutex_unlock(&module->mutex);
            return result;
        }
    }
    // If no matching log entry is found, return NULL
    pthread_mutex_unlock(&module->mutex);
    return NULL;
