// Clear the entire logging module by freeing all memory and resetting the counters
void clear_logging(struct logging_module* module) {
    // Acquire the mutex for protecting the log entries array
    pthread_mutex_lock(&module->mutex);
    // Free all memory allocated to the log entries, index nodes, and records arrays
    free(module->log_entries);
