// Purge old log entries to free up resources and reduce memory fragmentation
void purge_old_log_entries(struct logging_module* module) {
    // Acquire the mutex for protecting the log entries array
    pthread_mutex_lock(&module->mutex);
    // Iterate through the log entries and find the oldest entry
    size_t oldest_index = 0;
    time_t oldest_timestamp = module->log_entries[oldest_index]->timestamp;
    for (size_t i = 1; i < module->num_log_entries; i++) {
        if (module->log_entries[i]->timestamp < oldest_timestamp) {
            oldest_index = i;
            oldest_timestamp = module->log_entries[oldest_index]->timestamp;
        }
    }
    // Free the memory allocated to the oldest log entry and remove it from the array
    free(module->log_entries[oldest_index]);
    memmove(&module->log_entries[oldest_index], &module->log_entries[oldest_index + 1], (module->num_log_entries - oldest_index - 1) * sizeof(ModemLogEntry*));
    module->num_log_entries--;
    // Release the mutex and signal the condition variable for old log entries
    pthread_mutex_unlock(&module->mutex);
    pthread_cond_signal(&module->purge_cond);
}

// Compact the log structure to optimize for both memory and CPU usage
void compact_log(struct logging_module* module) {
    // Acquire the mutex for protecting the log entries array
    pthread_mutex_lock(&module->mutex);
    // Iterate through the log entries and find the ones that can be removed
    size_t num_removed = 0;
    for (size_t i = 0; i < module->num_log_entries; i++) {
        if (module->log_entries[i]->message == NULL) {
            // Free the memory allocated to the log entry and remove it from the array
            free(module->log_entries[i]);
            memmove(&module->log_entries[i], &module->log_entries[i + 1], (module->num_log_entries - i - 1) * sizeof(ModemLogEntry*));
            module->num_log_entries--;
            num_removed++;
        }
    }
    // Release the mutex and signal the condition variable for old log entries
    pthread_mutex_unlock(&module->mutex);
    pthread_cond_signal(&module->compact_cond);
}
