Here is an example implementation of the logging function:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the maximum duration for which old entries can be kept in the log
#define MAX_ENTRY_AGE 3600 // seconds

// Define the minimum interval between log purges
#define MIN_PURGE_INTERVAL 60 // seconds

// Define the maximum number of threads that can access the log simultaneously
#define MAX_THREADS 16

// Define the log level threshold for each severity level
#define SEVERITY_LEVELS { "DEBUG", "INFO", "WARNING", "ERROR" }

// Define the structure to hold a single log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the structure to hold the entire log array
typedef struct {
    ModemLogEntry* entries[MAX_LOG_SIZE];
    size_t num_entries;
    pthread_mutex_t mutex;
} LogArray;

// Function to add a new entry to the log
void add_log_entry(ModemLogEntry* entry) {
    // Acquire the lock on the log array
    pthread_mutex_lock(&log->mutex);

    // Check if the log is full and needs to be purged
    if (log->num_entries >= MAX_LOG_SIZE) {
        purge_old_entries(log, MAX_ENTRY_AGE);
    }

    // Add the new entry to the log array
    log->entries[log->num_entries++] = entry;

    // Release the lock on the log array
    pthread_mutex_unlock(&log->mutex);
}

// Function to retrieve all entries in the log with a given timestamp
ModemLogEntry* get_log_entries(time_t timestamp) {
    // Acquire the lock on the log array
    pthread_mutex_lock(&log->mutex);

    // Find the first entry with the specified timestamp
    int i = 0;
    while (i < log->num_entries && log->entries[i]->timestamp != timestamp) {
        i++;
    }

    // If no entry was found, return NULL
    if (i == log->num_entries) {
        pthread_mutex_unlock(&log->mutex);
        return NULL;
    }

    // Create a new array to hold the retrieved entries
    ModemLogEntry* retrieved_entries = malloc(sizeof(ModemLogEntry) * (log->num_entries - i));

    // Copy the retrieved entries into the new array
    for (int j = 0; j < log->num_entries - i; j++) {
        retrieved_entries[j] = log->entries[i + j];
    }

    // Release the lock on the log array
    pthread_mutex_unlock(&log->mutex);

    return retrieved_entries;
}

// Function to clear all entries in the log
void clear_log() {
    // Acquire the lock on the log array
    pthread_mutex_lock(&log->mutex);

    // Clear the log array
    log->num_entries = 0;

    // Release the lock on the log array
    pthread_mutex_unlock(&log->mutex);
}

// Function to purge old entries from the log
void purge_old_entries(LogArray* log, time_t age) {
    // Acquire the lock on the log array
    pthread_mutex_lock(&log->mutex);

    // Find the first entry that is older than the specified age
    int i = 0;
    while (i < log->num_entries && log->entries[i]->timestamp >= time(NULL) - age) {
        i++;
    }

    // If no entry was found, return immediately
    if (i == log->num_entries) {
        pthread_mutex_unlock(&log->mutex);
        return;
    }

    // Remove the old entries from the log array
    for (int j = i; j < log->num_entries; j++) {
        free(log->entries[j]);
    }
    log->num_entries -= i;

    // Release the lock on the log array
    pthread_mutex_unlock(&log->mutex);
}

// Function to compact the log structure by removing unused entries
void compact_log() {
    // Acquire the lock on the log array
    pthread_mutex_lock(&log->mutex);

    // Find the first unused entry in the log array
    int i = 0;
    while (i < log->num_entries && log->entries[i] != NULL) {
        i++;
    }

    // If no unused entry was found, return immediately
    if (i == log->num_entries) {
        pthread_mutex_unlock(&log->mutex);
        return;
    }

    // Remove the unused entries from the log array
    for (int j = i; j < log->num_entries; j++) {
        free(log->entries[j]);
    }
    log->num_entries -= i;

    // Release the lock on the log array
    pthread_mutex_unlock(&log->mutex);
}

// Function to export the log entries to a file in a standardized format
void export_log(FILE* fp) {
    // Acquire the lock on the log array
    pthread_mutex_lock(&log->mutex);

    // Write each entry in the log array to the file
    for (int i = 0; i < log->num_entries; i++) {
        fprintf(fp, "%s %d %s\n", log->entries[i]->timestamp, log->entries[i]->level, log->entries[i]->message);
    }

    // Release the lock on the log array
    pthread_mutex_unlock(&log->mutex);
}
