void handleConnection(int socket, string outputFile, string filterRegex, int bufferSize, int logLevel, int timeout) {
    // Read data from the socket
    char* buffer = new char[bufferSize];
    int bytesRead = recv(socket, buffer, bufferSize, 0);
    if (bytesRead < 0) {
        cout << "Error reading from socket" << endl;
        return;
    }

    // Filter data if a filter regex is specified
    string data = "";
    if (!filterRegex.empty()) {
        regex pattern(filterRegex);
        smatch matches;
        if (regex_search(buffer, matches, pattern)) {
            data = matches[0].str();
        }
    } else {
        data = buffer;
    }

    // Write data to the output file if specified
    if (!outputFile.empty()) {
        ofstream outfile(outputFile, ios::app);
        outfile << data << endl;
        outfile.close();
    }

    // Log data processing status
    switch (logLevel) {
        case LOG_LEVEL_DEBUG:
            cout << "Debug: Processed " << bytesRead << " bytes" << endl;
            break;
        case LOG_LEVEL_INFO:
            cout << "Info: Processed " << bytesRead << " bytes" << endl;
            break;
        case LOG_LEVEL_WARNING:
            cout << "Warning: Processed " << bytesRead << " bytes" << endl;
            break;
        case LOG_LEVEL_ERROR:
            cout << "Error: Processed " << bytesRead << " bytes" << endl;
            break;
        case LOG_LEVEL_FATAL:
            cout << "Fatal: Processed " << bytesRead << " bytes" << endl;
            break;
    }
}

void handleConnections(vector<Connection> connections, string outputFile, string filterRegex, int bufferSize, int logLevel, int timeout) {
    // Handle each connection in a separate thread
    vector<thread> threads;
    for (int i = 0; i < connections.size(); i++) {
        Connection& connection = connections[i];
        threads.push_back(thread([connection, outputFile, filterRegex, bufferSize, logLevel, timeout]() {
            handleConnection(connection.socket, outputFile, filterRegex, bufferSize, logLevel, timeout);
        }));
    }

    // Wait for all threads to finish
    for (int i = 0; i < threads.size(); i++) {
        threads[i].join();
    }
}

void runServer(string outputFile, string filterRegex, int bufferSize, int maxConnections, int threadCount, int logLevel, int timeout) {
    // Create a socket for the server to listen on
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket < 0) {
        cout << "Error creating socket" << endl;
        return;
    }

    // Set up the address for the server to listen on
    sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_port = htons(DEFAULT_PORT);
    address.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the address and listen for incoming connections
    if (bind(socket, (sockaddr*)&address, sizeof(address)) < 0) {
        cout << "Error binding socket" << endl;
        return;
    }

    if (listen(socket, maxConnections) < 0) {
        cout << "Error listening on socket" << endl;
        return;
    }

    // Set up the thread data structure for managing connections
    ThreadData threadData;
    threadData.connections = vector<Connection>();
    threadData.connectionsMutex = mutex();
    threadData.connectionsCondVar = condition_variable();

    // Start the server in a separate thread
    thread serverThread(thread([socket, &threadData]() {
        while (true) {
            // Accept an incoming connection
            sockaddr_in clientAddress;
            int clientSocket = accept(socket, (sockaddr*)&clientAddress, sizeof(clientAddress));
            if (clientSocket < 0) {
                cout << "Error accepting incoming connection" << endl;
                return;
            }

            // Add the new connection to the list of connections
            Connection newConnection = { clientSocket, true };
            threadData.connectionsMutex.lock();
            threadData.connections.push_back(newConnection);
            threadData.connectionsCondVar.notify_all();
            threadData.connectionsMutex.unlock();
        }
    }));

    // Start the worker threads for processing incoming data
    vector<thread> workerThreads;
    for (int i = 0; i < threadCount; i++) {
        workerThreads.push_back(thread([&threadData, outputFile, filterRegex, bufferSize, logLevel, timeout]() {
            while (true) {
                // Wait for a connection to become available
                Connection connection;
                threadData.connectionsMutex.lock();
                while (threadData.connections.empty()) {
                    threadData.connectionsCondVar.wait(threadData.connectionsMutex);
                }
                connection = threadData.connections[0];
                threadData.connections.erase(threadData.connections.begin());
                threadData.connectionsMutex.unlock();

                // Handle the connection in a separate thread
                handleConnection(connection.socket, outputFile, filterRegex, bufferSize, logLevel, timeout);
            }
        }));
    }

    // Wait for all threads to finish
    serverThread.join();
    for (int i = 0; i < workerThreads.size(); i++) {
        workerThreads[i].join();
    }
}

int main(int argc, char** argv) {
    // Parse command-line options
    if (!parseOptions(argc, argv)) {
        return 1;
    }

    // Run the server
    runServer("", "", 0, 0, 0, 0, -1);

    return 0;
}
