// Define the linked list data structure for storing log entries
typedef struct LogListNode {
    ModemLogEntry *entry;
    struct LogListNode *next;
} LogListNode;

// Define the head node of the linked list
static LogListNode *head = NULL;

// Define a mutex for thread safety
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new entry to the log buffer
void addLogEntry(ModemLogEntry *entry) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&log_mutex);

    // Check if the log buffer is full
    if (head == NULL || head->next == NULL) {
        // If the log buffer is full, resize it by doubling its size
        LogListNode *new_node = malloc(sizeof(LogListNode));
        new_node->entry = entry;
        new_node->next = NULL;
        if (head != NULL) {
            head->next = new_node;
        } else {
            head = new_node;
        }
    } else {
        // If the log buffer is not full, add a new entry to the end of the list
        LogListNode *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(LogListNode));
        current->next->entry = entry;
        current->next->next = NULL;
    }

    // Release the mutex for thread safety
    pthread_mutex_unlock(&log_mutex);
}

// Function to retrieve a log entry by timestamp
ModemLogEntry *getLogEntry(time_t timestamp) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&log_mutex);

    // Iterate through the linked list and find the first entry with a matching timestamp
    LogListNode *current = head;
    while (current != NULL && current->entry->timestamp < timestamp) {
        current = current->next;
    }

    // If an entry was found, return it
    if (current != NULL && current->entry->timestamp == timestamp) {
        ModemLogEntry *result = malloc(sizeof(ModemLogEntry));
        memcpy(result, current->entry, sizeof(ModemLogEntry));
        pthread_mutex_unlock(&log_mutex);
        return result;
    } else {
        // If no entry was found, return NULL
        pthread_mutex_unlock(&log_mutex);
        return NULL;
    }
}

// Function to clear the entire log buffer
void clearLog() {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&log_mutex);

    // Free all nodes in the linked list and set head to NULL
    LogListNode *current = head;
    while (current != NULL) {
        LogListNode *next = current->next;
        free(current);
        current = next;
    }
    head = NULL;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&log_mutex);
}
