function generateUI(configs, container) {
  const elements = [];
  configs.forEach((config) => {
    if (config.type === "button") {
      elements.push(`<button style="${config.style}" onclick="${config.onclick}">${config.text}</button>`);
    } else if (config.type === "input") {
      elements.push(`<input type="${config.type}" value="${config.value}" style="${config.style}" onchange="${config.onchange}">`);
    } else if (config.type === "label") {
      elements.push(`<label for="${config.for}" style="${config.style}">${config.text}</label>`);
    } else if (config.type === "section") {
      const nestedElements = generateUI(config.nested, container);
      elements.push(`<div class="section" style="${config.style}"><h2>${config.title}</h2>${nestedElements}</div>`);
    } else {
      throw new Error(`Invalid configuration type: ${config.type}`);
    }
  });
  container.innerHTML = elements.join("");
  return container.innerHTML;
}
