class NetworkSessionManager {
public:
    // Constructor
    NetworkSessionManager(int maxSessions, int sessionRetentionTime);

    // Destructor
    ~NetworkSessionManager();

    // Add a new session to the manager
    void addSession(const std::string& sessionId, const std::string& clientIp, const std::chrono::time_point<std::chrono::system_clock>& startTime);

    // Retrieve sessions by IP address or session ID
    std::vector<NetworkSession> getSessions(const std::string& ipAddress) const;
    std::vector<NetworkSession> getSessions(const std::string& sessionId) const;

    // Clear all sessions from the manager
    void clearAllSessions();

    // Export session data to a file in JSON format for external analytics tools
    void exportSessionsToFile(const std::string& filename);

private:
    // Maximum number of sessions allowed in the manager
    int maxSessions_;

    // Session retention time in seconds
    int sessionRetentionTime_;

    // Map of IP addresses to a list of sessions for that IP address
    std::unordered_map<std::string, std::vector<NetworkSession>> ipAddressToSessionsMap_;

    // Map of session IDs to sessions
    std::unordered_map<std::string, NetworkSession> sessionIdToSessionMap_;

    // Mutex for thread safety when accessing the session maps
    std::mutex mutex_;

    // Condition variable for signaling when a session has expired and needs to be purged
    std::condition_variable sessionExpiredConditionVariable_;

    // Background task scheduler for automatically purging expired sessions
    void purgeExpiredSessions();

    // Compact the session data structure periodically to reduce memory fragmentation
    void compactSessionDataStructure();

    // Export session data to a file in JSON format
    void exportSessionsToFile(const std::string& filename, const std::vector<NetworkSession>& sessions);
};

// NetworkSession.h
#include <iostream>
#include <string>
#include <chrono>

class NetworkSession {
public:
    // Constructor
    NetworkSession(const std::string& sessionId, const std::string& clientIp, const std::chrono::time_point<std::chrono::system_clock>& startTime);

    // Getters for session ID, client IP address, and start time
    const std::string& getSessionId() const;
    const std::string& getClientIp() const;
    const std::chrono::time_point<std::chrono::system_clock>& getStartTime() const;

    // Setters for session length and description of activities
    void setSessionLength(const std::chrono::duration<double>& sessionLength);
    void setActivitiesDescription(const std::string& activitiesDescription);

private:
    // Session ID
    std::string sessionId_;

    // Client IP address
    std::string clientIp_;

    // Start time of the session
    std::chrono::time_point<std::chrono::system_clock> startTime_;

    // Length of the session in seconds
    std::chrono::duration<double> sessionLength_;

    // Description of activities during the session
    std::string activitiesDescription_;
};

// NetworkSessionManager.cpp
#include "NetworkSessionManager.h"

NetworkSessionManager::NetworkSessionManager(int maxSessions, int sessionRetentionTime) :
    maxSessions_(maxSessions),
    sessionRetentionTime_(sessionRetentionTime) {
}

NetworkSessionManager::~NetworkSessionManager() {
    // Clear all sessions from the manager
    clearAllSessions();
}

void NetworkSessionManager::addSession(const std::string& sessionId, const std::string& clientIp, const std::chrono::time_point<std::chrono::system_clock>& startTime) {
    // Lock the mutex to ensure thread safety when accessing the session maps
    std::lock_guard<std::mutex> lock(mutex_);

    // Check if the maximum number of sessions has been reached
    if (ipAddressToSessionsMap_.size() >= maxSessions_) {
        throw std::runtime_error("Maximum number of sessions reached");
    }

    // Create a new session and add it to the maps
    NetworkSession newSession(sessionId, clientIp, startTime);
    ipAddressToSessionsMap_[clientIp].push_back(newSession);
    sessionIdToSessionMap_[sessionId] = newSession;
}

std::vector<NetworkSession> NetworkSessionManager::getSessions(const std::string& ipAddress) const {
    // Lock the mutex to ensure thread safety when accessing the session maps
    std::lock_guard<std::mutex> lock(mutex_);

    // Check if the IP address is valid and has sessions associated with it
    auto it = ipAddressToSessionsMap_.find(ipAddress);
    if (it == ipAddressToSessionsMap_.end()) {
        return {};
    }

    // Return a copy of the vector of sessions for the IP address
    return it->second;
}

std::vector<NetworkSession> NetworkSessionManager::getSessions(const std::string& sessionId) const {
    // Lock the mutex to ensure thread safety when accessing the session maps
    std::lock_guard<std::mutex> lock(mutex_);

    // Check if the session ID is valid and has a corresponding session
    auto it = sessionIdToSessionMap_.find(sessionId);
    if (it == sessionIdToSessionMap_.end()) {
        return {};
    }

    // Return a copy of the session
    return std::vector<NetworkSession>{it->second};
}

void NetworkSessionManager::clearAllSessions() {
    // Lock the mutex to ensure thread safety when accessing the session maps
    std::lock_guard<std::mutex> lock(mutex_);

    // Clear all sessions from the maps
    ipAddressToSessionsMap_.clear();
    sessionIdToSessionMap_.clear();
}

void NetworkSessionManager::exportSessionsToFile(const std::string& filename) {
    // Lock the mutex to ensure thread safety when accessing the session maps
    std::lock_guard<std::mutex> lock(mutex_);

    // Open the file for writing and export the sessions
    std::ofstream outFile(filename, std::ios::out | std::ios::trunc);
    if (!outFile.is_open()) {
        throw std::runtime_error("Failed to open file for writing");
    }

    // Export each session to the file
    for (const auto& ipAddress : ipAddressToSessionsMap_) {
        for (const auto& session : ipAddress.second) {
            outFile << session.getSessionId() << ",";
            outFile << session.getClientIp() << ",";
            outFile << std::chrono::duration_cast<std::chrono::seconds>(session.getStartTime().time_since_epoch()).count();
            outFile << ",";
            outFile << session.getSessionLength().count();
            outFile << ",";
            outFile << session.getActivitiesDescription() << std::endl;
        }
    }
}

void NetworkSessionManager::purgeExpiredSessions() {
    // Lock the mutex to ensure thread safety when accessing the session maps
    std::lock_guard<std::mutex> lock(mutex_);

    // Iterate over each IP address and remove any expired sessions
    for (auto it = ipAddressToSessionsMap_.begin(); it != ipAddressToSessionsMap_.end();) {
        auto& sessions = it->second;
        for (auto sessionIt = sessions.begin(); sessionIt != sessions.end();) {
            if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - sessionIt->getStartTime()).count() > sessionRetentionTime_) {
                // Remove the expired session from the maps
                sessionIdToSessionMap_.erase(sessionIt->getSessionId());
                sessions.erase(sessionIt);
            } else {
                ++sessionIt;
            }
        }

        // If there are no more sessions for this IP address, remove it from the map
        if (sessions.empty()) {
            ipAddressToSessionsMap_.erase(it++);
        } else {
            ++it;
        }
    }
}

void NetworkSessionManager::compactSessionDataStructure() {
    // Lock the mutex to ensure thread safety when accessing the session maps
    std::lock_guard<std::mutex> lock(mutex_);

    // Iterate over each IP address and remove any expired sessions
    for (auto it = ipAddressToSessionsMap_.begin(); it != ipAddressToSessionsMap_.end();) {
        auto& sessions = it->second;
        for (auto sessionIt = sessions.begin(); sessionIt != sessions.end();) {
            if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - sessionIt->getStartTime()).count() > sessionRetentionTime_) {
                // Remove the expired session from the maps
                sessionIdToSessionMap_.erase(sessionIt->getSessionId());
                sessions.erase(sessionIt);
            } else {
                ++sessionIt;
            }
        }

        // If there are no more sessions for this IP address, remove it from the map
        if (sessions.empty()) {
            ipAddressToSessionsMap_.erase(it++);
        } else {
            ++it;
        }
    }
}

void NetworkSessionManager::exportSessionsToFile(const std::string& filename, const std::vector<NetworkSession>& sessions) {
    // Lock the mutex to ensure thread safety when accessing the session maps
    std::lock_guard<std::mutex> lock(mutex_);

    // Open the file for writing and export the sessions
    std::ofstream outFile(filename, std::ios::out | std::ios::trunc);
    if (!outFile.is_open()) {
        throw std::runtime_error("Failed to open file for writing");
    }

    // Export each session to the file
    for (const auto& session : sessions) {
        outFile << session.getSessionId() << ",";
        outFile << session.getClientIp() << ",";
        outFile << std::chrono::duration_cast<std::chrono::seconds>(session.getStartTime().time_since_epoch()).count();
        outFile << ",";
        outFile << session.getSessionLength().count();
        outFile << ",";
        outFile << session.getActivitiesDescription() << std::endl;
    }
}

