#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define a structure to represent a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define a dynamic array of ModemLogEntry structures
typedef struct {
    ModemLogEntry** entries;
    size_t capacity;
    size_t count;
} DynamicArray;

// Function to add a new log entry to the dynamic array
void addLogEntry(DynamicArray* array, time_t timestamp, int level, char* message) {
    // Check if the array is full and needs to be resized
    if (array->count == array->capacity) {
        // Double the capacity of the array
        array->capacity *= 2;
        // Reallocate memory for the entries
        array->entries = realloc(array->entries, array->capacity * sizeof(ModemLogEntry*));
    }

    // Create a new log entry and add it to the array
    ModemLogEntry* entry = malloc(sizeof(ModemLogEntry));
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = message;
    array->entries[array->count++] = entry;
}

// Function to retrieve a log entry from the dynamic array by timestamp
ModemLogEntry* getLogEntry(DynamicArray* array, time_t timestamp) {
    // Iterate through the entries in the array and find the one with the matching timestamp
    for (size_t i = 0; i < array->count; i++) {
        if (array->entries[i]->timestamp == timestamp) {
            return array->entries[i];
        }
    }

    // If no entry is found, return NULL
    return NULL;
}

// Function to clear the entire log by freeing all allocated memory
void clearLog(DynamicArray* array) {
    for (size_t i = 0; i < array->count; i++) {
        free(array->entries[i]);
    }
    array->count = 0;
}

// Function to limit the number of entries in the log to a specified maximum size
void limitLogSize(DynamicArray* array, size_t maxSize) {
    // If the current size of the array is less than or equal to the maximum size, do nothing
    if (array->count <= maxSize) {
        return;
    }

    // Otherwise, remove excess entries from the end of the array
    for (size_t i = 0; i < array->count - maxSize; i++) {
        free(array->entries[i]);
    }
    array->count -= array->count - maxSize;
}

// Function to automatically purge old entries from the log to free up resources
void purgeOldEntries(DynamicArray* array, time_t duration) {
    // Get the current timestamp
    time_t now = time(NULL);

    // Iterate through the entries in the array and find those that are older than the specified duration
    for (size_t i = 0; i < array->count; i++) {
        if (array->entries[i]->timestamp + duration <= now) {
            free(array->entries[i]);
            array->count--;
            i--;
        }
    }
}

// Function to export the log entries to a file in a standardized format for external analysis tools
void exportLogEntries(DynamicArray* array, FILE* file) {
    // Iterate through the entries in the array and write them to the file
    for (size_t i = 0; i < array->count; i++) {
        fprintf(file, "%lu %d %s\n", array->entries[i]->timestamp, array->entries[i]->level, array->entries[i]->message);
    }
}

// Function to reduce memory fragmentation by periodically compacting the log structure
void compactLog(DynamicArray* array) {
    // Create a new dynamic array with a smaller capacity than the original one
    DynamicArray* newArray = malloc(sizeof(DynamicArray));
    newArray->capacity = array->count;
    newArray->entries = malloc(newArray->capacity * sizeof(ModemLogEntry*));

    // Copy the entries from the original array to the new one, ensuring that they are contiguous in memory
    for (size_t i = 0; i < array->count; i++) {
        newArray->entries[i] = malloc(sizeof(ModemLogEntry));
        memcpy(newArray->entries[i], array->entries[i], sizeof(ModemLogEntry));
    }

    // Free the original array and replace it with the new one
    free(array);
    array = newArray;
}

// Function to free allocated memory to prevent leaks
void freeLog(DynamicArray* array) {
    for (size_t i = 0; i < array->count; i++) {
        free(array->entries[i]);
    }
    free(array);
}
