}

// Function to purge old entries from the log
void purgeOldEntries(Log* log) {
    // Calculate the number of days to keep logs
    int numDaysToKeep = 30;

    // Get the current time
    time_t now = time(NULL);

    // Iterate through the log entries and purge old entries
    for (size_t i = 0; i < log->size; i++) {
        NetworkTraffic* entry = &log->entries[i];
        if (now - entry->timestamp > numDaysToKeep * 24 * 60 * 60) {
            // Remove the old entry from the log
            memmove(&log->entries[i], &log->entries[i + 1], sizeof(NetworkTraffic) * (log->size - i));
            log->size--;
