    // If the current size of the log is greater than the maximum size, remove excess entries
    if (log->size > maxSize) {
        log->size = maxSize;
    }
}

// Define the function to purge old entries from the log
void purgeOldEntries(LogData* log, uint64_t duration) {
    // Iterate through the log entries and remove any that are older than the specified duration
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i].timestamp <= duration) {
            // Remove the entry from the log
            memmove(&log->entries[i], &log->entries[i + 1], sizeof(NetworkTraffic) * (log->size - i));
            log->size--;
        }
    }
}

// Define the function to filter logs based on a specified protocol type
void filterLogs(LogData* log, uint8_t protocolType) {
    // Iterate through the log entries and remove any that do not match the specified protocol type
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i].protocolType != protocolType) {
            // Remove the entry from the log
            memmove(&log->entries[i], &log->entries[i + 1], sizeof(NetworkTraffic) * (log->size - i));
            log->size--;
        }
    }
}

// Define the function to export logs in a specific format for external analysis tools
void exportLogs(LogData* log, char* filename) {
    // Open the file for writing and write the log entries to it
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    for (int i = 0; i < log->size; i++) {
        NetworkTraffic* entry = &log->entries[i];
        fprintf(fp, "%u,%u,%llu,%hu,%hhu\n", entry->sourceIP, entry->destinationIP, entry->timestamp, entry->packetSize, entry->protocolType);
    }

    // Close the file and return
    fclose(fp);
}
