#include <algorithm>

class NetworkTransactionManager {
public:
    // Constructor
    NetworkTransactionManager(size_t maxSize, size_t encryptionKeyLength) :
        maxSize_(maxSize), encryptionKeyLength_(encryptionKeyLength) {}

    // Add a new transaction to the collection
    void addTransaction(const NetworkTransaction& transaction) {
        std::lock_guard<std::mutex> lock(mutex_);
        transactions_.push_back(transaction);
        if (transactions_.size() > maxSize_) {
            // Remove oldest transaction
            transactions_.erase(transactions_.begin());
        }
    }

    // Retrieve all transactions from a specific source IP address
    std::vector<NetworkTransaction> getTransactionsBySourceIP(const std::string& sourceIP) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<NetworkTransaction> result;
        for (auto it = transactions_.begin(); it != transactions_.end(); ++it) {
            if (it->sourceIP == sourceIP) {
                result.push_back(*it);
            }
        }
        return result;
    }

    // Retrieve all transactions to a specific destination IP address
    std::vector<NetworkTransaction> getTransactionsByDestinationIP(const std::string& destinationIP) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<NetworkTransaction> result;
        for (auto it = transactions_.begin(); it != transactions_.end(); ++it) {
            if (it->destinationIP == destinationIP) {
                result.push_back(*it);
            }
        }
        return result;
    }

    // Clear all transactions from the collection
    void clearTransactions() {
        std::lock_guard<std::mutex> lock(mutex_);
        transactions_.clear();
    }

private:
    // Maximum size of the transaction collection
    const size_t maxSize_;

    // Encryption key length for encrypting transaction payloads
    const size_t encryptionKeyLength_;

    // Vector to store all transactions
    std::vector<NetworkTransaction> transactions_;

    // Mutex to ensure thread safety
    std::mutex mutex_;
};
