// Define a list data structure to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
} NFAPI_CRC_INDICATION_LIST_T;

// Define a mutex to ensure thread-safe access to the list
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *create_crc_indication_list(size_t capacity) {
    // Allocate memory for the list data structure
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        return NULL;
    }

    // Initialize the list capacity and size to 0
    list->capacity = capacity;
    list->size = 0;

    // Allocate memory for the data array
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (!list->data) {
        free(list);
        return NULL;
    }

    return list;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the list
void add_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t rx_ue_information_tag, uint32_t rnti, uint8_t crc_indication_rel8_tag, uint8_t crcflag) {
    // Acquire the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&list_mutex);

    // Check if the list is full
    if (list->size == list->capacity) {
        // If the list is full, double its capacity and reallocate memory for the data array
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_data) {
            // If the reallocation fails, free the old data and return
            free(list->data);
            list->data = NULL;
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        // Update the list capacity and data array
        list->capacity = new_capacity;
        list->data = new_data;
    }

    // Add a new NFAPI_CRC_INDICATION_PDU_T structure to the list
    list->data[list->size].rx_ue_information_tag = rx_ue_information_tag;
    list->data[list->size].rnti = rnti;
    list->data[list->size].crc_indication_rel8_tag = crc_indication_rel8_tag;
    list->data[list->size].crcflag = crcflag;
    list->data[list->size].timestamp = time(NULL);
    list->size++;

