            if (socket == ERROR_CODE) {
                perror("Error creating socket");
                exit(ERROR_CODE);
            }

            // Set the socket to be reusable
            int option = 1;
            setsockopt(socket, SOL_SOCKET, SO_REUSEADDR, &option, sizeof(option));

            // Bind the socket to the specified port
            sockaddr_in address;
            address.sin_family = AF_INET;
            address.sin_port = htons(stoi(port));
            address.sin_addr.s_addr = INADDR_ANY;

            if (bind(socket, (sockaddr*)&address, sizeof(address)) == ERROR_CODE) {
                perror("Error binding socket");
                exit(ERROR_CODE);
            }

            // Listen on the socket for incoming connections
            if (listen(socket, maxConnections) == ERROR_CODE) {
                perror("Error listening on socket");
                exit(ERROR_CODE);
            }

            sockets.push_back(socket);
        }

        // Set the vector of sockets as a class variable
        this->sockets = sockets;
    }

    // Function to initialize the output directory for writing records
    void initOutputDirectory() {
        // Create the output directory if it does not exist
        if (!exists(outputDirectory)) {
            create_directory(outputDirectory);
        }

        // Set the output directory as a class variable
        this->outputDirectory = outputDirectory;
    }

    // Function to initialize the filter regular expression for filtering lines
    void initFilterRegex() {
        // Compile the filter regular expression
        regex_t filterRegexCompiled;
        if (regcomp(&filterRegexCompiled, filterRegex.c_str(), REG_EXTENDED | REG_NOSUB) != 0) {
            perror("Error compiling filter regular expression");
            exit(ERROR_CODE);
        }

        // Set the compiled filter regular expression as a class variable
        this->filterRegexCompiled = filterRegexCompiled;
    }

    // Function to initialize the buffer size for reading files in chunks
    void initBufferSize() {
        // Set the buffer size as a class variable
        this->bufferSize = bufferSize;
    }

    // Function to initialize the maximum number of simultaneous connections
    void initMaxConnections() {
        // Set the maximum number of simultaneous connections as a class variable
        this->maxConnections = maxConnections;
    }

    // Function to initialize the number of worker threads for processing records
    void initThreadCount() {
        // Set the number of worker threads as a class variable
        this->threadCount = threadCount;
    }

    // Function to handle incoming connections and process records in parallel
    void handleConnections() {
        // Initialize a vector of threads to store the worker threads
        vector<thread> threads;

        // Iterate over the sockets and create a new thread for each one
        for (auto socket : sockets) {
            threads.push_back(thread([this, socket]() {
                // Initialize a vector of records to store the processed records
                vector<Record> records;

                // Read data from the socket in chunks and process each record
                while (true) {
                    // Read data from the socket in chunks
                    char buffer[bufferSize];
                    int bytesRead = read(socket, buffer, bufferSize);

                    if (bytesRead == ERROR_CODE) {
                        perror("Error reading from socket");
                        exit(ERROR_CODE);
                    } else if (bytesRead == 0) {
                        // Close the socket and break out of the loop if there is no more data to read
                        close(socket);
                        break;
                    }

                    // Process each record in parallel using a worker thread
                    for (auto& record : split(buffer, '\n')) {
                        threads.push_back(thread([this, &records, record]() {
                            // Filter lines based on the regular expression if necessary
                            if (!filterRegex.empty()) {
                                regex_t filterRegexCompiled = this->filterRegexCompiled;
                                if (regexec(&filterRegexCompiled, record.c_str(), 0, NULL, 0) == REG_NOMATCH) {
                                    return;
                                }
                            }

                            // Calculate the MD5 hash of each record
                            unsigned char md5[MD5_DIGEST_LENGTH];
                            MD5((unsigned char*)record.c_str(), record.length(), md5);

                            // Add the record to the vector of records
                            records.push_back({record, md5});
                        }));
                    }
                }

                // Join all worker threads and write the processed records to a file
                for (auto& thread : threads) {
                    thread.join();
                }

                string filename = outputDirectory + "/" + to_string(socket);
                ofstream outfile(filename, ios::out | ios::binary);

                if (!outfile) {
                    perror("Error opening output file");
                    exit(ERROR_CODE);
                }

                for (auto& record : records) {
                    outfile.write((char*)record.data.c_str(), record.data.length());
                    outfile.write((char*)record.md5, MD5_DIGEST_LENGTH);
                }

                outfile.close();
            }));
        }

        // Join all worker threads and close the sockets
        for (auto& thread : threads) {
            thread.join();
        }

        for (auto socket : sockets) {
            close(socket);
        }
    }

    // Function to split a string into substrings based on a delimiter character
    vector<string> split(const string& s, char delim) {
        vector<string> elems;
        stringstream ss(s);
        string item;

        while (getline(ss, item, delim)) {
            elems.push_back(item);
        }

        return elems;
    }

    // Function to determine a Pokemon's weaknesses using a switch statement based on its type
    vector<string> getWeaknesses(const string& pokemonType) {
        vector<string> weaknesses;

        switch (pokemonType[0]) {
            case 'F':
                weaknesses.push_back("Fire");
                break;
            case 'G':
                weaknesses.push_back("Grass");
                break;
            case 'I':
                weaknesses.push_back("Ice");
                break;
            case 'L':
                weaknesses.push_back("Lightning");
                break;
            case 'P':
                weaknesses.push_back("Poison");
                break;
            case 'R':
                weaknesses.push_back("Rock");
                break;
            case 'S':
                weaknesses.push_back("Steel");
                break;
            case 'W':
                weaknesses.push_back("Water");
                break;
        }

        return weaknesses;
    }
};

int main() {
    // Initialize the Pokemon class with the command-line arguments
    Pokemon pokemon(argc, argv);

    // Handle incoming connections and process records in parallel
    pokemon.handleConnections();

    return 0;
}
```

