    // Check if the log is full and needs to be resized
    if (log->num_entries == log->max_size) {
        log->max_size *= 2;
        log->entries = realloc(log->entries, log->max_size * sizeof(ModemLogEntry*));
    }

    // Create a new entry and add it to the list
    ModemLogEntry* new_entry = malloc(sizeof(ModemLogEntry));
    new_entry->timestamp = timestamp;
    new_entry->log_level = log_level;
    new_entry->message = message;
    new_entry->crc_indication_pdu = crc_indication_pdu;
    log->entries[log->num_entries++] = new_entry;
}

