// Define constants for command line options
#define OPTION_MANPAGE "--manpage"
#define OPTION_CS "--cs"
#define OPTION_O "--o"

// Define constants for error messages
#define ERROR_INVALID_FILE "Invalid input file provided. Please provide a valid file path."
#define ERROR_CORRUPTED_DATA "Corrupted data encountered during processing. Please check the input file."
#define ERROR_SYSTEM "Unexpected system error encountered during execution. Please try again later."

