    char *output_file;
    int manpage;
    int cs;
} config_t;

// Function to parse command line arguments and return a config_t struct
config_t parse_args(int argc, char **argv) {
    // Initialize default values for configuration settings
    config_t config = {NULL, NULL, 0, 0};

    // Iterate over command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], OPTION_MANPAGE) == 0) {
            config.manpage = 1;
        } else if (strcmp(argv[i], OPTION_CS) == 0) {
            config.cs = 1;
        } else if (strcmp(argv[i], OPTION_O) == 0 && i + 1 < argc) {
            config.output_file = argv[i + 1];
        } else {
            config.input_file = argv[i];
        }
    }

    // Validate configuration settings and return struct
    if (config.input_file == NULL || strlen(config.input_file) == 0) {
        fprintf(stderr, ERROR_INVALID_FILE);
        exit(1);
    } else if (config.output_file != NULL && strlen(config.output_file) == 0) {
        fprintf(stderr, "Invalid output file provided. Please provide a valid file path.");
        exit(1);
    }
    return config;
}

