}

// Function to implement thread safety measures for concurrent file reading
void* read_file_thread(void *args) {
    // Cast arguments to appropriate types
    char **input_files = (char **) args;
    FILE *input_file = fopen(input_files[0], "r");

    // Check for errors and handle appropriately
    if (input_file == NULL) {
        handle_error("Error opening input file.");
        return NULL;
    }

    // Read input file line by line and count lines
    process_input_file(input_file);

    // Close input file and return
    fclose(input_file);
    return NULL;
}

// Function to handle concurrency for reading multiple files concurrently
void read_files_concurrently(char **input_files, int num_files) {
    // Initialize variables for thread management
    pthread_t threads[num_files];
    void *status;

    // Create threads for each input file and start execution
    for (int i = 0; i < num_files; i++) {
        if (pthread_create(&threads[i], NULL, read_file_thread, &input_files[i])) {
            handle_error("Error creating thread.");
            return;
        }
    }

    // Join threads and handle any errors that may occur
    for (int i = 0; i < num_files; i++) {
        if (pthread_join(threads[i], &status)) {
            handle_error("Error joining thread.");
            return;
        }
    }
}

