// Define the structure for a network session
typedef struct NetworkSession {
    uint32_t session_id;
    time_t connection_timestamp;
    char client_ip[16]; // IPv4 or IPv6 address
    void* data; // variable-length data payload
} NetworkSession;

// Define the maximum number of active sessions
#define MAX_ACTIVE_SESSIONS 1000

// Define the duration for which a session is considered expired
#define SESSION_EXPIRATION_DURATION (60 * 60) // 1 hour in seconds

// Define the frequency for purging expired sessions
#define PURGE_EXPIRED_SESSIONS_FREQUENCY (30 * 60) // 30 minutes in seconds

// Define the frequency for compacting the session pool
#define COMPACT_SESSION_POOL_FREQUENCY (15 * 60) // 15 minutes in seconds

// Define the maximum size of the session data payload
#define MAX_DATA_PAYLOAD_SIZE 1024

// Define the structure for a linked list node
typedef struct LinkedListNode {
    NetworkSession* session;
    struct LinkedListNode* next;
} LinkedListNode;

// Define the head and tail pointers of the linked list
static LinkedListNode* head = NULL;
static LinkedListNode* tail = NULL;

// Define a mutex for thread-safe access to the linked list
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new session to the linked list
void addSession(NetworkSession* session) {
    // Acquire the mutex for thread-safe access to the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node for the session
    LinkedListNode* node = malloc(sizeof(LinkedListNode));
    node->session = session;
    node->next = NULL;

    // If the linked list is empty, set the head and tail pointers to the new node
    if (head == NULL) {
        head = node;
        tail = node;
    } else {
        // Otherwise, add the new node to the end of the linked list
        tail->next = node;
        tail = node;
    }

    // Release the mutex for thread-safe access to the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a session from the linked list by client IP address
NetworkSession* getSessionByClientIP(const char* client_ip) {
    // Acquire the mutex for thread-safe access to the linked list
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list until a matching session is found
    LinkedListNode* node = head;
    while (node != NULL) {
        if (strcmp(node->session->client_ip, client_ip) == 0) {
            // Release the mutex for thread-safe access to the linked list
            pthread_mutex_unlock(&mutex);

            return node->session;
        }
        node = node->next;
    }

    // Release the mutex for thread-safe access to the linked list
    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Function to clear all sessions from the linked list
void clearSessions() {
    // Acquire the mutex for thread-safe access to the linked list
    pthread_mutex_lock(&mutex);

    // Free the memory allocated to each session in the linked list
    LinkedListNode* node = head;
    while (node != NULL) {
        NetworkSession* session = node->session;
        free(session->data);
        free(session);
        node = node->next;
    }

    // Reset the head and tail pointers to NULL
    head = NULL;
    tail = NULL;

    // Release the mutex for thread-safe access to the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to limit the number of active sessions to a specified maximum size
void limitActiveSessions(int max_active_sessions) {
    // Acquire the mutex for thread-safe access to the linked list
    pthread_mutex_lock(&mutex);

    // If the current number of active sessions is greater than the maximum, remove excess sessions
    if (getActiveSessionCount() > max_active_sessions) {
        LinkedListNode* node = head;
        while (node != NULL && getActiveSessionCount() > max_active_sessions) {
            NetworkSession* session = node->session;
            free(session->data);
            free(session);
            node = node->next;
        }
    }

    // Release the mutex for thread-safe access to the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to filter sessions based on a specified client IP range
void filterSessionsByClientIPRange(const char* client_ip_range) {
    // Acquire the mutex for thread-safe access to the linked list
