} LogList;

// Define the function to add a new entry to the log list
void add_log_entry(LogList* log, time_t timestamp, int log_level, char* message, NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu) {
    // Check if the log is full
    if (log->size == log->capacity) {
        // If the log is full, purge old entries to make room for new ones
        purge_old_entries(log);
    }

    // Add a new entry to the log list
    ModemLogEntry* new_entry = malloc(sizeof(ModemLogEntry));
    new_entry->timestamp = timestamp;
    new_entry->log_level = log_level;
    new_entry->message = message;
    new_entry->crc_indication_pdu = crc_indication_pdu;
    log->entries[log->size++] = new_entry;
}

// Define the function to retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(LogList* log, time_t timestamp) {
    // Iterate through the log entries and find the one with the matching timestamp
    for (int i = 0; i < log->size; i++) {
        if (log->entries[i]->timestamp == timestamp) {
            return log->entries[i];
        }
    }

    // If no entry is found, return NULL
    return NULL;
}

