    // Free all the memory allocated for the log entries
    for (int i = 0; i < log->size; i++) {
        free(log->entries[i]);
    }

    // Reset the size and capacity of the log list
    log->size = 0;
    log->capacity = MAX_LOG_SIZE;
}

// Define the function to purge old entries from the log list
void purge_old_entries(LogList* log) {
    // If the log is not full, do nothing
    if (log->size < log->capacity) {
        return;
    }

    // Sort the log entries by timestamp in descending order
    qsort(log->entries, log->size, sizeof(ModemLogEntry*), compare_log_entries);

    // Purge old entries until the log is not full
    for (int i = 0; i < log->size - 1; i++) {
        if (log->entries[i]->timestamp < time(NULL) - LOG_RETENTION_DURATION) {
            free(log->entries[i]);
            log->size--;
        } else {
            break;
        }
    }
}

// Define the function to compact the log structure
void compact_log(LogList* log) {
    // If the log is not full, do nothing
    if (log->size < log->capacity) {
        return;
    }

    // Sort the log entries by timestamp in descending order
    qsort(log->entries, log->size, sizeof(ModemLogEntry*), compare_log_entries);

    // Compact the log structure by removing duplicate entries
    for (int i = 0; i < log->size - 1; i++) {
        if (log->entries[i]->timestamp == log->entries[i + 1]->timestamp) {
            free(log->entries[i]);
            log->size--;
            memmove(&log->entries[i], &log->entries[i + 1], sizeof(ModemLogEntry*) * (log->size - i));
        }
    }
}

