void handle_edge_cases(LogList* log) {
    // If the log is full, purge old entries to make room for new ones
    if (log->size == log->capacity) {
        purge_old_entries(log);
    }

    // If the log is not full, ensure that it has enough capacity to accommodate new entries
    if (log->size < log->capacity) {
