void maintain_thread_safety(LogList* log) {
    // Use a semaphore to synchronize access to the log list
    sem_t* semaphore = sem_open("log_semaphore", O_CREAT, 0644, 1);
    if (semaphore == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(EXIT_FAILURE);
    }

    // Acquire the semaphore before accessing the log list
    int ret = sem_wait(semaphore);
    if (ret == -1) {
        perror("Failed to acquire semaphore");
        exit(EXIT_FAILURE);
    }

    // Release the semaphore after accessing the log list
    ret = sem_post(semaphore);
    if (ret == -1) {
