    entry->timestamp = timestamp;
    entry->log_level = log_level;
    entry->message = message;
    entry->crc_indication_pdu = crc_indication_pdu;
    list->entries[list->size++] = entry;
}

// Define the function to retrieve a log entry by timestamp
ModemLogEntry *get_log_entry(LogList *list, time_t timestamp) {
    // Iterate through the list of entries and find the one with the matching timestamp
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->timestamp == timestamp) {
            return list->entries[i];
        }
    }

    // If no entry is found, return NULL
    return NULL;
}

// Define the function to retrieve a log entry by RNTI uniqueness
ModemLogEntry *get_log_entry_by_rnti(LogList *list, int rnti) {
    // Iterate through the list of entries and find the one with the matching RNTI
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->crc_indication_pdu->rx_ue_information.rnti == rnti) {
            return list->entries[i];
        }
    }

    // If no entry is found, return NULL
    return NULL;
}

// Define the function to clear the log list
void clear_log(LogList *list) {
    // Free all entries in the list
    for (int i = 0; i < list->size; i++) {
        free(list->entries[i]);
    }

    // Reset the size and capacity of the list
    list->size = 0;
    list->capacity = MAX_LOG_SIZE;
}

// Define the function to purge old entries from the log list
void purge_old_entries(LogList *list) {
    // Sort the list by timestamp in descending order
    qsort(list->entries, list->size, sizeof(ModemLogEntry), compare_log_entry_by_timestamp);

    // Purge old entries until the list size is less than or equal to the maximum capacity
    for (int i = 0; i < list->size - MAX_LOG_SIZE; i++) {
        free(list->entries[i]);
    }

    // Reduce the size of the list by the number of purged entries
    list->size -= (list->size - MAX_LOG_SIZE);
}

// Define the function to compact the log structure
void compact_log(LogList *list) {
    // Sort the list by timestamp in descending order
    qsort(list->entries, list->size, sizeof(ModemLogEntry), compare_log_entry_by_timestamp);

    // Compact the list by removing duplicate entries
    for (int i = 0; i < list->size - 1; i++) {
        if (list->entries[i]->timestamp == list->entries[i + 1]->timestamp) {
            free(list->entries[i]);
            memmove(&list->entries[i], &list->entries[i + 1], sizeof(ModemLogEntry));
            list->size--;
        }
    }
}

