void handle_external_logging(LogList *list) {
    // Check if an external logging service is available and use it if necessary
    if (external_logging_service_available()) {
        export_logs_to_file(list);
    } else {
        // If the external logging service is not available, log to a local file instead
        int fd = open("local_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (fd == -1) {
            perror("Error opening local log file");
            return;
