        // If the dataset is full, remove the oldest entry
        SensorDataPoint *oldest = &dataset[0];
        for (int i = 1; i < dataset_size; i++) {
            if (dataset[i].timestamp < oldest->timestamp) {
                oldest = &dataset[i];
            }
        }
        // Remove the oldest entry from the dataset
        memmove(oldest, oldest + 1, sizeof(SensorDataPoint) * (dataset_size - (oldest - dataset)));
        dataset_size--;
    }
    // Add the new sensor data point to the end of the dataset
    SensorDataPoint *new_point = &dataset[dataset_size];
    new_point->timestamp = timestamp;
    new_point->sensor_id = sensor_id;
    new_point->measurement = measurement;
