        int num_to_remove = 0;
        time_t current_time = time(NULL);
        for (int i = 0; i < dataset_size; i++) {
            if (current_time - dataset[i].timestamp > RETENTION_POLICY * 24 * 60 * 60) {
                num_to_remove++;
            } else {
                break;
            }
        }
        // Remove the oldest entries from the dataset
        memmove(dataset, dataset + num_to_remove, sizeof(SensorDataPoint) * (dataset_size - num_to_remove));
        dataset_size -= num_to_remove;
    }
}

