        }
        mean[dataset[i].sensor_id] += dataset[i].measurement;
        stddev[dataset[i].sensor_id] += pow(dataset[i].measurement - mean[dataset[i].sensor_id], 2);
    }
    for (int i = 0; i < num_sensor_types; i++) {
        mean[i] /= dataset_size;
        stddev[i] = sqrt(stddev[i] / (dataset_size - 1));
    }
    // Iterate through the dataset and flag outliers based on the statistical thresholds
    for (int i = 0; i < dataset_size; i++) {
        if (fabs(dataset[i].measurement - mean[dataset[i].sensor_id]) > STATISTICAL_THRESHOLD * stddev[dataset[i].sensor_id]) {
