// Define the function for allocating a new element in the dynamic resource pool
void DynamicResourcePoolManager_allocate(DynamicResourcePoolManager* pool) {
    // Acquire the mutex for protecting concurrent access to the pool
    pthread_mutex_lock(&pool->mutex);

    // Check if there is enough space in the pool for a new element
    if (pool->num_elements < pool->offset_size) {
        // Generate a random offset value within the specified range
        int offset = generateRandomNumber(pool->min_value, pool->max_value);

        // Generate a random key value within the specified range
        int key = generateRandomNumber(pool->min_value, pool->max_value);

        // Generate a random record value within the specified range
        int record = generateRandomNumber(pool->min_value, pool->max_value);

        // Add the new element to the pool
        pool->offsets[pool->num_elements].offset = offset;
        pool->keys[pool->num_elements].key = key;
        pool->records[pool->num_elements].value = record;

        // Increment the number of elements in the pool
        pool->num_elements++;
    } else {
        // Release the mutex for protecting concurrent access to the pool
        pthread_mutex_unlock(&pool->mutex);

        // Print an error message if there is no space in the pool for a new element
        printf("Error: No space in the dynamic resource pool\n");
    }
}

// Define the function for deallocating an element from the dynamic resource pool
void DynamicResourcePoolManager_deallocate(DynamicResourcePoolManager* pool, int index) {
    // Acquire the mutex for protecting concurrent access to the pool
    pthread_mutex_lock(&pool->mutex);

    // Check if the specified index is valid
    if (index >= 0 && index < pool->num_elements) {
        // Remove the element from the pool
        pool->offsets[index] = pool->offsets[pool->num_elements - 1];
        pool->keys[index] = pool->keys[pool->num_elements - 1];
        pool->records[index] = pool->records[pool->num_elements - 1];

        // Decrement the number of elements in the pool
        pool->num_elements--;
    } else {
        // Release the mutex for protecting concurrent access to the pool
        pthread_mutex_unlock(&pool->mutex);

        // Print an error message if the specified index is invalid
        printf("Error: Invalid index in dynamic resource pool\n");
    }
}

