import java.util.*;
import java.util.concurrent.*;

public class CacheManager {
    private static final int MAX_CACHE_SIZE = 1000; // maximum number of cache entries
    private static final long EXPIRATION_TIME = 3600000L; // expiration time in milliseconds
    private static final String[] VALID_CONTENT_TYPES = {"text/plain", "application/json"}; // valid content types

    private Map<String, CacheEntry> cache; // map of cache entries by key
    private long totalSize; // total size of all cache entries in bytes
    private int numEntries; // number of cache entries
    private boolean isFull; // flag indicating whether the cache is full

    public CacheManager() {
        this.cache = new ConcurrentHashMap<>();
        this.totalSize = 0L;
        this.numEntries = 0;
        this.isFull = false;
    }

    public void addEntry(String key, String contentType, byte[] data) {
        if (key == null || contentType == null || data == null) {
            throw new IllegalArgumentException("Invalid input: key, content type, or data cannot be null");
        }

        // check if the cache is full and evict outdated or least recently used entries if necessary
        if (isFull()) {
            evictEntries();
        }

        // create a new cache entry and add it to the map
        CacheEntry entry = new CacheEntry(key, contentType, data);
        cache.put(key, entry);

        // update the total size and number of entries
        totalSize += entry.getSize();
        numEntries++;
    }

    public byte[] getEntry(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Invalid input: key cannot be null");
        }

        // check if the cache contains the requested entry
        CacheEntry entry = cache.get(key);
        if (entry == null) {
            return null;
        }

        // update the last accessed time and return the data
        entry.setLastAccessedTime();
        return entry.getData();
    }

    public void evictEntries() {
        // sort the cache entries by their last accessed time in descending order
        List<CacheEntry> sortedEntries = new ArrayList<>(cache.values());
        sortedEntries.sort(Comparator.comparingLong(CacheEntry::getLastAccessedTime).reversed());

        // evict the least recently used entries until the cache is not full or there are no more entries to evict
        while (isFull() && !sortedEntries.isEmpty()) {
            CacheEntry entry = sortedEntries.remove(0);
            cache.remove(entry.getKey());
            totalSize -= entry.getSize();
            numEntries--;
        }
    }

    public boolean isFull() {
        return totalSize > MAX_CACHE_SIZE || numEntries >= MAX_CACHE_SIZE;
    }

    private static class CacheEntry {
        private String key;
        private String contentType;
        private byte[] data;
        private long lastAccessedTime; // in milliseconds

        public CacheEntry(String key, String contentType, byte[] data) {
            this.key = key;
            this.contentType = contentType;
            this.data = data;
            this.lastAccessedTime = System.currentTimeMillis();
        }

        public String getKey() {
            return key;
        }

        public String getContentType() {
            return contentType;
        }

        public byte[] getData() {
            return data;
        }

        public long getSize() {
            return data.length;
        }

        public void setLastAccessedTime() {
            lastAccessedTime = System.currentTimeMillis();
        }
    }
}
```
