        stage->output = allocator->alloc(stage->output_size);
        if (!stage->output) {
            fprintf(stderr, "Failed to allocate memory for stage %d's output\n", i);
            allocator->free(stage);
            allocator->free(pipeline->stages);
            allocator->free(pipeline);
            return NULL;
        }

        // Initialize the stage's processing function pointer
        stage->process = process_image;

        pipeline->stages[i] = stage;
    }

    return pipeline;
}

// Function to add a new stage to the image processing pipeline
int addStage(struct Pipeline* pipeline, void (*process)(void* input, void* output, size_t batch_size)) {
    // Check if the pipeline is full
    if (pipeline->num_stages == pipeline->max_num_stages) {
        fprintf(stderr, "Pipeline is full\n");
        return -1;
    }

    // Allocate memory for the new stage
    struct Stage* stage = (struct Stage*)pipeline->allocator->alloc(sizeof(struct Stage));
    if (!stage) {
        fprintf(stderr, "Failed to allocate memory for new stage\n");
        return -1;
    }

    // Initialize the new stage's internal buffer size based on the batch size and image resolution
    stage->output_size = pipeline->batch_size * sizeof(float) * 3;
    stage->output = pipeline->allocator->alloc(stage->output_size);
    if (!stage->output) {
        fprintf(stderr, "Failed to allocate memory for new stage's output\n");
        pipeline->allocator->free(stage);
        return -1;
    }

    // Initialize the new stage's processing function pointer
    stage->process = process_image;

    // Add the new stage to the pipeline
    pipeline->stages[pipeline->num_stages] = stage;
    ++pipeline->num_stages;

    return 0;
}

// Function to retrieve an intermediate result from a specific stage in the image processing pipeline
void* getStageResult(struct Pipeline* pipeline, int stage_index) {
    // Check if the stage index is valid
    if (stage_index < 0 || stage_index >= pipeline->num_stages) {
        fprintf(stderr, "Invalid stage index\n");
        return NULL;
    }

    // Return the result of the specified stage
    return pipeline->stages[stage_index]->output;
}

// Function to clear the entire image processing pipeline
void clearPipeline(struct Pipeline* pipeline) {
    // Free all memory allocated for the stages in the pipeline
    for (int i = 0; i < pipeline->num_stages; ++i) {
        pipeline->allocator->free(pipeline->stages[i]->output);
        pipeline->allocator->free(pipeline->stages[i]);
    }

    // Free the memory allocated for the stages array
    pipeline->allocator->free(pipeline->stages);

    // Reset the number of stages in the pipeline to 0
    pipeline->num_stages = 0;
}

// Function to filter stages based on a specified operation type
void filterStagesByOperationType(struct Pipeline* pipeline, int operation_type) {
    // Check if the pipeline is empty
    if (pipeline->num_stages == 0) {
        fprintf(stderr, "Pipeline is empty\n");
        return;
    }

    // Iterate over each stage in the pipeline and filter out stages that do not match the specified operation type
    for (int i = 0; i < pipeline->num_stages; ++i) {
        if (pipeline->stages[i]->process != operation_type) {
            // Remove the stage from the pipeline by swapping it with the last stage and decrementing the number of stages
            struct Stage* temp = pipeline->stages[i];
            pipeline->stages[i] = pipeline->stages[pipeline->num_stages - 1];
            --pipeline->num_stages;
            // Free the memory allocated for the filtered stage
            pipeline->allocator->free(temp);
        }
    }
}

// Function to automatically purge outdated stages based on a configurable age threshold
void autoPurgeOutdatedStages(struct Pipeline* pipeline, int age_threshold) {
    // Check if the pipeline is empty
    if (pipeline->num_stages == 0) {
        fprintf(stderr, "Pipeline is empty\n");
        return;
    }

    // Iterate over each stage in the pipeline and purge outdated stages based on the specified age threshold
    for (int i = 0; i < pipeline->num_stages; ++i) {
        if (pipeline->stages[i]->process == NULL) {
            // Remove the stage from the pipeline by swapping it with the last stage and decrementing the number of stages
            struct Stage* temp = pipeline->stages[i];
            pipeline->stages[i] = pipeline->stages[pipeline->num_stages - 1];
            --pipeline->num_stages;
            // Free the memory allocated for the purged stage
            pipeline->allocator->free(temp);
        }
    }
}

// Function to process an image through the image processing pipeline
void processImage(struct Pipeline* pipeline, void* input) {
    // Check if the pipeline is empty
    if (pipeline->num_stages == 0) {
        fprintf(stderr, "Pipeline is empty\n");
        return;
    }

    // Iterate over each stage in the pipeline and process the input image through each stage
    for (int i = 0; i < pipeline->num_stages; ++i) {
        pipeline->stages[i]->process(input, pipeline->stages[i]->output, pipeline->batch_size);
        input = pipeline->stages[i]->output;
    }
}

// Function to free all allocated resources for the image processing pipeline
void freePipeline(struct Pipeline* pipeline) {
    // Free all memory allocated for the stages in the pipeline
    for (int i = 0; i < pipeline->num_stages; ++i) {
        pipeline->allocator->free(pipeline->stages[i]->output);
        pipeline->allocator->free(pipeline->stages[i]);
    }

    // Free the memory allocated for the stages array
    pipeline->allocator->free(pipeline->stages);

    // Reset the number of stages in the pipeline to 0
    pipeline->num_stages = 0;
}
