    int level;
    char *transaction_details;
    char *message;
} TransactionLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 10000

// Define the structure for a log filter
typedef struct {
    int level;
    char *transaction_details;
} LogFilter;

// Define the structure for a log entry with filtering information
typedef struct {
    TransactionLogEntry entry;
    LogFilter filter;
} FilteredTransactionLogEntry;

// Define the function to add a new transaction log entry
void add_transaction_log_entry(TransactionLogEntry *entry) {
    // Check if the log array is full, and purge old entries if necessary
    if (num_entries >= MAX_LOG_SIZE) {
        purge_old_entries();
    }

    // Add the new entry to the log array
    transaction_log[num_entries++] = *entry;
}

// Define the function to retrieve a transaction log entry by timestamp
TransactionLogEntry* get_transaction_log_entry(time_t timestamp) {
    for (int i = 0; i < num_entries; i++) {
        if (transaction_log[i].timestamp == timestamp) {
            return &transaction_log[i];
        }
    }
    return NULL;
}

// Define the function to clear the transaction log
void clear_transaction_log() {
    num_entries = 0;
}

// Define the function to filter the transaction log based on a specified log level and transaction details
FilteredTransactionLogEntry* filter_transaction_log(int level, char *transaction_details) {
    FilteredTransactionLogEntry *filtered_log = (FilteredTransactionLogEntry*) malloc(sizeof(FilteredTransactionLogEntry));
    filtered_log->entry.timestamp = 0;
    filtered_log->entry.level = 0;
    filtered_log->entry.transaction_details = NULL;
    filtered_log->entry.message = NULL;
    filtered_log->filter.level = level;
    filtered_log->filter.transaction_details = transaction_details;

    for (int i = 0; i < num_entries; i++) {
        if (transaction_log[i].timestamp == timestamp) {
            filtered_log->entry = transaction_log[i];
            return filtered_log;
        }
    }
    return NULL;
}

// Define the function to purge old entries from the log array
void purge_old_entries() {
    // Check if there are any old entries in the log array
    if (num_entries > 0) {
        // Find the oldest entry in the log array
        int oldest_entry = 0;
        for (int i = 1; i < num_entries; i++) {
            if (transaction_log[i].timestamp < transaction_log[oldest_entry].timestamp) {
                oldest_entry = i;
            }
        }

        // Remove the oldest entry from the log array
        for (int i = oldest_entry; i < num_entries - 1; i++) {
            transaction_log[i] = transaction_log[i + 1];
        }
        num_entries--;
    }
}

// Define the function to compact the log structure periodically
void compact_log() {
    // Check if there are any unused entries in the log array
    for (int i = 0; i < num_entries; i++) {
        if (transaction_log[i].timestamp == 0) {
            // Remove the unused entry from the log array
            for (int j = i; j < num_entries - 1; j++) {
                transaction_log[j] = transaction_log[j + 1];
            }
            num_entries--;
        }
    }
}

