void insertAndSort(std::vector<int>& vec, int targetValue, int searchValue, int newValue) {
    // Find the index of the first occurrence of searchValue in the vector
    auto it = std::find(vec.begin(), vec.end(), searchValue);

    // If searchValue is not present in the vector, append newValue to the end
    if (it == vec.end()) {
        vec.push_back(newValue);
    } else {
        // Insert newValue into the vector immediately after the first occurrence of searchValue
        vec.insert(it + 1, newValue);
    }

    // Sort the entire vector in ascending order
    std::sort(vec.begin(), vec.end());
}
