    new_str[len] = '/';
    new_str[len + 1] = '\0';

    // Reverse the input string if it is less than half of the size limit and case-sensitive is set to true
    if (case_sensitive && len < limit / 2) {
        reverse(new_str);
    }

    return new_str;
}

void reverse(char* str) {
    // Get the length of the input string
    size_t len = strlen(str);

    // Iterate through the characters in the input string and swap them with their corresponding reversed counterparts
    for (size_t i = 0; i < len / 2; i++) {
        char tmp = str[i];
        str[i] = str[len - i - 1];
        str[len - i - 1] = tmp;
    }
}
