    for (int i = 0; i < num_active_sessions; i++) {
        if ((protocol_version != 0 && sessions[i].network_protocol_version != protocol_version) ||
            (start_time != 0 && sessions[i].connection_start_time < start_time) ||
            (end_time != 0 && sessions[i].connection_end_time > end_time)) {
            // Remove the session from the dynamic array
            num_active_sessions--;
        }
    }
}

// Define the function to purge inactive sessions older than a configurable duration
