    for (int i = 0; i < num_active_sessions; i++) {
        if (now - sessions[i].connection_end_time > INACTIVE_SESSION_PURGE_DURATION) {
            // Remove the session from the dynamic array
            num_active_sessions--;
        }
    }
}

