void reorganize_sessions() {
    // Get the current time
    time_t now = time(NULL);

    // Iterate through the dynamic array of sessions and reorganize the structure every SESSION_REORGANIZE_FREQUENCY seconds
    for (int i = 0; i < num_active_sessions; i++) {
        if (now - sessions[i].connection_end_time > SESSION_REORGANIZE_FREQUENCY) {
            // Reorganize the session structure
            reorganize_session(&sessions[i]);
        }
    }
}

// Define the function to export session data to a file in a standardized format
