    // Open the export file for writing
    FILE* fp = fopen(EXPORT_FILE_PATH, "w");

    // Iterate through the dynamic array of sessions and export each session to the file
    for (int i = 0; i < num_active_sessions; i++) {
        NetworkSession* session = &sessions[i];
        fprintf(fp, EXPORT_FILE_FORMAT, session->session_id, session->connection_start_time, session->connection_end_time, session->network_protocol_version, session->payload);
    }

    // Close the export file
    fclose(fp);
}
