    return cache->jobs[index];
}

void cache_remove(struct cache *cache, int index) {
    // Remove a job from the cache by its index
    cache->size--;
    memmove(&cache->jobs[index], &cache->jobs[index + 1], sizeof(struct job *) * (cache->size - index));
}

// Define the DNS resolution function
void resolve_hostname(char *hostname, struct job *job) {
    // Initialize the cache entry
    struct cache_entry *entry = malloc(sizeof(struct cache_entry));
    entry->timestamp = time(NULL);
    entry->job = job;

    // Check if the hostname is already in the cache
    for (int i = 0; i < cache.size; i++) {
        struct cache_entry *cache_entry = cache.jobs[i];
        if (strcmp(hostname, cache_entry->job->hostname) == 0) {
            // If the hostname is in the cache, update its timestamp and return it
            entry->timestamp = time(NULL);
            return cache_entry->job;
        }
    }

    // If the hostname is not in the cache, resolve it using multiple external DNS servers with configurable priorities
    struct addrinfo *result = NULL;
    int status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        // If the resolution fails, log the error and return NULL
        printf("DNS resolution failed: %s\n", gai_strerror(status));
        return NULL;
    }

    // Iterate over the DNS servers with priorities and resolve the hostname using each one
    for (struct addrinfo *server = result; server != NULL; server = server->ai_next) {
        struct sockaddr_in *address = (struct sockaddr_in *)server->ai_addr;
        int socket = socket(AF_INET, SOCK_STREAM, 0);
        if (socket == -1) {
            // If the socket creation fails, log the error and continue to the next server
            printf("Socket creation failed: %s\n", strerror(errno));
            continue;
        }

        int ret = connect(socket, address, sizeof(*address));
        if (ret == -1) {
            // If the connection fails, log the error and close the socket
            printf("Connection failed: %s\n", strerror(errno));
            close(socket);
            continue;
        }

        char buffer[256];
        int bytes = recv(socket, buffer, sizeof(buffer), 0);
        if (bytes == -1) {
            // If the receive fails, log the error and close the socket
            printf("Receive failed: %s\n", strerror(errno));
            close(socket);
            continue;
        }

        // Parse the received data and extract the IP address
        struct sockaddr_in *ip = (struct sockaddr_in *)buffer;
        char ip_address[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &ip->sin_addr, ip_address, sizeof(ip_address));

        // Add the resolved IP address to the cache and return it
        entry->job->hostname = hostname;
        entry->job->ip_address = ip_address;
        cache_add(&cache, entry);
        return entry->job;
    }

    // If all DNS servers fail, log an error and return NULL
    printf("All DNS servers failed\n");
    freeaddrinfo(result);
    return NULL;
}

// Define the job processing function
void process_jobs(struct cache *cache) {
    // Initialize the array of jobs to be processed
    struct job **jobs = malloc(sizeof(struct job *) * cache->size);

    // Iterate over the cache and add each job with a unique priority to the array of jobs to be processed
    for (int i = 0; i < cache.size; i++) {
        struct cache_entry *cache_entry = cache.jobs[i];
        if (cache_entry->job->status == 'U') {
            // If the job is unprocessed, add it to the array of jobs to be processed
            jobs[jobs.size++] = cache_entry->job;
        }
    }

    // Process the array of jobs in parallel using multiple threads
    pthread_t *threads = malloc(sizeof(pthread_t) * jobs.size);
    for (int i = 0; i < jobs.size; i++) {
        struct job *job = jobs[i];
        pthread_create(&threads[i], NULL, resolve_hostname, job->hostname);
    }

    // Wait for all threads to complete and check for any errors
    for (int i = 0; i < jobs.size; i++) {
        struct job *job = jobs[i];
        pthread_join(threads[i], NULL);
        if (job->status == 'E') {
            // If an error occurs during processing, log the error and return it
            printf("Error occurred while processing job: %s\n", job->error);
            freeaddrinfo(result);
            return;
        }
    }

    // Free the memory allocated for the array of jobs and the threads
    free(jobs);
    free(threads);
}

// Define the main function
int main() {
    // Initialize the cache
