#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the log level constants
#define LOG_LEVEL_CRITICAL 5
#define LOG_LEVEL_ERROR 4
#define LOG_LEVEL_WARNING 3
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_DEBUG 1

// Define the log entry structure
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the log array and its mutex
ModemLogEntry* log_array = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new entry to the log
void add_log_entry(time_t timestamp, int level, char* message) {
    // Lock the mutex before modifying the log array
    pthread_mutex_lock(&log_mutex);

    // Check if the log array is full and needs to be resized
    if (log_array == NULL || log_size >= MAX_LOG_SIZE) {
        // Resize the log array by 50%
        int new_size = log_size + (log_size / 2);
        ModemLogEntry* new_array = realloc(log_array, new_size * sizeof(ModemLogEntry));
        if (new_array == NULL) {
            // Reallocation failed, free the old array and return
            free(log_array);
            log_array = NULL;
            pthread_mutex_unlock(&log_mutex);
            return;
        }
        log_array = new_array;
    }

    // Add the new entry to the log array
    log_array[log_size].timestamp = timestamp;
    log_array[log_size].level = level;
    log_array[log_size].message = strdup(message);
    log_size++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(time_t timestamp) {
    // Lock the mutex before accessing the log array
    pthread_mutex_lock(&log_mutex);

    // Search for the specified timestamp in the log array
    int i;
    for (i = 0; i < log_size; i++) {
        if (log_array[i].timestamp == timestamp) {
            break;
        }
    }

    // Return NULL if the timestamp was not found
    if (i >= log_size) {
        pthread_mutex_unlock(&log_mutex);
        return NULL;
    }

    // Return a copy of the log entry
    ModemLogEntry* entry = malloc(sizeof(ModemLogEntry));
    memcpy(entry, &log_array[i], sizeof(ModemLogEntry));
    pthread_mutex_unlock(&log_mutex);
    return entry;
}

// Function to clear the entire log
void clear_log() {
    // Lock the mutex before modifying the log array
    pthread_mutex_lock(&log_mutex);

    // Free all entries in the log array
    int i;
    for (i = 0; i < log_size; i++) {
        free(log_array[i].message);
    }
    log_size = 0;

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to filter logs based on a specified log level
void filter_logs(int level) {
    // Lock the mutex before modifying the log array
    pthread_mutex_lock(&log_mutex);

    // Iterate over all entries in the log array and remove any that do not match the specified level
    int i;
    for (i = 0; i < log_size; i++) {
        if (log_array[i].level != level) {
            free(log_array[i].message);
            memmove(&log_array[i], &log_array[i + 1], (log_size - i - 1) * sizeof(ModemLogEntry));
            log_size--;
            i--;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to purge old entries from the log
void purge_old_entries(time_t duration) {
    // Lock the mutex before modifying the log array
    pthread_mutex_lock(&log_mutex);

    // Iterate over all entries in the log array and remove any that are older than the specified duration
    int i;
    for (i = 0; i < log_size; i++) {
        if (log_array[i].timestamp < time(NULL) - duration) {
            free(log_array[i].message);
            memmove(&log_array[i], &log_array[i + 1], (log_size - i - 1) * sizeof(ModemLogEntry));
            log_size--;
            i--;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to compact the log structure
void compact_log() {
    // Lock the mutex before modifying the log array
    pthread_mutex_lock(&log_mutex);

    // Iterate over all entries in the log array and remove any that are not needed
    int i;
    for (i = 0; i < log_size; i++) {
        if (log_array[i].message == NULL) {
            memmove(&log_array[i], &log_array[i + 1], (log_size - i - 1) * sizeof(ModemLogEntry));
            log_size--;
            i--;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&log_mutex);
}

// Function to export the log entries to a file in a standardized format
void export_log(char* filename) {
    // Lock the mutex before accessing the log array
    pthread_mutex_lock(&log_mutex);

    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Write each log entry to the output file
    int i;
    for (i = 0; i < log_size; i++) {
        fprintf(fp, "%lu %d %s\n", log_array[i].timestamp, log_array[i].level, log_array[i].message);
    }

    // Close the output file and return
    fclose(fp);
    pthread_mutex_unlock(&log_mutex);
}
