// Define the function to create and populate an array of CRC indication data structures
void create_and_populate_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T **crc_indication_array, int num_elements) {
    // Check if the input size is valid and less than or equal to 1024 elements
    if (num_elements <= 0 || num_elements > 1024) {
        printf("Invalid input size for CRC indication array\n");
        return;
    }

    // Allocate memory for the array of CRC indication data structures
    *crc_indication_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crc_indication_array == NULL) {
        printf("Failed to allocate memory for CRC indication array\n");
        return;
    }

    // Initialize the CRCFLAG within each CRC indication structure randomly
    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        (*crc_indication_array)[i].crc_indication_rel8_tag = rand() % 256;
