    // Populate the RX UE information tag and RNTI for each CRC indication structure
    for (int i = 0; i < num_elements; i++) {
        (*crc_indication_array)[i].rx_ue_information_tag = rand() % 65536;
        (*crc_indication_array)[i].rnti = rand() % 1048576;
