```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the log entry structure
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the log structure
typedef struct {
    ModemLogEntry* entries;
    size_t num_entries;
    size_t max_size;
} Log;

// Function to add a new entry to the log
void add_entry(Log* log, time_t timestamp, int level, char* message) {
    // Check if the log is full
    if (log->num_entries == log->max_size) {
        // Purge old entries if necessary
        purge_old_entries(log);
    }

    // Add the new entry to the log
    ModemLogEntry* new_entry = malloc(sizeof(ModemLogEntry));
    new_entry->timestamp = timestamp;
    new_entry->level = level;
    new_entry->message = strdup(message);
    log->entries[log->num_entries++] = new_entry;
}

// Function to retrieve entries from the log by timestamp
ModemLogEntry* get_entries_by_timestamp(Log* log, time_t start_time, time_t end_time) {
    // Check if the log is empty
    if (log->num_entries == 0) {
        return NULL;
    }

    // Find the first entry that matches the timestamp range
    size_t i = 0;
    while (i < log->num_entries && log->entries[i]->timestamp < start_time) {
        i++;
    }

    // Check if there are any entries in the specified range
    if (i == log->num_entries || log->entries[i]->timestamp > end_time) {
        return NULL;
    }

    // Create a new array to hold the matching entries
    ModemLogEntry* matching_entries = malloc(sizeof(ModemLogEntry) * (end_time - start_time));
    size_t j = 0;

    // Add the matching entries to the array
    while (i < log->num_entries && log->entries[i]->timestamp <= end_time) {
        matching_entries[j++] = *log->entries[i];
        i++;
    }

    return matching_entries;
}

// Function to clear the entire log
void clear_log(Log* log) {
    // Free all entries in the log
    for (size_t i = 0; i < log->num_entries; i++) {
        free(log->entries[i]);
    }

    // Reset the log structure
    log->num_entries = 0;
}

// Function to purge old entries from the log
void purge_old_entries(Log* log) {
    // Check if the log is empty
    if (log->num_entries == 0) {
        return;
    }

    // Find the oldest entry in the log
    size_t i = 0;
    while (i < log->num_entries && log->entries[i]->timestamp > time(NULL) - log->max_size) {
        i++;
    }

    // Check if there are any old entries to purge
    if (i == log->num_entries) {
        return;
    }

    // Free the oldest entry and shift all remaining entries down
    free(log->entries[i]);
    for (size_t j = i; j < log->num_entries - 1; j++) {
        log->entries[j] = log->entries[j + 1];
    }

    // Decrement the number of entries in the log
    log->num_entries--;
}

// Function to filter logs based on a specified log level
void filter_logs(Log* log, int level) {
    // Check if the log is empty
    if (log->num_entries == 0) {
        return;
    }

    // Find the first entry that matches the specified log level
    size_t i = 0;
    while (i < log->num_entries && log->entries[i]->level > level) {
        i++;
    }

    // Check if there are any entries in the specified range
    if (i == log->num_entries || log->entries[i]->level <= level) {
        return;
    }

    // Create a new array to hold the matching entries
    ModemLogEntry* matching_entries = malloc(sizeof(ModemLogEntry) * (log->num_entries - i));
    size_t j = 0;

    // Add the matching entries to the array
    while (i < log->num_entries && log->entries[i]->level > level) {
        matching_entries[j++] = *log->entries[i];
        i++;
    }

    return matching_entries;
}

// Function to export the log entries to a file in a standardized format
void export_log(Log* log, char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Write the log entries to the file
    for (size_t i = 0; i < log->num_entries; i++) {
        fprintf(fp, "%lu %d %s\n", log->entries[i]->timestamp, log->entries[i]->level, log->entries[i]->message);
    }

    // Close the output file
    fclose(fp);
}

// Function to compact the log structure periodically
void compact_log(Log* log) {
    // Check if the log is empty
    if (log->num_entries == 0) {
        return;
    }

    // Find the first entry that needs to be compacted
    size_t i = 0;
    while (i < log->num_entries && log->entries[i]->timestamp > time(NULL) - log->max_size) {
        i++;
    }

    // Check if there are any entries that need to be compacted
    if (i == log->num_entries) {
        return;
    }

    // Create a new array to hold the remaining entries
    ModemLogEntry* new_entries = malloc(sizeof(ModemLogEntry) * (log->num_entries - i));
    size_t j = 0;

    // Copy the remaining entries to the new array
    while (i < log->num_entries) {
        new_entries[j++] = *log->entries[i];
        i++;
    }

    // Free the old entries and replace them with the new array
    for (size_t k = 0; k < log->num_entries; k++) {
        free(log->entries[k]);
    }
    log->entries = new_entries;
    log->num_entries = j;
}
