function extractOldTestamentBooks(text) {
  const bookRegex = new RegExp(`\\b(${oldTestamentBooks.join('|')})\\b`, 'gi');
  const matches = text.match(bookRegex);
  if (!matches) return {};
  const bookCounts = {};
