#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

void print_usage() {
    printf("Usage: file_manager [OPTION]...\n");
    printf("\t-a, --append_text=FILENAME\tAppend text to a file.\n");
    printf("\t-r, --read=FILENAME\tRead a file and print its contents.\n");
    printf("\t-w, --write=FILENAME\tWrite text to a file.\n");
    printf("\t-l, --list_files\tList all files in the current directory.\n");
    printf("\t--help\tPrint this help message and exit.\n");
}

void append_text(char *filename) {
    FILE *file = fopen(filename, "a+");
    if (file == NULL) {
        perror("Error opening file for appending");
        return;
    }
    char text[1024];
    printf("Enter the text to append: ");
    scanf("%s", text);
    fprintf(file, "%s\n", text);
    fclose(file);
}

void read_file(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file for reading");
        return;
    }
    char buffer[1024];
    while (fgets(buffer, 1024, file)) {
        printf("%s", buffer);
    }
    fclose(file);
}

void write_file(char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Error opening file for writing");
        return;
    }
    char text[1024];
    printf("Enter the text to write: ");
    scanf("%s", text);
    fprintf(file, "%s\n", text);
    fclose(file);
}

void list_files() {
    DIR *dir = opendir(".");
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        printf("%s\n", entry->d_name);
    }
    closedir(dir);
}

int main(int argc, char **argv) {
    if (argc == 1) {
        print_usage();
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 || strcmp(argv[i], "--append_text") == 0) {
            if (i + 1 >= argc) {
                printf("Error: Missing file name for -a option\n");
                return 1;
            }
            append_text(argv[i + 1]);
        } else if (strcmp(argv[i], "-r") == 0 || strcmp(argv[i], "--read") == 0) {
            if (i + 1 >= argc) {
                printf("Error: Missing file name for -r option\n");
                return 1;
            }
            read_file(argv[i + 1]);
        } else if (strcmp(argv[i], "-w") == 0 || strcmp(argv[i], "--write") == 0) {
            if (i + 1 >= argc) {
                printf("Error: Missing file name for -w option\n");
                return 1;
            }
            write_file(argv[i + 1]);
        } else if (strcmp(argv[i], "-l") == 0 || strcmp(argv[i], "--list_files") == 0) {
            list_files();
        } else if (strcmp(argv[i], "--help") == 0) {
            print_usage();
            return 0;
        } else {
            printf("Error: Invalid option %s\n", argv[i]);
            return 1;
        }
    }
    return 0;
}
```
