```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class ResourceRequestCache {
public:
    // Constructor
    ResourceRequestCache(size_t maxSize, size_t stalePolicyInterval) :
        _maxSize(maxSize),
        _stalePolicyInterval(stalePolicyInterval),
        _requests(),
        _requestMap(),
        _mutex(),
        _cv(),
        _thread() {}

    // Destructor
    ~ResourceRequestCache() {
        stop();
    }

    // Add a new request to the cache
    void add(const ResourceRequest& request) {
        std::lock_guard<std::mutex> lock(_mutex);
        _requests.push_back(request);
        _requestMap[request.getId()] = request;
        if (_requests.size() > _maxSize) {
            evictStaleRequests();
        }
    }

    // Retrieve a request from the cache by ID
    ResourceRequest get(const std::string& id) {
        std::lock_guard<std::mutex> lock(_mutex);
        auto it = _requestMap.find(id);
        if (it != _requestMap.end()) {
            return it->second;
        } else {
            return ResourceRequest();
        }
    }

    // Evict stale requests from the cache
    void evictStaleRequests() {
        std::lock_guard<std::mutex> lock(_mutex);
        auto now = std::chrono::steady_clock::now();
        for (auto it = _requests.begin(); it != _requests.end();) {
            if (it->getExpirationTime() < now) {
                it = _requests.erase(it);
            } else {
                ++it;
            }
        }
    }

    // Filter requests based on metadata
    std::vector<ResourceRequest> filter(const Metadata& metadata) {
        std::lock_guard<std::mutex> lock(_mutex);
        std::vector<ResourceRequest> filteredRequests;
        for (auto& request : _requests) {
            if (request.getMetadata().matches(metadata)) {
                filteredRequests.push_back(request);
            }
        }
        return filteredRequests;
    }

    // Purge stale requests in the background
    void purgeStaleRequests() {
        std::lock_guard<std::mutex> lock(_mutex);
        evictStaleRequests();
        _cv.notify_all();
    }

    // Serialize cache state to disk
    void serialize(const std::string& filename) {
        std::lock_guard<std::mutex> lock(_mutex);
        std::ofstream ofs(filename, std::ios::binary);
        if (!ofs.is_open()) {
            throw std::runtime_error("Failed to open file for serialization");
        }
        ofs.write((char*)&_requests[0], _requests.size() * sizeof(ResourceRequest));
    }

    // Deserialize cache state from disk
    void deserialize(const std::string& filename) {
        std::lock_guard<std::mutex> lock(_mutex);
        std::ifstream ifs(filename, std::ios::binary);
        if (!ifs.is_open()) {
            throw std::runtime_error("Failed to open file for deserialization");
        }
        _requests.clear();
        _requestMap.clear();
        size_t numRequests;
        ifs.read((char*)&numRequests, sizeof(size_t));
        for (size_t i = 0; i < numRequests; ++i) {
            ResourceRequest request;
            ifs.read((char*)&request, sizeof(ResourceRequest));
            _requests.push_back(request);
            _requestMap[request.getId()] = request;
        }
    }

private:
