        // If the log is full, remove the oldest entry
        ModemLogEntry* oldest = &log->entries[0];
        free(oldest->message);
        memmove(&log->entries[0], &log->entries[1], sizeof(ModemLogEntry) * (MAX_LOG_SIZE - 1));
        log->count--;
    }

    // Add the new entry to the end of the log array
    ModemLogEntry* new_entry = &log->entries[log->count];
    new_entry->timestamp = timestamp;
    new_entry->log_level = log_level;
    new_entry->message = strdup(message);
    log->count++;
}

