    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list to hold the CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to initialize and populate the list with unique CRC indications
void init_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Initialize the list with a capacity of 10,000 structures
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10000);
    list->size = 0;
    list->capacity = 10000;

    // Populate the list with unique CRC indications
    for (int i = 0; i < list->capacity; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[i];
        pdu->rx_ue_information_tag = rand() % 65535;
        pdu->rnti = rand() % 65535;
        pdu->crc_indication_rel8_tag = rand() % 256;
        pdu->crcflag = rand() % 256;

        // Ensure that no two consecutive structures share the same RNTI value
        if (i > 0 && list->data[i - 1].rnti == pdu->rnti) {
            i--;
            continue;
        }

        list->size++;
    }
}

// Define the function to handle dynamically varying input sizes
void resize_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list, size_t new_capacity) {
    // Reallocate memory for the list with the new capacity
    NFAPI_CRC_INDICATION_PDU_T *new_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    memcpy(new_data, list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->size);
    free(list->data);
    list->data = new_data;
    list->capacity = new_capacity;
}

// Define the function to sort the list based on the RNTI values in ascending order
void sort_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Sort the list using a simple bubble sort algorithm
    for (int i = 0; i < list->size - 1; i++) {
        for (int j = 0; j < list->size - i - 1; j++) {
            if (list->data[j].rnti > list->data[j + 1].rnti) {
                NFAPI_CRC_INDICATION_PDU_T tmp = list->data[j];
                list->data[j] = list->data[j + 1];
                list->data[j + 1] = tmp;
            }
        }
    }
}

// Define the function to handle concurrent calls from different threads
void *crc_indication_thread(void *arg) {
    NFAPI_CRC_INDICATION_LIST_T *list = (NFAPI_CRC_INDICATION_LIST_T *) arg;

    // Acquire a lock to prevent concurrent access to the list
    pthread_mutex_lock(&list->mutex);

    // Populate the list with unique CRC indications
    init_crc_indication_list(list);

    // Release the lock and return
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Define the function to monitor memory usage and performance metrics
void log_crc_indication_metrics(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Log the current size of the list
    printf("Current size of CRC indication list: %zu\n", list->size);

    // Log the maximum capacity of the list
    printf("Maximum capacity of CRC indication list: %zu\n", list->capacity);

    // Log the memory usage of the list
    printf("Memory usage of CRC indication list: %zu bytes\n", sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->size);
}

int main() {
    // Initialize the list with a capacity of 10,000 structures
    NFAPI_CRC_INDICATION_LIST_T list;
    init_crc_indication_list(&list);

    // Sort the list based on the RNTI values in ascending order
    sort_crc_indication_list(&list);

    // Log the current size and maximum capacity of the list
    log_crc_indication_metrics(&list);

    // Handle concurrent calls from different threads
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, crc_indication_thread, &list);
    pthread_create(&thread2, NULL, crc_indication_thread, &list);
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    // Log the current size and maximum capacity of the list after handling concurrent calls from different threads
    log_crc_indication_metrics(&list);

    return 0;
}
