// Define the structure for the network event
typedef struct NetworkEvent {
    int type; // Event type (e.g., connection, disconnection)
    char* source_ip; // Source IP address
    time_t timestamp; // Timestamp of the event
    char* message; // Variable-length message
} NetworkEvent;

// Define a linked list data structure to store the network events
typedef struct EventList {
    NetworkEvent* head; // Pointer to the first event in the list
    NetworkEvent* tail; // Pointer to the last event in the list
    int size; // Number of events in the list
} EventList;

// Define a thread-safe mutex for protecting the linked list
pthread_mutex_t event_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new network event to the list
void add_event(NetworkEvent* event) {
    pthread_mutex_lock(&event_list_mutex);
    EventList* list = get_event_list();
    if (list->size >= MAX_EVENTS) { // If the list is full, purge old events
        purge_old_events(list);
    }
    NetworkEvent* new_event = malloc(sizeof(NetworkEvent));
    memcpy(new_event, event, sizeof(NetworkEvent));
    if (list->head == NULL) { // If the list is empty, set the head and tail pointers
        list->head = new_event;
        list->tail = new_event;
    } else { // Otherwise, add the new event to the end of the list
        list->tail->next = new_event;
        list->tail = new_event;
    }
    list->size++;
    pthread_mutex_unlock(&event_list_mutex);
}

// Function to retrieve all network events from a specific source IP address
NetworkEvent* get_events_by_source_ip(char* source_ip) {
    pthread_mutex_lock(&event_list_mutex);
    EventList* list = get_event_list();
    NetworkEvent* event = NULL;
    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->head[i].source_ip, source_ip) == 0) { // If the event matches the source IP, return it
            event = &list->head[i];
            break;
        }
    }
    pthread_mutex_unlock(&event_list_mutex);
    return event;
}

// Function to clear all network events from the list
void clear_events() {
    pthread_mutex_lock(&event_list_mutex);
    EventList* list = get_event_list();
    for (int i = 0; i < list->size; i++) {
        free(list->head[i].message); // Free the message memory
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&event_list_mutex);
}

// Function to purge old events from the list
void purge_old_events(EventList* list) {
    for (int i = 0; i < list->size; i++) {
        if (time(NULL) - list->head[i].timestamp > MAX_EVENT_AGE) { // If the event is older than the maximum age, free it
            free(list->head[i].message);
            list->head = list->head + 1;
            i--;
        } else {
            break;
        }
    }
}

// Function to compact the event log by removing unused memory
void compact_event_log() {
    pthread_mutex_lock(&event_list_mutex);
    EventList* list = get_event_list();
    for (int i = 0; i < list->size; i++) {
        if (list->head[i].message == NULL) { // If the event has no message, free it
            free(list->head[i]);
            list->head = list->head + 1;
            i--;
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&event_list_mutex);
}

// Function to export the event entries to a file in a standardized format
void export_events(char* filename) {
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: Could not open file for writing\n");
        return;
    }
    pthread_mutex_lock(&event_list_mutex);
    EventList* list = get_event_list();
    for (int i = 0; i < list->size; i++) {
        fprintf(fp, "%d,%s,%ld,%s\n", list->head[i].type, list->head[i].source_ip, list->head[i].timestamp, list->head[i].message);
    }
    pthread_mutex_unlock(&event_list_mutex);
    fclose(fp);
}
```
