    memory_pool->block_size = 64;
    memory_pool->free_list = NULL;

    // Return the initialized memory pool
    return memory_pool;
}

// Define the function to allocate memory from the memory pool
void *allocate_memory(MemoryPool *memory_pool, size_t size) {
    // Check if there is enough space in the free list
    if (memory_pool->free_list == NULL || memory_pool->free_list->size < size) {
        // Allocate a new block of memory from the system
        void *block = malloc(memory_pool->block_size);
        if (block == NULL) {
            printf("Failed to allocate memory for block\n");
            return NULL;
        }

        // Add the new block to the free list
        MemoryBlock *new_block = (MemoryBlock *) malloc(sizeof(MemoryBlock));
        if (new_block == NULL) {
            printf("Failed to allocate memory for new block\n");
            return NULL;
        }
        new_block->size = memory_pool->block_size;
        new_block->next = memory_pool->free_list;
        memory_pool->free_list = new_block;
    }

    // Allocate the requested size from the free list
    MemoryBlock *block = memory_pool->free_list;
    if (block == NULL) {
        printf("Failed to allocate memory for block\n");
        return NULL;
    }
    memory_pool->free_list = block->next;
    void *memory = (void *) ((char *) block + sizeof(MemoryBlock));
    return memory;
}

// Define the function to free memory from the memory pool
void free_memory(MemoryPool *memory_pool, void *memory) {
    // Check if the memory is in the free list
    MemoryBlock *block = (MemoryBlock *) ((char *) memory - sizeof(MemoryBlock));
    if (block == NULL || block->next != NULL) {
        printf("Failed to free memory\n");
        return;
    }

    // Add the freed block to the free list
    block->next = memory_pool->free_list;
    memory_pool->free_list = block;
}
