            // Reallocation failed, exit the function
            pthread_mutex_unlock(&log_array_mutex);
            return;
        }
        log_array.entries = new_entries;
        log_array.capacity = new_capacity;
    }

    // Add the new log entry to the array
    log_array.entries[log_array.size++] = entry;

    // Release the mutex lock
    pthread_mutex_unlock(&log_array_mutex);
}

