// Struct to store information about a hash function or cipher
typedef struct {
    const char* name;
    void (*func)(void);
    void* params;
} HashCipherInfo;

// Function to check the availability of a hash function or cipher
int is_available(const char* name) {
    // Check if the hash function or cipher is available based on the current system configuration and library availability
    return 1;
}

// Function to allocate memory for a list of pointers to structs
HashCipherInfo** alloc_list(int size) {
    HashCipherInfo** list = malloc(size * sizeof(HashCipherInfo*));
    if (!list) {
        // Handle memory allocation failure gracefully
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        list[i] = malloc(sizeof(HashCipherInfo));
        if (!list[i]) {
            // Handle memory allocation failure gracefully
            free(list);
            return NULL;
        }
    }
    return list;
}

// Function to populate a list of pointers to structs with information about available hash functions and ciphers
HashCipherInfo** get_available_hash_ciphers() {
    // Check if the cache is valid
    if (cache_valid) {
        return cache;
    }

    // Allocate memory for the list of pointers to structs
    HashCipherInfo** list = alloc_list(10);
    if (!list) {
        // Handle memory allocation failure gracefully
        return NULL;
    }

    // Populate the list with information about available hash functions and ciphers
    int i = 0;
    for (const EVP_MD* md : EVP_mds()) {
        if (is_available(EVP_MD_name(md))) {
            HashCipherInfo* info = malloc(sizeof(HashCipherInfo));
            if (!info) {
                // Handle memory allocation failure gracefully
                free(list);
                return NULL;
            }
            info->name = EVP_MD_name(md);
            info->func = EVP_DigestInit;
            info->params = md;
            list[i++] = info;
        }
    }
    for (const EVP_CIPHER* cipher : EVP_ciphers()) {
        if (is_available(EVP_CIPHER_name(cipher))) {
            HashCipherInfo* info = malloc(sizeof(HashCipherInfo));
            if (!info) {
                // Handle memory allocation failure gracefully
                free(list);
                return NULL;
            }
            info->name = EVP_CIPHER_name(cipher);
            info->func = EVP_EncryptInit;
            info->params = cipher;
            list[i++] = info;
        }
    }

    // Cache the results for future use
    cache = list;
    cache_valid = 1;

    return list;
}

// Function to free memory allocated by get_available_hash_ciphers()
void free_list(HashCipherInfo** list) {
    if (!list) {
        return;
    }
    for (int i = 0; i < 10; i++) {
        if (list[i]) {
            free(list[i]);
        }
    }
    free(list);
}
