#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct to hold information about each logging framework
typedef struct {
    const char* name;
    void (*configure)(void);
    void* params;
} LoggingFramework;

// Define an array of available logging frameworks
LoggingFramework frameworks[] = {
    {"syslog", syslog_configure, NULL},
    {"file", file_configure, NULL},
    {"console", console_configure, NULL},
};

// Define a cache to store the results of availability checks
static int* cached_availability;

// Function to check if a logging framework is available
int is_available(const char* name) {
    // Check if the framework is already in the cache
    if (cached_availability[name]) {
        return 1;
    }

    // Check if the framework is available on the system
    for (int i = 0; i < sizeof(frameworks) / sizeof(frameworks[0]); i++) {
        if (!strcmp(name, frameworks[i].name)) {
            cached_availability[name] = 1;
            return 1;
        }
    }

    // Log an error message if the framework is not available
    printf("Logging framework %s is not available\n", name);
    return 0;
}

// Function to initialize a logging framework
void* init_logging(const char* name) {
    // Check if the framework is available
    if (!is_available(name)) {
        return NULL;
    }

    // Initialize the framework and store the result in the cache
    void* params = frameworks[name].configure();
    cached_availability[name] = 1;
    return params;
}

// Function to deinitialize a logging framework
void deinit_logging(const char* name) {
    // Check if the framework is available
    if (!is_available(name)) {
        return;
    }

    // Deinitialize the framework and remove it from the cache
    frameworks[name].deconfigure();
    cached_availability[name] = 0;
}

// Function to get a list of available logging frameworks
LoggingFramework* get_available_frameworks() {
    // Initialize the cache if necessary
    if (!cached_availability) {
        cached_availability = calloc(sizeof(int), sizeof(frameworks) / sizeof(frameworks[0]));
    }

    // Iterate over the frameworks and check their availability
    for (int i = 0; i < sizeof(frameworks) / sizeof(frameworks[0]); i++) {
        if (!is_available(frameworks[i].name)) {
            continue;
        }

        // Add the framework to the list of available frameworks
        LoggingFramework* framework = malloc(sizeof(LoggingFramework));
        memcpy(framework, &frameworks[i], sizeof(LoggingFramework));
        return framework;
    }

    // Return an empty list if no frameworks are available
    return NULL;
}
