// Define the structure for an event
typedef struct {
    int id;
    char *name;
} event_t;

// Define the structure for a collection of events
typedef struct {
    int size;
    int capacity;
    event_t **events;
} event_collection_t;

// Function to create a new event collection
event_collection_t *create_event_collection(int initial_capacity) {
    // Allocate memory for the event collection structure
    event_collection_t *collection = malloc(sizeof(event_collection_t));
    if (!collection) {
        printf("Error: Failed to allocate memory for event collection\n");
        return NULL;
    }

    // Initialize the size and capacity of the collection
    collection->size = 0;
    collection->capacity = initial_capacity;

    // Allocate memory for the events array
    collection->events = malloc(sizeof(event_t *) * initial_capacity);
    if (!collection->events) {
        printf("Error: Failed to allocate memory for events array\n");
        free(collection);
        return NULL;
    }

    // Initialize the events array with NULL pointers
    for (int i = 0; i < initial_capacity; i++) {
        collection->events[i] = NULL;
    }

    return collection;
}

// Function to add a new event to the collection
void add_event(event_collection_t *collection, int id, char *name) {
    // Check if the collection is full
    if (collection->size == collection->capacity) {
        printf("Error: Event collection is full\n");
        return;
    }

    // Allocate memory for the new event
    event_t *event = malloc(sizeof(event_t));
    if (!event) {
        printf("Error: Failed to allocate memory for new event\n");
        return;
    }

    // Initialize the event fields
    event->id = id;
    event->name = name;

    // Add the event to the collection
    collection->events[collection->size++] = event;
}

// Function to remove an event from the collection
void remove_event(event_collection_t *collection, int id) {
    // Find the index of the event in the collection
    int index = -1;
    for (int i = 0; i < collection->size; i++) {
        if (collection->events[i]->id == id) {
            index = i;
            break;
        }
    }

    // Check if the event was found in the collection
    if (index == -1) {
        printf("Error: Event not found in collection\n");
        return;
    }

    // Remove the event from the collection
    free(collection->events[index]);
    collection->events[index] = NULL;

    // Shift all events after the removed event to fill the gap
    for (int i = index + 1; i < collection->size; i++) {
        collection->events[i - 1] = collection->events[i];
        collection->events[i] = NULL;
    }

    // Decrement the size of the collection
    collection->size--;
}

// Function to print all events in the collection
void print_events(event_collection_t *collection) {
    for (int i = 0; i < collection->size; i++) {
        printf("Event %d: %s\n", collection->events[i]->id, collection->events[i]->name);
    }
}
