    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the current capacity is exceeded
    if (num_elements >= MAX_ELEMENTS) {
        // If so, resize the array and copy the existing elements to the new one
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(crc_indications, 2 * MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            // If the resize fails, release the mutex and return
            pthread_mutex_unlock(&crc_indication_mutex);
            return;
        }
        crc_indications = new_array;
    }

    // Add the new CRC indication to the array
    crc_indications[num_elements].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    crc_indications[num_elements].RNTI = RNTI;
    crc_indications[num_elements].CRCFLAG = CRCFLAG;
