    // Acquire the mutex for thread-safe access to the array
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the index is valid
    if (index >= num_elements) {
        // If not, release the mutex and return NULL
        pthread_mutex_unlock(&crc_indication_mutex);
        return NULL;
    }

    // Return a pointer to the CRC indication at the specified index
    NFAPI_CRC_INDICATION_PDU_T *crc_indication = &crc_indications[index];

    // Release the mutex and return
