pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Define the function to initialize and populate the linked list of LTE_PHY_RX_FRAME_INFO structures
void init_and_populate_linked_list(LTE_PHY_RX_FRAME_INFO **head) {
    // Initialize the head pointer to NULL
    *head = NULL;

    // Read the file in chunks and update the hash using the hashlib.md5() object
    FILE *file = fopen("file.txt", "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

