    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        // Update the hash using the hashlib.md5() object
        MD5_CTX *ctx = hashlib.md5();
        hashlib.update(ctx, buffer, bytes_read);
    }

    // Get the hexdigest of the hash and convert it to a string
    char *hexdigest = hashlib.hexdigest(ctx);

    // Allocate memory for the UE IDs cache
    UE_IDS *ue_ids_cache = malloc(sizeof(UE_IDS));
    if (ue_ids_cache == NULL) {
        perror("Error allocating memory for UE IDs cache");
        return;
    }

