        record->srb = allocate_phy_rx_srb(record->ue_context);
        record->drb = allocate_phy_rx_drb(record->ue_context);

        // Add the record to the linked list
        if (*head == NULL) {
            *head = tail = record;
        } else {
            tail->next = record;
            tail = record;
        }
    }

    // Free the memory for the UE IDs cache
    free(ue_ids_cache);
}

// Define the function to handle allocation failures gracefully
