        new_audio_buffers[*audio_buffers].sample_rate = atof(buffer);
        new_audio_buffers[*audio_buffers].channel_count = atoi(buffer);
        new_audio_buffers[*audio_buffers].audio_samples = strdup(buffer);
        *audio_buffers += 1;
    }
    fclose(file);
}

// Function to initialize event processing pipeline
void initialize_event_processing_pipeline(int *event_buffer_size, struct event **event_buffers) {
    // Allocate memory for event buffers
    *event_buffers = (struct event *)malloc(sizeof(struct event) * 5000);
