};

// Define the function to dynamically allocate and initialize interconnected data structures for a high-performance log processing pipeline
void init_log_data(struct log_data* data) {
    // Allocate memory for the array of log records
    data->records = (struct log_record**)malloc(sizeof(struct log_record*) * data->capacity);
    if (!data->records) {
        fprintf(stderr, "Error: failed to allocate memory for log records\n");
        exit(1);
    }

    // Initialize the array of log records
    for (int i = 0; i < data->capacity; i++) {
        data->records[i] = (struct log_record*)malloc(sizeof(struct log_record));
        if (!data->records[i]) {
            fprintf(stderr, "Error: failed to allocate memory for log record %d\n", i);
            exit(1);
        }
    }

    // Initialize the number of records and capacity
    data->num_records = 0;
    data->capacity = data->max_num_logs;
}

// Define the function to dynamically allocate and initialize interconnected data structures for a high-performance log processing pipeline
void free_log_data(struct log_data* data) {
    // Free the array of log records
    for (int i = 0; i < data->capacity; i++) {
        if (data->records[i]) {
            free(data->records[i]);
        }
    }
    free(data->records);
}

// Define the function to avoid duplicate log entries during a single execution
