struct OffsetKey {
    long offset;
    int key;
};

// Define the structure for storing record values
struct Record {
    int value;
};

// Define the function to manage a dynamic resource pool
void* resourcePool(int capacity, void* data) {
    // Initialize the resource pool with the specified capacity
    vector<OffsetKey> offsetKeys = vector<OffsetKey>(capacity);
    vector<Record> records = vector<Record>(capacity);

    // Define the mutex and condition variable for synchronizing access to the resource pool
    mutex mtx;
    condition_variable cv;

    // Define the function to allocate memory for the offset and key values
    void* allocateOffsetKey(int size) {
        // Allocate memory for the offset and key values
        OffsetKey* offsetKey = new OffsetKey[size];

        // Initialize the offset and key values
        for (int i = 0; i < size; ++i) {
            offsetKey[i].offset = 0;
            offsetKey[i].key = 0;
        }

        return offsetKey;
    }

    // Define the function to allocate memory for the record values
    void* allocateRecord(int size) {
        // Allocate memory for the record values
        Record* record = new Record[size];

        // Initialize the record values
        for (int i = 0; i < size; ++i) {
            record[i].value = 0;
        }

        return record;
    }

    // Define the function to deallocate memory for the offset and key values
    void deallocateOffsetKey(void* data) {
        // Deallocate the memory for the offset and key values
        delete[] (OffsetKey*)data;
    }

    // Define the function to deallocate memory for the record values
    void deallocateRecord(void* data) {
        // Deallocate the memory for the record values
        delete[] (Record*)data;
    }

    // Define the function to resize the resource pool
    void resize(int newCapacity) {
        // Resize the offset and key arrays
        vector<OffsetKey> newOffsetKeys = vector<OffsetKey>(newCapacity);
        vector<Record> newRecords = vector<Record>(newCapacity);

        // Copy the old data to the new arrays
        for (int i = 0; i < capacity; ++i) {
            newOffsetKeys[i].offset = offsetKeys[i].offset;
            newOffsetKeys[i].key = offsetKeys[i].key;
            newRecords[i].value = records[i].value;
        }

        // Update the capacity and data arrays
        capacity = newCapacity;
        offsetKeys = newOffsetKeys;
        records = newRecords;
    }

    // Define the function to add a resource to the pool
    void addResource(int key, int value) {
        // Lock the mutex
        unique_lock<mutex> lock(mtx);

        // Check if the resource pool is full
        if (capacity == offsetKeys.size()) {
            // Resize the resource pool if it is full
            resize(2 * capacity);
        }

        // Add the resource to the pool
        offsetKeys[offset].key = key;
        records[offset].value = value;

        // Increment the offset and notify any waiting threads
        ++offset;
        cv.notify_all();
    }

    // Define the function to get a resource from the pool
    void* getResource(int key) {
        // Lock the mutex
        unique_lock<mutex> lock(mtx);

        // Check if the resource is in the pool
        for (int i = 0; i < offset; ++i) {
            if (offsetKeys[i].key == key) {
                return &records[i];
            }
        }

        // Wait for a resource to become available
        cv.wait(lock);

        // Check if the resource is in the pool
        for (int i = 0; i < offset; ++i) {
            if (offsetKeys[i].key == key) {
                return &records[i];
            }
        }

        // Return nullptr if no resource is found
        return nullptr;
    }

    // Define the function to remove a resource from the pool
    void removeResource(int key) {
        // Lock the mutex
        unique_lock<mutex> lock(mtx);

        // Check if the resource is in the pool
        for (int i = 0; i < offset; ++i) {
            if (offsetKeys[i].key == key) {
                // Remove the resource from the pool
                --offset;
                swap(offsetKeys[i], offsetKeys[offset]);
                swap(records[i], records[offset]);

                // Notify any waiting threads
                cv.notify_all();

                return;
            }
        }
    }
}

// Define the function to calculate the MD5 hash of a file
void calculateMD5Hash(ifstream& file, string& md5) {
    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Read the file in chunks and update the MD5 hash
    const int BUFFER_SIZE = 1024 * 1024;
    char buffer[BUFFER_SIZE];
    while (file.read(buffer, BUFFER_SIZE)) {
        MD5_Update(&ctx, buffer, file.gcount());
    }

    // Finalize the MD5 hash and return it as a string
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &ctx);
    md5 = toHexString(digest, MD5_DIGEST_LENGTH);
}

