ModemLogEntry* ModemLogManager_get_entry(ModemLogManager* log_manager, time_t timestamp) {
    // Check if the log manager has any entries
    if (log_manager->num_entries == 0) {
        return NULL;
    }

    // Find the entry with the specified timestamp in the log manager's internal data structures
    for (int i = 0; i < log_manager->num_entries; i++) {
        if (log_manager->entries[i].timestamp == timestamp) {
            return &(log_manager->entries[i]);
        }
    }

    // Return NULL if the entry is not found
    return NULL;
}

