void ModemLogManager_clear_entries(ModemLogManager* log_manager) {
    // Clear all entries in the log manager's internal data structures
    log_manager->num_entries = 0;
}

// Define the function to export the log manager's internal data structures to a file in JSON format
void ModemLogManager_export_json(ModemLogManager* log_manager, const char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        return;
    }

    // Write the JSON header to the output file
    fprintf(fp, "{\n");

    // Iterate over all entries in the log manager's internal data structures and write them to the output file
    for (int i = 0; i < log_manager->num_entries; i++) {
        ModemLogEntry* entry = &(log_manager->entries[i]);
        fprintf(fp, "\"timestamp\": %ld,\n", entry->timestamp);
        fprintf(fp, "\"level\": %d,\n", entry->level);
        fprintf(fp, "\"message\": \"%s\"\n", entry->message);
    }

    // Write the JSON footer to the output file
    fprintf(fp, "}\n");

    // Close the output file
    fclose(fp);
}

// Define the function to export the log manager's internal data structures to a file in CSV format
void ModemLogManager_export_csv(ModemLogManager* log_manager, const char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        return;
    }

    // Write the CSV header to the output file
    fprintf(fp, "timestamp,level,message\n");

    // Iterate over all entries in the log manager's internal data structures and write them to the output file
    for (int i = 0; i < log_manager->num_entries; i++) {
        ModemLogEntry* entry = &(log_manager->entries[i]);
        fprintf(fp, "%ld,%d,\"%s\"\n", entry->timestamp, entry->level, entry->message);
    }

    // Close the output file
    fclose(fp);
}

// Define the function to generate a unique ID for each log entry
int generate_unique_id() {
    // Generate a random floating-point value within the specified range
    float rand_value = (float)RAND_MAX * (float)rand() / (float)RAND_MAX;

    // Convert the random floating-point value to an integer
    int id = (int)(rand_value * 1000);

    return id;
}
