int read_file(char *filename, void **buffer) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return -1;
    }

    *buffer = malloc(st.st_size);
    if (*buffer == NULL) {
        perror("malloc");
        close(fd);
        return -1;
    }

    ssize_t bytes_read = read(fd, *buffer, st.st_size);
    if (bytes_read == -1) {
        perror("read");
        free(*buffer);
        close(fd);
        return -1;
    }

    close(fd);
    return bytes_read;
}

