            (*output_buffer)[*output_size] = transformed_char;
            *output_size += 1;
        } else {
            // Add the current character to the output buffer as is
            *output_buffer = realloc(*output_buffer, (*output_size) + 1);
            if (*output_buffer == NULL) {
