        if (token == NULL) {
            continue;
        }

        // Check if token is a cryptographic function or block cipher
        if (strcmp(token, "cryptographic_function") == 0) {
            // Load cryptographic function implementation and parameters from configuration file
            char* impl = strtok(NULL, " ");
