                token = strtok(NULL, " ");
                if (token == NULL) {
                    break;
                }
                params[i] = atoi(token);
            }

            // Add cryptographic function to list of available functions
            struct crypto_function* func = malloc(sizeof(struct crypto_function));
            if (func == NULL) {
                printf("Error: unable to allocate memory for cryptographic function\n");
                return;
            }
            func->name = impl;
            func->params = params;
            func->next = available_functions;
            available_functions = func;
        } else if (strcmp(token, "block_cipher") == 0) {
            // Load block cipher implementation and parameters from configuration file
            char* impl = strtok(NULL, " ");
            if (impl == NULL) {
                continue;
