            if (cipher == NULL) {
                printf("Error: unable to allocate memory for block cipher\n");
                return;
            }
            cipher->name = impl;
            cipher->params = params;
            cipher->next = available_block_ciphers;
            available_block_ciphers = cipher;
        }
    }

    // Close configuration file
    fclose(fp);
}

