#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <pthread.h>
#include <unistd.h>

// Define a structure to hold the parsing rules and configuration for each file
typedef struct {
    char *file_name;
    json_object *rules;
} file_config_t;

// Define a structure to hold the parsing results for each file
typedef struct {
    char *file_name;
    char *output;
} file_result_t;

// Define a function to parse a single binary file based on the given rules
void* parse_file(void *args) {
    // Cast the arguments to the appropriate types
    file_config_t *config = (file_config_t*) args;
    char *file_name = config->file_name;
    json_object *rules = config->rules;

    // Open the input file and allocate memory for the output string
    FILE *input = fopen(file_name, "rb");
    if (input == NULL) {
        printf("Error opening input file %s\n", file_name);
        return NULL;
    }
    char *output = malloc(1024);
    if (output == NULL) {
        printf("Error allocating memory for output string\n");
        fclose(input);
        return NULL;
    }

    // Initialize the output string to an empty string
    output[0] = '\0';

    // Parse the input file based on the given rules
    while (1) {
        // Read a chunk of data from the input file
        char *data = malloc(1024);
        if (data == NULL) {
            printf("Error allocating memory for data buffer\n");
            fclose(input);
            free(output);
            return NULL;
        }
        size_t bytes_read = fread(data, 1, 1024, input);
        if (bytes_read == 0) {
            // End of file reached
            break;
        }

        // Parse the data using the given rules
        json_object *parsed_data = json_tokener_parse(data);
        if (parsed_data == NULL) {
            printf("Error parsing input data\n");
            fclose(input);
            free(output);
            return NULL;
        }

        // Append the parsed data to the output string
        strcat(output, json_object_get_string(parsed_data));

        // Free the memory allocated for the parsed data
        json_object_put(parsed_data);
    }

    // Close the input file and return the output string
    fclose(input);
    free(data);
    return output;
}

// Define a function to process multiple binary files concurrently based on the given rules
void process_files(char *output_dir, char *config_file, int verbose, int dry_run, int max_threads) {
    // Load the configuration file and allocate memory for the parsing results
    json_object *config = json_object_from_file(config_file);
    if (config == NULL) {
        printf("Error loading configuration file %s\n", config_file);
        return;
    }
    int num_files = json_object_array_length(config);
    file_result_t *results = malloc(num_files * sizeof(file_result_t));
    if (results == NULL) {
        printf("Error allocating memory for parsing results\n");
        json_object_put(config);
        return;
    }

    // Initialize the parsing results to an empty string
    for (int i = 0; i < num_files; i++) {
        file_result_t *result = &results[i];
        result->file_name = NULL;
        result->output = malloc(1024);
        if (result->output == NULL) {
            printf("Error allocating memory for output string\n");
            json_object_put(config);
            free(results);
            return;
        }
        result->output[0] = '\0';
    }

    // Create a thread pool to process the files concurrently
    pthread_t *threads = malloc(num_files * sizeof(pthread_t));
    if (threads == NULL) {
        printf("Error allocating memory for thread pool\n");
        json_object_put(config);
        free(results);
        return;
    }

    // Initialize the threads and start processing the files
    for (int i = 0; i < num_files; i++) {
        file_config_t *config = &((file_config_t*) json_object_get_array(config))[i];
        pthread_create(&threads[i], NULL, parse_file, config);
    }

    // Wait for all threads to complete and collect the parsing results
    for (int i = 0; i < num_files; i++) {
        void *result = malloc(1024);
        if (result == NULL) {
            printf("Error allocating memory for parsing result\n");
            json_object_put(config);
            free(results);
            return;
        }
        pthread_join(threads[i], &result);
        file_result_t *file_result = (file_result_t*) result;
        results[i].file_name = file_result->file_name;
        strcat(results[i].output, file_result->output);
    }

    // Free the memory allocated for the thread pool and the parsing results
    free(threads);
    json_object_put(config);
    free(results);

    // Write the output to individual files within the specified output directory
    for (int i = 0; i < num_files; i++) {
        file_result_t *result = &results[i];
        char *file_name = result->file_name;
        char *output = result->output;
        FILE *output_file = fopen(file_name, "wb");
        if (output_file == NULL) {
            printf("Error opening output file %s\n", file_name);
            continue;
        }
        size_t bytes_written = fwrite(output, 1, strlen(output), output_file);
        if (bytes_written < strlen(output)) {
            printf("Error writing to output file %s\n", file_name);
        }
        fclose(output_file);
    }
}

