    if (argc < 5) {
        printf("Usage: %s output_dir config_file verbose dry_run max_threads\n", argv[0]);
        return 1;
    }
    char *output_dir = argv[1];
    char *config_file = argv[2];
    int verbose = atoi(argv[3]);
