    public static void addNetworkEvent(NetworkEvent event) {
        // Acquire the lock on the event cache and wait until the event log is not full
        lock.lock();
        try {
            while (eventCache.size() >= MAX_EVENT_LOG_SIZE) {
                eventLogFull.await();
            }

            // Add the event to the event cache
            eventCache.put(event.getId(), event);

            // Signal that an event has been added to the event cache
            eventAdded.signalAll();
        } catch (InterruptedException e) {
            // Ignore the exception and continue adding events
        } finally {
            lock.unlock();
        }
    }

    public static NetworkEvent getNetworkEvent(String id) {
        // Acquire the lock on the event cache and return the event with the specified ID
        lock.lock();
        try {
            return eventCache.get(id);
        } finally {
            lock.unlock();
        }
    }

    public static List<NetworkEvent> getNetworkEventsByType(String type) {
        // Acquire the lock on the event cache and return all events with the specified type
        lock.lock();
        try {
            return eventCache.values().stream()
                    .filter(event -> event.getType().equals(type))
                    .collect(Collectors.toList());
        } finally {
            lock.unlock();
        }
    }

    public static List<NetworkEvent> getNetworkEventsByTimestamp(long timestamp) {
        // Acquire the lock on the event cache and return all events with a timestamp greater than or equal to the specified value
        lock.lock();
        try {
            return eventCache.values().stream()
                    .filter(event -> event.getTimestamp() >= timestamp)
                    .collect(Collectors.toList());
        } finally {
            lock.unlock();
        }
    }

    public static void clearNetworkEvents() {
        // Acquire the lock on the event cache and clear all events
        lock.lock();
        try {
            eventCache.clear();
        } finally {
            lock.unlock();
        }
    }

