```
import java.io.File;
import java.io.IOException;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import java.util.logging.Level;
import java.util.logging.Logger;

public class NetworkEventLog {
  private static final Logger LOGGER = Logger.getLogger(NetworkEventLog.class.getName());
  private static final int CHUNK_SIZE = 1024 * 1024; // 1 MB
  private static final int MAX_EVENTS = 10000;
  private static final Map<String, FactoryFunction> FACTORY_FUNCTIONS = new HashMap<>();

  private final Lock lock = new ReentrantLock();
  private final List<NetworkEvent> events = new ArrayList<>();
  private int eventCount = 0;

  public NetworkEventLog() {
    // Initialize the factory functions registry
    FACTORY_FUNCTIONS.put("default", this::createDefaultEvent);
    FACTORY_FUNCTIONS.put("custom", this::createCustomEvent);
  }

  public void addEvent(NetworkEvent event) {
    lock.lock();
    try {
      events.add(event);
      eventCount++;
      if (events.size() > MAX_EVENTS) {
        pruneEvents();
      }
    } finally {
      lock.unlock();
    }
  }

  public void addEvent(String type, String description) {
    NetworkEvent event = createEvent(type, description);
    addEvent(event);
  }

  public List<NetworkEvent> getEvents() {
    return events;
  }

  public List<NetworkEvent> getEventsByType(String type) {
    lock.lock();
    try {
      return events.stream().filter(e -> e.getType().equals(type)).collect(Collectors.toList());
    } finally {
      lock.unlock();
    }
  }

  public List<NetworkEvent> getEventsByTimestamp(long timestamp) {
    lock.lock();
    try {
      return events.stream().filter(e -> e.getTimestamp() == timestamp).collect(Collectors.toList());
    } finally {
      lock.unlock();
    }
  }

  public void clearEvents() {
    lock.lock();
    try {
      events.clear();
      eventCount = 0;
    } finally {
      lock.unlock();
    }
  }

  private NetworkEvent createDefaultEvent(String type, String description) {
    return new DefaultNetworkEvent(type, description);
  }

  private NetworkEvent createCustomEvent(String type, String description) {
    return new CustomNetworkEvent(type, description);
  }

  private void pruneEvents() {
    // Prune events to maintain the maximum size
    List<NetworkEvent> prunedEvents = events.subList(0, events.size() - MAX_EVENTS);
    for (NetworkEvent event : prunedEvents) {
      removeEvent(event);
    }
  }

  private void removeEvent(NetworkEvent event) {
    lock.lock();
    try {
      events.remove(event);
      eventCount--;
    } finally {
      lock.unlock();
    }
  }

  public static String calculateMD5Hash(String filePath) throws IOException, NoSuchAlgorithmException {
    File file = new File(filePath);
    if (!file.exists()) {
      throw new IllegalArgumentException("File does not exist: " + filePath);
    }
    if (!file.canRead()) {
      throw new IOException("Cannot read file: " + filePath);
    }

    // Calculate the MD5 hash of the file in fixed-size chunks
    MessageDigest md = MessageDigest.getInstance("MD5");
    byte[] buffer = new byte[CHUNK_SIZE];
    int bytesRead;
    try (FileInputStream fis = new FileInputStream(file)) {
      while ((bytesRead = fis.read(buffer)) > 0) {
        md.update(buffer, 0, bytesRead);
      }
    }

    // Return the hex digest of the hash
    return String.format("%032x", new BigInteger(1, md.digest()));
  }
}
