#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

// Define the structure for the parsing rules
typedef struct {
    char *name;
    int type;
    int size;
} rule_t;

// Define the structure for the file information
typedef struct {
    char *filename;
    FILE *file;
    json_object *config;
    int thread_id;
    int chunk_size;
    int current_chunk;
    int total_chunks;
} file_info_t;

// Define the structure for the parsing context
typedef struct {
    char *output_dir;
    json_object *config;
    int verbose;
    int dry_run;
    int max_threads;
    semaphore_t *semaphore;
} parse_context_t;

// Define the function to process a single file
void* process_file(void *args) {
    file_info_t *file = (file_info_t *) args;
    json_object *config = file->config;
    char *output_dir = parse_context.output_dir;
    int verbose = parse_context.verbose;
    int dry_run = parse_context.dry_run;
    int max_threads = parse_context.max_threads;
    semaphore_t *semaphore = parse_context.semaphore;

    // Initialize the parsing context
    json_object *parsing_context = json_object_new();
    json_object_object_add(parsing_context, "file", file->filename);
    json_object_object_add(parsing_context, "thread_id", file->thread_id);
    json_object_object_add(parsing_context, "chunk_size", file->chunk_size);
    json_object_object_add(parsing_context, "current_chunk", file->current_chunk);
    json_object_object_add(parsing_context, "total_chunks", file->total_chunks);

    // Loop through the chunks of the file
    while (file->current_chunk < file->total_chunks) {
        // Read the next chunk of data from the file
        char *data = malloc(file->chunk_size);
        fread(data, 1, file->chunk_size, file->file);

        // Parse the data using the parsing rules
        json_object *parsed_data = parse_data(data, config, parsing_context);

        // Write the parsed data to a file
        char *output_filename = malloc(strlen(output_dir) + strlen(file->filename) + 10);
        sprintf(output_filename, "%s/%s.%d", output_dir, file->filename, file->thread_id);
        FILE *output_file = fopen(output_filename, "a");
        json_object_to_file(output_file, parsed_data);
        fclose(output_file);

        // Update the progress of the file and the overall processing status
        semaphore_wait(semaphore);
        file->current_chunk++;
        parse_context.total_chunks--;
        semaphore_post(semaphore);
    }

    // Clean up the parsing context
    json_object_put(parsing_context);

    return NULL;
}

// Define the function to parse a single chunk of data using the given parsing rules
json_object* parse_data(char *data, json_object *config, json_object *parsing_context) {
    // Initialize the parsed data object
    json_object *parsed_data = json_object_new();

    // Loop through the parsing rules
    int i;
    for (i = 0; i < json_object_array_length(config); i++) {
        json_object *rule = json_object_array_get_idx(config, i);
        char *name = json_object_get_string(json_object_object_get(rule, "name"));
        int type = json_object_get_int(json_object_object_get(rule, "type"));
        int size = json_object_get_int(json_object_object_get(rule, "size"));

        // Parse the data using the current rule
        switch (type) {
            case 0: // Integer
                json_object_object_add(parsed_data, name, json_object_new_int(atoi(data)));
                break;
            case 1: // Float
                json_object_object_add(parsed_data, name, json_object_new_double(atof(data)));
                break;
            case 2: // String
                json_object_object_add(parsed_data, name, json_object_new_string(data));
                break;
        }
    }

    return parsed_data;
}

// Define the function to handle errors related to file operations and JSON parsing errors
void error_handler(char *message) {
    if (parse_context.verbose) {
        printf("Error: %s\n", message);
    }
}

int main(int argc, char **argv) {
    // Check the command-line arguments
    if (argc < 5) {
        fprintf(stderr, "Usage: %s output_dir config_file [verbose] [dry_run] [max_threads]\n", argv[0]);
        return 1;
    }

    // Initialize the parsing context
    parse_context.output_dir = argv[1];
    parse_context.config = json_object_from_file(argv[2]);
    parse_context.verbose = atoi(argv[3]);
    parse_context.dry_run = atoi(argv[4]);
    parse_context.max_threads = argc > 5 ? atoi(argv[5]) : 1;
    semaphore_init(&parse_context.semaphore, 0);

    // Loop through the files specified in the configuration file
    int i;
    for (i = 0; i < json_object_array_length(parse_context.config); i++) {
        json_object *file = json_object_array_get_idx(parse_context.config, i);
        char *filename = json_object_get_string(json_object_object_get(file, "name"));
        int thread_id = json_object_get_int(json_object_object_get(file, "thread_id"));
        int chunk_size = json_object_get_int(json_object_object_get(file, "chunk_size"));
        int total_chunks = json_object_get_int(json_object_object_get(file, "total_chunks"));

        // Open the file and initialize the file information structure
        FILE *file = fopen(filename, "r");
        if (file == NULL) {
            error_handler("Failed to open file");
            continue;
        }
        file_info_t *file_info = malloc(sizeof(file_info_t));
        file_info->filename = filename;
        file_info->file = file;
        file_info->config = json_object_new();
        json_object_object_add(file_info->config, "name", json_object_new_string(filename));
        json_object_object_add(file_info->config, "thread_id", json_object_new_int(thread_id));
        json_object_object_add(file_info->config, "chunk_size", json_object_new_int(chunk_size));
        json_object_object_add(file_info->config, "current_chunk", json_object_new_int(0));
        json_object_object_add(file_info->config, "total_chunks", json_object_new_int(total_chunks));

        // Create a new thread to process the file
        pthread_t thread;
        if (pthread_create(&thread, NULL, process_file, file_info) != 0) {
            error_handler("Failed to create thread");
            continue;
        }
    }

    // Wait for all threads to finish processing the files
    while (parse_context.total_chunks > 0) {
        semaphore_wait(&parse_context.semaphore);
    }

    // Clean up the parsing context
    json_object_put(parse_context.config);
    semaphore_destroy(&parse_context.semaphore);

    return 0;
}
