#include <pthread.h>

// Log entry structure
typedef struct {
    long timestamp;
    int key;
    char* message;
} log_entry_t;

// Log structure
typedef struct {
    log_entry_t** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} log_t;

// Initialize the log structure
void init_log(log_t* log) {
    log->entries = NULL;
    log->capacity = 0;
    log->count = 0;
    pthread_mutex_init(&log->mutex, NULL);
}

// Add a new entry to the log
void add_entry(log_t* log, long timestamp, int key, char* message) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log->mutex);

    // Check if the log needs to be resized
    if (log->count == log->capacity) {
        log->capacity *= 2;
        log->entries = realloc(log->entries, log->capacity * sizeof(log_entry_t*));
    }

    // Add the new entry to the log
    log->entries[log->count] = malloc(sizeof(log_entry_t));
    log->entries[log->count]->timestamp = timestamp;
    log->entries[log->count]->key = key;
    log->entries[log->count]->message = strdup(message);
    log->count++;

    // Unlock the mutex
    pthread_mutex_unlock(&log->mutex);
}

// Retrieve an entry from the log by timestamp
log_entry_t* get_entry_by_timestamp(log_t* log, long timestamp) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log->mutex);

    // Search for the entry with the specified timestamp
    for (size_t i = 0; i < log->count; i++) {
        if (log->entries[i]->timestamp == timestamp) {
            log_entry_t* entry = log->entries[i];
            pthread_mutex_unlock(&log->mutex);
            return entry;
        }
    }

    // Unlock the mutex and return NULL if no entry was found
    pthread_mutex_unlock(&log->mutex);
    return NULL;
}

// Retrieve an entry from the log by key
log_entry_t* get_entry_by_key(log_t* log, int key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log->mutex);

    // Search for the entry with the specified key
    for (size_t i = 0; i < log->count; i++) {
        if (log->entries[i]->key == key) {
            log_entry_t* entry = log->entries[i];
            pthread_mutex_unlock(&log->mutex);
            return entry;
        }
    }

    // Unlock the mutex and return NULL if no entry was found
    pthread_mutex_unlock(&log->mutex);
    return NULL;
}

// Clear the log entries
void clear_log(log_t* log) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log->mutex);

    // Free all allocated memory for the log entries
    for (size_t i = 0; i < log->count; i++) {
        free(log->entries[i]->message);
        free(log->entries[i]);
    }

    // Reset the log structure
    log->count = 0;
    log->capacity = 1000;
    log->entries = malloc(log->capacity * sizeof(log_entry_t*));

    // Unlock the mutex
    pthread_mutex_unlock(&log->mutex);
}

// Compact the log structure to reduce memory fragmentation
void compact_log(log_t* log) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log->mutex);

    // Reallocate the log entries array to a smaller size if possible
    if (log->count < log->capacity / 2) {
        log->capacity = log->count;
        log->entries = realloc(log->entries, log->capacity * sizeof(log_entry_t*));
    }

    // Unlock the mutex
    pthread_mutex_unlock(&log->mutex);
}

// Export the log entries to a file in a standardized format
void export_log(log_t* log, char* filename) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&log->mutex);

    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Write each log entry to the output file
    for (size_t i = 0; i < log->count; i++) {
        fprintf(fp, "%ld %d %s\n", log->entries[i]->timestamp, log->entries[i]->key, log->entries[i]->message);
    }

    // Close the output file
    fclose(fp);

    // Unlock the mutex
    pthread_mutex_unlock(&log->mutex);
}
