#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the parsing rules
const char* rules = "1234567890";

// Define the maximum size of the record array
#define MAX_RECORD_ARRAY_SIZE 10000

// Define the maximum size of the integer array
#define MAX_INTEGER_ARRAY_SIZE 100000

// Define the chunk size for reading input data
#define CHUNK_SIZE 4096

// Define the mutex for serializing access to shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to read and parse the input file
void readInputFile(const char* inputFileName, const char* outputFileName, const char* rules) {
    // Open the input file for reading
    FILE* inputFile = fopen(inputFileName, "r");
    if (inputFile == NULL) {
        printf("Error: unable to open input file %s\n", inputFileName);
        return;
    }

    // Open the output file for writing
    FILE* outputFile = fopen(outputFileName, "w");
    if (outputFile == NULL) {
        printf("Error: unable to open output file %s\n", outputFileName);
        fclose(inputFile);
        return;
    }

    // Allocate memory for the long offset array
    long* offsets = malloc(sizeof(long) * MAX_RECORD_ARRAY_SIZE);
    if (offsets == NULL) {
        printf("Error: unable to allocate memory for long offset array\n");
        fclose(inputFile);
        fclose(outputFile);
        return;
    }

    // Allocate memory for the integer key array
    int* keys = malloc(sizeof(int) * MAX_INTEGER_ARRAY_SIZE);
    if (keys == NULL) {
        printf("Error: unable to allocate memory for integer key array\n");
        free(offsets);
        fclose(inputFile);
        fclose(outputFile);
        return;
    }

    // Allocate memory for the record array
    Record* records = malloc(sizeof(Record) * MAX_RECORD_ARRAY_SIZE);
    if (records == NULL) {
        printf("Error: unable to allocate memory for record array\n");
        free(offsets);
        free(keys);
        fclose(inputFile);
        fclose(outputFile);
        return;
    }

    // Initialize the offset and key arrays
    long offset = 0;
    int key = 0;
    for (int i = 0; i < MAX_RECORD_ARRAY_SIZE; i++) {
        offsets[i] = offset;
        keys[i] = key++;
    }

    // Initialize the record array with random values
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORD_ARRAY_SIZE; i++) {
        records[i].value = rand() % 100000;
    }

    // Read the input file in chunks and parse it according to the rules
    char* buffer = malloc(CHUNK_SIZE);
    while (fgets(buffer, CHUNK_SIZE, inputFile) != NULL) {
        // Parse the input data using the provided rules
        for (int i = 0; i < strlen(buffer); i++) {
            if (strchr(rules, buffer[i]) != NULL) {
                // Update the offset and key arrays
                offsets[offset] = i;
                keys[key] = buffer[i];
                offset++;
                key++;
            }
        }
    }

    // Print the largest integer from the input data
    int largestInteger = 0;
    for (int i = 0; i < MAX_INTEGER_ARRAY_SIZE; i++) {
        if (keys[i] > largestInteger) {
            largestInteger = keys[i];
        }
    }
    printf("Largest integer: %d\n", largestInteger);

    // Print the sum of all integers read from standard input
    int sum = 0;
    for (int i = 0; i < MAX_INTEGER_ARRAY_SIZE; i++) {
        sum += keys[i];
    }
    printf("Sum: %d\n", sum);

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);
    free(records);
    fclose(inputFile);
    fclose(outputFile);
}

// Function to log detailed information about the operation
void logOperation(const char* inputFileName, const char* outputFileName) {
    // Open the operation log file for writing
    FILE* logFile = fopen("operation_log.txt", "w");
    if (logFile == NULL) {
        printf("Error: unable to open operation log file\n");
        return;
    }

    // Log the start time of the operation
    time_t startTime = time(NULL);
    fprintf(logFile, "Start time: %s", ctime(&startTime));

    // Log the input and output files used in the operation
    fprintf(logFile, "Input file: %s\nOutput file: %s\n", inputFileName, outputFileName);

    // Log the largest and smallest integers processed
    int largestInteger = 0;
    for (int i = 0; i < MAX_INTEGER_ARRAY_SIZE; i++) {
        if (keys[i] > largestInteger) {
            largestInteger = keys[i];
        }
    }
    fprintf(logFile, "Largest integer: %d\n", largestInteger);

    // Log the sum of all integers read from standard input
    int sum = 0;
    for (int i = 0; i < MAX_INTEGER_ARRAY_SIZE; i++) {
        sum += keys[i];
    }
    fprintf(logFile, "Sum: %d\n", sum);

    // Log the end time of the operation
    time_t endTime = time(NULL);
    fprintf(logFile, "End time: %s", ctime(&endTime));

    // Close the log file
    fclose(logFile);
}

// Main function to execute the program
int main(int argc, char* argv[]) {
    if (argc != 4) {
        printf("Usage: %s <input_file> <output_file> <rules>\n", argv[0]);
        return 1;
    }

    // Acquire the mutex to serialize access to shared resources
    pthread_mutex_lock(&mutex);

    // Read and parse the input file
    readInputFile(argv[1], argv[2], argv[3]);

    // Log detailed information about the operation
    logOperation(argv[1], argv[2]);

    // Release the mutex to allow other threads to access shared resources
    pthread_mutex_unlock(&mutex);

    return 0;
}
