    int key = 0;
    for (int i = 0; i < 10000; i++) {
        offsets[i] = offset;
        keys[i] = key;
        record_t record = {key};
        records[i] = record;
        key++;
        offset += sizeof(record);
    }

    // Read the input file and parse it according to the rules
