        // Check if the value is within the specified range
        if (value < 0 || value > 100000) {
            printf("Error: invalid integer value\n");
            continue;
        }

        // Update the offset and key arrays
        offsets[key] = offset;
        keys[key] = value;
        record_t record = {value};
        records[key] = record;
        key++;
        offset += sizeof(record);
