// Define the function to monitor and report system resource utilization
void monitor_resources() {
    // Get the current time in milliseconds
    long current_time = (long)time(NULL) * 1000;

    // Calculate the CPU usage percentage
    double cpu_usage = (double)sysconf(_SC_NPROCESSORS_ONLN) / 100.0;

