    printf("Current time: %ld\n", current_time);
    printf("CPU usage: %.2f%%\n", cpu_usage);
    printf("Available memory: %ld bytes\n", available_memory);
}

// Define the function to serialize access to shared resources
void serialize(int* array, int size) {
    // Use a mutex to synchronize access to the shared resource
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Perform the operation on the shared resource
    for (int i = 0; i < size; i++) {
        array[i]++;
    }

    // Release the mutex to allow other threads to access the shared resource
    pthread_mutex_unlock(&mutex);
}

// Define the function to log detailed information about the operation
void log_operation(char* input_file, char* output_file, char* rules, int async) {
    // Open the log file for writing
    FILE* log = fopen("operation_log.txt", "w");
    if (log == NULL) {
        printf("Error opening log file: %s\n", strerror(errno));
        return;
    }

    // Write the start time of the operation to the log file
    long start_time = (long)time(NULL) * 1000;
    fprintf(log, "Start time: %ld\n", start_time);

    // Read and parse the input file
    read_and_parse(input_file, output_file, rules, async);

    // Write the end time of the operation to the log file
    long end_time = (long)time(NULL) * 1000;
    fprintf(log, "End time: %ld\n", end_time);

    // Close the log file
    fclose(log);
}
