// Function to apply grayscale filter to an image
void apply_grayscale(unsigned char* data, int width, int height, int channels) {
    // Convert RGB to grayscale using the luminance formula
    for (int i = 0; i < width * height * channels; i += channels) {
        float lum = 0.299f * data[i] + 0.587f * data[i + 1] + 0.114f * data[i + 2];
        data[i] = data[i + 1] = data[i + 2] = (unsigned char)lum;
    }
}

// Function to apply blur filter to an image
void apply_blur(unsigned char* data, int width, int height, int channels, float radius) {
    // Apply a Gaussian blur with the specified radius
    for (int i = 0; i < width * height * channels; i += channels) {
        float sum_r = 0.0f, sum_g = 0.0f, sum_b = 0.0f;
        for (int j = -radius; j <= radius; j++) {
            int x = i % width + j;
            if (x < 0) x += width;
            else if (x >= width * height * channels) x -= width * height * channels;
            sum_r += data[x];
            sum_g += data[x + 1];
            sum_b += data[x + 2];
        }
        data[i] = (unsigned char)(sum_r / (radius * 2 + 1));
        data[i + 1] = (unsigned char)(sum_g / (radius * 2 + 1));
        data[i + 2] = (unsigned char)(sum_b / (radius * 2 + 1));
    }
}

// Function to apply sharpen filter to an image
void apply_sharpen(unsigned char* data, int width, int height, int channels, float amount) {
    // Apply a sharpening effect with the specified amount
    for (int i = 0; i < width * height * channels; i += channels) {
        float sum_r = 0.0f, sum_g = 0.0f, sum_b = 0.0f;
        for (int j = -1; j <= 1; j++) {
            int x = i % width + j;
            if (x < 0) x += width;
            else if (x >= width * height * channels) x -= width * height * channels;
            sum_r += data[x];
            sum_g += data[x + 1];
            sum_b += data[x + 2];
        }
        data[i] = (unsigned char)(sum_r - amount);
        data[i + 1] = (unsigned char)(sum_g - amount);
        data[i + 2] = (unsigned char)(sum_b - amount);
    }
}

