import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ResourceUsageLog {
    private static final Logger LOGGER = Logger.getLogger(ResourceUsageLog.class.getName());

    // Define the maximum size of the log
    private static final int MAX_LOG_SIZE = 1000;

    // Define the LFU (Least Frequently Used) strategy for pruning logs
    private static final LFUStrategy lfuStrategy = new LFUStrategy();

    // Define a registry of factory functions, keyed by ID
    private static Map<String, Function<JSONObject, ResourceUsageLog>> factoryRegistry = new HashMap<>();

    // Define the transaction ID
    private String transactionId;

    // Define the timestamp
    private long timestamp;

    // Define the resource type
    private String resourceType;

    // Define the consumption amount
    private double consumptionAmount;

    // Define the detailed usage context
    private JSONObject usageContext;

    public ResourceUsageLog(String transactionId, long timestamp, String resourceType, double consumptionAmount, JSONObject usageContext) {
        this.transactionId = transactionId;
        this.timestamp = timestamp;
        this.resourceType = resourceType;
        this.consumptionAmount = consumptionAmount;
        this.usageContext = usageContext;
    }

    public static void addLog(ResourceUsageLog log) {
        // Add the log to the log list
        synchronized (lfuStrategy) {
            lfuStrategy.add(log);
        }
    }

    public static List<ResourceUsageLog> getLogsByTransactionId(String transactionId) {
        // Get the logs by transaction ID
        synchronized (lfuStrategy) {
            return lfuStrategy.getByTransactionId(transactionId);
        }
    }

    public static List<ResourceUsageLog> getLogsByResourceType(String resourceType) {
        // Get the logs by resource type
        synchronized (lfuStrategy) {
            return lfuStrategy.getByResourceType(resourceType);
        }
    }

    public static void clearLogs() {
        // Clear all logs
        synchronized (lfuStrategy) {
            lfuStrategy.clear();
        }
    }

    public static JSONObject toJSON(ResourceUsageLog log) {
        // Convert the log to a JSON object
        JSONObject json = new JSONObject();
        json.put("transactionId", log.getTransactionId());
        json.put("timestamp", log.getTimestamp());
        json.put("resourceType", log.getResourceType());
        json.put("consumptionAmount", log.getConsumptionAmount());
        json.put("usageContext", log.getUsageContext());
        return json;
    }

    public static ResourceUsageLog fromJSON(JSONObject json) {
        // Create a new instance of the class from a JSON object
        String transactionId = (String) json.get("transactionId");
        long timestamp = (long) json.get("timestamp");
        String resourceType = (String) json.get("resourceType");
        double consumptionAmount = (double) json.get("consumptionAmount");
        JSONObject usageContext = (JSONObject) json.get("usageContext");
        return new ResourceUsageLog(transactionId, timestamp, resourceType, consumptionAmount, usageContext);
    }

    public static void addFactoryFunction(String id, Function<JSONObject, ResourceUsageLog> factoryFunction) {
        // Add a factory function to the registry
        synchronized (factoryRegistry) {
            factoryRegistry.put(id, factoryFunction);
        }
    }

    public static ResourceUsageLog createInstanceFromFactoryFunction(String id, JSONObject json) {
        // Create a new instance of the class using a factory function from the registry
        synchronized (factoryRegistry) {
            Function<JSONObject, ResourceUsageLog> factoryFunction = factoryRegistry.get(id);
            if (factoryFunction != null) {
                return factoryFunction.apply(json);
            } else {
                throw new IllegalArgumentException("No factory function found for ID: " + id);
            }
        }
    }
}
