// Define the structure for a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1024

// Define the hash table for fast lookups by timestamp
typedef struct {
    uint32_t capacity;
    uint32_t size;
    ModemLogEntry* entries[MAX_LOG_SIZE];
} LogHashTable;

// Initialize the log hash table
void init_log_hash_table(LogHashTable* table) {
    table->capacity = MAX_LOG_SIZE;
    table->size = 0;
    for (int i = 0; i < MAX_LOG_SIZE; i++) {
        table->entries[i] = NULL;
    }
}

// Add a new log entry to the hash table
void add_log_entry(LogHashTable* table, ModemLogEntry* entry) {
    // Check if the hash table is full
    if (table->size == table->capacity) {
        // Archive old log entries
        archive_old_log_entries(table);
    }
    // Add the new entry to the hash table
    table->entries[table->size++] = entry;
}

// Retrieve a log entry from the hash table by timestamp
ModemLogEntry* get_log_entry_by_timestamp(LogHashTable* table, time_t timestamp) {
    // Iterate through the hash table entries
    for (int i = 0; i < table->size; i++) {
        ModemLogEntry* entry = table->entries[i];
        if (entry->timestamp == timestamp) {
            return entry;
        }
    }
    // Return NULL if the entry is not found
    return NULL;
}

// Clear the entire log by setting the size to 0
void clear_log(LogHashTable* table) {
    table->size = 0;
}

// Archive old log entries when the maximum size is reached
void archive_old_log_entries(LogHashTable* table) {
    // Iterate through the hash table entries
    for (int i = 0; i < table->size - MAX_LOG_SIZE; i++) {
        ModemLogEntry* entry = table->entries[i];
        free(entry);
    }
    // Shift the remaining entries to the front of the array
    memmove(table->entries, table->entries + (table->size - MAX_LOG_SIZE), sizeof(ModemLogEntry*) * (MAX_LOG_SIZE));
    table->size = MAX_LOG_SIZE;
}

// Filter log entries by log level
void filter_log_entries_by_level(LogHashTable* table, int level) {
    // Iterate through the hash table entries
    for (int i = 0; i < table->size; i++) {
        ModemLogEntry* entry = table->entries[i];
        if (entry->level != level) {
            free(entry);
            memmove(table->entries + i, table->entries + i + 1, sizeof(ModemLogEntry*) * (table->size - i));
            table->size--;
            i--;
        }
    }
}

// Retrieve log entries within a specified date range
void get_log_entries_by_date_range(LogHashTable* table, time_t start_time, time_t end_time) {
    // Iterate through the hash table entries
    for (int i = 0; i < table->size; i++) {
        ModemLogEntry* entry = table->entries[i];
        if (entry->timestamp >= start_time && entry->timestamp <= end_time) {
            // Print the log entry
            printf("%s\n", entry->message);
        }
    }
}
