#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Custom data structure for log entries
typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
} ModemLogEntry;

// Custom memory pool for allocating ModemLogEntry structures
struct MemoryPool {
    size_t capacity;
    size_t used;
    ModemLogEntry* entries;
};

// Custom hash table for fast lookups of log entries by timestamp
struct HashTable {
    size_t size;
    size_t count;
    struct {
        time_t timestamp;
        int index;
    }* buckets;
};

// Function to add a new log entry to the dynamic array
void addLogEntry(ModemLogEntry* entry) {
    // Check if the memory pool is full and needs to be resized
    if (memory_pool.used == memory_pool.capacity) {
        resizeMemoryPool();
    }

    // Add the new log entry to the memory pool
    memory_pool.entries[memory_pool.used++] = *entry;
}

// Function to retrieve a log entry by timestamp
ModemLogEntry* getLogEntry(time_t timestamp) {
    // Check if the hash table is empty and needs to be initialized
    if (hash_table.count == 0) {
        initializeHashTable();
    }

    // Look up the log entry in the hash table by timestamp
    int index = hash_table.buckets[timestamp % hash_table.size].index;
    if (index != -1) {
        return &memory_pool.entries[index];
    } else {
        return NULL;
    }
}

// Function to clear the entire log
void clearLog() {
    // Reset the memory pool and hash table
    memory_pool.used = 0;
    hash_table.count = 0;
}

// Function to limit the number of log entries to a specified maximum size
void limitLogSize(size_t max_size) {
    // Check if the current log size is greater than the maximum size
    if (memory_pool.used > max_size) {
        // Archive old log entries by moving them to the end of the memory pool
        for (int i = 0; i < memory_pool.used - max_size; i++) {
            ModemLogEntry* entry = &memory_pool.entries[i];
            memmove(&entry, &entry + 1, sizeof(ModemLogEntry) * (max_size - i));
        }

        // Update the memory pool and hash table sizes
        memory_pool.used = max_size;
        hash_table.count = max_size;
    }
}

// Function to resize the memory pool when it is full
void resizeMemoryPool() {
    // Double the size of the memory pool
    size_t new_capacity = memory_pool.capacity * 2;

    // Allocate a new memory pool with the doubled capacity
    ModemLogEntry* new_entries = malloc(sizeof(ModemLogEntry) * new_capacity);
    if (new_entries == NULL) {
        printf("Error: Failed to allocate memory for log entries\n");
        exit(1);
    }

    // Copy the existing log entries to the new memory pool
    memcpy(new_entries, memory_pool.entries, sizeof(ModemLogEntry) * memory_pool.used);

    // Free the old memory pool and update the pointers
    free(memory_pool.entries);
    memory_pool.capacity = new_capacity;
    memory_pool.entries = new_entries;
}

// Function to initialize the hash table when it is empty
void initializeHashTable() {
    // Allocate a new hash table with a default size
    struct HashTable* new_hash_table = malloc(sizeof(struct HashTable));
    if (new_hash_table == NULL) {
        printf("Error: Failed to allocate memory for log entries\n");
        exit(1);
    }

    // Initialize the hash table with a default size and count
    new_hash_table->size = 1024;
    new_hash_table->count = 0;

    // Allocate memory for the buckets
    new_hash_table->buckets = malloc(sizeof(struct { time_t timestamp; int index; }) * new_hash_table->size);
    if (new_hash_table->buckets == NULL) {
        printf("Error: Failed to allocate memory for log entries\n");
        exit(1);
    }

    // Initialize the buckets with invalid indices
    for (int i = 0; i < new_hash_table->size; i++) {
        new_hash_table->buckets[i].index = -1;
    }

    // Free the old hash table and update the pointers
    free(hash_table);
    hash_table = new_hash_table;
}

// Function to rehash the hash table when it is full
void rehashHashTable() {
    // Double the size of the hash table
    size_t new_size = hash_table->size * 2;

    // Allocate a new hash table with the doubled size
    struct HashTable* new_hash_table = malloc(sizeof(struct HashTable));
    if (new_hash_table == NULL) {
        printf("Error: Failed to allocate memory for log entries\n");
        exit(1);
    }

    // Initialize the hash table with the doubled size and count
    new_hash_table->size = new_size;
    new_hash_table->count = 0;

    // Allocate memory for the buckets
    new_hash_table->buckets = malloc(sizeof(struct { time_t timestamp; int index; }) * new_hash_table->size);
    if (new_hash_table->buckets == NULL) {
        printf("Error: Failed to allocate memory for log entries\n");
        exit(1);
    }

    // Copy the existing hash table buckets to the new hash table
    memcpy(new_hash_table->buckets, hash_table->buckets, sizeof(struct { time_t timestamp; int index; }) * hash_table->size);

    // Free the old hash table and update the pointers
    free(hash_table);
    hash_table = new_hash_table;
}
