#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a log entry
typedef struct {
    time_t timestamp;
    int level;
    char message[256];
} ModemLogEntry;

// Define the maximum size of the log array
#define MAX_LOG_SIZE 1000

// Define the purge interval in seconds
#define PURGE_INTERVAL 300

// Define the log level filter
#define LOG_LEVEL_FILTER 2 // Critical messages only

// Define the log file path
#define LOG_FILE_PATH "log.txt"

// Define the log file format
#define LOG_FILE_FORMAT "%s %d %s\n"

// Define the log level names for printing
const char* log_level_names[] = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"};

// Define the log array
ModemLogEntry* log_array;

// Initialize the log array
void init_log_array() {
    log_array = (ModemLogEntry*)malloc(MAX_LOG_SIZE * sizeof(ModemLogEntry));
}

// Add a new log entry to the array
void add_log_entry(time_t timestamp, int level, const char* message) {
    // Check if the log array is full
    if (log_array == NULL || MAX_LOG_SIZE <= 0) {
        return;
    }

    // Get the next available index in the log array
    int index = get_next_index();

    // Set the timestamp, level, and message for the new entry
    log_array[index].timestamp = timestamp;
    log_array[index].level = level;
    strncpy(log_array[index].message, message, 256);
}

// Get the next available index in the log array
int get_next_index() {
    // Check if the log array is full
    if (log_array == NULL || MAX_LOG_SIZE <= 0) {
        return -1;
    }

    // Find the first empty slot in the log array
    for (int i = 0; i < MAX_LOG_SIZE; i++) {
        if (log_array[i].timestamp == 0) {
            return i;
        }
    }

    // If no empty slots are found, return -1
    return -1;
}

// Retrieve log entries by timestamp
void retrieve_logs(time_t start_timestamp, time_t end_timestamp) {
    // Check if the log array is empty
    if (log_array == NULL || MAX_LOG_SIZE <= 0) {
        return;
    }

    // Find the first entry with a timestamp greater than or equal to start_timestamp
    int start_index = -1;
    for (int i = 0; i < MAX_LOG_SIZE; i++) {
        if (log_array[i].timestamp >= start_timestamp) {
            start_index = i;
            break;
        }
    }

    // If no entry is found, return
    if (start_index == -1) {
        return;
    }

    // Find the first entry with a timestamp less than or equal to end_timestamp
    int end_index = -1;
    for (int i = start_index; i < MAX_LOG_SIZE; i++) {
        if (log_array[i].timestamp <= end_timestamp) {
            end_index = i;
            break;
        }
    }

    // If no entry is found, return
    if (end_index == -1) {
        return;
    }

    // Print the log entries between start_index and end_index
    for (int i = start_index; i <= end_index; i++) {
        printf(LOG_FILE_FORMAT, log_array[i].timestamp, log_array[i].level, log_array[i].message);
    }
}

// Clear the entire log array
void clear_logs() {
    // Check if the log array is empty
    if (log_array == NULL || MAX_LOG_SIZE <= 0) {
        return;
    }

    // Set all entries in the log array to zero
    for (int i = 0; i < MAX_LOG_SIZE; i++) {
        memset(&log_array[i], 0, sizeof(ModemLogEntry));
    }
}

// Purge old log entries from the log array
void purge_logs() {
    // Check if the log array is empty
    if (log_array == NULL || MAX_LOG_SIZE <= 0) {
        return;
    }

    // Get the current time
    time_t now = time(NULL);

    // Find the first entry with a timestamp older than PURGE_INTERVAL seconds ago
    int purge_index = -1;
    for (int i = 0; i < MAX_LOG_SIZE; i++) {
        if (log_array[i].timestamp != 0 && log_array[i].timestamp + PURGE_INTERVAL <= now) {
            purge_index = i;
            break;
        }
    }

    // If no entry is found, return
    if (purge_index == -1) {
        return;
    }

    // Set all entries with a timestamp older than PURGE_INTERVAL seconds ago to zero
    for (int i = purge_index; i < MAX_LOG_SIZE; i++) {
        memset(&log_array[i], 0, sizeof(ModemLogEntry));
    }
}

// Filter log entries based on the specified log level filter
void filter_logs(int log_level) {
    // Check if the log array is empty
    if (log_array == NULL || MAX_LOG_SIZE <= 0) {
        return;
    }

    // Find the first entry with a log level greater than or equal to the specified log level
    int start_index = -1;
    for (int i = 0; i < MAX_LOG_SIZE; i++) {
        if (log_array[i].level >= log_level) {
            start_index = i;
            break;
        }
    }

    // If no entry is found, return
    if (start_index == -1) {
        return;
    }

    // Print the log entries with a log level greater than or equal to the specified log level
    for (int i = start_index; i < MAX_LOG_SIZE; i++) {
        printf(LOG_FILE_FORMAT, log_array[i].timestamp, log_array[i].level, log_array[i].message);
    }
}

// Export the log entries to a file in a standardized format
void export_logs() {
    // Check if the log array is empty
    if (log_array == NULL || MAX_LOG_SIZE <= 0) {
        return;
    }

    // Open the log file for writing
    FILE* log_file = fopen(LOG_FILE_PATH, "w");
    if (log_file == NULL) {
        printf("Error: Unable to open log file\n");
        return;
    }

    // Write the log entries to the log file
    for (int i = 0; i < MAX_LOG_SIZE; i++) {
        if (log_array[i].timestamp != 0) {
            fprintf(log_file, LOG_FILE_FORMAT, log_array[i].timestamp, log_array[i].level, log_array[i].message);
        }
    }

    // Close the log file
    fclose(log_file);
}
