// Function to manage the dynamic array of FileMetadata structures
void manage_dynamic_array(struct DynamicArray *arr, size_t new_size) {
    // Check if the new size is greater than the current capacity
    if (new_size > arr->capacity) {
        // Reallocate memory for the dynamic array
        FileMetadata **new_data = realloc(arr->data, new_size * sizeof(FileMetadata));
        if (!new_data) {
            fprintf(stderr, "Error: Failed to allocate memory for the dynamic array\n");
            exit(1);
        }
        arr->capacity = new_size;
        arr->data = new_data;
    }
}

