    // Add the new log entry to the end of the array
    log_entries[log_entry_count].timestamp = timestamp;
    log_entries[log_entry_count].level = level;
    strcpy(log_entries[log_entry_count].message, message);
    log_entry_count++;
}

// Function to retrieve a log entry by timestamp
ModemLogEntry* get_log_entry(time_t timestamp) {
    // Iterate through the log entries and find the matching timestamp
    for (int i = 0; i < log_entry_count; i++) {
        if (log_entries[i].timestamp == timestamp) {
            return &log_entries[i];
        }
    }

    // Return NULL if no match is found
    return NULL;
}

// Function to clear the entire log
void clear_log() {
    // Reset the log entry count and free the memory allocated for the log entries
    log_entry_count = 0;
    free(log_entries);
}

// Function to purge old entries from the log
void purge_old_entries() {
    // Get the current time
    time_t now = time(NULL);

    // Iterate through the log entries and find the oldest entry
    int oldest_entry = -1;
    for (int i = 0; i < log_entry_count; i++) {
        if (log_entries[i].timestamp < now) {
            oldest_entry = i;
        }
    }

    // If an old entry is found, remove it from the array and free its memory
    if (oldest_entry != -1) {
        log_entry_count--;
        free(log_entries[oldest_entry].message);
        memmove(&log_entries[oldest_entry], &log_entries[oldest_entry + 1], sizeof(ModemLogEntry) * (log_entry_count - oldest_entry));
    }
}

// Function to filter log entries based on the specified log level
void filter_log_level(int level) {
    // Iterate through the log entries and remove any that do not match the specified log level
    for (int i = 0; i < log_entry_count; i++) {
        if (log_entries[i].level != level) {
            memmove(&log_entries[i], &log_entries[i + 1], sizeof(ModemLogEntry) * (log_entry_count - i));
            log_entry_count--;
            i--;
        }
    }
}

// Function to export the log entries to a file in a standardized format
void export_log_entries() {
    // Open the log file for writing
