    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open input file %s", input_filename);
        return -1;
    }

    // Create a new thread for each input file and add it to the queue
    pthread_t threads[MAX_INPUT_FILES];
    int num_threads = 0;
    while (num_threads < MAX_INPUT_FILES) {
