#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Custom data structure to store network statistics
typedef struct NetworkStats {
    uint64_t timestamp;
    char ip_address[16];
    float packet_loss;
    float latency;
    float bandwidth_utilization;
    float error_rate;
} NetworkStats;

// Dynamic array to store network statistics
typedef struct NetworkStatistics {
    NetworkStats* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NetworkStatistics;

// Initialize a new network statistics object with the given capacity
NetworkStatistics* init_network_statistics(size_t capacity) {
    NetworkStatistics* stats = malloc(sizeof(NetworkStatistics));
    if (!stats) {
        return NULL;
    }
    stats->data = calloc(capacity, sizeof(NetworkStats));
    if (!stats->data) {
        free(stats);
        return NULL;
    }
    stats->capacity = capacity;
    stats->size = 0;
    pthread_mutex_init(&stats->mutex, NULL);
    return stats;
}

// Add a new network statistics entry to the array
bool add_network_statistics(NetworkStatistics* stats, uint64_t timestamp, char* ip_address, float packet_loss, float latency, float bandwidth_utilization, float error_rate) {
    if (!stats || !ip_address) {
        return false;
    }
    pthread_mutex_lock(&stats->mutex);
    // Check if the array is full and needs to be resized
    if (stats->size == stats->capacity) {
        NetworkStats* new_data = realloc(stats->data, 2 * stats->capacity * sizeof(NetworkStats));
        if (!new_data) {
            pthread_mutex_unlock(&stats->mutex);
            return false;
        }
        stats->data = new_data;
        stats->capacity *= 2;
    }
    // Add the new entry to the array
    NetworkStats* entry = &stats->data[stats->size++];
    entry->timestamp = timestamp;
    strcpy(entry->ip_address, ip_address);
    entry->packet_loss = packet_loss;
    entry->latency = latency;
    entry->bandwidth_utilization = bandwidth_utilization;
    entry->error_rate = error_rate;
    pthread_mutex_unlock(&stats->mutex);
    return true;
}

// Retrieve a network statistics entry by timestamp
NetworkStats* get_network_statistics_by_timestamp(NetworkStatistics* stats, uint64_t timestamp) {
    if (!stats) {
        return NULL;
    }
    pthread_mutex_lock(&stats->mutex);
    for (size_t i = 0; i < stats->size; i++) {
        NetworkStats* entry = &stats->data[i];
        if (entry->timestamp == timestamp) {
            pthread_mutex_unlock(&stats->mutex);
            return entry;
        }
    }
    pthread_mutex_unlock(&stats->mutex);
    return NULL;
}

// Retrieve a network statistics entry by IP address
NetworkStats* get_network_statistics_by_ip(NetworkStatistics* stats, char* ip_address) {
    if (!stats || !ip_address) {
        return NULL;
    }
    pthread_mutex_lock(&stats->mutex);
    for (size_t i = 0; i < stats->size; i++) {
        NetworkStats* entry = &stats->data[i];
        if (!strcmp(entry->ip_address, ip_address)) {
            pthread_mutex_unlock(&stats->mutex);
            return entry;
        }
    }
    pthread_mutex_unlock(&stats->mutex);
    return NULL;
}

// Retrieve a network statistics entry by metric range
NetworkStats* get_network_statistics_by_metric(NetworkStatistics* stats, float min_packet_loss, float max_packet_loss, float min_latency, float max_latency, float min_bandwidth_utilization, float max_bandwidth_utilization) {
    if (!stats) {
        return NULL;
    }
    pthread_mutex_lock(&stats->mutex);
    for (size_t i = 0; i < stats->size; i++) {
        NetworkStats* entry = &stats->data[i];
        if (entry->packet_loss >= min_packet_loss && entry->packet_loss <= max_packet_loss &&
            entry->latency >= min_latency && entry->latency <= max_latency &&
            entry->bandwidth_utilization >= min_bandwidth_utilization && entry->bandwidth_utilization <= max_bandwidth_utilization) {
            pthread_mutex_unlock(&stats->mutex);
            return entry;
        }
    }
    pthread_mutex_unlock(&stats->mutex);
    return NULL;
}

// Clear the entire network statistics dataset
void clear_network_statistics(NetworkStatistics* stats) {
    if (!stats) {
        return;
    }
    pthread_mutex_lock(&stats->mutex);
    stats->size = 0;
    pthread_mutex_unlock(&stats->mutex);
}

// Prune the network statistics dataset to a specified maximum size, using an LRU strategy
void prune_network_statistics(NetworkStatistics* stats, size_t max_size) {
    if (!stats || stats->size <= max_size) {
        return;
    }
    pthread_mutex_lock(&stats->mutex);
    // Sort the array by timestamp in descending order
    qsort(stats->data, stats->size, sizeof(NetworkStats), compare_network_statistics_by_timestamp);
    // Remove excess entries from the end of the array
    size_t num_entries = stats->size - max_size;
    for (size_t i = 0; i < num_entries; i++) {
        NetworkStats* entry = &stats->data[i];
        free(entry);
    }
    stats->size -= num_entries;
    pthread_mutex_unlock(&stats->mutex);
}

// Compare two network statistics entries by timestamp in descending order
int compare_network_statistics_by_timestamp(const void* a, const void* b) {
    NetworkStats* entry1 = (NetworkStats*)a;
    NetworkStats* entry2 = (NetworkStats*)b;
    if (entry1->timestamp < entry2->timestamp) {
        return 1;
    } else if (entry1->timestamp > entry2->timestamp) {
        return -1;
    } else {
        return 0;
    }
}

// Free the memory allocated for a network statistics object
void free_network_statistics(NetworkStatistics* stats) {
    if (!stats) {
        return;
    }
    pthread_mutex_lock(&stats->mutex);
    for (size_t i = 0; i < stats->size; i++) {
        NetworkStats* entry = &stats->data[i];
        free(entry);
    }
    free(stats->data);
    pthread_mutex_unlock(&stats->mutex);
    pthread_mutex_destroy(&stats->mutex);
    free(stats);
}
