    while ((read = getline(&line, &len, inputFile)) != -1) {
        // Parse event data from current line
        int eventTime = atoi(strtok(line, ","));
        int eventSeverity = atoi(strtok(NULL, ","));
        if (eventTime >= startTime && eventSeverity >= severityThreshold) {
            numEvents++;
            if (eventSeverity >= 5) {
                numSevereEvents++;
            }
        }
    }

    // Generate summary report and write to output file
    fprintf(outputFile, "Number of events: %d\n", numEvents);
    fprintf(outputFile, "Number of severe events: %d\n", numSevereEvents);

    // Close input and output files
    fclose(inputFile);
    fclose(outputFile);
}
