// Define the function to manage a dynamic resource pool with an initial capacity
void resourcePool(int capacity) {
    // Initialize the vector of resources with the specified capacity
    vector<Record> resources(capacity);

    // Initialize the mutex and condition variable for synchronizing access to the resources
    mutex mtx;
    condition_variable cv;

    // Define a function to allocate a new resource
    void allocateResource() {
        unique_lock<mutex> lock(mtx);
        while (resources.size() >= capacity) {
            cv.wait(lock);
        }
        resources.push_back(Record());
        cv.notify_all();
    }

    // Define a function to deallocate a resource
    void deallocateResource(int index) {
        unique_lock<mutex> lock(mtx);
        if (index < 0 || index >= resources.size()) {
            return;
        }
        resources[index] = Record();
        cv.notify_all();
    }

    // Define a function to access a resource
    void accessResource(int index) {
        unique_lock<mutex> lock(mtx);
        if (index < 0 || index >= resources.size()) {
            return;
        }
        Record& record = resources[index];
        // Perform any necessary operations on the resource here
    }
}

// Define a function to calculate the MD5 hash of a file
void md5Hash(const string& filename) {
    ifstream infile(filename, ios::binary);
    if (!infile.is_open()) {
        cerr << "Error: unable to open file " << filename << endl;
        return;
    }
    MD5_CTX ctx;
    MD5_Init(&ctx);
    char buffer[4096];
    while (infile.read(buffer, sizeof(buffer))) {
        MD5_Update(&ctx, buffer, infile.gcount());
    }
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &ctx);
    cout << "MD5 hash of file " << filename << ": ";
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", digest[i]);
    }
    cout << endl;
}

// Define a function to process a file in chunks
void processFile(const string& filename, int chunkSize) {
    ifstream infile(filename, ios::binary);
    if (!infile.is_open()) {
        cerr << "Error: unable to open file " << filename << endl;
        return;
    }
    vector<Offset> offsets;
    while (true) {
        Offset offset = infile.tellg();
        if (!infile.good()) {
            break;
        }
        offsets.push_back(offset);
        infile.seekg(chunkSize, ios::cur);
    }
    for (int i = 0; i < offsets.size(); ++i) {
        infile.seekg(offsets[i]);
        md5Hash(filename);
    }
}

// Define a function to process multiple files in parallel
void processFiles(const vector<string>& filenames, int chunkSize) {
    for (int i = 0; i < filenames.size(); ++i) {
        thread t([=]() {
            processFile(filenames[i], chunkSize);
        });
        t.detach();
    }
}

