void init_data_structures(int num_records, int range_min, int range_max) {
    // Allocate memory for the offset array
    Offset *offsets = malloc(num_records * sizeof(Offset));
    if (offsets == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
