        keys[i].key = rand() % (range_max - range_min + 1) + range_min;
    }

    // Initialize the record array with random values within the specified range and a valid RX_UE_INFORMATION_TAG and RNTI
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
        NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (crc_indication_pdu == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for crc_indication_pdu\n");
            exit(EXIT_FAILURE);
        }
        crc_indication_pdu->RX_UE_INFORMATION_TAG = rand() % (range_max - range_min + 1) + range_min;
        crc_indication_pdu->RNTI = rand() % (range_max - range_min + 1) + range_min;
        crc_indication_pdu->CRCFLAG = rand() % (range_max - range_min + 1) + range_min;
    }
}

// Define the function to read a file, sort its lines, and extract a sequence number from the last line
int read_file(char *filename, int *sequence_number) {
    // Open the file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open file %s\n", filename);
        return -1;
    }

    // Read the lines of the file into an array
    char **lines = malloc(sizeof(char *) * 1000);
    int num_lines = 0;
    while (fgets(lines[num_lines], 100, fp) != NULL) {
        num_lines++;
    }

    // Sort the lines of the file in ascending order
    qsort(lines, num_lines, sizeof(char *), compare);

    // Extract the sequence number from the last line
    char *last_line = lines[num_lines - 1];
    int len = strlen(last_line);
    if (len > 0 && last_line[len - 1] == '\n') {
        last_line[len - 1] = '\0';
    }
    *sequence_number = atoi(last_line);

    // Close the file and free the memory allocated for the lines array
    fclose(fp);
    free(lines);

    return 0;
}

// Define a comparison function to sort the lines of the file in ascending order
int compare(const void *a, const void *b) {
    char **ia = (char **)a;
    char **ib = (char **)b;
    return strcmp(*ia, *ib);
}
