// Structure to store network statistics
typedef struct NetworkStats {
    uint64_t timestamp; // Timestamp of the statistics entry
    char ip[16]; // IP address of the device
    float packet_loss; // Packet loss percentage
    float latency; // Latency in milliseconds
    float bandwidth_utilization; // Bandwidth utilization in Mbps
    float error_rate; // Error rate in percent
} NetworkStats;

// Dynamic array to store network statistics
typedef struct NetworkStatistics {
    NetworkStats* stats; // Array of network statistics entries
    size_t capacity; // Capacity of the dynamic array
    size_t count; // Number of elements in the dynamic array
} NetworkStatistics;

// Function to add a new network statistics entry
void add_network_statistics(NetworkStatistics* stats, uint64_t timestamp, char* ip, float packet_loss, float latency, float bandwidth_utilization, float error_rate) {
    // Check if the dynamic array is full
    if (stats->count == stats->capacity) {
        // If the dynamic array is full, prune the least recently used entry
        NetworkStats* lru = &(stats->stats[0]);
        for (size_t i = 1; i < stats->count; i++) {
            if (lru->timestamp < stats->stats[i].timestamp) {
                lru = &(stats->stats[i]);
            }
        }
        // Remove the least recently used entry from the dynamic array
        memmove(&(stats->stats[0]), &(stats->stats[1]), sizeof(NetworkStats) * (stats->count - 1));
        stats->count--;
    }
    // Add the new network statistics entry to the dynamic array
    NetworkStats* new_entry = &(stats->stats[stats->count]);
    new_entry->timestamp = timestamp;
    strcpy(new_entry->ip, ip);
    new_entry->packet_loss = packet_loss;
    new_entry->latency = latency;
    new_entry->bandwidth_utilization = bandwidth_utilization;
    new_entry->error_rate = error_rate;
    stats->count++;
}

// Function to retrieve network statistics by timestamp or IP address
NetworkStats* get_network_statistics(NetworkStatistics* stats, uint64_t timestamp, char* ip) {
    // Check if the dynamic array is empty
    if (stats->count == 0) {
        return NULL;
    }
    // Find the network statistics entry with the specified timestamp or IP address
    for (size_t i = 0; i < stats->count; i++) {
        NetworkStats* entry = &(stats->stats[i]);
        if ((timestamp != 0 && entry->timestamp == timestamp) || (ip != NULL && strcmp(entry->ip, ip) == 0)) {
            return entry;
        }
    }
    // If the network statistics entry is not found, return NULL
    return NULL;
}

// Function to clear the entire dynamic array of network statistics
void clear_network_statistics(NetworkStatistics* stats) {
    // Set the count of the dynamic array to 0
    stats->count = 0;
}

// Function to filter network statistics based on specific criteria
void filter_network_statistics(NetworkStatistics* stats, float packet_loss_threshold, float latency_range[2], float bandwidth_utilization_range[2]) {
    // Check if the dynamic array is empty
    if (stats->count == 0) {
        return;
    }
    // Filter the network statistics entries based on the specified criteria
    for (size_t i = 0; i < stats->count; i++) {
        NetworkStats* entry = &(stats->stats[i]);
        if (entry->packet_loss > packet_loss_threshold || entry->latency < latency_range[0] || entry->latency > latency_range[1] || entry->bandwidth_utilization < bandwidth_utilization_range[0] || entry->bandwidth_utilization > bandwidth_utilization_range[1]) {
