    // Acquire the mutex
    pthread_mutex_lock(&log_mutex);

    // Create a new array of log entries with the same size as the original array
    ModemLogEntry* compacted_entries = (ModemLogEntry*)malloc(sizeof(ModemLogEntry) * log_size);

