struct MAC_FRAME_HEADER {
    // ...
};

struct MAC_COMMAND {
    int sequenceNumber;
    // ...
};

void initializeAndSortNICP(std::vector<int>& nicpMessageIdentifiers, int targetValue, const MAC_FRAME_HEADER& frameHeader, const MAC_COMMAND& command, unsigned long timestamp) {
    // Check if the target value is present in the vector
    auto it = std::find(nicpMessageIdentifiers.begin(), nicpMessageIdentifiers.end(), targetValue);
    if (it != nicpMessageIdentifiers.end()) {
        // Insert the command with its sequence number into the vector immediately after the first occurrence of the target value
        MAC_COMMAND newCommand = { timestamp, frameHeader };
        nicpMessageIdentifiers.insert(++it, newCommand);
    } else {
        // Append the command to the end of the vector if the target value is not present
        MAC_COMMAND newCommand = { timestamp, frameHeader };
        nicpMessageIdentifiers.push_back(newCommand);
    }

    // Sort the vector in ascending order based on the MAC_COMMAND and sequence number
    std::sort(nicpMessageIdentifiers.begin(), nicpMessageIdentifiers.end(), [](const MAC_COMMAND& lhs, const MAC_COMMAND& rhs) {
        return lhs.sequenceNumber < rhs.sequenceNumber;
    });
}
