            strcpy(keys[num_sections - 1][num_subsections - 1][num_keys - 1], argv[++i]);
        }
    }

    // Free all allocated memory once the configuration is loaded, ensuring that resources are released promptly
    for (size_t i = 0; i < num_sections; i++) {
        free(sections[i]);
        free(subsections[i]);
        for (size_t j = 0; j < num_subsections; j++) {
            free(keys[i][j]);
        }
    }
    free(sections);
    free(subsections);
