#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

// Define the data structures for the records, keys, and CRC indications
typedef struct {
    long offset;
} offset_t;

typedef struct {
    int key;
} key_t;

typedef struct {
    int value;
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
} record_t;

// Define the custom memory pool for allocating memory efficiently
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
static uint8_t memory_pool[MEMORY_POOL_SIZE];
static size_t memory_pool_index = 0;

// Define the function to manage memory allocation and initialization for records
void allocate_records(size_t num_records, int range_start, int range_end) {
    // Allocate memory for the offset array
    size_t offset_array_size = sizeof(offset_t) * num_records;
    offset_t* offsets = (offset_t*) malloc(offset_array_size);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    size_t key_array_size = sizeof(key_t) * num_records;
    key_t* keys = (key_t*) malloc(key_array_size);
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Allocate memory for the record array
    size_t record_array_size = sizeof(record_t) * num_records;
    record_t* records = (record_t*) malloc(record_array_size);
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the offset and key arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i].offset = i * sizeof(record_t);
        keys[i].key = i + range_start;
    }

    // Initialize the record array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (range_end - range_start) + range_start;
        records[i].crc_indication.RX_UE_INFORMATION_TAG = NFAPI_CRC_INDICATION_PDU_T_RX_UE_INFORMATION_TAG;
        records[i].crc_indication.RNTI = i + range_start;
        records[i].crc_indication.CRC_INDICATION_REL8_TAG = NFAPI_CRC_INDICATION_PDU_T_CRC_INDICATION_REL8_TAG;
    }

    // Free the memory pool if it is not needed anymore
    if (memory_pool_index == 0) {
        free(memory_pool);
    }
}

// Define a function to release the allocated memory for records
void release_records() {
    free(offsets);
    free(keys);
    free(records);
}
